using namespace std;

struct ChildData {
    int jump_height;
    int original_index;
    int balloons_collected;
    bool has_processed;
    vector<int> eligible_balloons;
};

struct BalloonData {
    int height;
    bool is_taken;
    int taken_by;
};

bool compareChildrenByJump(const ChildData& a, const ChildData& b) {
    if (a.jump_height != b.jump_height) {
        return a.jump_height < b.jump_height;
    }
    return a.original_index < b.original_index;
}

bool compareChildrenByOriginalIndex(const ChildData& a, const ChildData& b) {
    return a.original_index < b.original_index;
}

void validateInputRange(int value, int min_val, int max_val, const string& var_name) {
    if (value < min_val || value > max_val) {
        cerr << "Invalid input range for " << var_name << endl;
        exit(EXIT_FAILURE);
    }
}

int main() {
    int num_children, num_balloons;
    cin >> num_children >> num_balloons;

    validateInputRange(num_children, 1, 1000, "num_children");
    validateInputRange(num_balloons, 1, 1000, "num_balloons");

    vector<ChildData> children(num_children);
    unordered_set<int> unique_jumps;
    for (int i = 0; i < num_children; ++i) {
        cin >> children[i].jump_height;
        validateInputRange(children[i].jump_height, 1, 100000, "jump_height");
        if (unique_jumps.count(children[i].jump_height)) {
            cerr << "Duplicate jump heights detected" << endl;
            exit(EXIT_FAILURE);
        }
        unique_jumps.insert(children[i].jump_height);
        children[i].original_index = i;
        children[i].balloons_collected = 0;
        children[i].has_processed = false;
    }

    vector<BalloonData> balloons(num_balloons);
    for (int i = 0; i < num_balloons; ++i) {
        cin >> balloons[i].height;
        validateInputRange(balloons[i].height, 1, 100000, "balloon_height");
        balloons[i].is_taken = false;
        balloons[i].taken_by = -1;
    }

    sort(children.begin(), children.end(), compareChildrenByJump);

    int previous_max_jump = numeric_limits<int>::min();
    for (auto& child : children) {
        child.eligible_balloons.clear();
        for (int i = 0; i < num_balloons; ++i) {
            if (!balloons[i].is_taken && 
                balloons[i].height <= child.jump_height && 
                balloons[i].height > previous_max_jump) {
                child.eligible_balloons.push_back(i);
            }
        }
        previous_max_jump = max(previous_max_jump, child.jump_height);
    }

    for (auto& child : children) {
        child.balloons_collected = child.eligible_balloons.size();
        child.has_processed = true;
        for (int idx : child.eligible_balloons) {
            balloons[idx].is_taken = true;
            balloons[idx].taken_by = child.original_index;
