    sort(children.begin(), children.end(), compareChildrenByOriginalIndex);

    for (const auto& child : children) {
        if (!child.has_processed) {
            cerr << "Child not processed correctly" << endl;
            exit(EXIT_FAILURE);
        }
        cout << child.balloons_collected << endl;
    }

    return 0;
}
