#include <iostream>
#include <vector>
#include <algorithm>
#include <unordered_map>
#include <limits>
#include <stdexcept>
#include <type_traits>

using namespace std;

struct ChildData {
    int reach_height;
    int original_index;
    mutable int balloons_taken;
    bool initialized;
    ChildData() : reach_height(0), original_index(0), balloons_taken(0), initialized(false) {}
};

struct BalloonData {
    int height;
    bool taken;
    BalloonData() : height(0), taken(false) {}
};

template<typename T>
void validate_input(const T& value, const T& min_val, const T& max_val) {
    static_assert(is_integral<T>::value, "Input must be integral type");
    if (value < min_val || value > max_val) {
        throw out_of_range("Input value out of valid range");
    }
}

void process_children(vector<ChildData>& children, int n) {
    for (int i = 0; i < n; ++i) {
        children[i].original_index = i;
        children[i].initialized = true;
    }
}

void process_balloons(vector<BalloonData>& balloons, int m) {
    for (int i = 0; i < m; ++i) {
        balloons[i].taken = false;
    }
}

bool compare_children(const ChildData& a, const ChildData& b) {
    if (!a.initialized || !b.initialized) {
        throw runtime_error("Uninitialized child data detected");
    }
    return a.reach_height < b.reach_height;
}

bool compare_original_index(const ChildData& a, const ChildData& b) {
    return a.original_index < b.original_index;
}

void validate_balloon_height(int height) {
    if (height <= 0) {
        throw invalid_argument("Balloon height must be positive");
    }
}

void validate_child_height(int height) {
    if (height <= 0) {
        throw invalid_argument("Child reach height must be positive");
    }
}

void count_balloons(vector<ChildData>& children, vector<BalloonData>& balloons) {
    for (auto& child : children) {
        if (!child.initialized) continue;

        for (auto& balloon : balloons) {
            if (balloon.taken) continue;

            if (child.reach_height >= balloon.height) {
                bool higher_child_took = false;
                for (const auto& other_child : children) {
                    if (other_child.reach_height > child.reach_height && 
                        other_child.reach_height >= balloon.height) {
                        higher_child_took = true;
                        break;
                    }
                }

                if (!higher_child_took) {
                    child.balloons_taken++;
                    balloon.taken = true;
                }
            }
        }
    }
}

int main() {
    try {
        int n, m;
        cin >> n >> m;

        validate_input(n, 1, 1000);
        validate_input(m, 1, 1000);

        vector<ChildData> children(n);
        vector<BalloonData> balloons(m);

        for (int i = 0; i < n; ++i) {
            cin >> children[i].reach_height;
            validate_child_height(children[i].reach_height);
        }

        for (int i = 0; i < m; ++i) {
            cin >> balloons[i].height;
            validate_balloon_height(balloons[i].height);
        }

        process_children(children, n);
        process_balloons(balloons, m);

        sort(children.begin(), children.end(), compare_children);

        count_balloons(children, balloons);

        sort(children.begin(), children.end(), compare_original_index);

        for (const auto& child : children) {
            cout << child.balloons_taken << endl;
        }
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

