#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>
#include <algorithm>
using namespace std;

const string TRIPLE_S_MARKER = "sss";
const string TRIPLE_K_MARKER = "kkk";
const char DOT_REPLACEMENT = '.';
const char SPACE_REPLACEMENT = ' ';
const int SHIFT_VALUE = 3;
const char NUMERIC_WRAP_START = '0';
const char NUMERIC_WRAP_END = '9';
const char ALPHA_WRAP_START = 'a';
const char ALPHA_WRAP_END = 'z';
const char NUMERIC_SHIFT_BASE = 'x';
const char ALPHA_SHIFT_BASE = '7';

struct CharacterMapping {
    char original;
    char encrypted;
};

vector<CharacterMapping> initializeNumericMappings() {
    vector<CharacterMapping> mappings;
    for (char c = NUMERIC_WRAP_START; c <= NUMERIC_WRAP_END; ++c) {
        CharacterMapping mapping;
        mapping.original = c;
        mapping.encrypted = (c - NUMERIC_WRAP_START + SHIFT_VALUE) % (NUMERIC_WRAP_END - NUMERIC_WRAP_START + 1) + NUMERIC_WRAP_START;
        mappings.push_back(mapping);
    }
    return mappings;
}

vector<CharacterMapping> initializeAlphaMappings() {
    vector<CharacterMapping> mappings;
    for (char c = ALPHA_WRAP_START; c <= ALPHA_WRAP_END; ++c) {
        CharacterMapping mapping;
        mapping.original = c;
        mapping.encrypted = (c - ALPHA_WRAP_START + SHIFT_VALUE) % (ALPHA_WRAP_END - ALPHA_WRAP_START + 1) + ALPHA_WRAP_START;
        mappings.push_back(mapping);
    }
    return mappings;
}

char decryptSingleCharacter(char c, const vector<CharacterMapping>& numericMappings, const vector<CharacterMapping>& alphaMappings) {
    if (isdigit(c)) {
        for (const auto& mapping : numericMappings) {
            if (mapping.encrypted == c) {
                return mapping.original;
            }
        }
    } else if (isalpha(c)) {
        for (const auto& mapping : alphaMappings) {
            if (mapping.encrypted == c) {
                return mapping.original;
            }
        }
    }
    throw runtime_error("Invalid character encountered during decryption");
}

void processTripleSequences(string& a) {
    size_t currentPosition = 0;
    while (currentPosition < a.length()) {
        size_t sPos = a.find(TRIPLE_S_MARKER, currentPosition);
        size_t kPos = a.find(TRIPLE_K_MARKER, currentPosition);

        size_t nextPos = min(sPos, kPos);
        if (nextPos == string::npos) {
            nextPos = max(sPos, kPos);
        }

        if (nextPos != string::npos) {
            if (nextPos == sPos) {
                a.replace(nextPos, TRIPLE_S_MARKER.length(), string(1, DOT_REPLACEMENT));
                currentPosition = nextPos + 1;
            } else if (nextPos == kPos) {
                a.replace(nextPos, TRIPLE_K_MARKER.length(), string(1, SPACE_REPLACEMENT));
                currentPosition = nextPos + 1;
            }
        } else {
            break;
        }
    }
}

string decryptMessage(const string& encrypted) {
    string workingCopy = encrypted;
    auto numericMappings = initializeNumericMappings();
    auto alphaMappings = initializeAlphaMappings();

    processTripleSequences(workingCopy);

    for (size_t i = 0; i < workingCopy.length(); ++i) {
        char currentChar = workingCopy[i];
        if (currentChar == DOT_REPLACEMENT || currentChar == SPACE_REPLACEMENT) {
            continue;
        }

        try {
            workingCopy[i] = decryptSingleCharacter(currentChar, numericMappings, alphaMappings);
        } catch (const runtime_error& e) {
            cerr << "Warning: " << e.what() << endl;
        }
    }

    return workingCopy;
}

int main() {
    string encryptedMessage;
    getline(cin, encryptedMessage);

    if (encryptedMessage.empty()) {
        cout << "";
        return 0;
    }

