            throw InputValidationException("Invalid x value");
        }
        if (y <= 0 || y > 10) {
            throw InputValidationException("Invalid y value");
        }
        if (z <= 0 || z > 100) {
            throw InputValidationException("Invalid z value");
        }
    }
};

class CharacterProcessor {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;

    static char processAlphabet(char c, int shift, bool isUpper) {
        int base = isUpper ? 'A' : 'a';
        int normalized = c - base;
        int shifted = (normalized + shift) % ALPHABET_SIZE;
        if (shifted < 0) shifted += ALPHABET_SIZE;
        return static_cast<char>(base + shifted);
    }

    static char processDigit(char c, int shift) {
        int normalized = c - '0';
        int shifted = (normalized + shift) % DIGIT_SIZE;
        if (shifted < 0) shifted += DIGIT_SIZE;
        return static_cast<char>('0' + shifted);
    }

public:
    static char processCharacter(char c, int shift) {
        if (isupper(c)) {
            return processAlphabet(c, shift, true);
        } else if (islower(c)) {
            return processAlphabet(c, shift, false);
        } else if (isdigit(c)) {
            return processDigit(c, shift);
        }
        return c;
    }
};

class PositionChecker {
public:
