namespace EncryptionUtils {
    template<typename T>
    constexpr bool is_valid_char_type = is_same_v<T, char> || is_same_v<T, unsigned char>;

    template<typename CharT, typename = enable_if_t<is_valid_char_type<CharT>>>
    CharT cyclic_shift(CharT c, int shift, bool is_digit) {
        constexpr auto alphabet_size = 26;
        constexpr auto digit_size = 10;

        if (is_digit) {
            if (!isdigit(c)) {
                throw invalid_argument("Non-digit character provided for digit shift");
            }
            shift %= digit_size;
            if (shift < 0) shift += digit_size;
            return '0' + (c - '0' + shift) % digit_size;
        } else {
            if (!isalpha(c)) {
                throw invalid_argument("Non-alphabetic character provided for alphabet shift");
            }
            shift %= alphabet_size;
            if (shift < 0) shift += alphabet_size;

            char base = islower(c) ? 'a' : 'A';
            return base + (c - base + shift) % alphabet_size;
        }
    }
}

