class TimeValidator {
public:
    static bool validateTime(int t) {
        if (t < 1 || t > 100) {
            throw invalid_argument("Invalid time value");
        }
        return true;
    }
};

class RoadConditionValidator {
public:
    static bool validateCondition(int c) {
        if (c < 1 || c > 50) {
            throw invalid_argument("Invalid road condition");
        }
        return true;
    }
};

class CombatSimulator {
private:
    int remainingTime;
    vector<int> roadConditions;
    bool reachedEndpoint;

    void processCondition(int condition) {
        try {
            RoadConditionValidator::validateCondition(condition);

            if (condition == 15) {
                reachedEndpoint = true;
                return;
            }

            if (remainingTime <= 0) {
                return;
            }

            switch (condition) {
                case 6:
                    remainingTime -= 0;
                    break;
                case 7:
                    remainingTime -= 5;
                    break;
                case 12:
                    remainingTime -= 20;
                    break;
                default:
                    remainingTime -= 2;
                    break;
            }

            if (remainingTime < 0) {
                remainingTime = numeric_limits<int>::min();
            }
        } catch (const invalid_argument& e) {
            cerr << "Error: " << e.what() << endl;
            remainingTime = numeric_limits<int>::min();
        }
    }

public:
    CombatSimulator(int time) : remainingTime(time), reachedEndpoint(false) {
        try {
            TimeValidator::validateTime(time);
        } catch (const invalid_argument& e) {
            cerr << "Error: " << e.what() << endl;
            remainingTime = 0;
        }
    }

    void addRoadCondition(int condition) {
        roadConditions.push_back(condition);
    }

    void simulate() {
        for (size_t i = 0; i < roadConditions.size(); ++i) {
            if (remainingTime <= 0 || reachedEndpoint) {
                break;
            }
            processCondition(roadConditions[i]);
        }
    }

    bool canReachEndpoint() const {
        return reachedEndpoint && remainingTime >= 0;
    }
};

int main() {
    int n;
    cin >> n;

    CombatSimulator simulator(n);

    try {
        for (int i = 0; i < n; ++i) {
            int condition;
            if (!(cin >> condition)) {
                throw runtime_error("Invalid input format");
