    context.right_children.resize(MAX_NODES + 1, 0);
    context.inorder_positions.reserve(MAX_NODES);
    context.current_postorder_index = n - 1;
}

void validate_input_sequences(const TreeConstructionContext& context, int n) {
    if (context.postorder.size() != n || context.inorder.size() != n) {
        throw runtime_error("Input sequence length mismatch");
    }
    for (int val : context.postorder) {
        if (val <= 0 || val > MAX_NODES) {
            throw runtime_error("Invalid node value in postorder");
        }
    }
    for (int val : context.inorder) {
        if (val <= 0 || val > MAX_NODES) {
            throw runtime_error("Invalid node value in inorder");
        }
    }
}

int build_tree_recursive(TreeConstructionContext& context, int inorder_start, int inorder_end) {
    if (inorder_start > inorder_end || context.current_postorder_index < 0) {
        return 0;
    }

    int current_root_value = context.postorder[context.current_postorder_index];
    if (current_root_value <= 0 || current_root_value > MAX_NODES) {
        throw runtime_error("Invalid root node value during construction");
    }

    int inorder_root_position = context.inorder_positions.at(current_root_value);
    if (inorder_root_position < inorder_start || inorder_root_position > inorder_end) {
        throw runtime_error("Invalid root position in inorder sequence");
    }

    context.current_postorder_index--;

    if (context.current_postorder_index < 0) {
        return current_root_value;
    }

    int right_subtree_size = inorder_end - inorder_root_position;
    if (right_subtree_size > 0) {
        context.right_children[current_root_value] = build_tree_recursive(context, inorder_root_position + 1, inorder_end);
    }

    if (context.current_postorder_index >= 0) {
        context.left_children[current_root_value] = build_tree_recursive(context, inorder_start, inorder_root_position - 1);
    }

    return current_root_value;
}

void construct_binary_tree(TreeConstructionContext& context, int n) {
    for (int i = 0; i < n; ++i) {
        context.inorder_positions[context.inorder[i]] = i;
    }

    build_tree_recursive(context, 0, n - 1);
}

void write_output(const TreeConstructionContext& context, int n) {
    ofstream output_file("sort.out");
    if (!output_file.is_open()) {
        throw runtime_error("Failed to open output file");
    }

    for (int i = 1; i <= n; ++i) {
        output_file << context.right_children[i] << " " << context.left_children[i] << endl;
    }
    output_file.close();
}

