    if (value < min_val || value > max_val) {
        throw std::out_of_range("Input value out of range");
    }
}

template<typename T>
std::string formatOutput(const T& value) {
    std::ostringstream oss;
    if (std::is_signed<T>::value) {
        oss << std::setw(8) << std::right << (value < 0 ? -value : value);
        if (value < 0) {
            return "-" + oss.str();
        }
    } else {
        oss << std::setw(8) << std::right << value;
    }
    return oss.str();
}

