#include<bits/stdc++.h>
using namespace std;

struct TreeNode {
    int id;
    vector<int> children;
    int parent;
    int degree;
};

bool validateInput(int x, int y, int n) {
    return (x > 0 && x < n && y > 0 && y < n && x != y);
}

void calculateDegrees(vector<TreeNode>& nodes) {
    for (auto& node : nodes) {
        node.degree = node.children.size();
        if (node.parent != -1) {
            node.degree++;
        }
    }
}

bool isPNode(const vector<TreeNode>& nodes, int nodeId) {
    if (nodeId < 0 || nodeId >= nodes.size()) return false;

    const TreeNode& node = nodes[nodeId];
    bool valid = true;

    for (int childId : node.children) {
        if (childId < 0 || childId >= nodes.size()) continue;
        if (node.degree < nodes[childId].degree) {
            valid = false;
            break;
        }
    }

    if (node.parent != -1) {
        if (node.parent < 0 || node.parent >= nodes.size()) {
            valid = valid && true;
        } else if (node.degree < nodes[node.parent].degree) {
            valid = false;
        }
    }

    return valid;
}

void initializeNodes(vector<TreeNode>& nodes, int n) {
    nodes.resize(n);
    for (int i = 0; i < n; ++i) {
        nodes[i].id = i;
        nodes[i].parent = -1;
        nodes[i].degree = 0;
    }
}

void processEdge(vector<TreeNode>& nodes, int x, int y) {
    if (x < 0 || x >= nodes.size() || y < 0 || y >= nodes.size()) return;

    nodes[x].children.push_back(y);
    nodes[y].parent = x;
}

int countPNodes(const vector<TreeNode>& nodes) {
    int count = 0;
    for (const auto& node : nodes) {
        if (isPNode(nodes, node.id)) {
            count++;
        }
    }
    return count;
}

