    for (int current_test_case = 0; current_test_case < test_case_count; ++current_test_case) {
        int node_count;
        input_file >> node_count;

        TreeData tree_data;
        tree_data.nodes.resize(node_count + 1);
        tree_data.p_count = 0;

        for (int i = 0; i <= node_count; ++i) {
            initializeNodeInfo(tree_data.nodes[i]);
        }

        for (int edge_index = 0; edge_index < node_count - 1; ++edge_index) {
            int parent_node, child_node;
            input_file >> parent_node >> child_node;

            tree_data.nodes[parent_node].neighbors.push_back(child_node);
            tree_data.nodes[child_node].neighbors.push_back(parent_node);

            tree_data.nodes[parent_node].degree++;
            tree_data.nodes[child_node].degree++;
        }

        for (int node_index = 0; node_index < node_count; ++node_index) {
