            int current_degree = tree_data.nodes[node_index].degree;

            for (size_t neighbor_index = 0; neighbor_index < tree_data.nodes[node_index].neighbors.size(); ++neighbor_index) {
                int neighbor_node = tree_data.nodes[node_index].neighbors[neighbor_index];
                int neighbor_degree = tree_data.nodes[neighbor_node].degree;

                if (current_degree < neighbor_degree) {
                    satisfies_p_condition = false;
                    break;
                }
            }

            if (satisfies_p_condition) {
                tree_data.nodes[node_index].is_p_node = true;
                tree_data.p_count++;
            }
        }

        output_file << tree_data.p_count << endl;
    }
}

int main() {
    ifstream input_file("p.in");
    ofstream output_file("p.out");

    if (!input_file.is_open() || !output_file.is_open()) {
