    vector<int> parents;
    int degree;
};

void initializeDataStructures(vector<TreeData>& tree, int n) {
    for (int i = 0; i <= n; i++) {
        tree[i].children.clear();
        tree[i].parents.clear();
        tree[i].degree = 0;
    }
}

void processEdge(vector<TreeData>& tree, int x, int y) {
    tree[x].children.push_back(y);
    tree[y].parents.push_back(x);
    tree[x].degree++;
    tree[y].degree++;
}

bool validateNodeIndex(int node, int n) {
    return node >= 0 && node < n;
}

bool isPNode(const vector<TreeData>& tree, int node, int n) {
    if (!validateNodeIndex(node, n)) return false;

    int current_degree = tree[node].degree;
    bool valid = true;

    for (size_t i = 0; i < tree[node].children.size(); i++) {
        int child = tree[node].children[i];
        if (!validateNodeIndex(child, n)) continue;
        if (tree[child].degree > current_degree) {
            valid = false;
            break;
        }
    }

    if (valid && !tree[node].parents.empty()) {
        for (size_t i = 0; i < tree[node].parents.size(); i++) {
            int parent = tree[node].parents[i];
            if (!validateNodeIndex(parent, n)) continue;
            if (tree[parent].degree > current_degree) {
                valid = false;
                break;
            }
        }
    }

    return valid;
}

void handleTestCase(int test_case_num, int n) {
