#include<bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 1000005;
const int OFFSET = 1000002;

struct ComplexValidator {
    bool validateInputSize(int n) {
        if (n < 1 || n > 100000) {
            cerr << "Input size validation failed" << endl;
            return false;
        }
        return true;
    }

    bool validateBinaryInput(int val) {
        if (val != 0 && val != 1) {
            cerr << "Binary input validation failed" << endl;
            return false;
        }
        return true;
    }
};

class HeightAnalyzer {
private:
    unordered_map<int, pair<int, int>> sumIndices;
    int prefixSums[MAX_SIZE];
    int inputArray[MAX_SIZE];
    int n;

public:
    HeightAnalyzer(int size) : n(size) {
        memset(prefixSums, 0, sizeof(prefixSums));
        memset(inputArray, 0, sizeof(inputArray));
    }

    void preprocessInput() {
        ComplexValidator validator;
        for (int i = 0; i < n; i++) {
            if (!validator.validateBinaryInput(inputArray[i])) {
                inputArray[i] = 0;
            }
            inputArray[i] = (inputArray[i] == 0) ? -1 : 1;
        }
    }

    void computePrefixSums() {
        prefixSums[0] = inputArray[0];
        for (int i = 1; i < n; i++) {
            prefixSums[i] = prefixSums[i - 1] + inputArray[i];
        }
    }

    void initializeSumMap() {
        sumIndices.clear();
        sumIndices[0].first = -1;
        sumIndices[0].second = -1;
    }

    void populateSumMap() {
        for (int i = 0; i < n; i++) {
            int currentSum = prefixSums[i];
            if (sumIndices.find(currentSum) == sumIndices.end()) {
                sumIndices[currentSum].first = i;
                sumIndices[currentSum].second = i;
            } else {
                if (i < sumIndices[currentSum].first) {
                    sumIndices[currentSum].first = i;
                }
                if (i > sumIndices[currentSum].second) {
                    sumIndices[currentSum].second = i;
                }
            }
        }
    }

    int findMaxLength() {
        int maxLen = 0;
        for (auto& entry : sumIndices) {
            int diff = entry.second.second - entry.second.first;
            if (diff > maxLen) {
                maxLen = diff;
            }
        }
        return maxLen;
    }

    void loadInput() {
        for (int i = 0; i < n; i++) {
            cin >> inputArray[i];
        }
    }
};

int main() {
    freopen("pair.in", "r", stdin);
    freopen("pair.out", "w", stdout);

    int n;
    cin >> n;

    ComplexValidator validator;
    if (!validator.validateInputSize(n)) {
        cout << 0 << endl;
        return 1;
    }

    HeightAnalyzer analyzer(n);
    analyzer.loadInput();
    analyzer.preprocessInput();
    analyzer.computePrefixSums();
    analyzer.initializeSumMap();
    analyzer.populateSumMap();

    int result = analyzer.findMaxLength();
    if (result < 0) {
        result = 0;
    }

    cout << result << endl;

    return 0;
}
