namespace EncryptionUtils {
    class CharacterValidator {
    public:
        static bool isValidAlphabetic(char c) {
            return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
        }
        static bool isValidNumeric(char c) {
            return c >= '0' && c <= '9';
        }
        static void validateInputCharacter(char c) {
            if (!isValidAlphabetic(c) && !isValidNumeric(c)) {
                throw runtime_error("Invalid character detected in input");
            }
        }
    };

    class CharacterTransformer {
    private:
        static char transformAlphabetic(char c, int shift, bool isLower) {
            const int alphabetSize = 26;
            char base = isLower ? 'a' : 'A';
            int normalizedShift = shift % alphabetSize;
            if (normalizedShift < 0) normalizedShift += alphabetSize;
            return static_cast<char>(base + (c - base + normalizedShift) % alphabetSize);
        }

        static char transformNumeric(char c, int shift) {
            const int numericSize = 10;
            int normalizedShift = shift % numericSize;
            if (normalizedShift < 0) normalizedShift += numericSize;
            return static_cast<char>('0' + (c - '0' + normalizedShift) % numericSize);
        }
    public:
        static char transformCharacter(char c, int shift) {
            CharacterValidator::validateInputCharacter(c);
            if (CharacterValidator::isValidAlphabetic(c)) {
