    } else if (a.min_val != b.min_val) {
        return a.min_val < b.min_val;
    } else {
        return a.index < b.index;
    }
}

void validateInput(int n) {
    if (n < 1 || n > 100) {
        throw runtime_error("Invalid number of data sets");
    }
}

void validateXY(int x, int y) {
    if (x < 1 || x > 20 || y < 1 || y > 20) {
        throw runtime_error("Invalid X or Y value");
    }
}

int computeDifference(int x, int y) {
    int diff = abs(x - y);
    if (diff < 0) {
        throw runtime_error("Difference cannot be negative");
    }
    return diff;
}

int findMinValue(int x, int y) {
    return min(x, y);
}

DataSet processDataSet(int x, int y, int index) {
    validateXY(x, y);
    int diff = computeDifference(x, y);
    int min_val = findMinValue(x, y);
    return {x, y, diff, min_val, index};
}

vector<DataSet> readAllDataSets(int n) {
