string performSafeReplacement(const string& input, const string& target, const string& replacement) {
    string result = input;
    size_t pos = 0;
    while(true) {
        pos = result.find(target, pos);
        if(pos == string::npos) break;
        if(pos + target.length() > result.length()) break;
        result.replace(pos, target.length(), replacement);
        pos += replacement.length();
    }
    return result;
}

char handleCharacterDecryption(char c) {
    if(c == ' ' || c == '.') return c;

    bool is_number = (c >= NUM_START && c <= NUM_END);
    bool is_letter = (c >= LETTER_START && c <= LETTER_END);

    if(!is_number && !is_letter) return c;

    char original_char = c;
    char decrypted_char;

    if(is_letter) {
        if(original_char >= 'a' && original_char <= 'w') {
            decrypted_char = original_char - SHIFT_VALUE;
        } else {
            int overflow = (original_char - 'a' - SHIFT_VALUE + ALPHABET_SIZE) % ALPHABET_SIZE;
            decrypted_char = NUM_START + overflow;
