            decrypted_char = original_char - SHIFT_VALUE;
        } else {
            int overflow = (original_char - NUM_START - SHIFT_VALUE + NUM_RANGE) % NUM_RANGE;
            decrypted_char = LETTER_START + overflow;
        }
    }

