class SentenceProcessor {
private:
    string sentence;
    vector<string> words;

    void tokenize() {
        istringstream iss(sentence);
        vector<string> tokens{istream_iterator<string>{iss},
                          istream_iterator<string>{}};
        for (auto& token : tokens) {
            try {
                WordValidator::validateWord(token);
                words.push_back(token);
            } catch (const runtime_error& e) {
                cerr << "Warning: " << e.what() << " - skipping: " << token << endl;
            }
        }
    }

public:
    explicit SentenceProcessor(const string& input) : sentence(input) {
        if (input.empty()) {
            throw invalid_argument("Input sentence cannot be empty");
        }
        tokenize();
    }

    string findLongestWord() {
        if (words.empty()) {
            throw runtime_error("No valid words found in sentence");
        }

        auto maxIt = max_element(words.begin(), words.end(),
            [](const string& a, const string& b) {
                if (a.length() == b.length()) {
