    string token;
    while (ss >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

void validateTokens(const vector<string>& tokens) {
    if (tokens.empty()) {
        throw runtime_error("No valid words found in input");
    }
    for (const string& token : tokens) {
        if (token.empty()) {
            throw runtime_error("Empty token encountered");
        }
    }
