            throw invalid_argument("Empty string or substring provided");
        }
        return str.find(substr) != string::npos;
    }

    void replaceAllOccurrences(string& str, const string& from, const string& to) {
        if (from.empty()) {
            throw invalid_argument("Empty 'from' string");
        }
        size_t start_pos = 0;
        while ((start_pos = str.find(from, start_pos)) != string::npos) {
            if (start_pos + from.length() > str.length()) {
                throw out_of_range("Substring out of range");
            }
            str.replace(start_pos, from.length(), to);
            start_pos += to.length();
        }
    }

    bool isSpecialTriplet(const string& str, size_t pos) {
        if (pos + 2 >= str.length()) {
            return false;
        }
        return (str[pos] == 'k' && str[pos+1] == 'k' && str[pos+2] == 'k') ||
               (str[pos] == 's' && str[pos+1] == 's' && str[pos+2] == 's');
    }
}

class CharacterDecoder {
private:
    static const string DIGITS;
    static const string LETTERS;
    static const string ALPHANUM;

    static char circularShift(char c, int shift) {
        if (!isalnum(c)) {
            throw invalid_argument("Non-alphanumeric character");
        }
        size_t pos = ALPHANUM.find(c);
        if (pos == string::npos) {
            throw out_of_range("Character not in alphanumeric set");
        }
        int new_pos = (pos - shift + ALPHANUM.length()) % ALPHANUM.length();
        return ALPHANUM[new_pos];
    }

public:
    static char decodeChar(char c) {
        try {
            if (isalpha(c)) {
                if (islower(c)) {
                    return circularShift(c, 3);
                } else {
                    throw invalid_argument("Uppercase character");
                }
            } else if (isdigit(c)) {
                return circularShift(c, 3);
            } else {
                throw invalid_argument("Non-alphanumeric character");
            }
        } catch (const exception& e) {
            cerr << "Decoding error: " << e.what() << endl;
            return c;
        }
    }
};

const string CharacterDecoder::DIGITS = "0123456789";
const string CharacterDecoder::LETTERS = "abcdefghijklmnopqrstuvwxyz";
