}

string replace_question_marks(const string& input) {
    string intermediate_result;
    for (char c : input) {
        if (c == '?') {
            intermediate_result += '!';
        } else {
            intermediate_result += c;
        }
    }
    return intermediate_result;
}

vector<WordInfo> tokenize_string(const string& input) {
    vector<WordInfo> tokens;
    istringstream iss(input);
    string token;
    size_t pos_counter = 0;

    while (iss >> token) {
        WordInfo wi;
        wi.content = token;
        wi.processed = false;
        wi.original_position = pos_counter++;
        tokens.push_back(wi);
    }

    return tokens;
}

void apply_rule_three(vector<WordInfo>& words) {
    for (size_t i = 0; i < words.size(); ) {
        if (i + 1 < words.size() && !words[i].processed && !words[i+1].processed) {
            if (words[i].content == "can" && words[i+1].content == "you") {
                words[i].content = "I";
                words[i+1].content = "can";
                words[i].processed = true;
                words[i+1].processed = true;
                i += 2;
                continue;
            } else if (words[i].content == "could" && words[i+1].content == "you") {
                words[i].content = "I";
                words[i+1].content = "could";
                words[i].processed = true;
                words[i+1].processed = true;
                i += 2;
                continue;
            }
        }
        i++;
    }
}

void apply_rule_four(vector<WordInfo>& words) {
    for (auto& word : words) {
        if (!word.processed && (word.content == "I" || word.content == "me")) {
            word.content = "you";
            word.processed = true;
        }
    }
}

string reconstruct_sentence(const vector<WordInfo>& words) {
    if (words.empty()) return "";

    vector<pair<size_t, string>> ordered_words;
    for (const auto& word : words) {
        ordered_words.emplace_back(word.original_position, word.content);
    }

    sort(ordered_words.begin(), ordered_words.end());

    string final_output;
    for (const auto& word_pair : ordered_words) {
        final_output += word_pair.second + " ";
    }

    if (!final_output.empty()) {
        final_output.pop_back();
    }

    return final_output;
}

string process_single_input(const string& input) {
    string phase_one_result = perform_case_conversion(input);
    string phase_two_result = replace_question_marks(phase_one_result);
    vector<WordInfo> tokenized_words = tokenize_string(phase_two_result);

    vector<WordInfo> rule_three_input = tokenized_words;
    apply_rule_three(rule_three_input);

    vector<WordInfo> rule_four_input = rule_three_input;
    apply_rule_four(rule_four_input);

    string final_result = reconstruct_sentence(rule_four_input);
    return final_result;
}

