string perform_punctuation_replacement(const string& input) {
    string temporary_storage;
    for (char current_char : input) {
        if (current_char == '?') {
            temporary_storage += '!';
        } else {
            temporary_storage += current_char;
        }
    }
    return temporary_storage;
}

vector<WordMetadata> tokenize_string(const string& input) {
    vector<WordMetadata> word_collection;
    istringstream input_stream(input);
    string temporary_word;
    size_t position_counter = 0;

    while (input_stream >> temporary_word) {
        WordMetadata word_data;
        word_data.content = temporary_word;
        word_data.processed = false;
        word_data.original_position = position_counter++;
        word_collection.push_back(word_data);
    }

    return word_collection;
}

