            word.content = "you";
            word.processed = true;
        }
    }
}

string reconstruct_output(const vector<WordMetadata>& words) {
    if (words.empty()) return "";

    vector<pair<size_t, string>> ordered_words;
    for (const auto& word : words) {
        ordered_words.emplace_back(word.original_position, word.content);
    }

    sort(ordered_words.begin(), ordered_words.end(), 
        [](const pair<size_t, string>& a, const pair<size_t, string>& b) {
            return a.first < b.first;
        });

    string output_buffer;
    for (size_t i = 0; i < ordered_words.size(); ++i) {
        if (i != 0) output_buffer += " ";
        output_buffer += ordered_words[i].second;
