    void tokenizeSentence() {
        istringstream iss(sentence);
        vector<string> tokens{istream_iterator<string>{iss}, istream_iterator<string>{}};

        for (size_t i = 0; i < tokens.size(); ++i) {
            bool valid = true;
            for (char c : tokens[i]) {
                if (!isalpha(c)) {
                    valid = false;
                    break;
                }
            }
            words.push_back({tokens[i], i, tokens[i].length(), valid});
        }
    }

