#include <algorithm>
#include <stdexcept>
using namespace std;

const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const int NUMERIC_WRAPAROUND_OFFSET = 7;
const int ALPHA_WRAPAROUND_OFFSET = 23;

struct DecryptionContext {
    string input;
    vector<size_t> specialPositions;
    vector<char> specialChars;
};

void initializeContext(DecryptionContext& ctx, const string& s) {
    ctx.input = s;
    ctx.specialPositions.clear();
    ctx.specialChars.clear();
}

void processSpecialSequences(DecryptionContext& ctx) {
    size_t kkkPos = ctx.input.find(SPACE_REPLACEMENT);
    while (kkkPos != string::npos) {
        ctx.specialPositions.push_back(kkkPos);
        ctx.specialChars.push_back(' ');
        ctx.input.replace(kkkPos, SPACE_REPLACEMENT.length(), "   ");
        kkkPos = ctx.input.find(SPACE_REPLACEMENT, kkkPos + 1);
    }

    size_t sssPos = ctx.input.find(DOT_REPLACEMENT);
    while (sssPos != string::npos) {
        ctx.specialPositions.push_back(sssPos);
        ctx.specialChars.push_back('.');
        ctx.input.replace(sssPos, DOT_REPLACEMENT.length(), "   ");
        sssPos = ctx.input.find(DOT_REPLACEMENT, sssPos + 1);
    }
}

void decryptCharacters(DecryptionContext& ctx) {
    for (size_t i = 0; i < ctx.input.length(); i++) {
        bool isSpecialPos = false;
        for (size_t j = 0; j < ctx.specialPositions.size(); j++) {
            if (i >= ctx.specialPositions[j] && i < ctx.specialPositions[j] + SHIFT_VALUE) {
                isSpecialPos = true;
                break;
            }
        }

        if (!isSpecialPos) {
            char currentChar = ctx.input[i];
            if (currentChar >= 'd' && currentChar <= 'z') {
                ctx.input[i] = currentChar - SHIFT_VALUE;
            } else if (currentChar >= 'a' && currentChar <= 'c') {
                ctx.input[i] = currentChar + ALPHA_WRAPAROUND_OFFSET;
            } else if (currentChar >= '3' && currentChar <= '9') {
                ctx.input[i] = currentChar - SHIFT_VALUE;
            } else if (currentChar >= '0' && currentChar <= '2') {
                ctx.input[i] = currentChar + NUMERIC_WRAPAROUND_OFFSET;
            }
        }
    }
}

void restoreSpecialCharacters(DecryptionContext& ctx) {
    for (size_t i = 0; i < ctx.specialPositions.size(); i++) {
        if (ctx.specialPositions[i] < ctx.input.length()) {
            ctx.input[ctx.specialPositions[i]] = ctx.specialChars[i];
            for (size_t j = ctx.specialPositions[i] + 1; j < ctx.specialPositions[i] + SHIFT_VALUE; j++) {
                if (j < ctx.input.length()) {
                    ctx.input.erase(j, 1);
                }
            }
        }
    }
}

string decryptMessage(const string& encrypted) {
    DecryptionContext ctx;
    initializeContext(ctx, encrypted);
    processSpecialSequences(ctx);
    decryptCharacters(ctx);
    restoreSpecialCharacters(ctx);
    return ctx.input;
}

