TreeConstructionState initialize_state(int pos, int root, int l, int r) {
    TreeConstructionState state;
    state.is_valid = false;
    state.current_root = root;
    state.left_bound = l;
    state.right_bound = r;
    state.left_child_pos = invalid_node;
    state.right_child_pos = invalid_node;
    state.left_subtree_size = 0;
