class HeightAnalyzer {
private:
    vector<int> prefixSums;
    unordered_map<int, pair<int, int>> sumIndices;
    int maxLength;

public:
    HeightAnalyzer() : maxLength(0) {
        prefixSums.reserve(MAX_SIZE);
        sumIndices.reserve(MAX_SIZE);
    }

    void preprocessArray(vector<int>& arr) {
        if(arr.empty()) return;
        prefixSums.resize(arr.size());
        prefixSums[0] = (arr[0] == 0) ? -1 : 1;
        for(size_t i = 1; i < arr.size(); ++i) {
            prefixSums[i] = prefixSums[i-1] + ((arr[i] == 0) ? -1 : 1);
        }
    }

    void analyzePrefixSums() {
        sumIndices.clear();
        sumIndices[0] = make_pair(-1, -1);
        for(size_t i = 0; i < prefixSums.size(); ++i) {
            int currentSum = prefixSums[i];
            if(sumIndices.find(currentSum) == sumIndices.end()) {
                sumIndices[currentSum] = make_pair(i, INVALID);
            } else {
                auto& entry = sumIndices[currentSum];
                if(entry.second == INVALID) {
                    entry.second = i;
                } else if(i > entry.second) {
                    entry.second = i;
                }
            }
        }
    }

    void calculateMaxLength() {
        for(const auto& entry : sumIndices) {
            if(entry.second.second != INVALID) {
                int currentLength = entry.second.second - entry.second.first;
                if(currentLength > maxLength) {
                    maxLength = currentLength;
                }
            }
        }
    }

    int getMaxLength() const {
        return maxLength;
    }
};

