class CombatTimeValidator {
public:
    static bool validateTime(int time) {
        if (time < 1 || time > 100) {
            throw runtime_error("Invalid combat time specification");
        }
        return true;
    }
};

class RoadConditionValidator {
public:
    static bool validateCondition(int condition) {
        if (condition < 1 || condition > 50) {
            throw runtime_error("Invalid road condition specification");
        }
        return true;
    }
};

class TimeManager {
private:
    int remainingTime;
    bool reachedEndpoint;
public:
    TimeManager(int initialTime) : remainingTime(initialTime), reachedEndpoint(false) {
        if (!CombatTimeValidator::validateTime(initialTime)) {
            throw runtime_error("TimeManager initialization failed");
        }
    }

    void processCondition(int condition) {
        try {
            RoadConditionValidator::validateCondition(condition);

            if (reachedEndpoint) {
                return;
            }

            if (condition == 6) {
                remainingTime = remainingTime;
            } else if (condition == 7) {
                remainingTime = max(remainingTime - 5, numeric_limits<int>::min());
            } else if (condition == 12) {
                remainingTime = max(remainingTime - 20, numeric_limits<int>::min());
            } else if (condition == 15) {
                reachedEndpoint = true;
                return;
            } else {
                remainingTime = max(remainingTime - 2, numeric_limits<int>::min());
            }

            if (remainingTime < 0 && !reachedEndpoint) {
                throw runtime_error("Time exhausted before reaching endpoint");
            }
        } catch (const exception& e) {
            cerr << "Error processing condition: " << e.what() << endl;
            throw;
        }
    }

    bool canContinue() const {
        return remainingTime >= 0 && !reachedEndpoint;
    }

    bool hasReachedEndpoint() const {
        return reachedEndpoint;
    }
};

class InputParser {
public:
    static pair<int, vector<int>> parseInput() {
        int n;
        vector<int> conditions;

        string line;
        while (getline(cin, line)) {
            istringstream iss(line);
            if (n == 0) {
                if (!(iss >> n)) {
                    throw runtime_error("Failed to read combat time");
                }
                CombatTimeValidator::validateTime(n);
            } else {
                int temp;
                while (iss >> temp) {
                    RoadConditionValidator::validateCondition(temp);
                    conditions.push_back(temp);
                }
                if (conditions.size() != static_cast<size_t>(n)) {
                    throw runtime_error("Mismatch between time and conditions count");
                }
            }
        }
        return make_pair(n, conditions);
    }
};

class OutputGenerator {
public:
    static void generateOutput(bool success) {
        if (success) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }
    }
};

