    long long price;
    long long value;
    long long requirement;
};

vector<NobleShop> shops;
long long dp[MAX_MONEY + EXTRA_BUFFER];
bool visited[MAX_SHOP][MAX_MONEY + EXTRA_BUFFER];
long long max_value_cache[MAX_SHOP][MAX_MONEY + EXTRA_BUFFER];

void initialize_globals() {
    memset(dp, 0, sizeof(dp));
    memset(visited, false, sizeof(visited));
    memset(max_value_cache, -1, sizeof(max_value_cache));
    shops.clear();
}

void validate_input(int n, int m) {
    if (n < 1 || n > 5000) {
        cerr << "Invalid number of shops" << endl;
        exit(1);
    }
    if (m < 1 || m > 5000) {
        cerr << "Invalid amount of money" << endl;
        exit(1);
    }
}

void process_shop(int index, int current_money) {
    if (index < 1 || index > shops.size()) return;
    if (current_money < 0 || current_money > MAX_MONEY + EXTRA_BUFFER) return;

    if (visited[index][current_money]) return;
    visited[index][current_money] = true;

    NobleShop shop = shops[index-1];
    if (shop.price <= current_money && current_money - shop.price >= shop.requirement) {
        long long potential_value = dp[current_money - shop.price] + shop.value;
        if (potential_value > dp[current_money]) {
            dp[current_money] = potential_value;
            max_value_cache[index][current_money] = dp[current_money];
        }
    }

    process_shop(index + 1, current_money);
    process_shop(index, current_money - 1);
}

