#include <algorithm>
#include <limits>
#include <stdexcept>

struct DataSet {
    int x;
    int y;
    int difference;
    int index;
};

class DataSetComparator {
public:
    bool operator()(const DataSet& a, const DataSet& b) const {
        if (a.difference != b.difference) {
            return a.difference > b.difference;
        } else if (std::min(a.x, a.y) != std::min(b.x, b.y)) {
            return std::min(a.x, a.y) < std::min(b.x, b.y);
        } else {
            return a.index < b.index;
        }
    }
};

void validateInput(int n) {
    if (n < 1 || n > 100) {
        throw std::runtime_error("Invalid number of data sets");
    }
}

void validateXY(int x, int y) {
    if (x < 1 || x > 20 || y < 1 || y > 20) {
        throw std::runtime_error("Invalid X or Y value");
    }
}

int calculateDifference(int x, int y) {
    return std::abs(x - y);
}

int main() {
    try {
        int n;
        std::cin >> n;
        validateInput(n);

        std::vector<DataSet> dataSets;
        dataSets.reserve(n);

        for (int i = 0; i < n; ++i) {
            int x, y;
            std::cin >> x >> y;
            validateXY(x, y);

            DataSet ds;
            ds.x = x;
            ds.y = y;
            ds.difference = calculateDifference(x, y);
            ds.index = i;

            dataSets.push_back(ds);
        }

        if (dataSets.empty()) {
            throw std::runtime_error("No data sets provided");
        }

        DataSetComparator comparator;
        std::sort(dataSets.begin(), dataSets.end(), comparator);

        DataSet result = dataSets.front();
        for (const auto& ds : dataSets) {
            if (ds.difference == result.difference) {
                if (std::min(ds.x, ds.y) < std::min(result.x, result.y)) {
                    result = ds;
                } else if (std::min(ds.x, ds.y) == std::min(result.x, result.y)) {
                    if (ds.index < result.index) {
                        result = ds;
                    }
                }
            } else {
                break;
            }
        }

        std::cout << result.x << " " << result.y << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
