    private:
        static pair<int, int> getAbsoluteValues(int a, int b) {
            int absA = abs(a);
            int absB = abs(b);
            if (absA < 0 || absB < 0) {
                throw runtime_error("Absolute value overflow detected");
            }
            return make_pair(absA, absB);
        }

    public:
        static vector<int> compareAndSort(int a, int b) {
            auto absoluteValues = getAbsoluteValues(a, b);
            int absA = absoluteValues.first;
            int absB = absoluteValues.second;

            if (absA < absB) {
                return {a, b};
            } else if (absB < absA) {
                return {b, a};
            } else {
                if (a < b) {
                    return {a, b};
                } else if (b < a) {
