#include<bits/stdc++.h>
using namespace std;

const int MAX_OFFSET = 200005;
const int BASE_OFFSET = 100002;

struct SegmentTracker {
    unordered_map<int, pair<int, int>> ranges;
    void update(int key, int pos) {
        if (ranges.find(key) == ranges.end()) {
            ranges[key] = make_pair(pos, pos);
        } else {
            ranges[key].first = min(ranges[key].first, pos);
            ranges[key].second = max(ranges[key].second, pos);
        }
    }
};

class HeightAnalyzer {
private:
    int n;
    vector<int> gender;
    vector<int> prefix;
    SegmentTracker tracker;

    void validateInput() {
        if (n < 1 || n > 100000) {
            cerr << "Invalid input size detected" << endl;
            exit(1);
        }
        for (int g : gender) {
            if (g != 0 && g != 1) {
                cerr << "Invalid gender value detected" << endl;
                exit(1);
            }
        }
    }

    void computePrefix() {
        prefix.resize(n + 1);
        prefix[0] = 0;
        for (int i = 1; i <= n; i++) {
            prefix[i] = prefix[i - 1] + (gender[i - 1] == 0 ? 1 : -1);
        }
    }

    void populateTracker() {
        for (int i = 0; i <= n; i++) {
            int adjusted = prefix[i] + BASE_OFFSET;
            if (adjusted < 0 || adjusted >= MAX_OFFSET) {
                cerr << "Offset out of bounds" << endl;
                continue;
            }
            tracker.update(adjusted, i);
        }
    }

public:
    HeightAnalyzer(int num, const vector<int>& g) : n(num), gender(g) {
        validateInput();
        computePrefix();
        populateTracker();
    }

    int findMaxLength() {
        int max_len = 0;
        for (const auto& entry : tracker.ranges) {
            if (entry.second.second - entry.second.first > max_len) {
                max_len = entry.second.second - entry.second.first;
            }
        }
        return max_len;
    }
};

int main() {
