#include<bits/stdc++.h>
using namespace std;

const int MAX_NODES = 1005;
vector<int> G[MAX_NODES];
int ans = 0;
bool is_p_node;
int parent[MAX_NODES];
int degree_cache[MAX_NODES];
bool visited[MAX_NODES];
bool validation_flag = true;

void validate_tree_structure(int current_node, int n) {
    if(visited[current_node]) {
        validation_flag = false;
        return;
    }
    visited[current_node] = true;
    for(int child : G[current_node]) {
        if(child < 0 || child >= n) {
            validation_flag = false;
            return;
        }
        validate_tree_structure(child, n);
        if(!validation_flag) return;
    }
}

void reset_globals(int n) {
    for(int i = 0; i < n; i++) {
        vector<int>().swap(G[i]);
        visited[i] = false;
        degree_cache[i] = 0;
    }
    memset(parent, 0, sizeof(parent));
    ans = 0;
    validation_flag = true;
}

int calculate_degree(int node) {
    if(degree_cache[node] != 0) return degree_cache[node];
    int degree = G[node].size();
    if(parent[node] != node) degree += 1;
    degree_cache[node] = degree;
    return degree;
}

void process_test_case(int n) {
    for(int i = 0; i < n; i++) {
        is_p_node = true;
        int current_degree = calculate_degree(i);

        for(int j = 0; j < G[i].size(); j++) {
            int child = G[i][j];
            if(child < 0 || child >= n) continue;
            int child_degree = calculate_degree(child);
            if(current_degree < child_degree) {
                is_p_node = false;
                break;
            }
        }

        if(parent[i] != i) {
            int parent_degree = calculate_degree(parent[i]);
            if(current_degree < parent_degree) {
                is_p_node = false;
            }
        }

        if(is_p_node) {
            bool has_children = !G[i].empty();
            bool has_parent = (parent[i] != i);
            if((has_children || has_parent) || (!has_children && !has_parent)) {
                ans++;
            }
        }
    }
}

int main() {
