#include <vector>
#include <string>
#include <cstdlib>
#include <stdexcept>

using namespace std;

struct ChessboardConfig {
    vector<vector<int>> grid;
    int size;
    vector<bool> white_row;
    vector<bool> white_diag1;
    vector<bool> white_diag2;
    vector<bool> black_row;
    vector<bool> black_diag1;
    vector<bool> black_diag2;
};

int total_solutions = 0;

void initializeConfig(ChessboardConfig& config, int n) {
    config.size = n;
    config.grid.resize(n, vector<int>(n));
    config.white_row.resize(n, false);
    config.white_diag1.resize(2 * n, false);
    config.white_diag2.resize(2 * n, false);
    config.black_row.resize(n, false);
    config.black_diag1.resize(2 * n, false);
    config.black_diag2.resize(2 * n, false);
}

bool validateWhitePosition(const ChessboardConfig& config, int row, int col) {
    if (row < 0 || row >= config.size || col < 0 || col >= config.size) {
        return false;
    }
    if (config.grid[row][col] == 0) {
        return false;
    }
    if (config.white_row[row]) {
        return false;
    }
    if (config.white_diag1[row + col]) {
        return false;
    }
    if (config.white_diag2[row - col + config.size]) {
        return false;
    }
    return true;
}

bool validateBlackPosition(const ChessboardConfig& config, int row, int col) {
    if (row < 0 || row >= config.size || col < 0 || col >= config.size) {
        return false;
    }
    if (config.grid[row][col] == 0) {
        return false;
    }
    if (config.black_row[row]) {
        return false;
    }
    if (config.black_diag1[row + col]) {
        return false;
    }
    if (config.black_diag2[row - col + config.size]) {
        return false;
    }
    return true;
}

void placeQueens(ChessboardConfig& config, int col) {
    if (col == config.size) {
        total_solutions++;
        return;
    }

    for (int white_row = 0; white_row < config.size; white_row++) {
        if (validateWhitePosition(config, white_row, col)) {
            ChessboardConfig new_config = config;
            new_config.white_row[white_row] = true;
            new_config.white_diag1[white_row + col] = true;
            new_config.white_diag2[white_row - col + config.size] = true;

            for (int black_row = 0; black_row < config.size; black_row++) {
                if (black_row != white_row && validateBlackPosition(new_config, black_row, col)) {
                    ChessboardConfig final_config = new_config;
                    final_config.black_row[black_row] = true;
                    final_config.black_diag1[black_row + col] = true;
                    final_config.black_diag2[black_row - col + config.size] = true;
                    placeQueens(final_config, col + 1);
                }
            }
        }
    }
}

void processInput(const string& filename, ChessboardConfig& config) {
    ifstream input_file(filename.c_str());
    if (!input_file.is_open()) {
        throw runtime_error("Unable to open input file");
    }

    int n;
    input_file >> n;
    initializeConfig(config, n);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!(input_file >> config.grid[i][j])) {
                throw runtime_error("Invalid input format");
            }
        }
    }
    input_file.close();
}

void writeOutput(const string& filename, int result) {
    ofstream output_file(filename.c_str());
    if (!output_file.is_open()) {
        throw runtime_error("Unable to open output file");
    }
    output_file << result << endl;
    output_file.close();
}

int main() {
    ChessboardConfig board_config;
    try {
        processInput("queen.in", board_config);
        placeQueens(board_config, 0);
        writeOutput("queen.out", total_solutions);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
