template<typename T>
constexpr bool is_safe_abs(T value) {
    return !(numeric_limits<T>::is_signed && value == numeric_limits<T>::min());
}

template<typename T>
T safe_abs(T value) {
    if constexpr (numeric_limits<T>::is_signed) {
        if (!is_safe_abs(value)) {
            throw overflow_error("Absolute value overflow detected");
        }
    }
    return value < 0 ? -value : value;
}

struct NumberPair {
    int original;
    int absolute;
    bool operator<(const NumberPair& other) const {
        if (absolute != other.absolute) {
            return absolute < other.absolute;
        }
        return original < other.original;
    }
};

void validate_input_stream(istream& is) {
    if (is.fail()) {
        is.clear();
        is.ignore(numeric_limits<streamsize>::max(), '\n');
        throw runtime_error("Invalid input detected");
    }
}

void sort_and_output(int a, int b) {
    try {
        NumberPair pa{a, safe_abs(a)};
        NumberPair pb{b, safe_abs(b)};

        if (pa < pb) {
            cout << a << " " << b;
        } else if (pb < pa) {
            cout << b << " " << a;
        } else {
            if (a < b) {
