using namespace std;

const int MAX_DIMENSION = 100;
const int MIN_DIMENSION = 1;

struct CanyonDimensions {
    int rows;
    int cols;
};

struct Position {
    int x;
    int y;
};

class CanyonMapValidator {
public:
    static void validateDimensions(int n, int m) {
        if (n < MIN_DIMENSION || n > MAX_DIMENSION || m < MIN_DIMENSION || m > MAX_DIMENSION) {
            throw out_of_range("Invalid canyon dimensions");
        }
    }

    static void validatePosition(const Position& pos, const CanyonDimensions& dims) {
        if (pos.x < 1 || pos.x > dims.rows || pos.y < 1 || pos.y > dims.cols) {
            throw out_of_range("Position out of canyon bounds");
        }
    }
};

class GrasslandCounter {
private:
    char terrain[MAX_DIMENSION+2][MAX_DIMENSION+2];
    bool visited[MAX_DIMENSION+2][MAX_DIMENSION+2];
    const int directions[4][2] = {{-1,0}, {1,0}, {0,-1}, {0,1}};
    CanyonDimensions dimensions;

    void initializeVisited() {
        for (int i = 0; i <= dimensions.rows + 1; i++) {
            for (int j = 0; j <= dimensions.cols + 1; j++) {
                visited[i][j] = false;
            }
        }
    }

    bool isPositionValid(const Position& pos) {
        return pos.x >= 1 && pos.x <= dimensions.rows && pos.y >= 1 && pos.y <= dimensions.cols;
    }

    void performDepthFirstSearch(Position current) {
        vector<Position> stack;
        stack.push_back(current);
        visited[current.x][current.y] = true;

        while (!stack.empty()) {
            Position top = stack.back();
            stack.pop_back();

            for (int i = 0; i < 4; i++) {
                Position neighbor = {top.x + directions[i][0], top.y + directions[i][1]};
                if (isPositionValid(neighbor) && terrain[neighbor.x][neighbor.y] == '#' && !visited[neighbor.x][neighbor.y]) {
                    visited[neighbor.x][neighbor.y] = true;
                    stack.push_back(neighbor);
                }
            }
        }
    }

public:
    GrasslandCounter(int n, int m) {
        CanyonDimensions dims = {n, m};
        CanyonMapValidator::validateDimensions(n, m);
        dimensions = dims;
        initializeVisited();
    }

    void readTerrain() {
        for (int i = 1; i <= dimensions.rows; i++) {
            string row;
            cin >> row;
            if (row.length() != static_cast<size_t>(dimensions.cols)) {
                throw invalid_argument("Invalid row length in terrain data");
            }
            for (int j = 1; j <= dimensions.cols; j++) {
                terrain[i][j] = row[j-1];
            }
        }
    }

    int countGrasslands() {
        int grasslandCount = 0;
        for (int i = 1; i <= dimensions.rows; i++) {
            for (int j = 1; j <= dimensions.cols; j++) {
                Position current = {i, j};
                if (terrain[i][j] == '#' && !visited[i][j]) {
                    performDepthFirstSearch(current);
                    grasslandCount++;
                }
            }
        }
        return grasslandCount;
    }
};

int main() {
    try {
        ifstream inputFile("hiking.in");
        ofstream outputFile("hiking.out");

        if (!inputFile.is_open() || !outputFile.is_open()) {
            throw runtime_error("Failed to open input or output file");
        }

        streambuf* cinBackup = cin.rdbuf();
        streambuf* coutBackup = cout.rdbuf();

        cin.rdbuf(inputFile.rdbuf());
        cout.rdbuf(outputFile.rdbuf());

        int n, m;
