        counter.readTerrain();
        int result = counter.countGrasslands();

        cout << result;

        cin.rdbuf(cinBackup);
        cout.rdbuf(coutBackup);

        inputFile.close();
        outputFile.close();

        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
}
