    int digit_sum;
    int original_index;
};

bool validate_input_string(const string& s) {
    if (s.empty()) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    return true;
}

long long convert_to_number(const string& s) {
    istringstream iss(s);
    long long val;
    iss >> val;
    if (iss.fail()) {
        return numeric_limits<long long>::max();
    }
    return val;
}

int calculate_digit_sum(long long x) {
    if (x < 0) x = -x;
    int sum = 0;
    while (x != 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

bool compare_plates(const NumberPlate& a, const NumberPlate& b) {
    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    } else {
        return a.numeric_value > b.numeric_value;
    }
}

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cerr << "Invalid number of plates" << endl;
        return 1;
    }

    vector<NumberPlate> plates;
    plates.reserve(n);
    string last_plate;
    bool last_plate_valid = false;

    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        if (!validate_input_string(s)) {
            continue;
