        long long num = convert_to_number(s);
        if (num == numeric_limits<long long>::max()) {
            continue;
        }
        int sum = calculate_digit_sum(num);
        plates.push_back({s, num, sum, i});
        if (i == n - 1) {
            last_plate = s;
            last_plate_valid = true;
        }
    }

    if (!last_plate_valid) {
        cerr << "Invalid last plate" << endl;
        return 1;
