#include<bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 105;
const int MIN_DIMENSION = 1;
const int MAX_DIRECTIONS = 4;
const int DIRECTION_OFFSETS[MAX_DIRECTIONS][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

struct CanyonMap {
    string terrain[MAX_DIMENSION];
    bool visited[MAX_DIMENSION][MAX_DIMENSION];
    int width;
    int height;
};

bool validateCoordinates(const CanyonMap& map, int x, int y) {
    if (x < 0 || x >= map.height || y < 0 || y >= map.width) {
        return false;
    }
    if (map.terrain[x][y] != '#' && map.terrain[x][y] != '.') {
        return false;
    }
    return true;
}

bool isBush(const CanyonMap& map, int x, int y) {
    if (!validateCoordinates(map, x, y)) {
        return false;
    }
    return map.terrain[x][y] == '#';
}

void initializeVisited(CanyonMap& map) {
    for (int i = 0; i < MAX_DIMENSION; ++i) {
        for (int j = 0; j < MAX_DIMENSION; ++j) {
            map.visited[i][j] = false;
        }
    }
}

void depthFirstSearch(CanyonMap& map, int x, int y) {
    if (map.visited[x][y]) {
        return;
    }
    if (!isBush(map, x, y)) {
        return;
    }

    map.visited[x][y] = true;

    for (int direction = 0; direction < MAX_DIRECTIONS; ++direction) {
        int newX = x + DIRECTION_OFFSETS[direction][0];
        int newY = y + DIRECTION_OFFSETS[direction][1];

        if (validateCoordinates(map, newX, newY)) {
            if (isBush(map, newX, newY) && !map.visited[newX][newY]) {
                depthFirstSearch(map, newX, newY);
            }
        }
    }
}

bool validateMapDimensions(int n, int m) {
    if (n < MIN_DIMENSION || n > MAX_DIMENSION - 5) {
        return false;
    }
    if (m < MIN_DIMENSION || m > MAX_DIMENSION - 5) {
        return false;
    }
    return true;
}

int countGrasslands(CanyonMap& map) {
    int count = 0;
    for (int i = 0; i < map.height; ++i) {
        for (int j = 0; j < map.width; ++j) {
            if (isBush(map, i, j) && !map.visited[i][j]) {
                ++count;
                depthFirstSearch(map, i, j);
            }
        }
    }
    return count;
}

void processInput(CanyonMap& map) {
    ifstream inputFile("hiking.in");
    if (!inputFile.is_open()) {
        cerr << "Error opening input file" << endl;
        exit(1);
    }

    inputFile >> map.height >> map.width;
    if (!validateMapDimensions(map.height, map.width)) {
        cerr << "Invalid map dimensions" << endl;
        exit(1);
    }

    for (int i = 0; i < map.height; ++i) {
        inputFile >> map.terrain[i];
        if (map.terrain[i].length() != map.width) {
            cerr << "Invalid terrain row length" << endl;
            exit(1);
        }
    }
    inputFile.close();
}

void writeOutput(int result) {
    ofstream outputFile("hiking.out");
    if (!outputFile.is_open()) {
        cerr << "Error opening output file" << endl;
        exit(1);
    }
    outputFile << result;
    outputFile.close();
}

int main() {
    CanyonMap map;
    initializeVisited(map);
    processInput(map);
    int grasslandCount = countGrasslands(map);
    writeOutput(grasslandCount);
    return 0;
}
