#include<bits/stdc++.h>
using namespace std;

struct CanyonConfiguration {
    vector<string> terrainGrid;
    int rowDimension;
    int columnDimension;
};

struct CoordinateDelta {
    int xModifier;
    int yModifier;
};

class GrasslandAnalyzer {
private:
    vector<vector<bool>> visitationTracker;
    vector<CoordinateDelta> directionVectors;
    CanyonConfiguration canyonData;

    bool validateCoordinateBounds(int xCoord, int yCoord) {
        bool xValid = (xCoord >= 0) && (xCoord < canyonData.rowDimension);
        bool yValid = (yCoord >= 0) && (yCoord < canyonData.columnDimension);
        return xValid && yValid;
    }

    void performDepthFirstExploration(int xCoord, int yCoord) {
        visitationTracker[xCoord][yCoord] = true;
        for (const auto& direction : directionVectors) {
            int newX = xCoord + direction.xModifier;
            int newY = yCoord + direction.yModifier;
            if (validateCoordinateBounds(newX, newY)) {
                if (!visitationTracker[newX][newY] && canyonData.terrainGrid[newX][newY] == '#') {
                    performDepthFirstExploration(newX, newY);
                }
            }
        }
    }

public:
    GrasslandAnalyzer(const CanyonConfiguration& config) : canyonData(config) {
        directionVectors = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        visitationTracker.resize(config.rowDimension, vector<bool>(config.columnDimension, false));
    }

    int calculateRequiredSearchers() {
        int grasslandCount = 0;
        for (int i = 0; i < canyonData.rowDimension; ++i) {
            for (int j = 0; j < canyonData.columnDimension; ++j) {
                if (canyonData.terrainGrid[i][j] == '#' && !visitationTracker[i][j]) {
                    ++grasslandCount;
                    performDepthFirstExploration(i, j);
                }
            }
        }
        return grasslandCount;
    }
};

int main() {
    ifstream inputFileStream("hiking.in");
    ofstream outputFileStream("hiking.out");

    if (!inputFileStream.is_open() || !outputFileStream.is_open()) {
        cerr << "File operation failed" << endl;
        return EXIT_FAILURE;
    }

    CanyonConfiguration canyonConfig;
    inputFileStream >> canyonConfig.rowDimension >> canyonConfig.columnDimension;
    canyonConfig.terrainGrid.resize(canyonConfig.rowDimension);

    for (int i = 0; i < canyonConfig.rowDimension; ++i) {
        inputFileStream >> canyonConfig.terrainGrid[i];
    }

    GrasslandAnalyzer analyzer(canyonConfig);
    int result = analyzer.calculateRequiredSearchers();

    outputFileStream << result;

    inputFileStream.close();
    outputFileStream.close();

    return 0;
}
