        char c = str[i];
        if (isalpha(c)) {
            hasAlpha = true;
            currentToken += c;
            inWord = true;
        } else if (isspace(c)) {
            if (inWord && hasAlpha) {
                tokens.push_back(currentToken);
                currentToken.clear();
                inWord = false;
                hasAlpha = false;
