#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cctype>
#include <stdexcept>
#include <limits>

using namespace std;

struct WordMetadata {
    string content;
    size_t position;
    bool is_valid;
    size_t ascii_sum;
};

class SentenceValidator {
public:
    static bool validateCharacter(char c) {
        return isalpha(c) || isspace(c);
    }

    static void verifySentence(const string& s) {
        if (s.empty()) {
            throw runtime_error("Empty sentence detected");
        }

        for (char c : s) {
            if (!validateCharacter(c)) {
                throw runtime_error("Invalid character in sentence");
            }
        }

        if (s.length() > numeric_limits<streamsize>::max()) {
            throw runtime_error("Sentence too long");
        }
    }
};

class WordProcessor {
private:
    vector<WordMetadata> words;

    void preprocessWord(WordMetadata& word) {
        word.is_valid = true;
        word.ascii_sum = 0;
        for (char c : word.content) {
            if (!isalpha(c)) {
                word.is_valid = false;
            }
            word.ascii_sum += static_cast<size_t>(c);
        }
    }

public:
    explicit WordProcessor(const string& s) {
        istringstream iss(s);
        string token;
        size_t pos = 0;

        while (iss >> token) {
            WordMetadata wm;
            wm.content = token;
            wm.position = pos++;
            words.push_back(wm);
        }

        for (auto& word : words) {
            preprocessWord(word);
        }
    }

    string findLongestWord() {
        if (words.empty()) {
            return "";
        }

        vector<WordMetadata> valid_words;
        copy_if(words.begin(), words.end(), back_inserter(valid_words),
            [](const WordMetadata& w) { return w.is_valid; });

        if (valid_words.empty()) {
            return "";
        }

        auto max_it = max_element(valid_words.begin(), valid_words.end(),
            [](const WordMetadata& a, const WordMetadata& b) {
                if (a.content.length() == b.content.length()) {
                    return a.position > b.position;
                }
                return a.content.length() < b.content.length();
            });

        return max_it->content;
    }

    void debugPrint() {
        for (const auto& word : words) {
            cout << "Word: " << word.content 
                 << ", Pos: " << word.position 
                 << ", Valid: " << word.is_valid 
                 << ", ASCII Sum: " << word.ascii_sum << endl;
        }
    }
};

int main() {
    try {
        string s;
        getline(cin, s);

        SentenceValidator::verifySentence(s);

        WordProcessor processor(s);
        processor.debugPrint();

        string longest = processor.findLongestWord();
        if (!longest.empty()) {
            cout << longest << endl;
        } else {
            cerr << "No valid words found" << endl;
        }

        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
}
