template<typename T>
struct DigitSumValidator {
    static_assert(is_integral<T>::value, "DigitSumValidator requires integral type");
    static bool validate(const T& value) {
        if (value < 0) throw invalid_argument("Negative values not allowed");
        if (value >= 10000) throw out_of_range("Value exceeds maximum allowed");
        return true;
    }
};

template<typename T>
T calculateDigitSum(T x) {
    DigitSumValidator<T>::validate(x);
    T s = 0;
    while (x != 0) {
        if (numeric_limits<T>::max() - s < x % 10) {
            throw overflow_error("Digit sum overflow detected");
        }
        s += x % 10;
        x /= 10;
    }
    return s;
}

struct AdvancedIntegerComparator {
    bool operator()(int a, int b) const {
        try {
            int sum_a = calculateDigitSum(a);
            int sum_b = calculateDigitSum(b);
            if (sum_a != sum_b) {
                return sum_a < sum_b;
            } else {
                return a < b;
            }
        } catch (const exception& e) {
            cerr << "Comparison error: " << e.what() << endl;
            return false;
        }
    }
};

void validateInputCount(int n) {
