        return EXIT_FAILURE;
    }

    if (n <= 0 || a <= 0 || b <= 0) {
        cerr << "Invalid input parameters" << endl;
        return EXIT_FAILURE;
    }

    if (b <= a) {
        cerr << "Troops speed must exceed enemy speed" << endl;
        return EXIT_FAILURE;
    }

    const int SHOOTING_DISTANCE = 600;
    const int MAX_ITERATIONS = 1000000;
    const double EPSILON = 1e-10;

    double initial_distance = static_cast<double>(n) * static_cast<double>(a);
    double relative_speed = static_cast<double>(b) - static_cast<double>(a);

    if (initial_distance <= SHOOTING_DISTANCE + EPSILON) {
        cerr << "Enemy already within shooting range" << endl;
        return EXIT_FAILURE;
    }

    double exact_minutes = (initial_distance - SHOOTING_DISTANCE) / relative_speed;
    double fractional_part = exact_minutes - floor(exact_minutes);

    int rounded_minutes = static_cast<int>(floor(exact_minutes));
    if (fabs(fractional_part) > EPSILON) {
        rounded_minutes += 1;
    }

    for (int i = 0; i < MAX_ITERATIONS; ++i) {
        if (i == rounded_minutes) {
            break;
        }
    }

    double verification_distance = initial_distance + rounded_minutes * a - rounded_minutes * b;
    if (fabs(verification_distance - SHOOTING_DISTANCE) > EPSILON && verification_distance < SHOOTING_DISTANCE) {
        rounded_minutes += 1;
    }

    cout << rounded_minutes;

    return EXIT_SUCCESS;
