class CharacterTransformer {
private:
    static char transformUpperCase(char c, int shift) {
        try {
            if (!isupper(c)) throw CharacterProcessingException();
            int base = 'A';
            int normalized = (c - base + shift) % 26;
            if (normalized < 0) normalized += 26;
            return static_cast<char>(base + normalized);
        } catch (...) {
            throw CharacterProcessingException();
        }
    }

    static char transformLowerCase(char c, int shift) {
        try {
            if (!islower(c)) throw CharacterProcessingException();
            int base = 'a';
            int normalized = (c - base + shift) % 26;
            if (normalized < 0) normalized += 26;
            return static_cast<char>(base + normalized);
        } catch (...) {
            throw CharacterProcessingException();
        }
    }

    static char transformDigit(char c, int shift) {
        try {
            if (!isdigit(c)) throw CharacterProcessingException();
            int base = '0';
            int normalized = (c - base + shift) % 10;
            if (normalized < 0) normalized += 10;
            return static_cast<char>(base + normalized);
        } catch (...) {
            throw CharacterProcessingException();
        }
    }

