        validation.outputCreatable = false;
    } else {
        close(fd);
    }
    validation.outputWritable = (access("shelf.out", W_OK) == 0);
    return validation;
}

void initializeIO() {
    FileValidation validation = validateFiles();
    if (!validation.inputExists || !validation.inputReadable) {
        cerr << "Input file error" << endl;
        exit(EXIT_FAILURE);
    }
    if (!validation.outputCreatable || !validation.outputWritable) {
        cerr << "Output file error" << endl;
        exit(EXIT_FAILURE);
    }
    freopen("shelf.in", "r", stdin);
    freopen("shelf.out", "w", stdout);
}

vector<int> readCowHeights(int N) {
    vector<int> heights;
    heights.reserve(N);
    for (int i = 0; i < N; ++i) {
        int height;
        if (!(cin >> height)) {
            cerr << "Invalid input format" << endl;
            exit(EXIT_FAILURE);
        }
        if (height <= 0) {
            cerr << "Invalid height value" << endl;
            exit(EXIT_FAILURE);
        }
        heights.push_back(height);
    }
    return heights;
}

int calculateMinTowerHeight(int N, int B, const vector<int>& heights) {
    int min_diff = INT_MAX;
    for (int mask = 1; mask < (1 << N); ++mask) {
        int current_sum = 0;
        for (int i = 0; i < N; ++i) {
            if (mask & (1 << i)) {
                current_sum += heights[i];
            }
        }
        if (current_sum >= B) {
            int current_diff = current_sum - B;
            if (current_diff < min_diff) {
                min_diff = current_diff;
                if (min_diff == 0) {
                    break;
                }
            }
        }
    }
    return min_diff;
}

int main() {
    initializeIO();
    int N, B;
    if (!(cin >> N >> B)) {
        cerr << "Invalid input format" << endl;
        exit(EXIT_FAILURE);
    }
    if (N <= 0 || N > 20) {
        cerr << "Invalid N value" << endl;
        exit(EXIT_FAILURE);
    }
    if (B <= 0) {
        cerr << "Invalid B value" << endl;
        exit(EXIT_FAILURE);
    }
    vector<int> heights = readCowHeights(N);
    int total_sum = accumulate(heights.begin(), heights.end(), 0);
    if (B > total_sum) {
        cerr << "B exceeds total height" << endl;
        exit(EXIT_FAILURE);
    }
    int result = calculateMinTowerHeight(N, B, heights);
    cout << result << endl;
    fclose(stdin);
    fclose(stdout);
    return 0;
}
