#include <bits/stdc++.h>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

const int MAX_STONES = 15;
const long long INF = numeric_limits<long long>::max();

struct Stone {
    long long anger;
    long long irritability;
    bool validated;
};

Stone stones[MAX_STONES];
long long global_min = INF;
int validated_stones = 0;

void validate_input(long long val, const string& type) {
    if (val < -numeric_limits<int>::max() || val > numeric_limits<int>::max()) {
        throw out_of_range("Input value out of range for " + type);
    }
}

void recursive_search(int current_index, long long product_anger, long long sum_irritability, bool at_least_one_selected, int depth, int max_depth) {
    if (depth > max_depth) {
        return;
    }

    if (current_index == validated_stones) {
        if (!at_least_one_selected) {
            return;
        }
        long long current_diff = abs(product_anger - sum_irritability);
        if (current_diff < global_min) {
            global_min = current_diff;
        }
        return;
    }

    if (product_anger > INF / stones[current_index].anger) {
        throw overflow_error("Anger product overflow detected");
    }

    if (sum_irritability > INF - stones[current_index].irritability) {
        throw overflow_error("Irritability sum overflow detected");
    }

    recursive_search(current_index + 1, 
                    product_anger * stones[current_index].anger, 
                    sum_irritability + stones[current_index].irritability, 
                    true, depth + 1, max_depth);

    recursive_search(current_index + 1, 
                    product_anger, 
                    sum_irritability, 
                    at_least_one_selected, depth + 1, max_depth);
}

void initialize_global_state() {
    global_min = INF;
    validated_stones = 0;
    for (int i = 0; i < MAX_STONES; ++i) {
        stones[i] = {0, 0, false};
    }
}

void process_input() {
    ifstream input_file("stone.in");
    ofstream output_file("stone.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        throw runtime_error("Failed to open input/output files");
    }

    int n;
    input_file >> n;

    if (n < 1 || n > 10) {
        throw invalid_argument("Number of stones out of valid range");
    }

    for (int i = 0; i < n; ++i) {
        long long anger, irritability;
        input_file >> anger >> irritability;

        validate_input(anger, "anger");
        validate_input(irritability, "irritability");

        stones[i] = {anger, irritability, true};
        validated_stones++;
    }

    try {
        recursive_search(0, 1, 0, false, 0, n * 2);
        output_file << global_min;
    } catch (const exception& e) {
        output_file << -1;
        cerr << "Error: " << e.what() << endl;
    }

    input_file.close();
    output_file.close();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    try {
        initialize_global_state();
        process_input();
    } catch (const exception& e) {
        ofstream output_file("stone.out");
        output_file << -1;
        cerr << "Fatal error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
