class CircularShiftCalculator {
private:
    int shiftAmount;
public:
    explicit CircularShiftCalculator(int z) : shiftAmount(z) {
        if (z <= 0) {
            throw invalid_argument("Shift amount must be positive");
        }
    }

    char calculateShiftedChar(char original) {
        char result = original;
