            int normalizedShift = shiftAmount % 26;
            int currentPos = original - 'A';
            int newPos = (currentPos + normalizedShift) % 26;
            result = static_cast<char>('A' + newPos);
        } else if (CharacterValidation::isLowerCase(original)) {
            int normalizedShift = shiftAmount % 26;
            int currentPos = original - 'a';
            int newPos = (currentPos + normalizedShift) % 26;
            result = static_cast<char>('a' + newPos);
        } else if (CharacterValidation::isDigit(original)) {
            int normalizedShift = shiftAmount % 10;
            int currentPos = original - '0';
            int newPos = (currentPos + normalizedShift) % 10;
            result = static_cast<char>('0' + newPos);
        }
        return result;
