    if (!is_within_bounds(a, static_cast<T>(1), static_cast<T>(1000))) throw std::out_of_range("a out of range");
    if (!is_within_bounds(b, static_cast<T>(1), static_cast<T>(1000))) throw std::out_of_range("b out of range");
    if (b <= a) throw std::logic_error("b must be greater than a");
}

template<typename T>
T calculate_relative_distance(T n, T a) {
