using namespace std;

struct CharacterValidator {
    static bool validateCharType(char c) {
        return (isupper(c) || (islower(c)) || (isdigit(c));
    }
};

class PositionCalculator {
public:
    static int calculateEffectiveShift(int originalPos, int shiftAmount, int moduloBase) {
        if (moduloBase <= 0) throw runtime_error("Modulo base must be positive");
        int effectiveShift = shiftAmount % moduloBase;
        if (effectiveShift < 0) effectiveShift += moduloBase;
        return (originalPos + effectiveShift) % moduloBase;
    }
};

class CharacterTransformer {
private:
    static char transformUpperCase(char c, int shift) {
        if (!isupper(c)) throw runtime_error("Invalid uppercase character");
        return PositionCalculator::calculateEffectiveShift(c - 'A', shift, 26) + 'A';
    }

    static char transformLowerCase(char c, int shift) {
        if (!islower(c)) throw runtime_error("Invalid lowercase character");
        return PositionCalculator::calculateEffectiveShift(c - 'a', shift, 26) + 'a';
    }

    static char transformDigit(char c, int shift) {
        if (!isdigit(c)) throw runtime_error("Invalid digit");
        return PositionCalculator::calculateEffectiveShift(c - '0', shift, 10) + '0';
    }

public:
    static char transformCharacter(char c, int shift) {
        if (!CharacterValidator::validateCharType(c)) return c;
        if (isupper(c)) return transformUpperCase(c, shift);
        if (islower(c)) return transformLowerCase(c, shift);
        if (isdigit(c)) return transformDigit(c, shift);
        return c;
