    vector<bool> black_rows;
    vector<bool> black_diag1;
    vector<bool> black_diag2;
    int size;
};

class QueenSolver {
private:
    int total_solutions;
    ChessboardState state;

    void initializeState(int n) {
        state.size = n;
        state.board.resize(n+2, vector<int>(n+2, 0));
        state.white_rows.resize(n+2, false);
        state.white_diag1.resize(2*n+2, false);
        state.white_diag2.resize(2*n+2, false);
        state.black_rows.resize(n+2, false);
        state.black_diag1.resize(2*n+2, false);
        state.black_diag2.resize(2*n+2, false);
    }

    bool validatePosition(int color, int row, int col) {
        if (color == 0) {
            return !state.white_rows[row] && 
                   !state.white_diag1[row+col] && 
                   !state.white_diag2[col-row+state.size] &&
                   state.board[row][col] == 1;
        } else {
            return !state.black_rows[row] && 
                   !state.black_diag1[row+col] && 
                   !state.black_diag2[col-row+state.size] &&
                   state.board[row][col] == 1;
        }
    }

    void updatePosition(int color, int row, int col, bool value) {
        if (color == 0) {
            state.white_rows[row] = value;
            state.white_diag1[row+col] = value;
            state.white_diag2[col-row+state.size] = value;
        } else {
            state.black_rows[row] = value;
            state.black_diag1[row+col] = value;
            state.black_diag2[col-row+state.size] = value;
        }
        state.board[row][col] = value ? 0 : 1;
    }

    void recursiveSolver(int current_col, int current_color) {
        if (current_col == state.size) {
            if (current_color == 0) {
                recursiveSolver(0, 1);
            } else {
                total_solutions++;
            }
            return;
        }

        for (int row_idx = 1; row_idx <= state.size; row_idx++) {
            if (validatePosition(current_color, row_idx, current_col)) {
                updatePosition(current_color, row_idx, current_col, true);
                recursiveSolver(current_col + 1, current_color);
                updatePosition(current_color, row_idx, current_col, false);
            }
        }
    }

