#include <iostream>
#include <algorithm>
#include <vector>
#include <stdexcept>
#include <limits>

using namespace std;

struct NumberWithSum {
    int original;
    int sum;
    bool operator<(const NumberWithSum& other) const {
        if (sum != other.sum) {
            return sum < other.sum;
        }
        return original < other.original;
    }
};

int calculateDigitSum(int x) {
    if (x < 0) {
        throw invalid_argument("Negative numbers not allowed");
    }
    int s = 0;
    int temp = x;
    while (temp != 0) {
        s += temp % 10;
        temp /= 10;
        if (s > numeric_limits<int>::max() - 100) {
            throw overflow_error("Sum overflow detected");
        }
    }
    return s;
}

void validateInputSize(int n) {
    if (n <= 0 || n >= 101) {
        throw out_of_range("Invalid input size");
    }
}

void validateNumber(int num) {
    if (num <= 0 || num >= 10000) {
        throw out_of_range("Number out of valid range");
    }
}

vector<NumberWithSum> processNumbers(const int* arr, int size) {
    vector<NumberWithSum> processed;
    for (int i = 0; i < size; ++i) {
        validateNumber(arr[i]);
        NumberWithSum ns;
        ns.original = arr[i];
        ns.sum = calculateDigitSum(arr[i]);
        processed.push_back(ns);
    }
    return processed;
}

void printSortedNumbers(const vector<NumberWithSum>& vec) {
    for (size_t i = 0; i < vec.size(); ++i) {
        if (i != 0) {
            cout << " ";
        }
        cout << vec[i].original;
    }
}

int main() {
    try {
        int n;
        cin >> n;
        validateInputSize(n);
        int a[102];
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }
        vector<NumberWithSum> processed = processNumbers(a, n);
        sort(processed.begin(), processed.end());
        printSortedNumbers(processed);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
