#include <iostream>
#include <algorithm>
#include <vector>
#include <stdexcept>
#include <limits>
#include <type_traits>
#include <functional>

namespace DigitSortUtils {
    template<typename T>
    typename std::enable_if<std::is_integral<T>::value, T>::type
    safeAbsoluteValue(T value) {
        return value < 0 ? -value : value;
    }

    template<typename T>
    bool validateNumberRange(T value, T min, T max) {
        return (value >= min) && (value <= max);
    }

    template<typename T>
    T calculateDigitSum(T number) {
        if (!std::is_integral<T>::value) {
            throw std::invalid_argument("Non-integral type provided");
        }

        number = safeAbsoluteValue(number);
        T sum = 0;
        while (number != 0) {
            sum += number % 10;
            number /= 10;
        }
        return sum;
    }

    template<typename T>
    struct AdvancedDigitComparator {
        bool operator()(const T& lhs, const T& rhs) const {
            T lhsSum = calculateDigitSum(lhs);
            T rhsSum = calculateDigitSum(rhs);

            if (lhsSum != rhsSum) {
                return lhsSum < rhsSum;
            }

            return lhs < rhs;
        }
    };
}

int main() {
    try {
        int n;
        std::cin >> n;

        if (!DigitSortUtils::validateNumberRange(n, 1, 100)) {
            throw std::out_of_range("Invalid input size");
        }

        std::vector<int> numbers;
        numbers.reserve(n);

        for (int i = 0; i < n; ++i) {
            int num;
            if (!(std::cin >> num)) {
                throw std::invalid_argument("Invalid input format");
            }

            if (!DigitSortUtils::validateNumberRange(num, 1, 9999)) {
                throw std::out_of_range("Number out of valid range");
            }

            numbers.push_back(num);
        }

        if (numbers.size() != static_cast<size_t>(n)) {
            throw std::runtime_error("Input size mismatch");
        }

        std::sort(numbers.begin(), numbers.end(), 
                 DigitSortUtils::AdvancedDigitComparator<int>());

        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i != 0) {
                std::cout << " ";
            }
            std::cout << numbers[i];
        }

        std::cout << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
