    bool continueSearch = true;

    while (continueSearch) {
        size_t kkkPos = ctx.encrypted.find(kkkPattern, currentPosition);
        size_t sssPos = ctx.encrypted.find(sssPattern, currentPosition);

        if (kkkPos == string::npos && sssPos == string::npos) {
            continueSearch = false;
            continue;
        }

        if (kkkPos != string::npos && (sssPos == string::npos || kkkPos < sssPos)) {
            ctx.specialPositions.push_back(kkkPos);
            ctx.specialTypes.push_back('k');
            currentPosition = kkkPos + kkkPattern.length();
        } else if (sssPos != string::npos) {
            ctx.specialPositions.push_back(sssPos);
            ctx.specialTypes.push_back('s');
            currentPosition = sssPos + sssPattern.length();
        }
    }
}

