    {"sss", "."}
};

const unordered_map<char, char> CIRCULAR_SHIFT_MAP = {
    {'a', 'x'}, {'b', 'y'}, {'c', 'z'}, {'d', '0'}, {'e', '1'}, {'f', '2'},
    {'g', '3'}, {'h', '4'}, {'i', '5'}, {'j', '6'}, {'k', '7'}, {'l', '8'},
    {'m', '9'}, {'n', 'a'}, {'o', 'b'}, {'p', 'c'}, {'q', 'd'}, {'r', 'e'},
    {'s', 'f'}, {'t', 'g'}, {'u', 'h'}, {'v', 'i'}, {'w', 'j'}, {'x', 'k'},
    {'y', 'l'}, {'z', 'm'}, {'0', '3'}, {'1', '4'}, {'2', '5'}, {'3', '6'},
    {'4', '7'}, {'5', '8'}, {'6', '9'}, {'7', 'a'}, {'8', 'b'}, {'9', 'c'}
};

string perform_circular_shift_decryption(const string& input) {
    string result;
    for (char c : input) {
        if (CIRCULAR_SHIFT_MAP.count(c)) {
            result += CIRCULAR_SHIFT_MAP.at(c);
        } else {
            throw runtime_error("Invalid character encountered during circular shift decryption");
        }
    }
    return result;
}

string handle_special_sequences(string s) {
    for (const auto& replacement : SPECIAL_REPLACEMENTS) {
        size_t pos = 0;
        while ((pos = s.find(replacement.first, pos)) != string::npos) {
            if (pos + replacement.first.length() > s.length()) {
                throw runtime_error("Invalid position during special sequence replacement");
            }
            s.replace(pos, replacement.first.length(), replacement.second);
            pos += replacement.second.length();
            if (pos > s.length()) {
                throw runtime_error("Position overflow during replacement");
            }
        }
    }
    return s;
}

