    for (size_t i = 0; i < input.length(); ) {
        if (i + 2 < input.length() && input[i] == input[i+1] && input[i] == input[i+2]) {
            string triple = input.substr(i, 3);
            if (triple != "kkk" && triple != "sss") {
                throw runtime_error("Invalid triple character sequence encountered");
            }
            i += 3;
        } else {
            if (!islower(input[i]) && !isdigit(input[i])) {
                throw runtime_error("Invalid character in input");
            }
            i++;
        }
    }
    return input;
}

string decrypt_message(const string& encrypted) {
    string temp = encrypted;
    temp = handle_special_sequences(temp);
    temp = perform_circular_shift_decryption(temp);
    return temp;
}

