class InputValidator {
public:
    static bool validateInteger(const std::string& str) {
        if (str.empty()) return false;
        size_t pos = 0;
        if (str[0] == '-' || str[0] == '+') pos = 1;
        for (; pos < str.size(); ++pos) {
            if (!isdigit(str[pos])) return false;
        }
        try {
            std::stoll(str);
        } catch (...) {
            return false;
        }
        return true;
    }

    static void ensureWithinRange(long long num) {
        if (num < std::numeric_limits<int>::min() || num > std::numeric_limits<int>::max()) {
            throw std::out_of_range("Integer out of range");
        }
    }
};

class OutputFormatter {
public:
    static std::string formatNumber(int num) {
        std::ostringstream oss;
        oss << std::setw(8) << num;
        return oss.str();
    }

    static void validateOutputWidth(const std::string& str) {
        if (str.length() != 8) {
            throw std::runtime_error("Formatting error: incorrect width");
        }
    }
};

class IntegerProcessor {
private:
    std::vector<int> integers;

    void parseInput(const std::string& input) {
        std::istringstream iss(input);
        std::string token;
        int count = 0;
        while (iss >> token && count < 3) {
            if (!InputValidator::validateInteger(token)) {
                throw std::invalid_argument("Invalid integer input");
            }
            long long num = std::stoll(token);
            InputValidator::ensureWithinRange(num);
            integers.push_back(static_cast<int>(num));
            count++;
        }
        if (integers.size() != 3) {
            throw std::invalid_argument("Exactly three integers required");
        }
    }

public:
    explicit IntegerProcessor(const std::string& input) {
        parseInput(input);
    }

    std::string getFormattedOutput() {
        std::string formatted;
        for (size_t i = 0; i < integers.size(); ++i) {
            std::string numStr = OutputFormatter::formatNumber(integers[i]);
            OutputFormatter::validateOutputWidth(numStr);
            formatted += numStr;
            if (i != integers.size() - 1) {
                formatted += " ";
            }
        }
        return formatted;
    }
};

int main() {
    std::string inputLine;
    try {
        std::getline(std::cin, inputLine);
        IntegerProcessor processor(inputLine);
        std::string output = processor.getFormattedOutput();
        std::cout << output << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
