using namespace std;

struct NumberMetadata {
    int original_value;
    int digit_sum;
    bool is_valid;
};

vector<NumberMetadata> preprocess_numbers(const vector<int>& numbers) {
    vector<NumberMetadata> processed;
    for (size_t i = 0; i < numbers.size(); ++i) {
        if (numbers[i] < 0 || numbers[i] >= 10000) {
            throw invalid_argument("Invalid number detected in input");
        }

        NumberMetadata meta;
        meta.original_value = numbers[i];
        meta.is_valid = true;

        int temp = numbers[i];
        int sum = 0;
        while (temp != 0) {
            int digit = temp % 10;
            if (digit < 0 || digit > 9) {
                meta.is_valid = false;
                break;
            }
            sum += digit;
            temp /= 10;
        }

        meta.digit_sum = sum;
        processed.push_back(meta);
    }
    return processed;
}

bool compare_metadata(const NumberMetadata& a, const NumberMetadata& b) {
    if (!a.is_valid || !b.is_valid) {
        throw runtime_error("Attempting to compare invalid numbers");
    }

    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    }

    return a.original_value < b.original_value;
}

vector<int> get_sorted_numbers(const vector<NumberMetadata>& processed) {
    vector<NumberMetadata> sorted_meta = processed;
    sort(sorted_meta.begin(), sorted_meta.end(), compare_metadata);

    vector<int> result;
    for (size_t i = 0; i < sorted_meta.size(); ++i) {
        if (!sorted_meta[i].is_valid) {
            continue;
        }
        result.push_back(sorted_meta[i].original_value);
    }

    return result;
}

void validate_input_count(int n) {
    if (n <= 0 || n >= 101) {
        throw out_of_range("Invalid input count");
    }
}

vector<int> read_input_numbers(int n) {
    vector<int> numbers;
    for (int i = 0; i < n; ++i) {
        int num;
        if (!(cin >> num)) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            throw runtime_error("Invalid input format");
        }
        numbers.push_back(num);
    }
    return numbers;
}

void print_numbers(const vector<int>& numbers) {
    for (size_t i = 0; i < numbers.size(); ++i) {
        if (i != 0) {
            cout << " ";
        }
        cout << numbers[i];
    }
    cout << endl;
}

int main() {
    try {
        int n;
        if (!(cin >> n)) {
            throw runtime_error("Failed to read input count");
        }

        validate_input_count(n);
        vector<int> input_numbers = read_input_numbers(n);
        vector<NumberMetadata> processed = preprocess_numbers(input_numbers);
        vector<int> sorted_numbers = get_sorted_numbers(processed);
        print_numbers(sorted_numbers);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
