#include<iostream>
#include<algorithm>
#include<vector>
#include<stdexcept>
#include<limits>
#include<cmath>
#include<type_traits>
using namespace std;

template<typename T>
struct DigitSumValidator {
    static_assert(is_integral<T>::value, "DigitSumValidator requires integral type");

    static bool validate(const T& value) {
        return value >= 0 && value < 10000;
    }

    static int calculate(const T& value) {
        if (!validate(value)) {
            throw out_of_range("Value out of valid range for digit sum calculation");
        }

        T temp = abs(value);
        int sum = 0;
        const int base = 10;
        const int max_iterations = 100;
        int iterations = 0;

        while (temp != 0 && iterations < max_iterations) {
            sum += temp % base;
            temp /= base;
            iterations++;

            if (iterations >= max_iterations) {
                throw runtime_error("Digit sum calculation exceeded maximum iterations");
            }
        }

        if (temp != 0) {
            throw runtime_error("Digit sum calculation did not converge");
        }

        return sum;
    }
};

struct SortingComparator {
    template<typename T>
    bool operator()(const T& a, const T& b) const {
        try {
            int sum_a = DigitSumValidator<T>::calculate(a);
            int sum_b = DigitSumValidator<T>::calculate(b);

            if (sum_a != sum_b) {
                return sum_a < sum_b;
            }

            return a < b;
        } catch (const exception& e) {
            cerr << "Error during comparison: " << e.what() << endl;
            return false;
        }
    }
};

struct InputValidator {
    static bool validateSize(int n) {
        return n > 0 && n < 101;
    }

    static bool validateElement(int x) {
        return x > 0 && x < 10000;
    }
};

int main() {
    int n;
    vector<int> a;

    try {
        if (!(cin >> n)) {
            throw runtime_error("Invalid input for N");
        }

        if (!InputValidator::validateSize(n)) {
            throw out_of_range("N is out of valid range");
        }

        a.resize(n);

        for (int i = 0; i < n; ++i) {
            if (!(cin >> a[i])) {
                throw runtime_error("Invalid input for array element");
            }

            if (!InputValidator::validateElement(a[i])) {
                throw out_of_range("Array element out of valid range");
            }
        }

        sort(a.begin(), a.end(), SortingComparator());

        for (size_t i = 0; i < a.size(); ++i) {
            if (i != 0) {
                cout << " ";
            }
            cout << a[i];
        }

        cout << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
