#include <iostream>
#include <algorithm>
#include <vector>
#include <stdexcept>
#include <limits>
#include <type_traits>
#include <sstream>
#include <iterator>

using namespace std;

namespace DigitSumUtility {
    template<typename T>
    typename enable_if<is_integral<T>::value, T>::type
    calculateDigitSum(T value) {
        if (value < 0) {
            throw invalid_argument("Negative values not supported");
        }
        T sum = 0;
        while (value != 0) {
            T digit = value % 10;
            if (digit > 9 || digit < 0) {
                throw runtime_error("Invalid digit encountered");
            }
            sum += digit;
            value /= 10;
            if (sum > numeric_limits<T>::max() - 100) {
                throw overflow_error("Digit sum overflow detected");
            }
        }
        return sum;
    }

    template<typename T>
    bool validateInputRange(T value, T min, T max) {
        return (value >= min) && (value <= max);
    }
}

struct AdvancedIntegerComparator {
    bool operator()(int a, int b) const {
        try {
            int suma = DigitSumUtility::calculateDigitSum(a);
            int sumb = DigitSumUtility::calculateDigitSum(b);

            if (!DigitSumUtility::validateInputRange(suma, 0, 10000) || 
                !DigitSumUtility::validateInputRange(sumb, 0, 10000)) {
                throw range_error("Digit sum out of expected range");
            }

            if (suma != sumb) {
                return suma < sumb;
            } else {
                if (!DigitSumUtility::validateInputRange(a, 0, 10000) || 
                    !DigitSumUtility::validateInputRange(b, 0, 10000)) {
                    throw range_error("Input value out of expected range");
                }
                return a < b;
            }
        } catch (const exception& e) {
            cerr << "Comparator error: " << e.what() << endl;
            return false;
        }
    }
};

template<typename Container>
void safeInputRead(Container& container, istream& is) {
    string line;
    while (getline(is, line)) {
        istringstream iss(line);
        typename Container::value_type value;
        while (iss >> value) {
            if (!DigitSumUtility::validateInputRange(value, 
                numeric_limits<typename Container::value_type>::min(), 
                numeric_limits<typename Container::value_type>::max())) {
                throw range_error("Input value out of range");
            }
            container.push_back(value);
        }
        if (!iss.eof()) {
            throw runtime_error("Invalid input format");
        }
        break;
    }
}

void processAndSortIntegers() {
    vector<int> numbers;
    int n = 0;

    try {
        cin >> n;
        if (!DigitSumUtility::validateInputRange(n, 1, 100)) {
            throw range_error("Invalid N value");
        }

        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        safeInputRead(numbers, cin);

        if (numbers.size() != static_cast<size_t>(n)) {
            throw length_error("Input size mismatch");
        }

        sort(numbers.begin(), numbers.end(), AdvancedIntegerComparator());

        for (auto it = numbers.begin(); it != numbers.end(); ++it) {
            if (!DigitSumUtility::validateInputRange(*it, 0, 10000)) {
                throw range_error("Output value out of range");
            }
            cout << *it;
            if (next(it) != numbers.end()) {
                cout << " ";
            }
        }
    } catch (const exception& e) {
        cerr << "Processing error: " << e.what() << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    try {
        processAndSortIntegers();
    } catch (...) {
        cerr << "Unexpected error occurred" << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

