#include<bits/stdc++.h>
using namespace std;

struct TreeNode {
    int id;
    vector<int> children;
    int parent;
    int degree;
};

bool validateInput(int x, int y, int n) {
    if (x <= 0 || x >= n || y <= 0 || y >= n) {
        return false;
    }
    if (x == y) {
        return false;
    }
    return true;
}

void calculateDegrees(vector<TreeNode>& nodes) {
    for (int i = 0; i < nodes.size(); ++i) {
        nodes[i].degree = nodes[i].children.size();
        if (nodes[i].parent != -1) {
            nodes[i].degree += 1;
        }
    }
}

bool isPNode(const vector<TreeNode>& nodes, int nodeIdx) {
    if (nodes[nodeIdx].parent == -1 && nodes[nodeIdx].children.empty()) {
        return true;
    }

    int currentDegree = nodes[nodeIdx].degree;
    bool valid = true;

    if (nodes[nodeIdx].parent != -1) {
        int parentDegree = nodes[nodes[nodeIdx].parent].degree;
        if (currentDegree < parentDegree) {
            valid = false;
        }
    }

    for (int child : nodes[nodeIdx].children) {
        int childDegree = nodes[child].degree;
        if (currentDegree < childDegree) {
            valid = false;
            break;
        }
    }

    return valid;
}

int main() {
    freopen("p.in", "r", stdin);
    freopen("p.out", "w", stdout);

    int t;
    cin >> t;
    if (t < 1 || t > 100) {
        cerr << "Invalid number of test cases" << endl;
        return 1;
    }

    while (t--) {
        int n;
        cin >> n;
        if (n < 1 || n > 1000) {
            cerr << "Invalid number of nodes" << endl;
            continue;
        }

        vector<TreeNode> nodes(n);
        for (int i = 0; i < n; ++i) {
            nodes[i].id = i;
            nodes[i].parent = -1;
        }

        bool inputValid = true;
        for (int i = 0; i < n - 1; ++i) {
            int x, y;
            cin >> x >> y;
            if (!validateInput(x, y, n)) {
                inputValid = false;
                break;
            }
            nodes[x].children.push_back(y);
            nodes[y].parent = x;
        }

        if (!inputValid) {
            cerr << "Invalid input data" << endl;
            continue;
        }

        calculateDegrees(nodes);

        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if (isPNode(nodes, i)) {
                ans++;
            }
        }

        cout << ans << endl;
    }

    return 0;
}
