constexpr long long MAXN = 2e5 + 7;
constexpr long long OFFSET = 1e5 + 3;
constexpr long long INF = numeric_limits<long long>::max();

struct HeightValidator {
    static bool validateHeight(int h) {
        return h == 0 || h == 1;
    }
};

template<typename T>
class SafeArray {
private:
    T* data;
    size_t size;
public:
    SafeArray(size_t n) : size(n) {
        data = new T[n + 2]();
    }
    ~SafeArray() {
        delete[] data;
    }
    T& operator[](size_t idx) {
        if (idx >= size) {
            throw out_of_range("Index out of bounds");
        }
        return data[idx];
    }
};

class PerfectMatchSolver {
private:
    long long n;
    SafeArray<long long> a;
    SafeArray<long long> sum;
    unordered_map<long long, long long> vis;
    long long ans;
public:
    PerfectMatchSolver(long long _n) : n(_n), a(_n + 2), sum(_n + 2), ans(0) {
        if (n <= 0 || n > MAXN) {
            throw invalid_argument("Invalid input size");
        }
    }

    void readInput() {
        for (long long i = 1; i <= n; ++i) {
            long long val;
            if (!(cin >> val)) {
                throw runtime_error("Failed to read input");
            }
            if (!HeightValidator::validateHeight(val)) {
                throw invalid_argument("Invalid gender value");
            }
            a[i] = (val == 0) ? -1 : 1;
        }
    }

    void precomputeSums() {
        sum[0] = 0;
        for (long long i = 1; i <= n; ++i) {
            sum[i] = sum[i - 1] + a[i];
        }
    }

    void solve() {
        vis.reserve(2 * MAXN);
        vis[0 + OFFSET] = 0;

        for (long long i = 1; i <= n; ++i) {
            long long current = sum[i];
            auto it = vis.find(current + OFFSET);
            if (it != vis.end() || current == 0) {
                long long prev_index = (current == 0) ? 0 : it->second;
                ans = max(ans, abs(prev_index - i));
            } else {
                vis[current + OFFSET] = i;
            }
        }
    }

    long long getResult() const {
        return ans;
    }
};

int main() {
    try {
        freopen("match.in", "r", stdin);
        freopen("match.out", "w", stdout);

        long long n;
        if (!(cin >> n)) {
            throw runtime_error("Failed to read n");
        }

        PerfectMatchSolver solver(n);
        solver.readInput();
        solver.precomputeSums();
        solver.solve();

