using namespace std;

namespace DigitSumSorter {
    class InputValidator {
    public:
        static bool validateIntegerCount(int count) {
            return count > 0 && count < 101;
        }

        static bool validateNumber(const string& numStr) {
            if (numStr.empty()) return false;
            for (char c : numStr) {
                if (!isdigit(c)) return false;
            }
            long num = stol(numStr);
            return num > 0 && num < 10000;
        }
    };

    class DigitSumCalculator {
    private:
        static int calculateSingleDigitSum(int x) {
            if (x < 0) x = -x;
            int s = 0;
            while (x != 0) {
                s += x % 10;
                x /= 10;
                if (s > INT_MAX / 10) {
                    throw overflow_error("Digit sum overflow");
                }
            }
            return s;
        }

    public:
        static int calculateDigitSum(const string& numStr) {
            if (!InputValidator::validateNumber(numStr)) {
                throw invalid_argument("Invalid number string");
            }
            int num = stoi(numStr);
            return calculateSingleDigitSum(num);
        }
    };

    class Comparator {
    public:
        bool operator()(const string& a, const string& b) {
            int sumA = DigitSumCalculator::calculateDigitSum(a);
            int sumB = DigitSumCalculator::calculateDigitSum(b);
            if (sumA != sumB) {
                return sumA < sumB;
            }
            int numA = stoi(a);
            int numB = stoi(b);
            return numA < numB;
        }
    };

    class InputProcessor {
    public:
        static vector<string> processInput() {
            string line;
            int N;
            while (true) {
                getline(cin, line);
                try {
                    N = stoi(line);
                    if (!InputValidator::validateIntegerCount(N)) {
                        throw out_of_range("Invalid N");
                    }
                    break;
                } catch (...) {
                    cerr << "Invalid input. Please enter a valid integer N (0 < N < 101): ";
                }
            }

            vector<string> numbers;
            while (numbers.size() < N) {
                getline(cin, line);
                istringstream iss(line);
                string num;
                while (iss >> num && numbers.size() < N) {
                    if (!InputValidator::validateNumber(num)) {
                        cerr << "Invalid number detected: " << num << ". Skipping." << endl;
                        continue;
                    }
                    numbers.push_back(num);
                }
                if (numbers.size() < N) {
                    cerr << "Insufficient numbers. Please enter " << N - numbers.size() << " more valid numbers: ";
                }
            }
            return numbers;
        }
    };
}

int main() {
    try {
        vector<string> numbers = DigitSumSorter::InputProcessor::processInput();
        sort(numbers.begin(), numbers.end(), DigitSumSorter::Comparator());
        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i != 0) cout << " ";
