#include <bits/stdc++.h>
#include <fstream>
#include <stdexcept>
#include <limits>
using namespace std;

struct ElevatorConfiguration {
    const long long RISE_TIME = 5;
    const long long DESCEND_TIME = 4;
    const long long DOOR_OPEN_TIME = 3;
    const long long PERSON_EXIT_TIME = 2;
    const long long STARTING_FLOOR = 0;
};

class ElevatorTimeCalculator {
private:
    vector<long long> destinations;
    long long personCount;
    ElevatorConfiguration config;

    void validateInput() {
        if (personCount < 1 || personCount > 100000) {
            throw invalid_argument("Invalid person count");
        }
        for (const auto& floor : destinations) {
            if (floor < 1 || floor > numeric_limits<long long>::max()) {
                throw invalid_argument("Invalid floor number");
            }
        }
    }

    long long calculateMaxFloor() {
        if (destinations.empty()) return 0;
        return *max_element(destinations.begin(), destinations.end());
    }

public:
    ElevatorTimeCalculator(long long n, const vector<long long>& floors) 
        : personCount(n), destinations(floors) {
        sort(destinations.begin(), destinations.end());
    }

    long long computeTotalTime() {
        validateInput();
        const long long maxFloor = calculateMaxFloor();
        long long totalTime = 0;
        long long currentFloor = config.STARTING_FLOOR;
        size_t personIndex = 0;

        while (currentFloor < maxFloor) {
            currentFloor++;
            totalTime += config.RISE_TIME;

            bool shouldOpenDoor = false;
            while (personIndex < destinations.size() && 
                   destinations[personIndex] == currentFloor) {
                shouldOpenDoor = true;
                personIndex++;
            }

            if (shouldOpenDoor) {
                totalTime += config.DOOR_OPEN_TIME;
                long long peopleExiting = 0;
                for (size_t i = 0; i < personIndex; ++i) {
                    if (destinations[i] == currentFloor) {
                        peopleExiting++;
                    }
                }
                totalTime += peopleExiting * config.PERSON_EXIT_TIME;
            }
        }

        while (currentFloor > config.STARTING_FLOOR) {
            currentFloor--;
            totalTime += config.DESCEND_TIME;
        }

        return totalTime;
    }
};

int main() {
    ifstream inputFile("elevator.in");
    ofstream outputFile("elevator.out");

