struct NumberWithMetadata {
    int originalValue;
    int digitSum;
    bool isValid;
};

vector<NumberWithMetadata> processInputArray(const int* arr, int size) {
    vector<NumberWithMetadata> processedNumbers;
    for (int i = 0; i < size; ++i) {
        NumberWithMetadata current;
        current.originalValue = arr[i];
        current.isValid = true;

        if (current.originalValue <= 0 || current.originalValue >= 10000) {
            current.isValid = false;
            processedNumbers.push_back(current);
            continue;
        }

        int temp = current.originalValue;
        int sum = 0;
        while (temp != 0) {
            int digit = temp % 10;
            if (digit < 0 || digit > 9) {
                current.isValid = false;
                break;
            }
            sum += digit;
            temp /= 10;
        }

        current.digitSum = sum;
        processedNumbers.push_back(current);
    }
    return processedNumbers;
}

bool validateProcessedNumbers(const vector<NumberWithMetadata>& numbers) {
    for (const auto& num : numbers) {
        if (!num.isValid) {
            return false;
        }
    }
    return true;
}

bool compareNumbers(const NumberWithMetadata& a, const NumberWithMetadata& b) {
    if (!a.isValid || !b.isValid) {
        throw runtime_error("Invalid number encountered during comparison");
    }

    if (a.digitSum != b.digitSum) {
        return a.digitSum < b.digitSum;
    } else {
        return a.originalValue < b.originalValue;
    }
}

void sortWithMetadata(vector<NumberWithMetadata>& numbers) {
    try {
        sort(numbers.begin(), numbers.end(), compareNumbers);
    } catch (const exception& e) {
        cerr << "Sorting failed: " << e.what() << endl;
        throw;
    }
}

vector<int> extractSortedValues(const vector<NumberWithMetadata>& numbers) {
