using namespace std;

template<typename T>
constexpr bool is_integer_type = is_integral<T>::value && !is_same<T, bool>::value;

template<typename T>
enable_if_t<is_integer_type<T>, T> safe_abs(T x) {
    static_assert(is_integer_type<T>, "Type must be integral and not bool");
    return x < 0 ? -x : x;
}

template<typename T>
enable_if_t<is_integer_type<T>, int> digit_sum(T x) noexcept {
    if (numeric_limits<T>::is_signed && x == numeric_limits<T>::min()) {
        x = numeric_limits<T>::max();
    }
    x = safe_abs(x);
    int s = 0;
    while (x != 0) {
        if (s > numeric_limits<int>::max() - (x % 10)) {
            s = numeric_limits<int>::max();
            break;
        }
        s += x % 10;
        if (x < 0) {
            x = -x;
        }
        x /= 10;
    }
    return s;
}

template<typename Container>
void validate_input_container(const Container& c) {
    if (c.empty()) {
        throw invalid_argument("Container must not be empty");
    }
    for (const auto& elem : c) {
        if (!is_integer_type<decltype(elem)>) {
            throw invalid_argument("All elements must be integers");
        }
        if (elem < 0) {
            throw invalid_argument("All elements must be positive");
        }
        if (elem >= 10000) {
            throw invalid_argument("All elements must be less than 10000");
        }
    }
}

template<typename T>
struct DigitSumComparator {
    bool operator()(T a, T b) const {
        static_assert(is_integer_type<T>, "Type must be integral and not bool");
        int sum_a = digit_sum(a);
        int sum_b = digit_sum(b);
        if (sum_a != sum_b) {
            return sum_a < sum_b;
        } else {
            return a < b;
        }
    }
};

template<typename InputIt, typename OutputIt>
void advanced_sort(InputIt first, InputIt last, OutputIt d_first) {
    using value_type = typename iterator_traits<InputIt>::value_type;
    static_assert(is_integer_type<value_type>, "Iterator value type must be integral and not bool");

    vector<value_type> temp_container(first, last);
    validate_input_container(temp_container);

    sort(temp_container.begin(), temp_container.end(), DigitSumComparator<value_type>());

    for (const auto& elem : temp_container) {
        *d_first++ = elem;
    }
}

