const long long TIME_EXIT = 2;

struct ElevatorState {
    long long current_floor;
    long long time_elapsed;
    bool door_open;
};

void validate_input(long long n, const vector<long long>& floors) {
    if (n < 1 || n > MAX_PEOPLE) {
        throw runtime_error("Invalid number of people");
    }
    for (long long floor : floors) {
        if (floor < 1 || floor > MAX_FLOOR) {
            throw runtime_error("Invalid floor number");
        }
    }
}

void handle_elevator_movement(ElevatorState& state, long long target_floor, bool going_up) {
    long long floor_diff = abs(target_floor - state.current_floor);
    if (going_up) {
        state.time_elapsed += floor_diff * TIME_UP;
    } else {
        state.time_elapsed += floor_diff * TIME_DOWN;
    }
    state.current_floor = target_floor;
}

void handle_door_operations(ElevatorState& state, long long people_exiting) {
    if (!state.door_open) {
        state.time_elapsed += TIME_OPEN;
        state.door_open = true;
    }
    state.time_elapsed += people_exiting * TIME_EXIT;
}

void process_floors(ElevatorState& state, const vector<long long>& floors) {
    vector<long long> sorted_floors = floors;
    sort(sorted_floors.begin(), sorted_floors.end());

    long long prev_floor = -1;
    long long people_on_current_floor = 0;

    for (size_t i = 0; i < sorted_floors.size(); ++i) {
        if (sorted_floors[i] != prev_floor) {
            if (people_on_current_floor > 0) {
                handle_door_operations(state, people_on_current_floor);
                state.door_open = false;
                people_on_current_floor = 0;
            }
            handle_elevator_movement(state, sorted_floors[i], true);
            prev_floor = sorted_floors[i];
        }
        people_on_current_floor++;
    }

    if (people_on_current_floor > 0) {
        handle_door_operations(state, people_on_current_floor);
        state.door_open = false;
    }

    handle_elevator_movement(state, 0, false);
}

