    if (s.empty() || s.size() > 10) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    return true;
}

long long convert_to_number(const string& s) {
    istringstream iss(s);
    long long val;
    iss >> val;
    if (iss.fail()) {
        return numeric_limits<long long>::max();
    }
    return val;
}

int calculate_digit_sum(long long x) {
    int sum_result = 0;
    long long temp = abs(x);
    while (temp > 0) {
        sum_result += temp % 10;
        temp /= 10;
    }
    return sum_result;
}

bool compare_plates(const NumberPlateInfo& a, const NumberPlateInfo& b) {
    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    }
    return a.numeric_value > b.numeric_value;
}

void initialize_plate_data(const vector<string>& plates) {
    for (size_t i = 0; i < plates.size(); ++i) {
        if (!validate_number_string(plates[i])) {
            throw invalid_argument("Invalid number plate format");
        }
        long long num_val = convert_to_number(plates[i]);
        int sum_val = calculate_digit_sum(num_val);
        plate_data.push_back({plates[i], num_val, sum_val, i});
    }
}

size_t find_plate_position(const string& target) {
    auto it = find_if(plate_data.begin(), plate_data.end(),
        [&target](const NumberPlateInfo& info) {
            return info.original == target;
        });
