    if (is_safe_multiply(newAnger, data.anger[index])) {
        newAnger *= data.anger[index];
    } else {
        throw overflow_error("Anger multiplication overflow during recursion");
    }

    int newIrritability = currentIrritability;
    if (is_safe_add(newIrritability, data.irritability[index])) {
        newIrritability += data.irritability[index];
    } else {
        throw overflow_error("Irritability addition overflow during recursion");
    }

    recursiveDifferenceCalculator(data, newAnger, newIrritability, index + 1, minDifference);
    recursiveDifferenceCalculator(data, currentAnger, currentIrritability, index + 1, minDifference);
}

