#include<bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 1001;
const int MAX_DIRECTIONS = 4;

struct CoordinateValidator {
    int max_x;
    int max_y;
    bool validate(int x, int y) const {
        bool x_valid = (x >= 0) && (x < max_x);
        bool y_valid = (y >= 0) && (y < max_y);
        return x_valid && y_valid;
    }
};

class TerrainAnalyzer {
private:
    char terrain_grid[MAX_DIMENSION][MAX_DIMENSION];
    bool visited[MAX_DIMENSION][MAX_DIMENSION];
    CoordinateValidator validator;
    const int directions[MAX_DIRECTIONS][2] = {{0,1},{1,0},{0,-1},{-1,0}};

    void initializeVisited(int n, int m) {
        for(int i=0;i<n;i++) {
            for(int j=0;j<m;j++) {
                visited[i][j] = false;
            }
        }
    }

public:
    void setDimensions(int n, int m) {
        validator.max_x = n;
        validator.max_y = m;
    }

    void loadTerrain(int n, int m) {
        for(int i=0;i<n;i++) {
            for(int j=0;j<m;j++) {
                char terrain_cell;
                cin>>terrain_cell;
                terrain_grid[i][j] = terrain_cell;
            }
        }
        initializeVisited(n, m);
    }

    void exploreRegion(int x, int y) {
        for(int direction_index=0;direction_index<MAX_DIRECTIONS;direction_index++) {
            int new_x = x + directions[direction_index][0];
            int new_y = y + directions[direction_index][1];
            if(validator.validate(new_x, new_y)) {
                if(terrain_grid[new_x][new_y] == '#' && !visited[new_x][new_y]) {
                    visited[new_x][new_y] = true;
                    exploreRegion(new_x, new_y);
                }
            }
        }
    }

    int countRegions() {
        int region_count = 0;
        for(int i=0;i<validator.max_x;i++) {
            for(int j=0;j<validator.max_y;j++) {
                if(terrain_grid[i][j] == '#' && !visited[i][j]) {
                    region_count++;
                    visited[i][j] = true;
                    exploreRegion(i, j);
                }
            }
        }
        return region_count;
    }
};

