#include<bits/stdc++.h>
using namespace std;

const int MAX_DIM = 1005;
const int MIN_DIM = 1;
const int MAX_DIRECTIONS = 4;

struct CanyonDimensions {
    int length;
    int width;
};

struct Direction {
    int dx;
    int dy;
};

class CanyonMapValidator {
public:
    static bool validateDimensions(const CanyonDimensions& dims) {
        if (dims.length < MIN_DIM || dims.length > MAX_DIM - 5) return false;
        if (dims.width < MIN_DIM || dims.width > MAX_DIM - 5) return false;
        return true;
    }

    static bool validatePosition(const CanyonDimensions& dims, int x, int y) {
        return x >= 0 && x < dims.length && y >= 0 && y < dims.width;
    }
};

class GrasslandCounter {
private:
    CanyonDimensions dimensions;
    char terrain[MAX_DIM][MAX_DIM];
    bool visited[MAX_DIM][MAX_DIM];
    Direction directions[MAX_DIRECTIONS] = {{0,1}, {1,0}, {0,-1}, {-1,0}};

    void initializeVisited() {
        for (int i = 0; i < dimensions.length; ++i) {
            for (int j = 0; j < dimensions.width; ++j) {
                visited[i][j] = false;
            }
        }
    }

    void performDepthFirstSearch(int x, int y) {
        if (!CanyonMapValidator::validatePosition(dimensions, x, y)) return;
        if (terrain[x][y] != '#' || visited[x][y]) return;

        visited[x][y] = true;

        for (int i = 0; i < MAX_DIRECTIONS; ++i) {
            Direction dir = directions[i];
            int newX = x + dir.dx;
            int newY = y + dir.dy;
            performDepthFirstSearch(newX, newY);
        }
    }

public:
    GrasslandCounter(const CanyonDimensions& dims) : dimensions(dims) {
        initializeVisited();
    }

    void setTerrain(int x, int y, char value) {
        if (CanyonMapValidator::validatePosition(dimensions, x, y)) {
            terrain[x][y] = value;
        }
    }

    int countGrasslands() {
        int count = 0;
        for (int i = 0; i < dimensions.length; ++i) {
            for (int j = 0; j < dimensions.width; ++j) {
                if (terrain[i][j] == '#' && !visited[i][j]) {
                    ++count;
                    performDepthFirstSearch(i, j);
                }
            }
        }
        return count;
    }
};

class FileHandler {
public:
    static bool openInputFile(ifstream& fin) {
        fin.open("hiking.in");
        return fin.is_open();
    }

    static bool openOutputFile(ofstream& fout) {
        fout.open("hiking.out");
        return fout.is_open();
    }
};

int main() {
    ifstream fin;
    ofstream fout;

    if (!FileHandler::openInputFile(fin)) {
        cerr << "Error opening input file" << endl;
        return EXIT_FAILURE;
    }

    CanyonDimensions dims;
    fin >> dims.length >> dims.width;

    if (!CanyonMapValidator::validateDimensions(dims)) {
        cerr << "Invalid canyon dimensions" << endl;
        return EXIT_FAILURE;
    }

    GrasslandCounter counter(dims);
    char cell;

    for (int i = 0; i < dims.length; ++i) {
        for (int j = 0; j < dims.width; ++j) {
            fin >> cell;
            counter.setTerrain(i, j, cell);
        }
    }

    fin.close();

    if (!FileHandler::openOutputFile(fout)) {
        cerr << "Error opening output file" << endl;
        return EXIT_FAILURE;
    }

    fout << counter.countGrasslands() << endl;
    fout.close();

    return EXIT_SUCCESS;
}
