using namespace std;

struct DataSet {
    int x;
    int y;
    int diff;
    int min_val;
    int index;
};

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else {
        if (a.min_val != b.min_val) {
            return a.min_val < b.min_val;
        } else {
            return a.index < b.index;
        }
    }
}

void validateInput(int n) {
    if (n < 1 || n > 100) {
        throw invalid_argument("Invalid number of data sets");
    }
}

void validateXY(int x, int y) {
    if (x < 1 || x > 20 || y < 1 || y > 20) {
        throw out_of_range("X or Y out of valid range");
    }
}

int calculateDifference(int x, int y) {
    return abs(x - y);
}

int findMinimumValue(int x, int y) {
    return min(x, y);
}

DataSet processDataSet(int x, int y, int index) {
    DataSet ds;
    ds.x = x;
    ds.y = y;
    ds.diff = calculateDifference(x, y);
    ds.min_val = findMinimumValue(x, y);
    ds.index = index;
    return ds;
}

void printResult(const DataSet& result) {
    cout << min(result.x, result.y) << " " << max(result.x, result.y) << endl;
}

int main() {
    try {
        int n;
        cin >> n;
        validateInput(n);

        vector<DataSet> dataSets;
        dataSets.reserve(n);

        for (int i = 0; i < n; i++) {
            int x, y;
