            if (dataSets[i].diff == result.diff && 
                dataSets[i].min_val == result.min_val && 
                dataSets[i].index < result.index) {
                result = dataSets[i];
            }
        }

        printResult(result);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
