const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const int ALPHABET_SIZE = 26;
const int DIGIT_COUNT = 10;

struct DecryptionContext {
    string currentToken;
    size_t positionTracker;
    bool specialSequenceFound;
    vector<char> decryptedBuffer;
};

void handleAlphabetShift(char& currentChar, DecryptionContext& context) {
    if(currentChar >= 'd' && currentChar <= 'z') {
        currentChar -= SHIFT_VALUE;
    } else if(currentChar >= 'a' && currentChar <= 'c') {
        currentChar = '7' + (currentChar - 'a');
    }
}

void handleDigitShift(char& currentChar, DecryptionContext& context) {
    if(currentChar >= '3' && currentChar <= '9') {
        currentChar -= SHIFT_VALUE;
    } else if(currentChar >= '0' && currentChar <= '2') {
        currentChar = 'x' + (currentChar - '0');
    }
}

bool checkForSpecialSequence(const string& input, size_t pos, const string& sequence) {
    if(pos + sequence.length() > input.length()) return false;
    for(size_t i = 0; i < sequence.length(); ++i) {
        if(input[pos + i] != sequence[i]) return false;
    }
    return true;
}

void processSpecialSequence(DecryptionContext& context, char replacement) {
    context.decryptedBuffer.push_back(replacement);
    context.positionTracker += 2;
    context.specialSequenceFound = true;
}

void initializeDecryptionContext(DecryptionContext& context) {
    context.positionTracker = 0;
    context.specialSequenceFound = false;
    context.decryptedBuffer.clear();
}

string performDecryption(const string& input) {
    DecryptionContext context;
    initializeDecryptionContext(context);

    while(context.positionTracker < input.length()) {
        char currentChar = input[context.positionTracker];
        context.specialSequenceFound = false;

        if(checkForSpecialSequence(input, context.positionTracker, SPACE_REPLACEMENT)) {
            processSpecialSequence(context, ' ');
            continue;
        }

        if(checkForSpecialSequence(input, context.positionTracker, DOT_REPLACEMENT)) {
            processSpecialSequence(context, '.');
            continue;
        }

        if(isalpha(currentChar)) {
            handleAlphabetShift(currentChar, context);
        } else if(isdigit(currentChar)) {
            handleDigitShift(currentChar, context);
        }

        if(!context.specialSequenceFound) {
            context.decryptedBuffer.push_back(currentChar);
            context.positionTracker++;
        }
    }

    return string(context.decryptedBuffer.begin(), context.decryptedBuffer.end());
}

