void validate_input_range(T value, T min, T max) {
    if (!is_valid_integer_type<T>) {
        throw invalid_argument("Type must be integral");
    }
    if (value <= min || value >= max) {
        throw out_of_range("Value out of valid range");
    }
}

class DigitSumCalculator {
public:
    template<typename T>
    static T calculate(T x) {
        static_assert(is_valid_integer_type<T>, "Must be integral type");
        if (x < 0) x = -x;
        T ans = 0;
        while (x != 0) {
            ans += x % 10;
            x /= 10;
            if (ans > numeric_limits<T>::max() / 10) {
                throw overflow_error("Digit sum overflow");
            }
        }
        return ans;
    }
};

class AdvancedIntegerComparator {
public:
    template<typename T>
    static bool compare(T x, T y) {
        static_assert(is_valid_integer_type<T>, "Must be integral type");
        T sum_x = DigitSumCalculator::calculate(x);
        T sum_y = DigitSumCalculator::calculate(y);

        if (sum_x != sum_y) {
            return sum_x < sum_y;
        }

        if (x == y) {
            return false;
        }

        if (x % 2 == 0 && y % 2 != 0) {
            return false;
        }

        if (x % 2 != 0 && y % 2 == 0) {
            return true;
        }

        return x < y;
    }
};

