    long long numericValue;
    int digitSum;
    size_t originalIndex;
};

vector<NumberPlateInfo> plateDatabase;

void validateInputRange(int value, int minVal, int maxVal, const string& context) {
    if (value < minVal || value > maxVal) {
        throw out_of_range(context + " out of valid range");
    }
}

long long convertStringToNumber(const string& s) {
    if (s.empty()) {
        throw invalid_argument("Empty string cannot be converted to number");
    }

    istringstream iss(s);
    long long val;
    iss >> val;

    if (iss.fail() || !iss.eof()) {
        throw invalid_argument("Invalid number format: " + s);
    }

    return val;
}

int calculateDigitSum(long long x) {
    if (x < 0) x = -x;
    int sumResult = 0;
    long long temp = x;

    while (temp != 0) {
        int digit = temp % 10;
        sumResult += digit;
        temp /= 10;
    }

    return sumResult;
}

bool comparePlates(const NumberPlateInfo& a, const NumberPlateInfo& b) {
    if (a.digitSum != b.digitSum) {
        return a.digitSum < b.digitSum;
    }

    if (a.numericValue != b.numericValue) {
        return a.numericValue > b.numericValue;
    }

    return a.originalIndex < b.originalIndex;
}

void initializePlateDatabase(int n) {
    plateDatabase.clear();
    plateDatabase.reserve(n);

    for (int i = 0; i < n; ++i) {
        string plateString;
        cin >> plateString;

        if (plateString.length() > 10) {
            throw length_error("Number plate string exceeds maximum length");
        }

        long long plateValue = convertStringToNumber(plateString);
        int sumValue = calculateDigitSum(plateValue);

        NumberPlateInfo info;
        info.originalString = plateString;
        info.numericValue = plateValue;
        info.digitSum = sumValue;
        info.originalIndex = i;

        plateDatabase.push_back(info);
    }
}

size_t findGarlicPosition() {
    if (plateDatabase.empty()) {
        throw logic_error("Plate database is empty");
    }

    const string& garlicPlate = plateDatabase.back().originalString;
    long long garlicValue = plateDatabase.back().numericValue;

    vector<NumberPlateInfo> sortedPlates = plateDatabase;
    sort(sortedPlates.begin(), sortedPlates.end(), comparePlates);

    for (size_t i = 0; i < sortedPlates.size(); ++i) {
        if (sortedPlates[i].originalString == garlicPlate && 
            sortedPlates[i].numericValue == garlicValue) {
            return i + 1;
        }
    }

    throw runtime_error("Garlic's plate not found in sorted database");
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    try {
        int n;
        cin >> n;

        validateInputRange(n, 1, 10000, "Number of plates");

        initializePlateDatabase(n);

        size_t position = findGarlicPosition();
        cout << position << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
