const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const int NUMERIC_WRAPAROUND = 10;
const int ALPHABET_WRAPAROUND = 26;
const char NUMERIC_START = '0';
const char NUMERIC_END = '9';
const char ALPHA_START = 'a';
const char ALPHA_END = 'z';

struct DecryptionContext {
    string encrypted;
    string decrypted;
    vector<size_t> specialPositions;
    bool hasSpecialSequences;
};

void initializeContext(DecryptionContext& ctx, const string& input) {
    ctx.encrypted = input;
    ctx.decrypted = "";
    ctx.hasSpecialSequences = false;
}

void detectSpecialSequences(DecryptionContext& ctx) {
    size_t kkkPos = ctx.encrypted.find(SPACE_REPLACEMENT);
    size_t sssPos = ctx.encrypted.find(DOT_REPLACEMENT);

    while (kkkPos != string::npos || sssPos != string::npos) {
        if (kkkPos != string::npos) {
            ctx.specialPositions.push_back(kkkPos);
            ctx.encrypted.replace(kkkPos, SPACE_REPLACEMENT.length(), " ");
            ctx.hasSpecialSequences = true;
        }
        if (sssPos != string::npos) {
            ctx.specialPositions.push_back(sssPos);
            ctx.encrypted.replace(sssPos, DOT_REPLACEMENT.length(), ".");
            ctx.hasSpecialSequences = true;
        }
        kkkPos = ctx.encrypted.find(SPACE_REPLACEMENT);
        sssPos = ctx.encrypted.find(DOT_REPLACEMENT);
    }
}

char decryptCharacter(char c) {
    if (c >= NUMERIC_START && c <= NUMERIC_END) {
        int shifted = c - SHIFT_VALUE;
        if (shifted < NUMERIC_START) {
            shifted += NUMERIC_WRAPAROUND;
            if (shifted > NUMERIC_END) {
                shifted = ALPHA_START + (shifted - NUMERIC_END - 1);
            }
        }
        return static_cast<char>(shifted);
    } else if (c >= ALPHA_START && c <= ALPHA_END) {
        int shifted = c - SHIFT_VALUE;
        if (shifted < ALPHA_START) {
            shifted += ALPHABET_WRAPAROUND;
            if (shifted > ALPHA_END) {
                shifted = NUMERIC_START + (shifted - ALPHA_END - 1);
            }
        }
        return static_cast<char>(shifted);
    }
    return c;
}

void processRegularCharacters(DecryptionContext& ctx) {
    for (size_t i = 0; i < ctx.encrypted.length(); ++i) {
        bool isSpecial = false;
        for (size_t pos : ctx.specialPositions) {
            if (i == pos) {
                isSpecial = true;
                break;
            }
        }
        if (!isSpecial) {
            ctx.decrypted += decryptCharacter(ctx.encrypted[i]);
        } else {
            ctx.decrypted += ctx.encrypted[i];
        }
    }
}

void validateOutput(const string& output) {
    for (char c : output) {
        if (!((c >= NUMERIC_START && c <= NUMERIC_END) || 
              (c >= ALPHA_START && c <= ALPHA_END) || 
              c == ' ' || c == '.')) {
            throw runtime_error("Invalid character in decrypted output");
        }
    }
}

int main() {
