        throw invalid_argument(message);
    }
}

int computeAbsoluteDifference(int a, int b) {
    return abs(a - b);
}

int findMinimumValue(int a, int b) {
    return min(a, b);
}

NumberSet createNumberSet(int x, int y, int index) {
    NumberSet ns;
    ns.x = x;
    ns.y = y;
    ns.diff = computeAbsoluteDifference(x, y);
    ns.min_val = findMinimumValue(x, y);
    ns.index = index;
    return ns;
}

