void initializeElevatorState(ElevatorState& state) {
    state.current_floor = 0;
    state.total_time = 0;
    state.passenger_count = 0;
    state.door_open = false;
    state.ascending = false;
    state.descending = false;
}

void processFloorTransition(ElevatorState& state, long long target_floor) {
    if (target_floor > state.current_floor) {
        state.ascending = true;
        state.descending = false;
        state.total_time += 5 * (target_floor - state.current_floor);
        state.current_floor = target_floor;
    } else if (target_floor < state.current_floor) {
        state.ascending = false;
        state.descending = true;
        state.total_time += 4 * (state.current_floor - target_floor);
        state.current_floor = target_floor;
    }
    state.ascending = false;
    state.descending = false;
}

void processPassengerOperations(ElevatorState& state, long long passenger_count) {
    if (!state.door_open) {
        state.total_time += 3;
        state.door_open = true;
    }
    state.total_time += 2 * passenger_count;
    state.passenger_count += passenger_count;
}

void returnToGroundFloor(ElevatorState& state) {
    if (state.current_floor != 0) {
        state.descending = true;
        state.ascending = false;
        state.total_time += 4 * state.current_floor;
        state.current_floor = 0;
        state.descending = false;
