CharacterProcessor initializeProcessor(char c, int pos, int y, int z) {
    CharacterProcessor cp;
    cp.original = c;
    cp.position = pos;
    cp.cycle = y;
    cp.shiftAmount = z;
    cp.shouldProcess = (pos % y == 0);
    cp.isUpper = (c >= 'A' && c <= 'Z');
    cp.isLower = (c >= 'a' && c <= 'z');
    cp.isDigit = (c >= '0' && c <= '9');
    return cp;
}

char processCharacter(CharacterProcessor cp) {
