struct CharacterValidator {
    static bool validateAlphabetUpper(char c) {
        return (c >= 'A' && c <= 'Z');
    }
    static bool validateAlphabetLower(char c) {
        return (c >= 'a' && c <= 'z');
    }
    static bool validateNumeric(char c) {
        return (c >= '0' && c <= '9');
    }
};

class CyclicShifter {
private:
    int shiftAmount;
    bool initialized;
public:
    CyclicShifter(int z) : shiftAmount(z), initialized(false) {
        if (z <= 0) throw invalid_argument("Shift amount must be positive");
        initialized = true;
    }
    char shiftCharacter(char c) {
        if (!initialized) throw runtime_error("Shifter not initialized");
        if (CharacterValidator::validateAlphabetUpper(c)) {
            int base = 'A';
            int range = 26;
            int shifted = (c - base + shiftAmount) % range;
            if (shifted < 0) shifted += range;
            return static_cast<char>(base + shifted);
        } else if (CharacterValidator::validateAlphabetLower(c)) {
            int base = 'a';
            int range = 26;
            int shifted = (c - base + shiftAmount) % range;
            if (shifted < 0) shifted += range;
            return static_cast<char>(base + shifted);
        } else if (CharacterValidator::validateNumeric(c)) {
            int base = '0';
            int range = 10;
            int shifted = (c - base + shiftAmount) % range;
            if (shifted < 0) shifted += range;
            return static_cast<char>(base + shifted);
        }
        return c;
    }
};

class InputProcessor {
private:
    int x, y, z;
    vector<char> characters;
    bool parametersValidated;
public:
