        if (y <= 0 || y > 10) throw out_of_range("Invalid y value");
        if (z <= 0 || z > 100) throw out_of_range("Invalid z value");
        parametersValidated = true;
    }
    void readCharacters() {
        if (!parametersValidated) throw runtime_error("Parameters not validated");
        characters.resize(x);
        for (int i = 0; i < x; ++i) {
            cin >> characters[i];
            if (!isalnum(characters[i])) throw invalid_argument("Invalid character in input");
        }
    }
    string process() {
        if (!parametersValidated || characters.empty()) throw runtime_error("Data not ready");
        CyclicShifter shifter(z);
        string result;
        for (int i = 1; i <= x; ++i) {
            if (i % y == 0) {
                try {
                    result += shifter.shiftCharacter(characters[i-1]);
                } catch (...) {
                    result += characters[i-1];
                }
            } else {
                result += characters[i-1];
            }
        }
        return result;
    }
};

int main() {
