        istringstream iss(input);
        tokens = vector<string>(istream_iterator<string>{iss},
                               istream_iterator<string>());
        processedFlags = vector<bool>(tokens.size(), false);
    }

    bool isWordBoundary(size_t pos) {
        if (pos >= tokens.size()) return false;
        if (processedFlags[pos]) return false;
        return true;
    }

    void processRule3() {
        for (size_t i = 0; i < tokens.size(); ++i) {
            if (!isWordBoundary(i)) continue;

            if (i + 1 < tokens.size() && !processedFlags[i+1]) {
                if ((tokens[i] == "can" && tokens[i+1] == "you") ||
                    (tokens[i] == "could" && tokens[i+1] == "you")) {
                    tokens[i] = "I";
                    processedFlags[i] = true;
                    processedFlags[i+1] = true;
