        istringstream iss(input);
        vector<string> tokens{istream_iterator<string>{iss},
                              istream_iterator<string>{}};

        if (tokens.empty()) {
            throw runtime_error("No words found in input");
        }

        for (const auto& token : tokens) {
            bool valid_word = true;
            for (char c : token) {
                if (!isalpha(c)) {
                    valid_word = false;
                    break;
                }
            }
            if (valid_word) {
                word_stats.emplace_back(token, token.length());
            }
        }
    }

public:
