using namespace std;

const unordered_map<string, string> SPECIAL_SEQUENCES = {
    {"kkk", " "},
    {"sss", "."}
};

const string NUMERIC_CHARS = "0123456789";
const string ALPHA_CHARS = "abcdefghijklmnopqrstuvwxyz";
const string ALL_CHARS = NUMERIC_CHARS + ALPHA_CHARS;

string handleSpecialSequences(const string& input) {
    string result = input;
    for (const auto& [seq, replacement] : SPECIAL_SEQUENCES) {
        size_t pos = result.find(seq);
        while (pos != string::npos) {
            if (pos % 3 == 0 || pos == 0) {
                result.replace(pos, seq.length(), replacement);
            }
            pos = result.find(seq, pos + replacement.length());
        }
    }
    return result;
}

char decryptChar(char c) {
    if (!isalnum(c) && c != ' ') {
        throw invalid_argument("Invalid character detected");
    }

    const size_t total_chars = ALL_CHARS.length();
    size_t pos = ALL_CHARS.find(c);

    if (pos != string::npos) {
        size_t new_pos = (pos - 3 + total_chars) % total_chars;
        if (new_pos < 0) {
            new_pos += total_chars;
        }
        return ALL_CHARS[new_pos];
    }

    return c;
}

string processRegularCharacters(const string& input) {
    string result;
    for (size_t i = 0; i < input.length(); ) {
        if (i + 2 < input.length() && 
            (input.substr(i, 3) == "kkk" || input.substr(i, 3) == "sss")) {
            i += 3;
            continue;
