int visited_status[MAX_DIMENSION][MAX_DIMENSION];
vector<CanyonPosition> direction_offsets = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

bool validate_position_bounds(CanyonPosition pos) {
    return pos.row >= 1 && pos.row <= canyon_rows && 
           pos.col >= 1 && pos.col <= canyon_cols;
}

bool is_valid_bush_position(CanyonPosition pos) {
    if (!validate_position_bounds(pos)) {
        return false;
    }
    return canyon_grid[pos.row][pos.col] == BUSH && 
           visited_status[pos.row][pos.col] == UNVISITED;
}

void perform_depth_first_search(CanyonPosition current_pos) {
    if (!is_valid_bush_position(current_pos)) {
        return;
    }

    visited_status[current_pos.row][current_pos.col] = VISITED;
    canyon_grid[current_pos.row][current_pos.col] = SPACE;

    for (const auto& offset : direction_offsets) {
        CanyonPosition new_pos = {
            current_pos.row + offset.row,
            current_pos.col + offset.col
        };
        perform_depth_first_search(new_pos);
    }
}

void initialize_visited_status() {
