const int MAX_DIM = 105;
const char BUSH = '#';
const char SPACE = '.';

struct CanyonMap {
    char grid[MAX_DIM][MAX_DIM];
    bool visited[MAX_DIM][MAX_DIM];
    int rows;
    int cols;
};

void initializeVisited(CanyonMap& canyon) {
    for(int i = 0; i < MAX_DIM; i++) {
        for(int j = 0; j < MAX_DIM; j++) {
            canyon.visited[i][j] = false;
        }
    }
}

bool validateCoordinates(const CanyonMap& canyon, int x, int y) {
    if(x < 0 || y < 0 || x >= canyon.rows || y >= canyon.cols) {
        return false;
    }
    if(canyon.grid[x][y] != BUSH) {
        return false;
    }
    if(canyon.visited[x][y]) {
        return false;
    }
    return true;
}

void performDFS(CanyonMap& canyon, int x, int y) {
    if(!validateCoordinates(canyon, x, y)) {
        return;
    }

    canyon.visited[x][y] = true;

    const int dx[] = {-1, 1, 0, 0};
    const int dy[] = {0, 0, -1, 1};

    for(int i = 0; i < 4; i++) {
        int newX = x + dx[i];
        int newY = y + dy[i];
        if(newX >= 0 && newY >= 0 && newX < canyon.rows && newY < canyon.cols) {
            if(!canyon.visited[newX][newY] && canyon.grid[newX][newY] == BUSH) {
                performDFS(canyon, newX, newY);
            }
        }
    }
}

int countGrasslands(CanyonMap& canyon) {
    initializeVisited(canyon);
    int grasslandCount = 0;

    for(int i = 0; i < canyon.rows; i++) {
        for(int j = 0; j < canyon.cols; j++) {
            if(canyon.grid[i][j] == BUSH && !canyon.visited[i][j]) {
                performDFS(canyon, i, j);
                grasslandCount++;
            }
        }
    }

    return grasslandCount;
}

bool readInputFile(CanyonMap& canyon, const string& filename) {
    ifstream inputFile(filename.c_str());
    if(!inputFile.is_open()) {
        return false;
    }

    inputFile >> canyon.rows >> canyon.cols;
    if(canyon.rows <= 0 || canyon.cols <= 0 || canyon.rows > 100 || canyon.cols > 100) {
        return false;
    }

    for(int i = 0; i < canyon.rows; i++) {
        for(int j = 0; j < canyon.cols; j++) {
            inputFile >> canyon.grid[i][j];
            if(canyon.grid[i][j] != BUSH && canyon.grid[i][j] != SPACE) {
                return false;
            }
        }
    }

    inputFile.close();
    return true;
}

bool writeOutputFile(const string& filename, int result) {
    ofstream outputFile(filename.c_str());
    if(!outputFile.is_open()) {
        return false;
    }

    outputFile << result;
    outputFile.close();
    return true;
}

