namespace BookshelfSolver {
    const int MAX_COWS = 25;
    const int INFINITE_HEIGHT = numeric_limits<int>::max();

    struct Configuration {
        int cow_count;
        int shelf_height;
        array<int, MAX_COWS> heights;
        bool heights_initialized;

        Configuration() : cow_count(0), shelf_height(0), heights_initialized(false) {
            heights.fill(0);
        }
    };

    class SolutionValidator {
    public:
        static bool validate_input_range(int value, int min_val, int max_val) {
            return (value >= min_val) && (value <= max_val);
        }

        static void verify_configuration(const Configuration& config) {
            if (!validate_input_range(config.cow_count, 1, 20)) {
                throw runtime_error("Invalid cow count");
            }
            int total_height = accumulate(config.heights.begin(), config.heights.begin() + config.cow_count, 0);
            if (!validate_input_range(config.shelf_height, 1, total_height)) {
                throw runtime_error("Invalid shelf height");
            }
            if (!config.heights_initialized) {
                throw runtime_error("Heights not initialized");
            }
        }
    };

    class TowerHeightCalculator {
    private:
        Configuration config;
        int minimal_excess;
        vector<bool> inclusion_status;

        void initialize_inclusion_status() {
            inclusion_status.resize(config.cow_count);
            fill(inclusion_status.begin(), inclusion_status.end(), false);
        }

        void recursive_height_evaluation(int current_position, int current_sum, int cows_remaining) {
            if (cows_remaining == 0) {
                if (current_sum >= config.shelf_height) {
                    int current_excess = current_sum - config.shelf_height;
                    if (current_excess < minimal_excess) {
                        minimal_excess = current_excess;
                    }
                }
                return;
            }

            if (current_position >= config.cow_count) {
                return;
            }

            if (current_sum - config.shelf_height >= minimal_excess) {
                return;
            }

            recursive_height_evaluation(current_position + 1, current_sum + config.heights[current_position], cows_remaining - 1);
            recursive_height_evaluation(current_position + 1, current_sum, cows_remaining);
        }

    public:
        TowerHeightCalculator(const Configuration& cfg) : config(cfg), minimal_excess(INFINITE_HEIGHT) {
            SolutionValidator::verify_configuration(config);
            initialize_inclusion_status();
        }

        int compute_minimal_excess() {
            for (int subset_size = 1; subset_size <= config.cow_count; ++subset_size) {
                recursive_height_evaluation(0, 0, subset_size);
            }
            return minimal_excess;
        }
    };
}

int main() {
