        input_file >> config.cow_count >> config.shelf_height;

        for (int i = 0; i < config.cow_count; ++i) {
            input_file >> config.heights[i];
        }
        config.heights_initialized = true;

        BookshelfSolver::TowerHeightCalculator calculator(config);
        int result = calculator.compute_minimal_excess();

        output_file << result << endl;

        input_file.close();
        output_file.close();

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
