    if (s[pos - 1] == ' ' && s[pos + 1] == ' ') return true;
    if ((pos == 0 || s[pos - 1] == ' ') && isPunctuation(s[pos + 1])) return true;
    if ((pos == s.length() - 1 || s[pos + 1] == ' ') && isPunctuation(s[pos - 1])) return true;
    return false;
}

vector<string> tokenizeWithPunctuation(const string& s) {
    vector<string> tokens;
    string current;
    for (char c : s) {
        if (c == ' ') {
            if (!current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
