#include<bits/stdc++.h>
using namespace std;

const int MAX_COWS = 25;
const int INF = 1e9+7;

struct CowTowerValidator {
    bool operator()(int sum, int target) const {
        return sum >= target;
    }
};

struct CowHeightAccumulator {
    int operator()(int a, int b) const {
        return a + b;
    }
};

class BookshelfHeightCalculator {
private:
    int cow_count;
    int bookshelf_height;
    int cow_heights[MAX_COWS];
    int minimal_excess;
    vector<int> current_combination;
    vector<vector<int>> all_valid_combinations;

    void validateInput() {
        if (cow_count <= 0 || cow_count > 20) {
            throw invalid_argument("Invalid number of cows");
        }
        if (bookshelf_height <= 0) {
            throw invalid_argument("Bookshelf height must be positive");
        }
        int total_height = accumulate(cow_heights, cow_heights + cow_count, 0, CowHeightAccumulator());
        if (bookshelf_height > total_height) {
            throw invalid_argument("Bookshelf height exceeds total cow heights");
        }
    }

    void recursiveCombinationSearch(int current_index, int current_sum) {
        if (CowTowerValidator()(current_sum, bookshelf_height)) {
            if (current_sum < minimal_excess) {
                minimal_excess = current_sum;
            }
            return;
        }
        if (current_index >= cow_count) {
            return;
        }
        if (current_sum + cow_heights[current_index] > minimal_excess) {
            return;
        }
        recursiveCombinationSearch(current_index + 1, current_sum + cow_heights[current_index]);
        recursiveCombinationSearch(current_index + 1, current_sum);
    }

public:
    BookshelfHeightCalculator(int n, int b) : cow_count(n), bookshelf_height(b), minimal_excess(INF) {
        fill_n(cow_heights, MAX_COWS, 0);
    }

    void readCowHeights() {
        for (int i = 0; i < cow_count; ++i) {
            if (!(cin >> cow_heights[i])) {
                throw runtime_error("Failed to read cow height");
            }
            if (cow_heights[i] <= 0) {
                throw invalid_argument("Cow height must be positive");
            }
        }
    }

    int calculateMinimalExcess() {
        try {
            validateInput();
            sort(cow_heights, cow_heights + cow_count, greater<int>());
            recursiveCombinationSearch(0, 0);
            if (minimal_excess == INF) {
                throw runtime_error("No valid combination found");
            }
            return minimal_excess - bookshelf_height;
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            return -1;
        }
    }
};

int main() {
    ifstream input_file("shelf.in");
    ofstream output_file("shelf.out");

    if (!input_file.is_open()) {
        cerr << "Failed to open input file" << endl;
        return 1;
    }

    if (!output_file.is_open()) {
        cerr << "Failed to open output file" << endl;
        return 1;
    }

    int n, b;
    input_file >> n >> b;

    BookshelfHeightCalculator calculator(n, b);
    calculator.readCowHeights();
    int result = calculator.calculateMinimalExcess();

    if (result >= 0) {
        output_file << result << endl;
    } else {
        output_file << "0" << endl;
    }

    input_file.close();
    output_file.close();

    return 0;
}
