    string state_hash = get_state_hash(current_product, current_sum);
    if (visited_states.find(state_hash) != visited_states.end()) {
        return;
    }
    visited_states.insert(state_hash);

    if (at_least_one_selected) {
        int current_diff = abs(current_product - current_sum);
        if (current_diff < 0) {
            current_diff = INT_MAX;
        }
        if (current_diff < global_min_diff) {
            global_min_diff = current_diff;
