#include<bits/stdc++.h>
#include<limits>
#include<stdexcept>
using namespace std;

struct StoneAttributes {
    int anger;
    int irritability;
};

class StoneProcessor {
private:
    vector<StoneAttributes> stones;
    int stoneCount;
    int globalMinimumDifference;
    bool initializationFlag;

    void validateInputParameters() {
        if (stoneCount < 1 || stoneCount > 10) {
            throw invalid_argument("Invalid stone count");
        }
        for (const auto& stone : stones) {
            if (stone.anger <= 0 || stone.irritability <= 0) {
                throw invalid_argument("Invalid stone attributes");
            }
        }
    }

    void recursiveStoneSelection(int currentDepth, int cumulativeAnger, int cumulativeIrritability, bool selectionMade) {
        if (currentDepth > stoneCount) {
            if (selectionMade) {
                int temporaryDifferenceHolder = abs(cumulativeAnger - cumulativeIrritability);
                if (temporaryDifferenceHolder < globalMinimumDifference) {
                    globalMinimumDifference = temporaryDifferenceHolder;
                }
            }
            return;
        }

        int newAngerProduct = cumulativeAnger * stones[currentDepth-1].anger;
        int newIrritabilitySum = cumulativeIrritability + stones[currentDepth-1].irritability;

        recursiveStoneSelection(currentDepth + 1, newAngerProduct, newIrritabilitySum, true);
        recursiveStoneSelection(currentDepth + 1, cumulativeAnger, cumulativeIrritability, selectionMade);
    }

public:
    StoneProcessor() : stoneCount(0), globalMinimumDifference(numeric_limits<int>::max()), initializationFlag(false) {}

    void initializeFromInput() {
        ifstream inputFile("stone.in");
        if (!inputFile.is_open()) {
            throw runtime_error("Unable to open input file");
        }

        inputFile >> stoneCount;
        stones.resize(stoneCount);
        for (int i = 0; i < stoneCount; ++i) {
            inputFile >> stones[i].anger >> stones[i].irritability;
        }
        inputFile.close();

        validateInputParameters();
        initializationFlag = true;
    }

    int computeMinimumDifference() {
        if (!initializationFlag) {
            throw logic_error("Processor not initialized");
        }

        recursiveStoneSelection(1, 1, 0, false);

        if (globalMinimumDifference == numeric_limits<int>::max()) {
            throw runtime_error("No valid stone combination found");
        }

        return globalMinimumDifference;
    }
};

int main() {
