void initializeGlobalState() {
    global_min_diff = INF;
    current_anger_product = 1;
    current_irritability_sum = 0;
    recursion_depth = 0;
    max_recursion_depth = 0;
    memset(visited, 0, sizeof(visited));
    initialization_complete = true;
}

void recursiveStoneSelection(int index, int selected_count) {
    if (!initialization_complete || !input_valid) return;

    recursion_depth++;
    if (recursion_depth > max_recursion_depth) {
        max_recursion_depth = recursion_depth;
    }

    if (index >= stone_count) {
        if (selected_count > 0) {
            int current_diff = abs(current_anger_product - current_irritability_sum);
            if (current_diff < global_min_diff) {
