    int globalMinimumDifference;
    int stoneCount;

    void validateInputRange(int value, const string& attributeName) {
        if (value < 0) {
            throw runtime_error(attributeName + " value cannot be negative");
        }
    }

    void recursiveStoneSelection(int currentIndex, int cumulativeAnger, int cumulativeIrritability, bool atLeastOneSelected) {
        if (currentIndex >= stoneCount) {
            if (!atLeastOneSelected) {
                return;
            }
            int currentDifference = abs(cumulativeAnger - cumulativeIrritability);
            if (currentDifference < globalMinimumDifference) {
                globalMinimumDifference = currentDifference;
            }
            return;
        }

        int newAnger = cumulativeAnger;
        int newIrritability = cumulativeIrritability;
        bool selectionFlag = atLeastOneSelected;

        if (cumulativeAnger == 0) {
            newAnger = 1;
        }

        int tempAnger = newAnger * stones[currentIndex].anger;
        int tempIrritability = newIrritability + stones[currentIndex].irritability;

        recursiveStoneSelection(currentIndex + 1, tempAnger, tempIrritability, true);
        recursiveStoneSelection(currentIndex + 1, newAnger, newIrritability, selectionFlag);
    }

public:
    StoneConfigurationManager(int n) : stoneCount(n), globalMinimumDifference(numeric_limits<int>::max()) {
        stones.resize(n);
    }

