        for (int i = 0; i < stoneCount; ++i) {
            cin >> stones[i].anger >> stones[i].irritability;
            validateInputRange(stones[i].anger, "Anger");
            validateInputRange(stones[i].irritability, "Irritability");
        }
    }

    int computeMinimumDifference() {
        recursiveStoneSelection(0, 0, 0, false);
        return globalMinimumDifference;
    }
};

