class StoneProcessor {
private:
    vector<StoneAttributes> stones;
    int minDifference;
    int totalStones;

    void validateInputRange(int value, const string& attributeName) {
        if (value < 0) {
            throw runtime_error("Negative value not allowed for " + attributeName);
        }
    }

    void recursiveSearch(int currentIndex, int productAnger, int sumIrritability, bool atLeastOneSelected) {
        if (currentIndex >= totalStones) {
            if (atLeastOneSelected) {
                int currentDifference = abs(productAnger - sumIrritability);
                if (currentDifference < minDifference) {
                    minDifference = currentDifference;
                }
            }
            return;
        }

        int newProduct = productAnger;
        int newSum = sumIrritability;
        bool selectionFlag = atLeastOneSelected;

        if (productAnger == 0) {
            newProduct = stones[currentIndex].anger;
        } else {
            newProduct *= stones[currentIndex].anger;
        }
        newSum += stones[currentIndex].irritability;

        recursiveSearch(currentIndex + 1, newProduct, newSum, true);
        recursiveSearch(currentIndex + 1, productAnger, sumIrritability, atLeastOneSelected);
    }

public:
    StoneProcessor(int n) : totalStones(n), minDifference(INT_MAX) {
        stones.resize(n);
    }

