#include <iostream>
#include <limits>
#include <stdexcept>
#include <type_traits>
#include <cmath>
using namespace std;

template<typename T>
constexpr bool is_safe_abs(T value) {
    return !(numeric_limits<T>::is_signed && value == numeric_limits<T>::min());
}

template<typename T>
T checked_abs(T value) {
    static_assert(is_integral<T>::value, "Type must be integral");
    if (!is_safe_abs(value)) {
        throw overflow_error("Absolute value overflow detected");
    }
    return value < 0 ? -value : value;
}

struct AbsoluteComparator {
    bool operator()(int a, int b) const {
        try {
            int abs_a = checked_abs(a);
            int abs_b = checked_abs(b);

            if (abs_a != abs_b) {
                return abs_a < abs_b;
            } else {
                if (a == b) {
                    return false;
                } else if (a < b) {
                    return true;
                } else {
                    return false;
                }
            }
        } catch (const overflow_error& e) {
            cerr << "Error: " << e.what() << endl;
            terminate();
        }
    }
};

void validate_input_stream(istream& is) {
    if (is.fail()) {
        is.clear();
        is.ignore(numeric_limits<streamsize>::max(), '\n');
