#include <iostream>
#include <algorithm>
#include <vector>
#include <string>
#include <sstream>
#include <cctype>
#include <stdexcept>
#include <limits>
using namespace std;

class NumberPlateValidator {
public:
    static bool validate(const string& s) {
        if (s.empty() || s.size() > 10) return false;
        for (char c : s) {
            if (!isdigit(c)) return false;
        }
        return true;
    }
};

class NumberPlateProcessor {
private:
    static int calculateSum(const string& s) {
        int sum = 0;
        for (char c : s) {
            sum += c - '0';
        }
        return sum;
    }

    static long long toNumber(const string& s) {
        long long num = 0;
        for (char c : s) {
            num = num * 10 + (c - '0');
        }
        return num;
    }

public:
    static pair<int, long long> process(const string& s) {
        if (!NumberPlateValidator::validate(s)) {
            throw invalid_argument("Invalid number plate format");
        }
        return {calculateSum(s), toNumber(s)};
    }
};

class NumberPlateComparator {
public:
    bool operator()(const string& a, const string& b) {
        auto [sum_a, num_a] = NumberPlateProcessor::process(a);
        auto [sum_b, num_b] = NumberPlateProcessor::process(b);

        if (sum_a != sum_b) {
            return sum_a < sum_b;
        }

        if (num_a != num_b) {
            return num_a > num_b;
        }

        return a.length() > b.length();
    }
};

class InputHandler {
public:
    static vector<string> readInput() {
        vector<string> plates;
        string line;
        getline(cin, line);

        int n;
        try {
            n = stoi(line);
            if (n < 1 || n > 10000) {
                throw out_of_range("Invalid number of plates");
            }
        } catch (...) {
            cerr << "Invalid input for number of plates" << endl;
            exit(1);
        }

        plates.reserve(n);
        for (int i = 0; i < n; ++i) {
            getline(cin, line);
            if (!NumberPlateValidator::validate(line)) {
                cerr << "Invalid plate format at position " << i+1 << endl;
                exit(1);
            }
            plates.push_back(line);
        }

        if (plates.empty()) {
            cerr << "No plates provided" << endl;
            exit(1);
        }

        return plates;
    }
};

class PositionFinder {
public:
    static int findPosition(const vector<string>& plates, const string& target) {
        vector<string> sorted = plates;
        sort(sorted.begin(), sorted.end(), NumberPlateComparator());

        for (size_t i = 0; i < sorted.size(); ++i) {
            if (sorted[i] == target) {
                return i + 1;
            }
        }

        return -1;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    try {
        vector<string> plates = InputHandler::readInput();
        if (plates.empty()) {
            cerr << "Error: Empty plate list" << endl;
            return 1;
        }

        string target = plates.back();
        if (!NumberPlateValidator::validate(target)) {
            cerr << "Error: Invalid target plate" << endl;
            return 1;
        }

        int position = PositionFinder::findPosition(plates, target);
        if (position == -1) {
            cerr << "Error: Target plate not found in sorted list" << endl;
            return 1;
        }

        cout << position << endl;
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
