    private:
        static pair<int, int> getAbsolutePair(int x, int y) {
            return make_pair(
                (x < 0) ? -x : x,
                (y < 0) ? -y : y
            );
        }

        static bool shouldSwapValues(int x, int y) {
            auto absPair = getAbsolutePair(x, y);
            if (absPair.first == absPair.second) {
                return x > y;
            }
            return absPair.first > absPair.second;
        }

    public:
        static vector<int> getSortedPair(int a, int b) {
            if (shouldSwapValues(a, b)) {
                return {b, a};
            }
            return {a, b};
        }
    };

