#include<bits/stdc++.h>
using namespace std;

const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const int LETTER_WRAPAROUND = 26;
const int NUMBER_WRAPAROUND = 10;

struct CharacterAnalysis {
    bool isLowercaseLetter;
    bool isDigit;
    bool isSpecialSequence;
    bool isSpaceReplacement;
    bool isDotReplacement;
};

CharacterAnalysis analyzeCharacter(const string& s, size_t i) {
    CharacterAnalysis result = {false, false, false, false, false};
    if (i + 2 < s.size()) {
        string triplet = s.substr(i, 3);
        result.isSpecialSequence = (triplet == SPACE_REPLACEMENT || triplet == DOT_REPLACEMENT);
        result.isSpaceReplacement = (triplet == SPACE_REPLACEMENT);
        result.isDotReplacement = (triplet == DOT_REPLACEMENT);
    }
    result.isLowercaseLetter = (s[i] >= 'a' && s[i] <= 'z');
    result.isDigit = (s[i] >= '0' && s[i] <= '9');
    return result;
}

char handleLetterShift(char c) {
    char shifted = c - SHIFT_VALUE;
    if (shifted < 'a') {
        int overflow = 'a' - shifted - 1;
        shifted = '9' - overflow % NUMBER_WRAPAROUND;
    }
    return shifted;
}

char handleDigitShift(char c) {
    char shifted = c - SHIFT_VALUE;
    if (shifted < '0') {
        int overflow = '0' - shifted - 1;
        shifted = 'z' - overflow % LETTER_WRAPAROUND;
    }
    return shifted;
}

string processString(const string& input) {
    string output;
    size_t i = 0;
    while (i < input.size()) {
        CharacterAnalysis analysis = analyzeCharacter(input, i);
        if (analysis.isSpecialSequence) {
            if (analysis.isSpaceReplacement) {
                output += ' ';
            } else if (analysis.isDotReplacement) {
                output += '.';
            }
            i += 3;
        } else {
            char current = input[i];
            char processed;
            if (analysis.isLowercaseLetter) {
                processed = handleLetterShift(current);
            } else if (analysis.isDigit) {
                processed = handleDigitShift(current);
            } else {
                processed = current;
            }
            output += processed;
            i++;
        }
    }
    return output;
}

int main() {
