            throw runtime_error("Invalid character in input");
        }
    }
}

vector<WordInfo> extractWordMetadata(const string& input) {
    vector<WordInfo> words;
    size_t start_pos = 0;
    bool in_word = false;
    bool current_word_valid = true;

    for (size_t i = 0; i <= input.size(); ++i) {
        if (i == input.size() || isspace(input[i])) {
            if (in_word) {
                size_t word_length = i - start_pos;
                words.push_back({
                    input.substr(start_pos, word_length),
                    start_pos,
                    word_length,
                    current_word_valid
                });
                in_word = false;
                current_word_valid = true;
            }
            if (i != input.size()) {
                start_pos = i + 1;
            }
        } else {
            if (!in_word) {
                in_word = true;
                start_pos = i;
            }
            if (!isalpha(input[i])) {
                current_word_valid = false;
            }
        }
    }

    if (words.empty()) {
        throw runtime_error("No words found in input");
    }

    return words;
}

WordInfo findLongestValidWord(const vector<WordInfo>& words) {
    WordInfo longest = {"", 0, 0, false};
    bool found_valid = false;

    for (const auto& word : words) {
        if (word.is_valid) {
            if (!found_valid || word.length > longest.length) {
                longest = word;
                found_valid = true;
            }
        }
    }

    if (!found_valid) {
        throw runtime_error("No valid words found");
    }

    for (const auto& word : words) {
        if (word.is_valid && word.length == longest.length && word.position < longest.position) {
            longest = word;
        }
    }

    return longest;
}

void outputResult(const WordInfo& result) {
    if (result.content.empty()) {
        throw runtime_error("Empty result content");
    }

    cout << result.content;

    if (result.content.size() != result.length) {
        throw runtime_error("Content length mismatch");
    }
}

int main() {
