using namespace std;

const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const char NUM_START = '0';
const char NUM_END = '9';
const char LETTER_START = 'a';
const char LETTER_END = 'z';
const char NUM_WRAP_START = '7';
const char LETTER_WRAP_START = 'x';

string performSafeReplace(const string& input, const string& from, const string& to) {
    string result = input;
    size_t pos = 0;
    while(true) {
        pos = result.find(from, pos);
        if(pos == string::npos) break;
        if(pos + from.length() > result.length()) {
            throw runtime_error("Invalid replacement position");
        }
        result.replace(pos, from.length(), to);
        pos += to.length();
    }
    return result;
}

char decryptChar(char c) {
    if(!isalnum(c) && c != '.' && c != ' ') {
        throw invalid_argument("Invalid character in input");
    }

    if(c >= 'd' && c <= 'z') {
        return static_cast<char>(c - SHIFT_VALUE);
    } else if(c >= '3' && c <= '9') {
        return static_cast<char>(c - SHIFT_VALUE);
    } else if(c >= 'a' && c <= 'c') {
        return static_cast<char>(NUM_WRAP_START + (c - LETTER_START));
    } else if(c >= '0' && c <= '2') {
        return static_cast<char>(LETTER_WRAP_START + (c - NUM_START));
    }
    return c;
}

string decryptString(const string& s) {
    string intermediate = s;
    try {
        intermediate = performSafeReplace(intermediate, DOT_REPLACEMENT, ".");
        intermediate = performSafeReplace(intermediate, SPACE_REPLACEMENT, " ");
    } catch(const exception& e) {
        cerr << "Replacement error: " << e.what() << endl;
        return "";
    }

    string result;
    for(size_t i = 0; i < intermediate.size(); ++i) {
        char current = intermediate[i];
        try {
            if(isalnum(current)) {
                result += decryptChar(current);
            } else {
                result += current;
            }
        } catch(const exception& e) {
            cerr << "Decryption error at position " << i << ": " << e.what() << endl;
            return "";
        }
    }

    return result;
}

int main() {
