BigNumber validate_and_parse_input(const string& input) {
    BigNumber num;
    num.is_valid = true;
    num.original_input = input;

    if (input.empty()) {
        num.is_valid = false;
        return num;
    }

    for (char c : input) {
        if (!isdigit(c)) {
            num.is_valid = false;
            return num;
