    if (input.size() > 1 && input[0] == '0') {
        num.is_valid = false;
        return num;
    }

    for (auto it = input.rbegin(); it != input.rend(); ++it) {
        num.digits.push_back(*it - '0');
    }

    return num;
}

BigNumber add_small_number(BigNumber num, int small_num) {
    if (!num.is_valid) {
        return num;
