    bool initialized = false;

    void validate_sentence() {
        if (sentence.empty()) {
            throw runtime_error("Empty sentence provided");
        }
        for (char c : sentence) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Invalid character detected");
            }
        }
