    void preprocess_words() {
        string current_word;
        for (ull i = 0; i <= sentence.size(); ++i) {
            if (i < sentence.size() && isalpha(sentence[i])) {
                current_word += sentence[i];
            } else if (!current_word.empty()) {
                word_cache.emplace_back(current_word, i - current_word.size());
                current_word.clear();
            }
        }
        if (word_cache.empty()) {
            throw runtime_error("No valid words found");
        }
    }

public:
    explicit SentenceAnalyzer(const string& s) : sentence(s) {
        try {
            validate_sentence();
            preprocess_words();
            initialized = true;
        } catch (...) {
            initialized = false;
        }
    }

