        if (!initialized) {
            return "";
        }

        ull max_length = numeric_limits<ull>::min();
        string result;
        ull earliest_position = numeric_limits<ull>::max();

        for (const auto& entry : word_cache) {
            const string& word = entry.first;
            ull position = entry.second;

            if (word.length() > max_length) {
                max_length = word.length();
                result = word;
                earliest_position = position;
            } else if (word.length() == max_length) {
                if (position < earliest_position) {
