    class WidthCalculator {
    public:
        static size_t calculateRequiredWidth(const string& str, size_t targetWidth) {
            if (str.length() >= targetWidth) {
                return str.length();
            }
            return targetWidth;
        }
    };
}

class InputProcessor {
private:
    static const int INPUT_COUNT = 3;
    vector<int> values;

    void validateInputCount(const vector<string>& tokens) {
        if (tokens.size() != INPUT_COUNT) {
            throw runtime_error("Invalid input count");
        }
    }

    void parseValues(const vector<string>& tokens) {
        for (const auto& token : tokens) {
            try {
                int val = stoi(token);
                if (!FormatUtils::IntegerValidator::validateRange(val)) {
                    throw out_of_range("Value out of range");
                }
                values.push_back(val);
            } catch (const invalid_argument&) {
                throw invalid_argument("Invalid integer format");
            } catch (const out_of_range&) {
                throw out_of_range("Integer out of range");
            }
        }
    }

public:
    void process() {
        string line;
        getline(cin, line);
        istringstream iss(line);
        vector<string> tokens;
        string token;

        while (iss >> token) {
            tokens.push_back(token);
        }

        validateInputCount(tokens);
        parseValues(tokens);
    }

    const vector<int>& getValues() const {
        return values;
    }
};

class OutputFormatter {
private:
    static const int FIELD_WIDTH = 8;
    vector<int> values;

    string formatSingleValue(int value) {
        ostringstream oss;
        oss << setw(FIELD_WIDTH) << right << value;
        string formatted = oss.str();
        string trimmed;
        remove_copy(formatted.begin(), formatted.end(), back_inserter(trimmed), '\0');
        return trimmed;
    }

public:
    OutputFormatter(const vector<int>& vals) : values(vals) {}

    string format() {
        if (values.size() != 3) {
            throw logic_error("Invalid value count for formatting");
        }

        string result;
        for (size_t i = 0; i < values.size(); ++i) {
            result += formatSingleValue(values[i]);
            if (i != values.size() - 1) {
                result += " ";
            }
        }
        return result;
    }
};

