#include <type_traits>
#include <vector>
#include <algorithm>

template<typename T>
void validateInputRange(const T& value) {
    if (!std::is_integral<T>::value) {
        throw std::invalid_argument("Input must be an integer");
    }
    if (value < std::numeric_limits<int>::min() || value > std::numeric_limits<int>::max()) {
        throw std::out_of_range("Input out of int range");
    }
}

std::vector<std::string> tokenizeInput(const std::string& input) {
    std::vector<std::string> tokens;
    std::istringstream iss(input);
    std::string token;
    while (iss >> token) {
        tokens.push_back(token);
    }
    if (tokens.size() != 3) {
        throw std::length_error("Exactly three integers required");
    }
    return tokens;
}

template<typename T>
T convertAndValidate(const std::string& str) {
    try {
        size_t pos;
        long val = std::stol(str, &pos);
        if (pos != str.length()) {
            throw std::invalid_argument("Invalid characters in input");
        }
        validateInputRange(val);
        return static_cast<T>(val);
    } catch (const std::invalid_argument&) {
        throw std::invalid_argument("Invalid integer format");
    } catch (const std::out_of_range&) {
        throw std::out_of_range("Integer out of range");
    }
}

void formatOutput(int a, int b, int c) {
    std::ios_base::fmtflags flags = std::cout.flags();
    std::streamsize prevPrecision = std::cout.precision();
    char prevFill = std::cout.fill();

    try {
        std::cout << std::right << std::setw(8) << a << " ";
        std::cout << std::right << std::setw(8) << b << " ";
        std::cout << std::right << std::setw(8) << c;
    } catch (...) {
        std::cout.flags(flags);
        std::cout.precision(prevPrecision);
        std::cout.fill(prevFill);
        throw;
    }

    std::cout.flags(flags);
    std::cout.precision(prevPrecision);
    std::cout.fill(prevFill);
}

int main() {
    try {
        std::string inputLine;
        std::getline(std::cin, inputLine);
        std::vector<std::string> tokens = tokenizeInput(inputLine);

        int a = convertAndValidate<int>(tokens[0]);
        int b = convertAndValidate<int>(tokens[1]);
        int c = convertAndValidate<int>(tokens[2]);

        formatOutput(a, b, c);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
