#include<bits/stdc++.h>
using namespace std;

struct CompressionState {
    string accumulated_pattern;
    vector<int> compression_sequence;
    char previous_value;
    int current_count;
    bool initialization_flag;
    bool dimension_output_flag;
    bool error_encountered;
};

void initialize_compression_state(CompressionState& state) {
    state.accumulated_pattern = "";
    state.compression_sequence.clear();
    state.previous_value = '\0';
    state.current_count = 0;
    state.initialization_flag = false;
    state.dimension_output_flag = false;
    state.error_encountered = false;
}

void process_character(CompressionState& state, char current_char) {
    if (!state.initialization_flag) {
        state.previous_value = current_char;
        state.current_count = 1;
        state.initialization_flag = true;
    } else {
        if (current_char == state.previous_value) {
            state.current_count++;
        } else {
            state.compression_sequence.push_back(state.current_count);
            state.previous_value = current_char;
            state.current_count = 1;
        }
    }
}

void finalize_compression(CompressionState& state) {
    if (state.current_count > 0) {
        state.compression_sequence.push_back(state.current_count);
    }
}

void validate_dimensions(CompressionState& state) {
    int calculated_size = state.accumulated_pattern.size();
    int dimension = sqrt(calculated_size);
    if (dimension * dimension != calculated_size) {
        state.error_encountered = true;
    }
}

void output_compression_result(CompressionState& state) {
    ofstream output_file("zip.out");
    if (output_file.is_open() && !state.error_encountered) {
        int dimension = sqrt(state.accumulated_pattern.size());
        output_file << dimension << " ";
        for (size_t i = 0; i < state.compression_sequence.size(); ++i) {
            output_file << state.compression_sequence[i];
            if (i != state.compression_sequence.size() - 1) {
                output_file << " ";
            }
        }
        output_file.close();
    }
}

int main() {
    ifstream input_file("zip.in");
    CompressionState compression_state;
    initialize_compression_state(compression_state);

    if (input_file.is_open()) {
        string current_line;
        while (getline(input_file, current_line)) {
            compression_state.accumulated_pattern += current_line;
            for (char c : current_line) {
                if (c != '0' && c != '1') {
                    compression_state.error_encountered = true;
                    break;
                }
                process_character(compression_state, c);
            }
            if (compression_state.error_encountered) break;
        }
        input_file.close();
    } else {
        compression_state.error_encountered = true;
    }

    if (!compression_state.error_encountered) {
        validate_dimensions(compression_state);
        if (!compression_state.error_encountered) {
            finalize_compression(compression_state);
            output_compression_result(compression_state);
        }
    }

    return compression_state.error_encountered ? 1 : 0;
}
