struct DataSet {
    int originalX;
    int originalY;
    int minVal;
    int maxVal;
    int difference;
    int index;
};

int validateInput(int value, int min, int max, const string& paramName) {
    if (value < min || value > max) {
        throw out_of_range(paramName + " out of valid range");
    }
    return value;
}

void processDataSet(DataSet& ds, int x, int y, int idx) {
    try {
        ds.originalX = validateInput(x, 1, 20, "X");
        ds.originalY = validateInput(y, 1, 20, "Y");
        ds.minVal = min(x, y);
        ds.maxVal = max(x, y);
        ds.difference = abs(x - y);
        ds.index = idx;
    } catch (const exception& e) {
        cerr << "Error processing data set " << idx << ": " << e.what() << endl;
        ds.difference = -1;
    }
}

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.difference != b.difference) {
        return a.difference > b.difference;
    }
    if (a.minVal != b.minVal) {
        return a.minVal < b.minVal;
    }
    return a.index < b.index;
}

int main() {
    int N = 0;
    vector<DataSet> dataSets;

    try {
        cin >> N;
        N = validateInput(N, 1, 100, "N");

        dataSets.resize(N);

        for (int i = 0; i < N; ++i) {
            int x, y;
            cin >> x >> y;
            processDataSet(dataSets[i], x, y, i);
        }

        if (dataSets.empty()) {
            throw runtime_error("No valid data sets processed");
        }

        sort(dataSets.begin(), dataSets.end(), compareDataSets);

        DataSet bestSet = dataSets[0];
        for (size_t i = 1; i < dataSets.size(); ++i) {
            if (dataSets[i].difference < 0) continue;
            if (compareDataSets(dataSets[i], bestSet)) {
                bestSet = dataSets[i];
            }
        }

        if (bestSet.difference < 0) {
            throw runtime_error("No valid data sets found");
        }

        cout << bestSet.originalX << " " << bestSet.originalY << endl;

    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
