    private:
        static int getPrecedence(const string& op) {
            static const map<string, int> precedence = {
                {"+", 1}, {"-", 1}, {"*", 2}, {"/", 2}
            };
            auto it = precedence.find(op);
            if (it != precedence.end()) return it->second;
            return -1;
        }

        static bool isOperator(const string& token) {
            static const vector<string> ops = {"+", "-", "*", "/"};
            return find(ops.begin(), ops.end(), token) != ops.end();
        }

