                    while (!opStack.empty() && getPrecedence(opStack.top()) >= getPrecedence(token)) {
                        output.push_back(opStack.top());
                        opStack.pop();
                    }
                    opStack.push(token);
                }
            }
            while (!opStack.empty()) {
                output.push_back(opStack.top());
                opStack.pop();
            }
            return output;
        }
    };

    class Evaluator {
    public:
