public:
    CyclicShifter(int z) : shiftAmount(z) {
        if (!validateShift(z)) {
            throw invalid_argument("Invalid shift value");
        }
    }
    char shiftAlphaUpper(char c) {
        if (!CharacterValidation::isValidAlpha(c) || !isupper(c)) {
            return c;
        }
        int base = 'A';
        int range = 26;
        return (c - base + shiftAmount % range + range) % range + base;
    }
    char shiftAlphaLower(char c) {
        if (!CharacterValidation::isValidAlpha(c) || !islower(c)) {
            return c;
        }
        int base = 'a';
        int range = 26;
        return (c - base + shiftAmount % range + range) % range + base;
    }
    char shiftNumeric(char c) {
        if (!CharacterValidation::isValidNum(c)) {
            return c;
        }
        int base = '0';
        int range = 10;
        return (c - base + shiftAmount % range + range) % range + base;
    }
