vector<int> meat_indices;

void validate_input(int value, int min_val, int max_val, const string& name) {
    if (value < min_val || value > max_val) {
        throw runtime_error("Invalid input value for " + name);
    }
}

void read_dishes(istream& in, int count, bool is_vegetarian) {
    vector<int> prices(count);
    vector<int> deliciousness(count);

    for (int i = 0; i < count; ++i) {
        in >> prices[i];
        validate_input(prices[i], 1, MAX_BUDGET, "dish price");
    }

    for (int i = 0; i < count; ++i) {
        in >> deliciousness[i];
        validate_input(deliciousness[i], 1, 100000, "dish deliciousness");
    }

    for (int i = 0; i < count; ++i) {
        Dish dish;
        dish.price = prices[i];
        dish.deliciousness = deliciousness[i];
        dish.is_vegetarian = is_vegetarian;
        dishes.push_back(dish);
        if (is_vegetarian) {
            vegetarian_indices.push_back(dishes.size() - 1);
        } else {
            meat_indices.push_back(dishes.size() - 1);
        }
    }
}

int solve_knapsack(int budget, bool require_vegetarian) {
    memset(dp, 0, sizeof(dp));
    int flag = 1;

    for (size_t i = 0; i < dishes.size(); ++i) {
        if (require_vegetarian && !dishes[i].is_vegetarian) continue;

        for (int j = 0; j <= budget; ++j) {
            if (j >= dishes[i].price) {
                dp[flag][j] = max(dp[1 - flag][j - dishes[i].price] + dishes[i].deliciousness, 
                                 dp[1 - flag][j]);
            } else {
                dp[flag][j] = dp[1 - flag][j];
            }
        }
        flag = 1 - flag;
    }

    return dp[1 - flag][budget];
}

int main() {
    ifstream fin("health.in");
    ofstream fout("health.out");

    if (!fin.is_open() || !fout.is_open()) {
        cerr << "Failed to open files" << endl;
        return EXIT_FAILURE;
    }

    int N, M, X;
    fin >> N >> M >> X;

