struct ElevatorConfiguration {
    const long long RISE_TIME_PER_FLOOR = 5;
    const long long DESCEND_TIME_PER_FLOOR = 4;
    const long long DOOR_OPEN_TIME = 3;
    const long long PERSON_EXIT_TIME = 2;
    const long long INITIAL_FLOOR = 0;
};

class ElevatorTimeCalculator {
private:
    long long total_time;
    long long passenger_count;
    vector<long long> destination_floors;
    ElevatorConfiguration config;

    void validateInputFile(ifstream& input_file) {
        if (!input_file.is_open()) {
            throw system_error(error_code(errno, generic_category()), "Input file opening failed");
        }
    }

    void validateOutputFile(ofstream& output_file) {
        if (!output_file.is_open()) {
            throw system_error(error_code(errno, generic_category()), "Output file opening failed");
        }
    }

    void readInputData(ifstream& input_file) {
        string line;
        getline(input_file, line);
        stringstream ss(line);
        ss >> passenger_count;

        if (passenger_count < 1 || passenger_count > 100000) {
            throw out_of_range("Invalid passenger count");
        }

        getline(input_file, line);
        stringstream ss2(line);
        long long floor;
        while (ss2 >> floor) {
            if (floor < 1 || floor > 1000000000000) {
                throw out_of_range("Invalid floor number");
            }
            destination_floors.push_back(floor);
        }

        if (destination_floors.size() != passenger_count) {
            throw length_error("Mismatch between passenger count and destinations");
        }
    }

    void calculateTime() {
        map<long long, long long> floor_counts;
        for (const auto& floor : destination_floors) {
            floor_counts[floor]++;
        }

        long long previous_floor = config.INITIAL_FLOOR;
        for (const auto& entry : floor_counts) {
            long long current_floor = entry.first;
            long long passenger_count = entry.second;

            if (current_floor > previous_floor) {
                total_time += (current_floor - previous_floor) * config.RISE_TIME_PER_FLOOR;
            } else if (current_floor < previous_floor) {
                total_time += (previous_floor - current_floor) * config.DESCEND_TIME_PER_FLOOR;
            }

            total_time += config.DOOR_OPEN_TIME;
            total_time += passenger_count * config.PERSON_EXIT_TIME;

            previous_floor = current_floor;
        }

        if (previous_floor != config.INITIAL_FLOOR) {
            total_time += previous_floor * config.DESCEND_TIME_PER_FLOOR;
        }
    }

public:
    ElevatorTimeCalculator() : total_time(0), passenger_count(0) {}

    void process() {
        ifstream input_file("elevator.in");
        validateInputFile(input_file);

        readInputData(input_file);
        input_file.close();

        calculateTime();

        ofstream output_file("elevator.out");
        validateOutputFile(output_file);
        output_file << total_time << endl;
        output_file.close();
    }
};

int main() {
