struct InputValidator {
    static void validateStreamState(const istream& stream) {
        if (stream.fail()) {
            throw runtime_error("Input stream failure detected");
        }
    }

    static void checkIntegerRange(long long value) {
        if (value < numeric_limits<int>::min() || value > numeric_limits<int>::max()) {
            throw out_of_range("Input value exceeds integer range");
        }
    }
};

class FormattedOutputGenerator {
private:
    int firstValue;
    int secondValue;
    int thirdValue;

public:
    FormattedOutputGenerator(int a, int b, int c) : firstValue(a), secondValue(b), thirdValue(c) {}

    string generateFormattedString() const {
        ostringstream oss;
        oss << right << setw(8) << firstValue << " " 
            << right << setw(8) << secondValue << " " 
            << right << setw(8) << thirdValue;
        return oss.str();
    }
};

int main() {
    try {
        string rawInput;
        getline(cin, rawInput);

        istringstream inputParser(rawInput);
        long long tempA, tempB, tempC;
        inputParser >> tempA >> tempB >> tempC;

        InputValidator::validateStreamState(inputParser);
        InputValidator::checkIntegerRange(tempA);
        InputValidator::checkIntegerRange(tempB);
        InputValidator::checkIntegerRange(tempC);

        int validatedA = static_cast<int>(tempA);
        int validatedB = static_cast<int>(tempB);
        int validatedC = static_cast<int>(tempC);

        FormattedOutputGenerator outputFormatter(validatedA, validatedB, validatedC);
        string formattedOutput = outputFormatter.generateFormattedString();

