#include<bits/stdc++.h>
using namespace std;

const int MAX_STONES = 15;
const int MAX_ANGER = 1e9;
const int MAX_IRRITABILITY = 1e9;

struct StoneValidationResult {
    bool isValid;
    string errorMessage;
};

struct StoneConfiguration {
    int angerProduct;
    int irritabilitySum;
    int stoneCount;
};

class StoneValidator {
public:
    static StoneValidationResult validateStone(int anger, int irritability) {
        StoneValidationResult result;
        result.isValid = true;

        if (anger <= 0 || anger > MAX_ANGER) {
            result.isValid = false;
            result.errorMessage = "Invalid anger value detected";
        }

        if (irritability < 0 || irritability > MAX_IRRITABILITY) {
            result.isValid = false;
            result.errorMessage = "Invalid irritability value detected";
        }

        return result;
    }
};

class StoneProcessor {
private:
    vector<pair<int, int>> stones;
    int minDifference;
    int totalStones;

    void processConfiguration(const StoneConfiguration& config) {
        if (config.stoneCount == 0) return;

        int currentDifference = abs(config.angerProduct - config.irritabilitySum);

        if (currentDifference < 0) {
            throw runtime_error("Negative difference calculated");
        }

        if (config.angerProduct < 0 || config.irritabilitySum < 0) {
            throw runtime_error("Negative product or sum detected");
        }

        if (minDifference == -1 || currentDifference < minDifference) {
            minDifference = currentDifference;
        }
    }

public:
    StoneProcessor(const vector<pair<int, int>>& s) : stones(s), minDifference(-1), totalStones(s.size()) {
        if (stones.empty()) {
            throw invalid_argument("No stones provided");
        }
    }

    void exploreCombinations(int index, StoneConfiguration current) {
        if (index >= totalStones) {
            processConfiguration(current);
            return;
        }

        if (index < 0 || index > totalStones) {
            throw out_of_range("Invalid stone index");
        }

        StoneConfiguration withStone = current;
        withStone.angerProduct *= stones[index].first;
        withStone.irritabilitySum += stones[index].second;
        withStone.stoneCount++;

        exploreCombinations(index + 1, withStone);
        exploreCombinations(index + 1, current);
    }

    int getMinDifference() {
        if (minDifference == -1) {
            throw logic_error("No valid configuration found");
        }
        return minDifference;
    }
};

int main() {
    ifstream inputFile("stone.in");
    ofstream outputFile("stone.out");

    if (!inputFile.is_open()) {
        cerr << "Failed to open input file" << endl;
        return EXIT_FAILURE;
    }

    if (!outputFile.is_open()) {
        cerr << "Failed to open output file" << endl;
        return EXIT_FAILURE;
    }

    int n;
    inputFile >> n;

    if (n <= 0 || n > 10) {
        cerr << "Invalid number of stones" << endl;
        return EXIT_FAILURE;
    }

    vector<pair<int, int>> stones(n);

    for (int i = 0; i < n; ++i) {
        inputFile >> stones[i].first >> stones[i].second;
        auto validation = StoneValidator::validateStone(stones[i].first, stones[i].second);
        if (!validation.isValid) {
            cerr << validation.errorMessage << endl;
            return EXIT_FAILURE;
        }
    }

    try {
        StoneProcessor processor(stones);
        StoneConfiguration initialConfig{1, 0, 0};
        processor.exploreCombinations(0, initialConfig);
        outputFile << processor.getMinDifference();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    inputFile.close();
    outputFile.close();

    return EXIT_SUCCESS;
}
