        }
    }
    return {true, ""};
}

void initializeDishes(vector<Dish>& dishes, const vector<int>& prices, const vector<int>& deliciousness) {
    for (size_t i = 0; i < prices.size(); ++i) {
        dishes.push_back({prices[i], deliciousness[i], false});
    }
}

int calculateMaxDeliciousness(int x, vector<Dish>& veg, vector<Dish>& meat) {
    vector<int> dp(x + 1, -1);
    dp[0] = 0;

    for (auto& v : veg) {
        for (int j = x; j >= v.price; --j) {
            if (dp[j - v.price] != -1) {
                if (dp[j] < dp[j - v.price] + v.deliciousness) {
                    dp[j] = dp[j - v.price] + v.deliciousness;
                }
            }
        }
    }

    vector<int> temp_dp = dp;
    int max_deliciousness = 0;

    for (int i = 0; i <= x; ++i) {
        if (temp_dp[i] != -1) {
            vector<int> meat_dp = temp_dp;
            for (auto& h : meat) {
                for (int j = x; j >= h.price + i; --j) {
                    if (meat_dp[j - h.price] != -1) {
                        if (meat_dp[j] < meat_dp[j - h.price] + h.deliciousness) {
                            meat_dp[j] = meat_dp[j - h.price] + h.deliciousness;
                        }
                    }
                }
            }
            if (meat_dp[x] > max_deliciousness) {
                max_deliciousness = meat_dp[x];
            }
        }
    }

    return max_deliciousness;
}

