bool is_leap_year(int year) {
    bool leap_year_flag = false;
    bool divisible_by_4 = (year % 4 == 0);
    bool divisible_by_100 = (year % 100 == 0);
    bool divisible_by_400 = (year % 400 == 0);

    if (divisible_by_4) {
        if (divisible_by_100) {
            if (divisible_by_400) {
                leap_year_flag = true;
            } else {
                leap_year_flag = false;
            }
        } else {
            leap_year_flag = true;
        }
    } else {
        leap_year_flag = false;
    }

    return leap_year_flag;
}

void validate_input(int year, int month) {
    bool year_valid = (year >= 1600 && year <= 3000);
    bool month_valid = (month >= 1 && month <= 12);

    if (!year_valid || !month_valid) {
        throw invalid_argument("Invalid input range");
    }
}

int get_days_in_month(int year, int month) {
    int days = 0;
    bool leap_year = is_leap_year(year);

    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            days = 31;
            break;
        case 4: case 6: case 9: case 11:
            days = 30;
            break;
        case 2:
            days = leap_year ? 29 : 28;
            break;
        default:
            throw runtime_error("Invalid month value");
    }

    return days;
}

