char processLowerCase(char c, int shift) {
    int normalizedShift = shift % 26;
    int base = 'a';
    int offset = (c - base + normalizedShift) % 26;
    if (offset < 0) {
        offset += 26;
    }
    return static_cast<char>(base + offset);
}

char processUpperCase(char c, int shift) {
    int normalizedShift = shift % 26;
    int base = 'A';
    int offset = (c - base + normalizedShift) % 26;
    if (offset < 0) {
        offset += 26;
    }
    return static_cast<char>(base + offset);
}

char processDigit(char c, int shift) {
    int normalizedShift = shift % 10;
    int base = '0';
    int offset = (c - base + normalizedShift) % 10;
    if (offset < 0) {
        offset += 10;
    }
    return static_cast<char>(base + offset);
}

