const string OUTPUT_FILE = "bigadd.out";

struct BigNumber {
    vector<int> digits;
    bool is_valid;
    string original_input;
};

BigNumber validate_and_parse_input(const string& input) {
    BigNumber num;
    num.is_valid = false;
    num.original_input = input;

    if (input.empty()) {
        return num;
    }

    for (char c : input) {
        if (!isdigit(c)) {
            return num;
        }
    }

    if (input.size() > MAX_DIGITS) {
        return num;
    }

    num.digits.resize(input.size());
    transform(input.rbegin(), input.rend(), num.digits.begin(), 
        [](char c) { return c - '0'; });

    num.is_valid = true;
    return num;
}

void handle_carry(BigNumber& num) {
    int carry = 0;
    for (size_t i = 0; i < num.digits.size(); ++i) {
        int current = num.digits[i] + carry;
        num.digits[i] = current % 10;
        carry = current / 10;
    }
    while (carry > 0) {
        num.digits.push_back(carry % 10);
        carry /= 10;
    }
}

string big_number_to_string(const BigNumber& num) {
    string result;
    for (auto it = num.digits.rbegin(); it != num.digits.rend(); ++it) {
        result += to_string(*it);
    }
    return result;
}

void write_output(const string& output) {
    ofstream out_file(OUTPUT_FILE);
    if (!out_file.is_open()) {
        throw runtime_error("Failed to open output file");
    }
    out_file << output;
    out_file.close();
}

int main() {
