        ifstream in_file(INPUT_FILE);
        if (!in_file.is_open()) {
            throw runtime_error("Failed to open input file");
        }

        string input;
        if (!(in_file >> input)) {
            throw runtime_error("Failed to read input");
        }
        in_file.close();

        BigNumber num = validate_and_parse_input(input);
        if (!num.is_valid) {
            throw runtime_error("Invalid input format");
        }

        if (num.digits.empty()) {
            throw runtime_error("Empty number");
        }

        if (num.digits.size() < 4) {
            num.digits.resize(4, 0);
        }

        num.digits[0] += 8;
        num.digits[1] += 1;
        num.digits[2] += 0;
        num.digits[3] += 2;

