            num->is_valid = false;
            return;
        }
        num->digits[current_position + 1] += num->digits[current_position] / 10;
        num->digits[current_position] %= 10;
        current_position++;
    }
    if (current_position > num->length) {
        num->length = current_position;
    }
}

void adjustLength(BigNumber* num) {
    while (num->length > 0 && num->digits[num->length - 1] == 0) {
        num->length--;
    }
    if (num->length == 0) {
        num->length = 1;
    }
}

string bigNumberToString(const BigNumber& num) {
    if (!num.is_valid) {
        return "INVALID_RESULT";
    }
    string result;
    for (int i = num.length - 1; i >= 0; --i) {
        result += to_string(num.digits[i]);
    }
    return result;
}

void performFileOperations() {
    ifstream input_file("bigadd.in");
    ofstream output_file("bigadd.out");

    if (!input_file.is_open() || !output_file.is_open()) {
