void processBalloons(Balloon balloons[], int m) {
    for (int i = 1; i <= m; i++) {
        if (balloons[i].height <= 0 || balloons[i].height > 100000) {
            throw runtime_error("Invalid balloon height");
        }
        balloons[i].taken = false;
        balloons[i].taken_by = -1;
    }
}

void findPotentialBalloons(Child& child, Balloon balloons[], int m) {
    for (int i = 1; i <= m; i++) {
        if (!balloons[i].taken && balloons[i].height <= child.jump_height) {
            child.potential_balloons.push_back(i);
        }
    }
}

void assignBalloons(Child children[], Balloon balloons[], int n, int m) {
    for (int i = 1; i <= n; i++) {
        if (children[i].processed) continue;

        findPotentialBalloons(children[i], balloons, m);

        for (int balloon_idx : children[i].potential_balloons) {
            if (!balloons[balloon_idx].taken) {
                balloons[balloon_idx].taken = true;
                balloons[balloon_idx].taken_by = children[i].id;
                children[i].balloons_taken++;
            }
        }

        children[i].processed = true;
    }
}

void verifyUniqueJumpHeights(Child children[], int n) {
    unordered_set<int> seen_heights;
    for (int i = 1; i <= n; i++) {
        if (seen_heights.count(children[i].jump_height)) {
            throw runtime_error("Duplicate jump heights detected");
        }
        seen_heights.insert(children[i].jump_height);
