#include<iostream>
#include<string>
#include<vector>
#include<algorithm>
#include<cctype>
#include<sstream>
#include<iterator>
#include<memory>
#include<stdexcept>
#include<utility>
#include<limits>
using namespace std;

class StringProcessor {
private:
    vector<string> tokens;
    vector<bool> processedFlags;

    void validateInput(const string& s) {
        if (s.length() > numeric_limits<streamsize>::max()) {
            throw length_error("Input string too long");
        }
        for (char c : s) {
            if (!isprint(c) && !isspace(c)) {
                throw invalid_argument("Invalid character in input");
            }
        }
    }

    void caseConversion(string& s) {
        for (auto& c : s) {
            if (isupper(c) && c != 'I') {
                c = tolower(c);
            }
        }
    }

    void questionMarkConversion(string& s) {
        size_t pos = 0;
        while ((pos = s.find('?', pos)) {
            if (pos == string::npos) break;
            s.replace(pos, 1, "!");
            pos += 1;
            if (pos >= s.size()) break;
        }
    }

    void tokenizeString(const string& s) {
        istringstream iss(s);
        tokens = vector<string>(istream_iterator<string>{iss},
                                istream_iterator<string>());
        processedFlags = vector<bool>(tokens.size(), false);
    }

    bool isIndependentWord(size_t index) {
        if (index >= tokens.size()) return false;
        if (processedFlags[index]) return false;
        string word = tokens[index];
        if (word.empty()) return false;
        for (char c : word) {
            if (!isalpha(c) && c != '!' && c != '.' && c != ',') {
                return false;
            }
        }
        return true;
    }

    void applyRule3() {
        for (size_t i = 0; i < tokens.size(); ++i) {
            if (!isIndependentWord(i)) continue;
            if (i + 1 < tokens.size() && isIndependentWord(i + 1)) {
                if (tokens[i] == "can" && tokens[i + 1] == "you") {
                    tokens[i] = "I";
                    tokens[i + 1] = "can";
                    processedFlags[i] = true;
                    processedFlags[i + 1] = true;
                } else if (tokens[i] == "could" && tokens[i + 1] == "you") {
                    tokens[i] = "I";
                    tokens[i + 1] = "could";
                    processedFlags[i] = true;
                    processedFlags[i + 1] = true;
                }
            }
        }
    }

    void applyRule4() {
        for (size_t i = 0; i < tokens.size(); ++i) {
            if (!isIndependentWord(i)) continue;
            if (tokens[i] == "I" || tokens[i] == "me") {
                tokens[i] = "you";
                processedFlags[i] = true;
            }
        }
    }

    string reconstructString() {
        ostringstream oss;
        if (!tokens.empty()) {
            copy(tokens.begin(), prev(tokens.end()),
                ostream_iterator<string>(oss, " "));
            oss << tokens.back();
        }
        string result = oss.str();
        if (!result.empty() && result.back() == ' ') {
            result.pop_back();
        }
        return result;
    }

public:
    string processString(const string& input) {
        try {
            validateInput(input);
            string workingCopy = input;
            caseConversion(workingCopy);
            questionMarkConversion(workingCopy);
            tokenizeString(workingCopy);
            applyRule4();
