class CharacterProcessor {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;
    int x, y, z;
    vector<char> buffer;

    void validateInput() {
        if (!InputValidation::validateX(x)) throw runtime_error("Invalid x");
        if (!InputValidation::validateY(y)) throw runtime_error("Invalid y");
        if (!InputValidation::validateZ(z)) throw runtime_error("Invalid z");
    }

    bool shouldProcessCharacter(int pos) {
        if (y == 0) return false;
        return pos % y == 0;
    }

    char processLowercase(char c) {
        int offset = (tolower(c) - 'a' + z) % ALPHABET_SIZE;
        if (offset < 0) offset += ALPHABET_SIZE;
        return 'a' + offset;
    }

    char processUppercase(char c) {
        int offset = (toupper(c) - 'A' + z) % ALPHABET_SIZE;
        if (offset < 0) offset += ALPHABET_SIZE;
        return 'A' + offset;
    }

    char processDigit(char c) {
        int offset = (c - '0' + z) % DIGIT_SIZE;
        if (offset < 0) offset += DIGIT_SIZE;
        return '0' + offset;
    }

    char processCharacter(char c, int pos) {
        if (!shouldProcessCharacter(pos)) return c;

        if (islower(c)) {
            return processLowercase(c);
        } else if (isupper(c)) {
            return processUppercase(c);
        } else if (isdigit(c)) {
            return processDigit(c);
        } else {
            return c;
        }
    }

public:
