            }
            buffer.push_back(c);
            i++;
        }
    }

    void process() {
        for (size_t i = 0; i < buffer.size(); ++i) {
            buffer[i] = processCharacter(buffer[i], i + 1);
        }
    }

    void output() {
        for (char c : buffer) {
            cout << c;
        }
    }
};

