public:
    static bool isValidAlphabet(char c) {
        return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
    }
    static bool isValidNumber(char c) {
        return c >= '0' && c <= '9';
    }
    static bool isValidCharacter(char c) {
        return isValidAlphabet(c) || isValidNumber(c);
    }
};

class PositionCalculator {
