        if (y <= 0) throw invalid_argument("y must be positive");
        return (index + 1) % y == 0;
    }
};

class CharacterTransformer {
private:
    static char transformAlphabet(char c, int z) {
        if (isupper(c)) {
            int base = 'A';
            int offset = (c - base + z) % 26;
            if (offset < 0) offset += 26;
            return base + offset;
        } else {
            int base = 'a';
            int offset = (c - base + z) % 26;
            if (offset < 0) offset += 26;
            return base + offset;
        }
    }
    static char transformNumber(char c, int z) {
        int base = '0';
        int offset = (c - base + z) % 10;
        if (offset < 0) offset += 10;
        return base + offset;
    }
public:
