namespace ChaseEnemyUtils {
    const int SHOOTING_DISTANCE = 600;

    struct InputValidationError : public runtime_error {
        InputValidationError(const string& msg) : runtime_error(msg) {}
    };

    template<typename T>
    void validateInputRange(T value, T min_val, T max_val, const string& param_name) {
        if (value < min_val || value > max_val) {
            throw InputValidationError("Invalid input for " + param_name + ": out of range");
        }
    }

    void validateSpeedCondition(int a, int b) {
        if (b <= a) {
            throw InputValidationError("Troop speed must be greater than enemy speed");
        }
    }

    void validateInitialDistance(int initial_distance, int shooting_distance) {
        if (initial_distance <= shooting_distance) {
            throw InputValidationError("Initial distance must be greater than shooting distance");
        }
    }

    int calculateMinutesToShoot(int n, int a, int b) {
        const double epsilon = 1e-9;
        double initial_distance = n * a;
        validateInitialDistance(initial_distance, SHOOTING_DISTANCE);

        double relative_speed = b - a;
        if (fabs(relative_speed) < epsilon) {
            throw runtime_error("Division by near-zero in relative speed calculation");
        }

        double exact_minutes = (initial_distance - SHOOTING_DISTANCE) / relative_speed;

        if (isnan(exact_minutes) {
            throw runtime_error("NaN detected in time calculation");
        }

        if (isinf(exact_minutes)) {
            throw runtime_error("Infinite time detected");
        }

        int rounded_minutes = static_cast<int>(exact_minutes);
        if (exact_minutes - rounded_minutes > epsilon) {
            rounded_minutes++;
        }

        if (rounded_minutes < 0) {
            throw runtime_error("Negative time calculated");
        }

        return rounded_minutes;
    }
}

int main() {
