        int n, a, b;
        cin.exceptions(ios::failbit);

        if (!(cin >> n >> a >> b)) {
            throw ChaseEnemyUtils::InputValidationError("Invalid input format");
        }

        ChaseEnemyUtils::validateInputRange(n, 1, 1000, "n");
        ChaseEnemyUtils::validateInputRange(a, 1, 1000, "a");
        ChaseEnemyUtils::validateInputRange(b, 1, 1000, "b");
