        int initial_distance = n * a;
        ChaseEnemyUtils::validateInitialDistance(initial_distance, ChaseEnemyUtils::SHOOTING_DISTANCE);

        int result = ChaseEnemyUtils::calculateMinutesToShoot(n, a, b);

        cout << result << endl;

    } catch (const ios::failure& e) {
        cerr << "I/O error occurred: " << e.what() << endl;
        return 1;
    } catch (const ChaseEnemyUtils::InputValidationError& e) {
        cerr << "Input validation error: " << e.what() << endl;
        return 1;
    } catch (const exception& e) {
        cerr << "Unexpected error: " << e.what() << endl;
        return 1;
    }

