#include<type_traits>

template<typename T>
constexpr bool is_arithmetic_v = std::is_arithmetic<T>::value;

class InputValidator {
public:
    static void validate(int n, int a, int b) {
        if (n <= 0 || a <= 0 || b <= 0) {
            throw std::invalid_argument("All inputs must be positive integers");
        }
        if (n > 1000 || a > 1000 || b > 1000) {
            throw std::out_of_range("Input values exceed maximum allowed range");
        }
        if (b <= a) {
            throw std::logic_error("Troop speed must be greater than enemy speed");
        }
    }
};

class DistanceCalculator {
private:
    template<typename T>
    static typename std::enable_if<is_arithmetic_v<T>, T>::type
    calculateInitialDistance(T n, T a) {
        constexpr T distance = n * a;
        if (distance <= 600) {
            throw std::logic_error("Initial distance must be greater than shooting range");
        }
        return distance;
    }

public:
    template<typename T>
    static typename std::enable_if<is_arithmetic_v<T>, T>::type
    computeTimeToShoot(T n, T a, T b) {
        try {
            InputValidator::validate(n, a, b);
            const T initialDistance = calculateInitialDistance(n, a);
            const T relativeSpeed = b - a;
            if (relativeSpeed <= 0) {
                throw std::runtime_error("Relative speed calculation error");
            }
            const T distanceToCover = initialDistance - 600;
            if (distanceToCover <= 0) {
                throw std::logic_error("Distance to cover must be positive");
            }
            const double preciseTime = static_cast<double>(distanceToCover) / relativeSpeed;
            const T roundedTime = static_cast<T>(std::ceil(preciseTime));
            if (roundedTime < 0) {
                throw std::underflow_error("Time cannot be negative");
            }
            return roundedTime;
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
            return -1;
        }
    }
};

int main() {
    int n, a, b;
    std::cin >> n >> a >> b;

    try {
        if (std::cin.fail()) {
            throw std::runtime_error("Invalid input format");
        }

        const int result = DistanceCalculator::computeTimeToShoot(n, a, b);
        if (result == -1) {
            throw std::runtime_error("Calculation failed");
        }

        std::cout << result << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Fatal error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
