    constexpr T lower_bound = static_cast<T>(1);
    constexpr T upper_bound = static_cast<T>(1000);
    return (value >= lower_bound) && (value <= upper_bound);
}

template<typename T>
void check_input_constraints(T n, T a, T b) {
    if (!validate_input(n) || !validate_input(a) || !validate_input(b)) {
        throw invalid_argument("Input values must be between 1 and 1000");
    }
    if (b <= a) {
        throw logic_error("Troops speed must be greater than enemy speed");
    }
}

template<typename T>
T calculate_initial_distance(T n, T a) {
    constexpr T distance_constraint = static_cast<T>(600);
    T initial_distance = n * a;
    if (initial_distance <= distance_constraint) {
        throw domain_error("Enemy must be farther than shooting distance initially");
    }
    return initial_distance;
}

template<typename T>
T compute_time_to_shoot(T initial_distance, T a, T b) {
    constexpr T distance_constraint = static_cast<T>(600);
    T relative_speed = b - a;
    if (relative_speed <= numeric_limits<T>::epsilon()) {
        throw runtime_error("Relative speed must be positive");
    }
    T time = (initial_distance - distance_constraint) / relative_speed;
    return time;
}

template<typename T>
T handle_rounding(T time) {
    T integer_part = floor(time);
    T fractional_part = time - integer_part;
    constexpr T epsilon = numeric_limits<T>::epsilon();
    if (fractional_part > epsilon) {
        time = integer_part + static_cast<T>(1);
    }
    return time;
}

