        cin.exceptions(ios::failbit);
        cin >> n >> a >> b;
        check_input_constraints(n, a, b);
        int initial_distance = calculate_initial_distance(n, a);
        double time = compute_time_to_shoot<double>(initial_distance, a, b);
        time = handle_rounding(time);
        if (time < 0 || time > numeric_limits<int>::max()) {
