        if (g.p < 1 || g.p > 1000) throw runtime_error("Invalid gem price");
    }

    void update_gem_stats(const gem& g) {
        if (g.r < 0 || g.r >= MAX_TYPES) return;
        sum1[g.r] += static_cast<double>(g.p);
        num[g.r] += 1.0;
    }

    double calculate_average(int type) {
        if (type < 0 || type >= MAX_TYPES || num[type] == 0) return 0.0;
        return sum1[type] / num[type];
