        } catch (const exception& e) {
            cerr << "Error in dataset " << i+1 << ": " << e.what() << endl;
            continue;
        }

        int diff = computeDifference(x, y);
        int min_val = findMinimumValue(x, y);
        dataSets.push_back({x, y, diff, min_val, i});
    }

    if (dataSets.empty()) {
        cerr << "No valid data sets provided" << endl;
        return 1;
    }

    sort(dataSets.begin(), dataSets.end(), compareDataSets);

    DataSet bestSet = dataSets.front();
    for (const auto& ds : dataSets) {
        if (ds.diff == bestSet.diff && ds.min_val == bestSet.min_val && ds.index < bestSet.index) {
            bestSet = ds;
        }
    }

    cout << bestSet.x << ' ' << bestSet.y << endl;

    return 0;
}
