        return EXIT_FAILURE;
    }

    vector<pair<int, pair<int, int>>> dataSets;
    int globalMaxDifference = numeric_limits<int>::min();
    bool initializationFlag = false;

    for (int currentIteration = 0; currentIteration < N; ++currentIteration) {
        int X, Y;
        cin >> X >> Y;

        if (X < 1 || X > 20 || Y < 1 || Y > 20) {
            cerr << "Invalid input values" << endl;
            continue;
        }

        int currentDifference = abs(X - Y);
        int currentMin = min(X, Y);
        bool shouldUpdate = false;

        if (!initializationFlag) {
            globalMaxDifference = currentDifference;
            initializationFlag = true;
            shouldUpdate = true;
        } else if (currentDifference > globalMaxDifference) {
            globalMaxDifference = currentDifference;
            shouldUpdate = true;
        }

        if (shouldUpdate) {
            dataSets.clear();
            dataSets.push_back(make_pair(currentDifference, make_pair(X, Y)));
        } else if (currentDifference == globalMaxDifference) {
            dataSets.push_back(make_pair(currentDifference, make_pair(X, Y)));
        }
    }

    if (dataSets.empty()) {
        cerr << "No valid data sets found" << endl;
        return EXIT_FAILURE;
    }

    pair<int, int> resultPair = dataSets[0].second;
    int resultMin = min(resultPair.first, resultPair.second);

    for (size_t i = 1; i < dataSets.size(); ++i) {
        const auto& currentPair = dataSets[i].second;
        int currentMinValue = min(currentPair.first, currentPair.second);

        if (currentMinValue < resultMin) {
            resultMin = currentMinValue;
            resultPair = currentPair;
        } else if (currentMinValue == resultMin) {
            continue;
        }
    }

    cout << resultPair.first << ' ' << resultPair.second << endl;

    return EXIT_SUCCESS;
}
