  const unordered_map<int, double>& num_ref;

  gem_comparator(const unordered_map<int, double>& s, const unordered_map<int, double>& n) 
    : sumr_ref(s), num_ref(n) {}

  bool operator()(const gem& a, const gem& b) const {
