namespace CharacterValidation {
    template<typename T>
    constexpr bool is_alpha_numeric(T c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
    }

    template<typename T>
    constexpr bool is_lower(T c) {
        static_assert(is_integral<T>::value, "Type must be integral");
        return c >= 'a' && c <= 'z';
    }

    template<typename T>
    constexpr bool is_upper(T c) {
        static_assert(is_integral<T>::value, "Type must be integral");
        return c >= 'A' && c <= 'Z';
    }

    template<typename T>
    constexpr bool is_digit(T c) {
        static_assert(is_integral<T>::value, "Type must be integral");
        return c >= '0' && c <= '9';
    }
}

class CyclicShifter {
private:
    int shift_amount;
    int alphabet_size;

public:
    CyclicShifter(int z, int size = 26) : shift_amount(z % size), alphabet_size(size) {
        if (size <= 0) {
            throw invalid_argument("Alphabet size must be positive");
        }
    }

    char shift_char(char c) {
        char base;
        int current_size;

        if (CharacterValidation::is_lower(c)) {
            base = 'a';
            current_size = alphabet_size;
        } else if (CharacterValidation::is_upper(c)) {
            base = 'A';
            current_size = alphabet_size;
        } else if (CharacterValidation::is_digit(c)) {
            base = '0';
            current_size = 10;
        } else {
            return c;
        }

        int normalized = c - base;
        int shifted = (normalized + shift_amount) % current_size;
        if (shifted < 0) {
            shifted += current_size;
        }
        return static_cast<char>(base + shifted);
    }
};

