class RoadConditionParser {
private:
    static const vector<RoadCondition> knownConditions;
public:
    static RoadCondition parse(int code) {
        if (code < 1 || code > 50) {
            throw invalid_argument("Invalid road condition code");
        }

        auto it = find_if(knownConditions.begin(), knownConditions.end(),
            [code](const RoadCondition& rc) { return rc.code == code; });

        if (it != knownConditions.end()) {
            return *it;
        }

        return {code, false, -2};
    }
};

const vector<RoadCondition> RoadConditionParser::knownConditions = {
    {6, false, 0},
    {7, false, -5},
    {12, false, -20},
    {15, true, 0}
};

class CombatSimulator {
private:
    int remainingTime;
    vector<int> roadConditions;

    void processCondition(int code) {
        try {
            RoadCondition rc = RoadConditionParser::parse(code);

            if (rc.isEndpoint) {
                throw runtime_error("Endpoint reached");
            }

            if (remainingTime + rc.timeEffect < 0) {
                remainingTime = 0;
                return;
            }

            remainingTime += rc.timeEffect;

            if (remainingTime <= 0) {
                throw runtime_error("Time expired");
            }
