                if (remainingTime <= 0) break;
                processCondition(code);
            }
        } catch (const exception& e) {
            cerr << "Error during simulation: " << e.what() << endl;
        }
    }

    bool hasTimeRemaining() const {
        return remainingTime > 0;
    }
};

