        static bool isLeapYear(int year) {
            if (!YearValidator::isValidYear(year)) {
                return false;
            }
            bool by4 = isDivisibleBy(year, 4);
            bool by100 = isDivisibleBy(year, 100);
            bool by400 = isDivisibleBy(year, 400);

            if (by400) {
                return true;
            } else if (by100) {
                return false;
            } else {
                return by4;
            }
