class CombatSimulator {
private:
    int remainingTime;
    vector<int> roadConditions;
    bool terminationFlag;

    void processCondition(int condition) {
        if (!RoadConditionValidator::validateCondition(condition)) {
            throw invalid_argument("Invalid road condition detected");
        }

        int timeModifier = 0;
        bool specialCondition = false;

        switch (condition) {
            case 6:
                timeModifier = 0;
                specialCondition = true;
                break;
            case 7:
                timeModifier = -5;
                break;
            case 12:
                timeModifier = -20;
                break;
            case 15:
                {
                    terminationFlag = true;
                    specialCondition = true;
                    break;
                }
            default:
                timeModifier = -2;
        }

        if (!specialCondition) {
            remainingTime += timeModifier;
            if (remainingTime < 0) {
                terminationFlag = true;
            }
        }
    }

public:
    CombatSimulator(int initialTime, const vector<int>& conditions) 
        : remainingTime(initialTime), roadConditions(conditions), terminationFlag(false) {
