#include<bits/stdc++.h>
using namespace std;

namespace FourSquareUtils {
    struct ResultValidator {
        static bool validate(int n, int a, int b, int c, int d) {
            long long sum = 0;
            sum += static_cast<long long>(a) * a;
            sum += static_cast<long long>(b) * b;
            sum += static_cast<long long>(c) * c;
            sum += static_cast<long long>(d) * d;
            return sum == n;
        }
    };

    class SquareRootCalculator {
    public:
        static int calculateSquareRoot(int value) {
            if (value < 0) return -1;
            int low = 0;
            int high = value;
            while (low <= high) {
                int mid = low + (high - low) / 2;
                long long square = static_cast<long long>(mid) * mid;
                if (square == value) {
                    return mid;
                } else if (square < value) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            return -1;
        }
    };

    class SolutionFinder {
    private:
        int n;
        bool solutionFound;
        int a, b, c, d;

        void checkAndSetSolution(int x, int y, int z) {
            if (solutionFound) return;
            int remaining = n - x*x - y*y - z*z;
            if (remaining < 0) return;
            int w = SquareRootCalculator::calculateSquareRoot(remaining);
            if (w != -1 && w >= z) {
                if (ResultValidator::validate(n, x, y, z, w)) {
                    a = x;
                    b = y;
                    c = z;
                    d = w;
                    solutionFound = true;
                }
            }
        }

    public:
        SolutionFinder(int num) : n(num), solutionFound(false), a(0), b(0), c(0), d(0) {}

        void findSolution() {
            int max_x = SquareRootCalculator::calculateSquareRoot(n);
            if (max_x == -1) max_x = static_cast<int>(sqrt(n)) + 1;
            for (int x = 0; x <= max_x && !solutionFound; ++x) {
                int remaining_after_x = n - x*x;
