}

vector<string> processRule3(const vector<string>& tokens) {
    vector<string> processed;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i + 1 < tokens.size()) {
            if ((tokens[i] == "can" && tokens[i+1] == "you") ||
                (tokens[i] == "could" && tokens[i+1] == "you")) {
                processed.push_back("I");
                processed.push_back(tokens[i]);
                i++;
