            }
        }
        processed.push_back(tokens[i]);
    }
    return processed;
}

string reconstructString(const vector<string>& tokens) {
    if (tokens.empty()) return "";
    ostringstream oss;
    copy(tokens.begin(), tokens.end() - 1, ostream_iterator<string>(oss, " "));
    oss << tokens.back();
    return oss.str();
}

void performSanityChecks(const string& input, const string& output) {
    if (input.empty() != output.empty()) {
        throw runtime_error("Input/output empty state mismatch");
    }
    if (count(output.begin(), output.end(), '?') > 0) {
