                       sumIrritability + stones[currentIndex].irritability, 
                       true);

        recursiveSearch(currentIndex + 1, 
                       productAnger, 
                       sumIrritability, 
                       atLeastOneSelected);
    }

public:
    DifferenceCalculator(const vector<StoneAttributes>& inputStones) : stones(inputStones), minimalDifference(INFINITE_DIFFERENCE) {
        recursiveSearch(0, 1, 0, false);
    }

    int getMinimalDifference() const {
        return minimalDifference;
    }
