        throw logic_error("Solution does not satisfy n = a² + b² + c² + d²");
    }
}

void check_lexicographical_order(int a, int b, int c, int d) {
    if (a > b || b > c || c > d) {
        throw logic_error("Solution is not lexicographically smallest");
    }
