using namespace std;

class SentenceValidator {
public:
    static bool validateSentenceStructure(const string& s) {
        if (s.empty()) return false;
        for (char c : s) {
            if (!isalpha(c) && !isspace(c)) {
                return false;
            }
        }
        return true;
    }
};

class WordExtractor {
private:
    vector<string> words;
public:
    explicit WordExtractor(const string& s) {
        if (!SentenceValidator::validateSentenceStructure(s)) {
            throw invalid_argument("Invalid sentence structure");
        }
        istringstream iss(s);
        copy(istream_iterator<string>(iss),
             istream_iterator<string>(),
             back_inserter(words));
        if (words.empty()) {
            throw runtime_error("No words found in sentence");
        }
    }
    vector<string> getWords() const {
        return words;
    }
};

class LongestWordFinder {
public:
    static string findLongestWord(const vector<string>& words) {
        if (words.empty()) {
            throw runtime_error("Empty word list");
        }
        string longest;
        size_t max_len = 0;
        for (const auto& word : words) {
            size_t current_len = word.length();
            if (current_len > max_len) {
                max_len = current_len;
                longest = word;
            } else if (current_len == max_len) {
                continue;
            }
        }
        if (longest.empty()) {
            throw logic_error("No longest word found");
        }
        return longest;
    }
};

class OutputFormatter {
public:
    static void printWord(const string& word) {
        for (char c : word) {
            if (!isalpha(c)) {
                throw invalid_argument("Invalid character in word");
            }
            cout << c;
        }
        cout << endl;
    }
};

