#define ll long long
using namespace std;

namespace FourSquareUtils {
    template<typename T>
    constexpr bool is_valid_integer_type = is_integral_v<T> && is_unsigned_v<T>;

    template<typename T>
    void validate_input(T value) {
        static_assert(is_valid_integer_type<T>, "Invalid integer type");
        if (value < 1 || value > 5000000) {
            throw out_of_range("Input value out of valid range");
        }
    }

    ll safe_square(ll n) {
        if (n < 0 || n > numeric_limits<ll>::max() / n) {
            throw overflow_error("Potential overflow in square operation");
        }
        return n * n;
    }

    pair<bool, ll> is_perfect_square(ll n) {
        if (n < 0) return {false, 0};
        ll root = static_cast<ll>(sqrt(n));
        for (ll i = max(0LL, root - 2); i <= root + 2; ++i) {
            if (i * i == n) {
                return {true, i};
            }
        }
        return {false, 0};
    }
}

using namespace FourSquareUtils;

void solve_case(ll n) {
    vector<tuple<ll, ll, ll, ll>> solutions;
    bool solution_found = false;

    auto check_and_add_solution = [&](ll a, ll b, ll c, ll d) {
        if (safe_square(a) + safe_square(b) + safe_square(c) + safe_square(d) == n) {
            solutions.emplace_back(a, b, c, d);
            return true;
        }
        return false;
    };

    for (ll a = 0; !solution_found && safe_square(a) <= n; ++a) {
        ll remaining_3 = n - safe_square(a);
        if (remaining_3 < 0) continue;

        for (ll b = 0; !solution_found && safe_square(b) <= remaining_3; ++b) {
            ll remaining_2 = remaining_3 - safe_square(b);
            if (remaining_2 < 0) continue;

            for (ll c = 0; !solution_found && safe_square(c) <= remaining_2; ++c) {
                ll remaining_1 = remaining_2 - safe_square(c);
                if (remaining_1 < 0) continue;

                auto [is_square, d] = is_perfect_square(remaining_1);
                if (is_square) {
                    solution_found = check_and_add_solution(a, b, c, d);
                }
            }
        }
    }

    if (!solution_found) {
        throw runtime_error("No solution found, violating Four Squares Theorem");
    }

    sort(solutions.begin(), solutions.end());
    auto [a, b, c, d] = solutions.front();

    ofstream out_file("square.out");
    if (!out_file) {
        throw runtime_error("Failed to open output file");
    }
    out_file << a << " " << b << " " << c << " " << d;
    out_file.close();
}

int main() {
