using namespace std;

struct NumberContainer {
    int original_value;
    int digit_sum;
    string string_representation;
};

bool validateInputSize(int n) {
    return n > 0 && n < 101;
}

bool validateNumberValue(int num) {
    return num > 0 && num < 10000;
}

int calculateDigitSum(int x) {
    if (x == 0) return 0;
    int absolute_x = abs(x);
    int accumulated_sum = 0;
    while (absolute_x != 0) {
        int current_digit = absolute_x % 10;
        accumulated_sum += current_digit;
        absolute_x /= 10;
    }
    return accumulated_sum;
}

bool compareNumberContainers(const NumberContainer& a, const NumberContainer& b) {
    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    }
    return a.original_value < b.original_value;
}

void processInput(int& n, vector<NumberContainer>& containers) {
