        NumberContainer container;
        container.original_value = temp_num;
        container.digit_sum = calculateDigitSum(temp_num);
        container.string_representation = temp_str;
        containers.push_back(container);
    }
}

void outputResults(const vector<NumberContainer>& containers) {
