}

long long safeStoll(const string& s) {
    try {
        return stoll(s);
    } catch (...) {
        return 0;
    }
}

int calculateDigitSum(long long num) {
    if (num < 0) num = -num;
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }
    return sum;
}

bool comparePlates(const NumberPlate& a, const NumberPlate& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    if (a.numeric != b.numeric) {
        return a.numeric > b.numeric;
    }
    return a.index < b.index;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n < 1 || n > 10000) {
        cerr << "Invalid number of plates" << endl;
        return EXIT_FAILURE;
