        cerr << "Target plate not found" << endl;
        return EXIT_FAILURE;
    }

    sort(plates.begin(), plates.end(), comparePlates);

    long long targetNum = safeStoll(target);
    int targetSum = calculateDigitSum(targetNum);

    int position = 0;
    bool found = false;

    for (size_t i = 0; i < plates.size(); ++i) {
        if (plates[i].original == target) {
            position = i + 1;
            found = true;
            break;
        }
    }

    if (!found) {
        cerr << "Target plate not found in sorted list" << endl;
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < plates.size(); ++i) {
        if (plates[i].sum < targetSum || 
            (plates[i].sum == targetSum && plates[i].numeric > targetNum)) {
            position--;
        }
    }

    cout << position << endl;

    return EXIT_SUCCESS;
}
