using namespace std;

struct NumberWithSum {
    int original;
    int digit_sum;
    bool sum_calculated;
};

int calculate_digit_sum(int a) {
    if (a < 0) {
        throw invalid_argument("Negative numbers not allowed");
    }
    if (a >= 10000) {
        throw out_of_range("Number exceeds maximum allowed value");
    }
    int current_sum = 0;
    int remaining = a;
    while (remaining != 0) {
        int last_digit = remaining % 10;
        if (last_digit < 0 || last_digit > 9) {
            throw runtime_error("Invalid digit encountered");
        }
        current_sum += last_digit;
        remaining = remaining / 10;
        if (current_sum > numeric_limits<int>::max() - 9) {
            throw overflow_error("Digit sum overflow");
        }
    }
    return current_sum;
}

void validate_input_size(int n) {
    if (n <= 0) {
        throw invalid_argument("Input size must be positive");
    }
    if (n >= 101) {
        throw out_of_range("Input size exceeds maximum allowed");
    }
}

