#include <iostream>
#include <algorithm>
#include <vector>
#include <stdexcept>
#include <limits>
#include <sstream>
#include <type_traits>

using namespace std;

namespace DigitSumUtils {
    template<typename T>
    typename enable_if<is_integral<T>::value, T>::type
    calculateDigitSum(T number) noexcept {
        if (number < 0) number = -number;
        T sum = 0;
        while (number != 0) {
            sum += number % 10;
            number /= 10;
            if (sum > numeric_limits<T>::max() / 10) {
                throw overflow_error("Digit sum overflow detected");
            }
        }
        return sum;
    }

    template<typename T>
    bool validateNumberRange(T number, T min, T max) {
        return (number >= min) && (number <= max);
    }
}

class AdvancedIntegerSorter {
private:
    vector<int> numbers;
    size_t count;

    void validateInputCount(int n) const {
        if (!DigitSumUtils::validateNumberRange(n, 1, 100)) {
            throw invalid_argument("Input count must be between 1 and 100");
        }
    }

    void validateInputNumber(int num) const {
        if (!DigitSumUtils::validateNumberRange(num, 1, 9999)) {
            throw invalid_argument("Numbers must be between 1 and 9999");
        }
    }

    static bool compareNumbers(int x, int y) {
        try {
            int sumX = DigitSumUtils::calculateDigitSum(x);
            int sumY = DigitSumUtils::calculateDigitSum(y);
            if (sumX != sumY) {
                return sumX < sumY;
            }
            return x < y;
        } catch (const exception& e) {
            cerr << "Comparison error: " << e.what() << endl;
            return x < y;
        }
    }

public:
    explicit AdvancedIntegerSorter(int n) : count(n) {
        validateInputCount(n);
        numbers.reserve(n);
    }

    void readNumbers(istream& is) {
        string line;
        while (getline(is, line)) {
            istringstream iss(line);
            int num;
            while (iss >> num) {
                validateInputNumber(num);
                numbers.push_back(num);
                if (numbers.size() > count) {
                    throw length_error("Exceeded specified number of elements");
                }
            }
        }
    }

    void sortNumbers() {
        if (numbers.empty()) return;
        try {
            sort(numbers.begin(), numbers.end(), compareNumbers);
        } catch (const exception& e) {
            cerr << "Sorting failed: " << e.what() << endl;
            sort(numbers.begin(), numbers.end());
        }
    }

    void printNumbers(ostream& os) const {
        if (numbers.empty()) return;
        for (size_t i = 0; i < numbers.size(); ++i) {
            os << numbers[i];
            if (i != numbers.size() - 1) {
                os << " ";
            }
        }
    }
};

int main() {
    try {
        int n;
        cin >> n;
        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        AdvancedIntegerSorter sorter(n);
        sorter.readNumbers(cin);
        sorter.sortNumbers();
        sorter.printNumbers(cout);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
