    long long numeric;
    int sum;
    int index;
};

vector<PlateInfo> plates;
unordered_map<string, bool> validation_map;

bool is_valid_number_plate(const string& s) {
    if (s.empty() || s.length() > 10) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    return true;
}

long long convert_to_numeric(const string& s) {
    long long result = 0;
    for (char c : s) {
        result = result * 10 + (c - '0');
    }
    return result;
}

int calculate_digit_sum(long long num) {
    int sum = 0;
    while (num != 0) {
        sum += num % 10;
        num /= 10;
    }
    return sum;
}

bool compare_plates(const PlateInfo& a, const PlateInfo& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    return a.numeric > b.numeric;
}

void validate_and_store_plate(const string& plate, int idx) {
    if (!is_valid_number_plate(plate)) {
        cerr << "Invalid plate detected: " << plate << endl;
        exit(1);
    }
    if (validation_map.find(plate) != validation_map.end()) {
        cerr << "Duplicate plate detected: " << plate << endl;
        exit(1);
    }
    validation_map[plate] = true;

    PlateInfo info;
    info.original = plate;
    info.numeric = convert_to_numeric(plate);
    info.sum = calculate_digit_sum(info.numeric);
    info.index = idx;
    plates.push_back(info);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cerr << "Invalid number of plates" << endl;
        return 1;
    }

    vector<string> raw_inputs(n);
    for (int i = 0; i < n; ++i) {
        cin >> raw_inputs[i];
    }

    string target_plate = raw_inputs.back();
    for (int i = 0; i < n; ++i) {
        validate_and_store_plate(raw_inputs[i], i);
    }

    stable_sort(plates.begin(), plates.end(), compare_plates);

    int position = 1;
    bool found = false;
    int target_sum = 0;
    long long target_numeric = 0;

    for (const auto& plate : plates) {
        if (plate.original == target_plate) {
            target_sum = plate.sum;
            target_numeric = plate.numeric;
            break;
        }
    }

    for (size_t i = 0; i < plates.size(); ++i) {
        if (plates[i].original == target_plate) {
            found = true;
            break;
        }
        if (plates[i].sum < target_sum || 
            (plates[i].sum == target_sum && plates[i].numeric > target_numeric)) {
            position++;
        }
    }

    if (!found) {
        cerr << "Target plate not found in sorted list" << endl;
        return 1;
    }

    cout << position << endl;
    return 0;
}
