        return stoll(s);
    } catch (const out_of_range& e) {
        return LLONG_MAX;
    } catch (const invalid_argument& e) {
        return -1;
    }
}

bool validate_plate(const string& s) {
    if (s.empty() || s.length() > 10) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    return true;
}

bool compare_plates(const NumberPlate& a, const NumberPlate& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    if (a.numeric != b.numeric) {
        return a.numeric > b.numeric;
    }
    return a.index < b.index;
}

void initialize_plates(int n) {
    plates.reserve(n);
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        if (!validate_plate(s)) {
            cerr << "Invalid plate detected: " << s << endl;
            continue;
        }
        NumberPlate plate;
        plate.original = s;
        plate.numeric = string_to_ll(s);
        plate.sum = calculate_sum(s);
        plate.index = i;
        plates.push_back(plate);
        original_to_index[s] = i;
    }
