using namespace std;

ll n, m, a[55][55], max_;
vector<vector<ll>> prefix_sum;

void initialize_prefix_sum() {
    prefix_sum.resize(n + 2, vector<ll>(m + 2, 0));
    for (int i = 0; i <= n + 1; i++) {
        for (int j = 0; j <= m + 1; j++) {
            if (i == 0 || j == 0 || i == n + 1 || j == m + 1) {
                prefix_sum[i][j] = 0;
            } else {
                prefix_sum[i][j] = prefix_sum[i - 1][j] + prefix_sum[i][j - 1] - prefix_sum[i - 1][j - 1] + a[i][j];
            }
        }
    }
}

ll calculate_submatrix_sum(int u, int p, int l, int r) {
    if (u < 1 || p > n || l < 1 || r > m || u > p || l > r) {
        return LLONG_MIN;
    }
    return prefix_sum[p][r] - prefix_sum[u - 1][r] - prefix_sum[p][l - 1] + prefix_sum[u - 1][l - 1];
}

void validate_input() {
    if (n < 1 || m < 1 || n > 50 || m > 50) {
        cerr << "Invalid matrix dimensions" << endl;
        exit(1);
    }
}

void read_input() {
    ifstream input_file("submatrix.in");
    if (!input_file.is_open()) {
        cerr << "Failed to open input file" << endl;
        exit(1);
    }
    input_file >> n >> m;
    validate_input();
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            input_file >> a[i][j];
            if (a[i][j] < -1000 || a[i][j] > 1000) {
                cerr << "Invalid matrix element value" << endl;
                exit(1);
            }
        }
    }
    input_file.close();
}

void write_output() {
    ofstream output_file("submatrix.out");
    if (!output_file.is_open()) {
        cerr << "Failed to open output file" << endl;
        exit(1);
    }
    output_file << max_;
    output_file.close();
}

void find_max_submatrix() {
    max_ = LLONG_MIN;
    initialize_prefix_sum();
    for (int u = 1; u <= n; u++) {
        for (int p = u; p <= n; p++) {
            for (int l = 1; l <= m; l++) {
                for (int r = l; r <= m; r++) {
                    ll current_sum = calculate_submatrix_sum(u, p, l, r);
                    if (current_sum > max_) {
                        max_ = current_sum;
                    }
                }
            }
        }
    }
}

int main() {
    read_input();
    find_max_submatrix();
    write_output();
    return 0;
}
