#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <cstdlib>
using namespace std;

struct DataSet {
    int x;
    int y;
    int diff;
    int min_val;
    int index;
};

void validateInputRange(int value, int min_val, int max_val, const string& param_name) {
    if (value < min_val || value > max_val) {
        stringstream ss;
        ss << "Invalid " << param_name << " value: " << value << ". Must be between " << min_val << " and " << max_val;
        throw out_of_range(ss.str());
    }
}

vector<DataSet> processInput(int n) {
    if (n <= 0) throw invalid_argument("Number of datasets must be positive");
    vector<DataSet> datasets;
    datasets.reserve(n);

    for (int i = 0; i < n; ++i) {
        DataSet ds;
        cin >> ds.x >> ds.y;
        validateInputRange(ds.x, 1, 20, "X");
        validateInputRange(ds.y, 1, 20, "Y");
        ds.diff = abs(ds.x - ds.y);
        ds.min_val = min(ds.x, ds.y);
        ds.index = i;
        datasets.push_back(ds);
    }

    if (datasets.size() != n) throw runtime_error("Unexpected number of datasets processed");
    return datasets;
}

bool compareDatasets(const DataSet& a, const DataSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else if (a.min_val != b.min_val) {
        return a.min_val < b.min_val;
    } else {
        return a.index < b.index;
    }
}

pair<int, int> findTargetDataset(const vector<DataSet>& datasets) {
    if (datasets.empty()) throw invalid_argument("Dataset list cannot be empty");

    vector<DataSet> sorted = datasets;
    sort(sorted.begin(), sorted.end(), compareDatasets);

    for (size_t i = 1; i < sorted.size(); ++i) {
        if (sorted[i].diff != sorted[0].diff) {
            break;
        }
        if (sorted[i].min_val < sorted[0].min_val) {
            throw logic_error("Sorting failed for min_val comparison");
        }
    }

    if (sorted[0].diff < 0) throw domain_error("Negative difference detected");
    if (sorted[0].x < 1 || sorted[0].x > 20 || sorted[0].y < 1 || sorted[0].y > 20) {
        throw out_of_range("Invalid dataset values in result");
    }

    return make_pair(sorted[0].x, sorted[0].y);
}

int main() {
    try {
        int n;
