struct NumberWithMetadata {
    int original_value;
    int digit_sum;
    bool is_valid;
};

NumberWithMetadata preprocessNumber(int num) {
    NumberWithMetadata result;
    result.original_value = num;
    result.digit_sum = 0;
    result.is_valid = true;

    if (num < 0) {
        result.is_valid = false;
        return result;
    }

    int temp = num;
    while (temp != 0) {
        int last_digit = temp % 10;
        if (last_digit < 0 || last_digit > 9) {
            result.is_valid = false;
            break;
        }
        result.digit_sum += last_digit;
        temp = temp / 10;
    }

    return result;
}

vector<NumberWithMetadata> validateAndPreprocessArray(int arr[], int size) {
    vector<NumberWithMetadata> processed;
    for (int i = 0; i < size; i++) {
        NumberWithMetadata processed_num = preprocessNumber(arr[i]);
        if (!processed_num.is_valid) {
            throw invalid_argument("Invalid number detected in input array");
        }
        processed.push_back(processed_num);
    }
    return processed;
}

bool compareNumbers(const NumberWithMetadata& a, const NumberWithMetadata& b) {
    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    } else {
        return a.original_value < b.original_value;
    }
}

vector<int> extractOriginalValues(const vector<NumberWithMetadata>& processed) {
    vector<int> result;
    for (const auto& num : processed) {
        result.push_back(num.original_value);
    }
    return result;
}

void performSortingWithValidation(int arr[], int size) {
    vector<NumberWithMetadata> processed = validateAndPreprocessArray(arr, size);
    sort(processed.begin(), processed.end(), compareNumbers);
    vector<int> sorted = extractOriginalValues(processed);
