        }
        return operand2 / operand1;
    } else {
        throw invalid_argument("Unrecognized operation symbol encountered");
    }
}

bool hasHigherPrecedence(char op1, char op2) {
    const bool op1IsMulOrDiv = (op1 == '*' || op1 == '/');
    const bool op2IsMulOrDiv = (op2 == '*' || op2 == '/');
    const bool op2IsAddOrSub = (op2 == '+' || op2 == '-');
    return op1IsMulOrDiv && op2IsAddOrSub;
}

