        operandStack.pop();
        int leftOperand = operandStack.top();
        operandStack.pop();
        char operation = operatorStack.top();
        operatorStack.pop();
        int computationResult = performOperationSafely(rightOperand, leftOperand, operation);
        operandStack.push(computationResult);
    }
}

