using namespace std;

namespace StringUtils {
    string toLowerExceptI(const string& input) {
        string result;
        for (char c : input) {
            if (isupper(c) && c != 'I') {
                result += tolower(c);
            } else {
                result += c;
            }
        }
        return result;
    }

    string replaceQuestionMarks(const string& input) {
        string result;
        for (char c : input) {
            if (c == '?') {
                result += '!';
            } else {
                result += c;
            }
        }
        return result;
    }

    vector<string> splitString(const string& input) {
        vector<string> tokens;
        istringstream iss(input);
        copy(istream_iterator<string>(iss),
             istream_iterator<string>(),
             back_inserter(tokens));
        return tokens;
    }

    bool isWordChar(char c) {
        return isalpha(c) || c == '\'';
    }
}

class AITransformer {
private:
    vector<string> processedTokens;
    vector<bool> replacedTokens;

    void validateInput(const string& input) {
        if (input.length() > 100) {
            throw runtime_error("Input string too long");
        }
    }

    void processTokenReplacements() {
        for (size_t i = 0; i < processedTokens.size(); ++i) {
            if (replacedTokens[i]) continue;

            if (i + 1 < processedTokens.size()) {
                if ((processedTokens[i] == "can" || processedTokens[i] == "could") && 
                    processedTokens[i+1] == "you" && !replacedTokens[i+1]) {
                    processedTokens[i] = "I " + processedTokens[i];
                    processedTokens.erase(processedTokens.begin() + i + 1);
                    replacedTokens[i] = true;
                    replacedTokens.erase(replacedTokens.begin() + i + 1);
                    --i;
                    continue;
                }
            }

            if ((processedTokens[i] == "I" || processedTokens[i] == "me") && !replacedTokens[i]) {
                processedTokens[i] = "you";
                replacedTokens[i] = true;
            }
        }
    }

public:
    string transform(const string& input) {
        try {
            validateInput(input);

            string formatted = StringUtils::toLowerExceptI(input);
            formatted = StringUtils::replaceQuestionMarks(formatted);

            vector<string> tokens = StringUtils::splitString(formatted);
            processedTokens = tokens;
            replacedTokens.assign(tokens.size(), false);

            processTokenReplacements();

            ostringstream oss;
            for (size_t i = 0; i < processedTokens.size(); ++i) {
                if (i != 0) oss << " ";
                oss << processedTokens[i];
            }

            string result = oss.str();

            if (!result.empty() && ispunct(result.back())) {
                result = result.substr(0, result.length() - 1) + " " + result.back();
            }

            return result;
        } catch (const exception& e) {
            cerr << "Error processing input: " << e.what() << endl;
            return input;
        }
    }
};

int main() {
    try {
        int n;
        cin >> n;
        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        if (n <= 0 || n > 100) {
            throw runtime_error("Invalid number of inputs");
        }

        AITransformer transformer;
        vector<string> inputs;
        vector<string> outputs;

        for (int i = 0; i < n; ++i) {
            string input;
            getline(cin, input);
            inputs.push_back(input);
        }

        for (const auto& input : inputs) {
            outputs.push_back(transformer.transform(input));
        }

        for (const auto& output : outputs) {
            cout << output << endl;
        }

        return 0;
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }
}
