template<typename T>
constexpr bool is_valid_integer_type = is_integral<T>::value && !is_same<T, bool>::value;

template<typename T>
enable_if_t<is_valid_integer_type<T>, T> digit_sum(T x) {
    static_assert(is_valid_integer_type<T>, "Invalid type for digit sum calculation");
    if (x < 0) throw invalid_argument("Negative numbers not allowed");
    T s = 0;
    while (x != 0) {
        if (numeric_limits<T>::max() - s < x % 10) {
            throw overflow_error("Digit sum overflow detected");
        }
        s += x % 10;
        x /= 10;
    }
    return s;
}

struct AdvancedIntegerComparator {
    template<typename T>
    bool operator()(T x, T y) const {
        static_assert(is_valid_integer_type<T>, "Invalid type for comparison");
        try {
            auto sum_x = digit_sum(x);
            auto sum_y = digit_sum(y);
            if (sum_x != sum_y) {
                return sum_x < sum_y;
            } else {
                if (x == y) {
                    throw logic_error("Duplicate values detected");
                }
