    class DigitSumValidator {
    public:
        static bool validateNumber(int x) {
            return x >= 0 && x <= MAX_NUMBER;
        }

        static bool validateDigitSum(int sum) {
            return sum >= 0 && sum <= MAX_DIGIT_SUM;
        }
    };

    int calculateDigitSumWithValidation(int x) {
        if (!DigitSumValidator::validateNumber(x)) {
            throw out_of_range("Number exceeds valid range");
        }

        int original = x;
        int accumulated_sum = 0;
        int safety_counter = 0;
        const int MAX_DIGITS = 5;

        while (x != 0 && safety_counter < MAX_DIGITS) {
            int current_digit = x % 10;
            accumulated_sum += current_digit;
            x /= 10;
            safety_counter++;
        }

        if (!DigitSumValidator::validateDigitSum(accumulated_sum)) {
            throw logic_error("Invalid digit sum calculated");
        }

        return accumulated_sum;
    }
}

