template<typename T>
constexpr bool is_valid_integer_type = is_integral<T>::value && !is_same<T, bool>::value;

template<typename T>
enable_if_t<is_valid_integer_type<T>, int> calculate_digit_sum(T num) noexcept {
    static_assert(is_valid_integer_type<T>, "Type must be a non-boolean integral type");
    if (num < 0) num = -num;
    int sum = 0;
    while (num != 0) {
        sum += num % 10;
        num /= 10;
        if (sum > numeric_limits<int>::max() / 2) {
            sum = 0;
            break;
        }
    }
    return sum;
}

template<typename T>
enable_if_t<is_valid_integer_type<T>, bool> compare_numbers(T a, T b) {
    constexpr int max_safe_sum = numeric_limits<int>::max() / 10;
    int sum_a = calculate_digit_sum(a);
    int sum_b = calculate_digit_sum(b);

    if (sum_a > max_safe_sum || sum_b > max_safe_sum) {
        throw overflow_error("Potential digit sum overflow detected");
