    static const int DIGIT_SIZE = 10;

    static char transformUpperCase(char c, int shift) {
        try {
            if (!isupper(c)) throw CharacterProcessingException();
            int normalized = c - 'A';
            int shifted = (normalized + shift) % ALPHABET_SIZE;
            if (shifted < 0) shifted += ALPHABET_SIZE;
            return static_cast<char>(shifted + 'A');
        } catch (...) {
            throw CharacterProcessingException();
        }
    }

    static char transformLowerCase(char c, int shift) {
        try {
            if (!islower(c)) throw CharacterProcessingException();
            int normalized = c - 'a';
            int shifted = (normalized + shift) % ALPHABET_SIZE;
            if (shifted < 0) shifted += ALPHABET_SIZE;
            return static_cast<char>(shifted + 'a');
        } catch (...) {
            throw CharacterProcessingException();
        }
    }

    static char transformDigit(char c, int shift) {
        try {
            if (!isdigit(c)) throw CharacterProcessingException();
            int normalized = c - '0';
            int shifted = (normalized + shift) % DIGIT_SIZE;
            if (shifted < 0) shifted += DIGIT_SIZE;
            return static_cast<char>(shifted + '0');
        } catch (...) {
            throw CharacterProcessingException();
        }
    }

public:
