            int num = c - '0';
            num = (num + shift) % 10;
            if (num < 0) num += 10;
            return '0' + num;
        } else if (isupper(c)) {
            int alphaPos = c - 'A';
            alphaPos = (alphaPos + shift) % 26;
            if (alphaPos < 0) alphaPos += 26;
            return 'A' + alphaPos;
        } else if (islower(c)) {
            int alphaPos = c - 'a';
            alphaPos = (alphaPos + shift) % 26;
            if (alphaPos < 0) alphaPos += 26;
            return 'a' + alphaPos;
        }
        return c;
    }

public:
    CyclicShifter(int z) : shiftAmount(z) {}

    void addCharacter(char c, size_t pos) {
