class CharacterTransformer {
private:
    static char processUpperCase(char c, int shift) {
        if (!isupper(c)) throw CharacterProcessingException();
        shift = shift % 26;
        if (shift < 0) shift += 26;
        return 'A' + (c - 'A' + shift) % 26;
    }

    static char processLowerCase(char c, int shift) {
        if (!islower(c)) throw CharacterProcessingException();
        shift = shift % 26;
        if (shift < 0) shift += 26;
        return 'a' + (c - 'a' + shift) % 26;
    }

    static char processDigit(char c, int shift) {
        if (!isdigit(c)) throw CharacterProcessingException();
        shift = shift % 10;
        if (shift < 0) shift += 10;
        return '0' + (c - '0' + shift) % 10;
    }

public:
    static char transformCharacter(char c, int shift) {
        try {
            if (isupper(c)) {
                return processUpperCase(c, shift);
            } else if (islower(c)) {
                return processLowerCase(c, shift);
            } else if (isdigit(c)) {
                return processDigit(c, shift);
            }
            return c;
        } catch (const CharacterProcessingException& e) {
