    CyclicShifter(int z) : shift_amount(z) {}

    char shiftCharacter(char c) {
        validateCharacter(c);
        if (is_upper_case) {
            int base = 'A';
            int range = 26;
            int shifted = (c - base + shift_amount) % range;
            if (shifted < 0) shifted += range;
            return static_cast<char>(base + shifted);
        } else if (is_lower_case) {
            int base = 'a';
            int range = 26;
            int shifted = (c - base + shift_amount) % range;
            if (shifted < 0) shifted += range;
            return static_cast<char>(base + shifted);
        } else if (is_digit) {
            int base = '0';
            int range = 10;
            int shifted = (c - base + shift_amount) % range;
            if (shifted < 0) shifted += range;
            return static_cast<char>(base + shifted);
        }
        return c;
    }
};

class PositionValidator {
private:
    int y_value;
    int current_position;

public:
    PositionValidator(int y) : y_value(y), current_position(0) {}

    bool shouldShift() {
        current_position++;
        if (y_value == 0) {
            throw runtime_error("Division by zero in position validation");
        }
        return (current_position % y_value == 0);
    }

    void reset() {
        current_position = 0;
    }
};

class InputSanitizer {
