#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <utility>
using namespace std;

struct ChildData {
    int original_index;
    int jump_capability;
    int balloons_acquired;
    bool processed_flag;
};

struct BalloonInfo {
    int elevation;
    bool claimed_status;
};

bool CompareJumpCapability(const ChildData& first, const ChildData& second) {
    if (first.jump_capability != second.jump_capability) {
        return first.jump_capability < second.jump_capability;
    }
    return first.original_index < second.original_index;
}

bool CompareOriginalIndex(const ChildData& first, const ChildData& second) {
    return first.original_index < second.original_index;
}

void ValidateInputParameters(int n, int m) {
    if (n < 1 || n > 1000 || m < 1 || m > 1000) {
        throw invalid_argument("Invalid input parameters detected");
    }
}

void ProcessChildData(vector<ChildData>& children, int n) {
    for (int i = 0; i < n; ++i) {
        if (children[i].jump_capability < 1 || children[i].jump_capability > 100000) {
            throw out_of_range("Child jump capability out of bounds");
        }
        children[i].original_index = i;
        children[i].balloons_acquired = 0;
        children[i].processed_flag = false;
    }
}

void ProcessBalloonData(vector<BalloonInfo>& balloons, int m) {
    for (int i = 0; i < m; ++i) {
        if (balloons[i].elevation < 1 || balloons[i].elevation > 100000) {
            throw out_of_range("Balloon elevation out of bounds");
        }
        balloons[i].claimed_status = false;
    }
}

void SortChildrenByJump(vector<ChildData>& children) {
    sort(children.begin(), children.end(), CompareJumpCapability);
}

void SortBalloonsByHeight(vector<BalloonInfo>& balloons) {
    sort(balloons.begin(), balloons.end(), [](const BalloonInfo& a, const BalloonInfo& b) {
        return a.elevation < b.elevation;
    });
}

void AllocateBalloons(vector<ChildData>& children, vector<BalloonInfo>& balloons) {
    int current_balloon_index = 0;
    for (auto& child : children) {
        int temp_counter = 0;
        while (current_balloon_index < balloons.size()) {
            if (!balloons[current_balloon_index].claimed_status && 
                balloons[current_balloon_index].elevation <= child.jump_capability) {
                temp_counter++;
                balloons[current_balloon_index].claimed_status = true;
                current_balloon_index++;
            } else {
                break;
            }
        }
        child.balloons_acquired = temp_counter;
        child.processed_flag = true;
    }
}

void VerifyAllChildrenProcessed(const vector<ChildData>& children) {
    for (const auto& child : children) {
        if (!child.processed_flag) {
            throw runtime_error("Child processing incomplete");
        }
    }
}

void OutputResults(const vector<ChildData>& children) {
    vector<ChildData> sorted_output = children;
    sort(sorted_output.begin(), sorted_output.end(), CompareOriginalIndex);
    for (const auto& child : sorted_output) {
        cout << child.balloons_acquired << endl;
    }
}

int main() {
    try {
        int num_children, num_balloons;
        cin >> num_children >> num_balloons;
        ValidateInputParameters(num_children, num_balloons);

        vector<ChildData> children_data(num_children);
        for (int i = 0; i < num_children; ++i) {
            cin >> children_data[i].jump_capability;
        }
        ProcessChildData(children_data, num_children);

        vector<BalloonInfo> balloon_data(num_balloons);
        for (int i = 0; i < num_balloons; ++i) {
            cin >> balloon_data[i].elevation;
        }
        ProcessBalloonData(balloon_data, num_balloons);

        SortChildrenByJump(children_data);
        SortBalloonsByHeight(balloon_data);

        AllocateBalloons(children_data, balloon_data);
        VerifyAllChildrenProcessed(children_data);

        OutputResults(children_data);
    } catch (const exception& e) {
        cerr << "Error occurred: " << e.what() << endl;
        return EXIT_FAILURE;
    }
