#include<bits/stdc++.h>
using namespace std;

const int MAX_HISTORY_SIZE = 10000000;
const int SAFETY_LIMIT = 1000000000;

struct PositionHistory {
    long long* visited;
    int capacity;
    int size;
};

void initializeHistory(PositionHistory* history) {
    history->capacity = 16;
    history->size = 0;
    history->visited = (long long*)malloc(history->capacity * sizeof(long long));
    if (history->visited == nullptr) {
        cerr << "Memory allocation failed" << endl;
        exit(EXIT_FAILURE);
    }
}

void ensureCapacity(PositionHistory* history) {
    if (history->size >= history->capacity) {
        int newCapacity = history->capacity * 2;
        if (newCapacity > MAX_HISTORY_SIZE) {
            newCapacity = MAX_HISTORY_SIZE;
        }
        long long* newVisited = (long long*)realloc(history->visited, newCapacity * sizeof(long long));
        if (newVisited == nullptr) {
            cerr << "Memory reallocation failed" << endl;
            exit(EXIT_FAILURE);
        }
        history->visited = newVisited;
        history->capacity = newCapacity;
    }
}

bool containsPosition(PositionHistory* history, long long pos) {
    for (int i = 0; i < history->size; ++i) {
        if (history->visited[i] == pos) {
            return true;
        }
    }
    return false;
}

void addPosition(PositionHistory* history, long long pos) {
    if (history->size >= MAX_HISTORY_SIZE) {
        cerr << "History size exceeded maximum limit" << endl;
        exit(EXIT_FAILURE);
    }
    ensureCapacity(history);
    history->visited[history->size++] = pos;
}

void printHistory(PositionHistory* history) {
    if (history->size == 0) return;
    cout << history->visited[0];
    for (int i = 1; i < history->size; ++i) {
        cout << ", " << history->visited[i];
    }
}

void processPosition(PositionHistory* history, long long currentPos) {
    if (currentPos <= 0 || currentPos > SAFETY_LIMIT) {
        cerr << "Invalid position encountered" << endl;
        exit(EXIT_FAILURE);
    }

    if (containsPosition(history, currentPos)) {
        addPosition(history, currentPos);
        return;
    }

    addPosition(history, currentPos);

    long long nextPos;
    if (currentPos % 2 == 0) {
        nextPos = currentPos / 2;
        if (nextPos <= 0 || nextPos > SAFETY_LIMIT) {
            cerr << "Invalid next position calculation" << endl;
            exit(EXIT_FAILURE);
        }
    } else {
        nextPos = 6 * ((currentPos - 1) / 2) + 6;
        if (nextPos <= 0 || nextPos > SAFETY_LIMIT) {
            cerr << "Invalid next position calculation" << endl;
            exit(EXIT_FAILURE);
        }
    }

    processPosition(history, nextPos);
}

int main() {
    PositionHistory history;
    initializeHistory(&history);

    long long n;
    if (!(cin >> n)) {
        cerr << "Invalid input" << endl;
        return EXIT_FAILURE;
    }

    if (n < 1 || n > (1LL << 30)) {
        cerr << "Input out of range" << endl;
        return EXIT_FAILURE;
    }

    processPosition(&history, n);
    printHistory(&history);

    free(history.visited);
    return 0;
}
