using namespace std;

struct QueueOperationResult {
    bool success;
    string message;
    int position;
};

class OverlyCautiousQueue {
private:
    vector<string> queue_data;
    int front_index;
    int back_index;
    int capacity;
    bool initialized;

    bool validateIndex(int index) {
        return index >= front_index && index < back_index && index < capacity && initialized;
    }

    QueueOperationResult validateOperation(int operation_type) {
        QueueOperationResult result;
        result.success = false;
        result.position = -1;

        if (operation_type != 1 && operation_type != 2) {
            result.message = "Invalid operation type detected";
            return result;
        }

        if (!initialized) {
            result.message = "Queue not properly initialized";
            return result;
        }

        result.success = true;
        return result;
    }

public:
    OverlyCautiousQueue() {
        capacity = 105;
        queue_data.resize(capacity);
        front_index = 0;
        back_index = 0;
        initialized = true;
    }

    QueueOperationResult enqueue(const string& name) {
        QueueOperationResult validation = validateOperation(1);
        if (!validation.success) {
            return validation;
        }

        if (back_index >= capacity) {
            QueueOperationResult result;
            result.success = false;
            result.message = "Queue capacity exceeded";
            return result;
        }

        bool friend_found = false;
        char target_first_char = toupper(name[0]);
        int insertion_position = back_index;

        for (int current_position = front_index; current_position < back_index; ++current_position) {
            if (!validateIndex(current_position)) {
                continue;
            }

            char current_first_char = toupper(queue_data[current_position][0]);
            if (current_first_char == target_first_char) {
                insertion_position = current_position + 1;
                friend_found = true;
                break;
            }
        }

        if (friend_found) {
            for (int shift_position = back_index; shift_position > insertion_position; --shift_position) {
                if (validateIndex(shift_position - 1)) {
                    queue_data[shift_position] = queue_data[shift_position - 1];
                }
            }
        }

        queue_data[insertion_position] = name;
        back_index++;

        QueueOperationResult result;
        result.success = true;
        result.position = insertion_position;
        return result;
    }

    QueueOperationResult dequeue() {
        QueueOperationResult validation = validateOperation(2);
        if (!validation.success) {
            return validation;
        }

        QueueOperationResult result;
        if (front_index >= back_index) {
            result.success = false;
            result.message = "0";
            return result;
        }

        result.success = true;
        result.message = queue_data[front_index];
        front_index++;

        return result;
    }
};

int main() {
    OverlyCautiousQueue queue_system;
    int operation_count;
    cin >> operation_count;

    if (operation_count < 1 || operation_count > 100) {
        cerr << "Invalid operation count" << endl;
        return 1;
    }

    while (operation_count--) {
        int operation_type;
        cin >> operation_type;

        if (operation_type == 1) {
            string person_name;
            cin >> person_name;
            QueueOperationResult enqueue_result = queue_system.enqueue(person_name);
            if (!enqueue_result.success) {
                cerr << "Enqueue failed: " << enqueue_result.message << endl;
            }
        }
        else if (operation_type == 2) {
            QueueOperationResult dequeue_result = queue_system.dequeue();
            if (dequeue_result.success) {
                cout << dequeue_result.message << endl;
            }
            else {
                cout << dequeue_result.message << endl;
            }
        }
        else {
            cerr << "Unexpected operation type encountered" << endl;
        }
    }

    return 0;
}
