using namespace std;

class QueueManager {
private:
    vector<string> queue;
    size_t max_size = 10000;

    bool validateName(const string& name) {
        if (name.empty()) return false;
        if (!isalpha(name[0])) return false;
        if (name.size() > 100) return false;
        for (char c : name) {
            if (!isalpha(c) && c != '_') return false;
        }
        return true;
    }

    bool hasFriend(const string& name) {
        if (queue.empty()) return false;
        char first_char = toupper(name[0]);
        for (const auto& person : queue) {
            if (!person.empty() && toupper(person[0]) == first_char) {
                return true;
            }
        }
        return false;
    }

    size_t findFirstFriendPosition(const string& name) {
        char first_char = toupper(name[0]);
        for (size_t i = 0; i < queue.size(); ++i) {
            if (!queue[i].empty() && toupper(queue[i][0]) == first_char) {
                return i;
            }
        }
        return numeric_limits<size_t>::max();
    }

public:
    void enqueue(const string& name) {
        if (!validateName(name)) {
            throw invalid_argument("Invalid name format");
        }
        if (queue.size() >= max_size) {
            throw length_error("Queue size exceeded");
        }

        if (hasFriend(name)) {
            size_t pos = findFirstFriendPosition(name);
            if (pos != numeric_limits<size_t>::max()) {
                queue.insert(queue.begin() + pos + 1, name);
                return;
            }
        }
        queue.push_back(name);
    }

    string dequeue() {
        if (queue.empty()) {
            return "0";
        }
        string front = queue.front();
        queue.erase(queue.begin());
        return front;
    }
};

int main() {
    QueueManager qm;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    while (n--) {
        int k;
        cin >> k;

        if (cin.fail()) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            continue;
        }

        try {
            if (k == 1) {
                string name;
                cin >> name;
                qm.enqueue(name);
            } else if (k == 2) {
                cout << qm.dequeue() << endl;
            } else {
                throw invalid_argument("Invalid operation code");
            }
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            continue;
        }
    }

    return 0;
}
