#include <iostream>
#include <vector>
#include <string>
#include <stdexcept>
#include <limits>

using namespace std;

struct QueueState {
    vector<string> queue_data;
    int front_index;
    int rear_index;
    bool initialization_flag;
    bool error_condition;
};

void initializeQueueState(QueueState& state) {
    state.queue_data.resize(10001);
    state.front_index = 0;
    state.rear_index = 0;
    state.initialization_flag = true;
    state.error_condition = false;
}

void handleEnqueueOperation(QueueState& state, const string& name) {
    if (!state.initialization_flag) {
        throw runtime_error("Queue not initialized properly");
    }

    bool insertion_flag = false;
    bool friend_found_flag = false;
    int insertion_position = -1;

    for (int current_index = state.front_index; current_index < state.rear_index; current_index++) {
        if (state.queue_data[current_index].empty()) {
            continue;
        }
        if (state.queue_data[current_index][0] == name[0]) {
            friend_found_flag = true;
            insertion_position = current_index;
            break;
        }
    }

    if (friend_found_flag) {
        for (int shift_index = state.rear_index; shift_index > insertion_position + 1; shift_index--) {
            state.queue_data[shift_index] = state.queue_data[shift_index - 1];
        }
        state.queue_data[insertion_position + 1] = name;
        insertion_flag = true;
    }

    if (!insertion_flag) {
        state.queue_data[state.rear_index] = name;
    }

    state.rear_index++;
}

void handleDequeueOperation(QueueState& state) {
    if (state.front_index >= state.rear_index) {
        cout << 0 << endl;
        state.error_condition = true;
        return;
    }

    if (state.queue_data[state.front_index].empty()) {
        cout << 0 << endl;
        state.error_condition = true;
        return;
    }

    cout << state.queue_data[state.front_index] << endl;
    state.front_index++;

    if (state.front_index > 10000) {
        state.front_index = 0;
        state.rear_index = 0;
    }
}

int main() {
    QueueState main_state;
    initializeQueueState(main_state);

    int operation_count;
    cin >> operation_count;

    if (cin.fail() || operation_count < 1 || operation_count > 100) {
        cerr << "Invalid operation count" << endl;
        return 1;
    }

    while (operation_count--) {
        int operation_type;
        cin >> operation_type;

        if (cin.fail()) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            continue;
        }

        if (operation_type == 1) {
            string new_name;
            cin >> new_name;
            if (new_name.empty()) {
                continue;
            }
            handleEnqueueOperation(main_state, new_name);
        } else if (operation_type == 2) {
            handleDequeueOperation(main_state);
        } else {
            continue;
        }
    }

    return 0;
}
