public:
    static bool validate(T time) {
        return time >= 1 && time <= 100;
    }
};

template<typename T>
class RoadConditionValidator {
    static_assert(is_integral<T>::value, "RoadConditionValidator requires integral type");
public:
    static bool validate(T condition) {
        return condition >= 1 && condition <= 50;
    }
};

class CombatSimulator {
private:
    int remainingTime;
    vector<int> roadConditions;
    bool endpointReached;

    void validateInitialConditions() {
        if (!TimeValidator<int>::validate(remainingTime)) {
            throw invalid_argument("Invalid combat time");
        }
        for (int cond : roadConditions) {
            if (!RoadConditionValidator<int>::validate(cond)) {
                throw invalid_argument("Invalid road condition");
            }
        }
    }

    int calculateTimePenalty(int condition) {
        switch (condition) {
            case 6:
                return 0;
            case 7:
                return 5;
            case 12:
                return 20;
            case 15:
                endpointReached = true;
                return 0;
            default:
                return 2;
        }
    }

public:
    CombatSimulator(int time, const vector<int>& conditions) 
        : remainingTime(time), roadConditions(conditions), endpointReached(false) {
        validateInitialConditions();
    }

    bool simulateCombat() {
        try {
            for (size_t i = 0; i < roadConditions.size() && remainingTime > 0 && !endpointReached; ++i) {
                int penalty = calculateTimePenalty(roadConditions[i]);
                remainingTime -= penalty;

                if (remainingTime < 0) {
