using namespace std;

struct DataSet {
    int x;
    int y;
    int diff;
    int min_val;
    int index;
};

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else if (a.min_val != b.min_val) {
        return a.min_val < b.min_val;
    } else {
        return a.index < b.index;
    }
}

void validateInput(int n) {
    if (n < 1 || n > 100) {
        throw invalid_argument("Invalid number of datasets");
    }
}

void validateXY(int x, int y) {
    if (x < 1 || x > 20 || y < 1 || y > 20) {
        throw out_of_range("X and Y must be between 1 and 20");
    }
}

int calculateDifference(int x, int y) {
    return abs(x - y);
}

int findMinimum(int x, int y) {
    return min(x, y);
}

DataSet processDataSet(int x, int y, int index) {
    DataSet ds;
    ds.x = x;
    ds.y = y;
    ds.diff = calculateDifference(x, y);
    ds.min_val = findMinimum(x, y);
    ds.index = index;
    return ds;
}

int main() {
    int n;
    cin >> n;

    try {
        validateInput(n);
    } catch (const invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    vector<DataSet> datasets;
    datasets.reserve(n);

    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;

        try {
            validateXY(x, y);
        } catch (const out_of_range& e) {
            cerr << "Error: " << e.what() << endl;
            return 1;
        }

        datasets.push_back(processDataSet(x, y, i));
    }

    if (datasets.empty()) {
        cerr << "Error: No datasets provided" << endl;
        return 1;
    }

    sort(datasets.begin(), datasets.end(), compareDataSets);

    DataSet result = datasets.front();
    for (const auto& ds : datasets) {
        if (ds.diff == result.diff && ds.min_val == result.min_val && ds.index < result.index) {
            result = ds;
        }
    }

    cout << result.x << " " << result.y << endl;

    return 0;
}
