#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <stdexcept>
#include <limits>
#include <cctype>
using namespace std;

struct QueuePerson {
    string name;
    bool is_valid;
    int position;
};

class AdvancedQueueManager {
private:
    vector<QueuePerson> queue;
    int front_index;
    int back_index;
    int capacity;
    int size;

    void validateName(const string& name) {
        if (name.empty()) throw runtime_error("Empty name not allowed");
        if (!isalpha(name[0])) throw runtime_error("Name must start with letter");
    }

    void resizeQueueIfNeeded() {
        if (size >= capacity - 2) {
            capacity *= 2;
            queue.resize(capacity);
        }
    }

    void compactQueue() {
        if (front_index > capacity / 4) {
            vector<QueuePerson> new_queue(queue.begin() + front_index, queue.begin() + back_index);
            queue = new_queue;
            back_index = back_index - front_index;
            front_index = 0;
            capacity = queue.size();
        }
    }

public:
    AdvancedQueueManager() : front_index(0), back_index(0), capacity(100), size(0) {
        queue.resize(capacity);
    }

    void enqueueWithFriendshipCheck(const string& name) {
        try {
            validateName(name);
            bool friend_found = false;
            char first_letter = toupper(name[0]);

            for (int i = front_index; i < back_index; ++i) {
                if (!queue[i].is_valid) continue;
                if (toupper(queue[i].name[0]) == first_letter) {
                    for (int j = back_index; j > i + 1; --j) {
                        if (j >= capacity) resizeQueueIfNeeded();
                        queue[j] = queue[j - 1];
                        queue[j].position = j;
                    }
                    queue[i + 1] = {name, true, i + 1};
                    friend_found = true;
                    break;
                }
            }

            if (!friend_found) {
                if (back_index >= capacity) resizeQueueIfNeeded();
                queue[back_index] = {name, true, back_index};
            }

            back_index++;
            size++;
            compactQueue();
        } catch (const exception& e) {
            cerr << "Enqueue error: " << e.what() << endl;
        }
    }

    string safeDequeue() {
        if (size <= 0 || front_index >= back_index) {
            return "0";
        }

        while (front_index < back_index && !queue[front_index].is_valid) {
            front_index++;
        }

        if (front_index >= back_index) {
            return "0";
        }

        string result = queue[front_index].name;
        queue[front_index].is_valid = false;
        front_index++;
        size--;

        if (size < capacity / 4 && capacity > 100) {
            compactQueue();
        }

        return result;
    }
};

int main() {
    AdvancedQueueManager aqm;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return EXIT_FAILURE;
    }

    while (n--) {
        int k;
        cin >> k;

        if (cin.fail()) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            cerr << "Invalid operation type" << endl;
            continue;
        }

        if (k == 1) {
            string name;
            cin >> name;
            aqm.enqueueWithFriendshipCheck(name);
        } else if (k == 2) {
            cout << aqm.safeDequeue() << endl;
        } else {
            cerr << "Unknown operation type" << endl;
