class OverlyComplexQueueManager {
private:
    vector<string> queueData;
    size_t queueFrontPointer;
    size_t queueBackPointer;
    bool initializationFlag;

    void initializeIfNeeded() {
        if (!initializationFlag) {
            queueData.resize(10001);
            queueFrontPointer = 0;
            queueBackPointer = 0;
            initializationFlag = true;
        }
    }

    void performInsertionWithFriendCheck(const string& name) {
        bool friendFoundStatus = false;
        size_t insertionPosition = numeric_limits<size_t>::max();

        for (size_t currentPosition = queueFrontPointer; currentPosition < queueBackPointer; ++currentPosition) {
            if (!queueData[currentPosition].empty() && 
                queueData[currentPosition][0] == name[0]) {
                friendFoundStatus = true;
                insertionPosition = currentPosition;
                break;
            }
        }

        if (friendFoundStatus) {
            for (size_t shiftPosition = queueBackPointer; shiftPosition > insertionPosition + 1; --shiftPosition) {
                if (shiftPosition < queueData.size()) {
                    queueData[shiftPosition] = queueData[shiftPosition - 1];
                }
            }
            if (insertionPosition + 1 < queueData.size()) {
                queueData[insertionPosition + 1] = name;
            }
        } else {
            if (queueBackPointer < queueData.size()) {
                queueData[queueBackPointer] = name;
            }
        }

        if (queueBackPointer < queueData.size()) {
            ++queueBackPointer;
        }
    }

