            ++queueFrontPointer;
        }
    }

public:
    OverlyComplexQueueManager() : initializationFlag(false) {}

    void processOperation(int operationCode, const string& name = "") {
        initializeIfNeeded();
        QueueOperationValidator::validateOperationCode(operationCode);

        if (operationCode == 1) {
            QueueOperationValidator::validateName(name);
            performInsertionWithFriendCheck(name);
