    public:
        static string toLowerExceptI(string str) {
            for (auto& c : str) {
                if (isupper(c) && c != 'I') {
                    c = tolower(c);
                }
            }
            return str;
        }

        static string replaceQuestionMarks(string str) {
            replace(str.begin(), str.end(), '?', '!');
            return str;
        }

        static vector<string> splitString(const string& str) {
            vector<string> tokens;
            string token;
            istringstream tokenStream(str);
            while (tokenStream >> token) {
                tokens.push_back(token);
            }
            return tokens;
        }
    };

    class RuleApplier {
    private:
        static bool isIndependentWord(const vector<string>& words, size_t index) {
            if (index >= words.size()) return false;
            string word = words[index];
            if (word.empty()) return false;
            for (char c : word) {
                if (ispunct(c) && c != '\'' && c != '-') {
                    return false;
                }
            }
            return true;
        }

    public:
        static void applyRule3(vector<string>& words) {
            unordered_set<size_t> processedIndices;
            for (size_t i = 0; i + 1 < words.size(); ) {
                if (processedIndices.find(i) != processedIndices.end()) {
                    i++;
                    continue;
                }
                if ((words[i] == "can" || words[i] == "could") && 
                    words[i+1] == "you" && 
                    isIndependentWord(words, i) && 
                    isIndependentWord(words, i+1)) {
                    words[i] = "I";
                    words[i+1] = words[i] == "can" ? "can" : "could";
                    processedIndices.insert(i);
                    processedIndices.insert(i+1);
                    i += 2;
                } else {
                    i++;
                }
            }
        }

        static void applyRule4(vector<string>& words) {
            unordered_set<size_t> processedIndices;
            for (size_t i = 0; i < words.size(); i++) {
                if (processedIndices.find(i) != processedIndices.end()) continue;
                if (words[i] == "I" || words[i] == "me") {
                    if (isIndependentWord(words, i)) {
                        words[i] = "you";
                        processedIndices.insert(i);
                    }
                }
            }
        }
    };

    class SentenceReconstructor {
    public:
        static string reconstruct(const vector<string>& words) {
            if (words.empty()) return "";
            string result;
            for (size_t i = 0; i < words.size(); i++) {
                result += words[i];
                if (i != words.size() - 1) {
                    result += " ";
                }
            }
            return result;
        }
    };
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    vector<string> inputs;
    inputs.reserve(n);
    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        inputs.push_back(move(line));
    }

