            processed = StringProcessingUtils::StringTransformer::replaceQuestionMarks(processed);
            vector<string> words = StringProcessingUtils::StringTransformer::splitString(processed);

            StringProcessingUtils::RuleApplier::applyRule4(words);
            StringProcessingUtils::RuleApplier::applyRule3(words);

            string result = StringProcessingUtils::SentenceReconstructor::reconstruct(words);
            outputs.push_back(move(result));
        } catch (const exception& e) {
            cerr << "Error processing input: " << e.what() << endl;
            outputs.push_back(input);
        }
    }

    for (const auto& output : outputs) {
        cout << output << '\n';
    }

    return 0;
}
