}

pair<int, int> process_receipt(const string& receipt_str) {
    int partial_value = 0;
    int missing_position_weight = 0;
    int position_weight = 1;
    bool missing_found = false;

    for (auto it = receipt_str.rbegin(); it != receipt_str.rend(); ++it) {
        if (*it == '?') {
            if (missing_found) {
                return make_pair(-1, -1);
            }
            missing_position_weight = position_weight;
            missing_found = true;
        } else if (*it >= '0' && *it <= '9') {
            partial_value += (*it - '0') * position_weight;
        }
        position_weight++;
    }

    if (!missing_found) {
        return make_pair(-1, -1);
    }

    return make_pair(partial_value, missing_position_weight);
