        int currentNumber = 0;
        cin >> currentNumber;
        validateNumber(currentNumber);

        int currentSum = calculateDigitSum(currentNumber);
        numberSumPairs.emplace_back(currentSum, currentNumber);
    }

    sort(numberSumPairs.begin(), numberSumPairs.end(), DigitSumComparator());

    for (size_t i = 0; i < numberSumPairs.size(); ++i) {
