        if (!RoadConditionValidator<int>::validateCondition(condition)) {
            throw invalid_argument("Invalid road condition detected");
        }

        if (condition == 6) {
            remainingTime += 0;
        } else if (condition == 7) {
            remainingTime = max(numeric_limits<long long>::min(), remainingTime - 5);
        } else if (condition == 12) {
