};

vector<string> split_string_with_delimiters(const string& input) {
    vector<string> tokens;
    string current_token;
    for (char ch : input) {
        if (isspace(ch) || ch == '?' || ch == '!' || ch == '.' || ch == ',') {
            if (!current_token.empty()) {
                tokens.push_back(current_token);
                current_token.clear();
            }
            if (ch != ' ') {
                tokens.push_back(string(1, ch));
            }
        } else {
            current_token += ch;
        }
    }
    if (!current_token.empty()) {
        tokens.push_back(current_token);
    }
    return tokens;
}

string join_words(const vector<WordMetadata>& words) {
    string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i > 0 && !words[i].is_punctuation && !words[i-1].is_punctuation) {
            result += " ";
        }
        result += words[i].content;
    }
    return result;
}

void process_case_conversion(string& s) {
    for (char& ch : s) {
        if (ch != 'I' && isupper(ch)) {
            ch = tolower(ch);
        }
    }
}

void process_question_marks(vector<WordMetadata>& words) {
