using namespace std;

bool isPunctuation(char c) {
    return c == '!' || c == '?' || c == '.' || c == ',';
}

string processToken(const string& token, bool& skipNext) {
    if (skipNext) {
        skipNext = false;
        return token;
    }

    string processed = token;
    if (processed == "can" || processed == "could") {
        return processed;
    }
    if (processed == "I" || processed == "me") {
        return "you";
    }
    return processed;
}

string processSpecialCases(const string& s) {
    regex can_you("(^|\\s)can you(\\s|$)");
    regex could_you("(^|\\s)could you(\\s|$)");
    string result = regex_replace(s, can_you, " I can ");
    result = regex_replace(result, could_you, " I could ");
    return result;
}

string formatString(const string& s) {
    string formatted;
    for (char c : s) {
        if (c != 'I' && isupper(c)) {
            formatted += tolower(c);
        } else {
            formatted += c;
        }
    }
    replace(formatted.begin(), formatted.end(), '?', '!');
    return formatted;
}

vector<string> tokenize(const string& s) {
    vector<string> tokens;
    string current;
    for (char c : s) {
        if (isalnum(c) || c == '\'') {
            current += c;
        } else {
            if (!current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
            if (c != ' ') {
                string punct;
                punct += c;
                tokens.push_back(punct);
            }
        }
    }
    if (!current.empty()) {
        tokens.push_back(current);
    }
    return tokens;
}

string reconstruct(const vector<string>& tokens) {
    string result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i > 0 && !isPunctuation(tokens[i][0]) {
            result += " ";
        }
        result += tokens[i];
    }
    return result;
}

string processRules(const string& s) {
    string temp = s;
    temp = processSpecialCases(temp);

    vector<string> tokens = tokenize(temp);
    bool skipNext = false;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (tokens[i] == "can" && i + 1 < tokens.size() && tokens[i+1] == "you") {
            tokens[i] = "I";
            tokens[i+1] = "can";
            skipNext = true;
        } else if (tokens[i] == "could" && i + 1 < tokens.size() && tokens[i+1] == "you") {
            tokens[i] = "I";
            tokens[i+1] = "could";
            skipNext = true;
        } else {
            tokens[i] = processToken(tokens[i], skipNext);
        }
    }
    return reconstruct(tokens);
}

string sanitizeOutput(const string& s) {
    string output;
    bool inSpace = false;
    for (char c : s) {
        if (c == ' ') {
            if (!inSpace) {
                output += c;
                inSpace = true;
            }
        } else {
            output += c;
            inSpace = false;
        }
    }
    return output;
}

