#include<limits>

using namespace std;

namespace FlyingChessUtils {
    const long long MAX_ITERATIONS = 1000000;

    class PositionValidator {
    public:
        static bool isValidPosition(long long pos) {
            return pos > 0 && pos <= numeric_limits<long long>::max();
        }
    };

    class CycleDetector {
    private:
        unordered_set<long long> visited;

    public:
        bool hasCycle(long long current) {
            if (visited.count(current) > 0) {
                return true;
            }
            visited.insert(current);
            return false;
        }

        void reset() {
            visited.clear();
        }
    };
}

void printSequence(const vector<long long>& sequence) {
    if (sequence.empty()) return;

    for (size_t i = 0; i < sequence.size(); ++i) {
        if (i != 0) {
            cout << ", ";
        }
        cout << sequence[i];
    }
}

vector<long long> generatePath(long long start) {
    using namespace FlyingChessUtils;

    if (!PositionValidator::isValidPosition(start)) {
        throw invalid_argument("Invalid starting position");
    }

    CycleDetector detector;
    vector<long long> path;
    long long current = start;
    int iterationCount = 0;

    while (true) {
        if (iterationCount++ > MAX_ITERATIONS) {
            throw runtime_error("Maximum iterations exceeded");
        }

        path.push_back(current);

        if (detector.hasCycle(current)) {
            break;
        }

        if (current % 2 == 0) {
            if (!PositionValidator::isValidPosition(current / 2)) {
                throw overflow_error("Position calculation overflow");
            }
            current = current / 2;
        } else {
            long long newPos = 3 * current + 3;
            if (!PositionValidator::isValidPosition(newPos)) {
                throw overflow_error("Position calculation overflow");
            }
            current = newPos;
        }
    }

    return path;
}

int main() {
    try {
        long long n;
        if (!(cin >> n)) {
            cerr << "Invalid input format" << endl;
            return 1;
        }

        vector<long long> path = generatePath(n);
        printSequence(path);

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
