struct NumberSet {
    int x;
    int y;
    int diff;
    int min_val;
    int input_order;
};

int validateInput(int value, int min_val, int max_val, const string& var_name) {
    if (value < min_val || value > max_val) {
        throw runtime_error("Invalid input value for " + var_name);
    }
    return value;
}

int calculateDifference(int x, int y) {
    return abs(x - y);
}

int findMinimumValue(int x, int y) {
    return min(x, y);
}

bool compareSets(const NumberSet& a, const NumberSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    }
    if (a.min_val != b.min_val) {
        return a.min_val < b.min_val;
    }
    return a.input_order < b.input_order;
}

int main() {
    try {
        int n;
        cin >> n;
        n = validateInput(n, 1, 100, "N");

        vector<NumberSet> sets;
        sets.reserve(n);

        for (int i = 0; i < n; ++i) {
            int x, y;
            if (!(cin >> x >> y)) {
                throw runtime_error("Failed to read input values");
            }

            x = validateInput(x, 1, 20, "X");
            y = validateInput(y, 1, 20, "Y");

            int diff = calculateDifference(x, y);
            int min_val = findMinimumValue(x, y);

            sets.push_back({x, y, diff, min_val, i});
        }

        if (sets.empty()) {
            throw runtime_error("No input sets provided");
        }

        sort(sets.begin(), sets.end(), compareSets);

