bool is_valid_year(int year) {
    if (year < 1600 || year > 3000) {
        return false;
    }
    return true;
}

bool is_valid_month(int month) {
    if (month < 1 || month > 12) {
        return false;
    }
    return true;
}

bool is_leap_year(int year) {
    if (year % 400 == 0) {
        return true;
    } else if (year % 100 == 0) {
        return false;
    } else if (year % 4 == 0) {
        return true;
    }
    return false;
}

