        string validation_error = validate_input(y, m);
        if (!validation_error.empty()) {
            throw runtime_error(validation_error);
        }

        switch (m) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                return 31;
            case 4: case 6: case 9: case 11:
