    bool is_valid;
};

vector<WordMetadata> extract_words_with_metadata(const string& input) {
    vector<WordMetadata> words;
    bool in_word = false;
    size_t start = 0;

    for (size_t i = 0; i < input.size(); ++i) {
        if (!isspace(input[i]) && !in_word) {
            in_word = true;
            start = i;
        } else if (isspace(input[i]) && in_word) {
            WordMetadata wm;
            wm.content = input.substr(start, i - start);
            wm.start_pos = start;
            wm.end_pos = i - 1;
            wm.is_valid = true;
            words.push_back(wm);
            in_word = false;
        }
    }

    if (in_word) {
        WordMetadata wm;
        wm.content = input.substr(start);
        wm.start_pos = start;
        wm.end_pos = input.size() - 1;
        wm.is_valid = true;
        words.push_back(wm);
    }

    return words;
}

string find_longest_word_with_validation(const vector<WordMetadata>& words) {
    if (words.empty()) {
        throw runtime_error("No words found in input");
    }

    string longest;
    size_t max_len = 0;
    bool found = false;

    for (const auto& wm : words) {
        if (!wm.is_valid) continue;

        bool contains_non_alpha = false;
        for (char c : wm.content) {
            if (!isalpha(c)) {
                contains_non_alpha = true;
                break;
            }
        }

        if (contains_non_alpha) continue;

        if (wm.content.length() > max_len || 
           (wm.content.length() == max_len && wm.start_pos < longest.find_first_of(longest))) {
            max_len = wm.content.length();
            longest = wm.content;
            found = true;
        }
    }

    if (!found) {
        throw runtime_error("No valid words found");
    }

    return longest;
}

void sanitize_input_string(string& input) {
    if (input.empty()) {
