#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<ll, ll> pll;

const ll MAX_FLOOR = 1e18;
const ll MIN_FLOOR = 0;
const ll TIME_UP = 5;
const ll TIME_DOWN = 4;
const ll TIME_OPEN = 3;
const ll TIME_PER_PERSON = 2;

struct ElevatorState {
    ll current_floor;
    ll total_time;
    unordered_map<ll, vector<size_t>> passenger_map;
    vector<bool> processed;
    bool initialization_complete;
};

void validate_floor(ll floor) {
    if (floor < MIN_FLOOR || floor > MAX_FLOOR) {
        throw runtime_error("Invalid floor number detected");
    }
}

void initialize_elevator(ElevatorState& state, ll n) {
    state.current_floor = 0;
    state.total_time = 0;
    state.processed.resize(n + 1, false);
    state.initialization_complete = true;
}

void process_passengers(ElevatorState& state, const vector<ll>& floors) {
    for (size_t i = 1; i < floors.size(); ++i) {
        validate_floor(floors[i]);
        state.passenger_map[floors[i]].push_back(i);
    }
}

void move_elevator(ElevatorState& state, ll target_floor) {
    validate_floor(target_floor);
    ll distance = abs(target_floor - state.current_floor);
    if (target_floor > state.current_floor) {
        state.total_time += distance * TIME_UP;
    } else if (target_floor < state.current_floor) {
        state.total_time += distance * TIME_DOWN;
    }
    state.current_floor = target_floor;
}

void handle_floor_stop(ElevatorState& state, ll floor) {
    validate_floor(floor);
    move_elevator(state, floor);
    state.total_time += TIME_OPEN;
    auto it = state.passenger_map.find(floor);
    if (it != state.passenger_map.end()) {
        for (auto passenger : it->second) {
            if (!state.processed[passenger]) {
                state.total_time += TIME_PER_PERSON;
                state.processed[passenger] = true;
            }
        }
    }
}

void verify_all_processed(const ElevatorState& state, ll n) {
    for (size_t i = 1; i <= n; ++i) {
        if (!state.processed[i]) {
            throw runtime_error("Not all passengers processed");
        }
    }
}

