using namespace std;

bool validateSentence(const string& sentence) {
    if (sentence.empty()) return false;
    for (char c : sentence) {
        if (!isalpha(c) && !isspace(c)) {
            return false;
        }
    }
    return true;
}

vector<string> tokenizeWithExtraChecks(const string& input) {
    vector<string> tokens;
    stringstream ss(input);
    string token;
    while (ss >> token) {
        if (!token.empty()) {
            for (char& c : token) {
                if (!isalpha(c)) {
                    throw runtime_error("Invalid character detected");
                }
            }
            tokens.push_back(token);
        }
    }
    if (tokens.empty()) {
        throw runtime_error("No valid words found");
    }
    return tokens;
}

string findLongestWordWithRedundantChecks(const vector<string>& words) {
    if (words.empty()) {
        throw runtime_error("Word list is empty");
    }

    string longest = words[0];
    size_t max_len = longest.size();

    for (size_t i = 1; i < words.size(); ++i) {
        const string& current = words[i];
        if (current.size() > numeric_limits<size_t>::max() - 1) {
            throw runtime_error("Word length exceeds system limits");
        }

        if (current.size() > max_len) {
            longest = current;
            max_len = current.size();
        } else if (current.size() == max_len) {
            if (current != longest) {
                continue;
            }
        }

        for (char c : current) {
            if (!isalpha(c)) {
                throw runtime_error("Invalid character in word");
            }
        }
    }

    if (longest.empty()) {
        throw runtime_error("Longest word is empty");
    }

    return longest;
}

int main() {
    try {
        string input;
        if (!getline(cin, input)) {
            throw runtime_error("Failed to read input");
        }

        if (!validateSentence(input)) {
            throw runtime_error("Invalid sentence format");
        }

        vector<string> words = tokenizeWithExtraChecks(input);

        string longest = findLongestWordWithRedundantChecks(words);

        if (longest.size() > 100) {
            throw runtime_error("Word length exceeds maximum allowed");
        }

        cout << longest;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
