SquareSolution findLexicographicallySmallestSolution(int target) {
    SquareSolution solution = {INT_MAX, INT_MAX, INT_MAX, INT_MAX, false};
    int max_i = static_cast<int>(sqrt(target)) + 2;
    for (int i = 0; i <= max_i; ++i) {
        int remaining_after_i = target - i * i;
        if (remaining_after_i < 0) continue;
        int max_j = static_cast<int>(sqrt(remaining_after_i)) + 2;
        for (int j = 0; j <= max_j; ++j) {
            int remaining_after_j = remaining_after_i - j * j;
            if (remaining_after_j < 0) continue;
            int max_k = static_cast<int>(sqrt(remaining_after_j)) + 2;
            for (int k = 0; k <= max_k; ++k) {
                int remaining_after_k = remaining_after_j - k * k;
                if (remaining_after_k < 0) continue;
                int l = static_cast<int>(sqrt(remaining_after_k));
                if (l * l != remaining_after_k) {
                    int potential_l_plus = l + 1;
                    if (potential_l_plus * potential_l_plus == remaining_after_k) {
                        l = potential_l_plus;
                    } else {
                        int potential_l_minus = l - 1;
                        if (potential_l_minus >= 0 && potential_l_minus * potential_l_minus == remaining_after_k) {
                            l = potential_l_minus;
