                int sum = i * i + j * j + k * k + l * l;
                if (sum == target) {
                    vector<int> current = {i, j, k, l};
                    sort(current.begin(), current.end());
                    vector<int> best = {solution.a, solution.b, solution.c, solution.d};
                    if (!solution.valid || lexicographical_compare(current.begin(), current.end(), best.begin(), best.end())) {
