            if (value < min_val || value > max_val) {
                throw out_of_range("Input value out of valid range");
            }
            return true;
        }
    };

    class MathOperations {
    public:
        static int secureSquareRoot(int x) {
            if (x < 0) {
                throw domain_error("Cannot compute square root of negative number");
            }
            double result = sqrt(x);
            if (abs(result - round(result)) > numeric_limits<double>::epsilon() * 100) {
                throw logic_error("Square root is not exact");
            }
            return static_cast<int>(round(result));
        }
    };

    class FileHandler {
    public:
        static unique_ptr<ifstream> openInputFile(const string& filename) {
            auto file = make_unique<ifstream>(filename);
            if (!file->is_open()) {
                throw runtime_error("Failed to open input file");
            }
            return file;
        }

        static unique_ptr<ofstream> openOutputFile(const string& filename) {
            auto file = make_unique<ofstream>(filename);
            if (!file->is_open()) {
                throw runtime_error("Failed to open output file");
            }
            return file;
        }
    };

    class SolutionFinder {
    public:
        static vector<int> findLexicographicalSolution(int n) {
            vector<int> solution(4, numeric_limits<int>::max());
            bool found = false;
            int max_i = MathOperations::secureSquareRoot(n) + 1;

            for (int i = 0; i <= max_i; ++i) {
                if (i * i > n) continue;
                int remaining1 = n - i * i;
                int max_j = MathOperations::secureSquareRoot(remaining1) + 1;

                for (int j = 0; j <= max_j; ++j) {
                    if (i * i + j * j > n) continue;
                    int remaining2 = remaining1 - j * j;
                    int max_k = MathOperations::secureSquareRoot(remaining2) + 1;

                    for (int k = 0; k <= max_k; ++k) {
                        if (i * i + j * j + k * k > n) continue;
                        int remaining3 = remaining2 - k * k;
                        try {
                            int l = MathOperations::secureSquareRoot(remaining3);
                            if (i * i + j * j + k * k + l * l == n) {
                                vector<int> current = {i, j, k, l};
                                sort(current.begin(), current.end());
                                if (current < solution) {
                                    solution = current;
                                    found = true;
                                }
                            }
                        } catch (...) {
                            continue;
                        }
                    }
                }
            }

            if (!found) {
                throw logic_error("No solution found, which violates the Four Squares Theorem");
            }
            return solution;
        }
    };
}

int main() {
    try {
        auto input_file = FourSquareUtils::FileHandler::openInputFile("square.in");
        int N;
        *input_file >> N;
        FourSquareUtils::InputValidator<int>::validate(N, 1, 5000000);

        auto solution = FourSquareUtils::SolutionFinder::findLexicographicalSolution(N);

        auto output_file = FourSquareUtils::FileHandler::openOutputFile("square.out");
        *output_file << solution[0] << " " << solution[1] << " " << solution[2] << " " << solution[3];

