using namespace std;

struct SquareSolution {
    int a;
    int b;
    int c;
    int d;
    bool valid;
};

SquareSolution findLexicographicallySmallestSolution(int target) {
    SquareSolution solution = {numeric_limits<int>::max(), numeric_limits<int>::max(), 
                              numeric_limits<int>::max(), numeric_limits<int>::max(), false};
    const int upper_bound = static_cast<int>(sqrt(target)) + 2;
    vector<vector<int>> intermediate_results;

    for (int i = 0; i <= upper_bound; ++i) {
        int i_sq = i * i;
        if (i_sq > target) continue;

        for (int j = 0; j <= upper_bound; ++j) {
            int j_sq = j * j;
            if (i_sq + j_sq > target) continue;

            for (int k = 0; k <= upper_bound; ++k) {
                int k_sq = k * k;
                if (i_sq + j_sq + k_sq > target) continue;

                int remaining = target - i_sq - j_sq - k_sq;
                if (remaining < 0) continue;

                int d = static_cast<int>(sqrt(remaining));
                while (d * d > remaining) --d;
                while ((d + 1) * (d + 1) <= remaining) ++d;

                if (i_sq + j_sq + k_sq + d * d == target) {
                    vector<int> current = {i, j, k, d};
                    intermediate_results.push_back(current);
                }
            }
        }
    }

    if (!intermediate_results.empty()) {
        sort(intermediate_results.begin(), intermediate_results.end());
        solution.a = intermediate_results[0][0];
        solution.b = intermediate_results[0][1];
        solution.c = intermediate_results[0][2];
        solution.d = intermediate_results[0][3];
        solution.valid = true;
    }

    return solution;
}

void validateInput(int n) {
    if (n < 1 || n > 5000000) {
        throw invalid_argument("Input must be between 1 and 5000000 inclusive");
    }
}

void writeOutput(const string& filename, const SquareSolution& solution) {
    ofstream outfile(filename);
    if (!outfile.is_open()) {
        throw runtime_error("Unable to open output file");
    }
    outfile << solution.a << " " << solution.b << " " << solution.c << " " << solution.d;
    outfile.close();
}

int readInput(const string& filename) {
    ifstream infile(filename);
    if (!infile.is_open()) {
        throw runtime_error("Unable to open input file");
    }
    int n;
    infile >> n;
    infile.close();
    return n;
}

int main() {
    try {
        int n = readInput("square.in");
        validateInput(n);
        SquareSolution solution = findLexicographicallySmallestSolution(n);
        if (!solution.valid) {
            throw runtime_error("No valid solution found");
        }
        writeOutput("square.out", solution);
    } catch (const exception& e) {
        ofstream error_log("error.log", ios_base::app);
        error_log << "Error: " << e.what() << endl;
        error_log.close();
        return 1;
    }
    return 0;
}
