}

void populate_inorder_positions(int traversal_length) {
    for (int current_position = 1; current_position <= traversal_length; ++current_position) {
        inorder_position_mapping[inorder_traversal[current_position]] = current_position;
    }
}

int validate_and_build_tree(int postorder_root_position, int inorder_start, int inorder_end, int current_subtree_size) {
    if (current_subtree_size <= 0 || postorder_root_position < 1 || inorder_start > inorder_end) {
        return 0;
