    validation.is_valid_postorder = true;
    for (int i = 1; i <= n; ++i) {
        if (a[i] < MIN_VALUE || a[i] > MAX_VALUE) {
            validation.is_valid_postorder = false;
            break;
        }
    }

    validation.is_valid_inorder = true;
    for (int i = 1; i <= n; ++i) {
        if (b[i] < MIN_VALUE || b[i] > MAX_VALUE) {
            validation.is_valid_inorder = false;
            break;
        }
    }

    validation.has_duplicates = false;
    unique_values.clear();
    for (int i = 1; i <= n; ++i) {
        if (unique_values.count(a[i]) {
            validation.has_duplicates = true;
            break;
        }
        unique_values.insert(a[i]);
    }

    return validation;
}

void initialize_arrays() {
    for (int i = 0; i < MAX_NODES; ++i) {
        l[i] = 0;
        r[i] = 0;
        visited[i] = false;
    }
}

int find_position(int value, int start, int end) {
    for (int i = start; i <= end; ++i) {
        if (b[i] == value) {
            return i;
        }
    }
    return -1;
}

int dfs(int post_start, int in_start, int length) {
    if (length <= 0) {
        return 0;
    }

    int root_value = a[post_start + length - 1];
    if (visited[root_value]) {
        return 0;
    }
    visited[root_value] = true;

    int root_pos = find_position(root_value, in_start, in_start + length - 1);
    if (root_pos == -1) {
        return 0;
    }

    int right_length = in_start + length - 1 - root_pos;
    int left_length = root_pos - in_start;

    if (right_length > 0) {
        r[root_value] = dfs(post_start + left_length, root_pos + 1, right_length);
    } else {
        r[root_value] = 0;
    }

    if (left_length > 0) {
        l[root_value] = dfs(post_start, in_start, left_length);
    } else {
        l[root_value] = 0;
    }

    return root_value;
}

void verify_tree_structure() {
    for (int i = 1; i <= n; ++i) {
        if (l[i] != 0 && !visited[l[i]]) {
            l[i] = 0;
        }
        if (r[i] != 0 && !visited[r[i]]) {
            r[i] = 0;
        }
    }
}

