        !validation.is_valid_inorder || validation.has_duplicates) {
        cout << "Invalid input data" << endl;
        return 1;
    }

    initialize_arrays();
    dfs(n, 1, n);
    verify_tree_structure();

    for (int i = 1; i <= n; ++i) {
        cout << l[i] << " " << r[i] << endl;
    }

    return 0;
}
