#include<bits/stdc++.h>
using namespace std;

const int MAX_NODES = 1010;
const int MAX_TRAVERSAL_LENGTH = 35;

struct TreeNodeInfo {
    int left_child;
    int right_child;
    bool visited;
    int inorder_position;
};

int postorder_traversal[MAX_TRAVERSAL_LENGTH];
int inorder_traversal[MAX_TRAVERSAL_LENGTH];
TreeNodeInfo node_info[MAX_NODES];
map<int, int> inorder_position_map;
map<int, bool> node_existence_map;

void initializeDataStructures() {
    for (int i = 0; i < MAX_NODES; i++) {
        node_info[i].left_child = 0;
        node_info[i].right_child = 0;
        node_info[i].visited = false;
        node_info[i].inorder_position = -1;
    }
    inorder_position_map.clear();
    node_existence_map.clear();
}

void validateInput(int n) {
    if (n <= 0 || n > 30) {
        cerr << "Invalid number of nodes" << endl;
        exit(1);
    }
    for (int i = 1; i <= n; i++) {
        if (postorder_traversal[i] <= 0 || postorder_traversal[i] >= 1000) {
            cerr << "Invalid node value in postorder traversal" << endl;
            exit(1);
        }
        if (inorder_traversal[i] <= 0 || inorder_traversal[i] >= 1000) {
            cerr << "Invalid node value in inorder traversal" << endl;
            exit(1);
        }
    }
}

void buildInorderPositionMap(int n) {
    for (int i = 1; i <= n; i++) {
        if (inorder_position_map.find(inorder_traversal[i]) != inorder_position_map.end()) {
            cerr << "Duplicate node in inorder traversal" << endl;
            exit(1);
        }
        inorder_position_map[inorder_traversal[i]] = i;
        node_existence_map[inorder_traversal[i]] = true;
    }
}

int constructBinaryTree(int post_start, int in_start, int subtree_size) {
    if (subtree_size <= 0) {
        return 0;
    }

    int root_value = postorder_traversal[post_start + subtree_size - 1];
    if (!node_existence_map[root_value]) {
        cerr << "Node not found in inorder traversal" << endl;
        exit(1);
    }

    int root_in_pos = inorder_position_map[root_value];
    if (root_in_pos < in_start || root_in_pos >= in_start + subtree_size) {
        cerr << "Invalid tree structure detected" << endl;
        exit(1);
    }

    int left_subtree_size = root_in_pos - in_start;
    int right_subtree_size = subtree_size - left_subtree_size - 1;

    if (left_subtree_size < 0 || right_subtree_size < 0) {
        cerr << "Invalid subtree size calculation" << endl;
        exit(1);
    }

    int left_child = constructBinaryTree(post_start, in_start, left_subtree_size);
    int right_child = constructBinaryTree(post_start + left_subtree_size, root_in_pos + 1, right_subtree_size);

    node_info[root_value].left_child = left_child;
    node_info[root_value].right_child = right_child;

    return root_value;
}

void outputResults(int n) {
    for (int i = 1; i <= n; i++) {
        if (!node_existence_map[i]) {
            cerr << "Node missing in traversal sequences" << endl;
            exit(1);
        }
        cout << node_info[i].left_child << " " << node_info[i].right_child << endl;
    }
}

