TreeConstructionState validateAndSplit(int post_start, int post_end, int in_start, int in_end) {
    TreeConstructionState state;
    state.is_valid = false;

    if (post_start > post_end || in_start > in_end) {
        state.is_valid = true;
        return state;
    }

    if (post_start < 1 || post_end > node_count || in_start < 1 || in_end > node_count) {
        return state;
    }

    int root_val = postorder[post_end];
    if (root_val < 1 || root_val >= MAX_VALUE) {
        return state;
    }

    int root_pos = -1;
    for (int i = in_start; i <= in_end; ++i) {
        if (inorder[i] == root_val) {
            root_pos = i;
            break;
        }
    }

    if (root_pos == -1) {
        return state;
    }

    int left_size = root_pos - in_start;
    int right_size = in_end - root_pos;

    state.is_valid = true;
    state.root_value = root_val;

    if (left_size > 0) {
        for (int i = post_start; i <= post_start + left_size - 1; ++i) {
            state.left_subtree.push_back(postorder[i]);
        }
    }

    if (right_size > 0) {
        for (int i = post_start + left_size; i <= post_end - 1; ++i) {
            state.right_subtree.push_back(postorder[i]);
        }
    }

    return state;
}

int buildTree(int post_start, int post_end, int in_start, int in_end) {
    TreeConstructionState state = validateAndSplit(post_start, post_end, in_start, in_end);

    if (!state.is_valid) {
        return INVALID_NODE;
    }

    if (post_start > post_end || in_start > in_end) {
        return INVALID_NODE;
    }

    int root_val = state.root_value;
    node_exists[root_val] = true;

    if (!state.left_subtree.empty()) {
        int left_root = buildTree(post_start, post_start + state.left_subtree.size() - 1, 
