    }
    unordered_set<int> unique_values;
    for(int i = 1; i <= n; i++) {
        if(postorder[i] <= 0 || postorder[i] >= 1000) {
            throw out_of_range("Node value out of bounds in postorder");
        }
        unique_values.insert(postorder[i]);
    }
    for(int i = 1; i <= n; i++) {
        if(inorder[i] <= 0 || inorder[i] >= 1000) {
            throw out_of_range("Node value out of bounds in inorder");
        }
        if(unique_values.find(inorder[i]) == unique_values.end()) {
            throw TreeValidationException();
        }
    }
}

int buildTree(int post_start, int post_end, int in_start, int in_end) {
    if(post_start > post_end || in_start > in_end) {
        return 0;
