vector<DataSet> processInput(int n) {
    vector<DataSet> datasets;
    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;
        validateInput(x, y);
        auto [diff, min_val] = calculateDifference(x, y);
        datasets.push_back({x, y, diff, min_val, i});
    }
    return datasets;
}

DataSet findOptimalDataSet(const vector<DataSet>& datasets) {
    if (datasets.empty()) {
        throw runtime_error("No datasets provided");
    }

    DataSet optimal = datasets[0];
    for (const auto& ds : datasets) {
        if (ds.diff > optimal.diff) {
            optimal = ds;
        } else if (ds.diff == optimal.diff) {
            if (ds.min_val < optimal.min_val) {
                optimal = ds;
            } else if (ds.min_val == optimal.min_val && ds.index < optimal.index) {
                optimal = ds;
            }
        }
    }
    return optimal;
}

void printResult(const DataSet& result) {
    cout << max(result.x, result.y) << " " << min(result.x, result.y) << endl;
}

int main() {
    try {
        int n;
        cin >> n;
        if (n < 1 || n > 100) {
            throw invalid_argument("N must be between 1 and 100");
        }

        vector<DataSet> datasets = processInput(n);
        DataSet result = findOptimalDataSet(datasets);
        printResult(result);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
