#include<bits/stdc++.h>
using namespace std;

bool is_valid_char(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '(' || c == ')' || (c >= '0' && c <= '9');
}

bool is_valid_number(char c) {
    return c >= '1' && c <= '9';
}

string process_encoded_string(const string& s) {
    stack<string> string_stack;
    stack<int> number_stack;
    string current_string;
    int current_number = 0;
    bool number_flag = false;
    bool nested_flag = false;
    int parenthesis_depth = 0;

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (!is_valid_char(c)) {
            continue;
        }

        if (isdigit(c)) {
            if (!is_valid_number(c)) {
                continue;
            }
            if (number_flag) {
                current_number = current_number * 10 + (c - '0');
            } else {
                current_number = c - '0';
                number_flag = true;
            }
        } else if (c == '(') {
            if (number_flag) {
                number_stack.push(current_number);
                current_number = 0;
                number_flag = false;
            } else if (!number_stack.empty()) {
                number_stack.push(1);
            }
            string_stack.push(current_string);
            current_string.clear();
            parenthesis_depth++;
            nested_flag = (parenthesis_depth > 1);
        } else if (c == ')') {
            if (parenthesis_depth == 0) {
                continue;
            }
            string temp;
            if (!number_stack.empty()) {
                int num = number_stack.top();
                number_stack.pop();
                for (int j = 0; j < num; ++j) {
                    temp += current_string;
                }
            } else {
                temp = current_string;
            }
            if (!string_stack.empty()) {
                current_string = string_stack.top() + temp;
                string_stack.pop();
            } else {
                current_string = temp;
            }
            parenthesis_depth--;
            nested_flag = (parenthesis_depth > 0);
        } else {
            if (number_flag) {
                number_stack.push(current_number);
                current_number = 0;
                number_flag = false;
            }
            current_string += c;
        }
    }

    while (!number_stack.empty()) {
        int num = number_stack.top();
        number_stack.pop();
        string temp;
        for (int j = 0; j < num; ++j) {
            temp += current_string;
        }
        current_string = temp;
    }

    return current_string;
}

string validate_and_process(const string& s) {
    if (s.empty()) {
        return "";
    }

    int parenthesis_balance = 0;
    bool has_digit = false;
    bool has_letters = false;

    for (char c : s) {
        if (!is_valid_char(c)) {
            return "";
        }
        if (c == '(') {
            parenthesis_balance++;
        } else if (c == ')') {
            parenthesis_balance--;
        }
        if (isdigit(c)) {
            has_digit = true;
        }
        if (isalpha(c)) {
            has_letters = true;
        }
    }

    if (parenthesis_balance != 0) {
        return "";
    }

    if (!has_digit && !has_letters) {
        return "";
    }

    return process_encoded_string(s);
}

int main() {
    string s;
    cin >> s;

    string result = validate_and_process(s);

    if (result.empty()) {
        cout << "";
    } else {
        cout << result;
