#include <bits/stdc++.h>
using namespace std;

struct CompressionState {
    vector<int> compressed_data;
    char current_char;
    int current_count;
    bool initialized;
};

void initialize_compression_state(CompressionState& state) {
    state.current_count = 0;
    state.initialized = false;
    state.current_char = '\0';
}

void process_character(CompressionState& state, char c) {
    if (!state.initialized) {
        state.current_char = c;
        state.current_count = 1;
        state.initialized = true;
    } else {
        if (c == state.current_char) {
            state.current_count++;
        } else {
            state.compressed_data.push_back(state.current_count);
            state.current_char = c;
            state.current_count = 1;
        }
    }
}

void finalize_compression(CompressionState& state) {
    if (state.current_count > 0) {
        state.compressed_data.push_back(state.current_count);
    }
}

