    vector<HeightData> processedData;
    map<int, vector<int>> cumulativeMap;

    void preprocessData(const vector<int>& input) {
        HeightData initial;
        initial.gender = 0;
        initial.cumulative = 0;
        initial.index = 0;
        processedData.push_back(initial);

        for (int i = 0; i < input.size(); i++) {
            HeightData current;
            current.gender = input[i];
            current.index = i + 1;
            current.cumulative = processedData.back().cumulative + (current.gender == 0 ? -1 : 1);
            processedData.push_back(current);
