        if (val <= range.first || val > range.second) {
            throw InputValidationException("Input parameter out of valid range");
        }
    }
}

char transformCharacter(char c, int shift, bool& wasTransformed) {
    const int alphabetSize = 26;
    const int digitSize = 10;
    char original = c;
    wasTransformed = false;

    if (isalpha(c)) {
        char base = isupper(c) ? 'A' : 'a';
        c = (c - base + shift) % alphabetSize + base;
        wasTransformed = true;
    } else if (isdigit(c)) {
        c = (c - '0' + shift) % digitSize + '0';
        wasTransformed = true;
    } else {
        throw invalid_argument("Invalid character in input");
    }

    if (original == c) {
        wasTransformed = false;
    }

    return c;
}

void processString(int length, int interval, int shift) {
    vector<char> buffer;
    buffer.reserve(length);
    char currentChar;
    int positionCounter = 0;

    while (positionCounter < length) {
        if (!(cin >> currentChar)) {
            throw runtime_error("Insufficient characters in input");
        }

        bool shouldTransform = false;
        bool wasTransformed = false;
        positionCounter++;

        if (interval > 0 && positionCounter % interval == 0) {
