class PerfectMatchValidator {
public:
    static bool validateInputSequence(const vector<int>& sequence) {
        unordered_set<int> validValues = {0, 1};
        for (int val : sequence) {
            if (validValues.find(val) == validValues.end()) {
                return false;
            }
        }
        return true;
    }
};

class SubsequenceAnalyzer {
private:
    vector<int> prefixSums;
    map<int, vector<int>> sumIndices;

public:
    void initializePrefixSums(const vector<int>& genderSequence) {
        prefixSums.resize(genderSequence.size() + 1);
        prefixSums[0] = 0;
        for (int i = 0; i < genderSequence.size(); ++i) {
            int adjustedValue = (genderSequence[i] == 0) ? -1 : 1;
            prefixSums[i+1] = prefixSums[i] + adjustedValue;
        }
    }

    void buildSumIndexMap() {
        for (int i = 0; i < prefixSums.size(); ++i) {
            sumIndices[prefixSums[i]].push_back(i);
        }
    }

    int findMaximumValidSubsequence() {
        int maxLength = 0;
        for (const auto& entry : sumIndices) {
            if (entry.second.size() >= 2) {
                int currentSpan = entry.second.back() - entry.second.front();
                if (currentSpan > maxLength) {
                    maxLength = currentSpan;
                }
            }
        }
        return maxLength;
    }
};

class InputHandler {
public:
    static vector<int> readGenderSequence(istream& inputStream) {
        int n;
        inputStream >> n;
        if (n < 1 || n > 100000) {
            throw out_of_range("Invalid number of participants");
        }

        vector<int> sequence(n);
        for (int i = 0; i < n; ++i) {
            if (!(inputStream >> sequence[i])) {
                throw runtime_error("Invalid input format");
            }
        }

        if (!PerfectMatchValidator::validateInputSequence(sequence)) {
            throw invalid_argument("Invalid gender values in sequence");
        }

        return sequence;
    }
};

class OutputHandler {
public:
    static void writeResult(ostream& outputStream, int result) {
        if (result < 0) {
            throw invalid_argument("Result cannot be negative");
        }
        outputStream << result;
    }
};

int main() {
    try {
        ifstream inputFile("pair.in");
        if (!inputFile.is_open()) {
            throw runtime_error("Unable to open input file");
        }

        vector<int> genderSequence = InputHandler::readGenderSequence(inputFile);
        inputFile.close();

        SubsequenceAnalyzer analyzer;
        analyzer.initializePrefixSums(genderSequence);
        analyzer.buildSumIndexMap();
        int result = analyzer.findMaximumValidSubsequence();

        ofstream outputFile("pair.out");
        if (!outputFile.is_open()) {
            throw runtime_error("Unable to open output file");
        }

