#include<bits/stdc++.h>
using namespace std;

template<typename T>
void validateInput(const T& input, const string& message) {
    if (cin.fail()) {
        cerr << "Invalid input: " << message << endl;
        exit(EXIT_FAILURE);
    }
}

struct StackValidator {
    static void checkStackAccess(const stack<int>& s, const string& name) {
        if (s.empty()) {
            cerr << "Warning: Attempted operation on empty stack " << name << endl;
        }
    }
};

class DoubleStackManager {
private:
    stack<int> stackA, stackB;

    void transferStackContents(stack<int>& from, stack<int>& to) {
        stack<int> temp;
        while (!from.empty()) {
            temp.push(from.top());
            from.pop();
        }
        while (!temp.empty()) {
            to.push(temp.top());
            temp.pop();
        }
    }

public:
    void processOperation(char stackId, char operation, optional<int> data = nullopt) {
        try {
            if (stackId != 'A' && stackId != 'B') {
                throw invalid_argument("Invalid stack identifier");
            }

            stack<int>& targetStack = (stackId == 'A') ? stackA : stackB;
            stack<int>& otherStack = (stackId == 'A') ? stackB : stackA;

            switch (operation) {
                case 'I':
                    if (!data.has_value()) {
                        throw runtime_error("Missing data for insert operation");
                    }
                    targetStack.push(data.value());
                    break;
                case 'D':
                    StackValidator::checkStackAccess(targetStack, string(1, stackId));
                    if (!targetStack.empty()) {
                        targetStack.pop();
                    }
                    break;
                case 'M':
                    StackValidator::checkStackAccess(otherStack, string(1, (stackId == 'A') ? 'B' : 'A'));
                    transferStackContents(otherStack, targetStack);
                    break;
                default:
                    throw invalid_argument("Invalid operation code");
            }
        } catch (const exception& e) {
            cerr << "Operation error: " << e.what() << endl;
        }
    }

    pair<vector<int>, vector<int>> getFinalStacks() {
        vector<int> resultA, resultB;

        auto copyStack = [](stack<int>& s, vector<int>& v) {
            stack<int> temp;
            while (!s.empty()) {
                temp.push(s.top());
                s.pop();
            }
            while (!temp.empty()) {
                v.push_back(temp.top());
                temp.pop();
            }
        };

        copyStack(stackA, resultA);
        copyStack(stackB, resultB);

        return {resultA, resultB};
    }
};

int main() {
    DoubleStackManager manager;
    int n;
    cin >> n;
    validateInput(n, "Number of operations");

    for (int i = 0; i < n; ++i) {
        char stackId, operation;
        cin >> stackId >> operation;
        validateInput(stackId, "Stack identifier");
        validateInput(operation, "Operation code");

        if (operation == 'I') {
            int data;
            cin >> data;
            validateInput(data, "Data value");
            manager.processOperation(stackId, operation, data);
        } else {
            manager.processOperation(stackId, operation);
        }
    }

    auto [stackA, stackB] = manager.getFinalStacks();

    for (size_t i = 0; i < stackA.size(); ++i) {
        cout << stackA[i];
        if (i != stackA.size() - 1) cout << " ";
    }
    cout << endl;

    for (size_t i = 0; i < stackB.size(); ++i) {
        cout << stackB[i];
        if (i != stackB.size() - 1) cout << " ";
    }

    return 0;
}
