using namespace std;

void validateOperationCount(int n) {
    if (n < 1 || n > 100) {
        throw runtime_error("Invalid number of operations");
    }
}

void validateStackSelection(char c) {
    if (c != 'A' && c != 'B') {
        throw runtime_error("Invalid stack selection");
    }
}

void validateOperationType(char d) {
    if (d != 'I' && d != 'D' && d != 'M') {
        throw runtime_error("Invalid operation type");
    }
}

void performInsertion(stack<int>& target, int data) {
    if (data < -1000000 || data > 1000000) {
        throw runtime_error("Data value out of bounds");
    }
    target.push(data);
}

void performDeletion(stack<int>& target) {
    if (!target.empty()) {
        target.pop();
    } else {
        throw runtime_error("Attempt to pop empty stack");
    }
}

void performMerge(stack<int>& source, stack<int>& destination) {
    vector<int> tempStorage;
    while (!source.empty()) {
        tempStorage.push_back(source.top());
        source.pop();
    }
    reverse(tempStorage.begin(), tempStorage.end());
    for (int val : tempStorage) {
        destination.push(val);
    }
}

void printStack(stack<int> s) {
    vector<int> temp;
    while (!s.empty()) {
        temp.push_back(s.top());
        s.pop();
    }
    reverse(temp.begin(), temp.end());
    for (size_t i = 0; i < temp.size(); ++i) {
        cout << temp[i];
        if (i != temp.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

int main() {
    int n;
    cin >> n;
    try {
        validateOperationCount(n);
    } catch (const runtime_error& e) {
        cout << endl << endl;
        return 1;
    }

