            } catch (const runtime_error& e) {
                continue;
            }
        } else if (d == 'D') {
            try {
                if (c == 'A') {
                    performDeletion(a);
                } else {
                    performDeletion(b);
                }
            } catch (const runtime_error& e) {
                continue;
            }
        } else if (d == 'M') {
            try {
                if (c == 'A') {
                    performMerge(b, a);
                } else {
                    performMerge(a, b);
                }
            } catch (const runtime_error& e) {
                continue;
            }
        }
    }

