```cpp
#include<bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 1005;
const int MAX_DIRECTIONS = 4;

struct CanyonConfiguration {
    int width;
    int height;
    char terrain[MAX_DIMENSION][MAX_DIMENSION];
    bool visited[MAX_DIMENSION][MAX_DIMENSION];
};

struct Coordinate {
    int x;
    int y;
};

struct DirectionOffset {
    int dx;
    int dy;
};

class GrasslandAnalyzer {
private:
    CanyonConfiguration config;
    int grasslandCount;
    DirectionOffset directions[MAX_DIRECTIONS] = {{-1,0},{1,0},{0,-1},{0,1}};

    bool validateCoordinates(int x, int y) {
        return (x >= 0) && (x < config.height) && (y >= 0) && (y < config.width);
    }

    void exploreGrassland(int startX, int startY) {
        stack<Coordinate> explorationStack;
        explorationStack.push({startX, startY});
        config.visited[startX][startY] = true;

        while (!explorationStack.empty()) {
            Coordinate current = explorationStack.top();
            explorationStack.pop();

            for (int i = 0; i < MAX_DIRECTIONS; i++) {
                Coordinate neighbor = {
                    current.x + directions[i].dx,
                    current.y + directions[i].dy
                };

                if (validateCoordinates(neighbor.x, neighbor.y) &&
                    !config.visited[neighbor.x][neighbor.y] &&
                    config.terrain[neighbor.x][neighbor.y] == '#') {
                    config.visited[neighbor.x][neighbor.y] = true;
                    explorationStack.push(neighbor);
                }
            }
        }
    }

public:
    GrasslandAnalyzer() : grasslandCount(0) {
        memset(config.visited, false, sizeof(config.visited));
    }

    void initializeConfiguration() {
        ifstream inputFile("hiking.in");
        ofstream outputFile("hiking.out");

        if (!inputFile.is_open() || !outputFile.is_open()) {
            cerr << "File operation failed" << endl;
            exit(EXIT_FAILURE);
        }

        inputFile >> config.height >> config.width;

        for (int i = 0; i < config.height; i++) {
            string row;
            inputFile >> row;
            for (int j = 0; j < config.width; j++) {
                config.terrain[i][j] = row[j];
            }
        }

        inputFile.close();
    }

    void processCanyon() {
        for (int i = 0; i < config.height; i++) {
            for (int j = 0; j < config.width; j++) {
                if (config.terrain[i][j] == '#' && !config.visited[i][j]) {
                    exploreGrassland(i, j);
                    grasslandCount++;
                }
            }
        }
    }

    void outputResult() {
        ofstream outputFile("hiking.out");
        if (!outputFile.is_open()) {
            cerr << "Output file operation failed" << endl;
            exit(EXIT_FAILURE);
        }
        outputFile << grasslandCount << endl;
        outputFile.close();
    }
};

int main() {
    GrasslandAnalyzer analyzer;
    analyzer.initializeConfiguration();
    analyzer.processCanyon();
    analyzer.outputResult();
    return 0;
}
