#include<bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 1005;
const int MAX_DIRECTIONS = 4;

struct Coordinate {
    int x;
    int y;
};

struct CanyonMap {
    char grid[MAX_DIMENSION][MAX_DIMENSION];
    int rows;
    int cols;
};

struct ExplorationState {
    bool visited[MAX_DIMENSION][MAX_DIMENSION];
    int grassland_count;
};

int direction_offsets[MAX_DIRECTIONS][2] = {
    {-1, 0},
    {1, 0},
    {0, -1},
    {0, 1}
};

bool validate_coordinate_bounds(Coordinate coord, CanyonMap map) {
    bool x_valid = (coord.x >= 0) && (coord.x < map.rows);
    bool y_valid = (coord.y >= 0) && (coord.y < map.cols);
    return x_valid && y_valid;
}

void initialize_exploration_state(ExplorationState& state, CanyonMap map) {
    state.grassland_count = 0;
    for (int i = 0; i < map.rows; i++) {
        for (int j = 0; j < map.cols; j++) {
            state.visited[i][j] = false;
        }
    }
}

void explore_grassland(Coordinate current, CanyonMap& map, ExplorationState& state) {
    state.visited[current.x][current.y] = true;

    for (int direction_index = 0; direction_index < MAX_DIRECTIONS; direction_index++) {
        Coordinate neighbor = {
            current.x + direction_offsets[direction_index][0],
            current.y + direction_offsets[direction_index][1]
        };

        if (validate_coordinate_bounds(neighbor, map)) {
            if (!state.visited[neighbor.x][neighbor.y] && map.grid[neighbor.x][neighbor.y] == '#') {
                explore_grassland(neighbor, map, state);
            }
        }
    }
}

void process_canyon_map(CanyonMap& map, ExplorationState& state) {
    for (int i = 0; i < map.rows; i++) {
        for (int j = 0; j < map.cols; j++) {
            if (map.grid[i][j] == '#' && !state.visited[i][j]) {
                Coordinate start = {i, j};
                explore_grassland(start, map, state);
                state.grassland_count++;
            }
        }
    }
}

void verify_input_dimensions(int n, int m) {
    if (n < 1 || n > 100 || m < 1 || m > 100) {
        cerr << "Invalid dimensions detected" << endl;
        exit(EXIT_FAILURE);
    }
}

int main() {
