const int MAX_DIM = 1005;
const int MIN_DIM = 1;

struct CanyonValidation {
    bool is_valid_dimension(int val) {
        return val >= MIN_DIM && val <= MAX_DIM - 5;
    }
    bool is_valid_cell(char c) {
        return c == '#' || c == '.';
    }
};

class AdvancedCanyonAnalyzer {
private:
    int n, m;
    char maze[MAX_DIM][MAX_DIM];
    bool vis[MAX_DIM][MAX_DIM];
    int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    CanyonValidation validator;

    void initialize_visited() {
        for(int i = 0; i < MAX_DIM; i++) {
            for(int j = 0; j < MAX_DIM; j++) {
                vis[i][j] = false;
            }
        }
    }

    bool is_in_bounds(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    void perform_sanitized_dfs(int x, int y) {
        if(!is_in_bounds(x, y) || vis[x][y] || maze[x][y] != '#') {
            return;
        }

        vis[x][y] = true;

        for(int i = 0; i < 4; i++) {
            int tx = x + dir[i][0];
            int ty = y + dir[i][1];
            if(is_in_bounds(tx, ty) && !vis[tx][ty] && maze[tx][ty] == '#') {
                perform_sanitized_dfs(tx, ty);
            }
        }
    }

public:
    AdvancedCanyonAnalyzer() {
        initialize_visited();
    }

    void load_canyon() {
        ifstream input_file("hiking.in");
        if(!input_file.is_open()) {
            cerr << "Error opening input file" << endl;
            exit(1);
        }

        input_file >> n >> m;
        if(!validator.is_valid_dimension(n) || !validator.is_valid_dimension(m)) {
            cerr << "Invalid canyon dimensions" << endl;
            exit(1);
        }

        for(int i = 0; i < n; i++) {
            string row;
            input_file >> row;
            if(row.length() != m) {
                cerr << "Invalid row length" << endl;
                exit(1);
            }
            for(int j = 0; j < m; j++) {
                if(!validator.is_valid_cell(row[j])) {
                    cerr << "Invalid cell character" << endl;
                    exit(1);
                }
                maze[i][j] = row[j];
            }
        }
        input_file.close();
    }

    int calculate_required_people() {
        int people_count = 0;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(maze[i][j] == '#' && !vis[i][j]) {
                    perform_sanitized_dfs(i, j);
                    people_count++;
                }
            }
        }
        return people_count;
    }

    void save_result(int result) {
        ofstream output_file("hiking.out");
        if(!output_file.is_open()) {
            cerr << "Error opening output file" << endl;
            exit(1);
        }
        output_file << result << endl;
        output_file.close();
    }
};

int main() {
    AdvancedCanyonAnalyzer analyzer;
    analyzer.load_canyon();
    int result = analyzer.calculate_required_people();
    analyzer.save_result(result);
    return 0;
}
