using namespace std;

bool validateString(const string& s) {
    int balance = 0;
    for (char c : s) {
        if (c == '(') balance++;
        else if (c == ')') balance--;
        if (balance < 0) return false;
    }
    return balance == 0;
}

bool isNumericChar(char c) {
    return c >= '0' && c <= '9';
}

bool isAlphaChar(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

string processNestedPattern(const string& pattern, int multiplier) {
    string result;
    for (int i = 0; i < multiplier; ++i) {
        result += pattern;
    }
    return result;
}

string decodeSegment(const string& segment) {
    stack<char> processingStack;
    string validationBuffer;
    for (char c : segment) {
        if (c == '(' || c == ')' || isNumericChar(c) || isAlphaChar(c)) {
            validationBuffer += c;
        }
    }
    if (!validateString(validationBuffer)) {
        throw runtime_error("Invalid input pattern");
    }
    for (int i = 0; i < segment.size(); ++i) {
        char current = segment[i];
        if (current != ')') {
            processingStack.push(current);
        } else {
            string tempBuffer;
            while (!processingStack.empty() && processingStack.top() != '(') {
                tempBuffer += processingStack.top();
                processingStack.pop();
            }
            if (processingStack.empty()) {
                throw runtime_error("Unbalanced parentheses");
            }
            processingStack.pop();
            reverse(tempBuffer.begin(), tempBuffer.end());
            if (!processingStack.empty() && isNumericChar(processingStack.top())) {
                int repeatCount = processingStack.top() - '0';
                processingStack.pop();
                string repeatedPattern = processNestedPattern(tempBuffer, repeatCount);
                for (char rc : repeatedPattern) {
                    processingStack.push(rc);
                }
            } else {
                for (char rc : tempBuffer) {
                    processingStack.push(rc);
                }
            }
        }
    }
    string decoded;
    while (!processingStack.empty()) {
        decoded += processingStack.top();
        processingStack.pop();
    }
    reverse(decoded.begin(), decoded.end());
    return decoded;
