void safely_push_to_stack(stack<char>& st, char c) {
    if (is_valid_character(c)) {
        st.push(c);
    } else {
        throw runtime_error("Attempt to push invalid character to stack");
    }
}

string safely_pop_from_stack(stack<char>& st) {
    if (st.empty()) {
        throw runtime_error("Attempt to pop from empty stack");
    }
    string result;
    while (!st.empty() && st.top() != '(') {
        result += st.top();
        st.pop();
    }
    if (!st.empty() && st.top() == '(') {
        st.pop();
    }
    reverse(result.begin(), result.end());
    return result;
}

int safely_get_repetition_count(stack<char>& st) {
    if (st.empty() || !is_valid_digit(st.top())) {
        return 1;
    }
    int count = st.top() - '0';
    st.pop();
    return count;
}

string decode_string(const string& s) {
    stack<char> st;
