class CyclicShifter {
private:
    int shiftAmount;
    bool isUpperCase(char c) { return c >= 'A' && c <= 'Z'; }
    bool isLowerCase(char c) { return c >= 'a' && c <= 'z'; }
    bool isDigit(char c) { return c >= '0' && c <= '9'; }

    char shiftAlpha(char c, int base, int range) {
        int normalized = c - base;
        int shifted = (normalized + shiftAmount) % range;
        if (shifted < 0) shifted += range;
        return base + shifted;
    }

public:
    CyclicShifter(int z) : shiftAmount(z) {
        if (z < 0 || z > 100) throw invalid_argument("Invalid shift value");
    }

    char shiftCharacter(char c) {
        if (!CharacterValidator::isValidChar(c)) return c;

        if (isUpperCase(c)) {
            return shiftAlpha(c, 'A', 26);
        } else if (isLowerCase(c)) {
            return shiftAlpha(c, 'a', 26);
        } else if (isDigit(c)) {
            return shiftAlpha(c, '0', 10);
