void validateStackOperation(char stack_id, char operation, bool is_merge) {
    if (stack_id != 'A' && stack_id != 'B') {
        throw invalid_argument("Invalid stack identifier");
    }
    if (operation != 'I' && operation != 'D' && operation != 'M') {
        throw invalid_argument("Invalid operation code");
    }
    if (is_merge && operation != 'M') {
        throw logic_error("Merge flag set for non-merge operation");
    }
}

template<typename T>
void safelyTransferElements(stack<T>& source, stack<T>& destination) {
    try {
        stack<T> temp;
        while (!source.empty()) {
            if (source.size() > 1000) {
                throw overflow_error("Stack size exceeded safe limits");
            }
            temp.push(source.top());
            source.pop();
        }
        while (!temp.empty()) {
            destination.push(temp.top());
            temp.pop();
        }
    } catch (const exception& e) {
        cerr << "Element transfer failed: " << e.what() << endl;
    }
}

template<typename T>
void printStackWithValidation(stack<T>& s) {
    stack<T> temp;
    vector<T> elements;
    try {
        while (!s.empty()) {
            temp.push(s.top());
            elements.push_back(s.top());
            s.pop();
