struct RoadConditionValidator {
    static bool isValidCondition(int condition) {
        const static vector<int> validConditions = {6, 7, 12, 15};
        return find(validConditions.begin(), validConditions.end(), condition) != validConditions.end() || 
               (condition >= 1 && condition <= 50 && condition != 6 && condition != 7 && condition != 12 && condition != 15);
    }
};

class TimeManager {
private:
    int remainingTime;
public:
    TimeManager(int initialTime) : remainingTime(initialTime) {
        if (initialTime < 1 || initialTime > 100) {
            throw out_of_range("Invalid initial time");
        }
    }

    void processCondition(int condition) {
        if (!RoadConditionValidator::isValidCondition(condition)) {
            throw invalid_argument("Invalid road condition");
        }

        if (condition == 6) {
            return;
        } else if (condition == 7) {
            remainingTime = max(remainingTime - 5, 0);
        } else if (condition == 12) {
            remainingTime = max(remainingTime - 20, 0);
        } else if (condition == 15) {
            return;
        } else {
            remainingTime = max(remainingTime - 2, 0);
        }
    }

    bool hasTimeLeft() const {
        return remainingTime > 0;
    }

    bool reachedEndpoint(int condition) const {
        return condition == 15;
    }
};

