#include <vector>
#include <algorithm>
#include <cctype>
#include <sstream>
#include <iterator>
#include <stdexcept>
#include <utility>

using namespace std;

namespace StringProcessing {
    class InputValidator {
    public:
        static bool validateInputLength(const string& s) {
            return s.length() <= 100;
        }
    };

    class CaseConverter {
    public:
        static void convertToLowerExceptI(string& s) {
            for (char& c : s) {
                if (c >= 'A' && c <= 'Z' && c != 'I') {
                    c = tolower(c);
                }
            }
        }
    };

    class PunctuationReplacer {
    public:
        static void replaceQuestionMarks(string& s) {
            replace(s.begin(), s.end(), '?', '!');
        }
    };

    class WordSplitter {
    public:
        static vector<string> splitIntoWords(const string& s) {
            vector<string> words;
            istringstream iss(s);
            copy(istream_iterator<string>(iss),
                 istream_iterator<string>(),
                 back_inserter(words));
            return words;
        }
    };

    class WordProcessor {
    private:
        static bool isWordIndependent(const string& word, size_t index, const vector<string>& words) {
            if (word.empty()) return false;
            if (index > 0 && words[index-1].empty()) return false;
            if (index < words.size()-1 && words[index+1].empty()) return false;
            return true;
        }

    public:
        static void processCanYou(vector<string>& words) {
            for (size_t i = 0; i < words.size(); ++i) {
                if (i + 1 < words.size() && 
                    (words[i] == "can" || words[i] == "could") && 
                    words[i+1] == "you" &&
                    isWordIndependent(words[i], i, words) &&
                    isWordIndependent(words[i+1], i+1, words)) {
                    words[i] = "I";
                    words.insert(words.begin() + i + 1, words[i] == "I" ? "can" : "could");
                    words.erase(words.begin() + i + 2);
                }
            }
        }

        static void processIAndMe(vector<string>& words) {
            for (size_t i = 0; i < words.size(); ++i) {
                if ((words[i] == "I" || words[i] == "me") && 
                    isWordIndependent(words[i], i, words)) {
                    words[i] = "you";
                }
            }
        }
    };

    class OutputGenerator {
    public:
        static string joinWords(const vector<string>& words) {
            if (words.empty()) return "";
            ostringstream oss;
            copy(words.begin(), words.end()-1, ostream_iterator<string>(oss, " "));
            oss << words.back();
            return oss.str();
        }
    };
}

int main() {
    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    while (n--) {
        string input;
        getline(cin, input);

        try {
            if (!StringProcessing::InputValidator::validateInputLength(input)) {
                throw runtime_error("Input length exceeds maximum allowed");
            }

            StringProcessing::CaseConverter::convertToLowerExceptI(input);
            StringProcessing::PunctuationReplacer::replaceQuestionMarks(input);

            vector<string> words = StringProcessing::WordSplitter::splitIntoWords(input);
            if (words.empty()) continue;

            StringProcessing::WordProcessor::processIAndMe(words);
            StringProcessing::WordProcessor::processCanYou(words);

            string output = StringProcessing::OutputGenerator::joinWords(words);
            cout << output << endl;
        } catch (const exception& e) {
            cerr << "Error processing input: " << e.what() << endl;
            continue;
        }
    }

    return 0;
}
