#include <iostream>
#include <limits>
#include <stdexcept>
#include <type_traits>
#include <cmath>
using namespace std;

template<typename T>
constexpr bool is_safe_abs(T value) {
    return !(numeric_limits<T>::is_signed && value == numeric_limits<T>::min());
}

template<typename T>
T checked_abs(T value) {
    if constexpr (numeric_limits<T>::is_signed) {
        if (!is_safe_abs(value)) {
            throw overflow_error("Absolute value overflow detected");
        }
    }
    return value < 0 ? -value : value;
}

template<typename T>
void validate_input(T value) {
    if (cin.fail()) {
        throw invalid_argument("Invalid input type");
    }
    if (is_same<T, int>::value && (value < numeric_limits<int>::min() || value > numeric_limits<int>::max())) {
        throw out_of_range("Input out of int range");
    }
}

template<typename T>
pair<T, T> get_absolute_values(T a, T b) {
    T abs_a, abs_b;
    try {
        abs_a = checked_abs(a);
        abs_b = checked_abs(b);
    } catch (const overflow_error& e) {
        cerr << "Error: " << e.what() << endl;
        throw;
    }
    return make_pair(abs_a, abs_b);
}

template<typename T>
void print_sorted(T a, T b) {
    auto [abs_a, abs_b] = get_absolute_values(a, b);

    if (abs_a > abs_b) {
        cout << b << " " << a;
    } else if (abs_a == abs_b) {
        if (a > b) {
            cout << b << " " << a;
        } else {
            cout << a << " " << b;
        }
    } else {
        cout << a << " " << b;
    }
    cout << endl;
}

int main() {
    try {
        int a, b;
        cin >> a >> b;

        validate_input(a);
        validate_input(b);

        if (cin.peek() != EOF && cin.peek() != '\n') {
            throw invalid_argument("Extra input detected");
