    public:
        static bool validateIntegerRange(const string& input) {
            istringstream iss(input);
            long long temp;
            iss >> temp;
            return !iss.fail() && 
                   temp >= numeric_limits<int>::min() && 
                   temp <= numeric_limits<int>::max();
        }

        static void verifyInputCount(const vector<string>& tokens) {
            if (tokens.size() != 2) {
                throw runtime_error("Invalid input count");
            }
        }
    };

    class AbsoluteValueComparator {
    private:
        static pair<int, int> getAbsoluteValues(int x, int y) {
            return make_pair(
                x < 0 ? -x * (x != numeric_limits<int>::min()) : x,
                y < 0 ? -y * (y != numeric_limits<int>::min()) : y
            );
        }

    public:
        static vector<int> compareAndSort(int a, int b) {
            auto [absA, absB] = getAbsoluteValues(a, b);

            if (absA != absB) {
                return absA < absB ? vector<int>{a, b} : vector<int>{b, a};
            } else {
                if (a == b) {
                    return vector<int>{a, b};
                } else {
                    return a < b ? vector<int>{a, b} : vector<int>{b, a};
                }
            }
        }
    };
}

