class TalentShowAnalyzer {
private:
    vector<PerformanceEntry> performances;
    int totalAuditionHours;
    int remainingTimeMinutes;
    bool garlicPerformed;
    bool garlicDisqualified;
    bool reachedEnd;

    void initializeEntry(PerformanceEntry& entry) {
        entry.wasDisqualified = false;
        entry.isKaomianjin = false;
        entry.isTingtingting = false;
        entry.processed = false;
    }

    void processPerformanceEntry(const string& name, int duration) {
        PerformanceEntry entry;
        entry.performerName = name;
        entry.durationMinutes = duration;
        initializeEntry(entry);

        if (name == "kaomianjin") {
            entry.isKaomianjin = true;
        } else if (name == "tingtingting") {
            entry.isTingtingting = true;
        }

        performances.push_back(entry);
    }

    void handleDisqualification() {
        if (!performances.empty()) {
            performances.back().wasDisqualified = true;
            performances.back().processed = true;
        }
    }

    void processAllPerformances() {
        remainingTimeMinutes = totalAuditionHours * 60;
        garlicPerformed = false;
        garlicDisqualified = false;
        reachedEnd = false;

        for (size_t i = 0; i < performances.size(); ++i) {
            if (performances[i].processed) continue;

            if (performances[i].isTingtingting) {
                handleDisqualification();
                continue;
            }

            if (performances[i].durationMinutes > remainingTimeMinutes) {
                break;
            }

            remainingTimeMinutes -= performances[i].durationMinutes;
            performances[i].processed = true;

            if (performances[i].isKaomianjin) {
                garlicPerformed = true;
                if (i + 1 < performances.size() && performances[i+1].isTingtingting) {
                    garlicDisqualified = true;
                }
            }
        }

        reachedEnd = true;
    }

public:
    TalentShowAnalyzer(int hours) : totalAuditionHours(hours) {}

    void addPerformance(const string& name, int duration) {
        processPerformanceEntry(name, duration);
    }

    void addDisqualification() {
        handleDisqualification();
    }

    string getResult() {
        processAllPerformances();

        if (garlicDisqualified) {
            return "Hahaha.";
        }

        bool foundGarlic = false;
        for (const auto& entry : performances) {
            if (entry.isKaomianjin && entry.processed) {
                foundGarlic = true;
                break;
            }
        }

        if (!foundGarlic) {
            return "Unfortunately.";
        }

        return "Congratulations!";
    }
};

