struct TreeValidation {
    bool is_valid_tree;
    bool has_cycle;
    bool is_connected;
};

vector<int> G[MAX_NODES];
int fa[MAX_NODES];
int degree_cache[MAX_NODES];
bool visited[MAX_NODES];
TreeValidation tree_validator;

void initialize_globals() {
    for (int i = 0; i < MAX_NODES; i++) {
        vector<int>().swap(G[i]);
        fa[i] = -1;
        degree_cache[i] = -1;
        visited[i] = false;
    }
    tree_validator.is_valid_tree = true;
    tree_validator.has_cycle = false;
    tree_validator.is_connected = true;
}

void validate_tree_structure(int node, int parent) {
    if (visited[node]) {
        tree_validator.has_cycle = true;
        return;
    }
    visited[node] = true;
    for (size_t i = 0; i < G[node].size(); i++) {
        int neighbor = G[node][i];
        if (neighbor != parent) {
            validate_tree_structure(neighbor, node);
        }
    }
}

void precompute_degrees(int n) {
    for (int i = 0; i < n; i++) {
        degree_cache[i] = G[i].size();
        if (fa[i] == -1) {
            degree_cache[i]++;
        }
    }
}

bool is_p_node(int node, int n) {
    if (node < 0 || node >= n) {
        throw out_of_range("Node index out of bounds");
    }
    int current_degree = degree_cache[node];
    bool is_valid_p_node = true;
    for (size_t i = 0; i < G[node].size(); i++) {
        int child = G[node][i];
        if (child == fa[node]) continue;
        if (degree_cache[child] > current_degree) {
            is_valid_p_node = false;
            break;
        }
    }
    if (fa[node] != -1 && degree_cache[fa[node]] > current_degree) {
        is_valid_p_node = false;
    }
    return is_valid_p_node;
}

int count_p_nodes(int n) {
    int p_count = 0;
    for (int i = 0; i < n; i++) {
        try {
            if (is_p_node(i, n)) {
                p_count++;
            }
        } catch (const exception& e) {
            cerr << "Error processing node " << i << ": " << e.what() << endl;
        }
    }
    return p_count;
}

