#include <algorithm>
#include <stdexcept>
#include <limits>
using namespace std;

vector<int> g[1005];
int fa[1005];
int degree_cache[1005];
bool visited[1005];

void validate_input_range(int x, int n) {
    if (x < 0 || x >= n) {
        throw out_of_range("Node index out of bounds");
    }
}

void clear_global_state(int n) {
    for (int i = 0; i < n; i++) {
        vector<int>().swap(g[i]);
    }
    memset(fa, 0, sizeof(fa));
    memset(degree_cache, 0, sizeof(degree_cache));
    memset(visited, false, sizeof(visited));
}

int calculate_degree(int node, int n) {
    if (visited[node]) return degree_cache[node];
    visited[node] = true;
    int deg = g[node].size();
    if (fa[node] != 0) deg++;
    degree_cache[node] = deg;
    return deg;
}

bool is_p_node(int node, int n) {
    if (node < 0 || node >= n) return false;

    int current_degree = calculate_degree(node, n);
    bool valid = true;

    for (size_t i = 0; i < g[node].size(); ++i) {
        int child = g[node][i];
        int child_degree = calculate_degree(child, n);
        if (current_degree < child_degree) {
            valid = false;
            break;
        }
    }

    if (valid && fa[node] != 0) {
        int parent_degree = calculate_degree(fa[node], n);
        if (current_degree < parent_degree) {
            valid = false;
        }
    }

    return valid;
}

int main() {
    freopen("p.in", "r", stdin);
    freopen("p.out", "w", stdout);

    int t;
    cin >> t;
    if (t < 1 || t > 100) {
        cerr << "Invalid number of test cases" << endl;
        return 1;
    }

    while (t--) {
        int n;
        cin >> n;
        if (n < 1 || n > 1000) {
            cerr << "Invalid number of nodes" << endl;
            continue;
        }

        try {
            for (int i = 0; i < n - 1; i++) {
                int u, v;
                cin >> u >> v;
                validate_input_range(u, n);
                validate_input_range(v, n);
                g[u].push_back(v);
                fa[v] = u;
            }
        } catch (const exception& e) {
            cerr << "Input error: " << e.what() << endl;
            clear_global_state(n);
            continue;
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (is_p_node(i, n)) {
                ans++;
            }
        }

        cout << ans << endl;
        clear_global_state(n);
    }

    return 0;
}
