        if (!(isdigit(c) || islower(c))) {
            throw runtime_error("Invalid character in input");
        }
    }
}

vector<DecryptionRule> initializeRules() {
    vector<DecryptionRule> rules;
    rules.push_back({SPECIAL_SSS, "."});
    rules.push_back({SPECIAL_KKK, " "});
    return rules;
}

void processSpecialPatterns(string& s, const vector<DecryptionRule>& rules) {
    for (const auto& rule : rules) {
        size_t pos = 0;
        while ((pos = s.find(rule.encrypted, pos)) {
            if (pos == string::npos) break;
            if (pos + rule.encrypted.length() > s.length()) {
                throw runtime_error("Pattern exceeds string length");
            }
            s.replace(pos, rule.encrypted.length(), rule.decrypted);
            pos += rule.decrypted.length();
        }
    }
}

bool isShiftableCharacter(char c) {
    return (c >= 'd' && c <= 'z') || 
