int safe_abs(int x) {
    if (x == numeric_limits<int>::min()) {
        throw runtime_error("Absolute value overflow detected");
    }
    return (x < 0) ? -x : x;
}

bool validate_input(const string& input) {
    istringstream iss(input);
    int temp1, temp2;
    char ch;
    return (iss >> temp1 >> temp2) && !(iss >> ch);
}

void process_absolute_sorting(int a, int b) {
    int a_abs, b_abs;
    bool a_overflow = false;
    bool b_overflow = false;

    try {
        a_abs = safe_abs(a);
    } catch (const runtime_error& e) {
        a_abs = numeric_limits<int>::max();
        a_overflow = true;
    }

    try {
        b_abs = safe_abs(b);
    } catch (const runtime_error& e) {
        b_abs = numeric_limits<int>::max();
        b_overflow = true;
    }

    bool should_swap = false;
    bool absolute_equal = false;

    if (!a_overflow && !b_overflow) {
        if (a_abs > b_abs) {
            should_swap = true;
        } else if (a_abs == b_abs) {
            absolute_equal = true;
            if (a > b) {
                should_swap = true;
            }
        }
    } else if (a_overflow && !b_overflow) {
        should_swap = false;
    } else if (!a_overflow && b_overflow) {
        should_swap = true;
    } else {
        if (a > b) {
            should_swap = true;
        }
    }

    if (should_swap) {
        cout << b << " " << a << endl;
    } else {
        cout << a << " " << b << endl;
    }
}

