#include <iostream>
#include <vector>
#include <stdexcept>
#include <algorithm>
#include <cctype>
using namespace std;

struct EncryptionParameters {
    int x;
    int y;
    int z;
};

class CharacterValidator {
public:
    static bool isUppercase(char c) {
        return (c >= 'A' && c <= 'Z');
    }
    static bool isLowercase(char c) {
        return (c >= 'a' && c <= 'z');
    }
    static bool isDigit(char c) {
        return (c >= '0' && c <= '9');
    }
    static bool isSpecialCharacter(char c) {
        return !(isUppercase(c) || isLowercase(c) || isDigit(c));
    }
};

class CharacterTransformer {
private:
    static char transformUppercase(char c, int shift) {
        int normalizedShift = shift % 26;
        if (normalizedShift < 0) normalizedShift += 26;
        return (c - 'A' + normalizedShift) % 26 + 'A';
    }
    static char transformLowercase(char c, int shift) {
        int normalizedShift = shift % 26;
        if (normalizedShift < 0) normalizedShift += 26;
        return (c - 'a' + normalizedShift) % 26 + 'a';
    }
    static char transformDigit(char c, int shift) {
        int normalizedShift = shift % 10;
        if (normalizedShift < 0) normalizedShift += 10;
        return (c - '0' + normalizedShift) % 10 + '0';
    }
public:
    static char transformCharacter(char c, int shift) {
        if (CharacterValidator::isUppercase(c)) {
            return transformUppercase(c, shift);
        } else if (CharacterValidator::isLowercase(c)) {
            return transformLowercase(c, shift);
        } else if (CharacterValidator::isDigit(c)) {
            return transformDigit(c, shift);
        }
        return c;
    }
};

class InputSanitizer {
public:
    static void validateParameters(const EncryptionParameters& params) {
        if (params.x <= 10 || params.x > 100) {
            throw invalid_argument("Invalid value for x");
        }
        if (params.y <= 0 || params.y > 10) {
            throw invalid_argument("Invalid value for y");
        }
        if (params.z <= 0 || params.z > 100) {
            throw invalid_argument("Invalid value for z");
        }
    }
};

class EncryptionEngine {
private:
    EncryptionParameters params;
    vector<char> characters;
public:
    EncryptionEngine(const EncryptionParameters& p) : params(p) {
        characters.reserve(params.x);
    }
    void readCharacters() {
        char c;
        for (int i = 0; i < params.x; ++i) {
            cin >> c;
            characters.push_back(c);
        }
    }
    void processCharacters() {
        for (int i = 0; i < characters.size(); ++i) {
            if ((i + 1) % params.y == 0) {
                characters[i] = CharacterTransformer::transformCharacter(characters[i], params.z);
            }
        }
    }
    void outputResult() {
        for (const auto& c : characters) {
            cout << c;
        }
        cout << endl;
    }
};

int main() {
    try {
        EncryptionParameters params;
        cin >> params.x >> params.y >> params.z;
        InputSanitizer::validateParameters(params);

        EncryptionEngine engine(params);
        engine.readCharacters();

        if (params.y <= 0) {
            throw runtime_error("Division by zero risk detected");
        }

        engine.processCharacters();
        engine.outputResult();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
