};

vector<PerformanceRecord> performanceLog;
vector<int> cumulativeTimeTracker;

void validateInputRange(int value, int minVal, int maxVal, const string& context) {
    if (value < minVal || value > maxVal) {
        throw out_of_range(context + " out of valid range");
    }
}

void processPerformance(const string& name, int duration, int& currentSum, int totalAllowed) {
    PerformanceRecord record;
    record.name = name;
    record.duration = duration;
    record.wasInterrupted = false;

    if (currentSum + duration > totalAllowed) {
        performanceLog.push_back(record);
        throw runtime_error("Time limit exceeded");
    }

    currentSum += duration;
    cumulativeTimeTracker.push_back(currentSum);
    performanceLog.push_back(record);
}

void handleInterruption(int& currentSum) {
    if (performanceLog.empty()) {
        throw runtime_error("No performance to interrupt");
    }

    PerformanceRecord& lastRecord = performanceLog.back();
    if (lastRecord.wasInterrupted) {
        throw runtime_error("Double interruption detected");
    }

    lastRecord.wasInterrupted = true;
    currentSum -= lastRecord.duration;
    cumulativeTimeTracker.pop_back();
}

int main() {
