#include<bits/stdc++.h>
using namespace std;

struct CompressionState {
    string current_pattern;
    char previous_char;
    int consecutive_count;
    bool is_first_iteration;
    bool output_initialized;
    vector<int> compression_sequence;
};

void initializeCompressionState(CompressionState& state, const string& initial_pattern) {
    state.current_pattern = initial_pattern;
    state.previous_char = '0';
    state.consecutive_count = 1;
    state.is_first_iteration = true;
    state.output_initialized = false;
    state.compression_sequence.clear();
}

void processCharacter(CompressionState& state, char current_char) {
    if (state.is_first_iteration) {
        state.previous_char = current_char;
        state.is_first_iteration = false;
        return;
    }

    if (current_char == state.previous_char) {
        state.consecutive_count++;
    } else {
        state.compression_sequence.push_back(state.consecutive_count);
        state.previous_char = (state.previous_char == '0') ? '1' : '0';
        state.consecutive_count = 1;
    }
}

void finalizeCompression(CompressionState& state) {
    if (state.consecutive_count > 0) {
        state.compression_sequence.push_back(state.consecutive_count);
    }
}

void validateInputSize(const vector<string>& matrix, int expected_size) {
    if (matrix.size() != expected_size) {
        cerr << "Input matrix size mismatch" << endl;
        exit(1);
    }
    for (const auto& row : matrix) {
        if (row.size() != expected_size) {
            cerr << "Input row size mismatch" << endl;
            exit(1);
        }
    }
}

int main() {
    ifstream input_file("zip.in");
    ofstream output_file("zip.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "File opening failed" << endl;
        return EXIT_FAILURE;
    }

    vector<string> matrix;
    string first_line;
    getline(input_file, first_line);
    matrix.push_back(first_line);
    const int n = first_line.size();

    for (int i = 1; i < n; ++i) {
        string line;
        if (!getline(input_file, line)) {
            cerr << "Incomplete input" << endl;
            return EXIT_FAILURE;
        }
        matrix.push_back(line);
    }

    validateInputSize(matrix, n);

    string concatenated;
    for (const auto& row : matrix) {
        concatenated += row;
    }

    CompressionState state;
    initializeCompressionState(state, concatenated);

    for (char c : concatenated) {
        if (c != '0' && c != '1') {
            cerr << "Invalid character in input" << endl;
            return EXIT_FAILURE;
        }
        processCharacter(state, c);
    }

    finalizeCompression(state);

    output_file << n << " ";
    for (size_t i = 0; i < state.compression_sequence.size(); ++i) {
        output_file << state.compression_sequence[i];
        if (i != state.compression_sequence.size() - 1) {
            output_file << " ";
        }
    }

    input_file.close();
    output_file.close();

    return 0;
}
