struct NumberData {
    string original;
    int numeric;
    int sum;
    bool valid;
};

vector<NumberData> processNumbers(const vector<string>& inputs) {
    vector<NumberData> processed;
    for (const auto& input : inputs) {
        NumberData data;
        data.original = input;
        data.valid = true;

        try {
            data.numeric = stoi(input);
            if (data.numeric <= 0 || data.numeric >= 10000) {
                data.valid = false;
                continue;
            }
        } catch (...) {
            data.valid = false;
            continue;
        }

        int temp = data.numeric;
        data.sum = 0;
        while (temp > 0) {
            int digit = temp % 10;
            if (digit < 0 || digit > 9) {
                data.valid = false;
                break;
            }
            data.sum += digit;
            temp /= 10;
            if (temp < 0) {
                data.valid = false;
                break;
            }
        }

        if (data.valid) {
            processed.push_back(data);
        }
    }
    return processed;
}

bool validateInputCount(int n) {
    if (n <= 0 || n >= 101) {
        cerr << "Invalid input count detected" << endl;
        return false;
    }
    return true;
}

bool compareNumbers(const NumberData& a, const NumberData& b) {
    if (!a.valid || !b.valid) {
        return false;
    }

    if (a.sum != b.sum) {
        return a.sum < b.sum;
    } else {
        if (a.numeric != b.numeric) {
            return a.numeric < b.numeric;
        } else {
            return a.original.length() < b.original.length();
        }
    }
}

void handleInputValidation(int& n) {
    while (true) {
        cin >> n;
        if (cin.fail()) {
