using namespace std;

template<typename T>
constexpr bool is_valid_road_condition(T value) {
    return (value == 6 || value == 7 || value == 12 || value == 15 || (value >= 1 && value <= 50 && value != 6 && value != 7 && value != 12 && value != 15));
}

struct TimeValidator {
    static bool validate_initial_time(int n) {
        return n >= 1 && n <= 100;
    }
};

class RoadConditionProcessor {
private:
    int remaining_time;
    bool reached_endpoint;
    int iterations;
    vector<int> historical_conditions;

    void process_condition(int condition) {
        if (!is_valid_road_condition(condition)) {
            throw invalid_argument("Invalid road condition detected");
        }

        historical_conditions.push_back(condition);

        if (condition == 15) {
            reached_endpoint = true;
            return;
        }

        if (remaining_time <= 0) {
            return;
        }

        if (condition == 6) {
            return;
        } else if (condition == 7) {
            remaining_time = max(remaining_time - 5, 0);
        } else if (condition == 12) {
            remaining_time = max(remaining_time - 20, 0);
        } else {
            remaining_time = max(remaining_time - 2, 0);
        }

        iterations++;
    }

public:
    RoadConditionProcessor(int initial_time) : remaining_time(initial_time), reached_endpoint(false), iterations(0) {
        if (!TimeValidator::validate_initial_time(initial_time)) {
            throw invalid_argument("Invalid initial time provided");
        }
    }

    void process_conditions() {
        int condition;
        while (remaining_time > 0 && !reached_endpoint && iterations < numeric_limits<int>::max()) {
            if (!(cin >> condition)) {
                throw runtime_error("Failed to read road condition");
            }
            process_condition(condition);
        }
    }

    bool can_reach_endpoint() const {
        return reached_endpoint && remaining_time >= 0;
    }

    void verify_historical_conditions() const {
        for (int cond : historical_conditions) {
            if (!is_valid_road_condition(cond)) {
                throw logic_error("Historical conditions contain invalid value");
            }
        }
    }
};

