using namespace std;

const int MAX_DIMENSION = 115;
const int MIN_DIMENSION = 1;
const int DIRECTION_COUNT = 4;

struct CoordinateSystemValidator {
    static bool validateDimensions(int rows, int cols) {
        return (rows >= MIN_DIMENSION && rows <= MAX_DIMENSION) && 
               (cols >= MIN_DIMENSION && cols <= MAX_DIMENSION);
    }
};

class TerrainAnalyzer {
private:
    int rows;
    int cols;
    char terrainGrid[MAX_DIMENSION][MAX_DIMENSION];
    bool visitedCells[MAX_DIMENSION][MAX_DIMENSION];
    const int directionVectors[DIRECTION_COUNT][2] = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};
    int grasslandCount;

    void initializeVisitedCells() {
        for (int i = 0; i < MAX_DIMENSION; ++i) {
            for (int j = 0; j < MAX_DIMENSION; ++j) {
                visitedCells[i][j] = false;
            }
        }
    }

    bool isWithinBounds(int x, int y) {
        return (x >= 1 && x <= rows) && (y >= 1 && y <= cols);
    }

    void performDepthFirstSearch(int currentX, int currentY) {
        if (!isWithinBounds(currentX, currentY) {
            return;
        }
        if (visitedCells[currentX][currentY]) {
            return;
        }
        if (terrainGrid[currentX][currentY] != '#') {
            return;
        }

        visitedCells[currentX][currentY] = true;

        for (int directionIndex = 0; directionIndex < DIRECTION_COUNT; ++directionIndex) {
            int newX = currentX + directionVectors[directionIndex][0];
            int newY = currentY + directionVectors[directionIndex][1];
            performDepthFirstSearch(newX, newY);
        }
    }

public:
    TerrainAnalyzer() : rows(0), cols(0), grasslandCount(0) {
        initializeVisitedCells();
    }

    void loadTerrainData(ifstream& inputFile) {
        inputFile >> rows >> cols;
        if (!CoordinateSystemValidator::validateDimensions(rows, cols)) {
            throw out_of_range("Invalid terrain dimensions");
        }

        for (int i = 1; i <= rows; ++i) {
            string rowData;
            inputFile >> rowData;
            if (rowData.length() != static_cast<size_t>(cols)) {
                throw length_error("Row length mismatch");
            }
            for (int j = 1; j <= cols; ++j) {
                terrainGrid[i][j] = rowData[j-1];
                if (terrainGrid[i][j] == '.') {
                    visitedCells[i][j] = true;
                }
            }
        }
    }

    void calculateGrasslands() {
        for (int i = 1; i <= rows; ++i) {
            for (int j = 1; j <= cols; ++j) {
                if (!visitedCells[i][j] && terrainGrid[i][j] == '#') {
                    performDepthFirstSearch(i, j);
                    ++grasslandCount;
                }
            }
        }
    }

    int getGrasslandCount() const {
        return grasslandCount;
    }
};

