class StoneDifferenceCalculator {
private:
    int stoneCount;
    vector<StoneAttributes> stones;
    int minimalDifference;
    vector<bool> selectionTracker;
    vector<int> currentAngerProducts;
    vector<int> currentIrritabilitySums;

    void initializeData() {
        minimalDifference = numeric_limits<int>::max();
        selectionTracker.resize(stoneCount + 2, false);
        currentAngerProducts.resize(stoneCount + 2, 1);
        currentIrritabilitySums.resize(stoneCount + 2, 0);
    }

    void processInput(ifstream& inputFile) {
        inputFile >> stoneCount;
        stones.resize(stoneCount + 1);
        for (int i = 1; i <= stoneCount; ++i) {
            inputFile >> stones[i].anger >> stones[i].irritability;
        }
    }

    void validateInput() {
        if (stoneCount < 1 || stoneCount > 10) {
            throw runtime_error("Invalid stone count");
        }
