    void recursiveStoneSelection(int index, int currentProduct, int currentSum) {
        if (index > stoneCount) {
            if (currentProduct != 1) {
                int currentDifference = abs(currentProduct - currentSum);
                if (currentDifference < minimalDifference) {
                    minimalDifference = currentDifference;
                }
