#include<bits/stdc++.h>
using namespace std;

struct Stone {
    int anger;
    int irritability;
};

class StoneProcessor {
private:
    vector<Stone> stones;
    int min_diff;
    int n;

    void validateInput() {
        if (n < 1 || n > 10) {
            throw runtime_error("Invalid number of stones");
        }
        for (const auto& stone : stones) {
            if (stone.anger < 0 || stone.irritability < 0) {
                throw runtime_error("Negative values not allowed");
            }
        }
    }

    void initializeMinDiff() {
        min_diff = numeric_limits<int>::max();
        for (const auto& stone : stones) {
            int current_diff = abs(stone.anger - stone.irritability);
            if (current_diff < min_diff) {
                min_diff = current_diff;
            }
        }
    }

    void recursiveSearch(int index, int current_anger, int current_irritability, bool at_least_one_selected) {
        if (index == n) {
            if (at_least_one_selected) {
                int current_diff = abs(current_anger - current_irritability);
                if (current_diff < min_diff) {
                    min_diff = current_diff;
                }
            }
            return;
        }

        recursiveSearch(index + 1, current_anger, current_irritability, at_least_one_selected);

        int new_anger = current_anger;
        int new_irritability = current_irritability;
        if (current_anger == 0) {
            new_anger = stones[index].anger;
        } else {
            new_anger *= stones[index].anger;
        }
        new_irritability += stones[index].irritability;

        recursiveSearch(index + 1, new_anger, new_irritability, true);
    }

public:
    StoneProcessor(int num_stones) : n(num_stones) {
        stones.resize(n);
    }

    void readStones() {
        for (int i = 0; i < n; ++i) {
            if (!(cin >> stones[i].anger >> stones[i].irritability)) {
                throw runtime_error("Invalid input format");
            }
        }
        validateInput();
    }

    int findMinDifference() {
        initializeMinDiff();
        recursiveSearch(0, 0, 0, false);
        return min_diff;
    }
};

int main() {
    ifstream input_file("stone.in");
    ofstream output_file("stone.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "Error opening files" << endl;
        return 1;
    }

    cin.rdbuf(input_file.rdbuf());
    cout.rdbuf(output_file.rdbuf());

    try {
        int n;
        cin >> n;

        StoneProcessor processor(n);
        processor.readStones();
        int result = processor.findMinDifference();

        cout << result << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    input_file.close();
    output_file.close();

    return 0;
}
