#include<iostream>
#include<fstream>
#include<vector>
#include<string>
#include<stdexcept>
#include<algorithm>
using namespace std;

const int MAX_DIMENSION = 105;
char terrainGrid[MAX_DIMENSION][MAX_DIMENSION];
bool visitedMatrix[MAX_DIMENSION][MAX_DIMENSION];
int rowCount, colCount;
int totalGrasslands = 0;

struct Coordinate {
    int x;
    int y;
};

vector<Coordinate> directionVectors = {
    {0, 1}, {0, -1}, {1, 0}, {-1, 0}
};

void validateCoordinates(int x, int y) {
    if (x < 0 || x >= rowCount || y < 0 || y >= colCount) {
        throw out_of_range("Coordinates out of grid bounds");
    }
}

void exploreGrassland(int startX, int startY) {
    vector<Coordinate> explorationQueue;
    explorationQueue.push_back({startX, startY});
    visitedMatrix[startX][startY] = true;

    while (!explorationQueue.empty()) {
        Coordinate current = explorationQueue.back();
        explorationQueue.pop_back();

        for (const auto& dir : directionVectors) {
            int newX = current.x + dir.x;
            int newY = current.y + dir.y;

            try {
                validateCoordinates(newX, newY);
                if (!visitedMatrix[newX][newY] && terrainGrid[newX][newY] == '#') {
                    visitedMatrix[newX][newY] = true;
                    explorationQueue.push_back({newX, newY});
                }
            } catch (const out_of_range& e) {
                continue;
            }
        }
    }
}

void initializeVisitedMatrix() {
    for (int i = 0; i < rowCount; ++i) {
        for (int j = 0; j < colCount; ++j) {
            visitedMatrix[i][j] = false;
        }
    }
}

void processInputFile() {
    ifstream inputFile("hiking.in");
    if (!inputFile.is_open()) {
        throw runtime_error("Unable to open input file");
    }

    inputFile >> colCount >> rowCount;
    if (rowCount <= 0 || rowCount > MAX_DIMENSION || colCount <= 0 || colCount > MAX_DIMENSION) {
        throw invalid_argument("Invalid grid dimensions");
    }

    for (int i = 0; i < rowCount; ++i) {
        string rowData;
        inputFile >> rowData;
        if (rowData.length() != colCount) {
            throw invalid_argument("Row length mismatch");
        }
        for (int j = 0; j < colCount; ++j) {
            terrainGrid[i][j] = rowData[j];
        }
    }
    inputFile.close();
}

void writeOutputFile() {
    ofstream outputFile("hiking.out");
    if (!outputFile.is_open()) {
        throw runtime_error("Unable to open output file");
    }
    outputFile << totalGrasslands;
    outputFile.close();
}

int main() {
    try {
        processInputFile();
        initializeVisitedMatrix();

        for (int i = 0; i < rowCount; ++i) {
            for (int j = 0; j < colCount; ++j) {
                if (!visitedMatrix[i][j] && terrainGrid[i][j] == '#') {
                    exploreGrassland(i, j);
                    totalGrasslands++;
                }
            }
