#include <iostream>
#include <algorithm>
#include <vector>
#include <stdexcept>
#include <limits>
#include <type_traits>
#include <sstream>
#include <iterator>

using namespace std;

template<typename T>
struct DigitSumValidator {
    static_assert(is_integral<T>::value, "DigitSumValidator requires integral type");

    static T calculate(T x) {
        if (x < 0) {
            throw invalid_argument("Negative numbers not supported for digit sum");
        }
        if (x >= numeric_limits<T>::max()) {
            throw overflow_error("Number too large for digit sum calculation");
        }

        T ans = 0;
        while (x) {
            if (ans > (numeric_limits<T>::max() - (x % 10))) {
                throw overflow_error("Digit sum overflow detected");
            }
            ans += x % 10;
            x /= 10;
        }
        return ans;
    }
};

class AdvancedIntegerSorter {
private:
    vector<int> numbers;
    size_t max_size;

    void validateInputSize(size_t n) const {
        if (n <= 0 || n >= 101) {
            throw out_of_range("Input size must be between 1 and 100");
        }
    }

    void validateNumber(int num) const {
        if (num <= 0) {
            throw invalid_argument("Numbers must be positive");
        }
        if (num >= 10000) {
            throw out_of_range("Numbers must be less than 10000");
        }
    }

public:
    AdvancedIntegerSorter(size_t n) : max_size(n) {
        validateInputSize(n);
        numbers.reserve(n);
    }

    void addNumber(int num) {
        validateNumber(num);
        if (numbers.size() >= max_size) {
            throw length_error("Exceeded maximum number of elements");
        }
        numbers.push_back(num);
    }

    static bool compareNumbers(int x, int y) {
        auto sum_x = DigitSumValidator<int>::calculate(x);
        auto sum_y = DigitSumValidator<int>::calculate(y);

        if (sum_x != sum_y) {
            return sum_x < sum_y;
        }

        if (x % 2 != y % 2) {
            return (x % 2) < (y % 2);
        }

        if (x % 3 == 0 && y % 3 != 0) {
            return true;
        }

        if (y % 3 == 0 && x % 3 != 0) {
            return false;
        }

        return x < y;
    }

    void sortNumbers() {
        sort(numbers.begin(), numbers.end(), compareNumbers);
    }

    string getSortedString() const {
        ostringstream oss;
        if (!numbers.empty()) {
            copy(numbers.begin(), numbers.end() - 1, ostream_iterator<int>(oss, " "));
            oss << numbers.back();
        }
        return oss.str();
    }
};

int main() {
    try {
        int n;
        cin >> n;

        AdvancedIntegerSorter sorter(n);

        for (int i = 0; i < n; ++i) {
            int num;
            if (!(cin >> num)) {
                throw runtime_error("Invalid input format");
            }
            sorter.addNumber(num);
        }

        sorter.sortNumbers();
        cout << sorter.getSortedString() << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
