using namespace std;

namespace InputValidation {
    bool isStringNumeric(const string& s) {
        if (s.empty()) return false;
        size_t start = 0;
        if (s[0] == '-') {
            if (s.length() == 1) return false;
            start = 1;
        }
        return all_of(s.begin() + start, s.end(), [](char c) {
            return isdigit(c);
        });
    }

    void validateIntegerRange(long long val) {
        if (val < INT_MIN || val > INT_MAX) {
            throw out_of_range("Integer value out of range");
        }
    }
}

class TripleIntegerProcessor {
private:
    vector<int> values;
    string inputLine;

    void parseInput() {
        istringstream iss(inputLine);
        string token;
        int count = 0;

        while (iss >> token && count < 3) {
            if (!InputValidation::isStringNumeric(token)) {
                throw invalid_argument("Invalid integer format");
            }

            errno = 0;
            long long val = strtoll(token.c_str(), nullptr, 10);
            if (errno == ERANGE) {
                throw out_of_range("Integer value out of range during conversion");
            }
            InputValidation::validateIntegerRange(val);

            values.push_back(static_cast<int>(val));
            count++;
        }

        if (values.size() != 3) {
            throw length_error("Incorrect number of integers provided");
        }
    }

public:
    explicit TripleIntegerProcessor(const string& input) : inputLine(input) {
        if (input.empty()) {
            throw invalid_argument("Empty input string");
        }
        parseInput();
    }

    string getFormattedOutput() const {
        if (values.size() != 3) {
            throw logic_error("Invalid internal state");
        }

        ostringstream oss;
        oss << right << setw(8) << values[0] 
            << " " << right << setw(8) << values[1]
            << " " << right << setw(8) << values[2];

        string result = oss.str();
        if (result.length() != 26) {
            throw runtime_error("Unexpected formatting error");
        }

        return result;
    }
};

int main() {
