        string input;
        getline(cin, input);

        TripleIntegerProcessor processor(input);
        string output = processor.getFormattedOutput();

        cout << output << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
