#include <type_traits>
#include <sstream>
#include <iterator>

using namespace std;

template<typename T>
struct DigitSumValidator {
    static_assert(is_integral<T>::value, "DigitSumValidator requires integral type");

    static T calculateSum(T num) {
        if (num < 0) {
            throw invalid_argument("Negative numbers not supported");
        }

        T sum = 0;
        T original = num;
        while (num != 0) {
            T digit = num % 10;
            if (digit < 0 || digit > 9) {
                throw logic_error("Invalid digit encountered");
            }
            sum += digit;
            if (sum > numeric_limits<T>::max() - 9) {
                throw overflow_error("Digit sum overflow");
            }
            num /= 10;
            if (num < 0) {
                throw underflow_error("Negative during digit extraction");
            }
        }
        return sum;
    }
};

struct SortingComparator {
    template<typename T>
    bool operator()(T x, T y) const {
        try {
            T sum_x = DigitSumValidator<T>::calculateSum(x);
            T sum_y = DigitSumValidator<T>::calculateSum(y);

            if (sum_x != sum_y) {
                return sum_x < sum_y;
            } else {
                if (x == y) {
                    throw logic_error("Duplicate values detected");
                }
                return x < y;
            }
        } catch (const exception& e) {
            cerr << "Error during comparison: " << e.what() << endl;
            terminate();
        }
    }
};

template<typename Container>
void validateInputSize(const Container& container, size_t expected) {
    if (container.size() != expected) {
        throw length_error("Input size mismatch");
    }
}

template<typename T>
void validateInputRange(T value, T min, T max) {
    if (value <= min || value >= max) {
        throw out_of_range("Input value out of range");
    }
}

vector<int> parseInputLine(const string& line) {
    istringstream iss(line);
    vector<int> tokens;
    copy(istream_iterator<int>(iss), istream_iterator<int>(), back_inserter(tokens));

    for (int num : tokens) {
        validateInputRange(num, 0, 10000);
    }

    return tokens;
}

int main() {
    try {
        string line;
        getline(cin, line);
        int n = stoi(line);
        validateInputRange(n, 0, 101);

        getline(cin, line);
        vector<int> numbers = parseInputLine(line);
        validateInputSize(numbers, static_cast<size_t>(n));

        sort(numbers.begin(), numbers.end(), SortingComparator());

