        if (num >= 10000) return false;
        return true;
    }

    static bool validateInputSize(int n) {
        if (n <= 0) return false;
        if (n >= 101) return false;
        return true;
    }
};

class DigitSumCalculator {
private:
    static const int MAX_ITERATIONS = 100;
    static const int BASE = 10;

public:
    static int calculateWithValidation(int m) {
        if (!DigitSumValidator::validateInputNumber(m)) {
            throw invalid_argument("Invalid number for digit sum calculation");
        }

        int s = 0;
        int iterations = 0;
        int original = m;

        while (m > 0 && iterations < MAX_ITERATIONS) {
            if (m < 0) {
                throw runtime_error("Negative value encountered during digit sum calculation");
            }
            s += m % BASE;
            m /= BASE;
            iterations++;

            if (iterations >= MAX_ITERATIONS) {
                throw runtime_error("Digit sum calculation exceeded maximum iterations");
            }
        }

        if (m != 0) {
            throw runtime_error("Digit sum calculation did not converge");
        }

        return s;
    }
};

class AdvancedIntegerSorter {
private:
    vector<int> numbers;
    vector<pair<int, int>> numberWithSums;

    void precomputeSums() {
        for (int num : numbers) {
            try {
                int currentSum = DigitSumCalculator::calculateWithValidation(num);
                numberWithSums.emplace_back(num, currentSum);
            } catch (const exception& e) {
                cerr << "Error processing number " << num << ": " << e.what() << endl;
                numberWithSums.emplace_back(num, numeric_limits<int>::max());
            }
        }
    }

    static bool comparePairs(const pair<int, int>& a, const pair<int, int>& b) {
        if (a.second != b.second) {
