    for (int i = s.length() - 1; i >= 0; --i) {
        if (s[i] != '?') {
            int digit = s[i] - '0';
            if (digit < 0 || digit > 9) {
                return -1;
            }
            value += digit * weight;
        }
        weight++;
    }
    return value;
}

int findMissingDigit(const string& s, int target) {
    int missingPos = -1;
    int weight = 1;
    int partialValue = 0;
    for (int i = s.length() - 1; i >= 0; --i) {
        if (s[i] == '?') {
            if (missingPos != -1) {
                return -1;
            }
            missingPos = weight;
        } else {
            int digit = s[i] - '0';
            partialValue += digit * weight;
        }
        weight++;
    }
    if (missingPos == -1) {
        return -1;
    }
    int remaining = target - partialValue;
    if (remaining < 0 || remaining % missingPos != 0) {
        return -1;
    }
    int digit = remaining / missingPos;
    if (digit < 0 || digit > 9) {
        return -1;
    }
