    int s = 0;
    int temp = x;
    int iterations = 0;
    const int max_iterations = 100;
    while (temp != 0 && iterations < max_iterations) {
        s += temp % 10;
        temp /= 10;
        iterations++;
    }
    if (iterations >= max_iterations) {
        throw runtime_error("Potential infinite loop detected");
    }
    return s;
}

bool compareNumbers(const NumberWithSum& a, const NumberWithSum& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    if (a.original != b.original) {
        return a.original < b.original;
    }
    return a.index < b.index;
}

