using namespace std;

namespace FormatUtils {
    class InputValidator {
    public:
        static bool isNumeric(const string& s) {
            if (s.empty()) return false;
            size_t start = 0;
            if (s[0] == '-') start = 1;
            for (size_t i = start; i < s.size(); i++) {
                if (!isdigit(s[i])) {
                    return false;
                }
            }
            try {
                stol(s);
            } catch (...) {
                return false;
            }
            return true;
        }
    };

    class StringFormatter {
    private:
        static const size_t TARGET_WIDTH = 8;
        static string generatePadding(size_t count) {
            string padding;
            for (size_t i = 0; i < count; i++) {
                padding += " ";
            }
            return padding;
        }
    public:
        static string formatField(const string& input) {
            if (input.size() > TARGET_WIDTH) {
                return input.substr(0, TARGET_WIDTH);
            }
            size_t paddingSize = TARGET_WIDTH - input.size();
            if (paddingSize > numeric_limits<size_t>::max() - input.size()) {
                return input;
            }
            string padded = generatePadding(paddingSize);
            padded += input;
            if (padded.size() != TARGET_WIDTH) {
                while (padded.size() < TARGET_WIDTH) {
                    padded = " " + padded;
                }
            }
            return padded;
        }
    };
}

class InputProcessor {
private:
    vector<string> tokens;
    void validateInputCount() const {
        if (tokens.size() != 3) {
            throw runtime_error("Exactly 3 integers required");
        }
    }
    void validateNumericInput() const {
        for (const auto& token : tokens) {
            if (!FormatUtils::InputValidator::isNumeric(token)) {
                throw runtime_error("Non-numeric input detected");
            }
        }
    }
public:
    void readInput() {
        string line;
        getline(cin, line);
        istringstream iss(line);
        string token;
        while (iss >> token) {
            tokens.push_back(token);
        }
        validateInputCount();
        validateNumericInput();
    }
    vector<string> getTokens() const {
        return tokens;
    }
};

class OutputGenerator {
private:
    vector<string> formattedValues;
public:
    void formatValues(const vector<string>& values) {
        for (const auto& value : values) {
            formattedValues.push_back(FormatUtils::StringFormatter::formatField(value));
        }
    }
    void generateOutput() {
        if (formattedValues.size() != 3) return;
        cout << formattedValues[0] << " " << formattedValues[1] << " " << formattedValues[2] << endl;
    }
};

int main() {
    try {
        InputProcessor processor;
        processor.readInput();
        vector<string> tokens = processor.getTokens();
        OutputGenerator generator;
        generator.formatValues(tokens);
        generator.generateOutput();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
