MatrixBounds calculateSafeBounds(int n, int m) {
    MatrixBounds bounds;
    bounds.min_row = max(0, min(n-1, 0));
    bounds.max_row = max(0, min(n-1, n));
    bounds.min_col = max(0, min(m-1, 0));
    bounds.max_col = max(0, min(m-1, m));
    return bounds;
}

int safeGetElement(const vector<vector<int>>& num, int i, int j, int n, int m) {
    if (i < 0 || j < 0 || i >= n || j >= m) {
        return 0;
    }
    return num[i][j];
}

