#include<bits/stdc++.h>
using namespace std;

class QueueManager {
private:
    vector<string> queue;
    unordered_map<char, vector<int>> friendIndices;

public:
    void enqueue(const string& name) {
        if (name.empty()) {
            cerr << "Warning: Attempted to enqueue empty name" << endl;
            return;
        }

        char firstChar = toupper(name[0]);
        if (!isalpha(firstChar)) {
            cerr << "Warning: Invalid name format for " << name << endl;
            queue.push_back(name);
            return;
        }

        bool friendFound = false;
        if (friendIndices.find(firstChar) != friendIndices.end()) {
            for (auto it = friendIndices[firstChar].begin(); it != friendIndices[firstChar].end(); ++it) {
                if (*it < queue.size()) {
                    int insertPos = *it + 1;
                    if (insertPos > queue.size()) {
                        insertPos = queue.size();
                    }
                    queue.insert(queue.begin() + insertPos, name);
                    friendIndices[firstChar].push_back(insertPos);
                    friendFound = true;
                    break;
                } else {
                    friendIndices[firstChar].erase(it);
                    --it;
                }
            }
        }

        if (!friendFound) {
            queue.push_back(name);
            friendIndices[firstChar].push_back(queue.size() - 1);
        }

        for (auto& pair : friendIndices) {
            sort(pair.second.begin(), pair.second.end());
            pair.second.erase(unique(pair.second.begin(), pair.second.end()), pair.second.end());
        }
    }

    string dequeue() {
        if (queue.empty()) {
            return "0";
        }

        string front = queue.front();
        char firstChar = toupper(front[0]);

        if (friendIndices.find(firstChar) != friendIndices.end()) {
            for (auto it = friendIndices[firstChar].begin(); it != friendIndices[firstChar].end(); ) {
                if (*it == 0) {
                    it = friendIndices[firstChar].erase(it);
                } else {
                    --(*it);
                    ++it;
                }
            }
            if (friendIndices[firstChar].empty()) {
                friendIndices.erase(firstChar);
            }
        }

        queue.erase(queue.begin());
        return front;
    }
};

int main() {
