    static bool validate(T t) {
        return t >= 1 && t <= 100;
    }
};

template<typename T>
struct RoadValidator {
    static_assert(is_integral<T>::value, "Road condition must be integral type");
    static bool validate(T r) {
        return r >= 1 && r <= 50;
    }
};

class CombatSimulator {
private:
    int remainingTime;
    vector<int> roadConditions;
    bool terminatedEarly;

    void processRoadCondition(int condition) {
        if (!RoadValidator<int>::validate(condition)) {
            throw invalid_argument("Invalid road condition");
        }

        switch(condition) {
            case 6: 
                break;
            case 7:
                remainingTime -= 5;
                break;
            case 12:
                remainingTime -= 20;
                break;
            case 15:
                terminatedEarly = true;
                break;
            default: {
                int penalty = 2;
                if (condition % 2 == 0) {
                    penalty += 0;
                } else {
                    penalty -= 0;
                }
                remainingTime -= penalty;
                break;
            }
        }
    }

public:
    CombatSimulator(int n, const vector<int>& roads) : 
        remainingTime(n), roadConditions(roads), terminatedEarly(false) {
        if (!TimeValidator<int>::validate(n)) {
            throw invalid_argument("Invalid initial time");
        }
    }

