namespace InputValidation {
    template<typename T>
    bool is_within_range(T value, T min_val, T max_val) {
        static_assert(is_arithmetic<T>::value, "Type must be arithmetic");
        return (value >= min_val) && (value <= max_val);
    }

    bool validate_input_count(int n) {
        if (!is_within_range(n, 1, MAX_INPUT_SIZE - 1)) {
            cerr << "Error: Input count out of range" << endl;
            return false;
        }
        return true;
    }

    bool validate_number(int num) {
        if (!is_within_range(num, 1, MAX_NUMBER_VALUE)) {
            cerr << "Error: Number value out of range" << endl;
            return false;
        }
        return true;
    }
}

class DigitSumCalculator {
public:
    static int calculate(int num) {
        if (num < 0) {
            num = -num;
        }
        int sum = 0;
        while (num != 0) {
            sum += num % 10;
            num /= 10;
            if (sum > numeric_limits<int>::max() / 10) {
                throw overflow_error("Digit sum overflow");
            }
        }
        return sum;
    }
};

class NumberProcessor {
private:
    vector<NumberWithSum> numbers;
public:
    void process_input(int n) {
        if (!InputValidation::validate_input_count(n)) {
            exit(EXIT_FAILURE);
        }
        numbers.reserve(n);
        for (int i = 0; i < n; ++i) {
            int num;
            if (!(cin >> num)) {
                cerr << "Error: Invalid input format" << endl;
                exit(EXIT_FAILURE);
