class TalentShowAnalyzer {
private:
    vector<PerformanceLog> performance_logs;
    int total_audition_time_minutes;
    int current_cumulative_time;
    bool garlic_performed;
    bool garlic_terminated;
    bool time_exceeded;

    void resetState() {
        performance_logs.clear();
        current_cumulative_time = 0;
        garlic_performed = false;
        garlic_terminated = false;
        time_exceeded = false;
    }

    void handleTermination() {
        if (!performance_logs.empty()) {
            PerformanceLog& last_performance = performance_logs.back();
            if (last_performance.name == "kaomianjin") {
                garlic_terminated = true;
            }
            current_cumulative_time -= last_performance.duration;
            performance_logs.pop_back();
        }
    }

    void processPerformance(const string& name, int duration) {
        if (name == "kaomianjin") {
            garlic_performed = true;
        }
        current_cumulative_time += duration;
        PerformanceLog log_entry;
        log_entry.name = name;
        log_entry.duration = duration;
        log_entry.cumulative_time = current_cumulative_time;
        log_entry.was_terminated = false;
        performance_logs.push_back(log_entry);
    }

    void checkTimeExceeded() {
        if (current_cumulative_time > total_audition_time_minutes) {
            time_exceeded = true;
        }
    }

public:
    TalentShowAnalyzer(int x) : total_audition_time_minutes(x * 60) {
        resetState();
    }

    void processInput() {
        string input_name;
        while (cin >> input_name) {
            try {
                if (input_name == "tingtingting") {
                    handleTermination();
                } else {
                    int input_duration;
                    if (!(cin >> input_duration)) {
                        cin.clear();
                        cin.ignore(numeric_limits<streamsize>::max(), '\n');
                        throw runtime_error("Invalid duration input");
                    }
                    processPerformance(input_name, input_duration);
                    checkTimeExceeded();
                    if (time_exceeded) break;
                }
            } catch (const exception& e) {
                continue;
            }
        }
    }

    string getResult() {
        if (garlic_terminated) {
            return "Hahaha.";
        } else if (garlic_performed) {
            bool actually_performed = false;
            for (const auto& log : performance_logs) {
                if (log.name == "kaomianjin" && !log.was_terminated && log.cumulative_time <= total_audition_time_minutes) {
                    actually_performed = true;
                    break;
                }
            }
            if (actually_performed) {
                return "Congratulations!";
            } else {
                return "Unfortunately.";
            }
        } else {
            return "Unfortunately.";
        }
    }
};

int main() {
