class CharacterProcessor {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;

    static char processAlphabet(char c, int shift, bool isUpper) {
        if (!isalpha(c)) throw CharacterProcessingException("Non-alphabet character");
        char base = isUpper ? 'A' : 'a';
        int normalized = (c - base + shift) % ALPHABET_SIZE;
        if (normalized < 0) normalized += ALPHABET_SIZE;
        return static_cast<char>(base + normalized);
    }

    static char processDigit(char c, int shift) {
        if (!isdigit(c)) throw CharacterProcessingException("Non-digit character");
        int normalized = (c - '0' + shift) % DIGIT_SIZE;
        if (normalized < 0) normalized += DIGIT_SIZE;
        return static_cast<char>('0' + normalized);
    }

