char performCyclicShift(char c, int shiftAmount, int charType) {
    const int alphabetSize = 26;
    const int digitSize = 10;
    char baseChar;
    int moduloBase;

    switch(charType) {
        case 1:
            baseChar = 'A';
            moduloBase = alphabetSize;
            break;
        case 2:
            baseChar = 'a';
            moduloBase = alphabetSize;
            break;
        case 3:
