string processEncodedString(const string& s) {
    if (s.empty()) return "";
    for (char c : s) {
        if (!isValidCharacter(c)) {
            return "INVALID_INPUT";
        }
    }
    if (!isBalancedParentheses(s)) {
        return "UNBALANCED_PARENTHESES";
    }
    stack<string> strStack;
    stack<int> numStack;
    string currentStr;
    int currentNum = 0;
    for (int i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (isdigit(c)) {
            currentNum = currentNum * 10 + (c - '0');
        } else if (c == '(') {
            if (currentNum == 0) currentNum = 1;
            numStack.push(currentNum);
            strStack.push(currentStr);
            currentNum = 0;
            currentStr.clear();
        } else if (c == ')') {
            if (numStack.empty() || strStack.empty()) {
                return "STACK_UNDERFLOW";
            }
            int k = numStack.top();
            numStack.pop();
            string temp = strStack.top();
            strStack.pop();
            string repeated;
            for (int j = 0; j < k; ++j) {
                repeated += currentStr;
            }
            currentStr = temp + repeated;
        } else {
            currentStr += c;
        }
    }
    if (!numStack.empty() || !strStack.empty()) {
        return "STACK_NOT_EMPTY";
    }
    return currentStr;
}

