}

void validateInput(int n, int m) {
    if (n < 1 || n > 1000 || m < 1 || m > 1000) {
        throw runtime_error("Invalid input range");
    }
}

void processChildren(Child children[], int n) {
    for (int i = 0; i < n; i++) {
        if (children[i].height <= 0 || children[i].height > 100000) {
            throw runtime_error("Invalid child height");
        }
        children[i].index = i;
        children[i].balloons_taken = 0;
    }
