}

void processBalloons(Balloon balloons[], int m) {
    for (int i = 0; i < m; i++) {
        if (balloons[i].height <= 0 || balloons[i].height > 100000) {
            throw runtime_error("Invalid balloon height");
        }
        balloons[i].taken = false;
    }
    sort(balloons, balloons + m, compareBalloons);
}

void distributeBalloons(Child children[], Balloon balloons[], int n, int m) {
    for (int i = 0; i < n; i++) {
