#include<utility>
#include<memory>

using namespace std;

struct WordMetadata {
    string content;
    bool processed;
    size_t original_position;
};

class StringProcessor {
private:
    vector<WordMetadata> words;
    string original_input;

    void initializeWordMetadata() {
        for (size_t i = 0; i < words.size(); ++i) {
            words[i].processed = false;
            words[i].original_position = i;
        }
    }

    void formatCaseAndPunctuation() {
        for (auto& ch : original_input) {
            if (isupper(ch) && ch != 'I') {
                ch = tolower(ch);
            }
            if (ch == '?') {
                ch = '!';
            }
        }
    }

    void tokenizeInput() {
        istringstream iss(original_input);
        string token;
        while (iss >> token) {
            WordMetadata wm;
            wm.content = token;
            wm.processed = false;
            wm.original_position = words.size();
            words.push_back(wm);
        }
    }

    void applyRule3() {
        for (size_t i = 0; i < words.size(); ) {
            if (i + 1 < words.size() && !words[i].processed && !words[i+1].processed) {
                const string& current = words[i].content;
                const string& next = words[i+1].content;
                if ((current == "can" || current == "could") && next == "you") {
                    words[i].content = "I";
                    words[i+1].content = current;
                    words[i].processed = true;
                    words[i+1].processed = true;
                    i += 2;
                    continue;
                }
            }
            ++i;
        }
    }

    void applyRule4() {
        for (auto& word : words) {
            if (!word.processed && (word.content == "I" || word.content == "me")) {
                word.content = "you";
                word.processed = true;
            }
        }
    }

    string reconstructOutput() {
        ostringstream oss;
        for (size_t i = 0; i < words.size(); ++i) {
            if (i != 0) oss << " ";
            oss << words[i].content;
        }
        return oss.str();
    }

public:
    explicit StringProcessor(const string& input) : original_input(input) {}

    string process() {
        try {
            formatCaseAndPunctuation();
            tokenizeInput();
            initializeWordMetadata();
            applyRule3();
            applyRule4();
            return reconstructOutput();
        } catch (const exception& e) {
            cerr << "Processing error: " << e.what() << endl;
            return original_input;
        }
    }
};

int main() {
    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    vector<string> inputs;
    for (int i = 0; i < n; ++i) {
        string input;
        getline(cin, input);
        inputs.push_back(input);
    }

    vector<unique_ptr<StringProcessor>> processors;
    for (const auto& input : inputs) {
        processors.push_back(make_unique<StringProcessor>(input));
    }

    for (const auto& processor : processors) {
        string output = processor->process();
        cout << output << endl;
    }

    return 0;
}
