    {15, 0, true},
    {0, -2, false} // Default case
};

RoadCondition analyzeCondition(int code) {
    try {
        if (code < 0 || code > 50) {
            throw out_of_range("Invalid road condition code");
        }

        auto it = find_if(conditionDatabase.begin(), conditionDatabase.end(),
            [code](const RoadCondition& rc) { return rc.code == code; });

        if (it != conditionDatabase.end()) {
            return *it;
        } else {
            return conditionDatabase.back();
        }
    } catch (const exception& e) {
        cerr << "Error analyzing condition: " << e.what() << endl;
        return conditionDatabase.back();
    }
}

bool validateTimeImpact(int remainingTime, int impact) {
    if (impact > 0) {
        return false;
    }
    if (remainingTime + impact < numeric_limits<int>::min()) {
        return false;
    }
    return true;
}

void processTimeImpact(int& remainingTime, int impact) {
