namespace QueueUtils {
    template<typename T>
    class AdvancedQueueValidator {
    public:
        static bool validateElement(const T& element) {
            return !element.empty();
        }
    };

    template<typename T>
    class QueueOperationLogger {
    public:
        void logOperation(const string& operation, const T& element) {
            cerr << "Operation: " << operation << " Element: " << element << endl;
        }
    };
}

class OverEngineeredQueue {
private:
    vector<string> data;
    size_t front;
    size_t rear;
    QueueUtils::QueueOperationLogger<string> logger;

    bool validatePosition(size_t pos) const {
        return pos < data.size() && pos >= front;
    }

    void ensureCapacity() {
        if (rear >= data.size()) {
            data.resize(data.size() * 2 + 1);
        }
    }

    void validateState() const {
        if (front > rear) {
            throw runtime_error("Queue front exceeds rear");
        }
    }

public:
    OverEngineeredQueue() : front(0), rear(0) {
        data.reserve(105);
    }

    void enqueueWithFriendship(const string& name) {
        if (!QueueUtils::AdvancedQueueValidator<string>::validateElement(name)) {
            logger.logOperation("Invalid enqueue attempt", name);
            return;
        }

        bool inserted = false;
        for (size_t i = front; i < rear; ++i) {
            if (validatePosition(i) && 
                !data[i].empty() && 
                toupper(name[0]) == toupper(data[i][0])) {

                data.insert(data.begin() + i + 1, name);
                rear++;
                inserted = true;
                logger.logOperation("Inserted behind friend", name);
                break;
            }
        }

        if (!inserted) {
            ensureCapacity();
            if (rear < data.size()) {
                data[rear++] = name;
                logger.logOperation("Added to end", name);
            } else {
                throw runtime_error("Queue capacity exceeded");
            }
        }
        validateState();
    }

    string dequeue() {
        validateState();
        if (front >= rear) {
            logger.logOperation("Dequeue empty", "");
            return "0";
        }

        string result = data[front];
        if (!QueueUtils::AdvancedQueueValidator<string>::validateElement(result)) {
            logger.logOperation("Invalid element dequeued", result);
            return "0";
        }

        front++;
        logger.logOperation("Dequeued", result);
        return result;
    }

    bool isEmpty() const {
        return front >= rear;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    OverEngineeredQueue queue;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid operation count" << endl;
        return EXIT_FAILURE;
    }

    while (n--) {
        int k;
        cin >> k;

        if (cin.fail()) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            continue;
        }

