    void initializeWordTracking() {
        words.clear();
        istringstream iss(original_string);
        string temp_word;
        size_t pos_counter = 0;
        while (iss >> temp_word) {
            WordInfo wi;
            wi.content = temp_word;
            wi.processed = false;
            wi.original_position = pos_counter++;
            words.push_back(wi);
        }
    }

    void performCaseConversion() {
