            if (isupper(c) {
                if (c != 'I') {
                    c = tolower(c);
                }
            }
        }
    }

    void performPunctuationReplacement() {
        replace(original_string.begin(), original_string.end(), '?', '!');
    }

    void applyRuleFour() {
        for (auto& word : words) {
            if (!word.processed) {
                if (word.content == "I" || word.content == "me") {
                    word.content = "you";
                    word.processed = true;
                }
            }
        }
    }

    void applyRuleThree() {
        for (size_t i = 0; i < words.size(); ++i) {
            if (i + 1 < words.size()) {
                if (!words[i].processed && !words[i+1].processed) {
                    if ((words[i].content == "can" || words[i].content == "could") && words[i+1].content == "you") {
                        words[i].content = "I " + words[i].content;
                        words[i+1].processed = true;
                        words[i].processed = true;
                    }
                }
            }
        }
    }

    string reconstructOutput() {
        vector<pair<size_t, string>> ordered_words;
        for (const auto& word : words) {
            if (!word.processed) {
                ordered_words.emplace_back(word.original_position, word.content);
            } else {
                if (word.content.find(' ') != string::npos) {
                    ordered_words.emplace_back(word.original_position, word.content.substr(0, word.content.find(' ')));
                    ordered_words.emplace_back(word.original_position, word.content.substr(word.content.find(' ') + 1));
                } else {
                    ordered_words.emplace_back(word.original_position, word.content);
                }
