        }
        sort(ordered_words.begin(), ordered_words.end());
        ostringstream oss;
        for (size_t i = 0; i < ordered_words.size(); ++i) {
            if (i != 0) oss << " ";
            oss << ordered_words[i].second;
        }
        return oss.str();
    }

public:
    explicit StringProcessor(const string& input) : original_string(input) {}

    string process() {
        performCaseConversion();
        performPunctuationReplacement();
        initializeWordTracking();
        applyRuleFour();
        applyRuleThree();
        return reconstructOutput();
    }
};

