        } else {
            current_token += ch;
        }
    }
    if (!current_token.empty()) {
        tokens.push_back(current_token);
    }
    return tokens;
}

string reconstruct_from_tokens(const vector<string>& tokens) {
    string result;
    for (const auto& token : tokens) {
        result += token;
    }
    return result;
}

string perform_case_conversion(string str) {
    for (char& c : str) {
        if (isupper(c) && c != 'I') {
            c = tolower(c);
        }
    }
    return str;
}

string perform_punctuation_replacement(string str) {
    replace(str.begin(), str.end(), '?', '!');
    return str;
}

vector<WordMetadata> create_word_metadata_vector(const vector<string>& words) {
    vector<WordMetadata> metadata;
    for (size_t i = 0; i < words.size(); ++i) {
        metadata.push_back({words[i], false, i});
    }
    return metadata;
}

vector<string> apply_rule_three_and_four(vector<WordMetadata>& word_metadata) {
    vector<string> result;
    for (size_t i = 0; i < word_metadata.size(); ++i) {
        if (word_metadata[i].processed) continue;

        if (i + 1 < word_metadata.size() && 
            (word_metadata[i].content == "can" || word_metadata[i].content == "could") && 
            word_metadata[i+1].content == "you" && !word_metadata[i+1].processed) {
            result.push_back("I");
            result.push_back(word_metadata[i].content);
            word_metadata[i].processed = true;
            word_metadata[i+1].processed = true;
            i++;
        } else if ((word_metadata[i].content == "I" || word_metadata[i].content == "me") && !word_metadata[i].processed) {
            result.push_back("you");
            word_metadata[i].processed = true;
        } else {
            result.push_back(word_metadata[i].content);
        }
    }
    return result;
}

string process_ai_response(const string& input) {
