int calculateGarlicValue(const string& s, bool isReceipt) {
    int value = 0;
    int weight = 1;
    if (isReceipt) {
        for (int i = s.length() - 1; i >= 0; --i) {
            if (s[i] != '?') {
                value += weight * (s[i] - '0');
