int calculateGarlicValue(const string& numStr, bool isReceipt) {
    int garlicValue = 0;
    int positionWeight = 1;
    if (isReceipt) {
        for (auto it = numStr.rbegin(); it != numStr.rend(); ++it) {
            if (*it != '?') {
                garlicValue += positionWeight * (*it - '0');
            }
            positionWeight++;
        }
    } else {
        for (auto it = numStr.begin(); it != numStr.end(); ++it) {
            garlicValue += positionWeight * (*it - '0');
            positionWeight++;
        }
    }
    return garlicValue;
}

int findMissingDigit(const string& receipt, int balanceGarlic) {
    int questionMarkPos = -1;
    int questionMarkWeight = 0;
    int currentWeight = 1;
    for (int i = receipt.length() - 1; i >= 0; --i) {
        if (receipt[i] == '?') {
            questionMarkPos = i;
            questionMarkWeight = currentWeight;
            break;
        }
        currentWeight++;
    }

    if (questionMarkPos == -1) {
        throw runtime_error("No question mark found");
    }

    int partialReceiptValue = calculateGarlicValue(receipt, true);
    int difference = balanceGarlic - partialReceiptValue;

    if (difference < 0 || difference % questionMarkWeight != 0) {
        return -1;
    }

    int missingDigit = difference / questionMarkWeight;
    if (missingDigit < 0 || missingDigit > 9) {
        return -1;
    }

    return missingDigit;
}

