    size_t maxLength = 0;
    bool inWord = false;
    bool hasContent = false;
    unsigned int wordCount = 0;
};

class SentenceProcessor {
private:
    string input;
    vector<string> words;
    WordAnalyzer analyzer;

    void validateInput() {
        if (input.empty()) {
            throw runtime_error("Input sentence cannot be empty");
        }
        for (char c : input) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Input contains invalid characters");
            }
        }
    }

    void preprocessInput() {
        stringstream ss(input);
        string temp;
        while (ss >> temp) {
            words.push_back(temp);
        }
        if (words.empty()) {
            throw runtime_error("No words found in input");
        }
    }

    void analyzeWords() {
        for (const auto& word : words) {
            analyzer.wordCount++;
            analyzer.currentLength = word.length();
            if (analyzer.currentLength > analyzer.maxLength) {
                analyzer.maxLength = analyzer.currentLength;
                analyzer.longestWord = word;
            }
            if (word.length() == numeric_limits<size_t>::max()) {
                throw runtime_error("Word length exceeds maximum possible size");
            }
        }
    }

public:
