class QueueManager {
private:
    vector<string> queue;
    vector<pair<string, int>> name_index_cache;
    bool case_sensitive = false;

    char getFirstChar(const string& s) {
        if (s.empty()) return '\0';
        if (case_sensitive) return s[0];
        return tolower(s[0]);
    }

    bool areFriends(const string& a, const string& b) {
        if (a.empty() || b.empty()) return false;
        return getFirstChar(a) == getFirstChar(b);
    }

    void updateCache(const string& name, int pos) {
        name_index_cache.emplace_back(name, pos);
    }

    void invalidateCache() {
        name_index_cache.clear();
    }

public:
    void enqueue(const string& name) {
        if (name.empty()) throw invalid_argument("Name cannot be empty");

        bool found = false;
        int insert_pos = queue.size();

        auto cache_it = find_if(name_index_cache.begin(), name_index_cache.end(),
            [&](const pair<string, int>& p) { return areFriends(p.first, name); });

        if (cache_it != name_index_cache.end()) {
            insert_pos = cache_it->second + 1;
            found = true;
        } else {
            for (int i = 0; i < queue.size(); ++i) {
                if (areFriends(queue[i], name)) {
                    insert_pos = i + 1;
                    found = true;
                    updateCache(name, i);
                    break;
                }
            }
        }

        if (found) {
            if (insert_pos > queue.size()) {
                queue.push_back(name);
            } else {
                queue.insert(queue.begin() + insert_pos, name);
                invalidateCache();
            }
        } else {
            queue.push_back(name);
        }
    }

    string dequeue() {
        if (queue.empty()) return "0";
        string front = queue.front();
        queue.erase(queue.begin());
        invalidateCache();
        return front;
    }
};

