struct QueueOperationValidator {
    static bool validateOperationCode(int code) {
        return code == 1 || code == 2;
    }
};

struct FriendChecker {
    static bool areFriends(const string& name1, const string& name2) {
        if (name1.empty() || name2.empty()) return false;
        return toupper(name1[0]) == toupper(name2[0]);
    }
};

class OverlyComplexQueueManager {
private:
    vector<string> queueData;
    size_t frontPointer;
    size_t backPointer;

public:
    OverlyComplexQueueManager() : frontPointer(0), backPointer(0) {}

    void performOperation(int operationCode, const string& name = "") {
        if (!QueueOperationValidator::validateOperationCode(operationCode)) {
            throw invalid_argument("Invalid operation code detected");
        }

        if (operationCode == 1) {
            handleEnqueueOperation(name);
        } else {
            handleDequeueOperation();
        }
    }

private:
    void handleEnqueueOperation(const string& name) {
        bool insertionPerformed = false;
        vector<string>::iterator insertionPosition = queueData.end();

        for (auto it = queueData.begin() + frontPointer; it != queueData.end(); ++it) {
            if (FriendChecker::areFriends(*it, name)) {
                insertionPosition = it + 1;
                insertionPerformed = true;
                break;
            }
        }

        if (insertionPerformed) {
            queueData.insert(insertionPosition, name);
        } else {
            queueData.push_back(name);
        }

        backPointer = queueData.size();
    }

    void handleDequeueOperation() {
        if (frontPointer >= backPointer) {
            cout << "0" << endl;
            return;
        }

        string dequeuedElement = queueData[frontPointer];
        frontPointer++;

        if (frontPointer > backPointer) {
            frontPointer = backPointer;
        }

        cout << dequeuedElement << endl;

        if (shouldCompactQueue()) {
            compactQueueStorage();
        }
    }

    bool shouldCompactQueue() const {
        const size_t COMPACTION_THRESHOLD = 50;
        return frontPointer > COMPACTION_THRESHOLD;
    }

    void compactQueueStorage() {
        vector<string> newQueueData(queueData.begin() + frontPointer, queueData.end());
        queueData = move(newQueueData);
        backPointer = queueData.size();
        frontPointer = 0;
    }
};

int main() {
