#include <iostream>
#include <algorithm>
#include <vector>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

struct NumberSet {
    int first;
    int second;
    int original_index;
    bool was_swapped;
    int computed_difference;
    int minimum_value;
};

void validateInputRange(int value, int min_val, int max_val, const string& var_name) {
    if (value < min_val || value > max_val) {
        throw out_of_range(var_name + " out of valid range");
    }
}

void preprocessNumberSet(NumberSet& ns, int index) {
    ns.original_index = index;
    ns.was_swapped = false;
    if (ns.first > ns.second) {
        swap(ns.first, ns.second);
        ns.was_swapped = true;
    }
    ns.computed_difference = ns.second - ns.first;
    ns.minimum_value = min(ns.first, ns.second);
}

bool compareNumberSets(const NumberSet& a, const NumberSet& b) {
    if (a.computed_difference != b.computed_difference) {
        return a.computed_difference > b.computed_difference;
    }
    if (a.minimum_value != b.minimum_value) {
        return a.minimum_value < b.minimum_value;
    }
    return a.original_index < b.original_index;
}

void handleOutput(const NumberSet& result) {
    if (result.was_swapped) {
        cout << result.second << " " << result.first << endl;
    } else {
        cout << result.first << " " << result.second << endl;
    }
}

