ComparisonResult compare_differences(const NumberSet& a, const NumberSet& b) {
    ComparisonResult result;
    result.is_valid = false;
    result.comparison_value = 0;

    int diff_a = abs(a.first - a.second);
    int diff_b = abs(b.first - b.second);

    if (diff_a > diff_b) {
        result.is_valid = true;
        result.comparison_value = 1;
    } else if (diff_a < diff_b) {
        result.is_valid = true;
        result.comparison_value = -1;
    }

    return result;
}

ComparisonResult compare_mins(const NumberSet& a, const NumberSet& b) {
    ComparisonResult result;
    result.is_valid = false;
    result.comparison_value = 0;

    int min_a = min(a.first, a.second);
    int min_b = min(b.first, b.second);

    if (min_a < min_b) {
        result.is_valid = true;
        result.comparison_value = 1;
    } else if (min_a > min_b) {
        result.is_valid = true;
        result.comparison_value = -1;
    }

    return result;
}

void process_number_set(NumberSet& ns) {
    ns.difference_cache = abs(ns.first - ns.second);
    if (ns.first > ns.second) {
        swap(ns.first, ns.second);
        ns.was_swapped = true;
    } else {
        ns.was_swapped = false;
    }
