#include <limits>
#include <stdexcept>
#include <utility>
#include <memory>
using namespace std;

struct WordTracker {
    string word;
    size_t length;
    size_t position;
    bool initialized;
    WordTracker() : word(""), length(0), position(numeric_limits<size_t>::max()), initialized(false) {}
};

class SentenceAnalyzer {
private:
    string sentence;
    vector<string> words;
    vector<size_t> word_lengths;
    vector<pair<size_t, size_t>> word_positions;
    unique_ptr<WordTracker> tracker;

    void validateInput() {
        if (sentence.empty()) {
            throw runtime_error("Empty input sentence detected");
        }
        for (char c : sentence) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Invalid character in input");
            }
        }
    }

    void tokenizeSentence() {
        istringstream iss(sentence);
        string token;
        size_t pos = 0;
        while (iss >> token) {
            words.push_back(token);
            word_lengths.push_back(token.length());
            word_positions.emplace_back(pos, token.length());
            pos += token.length() + 1;
        }
        if (words.empty()) {
            throw runtime_error("No words found in sentence");
        }
    }

    void initializeTracker() {
        tracker = make_unique<WordTracker>();
        tracker->word = words[0];
        tracker->length = word_lengths[0];
        tracker->position = 0;
        tracker->initialized = true;
    }

    void findLongestWord() {
        if (!tracker->initialized) {
            throw runtime_error("Tracker not initialized");
        }
        for (size_t i = 1; i < words.size(); ++i) {
            if (word_lengths[i] > tracker->length) {
                tracker->word = words[i];
                tracker->length = word_lengths[i];
                tracker->position = i;
            } else if (word_lengths[i] == tracker->length) {
                if (word_positions[i].first < word_positions[tracker->position].first) {
                    tracker->word = words[i];
                    tracker->length = word_lengths[i];
                    tracker->position = i;
                }
            }
        }
    }

public:
    explicit SentenceAnalyzer(const string& s) : sentence(s) {
        validateInput();
        tokenizeSentence();
        initializeTracker();
        findLongestWord();
    }

    string getLongestWord() const {
        if (!tracker || !tracker->initialized) {
            throw runtime_error("No valid longest word found");
        }
        return tracker->word;
    }
};

int main() {
    try {
        string input;
        getline(cin, input);
        SentenceAnalyzer analyzer(input);
        string result = analyzer.getLongestWord();
        if (result.empty()) {
            cerr << "Error: Empty result detected" << endl;
            return EXIT_FAILURE;
        }
        cout << result << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
