            bool meets_criteria = true;
            int current_degree = nodes[current_node].degree;

            for(int child_index = 0; child_index < nodes[current_node].children.size(); child_index++) {
                int child_node = nodes[current_node].children[child_index];
                if(child_node < 0 || child_node >= n) {
                    continue;
                }
