            if(meets_criteria) {
                for(int parent_index = 0; parent_index < nodes[current_node].parents.size(); parent_index++) {
                    int parent_node = nodes[current_node].parents[parent_index];
                    if(parent_node < 0 || parent_node >= n) {
                        continue;
                    }
                    if(current_degree < nodes[parent_node].degree) {
                        meets_criteria = false;
                        break;
                    }
                }
            }

            if(meets_criteria) {
                for(int neighbor = 0; neighbor < n; neighbor++) {
                    if(adjacency_matrix[current_node][neighbor] && current_degree < nodes[neighbor].degree) {
                        meets_criteria = false;
