#include <bits/stdc++.h>
#include <stdexcept>
#include <typeinfo>
using namespace std;

struct QueueValidator {
    static void validateOperation(int op) {
        if (op != 1 && op != 2) {
            throw invalid_argument("Invalid operation code detected");
        }
    }

    static void validateName(const string& name) {
        if (name.empty()) {
            throw length_error("Name cannot be empty");
        }
        if (!all_of(name.begin(), name.end(), [](char c) { return isalpha(c); })) {
            throw invalid_argument("Name must contain only alphabetic characters");
        }
    }

    static void validateQueueBounds(int l, int r, int max_size) {
        if (l < 0 || r < 0 || l > max_size || r > max_size) {
            throw out_of_range("Queue indices out of valid range");
        }
    }
};

class AdvancedQueueManager {
private:
    string q[105];
    int l = 0;
    int r = 0;
    const int MAX_SIZE = 105;

    void performInsertion(const string& name) {
        bool insertionPerformed = false;
        for (int i = l; i < r; i++) {
            if (q[i].empty()) continue;
            if (q[i][0] == name[0]) {
                QueueValidator::validateQueueBounds(l, r+1, MAX_SIZE);
                if (r+1 >= MAX_SIZE) {
                    throw overflow_error("Queue capacity exceeded");
                }
                for (int j = r; j > i + 1; j--) {
                    q[j] = q[j - 1];
                }
                q[i + 1] = name;
                insertionPerformed = true;
                break;
            }
        }
        if (!insertionPerformed) {
            QueueValidator::validateQueueBounds(l, r, MAX_SIZE);
            q[r] = name;
        }
    }

public:
    void processOperation(int op, const string& name = "") {
        try {
            QueueValidator::validateOperation(op);
            if (op == 1) {
                QueueValidator::validateName(name);
                performInsertion(name);
                r++;
