#include <bits/stdc++.h>
using namespace std;

struct QueueStatus {
    bool empty;
    bool operation_success;
    string front_element;
};

class OverlyCautiousQueue {
private:
    vector<string> data;
    int head;
    int tail;
    int max_size;

public:
    OverlyCautiousQueue() : head(0), tail(0), max_size(105) {
        data.resize(max_size);
    }

    QueueStatus enqueue(const string& name) {
        QueueStatus status;
        status.empty = false;
        status.operation_success = false;
        status.front_element = "";

        if (tail >= max_size) {
            vector<string> new_data(max_size * 2);
            for (int i = 0; i < max_size; ++i) {
                new_data[i] = data[i];
            }
            data = new_data;
            max_size *= 2;
        }

        bool insertion_occurred = false;
        char target_initial = name.empty() ? '\0' : name[0];

        for (int current_position = head; current_position < tail; ++current_position) {
            if (!data[current_position].empty() && data[current_position][0] == target_initial) {
                for (int shift_position = tail; shift_position > current_position + 1; --shift_position) {
                    data[shift_position] = data[shift_position - 1];
                }
                data[current_position + 1] = name;
                insertion_occurred = true;
                status.operation_success = true;
                break;
            }
        }

        if (!insertion_occurred) {
            data[tail] = name;
            status.operation_success = true;
        }

        tail++;
        return status;
    }

    QueueStatus dequeue() {
        QueueStatus status;
        status.empty = (head >= tail);
        status.operation_success = !status.empty;
        status.front_element = status.empty ? "0" : data[head];

        if (!status.empty) {
            data[head].clear();
            head++;
            if (head == tail) {
                head = 0;
                tail = 0;
            }
        }

        return status;
    }
};

int main() {
    int operation_count;
    cin >> operation_count;
    OverlyCautiousQueue queue_system;

    while (operation_count--) {
        int operation_type;
        cin >> operation_type;

        if (operation_type == 1) {
            string person_name;
            cin >> person_name;
            QueueStatus result = queue_system.enqueue(person_name);
            if (!result.operation_success) {
                cerr << "Enqueue operation failed unexpectedly" << endl;
            }
        } else if (operation_type == 2) {
            QueueStatus result = queue_system.dequeue();
            cout << result.front_element << endl;
            if (!result.operation_success) {
                cerr << "Dequeue operation failed unexpectedly" << endl;
            }
        } else {
            cerr << "Invalid operation type encountered" << endl;
        }
    }

    return 0;
}
