        try {
            long long val = std::stoll(input);
            return val >= std::numeric_limits<int>::min() && val <= std::numeric_limits<int>::max();
        } catch (...) {
            return false;
        }
    }

    static bool validateInputCount(const std::vector<std::string>& tokens) {
        return tokens.size() == 3;
    }
};

class InputProcessor {
private:
    std::vector<int> processedValues;

public:
    void processInput(const std::string& rawInput) {
        std::istringstream iss(rawInput);
        std::vector<std::string> tokens;
        std::string token;

        while (iss >> token) {
            if (!InputValidator::validateIntegerRange(token)) {
                throw std::runtime_error("Invalid integer range detected");
            }
            tokens.push_back(token);
        }

        if (!InputValidator::validateInputCount(tokens)) {
            throw std::runtime_error("Incorrect number of input values");
        }

        for (const auto& t : tokens) {
            processedValues.push_back(std::stoi(t));
        }
    }

    const std::vector<int>& getProcessedValues() const {
        return processedValues;
    }
};

