        }

        static bool validateInput(const string& str) {
            if (str.empty()) return false;
            size_t pos = 0;
            if (str[0] == '-' || str[0] == '+') pos = 1;
            if (pos == str.size()) return false;
            return all_of(str.begin() + pos, str.end(), [](char c) {
                return isdigit(c);
            });
        }
    };

    class InputProcessor {
    private:
        static vector<string> tokenize(const string& input) {
            vector<string> tokens;
            string token;
            istringstream iss(input);
            while (iss >> token) {
                tokens.push_back(token);
            }
            return tokens;
        }

    public:
        static void processInput(int& a, int& b, int& c) {
            string inputLine;
            getline(cin, inputLine);

            vector<string> tokens = tokenize(inputLine);
            if (tokens.size() != 3) {
                throw runtime_error("Exactly three integers required");
            }

