    vector<int> balls;
    vector<int> queries;
    mutex mtx;
    atomic<bool> initialized{false};

    void initializeData() {
        unique_lock<mutex> lock(mtx);
        if (initialized) return;

        int m, n;
        if (!(cin >> m >> n)) {
            throw runtime_error("Invalid input format for m and n");
        }

        if (!BallValidator::validateBallCount(m) || !BallValidator::validateBallCount(n)) {
            throw out_of_range("Invalid m or n value");
        }

        balls.resize(m);
        for (int i = 0; i < m; ++i) {
            if (!(cin >> balls[i])) {
