            initializeData();

            ofstream out("ball.out");
            if (!out.is_open()) {
                throw runtime_error("Failed to open output file");
            }

            for (int query : queries) {
                bool found = binarySearch(query);
                out << (found ? "YES" : "NO") << "\n";
            }
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            exit(EXIT_FAILURE);
        }
    }
