    working_board[row][col] = state ? color + 2 : 1;
    column_usage[col][color] = state ? 1 : 0;
    positive_diagonal_usage[row + col][color] = state ? 1 : 0;
    negative_diagonal_usage[row - col + n][color] = state ? 1 : 0;
}

void recursive_solver(int current_row) {
    if (current_row >= n) {
        solution_count++;
        return;
    }

    for (int first_col = 0; first_col < n; first_col++) {
        if (validate_position(current_row, first_col, 0)) {
            mark_position(current_row, first_col, 0, true);

            for (int second_col = 0; second_col < n; second_col++) {
                if (second_col == first_col) continue;
                if (validate_position(current_row, second_col, 1)) {
                    mark_position(current_row, second_col, 1, true);

                    recursive_solver(current_row + 1);

                    mark_position(current_row, second_col, 1, false);
                }
            }

            mark_position(current_row, first_col, 0, false);
        }
    }
}

bool read_input_file() {
    ifstream input_file("queen.in");
