const int MAX_NODES = 1005;

struct NodeMetadata {
    int parent;
    int degree;
    bool is_p_node_candidate;
    bool has_been_verified;
    bool degree_check_passed;
};

struct TreeValidationResult {
    int p_node_count;
    bool validation_successful;
};

NodeMetadata node_info[MAX_NODES];
int temporary_degree_storage[MAX_NODES];
bool node_status_flags[MAX_NODES];
bool parent_child_relationship_established[MAX_NODES][MAX_NODES];

void initialize_global_structures(int n) {
    for(int i = 0; i <= n; i++) {
        node_info[i].parent = -1;
        node_info[i].degree = 0;
        node_info[i].is_p_node_candidate = true;
        node_info[i].has_been_verified = false;
        node_info[i].degree_check_passed = false;
        temporary_degree_storage[i] = 0;
        node_status_flags[i] = false;
        for(int j = 0; j <= n; j++) {
            parent_child_relationship_established[i][j] = false;
        }
    }
}

TreeValidationResult validate_tree_and_count_p_nodes(int n) {
    TreeValidationResult result;
    result.p_node_count = 0;
    result.validation_successful = true;

    for(int i = 0; i < n; i++) {
        if(!node_info[i].has_been_verified) {
            bool parent_condition = true;
            bool children_condition = true;

            if(node_info[i].parent != -1) {
                if(node_info[i].degree > node_info[node_info[i].parent].degree) {
                    parent_condition = false;
                }
            }

            for(int j = 0; j < n; j++) {
                if(parent_child_relationship_established[i][j]) {
                    if(node_info[i].degree < node_info[j].degree) {
                        children_condition = false;
                        break;
                    }
                }
            }

            node_info[i].degree_check_passed = parent_condition && children_condition;
            node_info[i].has_been_verified = true;
        }

        if(node_info[i].degree_check_passed) {
            result.p_node_count++;
        }
    }

    return result;
}

int main() {
    std::ifstream input_file("p.in");
    std::ofstream output_file("p.out");

    if(!input_file.is_open()) {
        std::cerr << "Error opening input file: " << std::strerror(errno) << std::endl;
        return EXIT_FAILURE;
    }

    if(!output_file.is_open()) {
        std::cerr << "Error opening output file: " << std::strerror(errno) << std::endl;
        return EXIT_FAILURE;
    }

    int t;
    input_file >> t;

    while(t--) {
        int n;
        input_file >> n;

        initialize_global_structures(n);

        for(int i = 1; i < n; i++) {
            int x, y;
            input_file >> x >> y;

            if(x < 0 || x >= n || y < 0 || y >= n) {
                continue;
            }

            node_info[y].parent = x;
            parent_child_relationship_established[x][y] = true;
            node_info[x].degree++;
            temporary_degree_storage[x]++;
        }

        for(int i = 0; i < n; i++) {
            node_info[i].degree = temporary_degree_storage[i];
        }

        TreeValidationResult validation_result = validate_tree_and_count_p_nodes(n);

        if(validation_result.validation_successful) {
            output_file << validation_result.p_node_count << std::endl;
        } else {
            output_file << "0" << std::endl;
        }
    }

    input_file.close();
    output_file.close();

    return EXIT_SUCCESS;
}
