void initializeBallData(BallData& data, int m) {
    data.isInitialized = false;
    data.isSorted = false;
    data.sortedBalls.reserve(m);
    for (int i = 0; i < m; i++) {
        int ballNum;
        if (scanf("%d", &ballNum) != 1) {
            exit(EXIT_FAILURE);
        }
        if (ballNum < 0 || ballNum > 1000000000 + EXTRA_BUFFER) {
            exit(EXIT_FAILURE);
        }
        data.sortedBalls.push_back(ballNum);
        data.ballSet.insert(ballNum);
    }
    data.isInitialized = true;
}

void ensureSorted(BallData& data) {
    if (!data.isSorted && data.isInitialized) {
        sort(data.sortedBalls.begin(), data.sortedBalls.end());
        data.isSorted = true;
    }
}

int performBinarySearch(const BallData& data, int target) {
    if (!data.isInitialized || !data.isSorted) {
        return 0;
    }
    int left = 0;
    int right = data.sortedBalls.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (data.sortedBalls[mid] == target) {
            return 1;
        } else if (data.sortedBalls[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return 0;
}

