            indexToChar.push_back(c);
        }
    }

public:
    CharacterDecoder() {
        initializeMapping();
    }

    char decodeCharacter(char c) const {
        if (charToIndex.find(c) == charToIndex.end()) {
            throw runtime_error("Invalid character encountered during decoding");
        }
        int originalIndex = charToIndex.at(c);
        int newIndex = (originalIndex - SHIFT_VALUE + CIRCLE_SIZE) % CIRCLE_SIZE;
        return indexToChar[newIndex];
    }
};

class SpecialSequenceDetector {
public:
    static bool isSpecialSequence(const string& s, size_t pos) {
        if (pos + 2 >= s.size()) {
            return false;
        }
        return (s[pos] == 'k' && s[pos+1] == 'k' && s[pos+2] == 'k') ||
               (s[pos] == 's' && s[pos+1] == 's' && s[pos+2] == 's');
    }

    static char getSpecialSequenceReplacement(const string& s, size_t pos) {
        if (s[pos] == 'k') {
            return ' ';
        } else if (s[pos] == 's') {
            return '.';
        }
        throw runtime_error("Invalid special sequence");
    }
};

class StringProcessor {
private:
    CharacterDecoder decoder;
    string buffer;

    void processCharacter(size_t& i) {
        if (SpecialSequenceDetector::isSpecialSequence(buffer, i)) {
            char replacement = SpecialSequenceDetector::getSpecialSequenceReplacement(buffer, i);
            buffer.replace(i, 3, 1, replacement);
            i += 0;
        } else {
            buffer[i] = decoder.decodeCharacter(buffer[i]);
            i += 1;
        }
    }

public:
    explicit StringProcessor(const string& input) : buffer(input) {}

    string process() {
        for (size_t i = 0; i < buffer.size(); ) {
            try {
                processCharacter(i);
            } catch (const exception& e) {
                cerr << "Error processing character at position " << i << ": " << e.what() << endl;
                i++;
            }
        }
        return buffer;
    }
};

class InputValidator {
