    ctx.tripletType = '\0';
}

void handleTripletDetection(DecryptionContext& ctx) {
    if (ctx.currentPosition + 2 < ctx.original.length()) {
        char current = ctx.original[ctx.currentPosition];
        char next1 = ctx.original[ctx.currentPosition + 1];
        char next2 = ctx.original[ctx.currentPosition + 2];

        if (current == next1 && current == next2) {
            if (current == 'k' || current == 's') {
                ctx.inTriplet = true;
                ctx.tripletType = current;
                ctx.tripletPositions.push_back(ctx.currentPosition);
            }
        }
    }
}

void processTripletReplacement(DecryptionContext& ctx) {
    if (ctx.inTriplet) {
        if (ctx.tripletType == 'k') {
            ctx.processed += " ";
        } else if (ctx.tripletType == 's') {
            ctx.processed += ".";
        }
        ctx.currentPosition += 3;
        ctx.inTriplet = false;
    }
}

void processRegularCharacter(DecryptionContext& ctx) {
    if (!ctx.inTriplet) {
        char c = ctx.original[ctx.currentPosition];
        if (isdigit(c) {
            if (c >= '0' && c <= '6') {
                ctx.processed += (c + 3);
            } else if (c == '7') {
                ctx.processed += 'a';
            } else if (c == '8') {
                ctx.processed += 'b';
            } else if (c == '9') {
                ctx.processed += 'c';
            }
        } else if (islower(c)) {
            if (c >= 'a' && c <= 'w') {
                ctx.processed += (c + 3);
            } else if (c == 'x') {
                ctx.processed += '0';
            } else if (c == 'y') {
                ctx.processed += '1';
            } else if (c == 'z') {
                ctx.processed += '2';
            }
        } else {
            throw runtime_error("Invalid character encountered");
        }
        ctx.currentPosition++;
    }
}

string decryptMessage(const string& input) {
