struct DataSet {
    int x;
    int y;
    int diff;
    int index;
};

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else {
        if (min(a.x, a.y) != min(b.x, b.y)) {
            return min(a.x, a.y) < min(b.x, b.y);
        } else {
            return a.index < b.index;
        }
    }
}

void validateInput(int value, int min_val, int max_val, const string& message) {
    if (value < min_val || value > max_val) {
        throw invalid_argument(message);
    }
}

int computeAbsoluteDifference(int a, int b) {
    return abs(a - b);
}

int findMinValue(int a, int b) {
    return min(a, b);
}

int main() {
    try {
        int n;
        cin >> n;
        validateInput(n, 1, 100, "Invalid number of data sets");

        vector<DataSet> dataSets;
        dataSets.reserve(n);

