    static bool validateBallCount(int m) {
        return m >= 1 && m <= MAX_SIZE;
    }
    static bool validateGameCount(int n) {
        return n >= 1 && n <= MAX_SIZE;
    }
    static bool validateBallNumber(int i) {
        return i >= 0 && i <= 1000000000 + SAFETY_BUFFER;
    }
};

class BallGameProcessor {
private:
    vector<int> ballNumbers;
    unordered_set<int> ballSet;
    bool useOptimizedSearch;

    void initializeDataStructures() {
        ballSet.reserve(ballNumbers.size());
        for (const auto& num : ballNumbers) {
            ballSet.insert(num);
        }
    }

public:
    BallGameProcessor(const vector<int>& numbers) : ballNumbers(numbers) {
        if (ballNumbers.size() > MAX_SIZE) {
            throw runtime_error("Exceeded maximum ball count");
        }
        sort(ballNumbers.begin(), ballNumbers.end());
        initializeDataStructures();
        useOptimizedSearch = ballNumbers.size() > 1000;
    }

    bool containsBall(int k) {
        if (!InputValidation::validateBallNumber(k)) {
            return false;
        }

        if (useOptimizedSearch) {
            auto it = lower_bound(ballNumbers.begin(), ballNumbers.end(), k);
            return it != ballNumbers.end() && *it == k;
        } else {
            return ballSet.find(k) != ballSet.end();
        }
    }
};

