        return EXIT_FAILURE;
    }

    vector<int> ballNumbers(m);
    for (int i = 0; i < m; ++i) {
        inputFile >> ballNumbers[i];
        if (!InputValidation::validateBallNumber(ballNumbers[i])) {
            cerr << "Invalid ball number detected" << endl;
            return EXIT_FAILURE;
        }
    }

