#include <functional>
#include <atomic>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>

using namespace std;

constexpr size_t MAX_BALLS = 1000005;
constexpr int MAX_NUMBER = 1000000000 + 100;

struct BallValidator {
    static bool validateNumber(int num) {
        return num >= 0 && num <= MAX_NUMBER;
    }
};

class BallDatabase {
private:
    vector<int> numbers;
    mutable mutex mtx;
    atomic<bool> initialized{false};

    void initializeDatabase(const vector<int>& nums) {
        unique_lock<mutex> lock(mtx);
        if (!initialized) {
            numbers = nums;
            sort(numbers.begin(), numbers.end());
            numbers.erase(unique(numbers.begin(), numbers.end()), numbers.end());
            initialized = true;
        }
    }

public:
    BallDatabase() = default;

    void loadData(const vector<int>& nums) {
        if (nums.size() > MAX_BALLS) {
            throw runtime_error("Exceeded maximum ball count");
        }
        for (int num : nums) {
            if (!BallValidator::validateNumber(num)) {
                throw runtime_error("Invalid ball number detected");
            }
        }
        initializeDatabase(nums);
    }

    bool contains(int k) const {
        if (!initialized) {
            throw runtime_error("Database not initialized");
        }
        if (!BallValidator::validateNumber(k)) {
            return false;
        }
        lock_guard<mutex> lock(mtx);
        return binary_search(numbers.begin(), numbers.end(), k);
    }
};

class InputParser {
private:
    static vector<int> parseLine(istream& is, size_t expectedCount) {
        vector<int> result;
        string line;
        getline(is, line);
        istringstream iss(line);
        copy(istream_iterator<int>(iss), istream_iterator<int>(), back_inserter(result));
        if (result.size() != expectedCount) {
            throw runtime_error("Unexpected input size");
        }
        return result;
    }

public:
    static pair<vector<int>, vector<int>> parseInput(const string& filename) {
        ifstream ifs(filename);
        if (!ifs.is_open()) {
            throw runtime_error("Failed to open input file");
        }

        string firstLine;
        getline(ifs, firstLine);
        istringstream iss(firstLine);
        int m, n;
        if (!(iss >> m >> n)) {
            throw runtime_error("Invalid first line format");
        }

        auto balls = parseLine(ifs, m);
        auto queries = parseLine(ifs, n);

        return {balls, queries};
    }
};

class OutputHandler {
private:
    ofstream ofs;
    mutex mtx;

public:
    OutputHandler(const string& filename) {
        ofs.open(filename);
        if (!ofs.is_open()) {
            throw runtime_error("Failed to open output file");
        }
    }

    void writeResult(bool result) {
        lock_guard<mutex> lock(mtx);
        ofs << (result ? "YES" : "NO") << '\n';
    }
};

int main() {
    try {
        auto [balls, queries] = InputParser::parseInput("ball.in");
        BallDatabase database;
        database.loadData(balls);

        OutputHandler output("ball.out");

        vector<future<void>> futures;
        for (int k : queries) {
            futures.push_back(async(launch::async, [&database, &output, k]() {
                bool result = database.contains(k);
                output.writeResult(result);
            }));
        }

        for (auto& f : futures) {
            f.get();
        }
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
