struct DecryptionMapping {
    char encrypted;
    char decrypted;
};

vector<DecryptionMapping> buildCustomMappingTable() {
    vector<DecryptionMapping> mappingTable;
    for (char c = 'd'; c <= 'z'; ++c) {
        mappingTable.push_back({c, static_cast<char>(c - 3)});
    }
    for (char c = '3'; c <= '9'; ++c) {
        mappingTable.push_back({c, static_cast<char>(c - 3)});
    }
    for (char c = 'a'; c <= 'c'; ++c) {
        mappingTable.push_back({c, static_cast<char>('7' + (c - 'a'))});
    }
    for (char c = '0'; c <= '2'; ++c) {
        mappingTable.push_back({c, static_cast<char>('x' + (c - '0'))});
    }
    return mappingTable;
}

string processSpecialPatterns(const string& input) {
    string processed;
    size_t currentPosition = 0;
    while (currentPosition < input.size()) {
        if (currentPosition + 2 < input.size()) {
            string triplet = input.substr(currentPosition, 3);
            if (triplet == "kkk") {
                processed += ' ';
                currentPosition += 3;
                continue;
            } else if (triplet == "sss") {
                processed += '.';
                currentPosition += 3;
                continue;
            }
        }
        processed += input[currentPosition];
        currentPosition++;
    }
    return processed;
}

char decryptSingleCharacter(char c, const vector<DecryptionMapping>& mappingTable) {
    for (const auto& entry : mappingTable) {
        if (entry.encrypted == c) {
            return entry.decrypted;
        }
    }
    return c;
}

