#include<cctype>
#include<stdexcept>
using namespace std;

const string SPECIAL_KKK = "kkk";
const string SPECIAL_SSS = "sss";
const int SHIFT_VALUE = 3;
const char NUM_START = '0';
const char NUM_END = '9';
const char LETTER_START = 'a';
const char LETTER_END = 'z';

struct DecryptionMapping {
    char from;
    char to;
};

vector<DecryptionMapping> buildDecryptionMap() {
    vector<DecryptionMapping> mappings;

    for (char c = 'a'; c <= 'z'; ++c) {
        DecryptionMapping m;
        m.from = c;
        m.to = (c - 'a' - SHIFT_VALUE + 26) % 26 + 'a';
        mappings.push_back(m);
    }

    for (char c = '0'; c <= '9'; ++c) {
        DecryptionMapping m;
        m.from = c;
        m.to = (c - '0' - SHIFT_VALUE + 10) % 10 + '0';
        mappings.push_back(m);
    }

    return mappings;
}

bool isSpecialSequence(const string& s, size_t pos, const string& seq) {
    if (pos + seq.length() > s.length()) return false;
    for (size_t i = 0; i < seq.length(); ++i) {
        if (s[pos + i] != seq[i]) return false;
    }
    return true;
}

string handleSpecialSequences(const string& input) {
    string result;
    size_t i = 0;
    while (i < input.length()) {
        if (isSpecialSequence(input, i, SPECIAL_KKK)) {
            result += ' ';
            i += SPECIAL_KKK.length();
        } else if (isSpecialSequence(input, i, SPECIAL_SSS)) {
            result += '.';
            i += SPECIAL_SSS.length();
        } else {
            result += input[i];
            ++i;
        }
    }
    return result;
}

char decryptChar(char c, const vector<DecryptionMapping>& mappings) {
    if (!isalnum(c)) throw runtime_error("Invalid character encountered");

    for (const auto& m : mappings) {
        if (m.from == c) {
            return m.to;
        }
    }

    if (isdigit(c)) {
        return (c - NUM_START - SHIFT_VALUE + 10) % 10 + NUM_START;
    } else if (isalpha(c)) {
        return (c - LETTER_START - SHIFT_VALUE + 26) % 26 + LETTER_START;
    }

    throw runtime_error("Character decryption failed");
}

string decryptString(const string& input) {
    string processed = handleSpecialSequences(input);
    vector<DecryptionMapping> mappings = buildDecryptionMap();
    string result;

    for (char c : processed) {
        if (c == ' ' || c == '.') {
            result += c;
        } else {
            try {
                result += decryptChar(c, mappings);
            } catch (const exception& e) {
                result += c;
            }
        }
    }

    return result;
}

int main() {
