    getline(cin, encrypted);

    if (encrypted.empty()) {
        cout << "" << endl;
        return 0;
    }

    string decrypted = decryptString(encrypted);

    if (decrypted.empty()) {
        cout << "DECRYPTION_FAILED" << endl;
    } else {
        cout << decrypted << endl;
    }

    return 0;
}
