class BinaryParser {
private:
    string buffer;
    size_t position;
    bool errorFlag;

    void validateInputFile(ifstream& file) {
        if (!file.is_open()) {
            errorFlag = true;
            return;
        }
        if (file.peek() == ifstream::traits_type::eof()) {
            errorFlag = true;
            return;
        }
    }

    bool isValidBinaryChar(char c) {
        return c == '0' || c == '1';
    }

    void validateBinaryString() {
        if (buffer.length() % UNIT_SIZE != 0) {
            errorFlag = true;
            return;
        }
        for (char c : buffer) {
            if (!isValidBinaryChar(c)) {
                errorFlag = true;
                return;
            }
        }
    }

    int binaryToDecimal(const string& bin) {
        int decimal = 0;
        for (char c : bin) {
            decimal = decimal * 2 + (c - '0');
        }
        return decimal;
    }

    char processLetterUnit(const string& unit) {
        if (unit.substr(0, 3) != "101") {
            errorFlag = true;
            return '\0';
        }
        int letterCode = binaryToDecimal(unit.substr(3));
        if (letterCode < 0 || letterCode > 25) {
            errorFlag = true;
            return '\0';
        }
        return 'A' + letterCode;
    }

    pair<int, bool> processNumberUnit(const string& unit1, const string& unit2) {
        if (unit1[0] != '0' || unit2[0] != '0') {
            errorFlag = true;
            return make_pair(0, false);
        }
        int num1 = binaryToDecimal(unit1);
        int num2 = binaryToDecimal(unit2);
        num1 /= 2;
        num2 /= 2;
        return make_pair(num1 + num2, true);
    }

public:
    BinaryParser(const string& input) : buffer(input), position(0), errorFlag(false) {
        validateBinaryString();
    }

    string parse() {
        string result;
        while (position < buffer.length() && !errorFlag) {
            string currentUnit = buffer.substr(position, UNIT_SIZE);
            position += UNIT_SIZE;

            if (currentUnit.length() < UNIT_SIZE) {
                errorFlag = true;
                break;
            }

            if (currentUnit.substr(0, 3) == "101") {
                char letter = processLetterUnit(currentUnit);
                if (errorFlag) break;
                result += letter;
            } else if (currentUnit.substr(0, 3) == "111") {
                if (currentUnit != "11100000") {
                    errorFlag = true;
                    break;
                }
                result += ' ';
            } else if (currentUnit[0] == '0') {
                if (position + UNIT_SIZE > buffer.length()) {
                    errorFlag = true;
                    break;
                }
                string nextUnit = buffer.substr(position, UNIT_SIZE);
                auto numberResult = processNumberUnit(currentUnit, nextUnit);
                if (errorFlag) break;
                result += to_string(numberResult.first);
                position += UNIT_SIZE;
            } else {
                errorFlag = true;
                break;
            }
        }
        return errorFlag ? "Error" : result;
    }
};

