#include <iostream>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <type_traits>

template<typename T>
constexpr bool is_positive_integer(T value) {
    return std::is_integral<T>::value && value > 0;
}

template<typename T>
constexpr bool is_within_range(T value, T min, T max) {
    return value >= min && value <= max;
}

template<typename T>
T safe_divide(T numerator, T denominator) {
    if (denominator == 0) {
        throw std::runtime_error("Division by zero encountered");
    }
    return numerator / denominator;
}

template<typename T>
T safe_subtract(T a, T b) {
    if (a < b) {
        throw std::runtime_error("Subtraction would result in negative value");
    }
    return a - b;
}

template<typename T>
T calculate_time_to_shoot(T n, T a, T b) {
    if (!is_positive_integer(n) || !is_positive_integer(a) || !is_positive_integer(b)) {
        throw std::invalid_argument("All inputs must be positive integers");
    }

    if (!is_within_range(n, static_cast<T>(1), static_cast<T>(1000)) {
        throw std::out_of_range("n is out of valid range");
    }

    if (!is_within_range(a, static_cast<T>(1), static_cast<T>(1000))) {
        throw std::out_of_range("a is out of valid range");
    }

    if (!is_within_range(b, static_cast<T>(1), static_cast<T>(1000))) {
        throw std::out_of_range("b is out of valid range");
    }

    if (b <= a) {
        throw std::logic_error("Troops speed must be greater than enemy speed");
    }

    T initial_distance = safe_subtract(a * n, 600);
    if (initial_distance <= 0) {
        throw std::logic_error("Initial distance must be greater than shooting distance");
    }

    T relative_speed = safe_subtract(b, a);
    T time = safe_divide(initial_distance, relative_speed);

    if (time * relative_speed < initial_distance) {
        time += 1;
    }

    return time;
}

int main() {
    try {
        int n, a, b;
        std::cin >> n >> a >> b;

        if (std::cin.fail()) {
            throw std::runtime_error("Invalid input format");
        }

        int result = calculate_time_to_shoot(n, a, b);
        std::cout << result << std::endl;
