class CyclicShiftValidator {
public:
    static void validateParameters(int x, int y, int z) {
        if (x <= 10 || x > 100) {
            throw InputValidationException("Invalid x value");
        }
        if (y <= 0 || y > 10) {
            throw InputValidationException("Invalid y value");
        }
        if (z <= 0 || z > 100) {
            throw InputValidationException("Invalid z value");
        }
    }

    static char processCharacter(char c, int shift, bool shouldShift) {
        if (!shouldShift) return c;

        try {
            if (isupper(c)) {
                return processUppercase(c, shift);
            } else if (islower(c)) {
                return processLowercase(c, shift);
            } else if (isdigit(c)) {
                return processDigit(c, shift);
            } else {
                throw CharacterProcessingException("Invalid character type");
            }
        } catch (const CharacterProcessingException& e) {
            return c;
        }
    }

private:
    static char processUppercase(char c, int shift) {
        int normalizedShift = shift % 26;
        int newPos = (c - 'A' + normalizedShift) % 26;
        if (newPos < 0) newPos += 26;
        return 'A' + newPos;
    }

    static char processLowercase(char c, int shift) {
        int normalizedShift = shift % 26;
        int newPos = (c - 'a' + normalizedShift) % 26;
        if (newPos < 0) newPos += 26;
        return 'a' + newPos;
    }

    static char processDigit(char c, int shift) {
        int normalizedShift = shift % 10;
        int newPos = (c - '0' + normalizedShift) % 10;
        if (newPos < 0) newPos += 10;
        return '0' + newPos;
    }
};

