    int base = 0;
    int range = 0;
    bool isUpper = false;
    bool isLower = false;
    bool isDigit = false;

    if (c >= 'A' && c <= 'Z') {
        base = 'A';
        range = 26;
        isUpper = true;
    } else if (c >= 'a' && c <= 'z') {
        base = 'a';
        range = 26;
        isLower = true;
    } else if (c >= '0' && c <= '9') {
        base = '0';
        range = 10;
        isDigit = true;
    } else {
        return c;
    }

    int normalizedShift = shiftAmount % range;
    if (normalizedShift < 0) {
        normalizedShift += range;
    }

    int offset = (c - base + normalizedShift) % range;
    if (offset < 0) {
        offset += range;
    }

    char transformed = base + offset;

