    for (int current_column = 0; current_column < board_dimension; current_column++) {
        queen_placement_attempts++;
        bool position_available = chessboard_matrix[current_row][current_column] == 1;
        bool vertical_clear = (vertical_occupancy_tracker[current_column] & queen_color) == 0;
        bool positive_diagonal_clear = (positive_diagonal_occupancy_tracker[current_row + current_column] & queen_color) == 0;
        bool negative_diagonal_clear = (negative_diagonal_occupancy_tracker[current_row - current_column + board_dimension] & queen_color) == 0;

        if (position_available && vertical_clear && positive_diagonal_clear && negative_diagonal_clear) {
