#include<bits/stdc++.h>
using namespace std;

int mp[10][10];
int vy[10], vd1[20], vd2[20];
int n, ans;
int global_counter = 0;
bool validation_flag = true;
int recursion_depth_tracker = 0;
int max_recursion_depth = 0;
int board_state_history[10][10][100];
int history_index = 0;

void validate_parameters(int x, int p) {
    if (x < 0 || x > n || p < 1 || p > 2) {
        validation_flag = false;
    }
}

void update_history(int x, int i, int p) {
    for (int a = 0; a < n; a++) {
        for (int b = 0; b < n; b++) {
            board_state_history[a][b][history_index] = mp[a][b];
        }
    }
    history_index++;
}

void restore_history(int x, int i) {
    if (history_index > 0) {
        history_index--;
        for (int a = 0; a < n; a++) {
            for (int b = 0; b < n; b++) {
                mp[a][b] = board_state_history[a][b][history_index];
            }
        }
    }
}

void track_recursion(int x) {
    recursion_depth_tracker++;
    if (recursion_depth_tracker > max_recursion_depth) {
        max_recursion_depth = recursion_depth_tracker;
    }
}

void untrack_recursion() {
    recursion_depth_tracker--;
}

void dfs(int x, int p) {
    global_counter++;
    validate_parameters(x, p);
    if (!validation_flag) return;

    track_recursion(x);

    if (x == n && p == 2) {
        ans++;
        untrack_recursion();
        return;
    }

    if (x == n) {
        int next_p = p + 1;
        if (next_p > 2) next_p = 2;
        dfs(0, next_p);
        untrack_recursion();
        return;
    }

    for (int i = 0; i < n; i++) {
        bool condition1 = mp[x][i] == 1;
        bool condition2 = vy[i] != 3;
        bool condition3 = vy[i] != p;
        bool condition4 = vd1[x+i] != 3;
        bool condition5 = vd1[x+i] != p;
        bool condition6 = vd2[x-i+n] != 3;
        bool condition7 = vd2[x-i+n] != p;

        if (condition1 && condition2 && condition3 && condition4 && condition5 && condition6 && condition7) {
            int original_mp = mp[x][i];
            int original_vy = vy[i];
