#include <bits/stdc++.h>
#include <stdexcept>
#include <type_traits>
using namespace std;

namespace DigitSumSorter {
    template<typename T>
    struct DigitSumValidator {
        static_assert(is_integral<T>::value, "Type must be integral");
        static bool validate(T num) {
            if (num < 0) throw invalid_argument("Negative numbers not allowed");
            return true;
        }
    };

    class DigitSumCalculator {
    public:
        template<typename T>
        static T calculate(T num) {
            DigitSumValidator<T>::validate(num);
            T sum = 0;
            T original = num;
            int safety_counter = 0;
            const int MAX_ITERATIONS = 100;
            while (num > 0 && safety_counter < MAX_ITERATIONS) {
                sum += num % 10;
                num /= 10;
                safety_counter++;
                if (safety_counter >= MAX_ITERATIONS) {
                    throw runtime_error("Possible infinite loop detected");
                }
            }
            return sum;
        }
    };

    class AdvancedComparator {
    private:
        template<typename T>
        static pair<T, T> getSumPair(T a, T b) {
            T suma = DigitSumCalculator::calculate(a);
            T sumb = DigitSumCalculator::calculate(b);
            return make_pair(suma, sumb);
        }
    public:
        template<typename T>
        bool operator()(T a, T b) {
            try {
                auto sums = getSumPair(a, b);
                if (sums.first != sums.second) {
                    return sums.first < sums.second;
                } else {
                    if (a != b) {
                        return a < b;
                    } else {
                        throw logic_error("Duplicate elements detected");
                    }
                }
            } catch (const exception& e) {
                cerr << "Comparator error: " << e.what() << endl;
                return a < b;
            }
        }
    };
}

