#include <bits/stdc++.h>
#include <stdexcept>
using namespace std;

struct PlateInfo {
    string original;
    int numeric;
    int sum;
    int index;
};

bool validateNumberString(const string& s) {
    if (s.empty()) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    return true;
}

int calculateDigitSum(int num) {
    if (num < 0) num = -num;
    int total = 0;
    while (num != 0) {
        total += num % 10;
        num /= 10;
    }
    return total;
}

bool comparePlates(const PlateInfo& a, const PlateInfo& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    return a.numeric > b.numeric;
}

void processInput(vector<PlateInfo>& plates, int n) {
    plates.resize(n);
    for (int i = 0; i < n; ++i) {
        string input;
        cin >> input;
        if (!validateNumberString(input)) {
            throw invalid_argument("Invalid number plate format");
        }
        plates[i].original = input;
        plates[i].numeric = stoi(input);
        plates[i].sum = calculateDigitSum(plates[i].numeric);
        plates[i].index = i;
    }
}

int findPosition(const vector<PlateInfo>& plates, const string& target) {
    if (!validateNumberString(target)) {
        throw invalid_argument("Invalid target plate format");
    }
    int targetNum = stoi(target);
    int targetSum = calculateDigitSum(targetNum);

    vector<pair<int, int>> sumAndValue;
    for (const auto& plate : plates) {
        sumAndValue.emplace_back(plate.sum, plate.numeric);
    }

    sort(sumAndValue.begin(), sumAndValue.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) {
            return a.first < b.first;
        }
        return a.second > b.second;
    });

    pair<int, int> targetPair = make_pair(targetSum, targetNum);
    auto it = lower_bound(sumAndValue.begin(), sumAndValue.end(), targetPair, 
        [](const pair<int, int>& a, const pair<int, int>& b) {
            if (a.first != b.first) {
                return a.first < b.first;
            }
            return a.second > b.second;
        });

    if (it != sumAndValue.end() && it->first == targetSum && it->second == targetNum) {
        return distance(sumAndValue.begin(), it) + 1;
    }

    vector<PlateInfo> sortedPlates = plates;
    sort(sortedPlates.begin(), sortedPlates.end(), comparePlates);

    for (size_t i = 0; i < sortedPlates.size(); ++i) {
        if (sortedPlates[i].original == target) {
            return i + 1;
        }
    }

    return -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cerr << "Invalid number of plates" << endl;
        return 1;
    }

    vector<PlateInfo> plates;
    try {
        processInput(plates, n);
    } catch (const exception& e) {
        cerr << "Error processing input: " << e.what() << endl;
        return 1;
    }

    string targetPlate = plates.back().original;
    int result = -1;

    try {
        result = findPosition(plates, targetPlate);
    } catch (const exception& e) {
        cerr << "Error finding position: " << e.what() << endl;
        return 1;
    }

    if (result == -1) {
        cerr << "Target plate not found in list" << endl;
        return 1;
    }

    cout << result << endl;
    return 0;
}
