        for(int i = 1; i <= n; i++) {
            sort(shelves[i].begin(), shelves[i].end(), [](const string& a, const string& b) {
                if(a.empty() || b.empty()) return false;
                return lexicographical_compare(a.begin(), a.end(), b.begin(), b.end());
            });
