        insertion_order = global_order_counter++;
    }
};

int QueueNode::global_order_counter = 0;

bool is_friend_relationship(const string& a, const string& b) {
    if(a.empty() || b.empty()) return false;
    char first_a = toupper(static_cast<unsigned char>(a[0]));
    char first_b = toupper(static_cast<unsigned char>(b[0]));
    return first_a == first_b;
}

void process_queue_insertion(vector<QueueNode>& container, const string& name) {
    bool friend_found = false;
    size_t insertion_position = container.size();
    QueueNode new_node(name);

    for(size_t i = 0; i < container.size(); ++i) {
        if(!container[i].processed && is_friend_relationship(container[i].name, name)) {
            insertion_position = i + 1;
            friend_found = true;
            break;
        }
    }

    if(!friend_found) {
        insertion_position = container.size();
    }

    container.insert(container.begin() + insertion_position, new_node);
}

