void initializeQueue(AdvancedQueue* q) {
    q->front = 0;
    q->rear = -1;
    q->capacity = 105;
    q->size = 0;
}

bool isQueueEmpty(AdvancedQueue* q) {
    return q->size == 0;
}

bool isQueueFull(AdvancedQueue* q) {
    return q->size == q->capacity;
}

void enqueueWithComplexLogic(AdvancedQueue* q, string name) {
    if (isQueueFull(q)) {
        return;
    }

    bool friendFound = false;
    int insertPosition = -1;

    for (int i = q->front; i <= q->rear; i++) {
        if (q->data[i][0] == name[0]) {
            insertPosition = i + 1;
            friendFound = true;
            break;
        }
    }

    if (friendFound) {
        if (insertPosition > q->rear) {
            q->rear++;
            q->data[q->rear] = name;
        } else {
            for (int j = q->rear + 1; j > insertPosition; j--) {
                if (j < q->capacity) {
                    q->data[j] = q->data[j - 1];
                }
            }
            q->data[insertPosition] = name;
            q->rear++;
        }
    } else {
        q->rear++;
        q->data[q->rear] = name;
    }

    q->size++;
}

