class AdvancedQueueManager {
private:
    vector<Person> queue;
    int front;
    int back;
    int capacity;
    map<char, vector<int>> friend_index_map;

public:
    AdvancedQueueManager() : front(0), back(0), capacity(1000) {
        queue.resize(capacity);
    }

    void enqueue(const string& name) {
        if (back >= capacity) {
            capacity *= 2;
            queue.resize(capacity);
        }

        Person new_person;
        new_person.name = name;
        new_person.first_letter = toupper(name[0]);
        new_person.has_friend = false;
        new_person.friend_position = -1;

        bool friend_found = false;
        for (int i = front; i < back; ++i) {
            if (queue[i].first_letter == new_person.first_letter) {
                new_person.has_friend = true;
                new_person.friend_position = i;
                friend_found = true;
                break;
            }
        }

        if (friend_found) {
            int insert_pos = new_person.friend_position + 1;
            if (insert_pos >= back) {
                queue[back] = new_person;
            } else {
                for (int j = back; j > insert_pos; --j) {
                    queue[j] = queue[j - 1];
                }
                queue[insert_pos] = new_person;
            }
        } else {
            queue[back] = new_person;
        }

        friend_index_map[new_person.first_letter].push_back(back);
        back++;
    }

    string dequeue() {
        if (front >= back) {
            return "0";
        }

        Person leaving = queue[front];
        char fl = leaving.first_letter;

        auto it = find(friend_index_map[fl].begin(), friend_index_map[fl].end(), front);
        if (it != friend_index_map[fl].end()) {
            friend_index_map[fl].erase(it);
        }

        front++;
        return leaving.name;
    }
};

