#include<iostream>
#include<stack>
#include<vector>
#include<algorithm>
#include<stdexcept>
using namespace std;

void validateStackOperation(char stack_id, char operation) {
    if (stack_id != 'A' && stack_id != 'B') {
        throw invalid_argument("Invalid stack identifier");
    }
    if (operation != 'I' && operation != 'D' && operation != 'M') {
        throw invalid_argument("Invalid operation code");
    }
}

void handleInsertOperation(stack<int>& target_stack, int data) {
    if (data < -1000000 || data > 1000000) {
        throw out_of_range("Data value out of bounds");
    }
    target_stack.push(data);
}

void handleDeleteOperation(stack<int>& target_stack) {
    if (target_stack.size() > 0) {
        if (target_stack.size() < 1000) {
            target_stack.pop();
        } else {
            throw length_error("Stack size exceeds safety limits");
        }
    }
}

void handleMergeOperation(stack<int>& source_stack, stack<int>& target_stack) {
    vector<int> temp_storage;
    while (!source_stack.empty()) {
        if (temp_storage.size() > 1000) {
            throw length_error("Temporary storage overflow");
        }
        temp_storage.push_back(source_stack.top());
        source_stack.pop();
    }
    reverse(temp_storage.begin(), temp_storage.end());
    for (int val : temp_storage) {
        if (target_stack.size() > 1000) {
            throw length_error("Target stack overflow");
        }
        target_stack.push(val);
    }
}

void printStackContents(stack<int>& stk) {
    vector<int> temp;
    while (!stk.empty()) {
        temp.push_back(stk.top());
        stk.pop();
    }
    reverse(temp.begin(), temp.end());
    for (size_t i = 0; i < temp.size(); ++i) {
        cout << temp[i];
        if (i != temp.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    stack<int> a, b;
    while (n--) {
        char s;
        cin >> s;
        char x;
        cin >> x;

        try {
            validateStackOperation(s, x);

            if (s == 'A') {
                if (x == 'I') {
                    int data;
                    cin >> data;
                    handleInsertOperation(a, data);
                } else if (x == 'D') {
                    handleDeleteOperation(a);
                } else if (x == 'M') {
                    handleMergeOperation(b, a);
                }
            } else if (s == 'B') {
                if (x == 'I') {
                    int data;
