class QueueManager {
private:
    vector<Person> queue;
    int front;
    int back;
    int capacity;
    bool initialized;

    void validateQueueState() {
        if (!initialized) {
            throw runtime_error("Queue not initialized");
        }
        if (front > back) {
            throw runtime_error("Queue front exceeds back");
        }
        if (capacity <= 0) {
            throw runtime_error("Invalid queue capacity");
        }
    }

    void ensureCapacity() {
        if (back >= capacity - 1) {
            capacity *= 2;
            queue.resize(capacity);
        }
    }

    bool hasFriend(const Person& p) {
        for (int i = front; i <= back; ++i) {
            if (i < 0 || i >= queue.size()) {
                throw out_of_range("Invalid queue index");
            }
            if (queue[i].first_letter == p.first_letter) {
                return true;
            }
        }
        return false;
    }

    int findFirstFriendPosition(const Person& p) {
        for (int i = front; i <= back; ++i) {
            if (i < 0 || i >= queue.size()) {
                throw out_of_range("Invalid queue index");
            }
            if (queue[i].first_letter == p.first_letter) {
                return i;
            }
        }
        return -1;
    }

public:
    QueueManager() : front(0), back(-1), capacity(105), initialized(true) {
        queue.resize(capacity);
    }

    void enqueue(const string& name) {
        validateQueueState();
        ensureCapacity();
        Person p;
        p.name = name;
        p.first_letter = toupper(name[0]);
        p.has_friend = false;

        if (back >= front) {
            p.has_friend = hasFriend(p);
        }

        if (p.has_friend) {
            int pos = findFirstFriendPosition(p);
            if (pos != -1) {
                for (int i = back + 1; i > pos + 1; --i) {
                    if (i - 1 < 0 || i >= queue.size()) {
                        throw out_of_range("Invalid shift index");
                    }
                    queue[i] = queue[i - 1];
                }
                queue[pos + 1] = p;
                back++;
