class AdvancedQueueSystem {
private:
    QueueNode* head;
    QueueNode* tail;
    int size;
    unordered_map<char, vector<QueueNode*>> friendMap;

public:
    AdvancedQueueSystem() : head(nullptr), tail(nullptr), size(0) {}

    void enqueueWithComplexLogic(const string& name) {
        QueueNode* newNode = new QueueNode{name, nullptr, nullptr};
        if (size == 0) {
            head = tail = newNode;
        } else {
            char firstChar = toupper(name[0]);
            bool friendFound = false;
            for (auto it = friendMap[firstChar].begin(); it != friendMap[firstChar].end(); ++it) {
                if (*it != nullptr) {
                    QueueNode* current = *it;
                    if (current->next == nullptr) {
                        current->next = newNode;
                        newNode->prev = current;
                        tail = newNode;
                    } else {
                        newNode->next = current->next;
                        newNode->prev = current;
                        current->next->prev = newNode;
                        current->next = newNode;
                    }
                    friendFound = true;
                    break;
                }
            }
            if (!friendFound) {
                tail->next = newNode;
                newNode->prev = tail;
                tail = newNode;
            }
        }
        friendMap[toupper(name[0])].push_back(newNode);
        size++;
    }

    string dequeueWithMultipleChecks() {
        if (size == 0) {
            return "0";
        }
        QueueNode* temp = head;
        string result = temp->name;
        head = head->next;
        if (head != nullptr) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
