        char firstChar = toupper(result[0]);
        auto& friends = friendMap[firstChar];
        for (auto it = friends.begin(); it != friends.end(); ) {
            if (*it == temp) {
                it = friends.erase(it);
            } else {
                ++it;
            }
        }
        delete temp;
        size--;
        return result;
    }

    bool isEmpty() const {
        return size == 0;
    }
};

