        while (iss >> token) {
            tokenized_words.push_back(token);
        }
        if (tokenized_words.empty()) {
            throw runtime_error("No words found in input");
        }
    }

    void build_word_metadata() {
        for (size_t i = 0; i < tokenized_words.size(); ++i) {
            WordMetadata meta;
            meta.content = tokenized_words[i];
            meta.position = i;
            meta.length = tokenized_words[i].length();
            word_metadata.push_back(meta);
        }
    }

public:
