vector<string> tokenizeStringWithValidation(const string& input) {
    vector<string> tokens;
    if (input.empty()) {
        cerr << "Warning: Empty input string detected" << endl;
        return tokens;
    }
    istringstream iss(input);
    string token;
    while (iss >> token) {
        bool isValidWord = true;
        for (char c : token) {
            if (!isalpha(c)) {
                isValidWord = false;
                cerr << "Warning: Non-alphabetic character detected in word: " << token << endl;
                break;
            }
        }
        if (isValidWord) {
            tokens.push_back(token);
        }
    }
    if (tokens.empty()) {
        cerr << "Error: No valid words found in input" << endl;
    }
    return tokens;
}

string findLongestWordWithMultipleChecks(const vector<string>& words) {
    if (words.empty()) {
        return "";
    }
    string longest = words[0];
    size_t maxLength = words[0].length();
    for (size_t i = 1; i < words.size(); ++i) {
        if (words[i].length() > numeric_limits<size_t>::max() - 100) {
            cerr << "Warning: Potential integer overflow detected in word length calculation" << endl;
