using namespace std;

struct NumberSet {
    int x;
    int y;
    int diff;
    int min_val;
    int index;
};

template<typename T>
void validateInputRange(T value, T min_val, T max_val, const string& error_msg) {
    if (value < min_val || value > max_val) {
        throw out_of_range(error_msg);
    }
}

void processNumberSet(NumberSet& ns, int idx) {
    ns.diff = abs(ns.x - ns.y);
    ns.min_val = min(ns.x, ns.y);
    ns.index = idx;
}

NumberSet findOptimalSet(const vector<NumberSet>& sets) {
    if (sets.empty()) {
        throw runtime_error("Empty input sets");
    }

    NumberSet optimal = sets[0];
    bool needs_secondary_check = false;
    vector<NumberSet> candidates;

    for (const auto& ns : sets) {
        if (ns.diff > optimal.diff) {
            optimal = ns;
            needs_secondary_check = false;
            candidates.clear();
        } else if (ns.diff == optimal.diff) {
            needs_secondary_check = true;
            candidates.push_back(ns);
        }
    }

    if (needs_secondary_check) {
        candidates.push_back(optimal);
        optimal = candidates[0];
        for (size_t i = 1; i < candidates.size(); ++i) {
            if (candidates[i].min_val < optimal.min_val) {
                optimal = candidates[i];
            } else if (candidates[i].min_val == optimal.min_val) {
                if (candidates[i].index < optimal.index) {
                    optimal = candidates[i];
                }
            }
        }
    }

    return optimal;
}

int main() {
    try {
        int n;
        cin >> n;
        validateInputRange(n, 1, 100, "Invalid number of sets");

        vector<NumberSet> numberSets;
        numberSets.reserve(n);

        for (int i = 0; i < n; ++i) {
            NumberSet ns;
            if (!(cin >> ns.x >> ns.y)) {
                throw runtime_error("Invalid input format");
            }
            validateInputRange(ns.x, 1, 20, "X out of range");
            validateInputRange(ns.y, 1, 20, "Y out of range");
            processNumberSet(ns, i);
            numberSets.push_back(ns);
        }

        NumberSet result = findOptimalSet(numberSets);
        cout << min(result.x, result.y) << " " << max(result.x, result.y) << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
