using namespace std;

int validateInput(const string& s) {
    if (s.empty()) throw runtime_error("Empty input");
    for (char c : s) {
        if (!isdigit(c) {
            if (c != '?') throw runtime_error("Invalid character");
        }
    }
    return stoi(s);
}

int computeGarlicValue(const string& s, bool hasWildcard) {
    int total = 0;
    int weight = 1;
    for (int i = s.length() - 1; i >= 0; --i) {
        if (s[i] == '?') {
            if (hasWildcard) throw runtime_error("Multiple wildcards");
            hasWildcard = true;
            continue;
        }
        int digit = s[i] - '0';
        if (digit < 0 || digit > 9) throw runtime_error("Invalid digit");
        total += digit * weight;
        ++weight;
    }
    return total;
}

bool isValidDigit(int d) {
    return d >= 0 && d <= 9;
}

string processReceipt(const string& receipt, int balance) {
    size_t qpos = receipt.find('?');
    if (qpos == string::npos) throw runtime_error("No wildcard found");

    int wildcardWeight = receipt.length() - qpos;
    int partialValue = 0;
    int currentWeight = 1;

    for (int i = receipt.length() - 1; i >= 0; --i) {
        if (receipt[i] == '?') {
            currentWeight = receipt.length() - i;
            continue;
        }
        if (!isdigit(receipt[i])) throw runtime_error("Corrupted receipt");
        partialValue += (receipt[i] - '0') * currentWeight;
        ++currentWeight;
    }

    int requiredValue = balance - partialValue;
    if (requiredValue < 0) return "Lier!";

    if (requiredValue % wildcardWeight != 0) return "Lier!";

    int missingDigit = requiredValue / wildcardWeight;
    if (!isValidDigit(missingDigit)) return "Lier!";

    string tempReceipt = receipt;
    tempReceipt[qpos] = '0' + missingDigit;

    int recalculatedValue = 0;
    currentWeight = 1;
    for (int i = tempReceipt.length() - 1; i >= 0; --i) {
        recalculatedValue += (tempReceipt[i] - '0') * currentWeight;
        ++currentWeight;
    }

    if (recalculatedValue != balance) return "Lier!";

    return to_string(missingDigit);
}

int main() {
    try {
        string receipt, balanceStr;
        cin >> receipt >> balanceStr;

        if (receipt.empty() || balanceStr.empty()) {
            cout << "Lier!" << endl;
            return 0;
        }

        int balance = validateInput(balanceStr);
        bool hasWildcard = false;
        for (char c : receipt) {
            if (c == '?') hasWildcard = true;
        }

        if (!hasWildcard) {
            cout << "Lier!" << endl;
            return 0;
        }

        if (count(receipt.begin(), receipt.end(), '?') > 1) {
            cout << "Lier!" << endl;
            return 0;
        }

        string result = processReceipt(receipt, balance);
        if (result == "Lier!") {
            cout << "Lier!" << endl;
        } else {
            int digit = stoi(result);
            if (digit >= 0 && digit <= 9) {
                cout << digit << endl;
            } else {
                cout << "Lier!" << endl;
            }
        }
    } catch (...) {
        cout << "Lier!" << endl;
    }

    return 0;
}
