#include <string>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cctype>
#include <stdexcept>
using namespace std;

bool is_valid_char(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == ' ';
}

void validate_input(const string& s) {
    if (s.empty()) throw runtime_error("Empty input string");
    for (char c : s) {
        if (!is_valid_char(c)) {
            throw runtime_error("Invalid character in input");
        }
    }
}

string sanitize_string(string s) {
    string result;
    bool last_was_space = false;
    for (char c : s) {
        if (c == ' ') {
            if (!last_was_space) {
                result += c;
                last_was_space = true;
            }
        } else {
            result += c;
            last_was_space = false;
        }
    }
    if (!result.empty() && result.back() == ' ') {
        result.pop_back();
    }
    return result;
}

vector<string> tokenize_string(const string& s) {
    vector<string> tokens;
    string current;
    for (char c : s) {
        if (c == ' ') {
            if (!current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
        } else {
            current += c;
        }
    }
    if (!current.empty()) {
        tokens.push_back(current);
    }
    return tokens;
}

string find_longest_word(const vector<string>& words) {
    if (words.empty()) return "";
    string longest = words[0];
    for (const string& word : words) {
        if (word.size() > longest.size()) {
            longest = word;
        }
    }
    return longest;
}

int main() {
    try {
        string input;
        getline(cin, input);
        validate_input(input);
        string sanitized = sanitize_string(input);
        vector<string> words = tokenize_string(sanitized);
        if (words.empty()) {
            cerr << "No valid words found" << endl;
            return 1;
        }
        string longest = find_longest_word(words);
        if (longest.empty()) {
            cerr << "Unexpected empty longest word" << endl;
            return 1;
        }
        cout << longest << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
