using namespace std;

struct WordProcessingState {
    bool processed;
    string original;
    string transformed;
};

class SentenceProcessor {
private:
    vector<WordProcessingState> words;
    vector<string> tempStorage;
    string intermediateResult;

    void initializeProcessingStates(const vector<string>& tokens) {
        words.clear();
        for (const auto& token : tokens) {
            WordProcessingState state;
            state.processed = false;
            state.original = token;
            state.transformed = token;
            words.push_back(state);
        }
    }

    void performCaseConversion() {
        for (auto& word : words) {
            if (!word.processed) {
                string temp;
                for (char c : word.original) {
                    if (isupper(c) && c != 'I') {
                        temp += tolower(c);
                    } else {
                        temp += c;
                    }
                }
                word.transformed = temp;
            }
        }
    }

    void performPunctuationReplacement() {
        for (auto& word : words) {
            if (!word.processed) {
                string temp;
                for (char c : word.transformed) {
                    if (c == '?') {
                        temp += '!';
                    } else {
                        temp += c;
                    }
                }
                word.transformed = temp;
            }
        }
    }

    void applyRuleFour() {
        for (size_t i = 0; i < words.size(); ++i) {
            if (!words[i].processed) {
                string lowerTransformed;
                for (char c : words[i].transformed) {
                    lowerTransformed += tolower(c);
                }
                if (lowerTransformed == "i" || lowerTransformed == "me") {
                    words[i].transformed = "you";
                    words[i].processed = true;
                }
            }
        }
    }

    void applyRuleThree() {
        for (size_t i = 0; i + 1 < words.size(); ++i) {
            if (!words[i].processed && !words[i+1].processed) {
                string lowerCurrent;
                for (char c : words[i].transformed) {
                    lowerCurrent += tolower(c);
                }
                string lowerNext;
                for (char c : words[i+1].transformed) {
                    lowerNext += tolower(c);
                }
                if ((lowerCurrent == "can" || lowerCurrent == "could") && lowerNext == "you") {
                    words[i].transformed = "I";
                    words[i+1].transformed = (lowerCurrent == "can") ? "can" : "could";
                    words[i].processed = true;
                    words[i+1].processed = true;
                }
            }
        }
    }

    void buildFinalResult() {
        intermediateResult.clear();
        for (size_t i = 0; i < words.size(); ++i) {
            if (i != 0) {
                intermediateResult += " ";
            }
            intermediateResult += words[i].transformed;
        }
    }

public:
    string processSentence(const string& input) {
        istringstream iss(input);
        vector<string> tokens{istream_iterator<string>{iss}, istream_iterator<string>{}};

        initializeProcessingStates(tokens);
        performCaseConversion();
        performPunctuationReplacement();
        applyRuleFour();
        applyRuleThree();
        buildFinalResult();

        return intermediateResult;
    }
};

int main() {
