    if (s.find('(') == string::npos || s.find(')') == string::npos) {
        throw runtime_error("Invalid encryption format");
    }
}

void processCharacter(char c, DecryptionContext& ctx) {
    if (isdigit(c)) {
        if (ctx.multiplier != 0) {
            throw runtime_error("Nested multipliers not supported");
        }
        ctx.multiplier = c - '0';
    } else if (c == '(') {
        if (ctx.multiplier == 0) {
            throw runtime_error("Missing multiplier before parenthesis");
        }
        ctx.stack.emplace_back(ctx.current, ctx.multiplier);
        ctx.current.clear();
        ctx.multiplier = 0;
    } else if (c == ')') {
        if (ctx.stack.empty()) {
            throw runtime_error("Unmatched closing parenthesis");
        }
        auto [prev_str, mult] = ctx.stack.back();
        ctx.stack.pop_back();
        string expanded;
        for (int i = 0; i < mult; i++) {
            expanded += ctx.current;
        }
        ctx.current = prev_str + expanded;
        ctx.multiplier = 0;
    } else {
        if (ctx.multiplier != 0 && !ctx.stack.empty()) {
            throw runtime_error("Invalid character between multiplier and parenthesis");
        }
        ctx.current += c;
    }
