struct DecryptionContext {
    string current_string;
    size_t current_position;
    bool is_valid;
    int recursion_depth;
};

string multiply_string(const string& str, int multiplier) {
    if (multiplier <= 0 || str.empty()) {
        return "";
    }
    string result;
    for (int i = 0; i < multiplier; ++i) {
        result += str;
    }
    return result;
}

void validate_input_string(const string& s, DecryptionContext& context) {
    context.is_valid = true;
    stack<char> paren_stack;
    for (char c : s) {
        if (c == '(') {
            paren_stack.push(c);
        } else if (c == ')') {
            if (paren_stack.empty()) {
                context.is_valid = false;
                return;
            }
            paren_stack.pop();
        }
    }
    context.is_valid = paren_stack.empty();
}

string decrypt_segment(DecryptionContext& context, const string& s) {
    if (context.current_position >= s.length() || !context.is_valid) {
        return "";
    }

    if (isdigit(s[context.current_position])) {
        int multiplier = s[context.current_position] - '0';
        if (multiplier < 1 || multiplier > 9) {
            context.is_valid = false;
            return "";
        }

        context.current_position += 1;
        if (context.current_position >= s.length() || s[context.current_position] != '(') {
            context.is_valid = false;
            return "";
        }

        context.current_position += 1;
        string segment_result;
        while (context.current_position < s.length() && s[context.current_position] != ')') {
            if (isdigit(s[context.current_position])) {
                context.recursion_depth += 1;
                if (context.recursion_depth > 100) {
                    context.is_valid = false;
                    return "";
                }
                segment_result += decrypt_segment(context, s);
            } else {
                segment_result += s[context.current_position];
                context.current_position += 1;
            }
        }

        if (context.current_position >= s.length() || s[context.current_position] != ')') {
            context.is_valid = false;
            return "";
        }

        context.current_position += 1;
        return multiply_string(segment_result, multiplier);
    } else {
        string single_char;
        single_char += s[context.current_position];
        context.current_position += 1;
        return single_char;
    }
}

string decrypt_string(const string& s) {
    DecryptionContext context;
    context.current_string = "";
    context.current_position = 0;
    context.is_valid = true;
    context.recursion_depth = 0;

    validate_input_string(s, context);
    if (!context.is_valid) {
        return "";
    }

    while (context.current_position < s.length() && context.is_valid) {
        context.current_string += decrypt_segment(context, s);
    }

    if (!context.is_valid) {
        return "";
    }

    return context.current_string;
}

