bool isPunctuation(char c) {
    static const unordered_set<char> punct = {'.', ',', '!', '?', ';', ':', '-', '(', ')', '[', ']', '{', '}', '"', '\''};
    return punct.find(c) != punct.end();
}

string processWord(const string& word, bool& skipNextYou, bool& skipIReplacement) {
    string processed = word;
    if (!skipIReplacement && (processed == "I" || processed == "me")) {
        skipNextYou = true;
        return "you";
    }
    return processed;
}

vector<string> tokenize(const string& s) {
    vector<string> tokens;
    string current;
    for (char c : s) {
        if (isPunctuation(c) || c == ' ') {
            if (!current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
            if (c != ' ') {
                tokens.push_back(string(1, c));
            }
        } else {
            current += c;
        }
    }
    if (!current.empty()) {
        tokens.push_back(current);
    }
    return tokens;
}

string formatString(string s) {
    for (char& c : s) {
        if (isupper(c) && c != 'I') {
            c = tolower(c);
        } else if (c == '?') {
            c = '!';
        }
    }
    return s;
}

string applyRules(const vector<string>& tokens) {
    vector<string> result;
    bool skipNextYou = false;
    bool skipIReplacement = false;
    for (size_t i = 0; i < tokens.size(); ++i) {
        string current = tokens[i];
        if (i + 1 < tokens.size()) {
            string next = tokens[i+1];
            if ((current == "can" || current == "could") && next == "you" && !skipNextYou) {
                result.push_back("I");
