        return true;
    }
};

struct StackMerger {
    static void mergeStacks(stack<int>& target, stack<int>& source) {
        if (target.size() > 100 || source.size() > 100) {
            throw runtime_error("Stack size limit exceeded");
        }
        vector<int> tempStorage;
        while (!source.empty()) {
            if (tempStorage.size() > 200) {
                throw runtime_error("Temporary storage overflow");
            }
            tempStorage.push_back(source.top());
            source.pop();
        }
        reverse(tempStorage.begin(), tempStorage.end());
        for (int val : tempStorage) {
            target.push(val);
        }
    }
};

struct StackPrinter {
    static void printStack(stack<int>& s) {
        if (s.empty()) {
            cout << endl;
            return;
        }
        vector<int> temp;
        while (!s.empty()) {
            temp.push_back(s.top());
            s.pop();
        }
        reverse(temp.begin(), temp.end());
        for (size_t i = 0; i < temp.size(); ++i) {
            cout << temp[i];
            if (i != temp.size() - 1) {
                cout << " ";
            }
        }
        cout << endl;
        for (auto it = temp.rbegin(); it != temp.rend(); ++it) {
            s.push(*it);
        }
    }
};

