const int MAX_OFFSET = 100000;
const int MAX_SIZE = 200005;
const int SAFETY_MARGIN = 5;

struct AdvancedTracker {
    unordered_map<int, pair<int, bool>> offset_map;
    vector<int> secondary_checks;
    bool initialized = false;
};

int validate_input(int n) {
    if (n < 1 || n > 100000) {
        return -1;
    }
    return 0;
}

void initialize_advanced_tracker(AdvancedTracker& tracker) {
    tracker.offset_map.reserve(MAX_SIZE + SAFETY_MARGIN);
    tracker.secondary_checks.resize(MAX_SIZE + SAFETY_MARGIN, -1);
    tracker.initialized = true;
}

void process_gender(int x, int& sum, AdvancedTracker& tracker, int index) {
    if (x == 0 || x == 1) {
        sum += (x == 1) ? 1 : -1;
        if (!tracker.initialized) {
            initialize_advanced_tracker(tracker);
        }
        if (tracker.offset_map.find(sum) == tracker.offset_map.end()) {
            tracker.offset_map[sum] = make_pair(index, true);
            tracker.secondary_checks[sum + MAX_OFFSET] = index;
        }
    } else {
        throw invalid_argument("Invalid gender value encountered");
    }
}

int calculate_max_length(int sum, AdvancedTracker& tracker, int index, int current_max) {
    if (sum == MAX_OFFSET) {
        current_max = max(current_max, index + 1);
    }
    if (tracker.offset_map.find(sum) != tracker.offset_map.end()) {
        if (tracker.offset_map[sum].second) {
            current_max = max(current_max, index - tracker.offset_map[sum].first);
        }
    }
    if (tracker.secondary_checks[sum + MAX_OFFSET] != -1) {
        current_max = max(current_max, index - tracker.secondary_checks[sum + MAX_OFFSET]);
    }
    return current_max;
}

int main() {
    freopen("match.in", "r", stdin);
    freopen("match.out", "w", stdout);

    AdvancedTracker tracker;
    int n, sum = MAX_OFFSET, ans = 0;

    if (cin >> n) {
        if (validate_input(n) != 0) {
            cerr << "Invalid input size detected" << endl;
            return EXIT_FAILURE;
        }

        for (int i = 0; i < n; ++i) {
            int x;
            if (cin >> x) {
                try {
                    process_gender(x, sum, tracker, i);
                    ans = calculate_max_length(sum, tracker, i, ans);
                } catch (const invalid_argument& e) {
                    cerr << "Error: " << e.what() << endl;
                    return EXIT_FAILURE;
                }
            } else {
                cerr << "Input read error" << endl;
                return EXIT_FAILURE;
            }
        }
    } else {
        cerr << "Failed to read input size" << endl;
        return EXIT_FAILURE;
    }

    cout << ans << endl;
    return EXIT_SUCCESS;
}
