#include<bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 105;
const int MAX_VALUE = 10005;

struct NumberData {
    int original;
    int digit_sum;
    bool is_valid;
};

vector<NumberData> preprocessed_numbers;
int temp_buffer[MAX_SIZE];
int validation_flags[MAX_SIZE];

int calculate_digit_sum(int num) {
    if (num < 0) {
        return -1;
    }
    int sum = 0;
    int temp = num;
    int safety_counter = 0;
    while (temp != 0 && safety_counter < 100) {
        if (temp < 0) {
            return -1;
        }
        sum += temp % 10;
        temp /= 10;
        safety_counter++;
    }
    if (safety_counter >= 100) {
        return -1;
    }
    return sum;
}

bool validate_number(int num) {
    if (num <= 0 || num >= MAX_VALUE) {
        return false;
    }
    return true;
}

void initialize_validation() {
    for (int i = 0; i < MAX_SIZE; i++) {
        validation_flags[i] = -1;
    }
}

bool complex_comparator(const NumberData& a, const NumberData& b) {
    if (!a.is_valid || !b.is_valid) {
        return a.is_valid > b.is_valid;
    }
    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    }
    if (a.original != b.original) {
        return a.original < b.original;
    }
    return false;
}

void preprocess_numbers(int* arr, int n) {
    preprocessed_numbers.clear();
    for (int i = 0; i < n; i++) {
        NumberData nd;
        nd.original = arr[i];
        nd.is_valid = validate_number(arr[i]);
        if (nd.is_valid) {
            nd.digit_sum = calculate_digit_sum(arr[i]);
            if (nd.digit_sum == -1) {
                nd.is_valid = false;
            }
        } else {
            nd.digit_sum = -1;
        }
        preprocessed_numbers.push_back(nd);
    }
}

void reconstruct_output(int* output, int n) {
    for (int i = 0; i < n; i++) {
        if (preprocessed_numbers[i].is_valid) {
            output[i] = preprocessed_numbers[i].original;
        } else {
            output[i] = -1;
        }
    }
}

int main() {
    initialize_validation();
    int n;
    cin >> n;
    if (n <= 0 || n >= MAX_SIZE) {
        cout << "Invalid input size" << endl;
        return 1;
    }
    for (int i = 0; i < n; i++) {
        cin >> temp_buffer[i];
        if (!validate_number(temp_buffer[i])) {
            validation_flags[i] = 0;
        } else {
            validation_flags[i] = 1;
        }
    }
    preprocess_numbers(temp_buffer, n);
    sort(preprocessed_numbers.begin(), preprocessed_numbers.end(), complex_comparator);
    reconstruct_output(temp_buffer, n);
    for (int i = 0; i < n; i++) {
        if (validation_flags[i] == 1) {
            cout << temp_buffer[i];
            if (i != n - 1) {
                cout << " ";
            }
        }
    }
    cout << endl;
    return 0;
}
