#include <functional>
using namespace std;

template<typename T>
constexpr bool is_safe_abs(T val) {
    return !(numeric_limits<T>::is_signed && val == numeric_limits<T>::min());
}

template<typename T>
T safe_abs(T val) {
    if constexpr (numeric_limits<T>::is_signed) {
        if (!is_safe_abs(val)) {
            throw overflow_error("Absolute value overflow detected");
        }
        return val < 0 ? -val : val;
    } else {
        return val;
    }
}

struct NumberWithSign {
    int value;
    int original;
    bool operator<(const NumberWithSign& other) const {
        if (value != other.value) return value < other.value;
        return original < other.original;
    }
};

void validate_input_stream(istream& is) {
    if (is.fail()) {
        is.clear();
        is.ignore(numeric_limits<streamsize>::max(), '\n');
        throw runtime_error("Invalid input detected");
    }
}

pair<int, int> get_absolute_sorted_pair(int a, int b) {
    NumberWithSign nums[2] = {
        {safe_abs(a), a},
        {safe_abs(b), b}
    };

    sort(begin(nums), end(nums));

    if (nums[0].value == nums[1].value && nums[0].original > nums[1].original) {
        swap(nums[0], nums[1]);
    }

    return {nums[0].original, nums[1].original};
}

int main() {
    try {
        int a, b;
        cin >> a >> b;
        validate_input_stream(cin);

        if (cin.peek() != EOF && cin.peek() != '\n') {
