    const long long MAX_ITERATIONS = 1000000;
    const long long MAX_POSITION = numeric_limits<long long>::max() / 6;

    bool isPositionValid(long long pos) {
        return pos > 0 && pos <= MAX_POSITION;
    }

    void validateInput(long long n) {
        if (n < 1) {
            throw invalid_argument("Initial position must be positive");
        }
        if (!isPositionValid(n)) {
            throw overflow_error("Initial position exceeds maximum allowed value");
        }
    }

    long long calculateNextPosition(long long current, bool& shouldTerminate) {
        shouldTerminate = false;
        if (!isPositionValid(current)) {
            shouldTerminate = true;
            return current;
        }
        if (current % 2 == 0) {
            if (current / 2 > MAX_POSITION) {
                shouldTerminate = true;
                return current;
            }
            return current / 2;
        } else {
            if (3 * current + 3 > MAX_POSITION) {
                shouldTerminate = true;
                return current;
            }
            return 6 * ((current - 1) / 2) + 6;
        }
    }
}

