bool isTripleCharSequence(const string& s, size_t pos, char c) {
    if (pos + 2 >= s.length()) return false;
    return s[pos] == c && s[pos+1] == c && s[pos+2] == c;
}

char handleAlphabetRotation(char c, bool reverse) {
    int direction = reverse ? -1 : 1;
    int offset = direction * ROTATION_OFFSET;

    if (isdigit(c)) {
        int numeric_value = c - '0';
        int rotated_value = (numeric_value + offset + DIGIT_RANGE) % DIGIT_RANGE;
        return '0' + rotated_value;
