#include<bits/stdc++.h>
using namespace std;

const string SPECIAL_KKK = "kkk";
const string SPECIAL_SSS = "sss";
const int ROTATION_OFFSET = 3;
const int ALPHABET_SIZE = 26;
const int DIGIT_COUNT = 10;

bool isTripleCharSequence(const string& s, size_t pos, char c) {
    return (pos + 2 < s.size()) && 
           (s[pos] == c) && 
           (s[pos+1] == c) && 
           (s[pos+2] == c);
}

char rotateCharacterBackward(char c, int offset) {
    if (isdigit(c)) {
        int num = c - '0';
        num = (num - offset + DIGIT_COUNT) % DIGIT_COUNT;
        return '0' + num;
    } else if (islower(c)) {
        int alphaPos = c - 'a';
        alphaPos = (alphaPos - offset + ALPHABET_SIZE) % ALPHABET_SIZE;
        return 'a' + alphaPos;
    }
    return c;
}

void validateInputString(const string& s) {
    for (size_t i = 0; i < s.size(); ) {
        if (isTripleCharSequence(s, i, 'k')) {
            if (s.substr(i, 3) != SPECIAL_KKK) {
                throw runtime_error("Invalid triple k sequence");
            }
            i += 3;
        } else if (isTripleCharSequence(s, i, 's')) {
            if (s.substr(i, 3) != SPECIAL_SSS) {
                throw runtime_error("Invalid triple s sequence");
            }
            i += 3;
        } else if (!isdigit(s[i]) && !islower(s[i])) {
            throw runtime_error("Invalid character in input");
        } else {
            i++;
        }
    }
}

string processEncryptedMessage(const string& encrypted) {
    string decrypted;
    decrypted.reserve(encrypted.size());

    for (size_t i = 0; i < encrypted.size(); ) {
        try {
            if (isTripleCharSequence(encrypted, i, 'k')) {
                decrypted += ' ';
                i += 3;
            } else if (isTripleCharSequence(encrypted, i, 's')) {
                decrypted += '.';
                i += 3;
            } else {
                char rotated = rotateCharacterBackward(encrypted[i], ROTATION_OFFSET);
                decrypted += rotated;
                i++;
            }
        } catch (const exception& e) {
            cerr << "Error processing character at position " << i << ": " << e.what() << endl;
            decrypted += '?';
            i++;
        }
    }

    return decrypted;
}

