char decryptChar(char c, const string& circularSeq) {
    if (c == ' ' || c == '.') return c;
    size_t pos = circularSeq.find(c);
    if (pos == string::npos) return c;
    pos = (pos - SHIFT_VALUE + circularSeq.size()) % circularSeq.size();
    return circularSeq[pos];
}

