    const long long MAX_POSITION = numeric_limits<long long>::max();
    const long long MIN_POSITION = numeric_limits<long long>::min();

    void validate_position(long long pos) {
        if (pos < MIN_POSITION || pos > MAX_POSITION) {
            throw out_of_range("Position value out of valid range");
        }
