        long long new_pos = pos / 2;
        validate_position(new_pos);
        if (visited_positions.find(new_pos) != visited_positions.end()) {
            termination_condition_met = true;
            path_history.push_back(new_pos);
            return;
        }
        visited_positions[pos] = true;
        path_history.push_back(pos);
        process_position(new_pos);
    }

    void handle_odd_position(long long pos) {
        long long new_pos = (pos - 1) * 3 + 6;
        validate_position(new_pos);
        if (visited_positions.find(new_pos) != visited_positions.end()) {
            termination_condition_met = true;
            path_history.push_back(new_pos);
            return;
