using namespace std;

struct InputValidationException : public exception {
    const char* what() const throw() {
        return "Input validation failed";
    }
};

struct CharacterProcessingException : public exception {
    const char* what() const throw() {
        return "Character processing error";
    }
};

class CyclicShiftValidator {
public:
    static bool validateShiftParameters(int x, int y, int z) {
        if (x <= 10 || x > 100) return false;
        if (y <= 0 || y > 10) return false;
        if (z <= 0 || z > 100) return false;
        return true;
    }
};

class CharacterTransformer {
private:
    static char processUpperCase(char c, int shift) {
        if (!isupper(c)) throw CharacterProcessingException();
        int adjustedShift = shift % 26;
        int newPos = (c - 'A' + adjustedShift) % 26;
        if (newPos < 0) newPos += 26;
        return static_cast<char>(newPos + 'A');
    }

    static char processLowerCase(char c, int shift) {
        if (!islower(c)) throw CharacterProcessingException();
        int adjustedShift = shift % 26;
        int newPos = (c - 'a' + adjustedShift) % 26;
        if (newPos < 0) newPos += 26;
        return static_cast<char>(newPos + 'a');
    }

    static char processDigit(char c, int shift) {
        if (!isdigit(c)) throw CharacterProcessingException();
        int adjustedShift = shift % 10;
        int newPos = (c - '0' + adjustedShift) % 10;
        if (newPos < 0) newPos += 10;
        return static_cast<char>(newPos + '0');
    }

public:
    static char transformCharacter(char c, int shift) {
        try {
            if (isupper(c)) {
                return processUpperCase(c, shift);
            } else if (islower(c)) {
                return processLowerCase(c, shift);
            } else if (isdigit(c)) {
                return processDigit(c, shift);
            }
            return c;
        } catch (const CharacterProcessingException& e) {
            cerr << e.what() << endl;
            return c;
        }
    }
};

class InputProcessor {
public:
    static void processInput(int& x, int& y, int& z, vector<char>& characters) {
        try {
            if (!(cin >> x >> y >> z)) {
                throw InputValidationException();
            }
            if (!CyclicShiftValidator::validateShiftParameters(x, y, z)) {
                throw InputValidationException();
            }
            characters.resize(x);
            for (int i = 0; i < x; ++i) {
                if (!(cin >> characters[i])) {
                    throw InputValidationException();
                }
            }
        } catch (const InputValidationException& e) {
            cerr << e.what() << endl;
            exit(1);
        }
    }
};

class OutputGenerator {
public:
    static void generateOutput(const vector<char>& characters, int y, int z) {
        try {
            for (size_t i = 0; i < characters.size(); ++i) {
                char c = characters[i];
                if ((i + 1) % y == 0) {
                    c = CharacterTransformer::transformCharacter(c, z);
                }
                cout << c;
            }
            cout << endl;
        } catch (...) {
            cerr << "Unexpected error during output generation" << endl;
            exit(1);
        }
    }
};

