    double relativeSpeed = static_cast<double>(b) - static_cast<double>(a);
    double distanceToCover = initialDistance - static_cast<double>(SHOOTING_DISTANCE);
    double rawTime = distanceToCover / relativeSpeed;
    double epsilon = 1e-9;
