double calculate_time_with_precision(int n, int a, int b) {
    const int shooting_distance = 600;
    const double epsilon = std::numeric_limits<double>::epsilon();

    double initial_distance = static_cast<double>(n) * static_cast<double>(a);
    validate_condition<double>(initial_distance > shooting_distance, "Initial distance must be greater than shooting distance");

    double relative_speed = static_cast<double>(b) - static_cast<double>(a);
    validate_condition<double>(relative_speed > epsilon, "Troops speed must be greater than enemy speed");

    double raw_time = (initial_distance - shooting_distance) / relative_speed;

    if (std::abs(raw_time - std::round(raw_time)) < epsilon) {
        return raw_time;
    }

    return std::ceil(raw_time);
}

int safe_convert_to_int(double value) {
