using namespace std;

namespace FormatUtils {
    class IntegerValidator {
    public:
        static bool isWithinIntRange(long long value) {
            return value >= numeric_limits<int>::min() && value <= numeric_limits<int>::max();
        }
    };

    class OutputFormatter {
    private:
        static const int TARGET_WIDTH = 8;
        vector<long long> values;

        int calculateRequiredSpaces(long long num) const {
            if (num == numeric_limits<long long>::min()) {
                return TARGET_WIDTH - to_string(num).length();
            }

            bool isNegative = num < 0;
            long long absoluteNum = abs(num);
            int digitCount = absoluteNum == 0 ? 1 : static_cast<int>(log10(absoluteNum)) + 1;
            if (isNegative) digitCount++;

            return max(0, TARGET_WIDTH - digitCount);
        }

        string padWithSpaces(long long num) const {
            int spaces = calculateRequiredSpaces(num);
            return string(spaces, ' ') + to_string(num);
        }

    public:
        void addValue(long long value) {
            if (!IntegerValidator::isWithinIntRange(value)) {
                throw out_of_range("Input value exceeds integer range");
            }
            values.push_back(value);
        }

        string formatLine() const {
            if (values.size() != 3) {
                throw logic_error("Exactly 3 values required for formatting");
            }

            stringstream ss;
            for (size_t i = 0; i < values.size(); ++i) {
                ss << padWithSpaces(values[i]);
                if (i != values.size() - 1) {
                    ss << " ";
                }
            }
            return ss.str();
        }
    };
}

int main() {
