                long long value = stoll(token, &pos);

                if (pos != token.length()) {
                    throw invalid_argument("Invalid characters in input");
                }

                if (!FormatUtils::IntegerValidator::isWithinIntRange(value)) {
                    throw out_of_range("Input value exceeds integer range");
                }

                formatter.addValue(value);
                valueCount++;
            } catch (const invalid_argument& e) {
                cerr << "Error: Invalid input format - " << e.what() << endl;
                return 1;
            } catch (const out_of_range& e) {
                cerr << "Error: " << e.what() << endl;
                return 1;
