    T exact_time = static_cast<double>(relative_distance) / speed_difference;
    T rounded_time = static_cast<T>(std::ceil(exact_time));
    if (rounded_time < 0) {
        throw std::logic_error("Time cannot be negative");
    }
    return rounded_time;
}

