using namespace std;

template<typename T>
struct DigitSumValidator {
    static_assert(is_integral<T>::value, "DigitSumValidator requires integral type");

    static T calculate(T value) {
        if (value < 0) {
            throw invalid_argument("Negative values not supported for digit sum calculation");
        }

        T sum = 0;
        T original = value;
        while (value != 0) {
            T digit = value % 10;
            if (digit < 0 || digit > 9) {
                throw logic_error("Invalid digit encountered during sum calculation");
            }
            sum += digit;
            value /= 10;

            if (sum > numeric_limits<T>::max() - 9) {
                throw overflow_error("Digit sum overflow detected");
            }
        }

        if (original != 0 && sum == 0) {
            throw runtime_error("Unexpected zero sum for non-zero value");
        }

        return sum;
    }
};

class InputSanitizer {
public:
    static int safeStoi(const string& str) {
        if (str.empty()) {
            throw invalid_argument("Empty string cannot be converted to integer");
        }

        for (char c : str) {
            if (!isdigit(c)) {
                throw invalid_argument("Non-digit character in input");
            }
        }

        try {
            int val = stoi(str);
            if (val <= 0 || val >= 101) {
                throw out_of_range("N is out of valid range");
            }
            return val;
        } catch (const out_of_range&) {
            throw out_of_range("Input value too large for integer type");
        }
    }
};

struct SortingComparator {
    bool operator()(int x, int y) const {
        try {
            int sum_x = DigitSumValidator<int>::calculate(x);
            int sum_y = DigitSumValidator<int>::calculate(y);

            if (sum_x == sum_y) {
                if (x == y) {
                    return false;
                }
                return x < y;
            }

            return sum_x < sum_y;
        } catch (const exception& e) {
            cerr << "Error during comparison: " << e.what() << endl;
            return false;
        }
    }
};

vector<int> parseInputNumbers(const string& input, int expectedCount) {
    vector<int> numbers;
    istringstream iss(input);
    string token;
    int parsedCount = 0;

    while (iss >> token) {
        try {
            int num = stoi(token);
            if (num <= 0 || num >= 10000) {
                throw out_of_range("Number out of valid range");
            }
            numbers.push_back(num);
            parsedCount++;
            if (parsedCount > expectedCount) {
                throw logic_error("More numbers provided than specified");
            }
        } catch (const invalid_argument&) {
            throw invalid_argument("Invalid number format in input");
        } catch (const out_of_range&) {
            throw out_of_range("Number value out of range");
        }
    }

    if (parsedCount != expectedCount) {
        throw logic_error("Number count mismatch");
    }

    return numbers;
}

int main() {
    try {
        string line;
        int n;

        if (!getline(cin, line)) {
            throw runtime_error("Failed to read N");
        }

        n = InputSanitizer::safeStoi(line);

        if (!getline(cin, line)) {
            throw runtime_error("Failed to read numbers");
        }

        vector<int> numbers = parseInputNumbers(line, n);

        if (numbers.size() != static_cast<size_t>(n)) {
            throw logic_error("Input size mismatch");
        }

        sort(numbers.begin(), numbers.end(), SortingComparator());

        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i != 0) {
