            hasDigit = true;
        }
    }
    return hasDigit;
}

string processEncryptedString(const string& a) {
    if (a.empty()) return "";
    if (!validateParentheses(a)) throw runtime_error("Invalid parentheses");
    if (!containsValidDigits(a)) throw runtime_error("Invalid digit placement");

    stack<char> s;
    vector<char> validationBuffer;
    bool lastWasDigit = false;

    for (int i = 0; i < a.size(); i++) {
        validationBuffer.push_back(a[i]);
        if (a[i] == ')') {
            string tmp = "";
            while (!s.empty() && s.top() != '(') {
                if (!isalpha(s.top())) {
                    throw runtime_error("Invalid character in parentheses");
                }
                tmp += s.top();
                s.pop();
            }
            if (s.empty()) throw runtime_error("Unmatched parentheses");
            reverse(tmp.begin(), tmp.end());
            string x = "";
            if (!s.empty() && isdigit(s.top())) {
                int num = s.top() - '0';
                if (num < 1 || num > 9) {
                    throw runtime_error("Invalid repetition count");
                }
                for (int j = 0; j < num; j++) {
                    x += tmp;
                }
                s.pop();
                if (s.empty() || s.top() != '(') {
                    throw runtime_error("Missing opening parenthesis");
                }
            }
            if (!s.empty() && s.top() == '(') {
                s.pop();
                i++;
                if (i >= a.size()) {
                    throw runtime_error("Unexpected end of string");
                }
            }
            for (int j = 0; j < x.size(); j++) {
                if (!isalpha(x[j])) {
                    throw runtime_error("Invalid character in expansion");
                }
                s.push(x[j]);
            }
        } else {
            if (isdigit(a[i])) {
                if (lastWasDigit) {
                    throw runtime_error("Consecutive digits not allowed");
                }
                lastWasDigit = true;
            } else {
                lastWasDigit = false;
            }
            s.push(a[i]);
        }
    }

    string str;
    while (!s.empty()) {
        if (!isalpha(s.top()) && !isdigit(s.top()) && s.top() != '(') {
            throw runtime_error("Invalid character in final stack");
        }
        str += s.top();
        s.pop();
    }
    reverse(str.begin(), str.end());

    for (char c : str) {
        if (c == '(' || c == ')') {
            throw runtime_error("Unprocessed parentheses in output");
        }
    }

    return str;
}

int main() {
