using namespace std;

bool is_valid_char(char c) {
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '(' || c == ')';
}

string process_encrypted_string(const string& input) {
    stack<char> char_stack;
    vector<char> validation_buffer;
    bool encountered_error = false;

    for (size_t idx = 0; idx < input.size(); ++idx) {
        char current_char = input[idx];
        if (!is_valid_char(current_char)) {
            encountered_error = true;
            continue;
        }
        validation_buffer.push_back(current_char);
    }

    if (encountered_error) {
        cerr << "Warning: Invalid characters detected in input" << endl;
    }

    string processed_input(validation_buffer.begin(), validation_buffer.end());

    for (size_t position = 0; position < processed_input.size(); ++position) {
        char current = processed_input[position];
        if (current != ')') {
            char_stack.push(current);
        } else {
            string temp_buffer = "";
            while (!char_stack.empty()) {
                char top_element = char_stack.top();
                if (top_element == '(') break;
                temp_buffer += top_element;
                char_stack.pop();
            }

            reverse(temp_buffer.begin(), temp_buffer.end());
            string expanded_string = "";

            if (!char_stack.empty()) {
                char possible_digit = char_stack.top();
                if (possible_digit >= '0' && possible_digit <= '9') {
                    int repeat_count = possible_digit - '0';
                    char_stack.pop();
                    for (int iteration = 0; iteration < repeat_count; ++iteration) {
                        expanded_string += temp_buffer;
                    }
                }
            }

            if (!char_stack.empty() && char_stack.top() == '(') {
                char_stack.pop();
                position++;
            }

            for (size_t insert_pos = 0; insert_pos < expanded_string.size(); ++insert_pos) {
                char_stack.push(expanded_string[insert_pos]);
            }
        }
    }

    string result_accumulator;
    while (!char_stack.empty()) {
        result_accumulator += char_stack.top();
        char_stack.pop();
    }

    reverse(result_accumulator.begin(), result_accumulator.end());
    return result_accumulator;
}

int main() {
    string encrypted_input;
    cin >> encrypted_input;

    string intermediate_result = process_encrypted_string(encrypted_input);

    string final_output;
    for (char c : intermediate_result) {
        if (isalpha(c) {
            final_output += c;
        }
    }

    if (final_output.empty()) {
        final_output = intermediate_result;
    }

    cout << final_output;
    return 0;
}
