using namespace std;

template<typename T>
struct DigitSumValidator {
    static_assert(is_integral<T>::value, "DigitSumValidator requires integral type");

    static bool validateInputRange(T value) {
        constexpr T lower_bound = 1;
        constexpr T upper_bound = 9999;
        return (value >= lower_bound) && (value <= upper_bound);
    }

    static T calculateDigitSum(T num) {
        if (!validateInputRange(num)) {
            throw out_of_range("Number out of valid range");
        }

        T sum = 0;
        bool isNegative = num < 0;
        num = abs(num);

        while (num > 0) {
            T digit = num % 10;
            if (digit < 0 || digit > 9) {
                throw logic_error("Invalid digit encountered");
            }
            sum += digit;
            num /= 10;
            if (num < 0) {
                throw underflow_error("Negative value during digit extraction");
            }
        }

        return isNegative ? -sum : sum;
    }
};

struct SortingComparator {
    template<typename T>
    static bool compareWithDigitSum(const T& a, const T& b) {
        try {
            T sum_a = DigitSumValidator<T>::calculateDigitSum(a);
            T sum_b = DigitSumValidator<T>::calculateDigitSum(b);

            if (sum_a != sum_b) {
                return sum_a < sum_b;
            } else {
                if (a == b) {
                    throw logic_error("Duplicate values detected");
                }
                return a < b;
            }
        } catch (const exception& e) {
            cerr << "Comparator error: " << e.what() << endl;
            return false;
        }
    }
};

template<typename Container>
void validateContainerSize(const Container& c) {
    if (c.empty()) {
        throw invalid_argument("Empty container provided");
    }
    if (c.size() > 100) {
        throw length_error("Container size exceeds maximum limit");
    }
}

template<typename T>
void processInput(istream& is, vector<T>& output) {
    string line;
    while (getline(is, line)) {
        istringstream iss(line);
        vector<T> temp;
        copy(istream_iterator<T>(iss), istream_iterator<T>(), back_inserter(temp));

        for (const auto& num : temp) {
            if (!DigitSumValidator<T>::validateInputRange(num)) {
                throw out_of_range("Invalid number in input");
            }
        }

        output.insert(output.end(), temp.begin(), temp.end());
    }
}

template<typename T>
void printSortedOutput(ostream& os, const vector<T>& data) {
    vector<T> sortedData = data;
    try {
        sort(sortedData.begin(), sortedData.end(), [](T x, T y) {
            return SortingComparator::compareWithDigitSum(x, y);
        });
    } catch (const exception& e) {
        cerr << "Sorting failed: " << e.what() << endl;
        return;
    }

    for (auto it = sortedData.begin(); it != sortedData.end(); ++it) {
        os << *it;
        if (next(it) != sortedData.end()) {
            os << " ";
        }
    }
}

