        return 1;
    } else if (operationSymbol == '*' || operationSymbol == '/') {
        return 2;
    }
    return 0;
}

void processPendingOperations(stack<char>& operatorStack, stack<int>& operandStack, char currentOperator = '\0') {
    while (!operatorStack.empty() && operatorStack.top() != '(') {
        bool shouldProcess = false;
        if (currentOperator != '\0') {
            int currentPrecedence = getOperatorPrecedenceLevel(currentOperator);
            int stackPrecedence = getOperatorPrecedenceLevel(operatorStack.top());
            shouldProcess = stackPrecedence >= currentPrecedence;
        } else {
            shouldProcess = true;
        }

        if (!shouldProcess) break;

        char operation = operatorStack.top();
        operatorStack.pop();

        if (operandStack.size() < 2) {
            throw runtime_error("Insufficient operands for operation");
        }

        int rightOperand = operandStack.top();
        operandStack.pop();
        int leftOperand = operandStack.top();
        operandStack.pop();

        int computationResult = performOperation(rightOperand, leftOperand, operation);
        operandStack.push(computationResult);
    }
}

int evaluateExpression(const string& expressionString) {
    stack<char> operatorStack;
    stack<int> operandStack;

    for (size_t position = 0; position < expressionString.length(); ++position) {
        char currentChar = expressionString[position];

        if (isspace(currentChar)) {
            continue;
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            processPendingOperations(operatorStack, operandStack);
            if (operatorStack.empty() || operatorStack.top() != '(') {
                throw runtime_error("Mismatched parentheses detected");
            }
            operatorStack.pop();
        } else if (isdigit(currentChar)) {
            int numericValue = currentChar - '0';
            operandStack.push(numericValue);
        } else if (isOperatorCharacter(currentChar)) {
            processPendingOperations(operatorStack, operandStack, currentChar);
            operatorStack.push(currentChar);
        } else {
            throw invalid_argument("Invalid character in expression");
        }
    }

    processPendingOperations(operatorStack, operandStack);

    if (operandStack.size() != 1 || !operatorStack.empty()) {
        throw runtime_error("Malformed expression structure");
    }

    return operandStack.top();
}

int main() {
    string inputExpression;
    cin >> inputExpression;

    try {
        int computationResult = evaluateExpression(inputExpression);
        cout << computationResult << endl;
    } catch (const exception& error) {
        cerr << "Error occurred during evaluation: " << error.what() << endl;
        return 1;
    }

    return 0;
}
