using namespace std;

int cal(int x, int y, char o) {
    if (o == '+') {
        if (x > 1000000 || y > 1000000 || x < -1000000 || y < -1000000) {
            throw runtime_error("Potential overflow detected");
        }
        return x + y;
    }
    if (o == '-') {
        if (y == INT_MIN && x == 1) {
            throw runtime_error("Potential underflow detected");
        }
        return y - x;
    }
    if (o == '*') {
        if ((x > 0 && y > 0 && x > INT_MAX / y) || 
            (x > 0 && y < 0 && y < INT_MIN / x) ||
            (x < 0 && y > 0 && x < INT_MIN / y) ||
            (x < 0 && y < 0 && y < INT_MAX / x)) {
            throw runtime_error("Multiplication overflow");
        }
        return x * y;
    }
    if (o == '/') {
        if (x == 0) {
            throw runtime_error("Division by zero");
        }
        if (y == INT_MIN && x == -1) {
            throw runtime_error("Division overflow");
        }
        return y / x;
    }
    throw runtime_error("Unknown operator");
}

bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '(' || c == ')';
}

int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

void processOperation(stack<char>& op, stack<int>& num) {
    if (op.empty() || num.size() < 2) {
        throw runtime_error("Invalid expression structure");
    }
    char operation = op.top();
    op.pop();
    int x = num.top();
    num.pop();
    int y = num.top();
    num.pop();
    if ((operation == '/' || operation == '*') && (x == 0 || y == 0)) {
        throw runtime_error("Potential division by zero during operation processing");
    }
    num.push(cal(x, y, operation));
}

int main() {
    string s;
    cin >> s;
    if (s.empty()) {
        cout << 0 << endl;
        return 0;
    }
    stack<char> op;
    stack<int> num;
    bool expectNumber = true;
    for (int i = 0; i < s.size(); i++) {
        if (isspace(s[i])) continue;
        if (isdigit(s[i])) {
            if (!expectNumber) {
                throw runtime_error("Unexpected number in expression");
            }
            int tmp = s[i] - '0';
            num.push(tmp);
            expectNumber = false;
        } else if (s[i] == '(') {
            if (!expectNumber) {
                throw runtime_error("Unexpected opening parenthesis");
            }
            op.push('(');
            expectNumber = true;
        } else if (s[i] == ')') {
            if (expectNumber) {
                throw runtime_error("Unexpected closing parenthesis");
            }
            while (!op.empty() && op.top() != '(') {
                processOperation(op, num);
            }
            if (op.empty()) {
                throw runtime_error("Mismatched parentheses");
            }
            op.pop();
            expectNumber = false;
        } else if (isOperator(s[i])) {
            if (expectNumber && s[i] != '-' && s[i] != '+') {
                throw runtime_error("Invalid operator position");
            }
            while (!op.empty() && op.top() != '(' && 
                   getPrecedence(op.top()) >= getPrecedence(s[i])) {
                processOperation(op, num);
            }
            op.push(s[i]);
            expectNumber = true;
        } else {
            throw runtime_error("Invalid character in expression");
        }
    }
    while (!op.empty()) {
        if (op.top() == '(') {
            throw runtime_error("Mismatched parentheses");
        }
        processOperation(op, num);
    }
    if (num.size() != 1) {
        throw runtime_error("Invalid expression evaluation");
    }
    cout << num.top() << endl;
    return 0;
}
