using namespace std;

class TimeValidator {
private:
    int remaining_time;
    vector<int> road_conditions;
    bool endpoint_reached;
    bool time_expired;

    void validateInput(int n, const vector<int>& conditions) {
        if (n < 1 || n > 100) {
            throw invalid_argument("Invalid combat time");
        }
        for (int cond : conditions) {
            if (cond < 1 || cond > 50) {
                throw invalid_argument("Invalid road condition");
            }
        }
    }

    void processCondition(int condition) {
        if (condition == 6) {
            return;
        } else if (condition == 15) {
            endpoint_reached = true;
            return;
        }

        int time_penalty = 0;
        switch (condition) {
            case 7:
                time_penalty = 5;
                break;
            case 12:
                time_penalty = 20;
                break;
            default:
                time_penalty = 2;
                break;
        }

        remaining_time -= time_penalty;
        if (remaining_time <= 0 && !endpoint_reached) {
            time_expired = true;
        }
    }

public:
    TimeValidator(int n, const vector<int>& conditions) {
        validateInput(n, conditions);
        remaining_time = n;
        road_conditions = conditions;
        endpoint_reached = false;
        time_expired = false;
    }

    bool canReachEndpoint() {
        try {
            for (size_t i = 0; i < road_conditions.size(); ++i) {
                if (endpoint_reached || time_expired) {
                    break;
                }
                processCondition(road_conditions[i]);
                if (i == road_conditions.size() - 1 && !endpoint_reached) {
                    time_expired = true;
                }
            }
            return endpoint_reached && !time_expired;
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            return false;
        }
    }
};

int main() {
    try {
        int n;
        cin >> n;
        if (cin.fail()) {
            throw runtime_error("Invalid input format");
        }

        vector<int> conditions(n);
        for (int i = 0; i < n; ++i) {
            cin >> conditions[i];
            if (cin.fail()) {
                throw runtime_error("Invalid input format");
            }
        }

        TimeValidator validator(n, conditions);
        bool result = validator.canReachEndpoint();

        if (result) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
