        if (CHARACTER_MAP.find(c) != string::npos) return true;
        return false;
    }
};

class PatternDetector {
public:
    static bool isPotentialSpecialPattern(const string& str, size_t pos) {
        if (pos + 3 > str.length()) return false;
        string substr = str.substr(pos, 3);
        return substr == "kkk" || substr == "sss";
    }
};

class CircularShifter {
private:
    static int safeModulo(int a, int b) {
        if (b == 0) throw runtime_error("Modulo by zero");
        int result = a % b;
        if (result < 0) result += b;
        return result;
    }

public:
    static char shiftCharacterBack(char c) {
        size_t found = CHARACTER_MAP.find(c);
        if (found == string::npos) {
            stringstream ss;
            ss << "Invalid character encountered: " << c;
            throw invalid_argument(ss.str());
        }
        int newPos = safeModulo(static_cast<int>(found) - ROTATION_OFFSET, CHARACTER_MAP.length());
        return CHARACTER_MAP[newPos];
    }
};

class SpecialPatternHandler {
public:
    static pair<char, size_t> handleSpecialPattern(const string& str, size_t pos) {
        string pattern = str.substr(pos, 3);
        if (pattern == "kkk") {
            return make_pair(' ', pos + 3);
        } else if (pattern == "sss") {
            return make_pair('.', pos + 3);
        }
        throw runtime_error("Unknown special pattern encountered");
    }
};

