    DecryptionResult result;

    void validateInput() {
        for (char c : encrypted) {
            if (!CharacterValidator::isValidEncryptedChar(c) && 
                !PatternDetector::isPotentialSpecialPattern(encrypted, &c - &encrypted[0])) {
                result.warnings.push_back("Invalid character in input: " + string(1, c));
                result.hasErrors = true;
