```cpp
#include <bits/stdc++.h>

using namespace std;

const string CHARACTER_MAP = "abcdefghijklmnopqrstuvwxyz0123456789";
const int ROTATION_OFFSET = 3;
const string SPACE_REPLACEMENT = "kkk";
const string PERIOD_REPLACEMENT = "sss";
const int MINIMUM_LENGTH_FOR_SPECIAL = 3;

struct DecryptionContext {
    string input;
    string output;
    vector<bool> processedIndices;
    bool hasSpecialSequences;
};

void initializeContext(DecryptionContext& ctx, const string& str) {
    ctx.input = str;
    ctx.output = "";
    ctx.processedIndices = vector<bool>(str.length(), false);
    ctx.hasSpecialSequences = false;
}

void handleSpecialSequences(DecryptionContext& ctx) {
    for (size_t i = 0; i < ctx.input.length(); ) {
        bool sequenceFound = false;
        if (i + ROTATION_OFFSET <= ctx.input.length()) {
            string currentTriplet = ctx.input.substr(i, ROTATION_OFFSET);
            if (currentTriplet == SPACE_REPLACEMENT) {
                ctx.output += ' ';
                for (size_t j = i; j < i + ROTATION_OFFSET; ++j) {
                    ctx.processedIndices[j] = true;
                }
                i += ROTATION_OFFSET;
                sequenceFound = true;
                ctx.hasSpecialSequences = true;
            } else if (currentTriplet == PERIOD_REPLACEMENT) {
                ctx.output += '.';
                for (size_t j = i; j < i + ROTATION_OFFSET; ++j) {
                    ctx.processedIndices[j] = true;
                }
                i += ROTATION_OFFSET;
                sequenceFound = true;
                ctx.hasSpecialSequences = true;
            }
        }
        if (!sequenceFound) {
            i++;
        }
    }
}

void handleCharacterRotation(DecryptionContext& ctx) {
    for (size_t i = 0; i < ctx.input.length(); ++i) {
        if (!ctx.processedIndices[i]) {
            char currentChar = ctx.input[i];
            size_t foundPos = CHARACTER_MAP.find(currentChar);
            if (foundPos != string::npos) {
                int newPos = (foundPos - ROTATION_OFFSET + CHARACTER_MAP.length()) % CHARACTER_MAP.length();
                ctx.output += CHARACTER_MAP[newPos];
            } else {
                ctx.output += currentChar;
            }
        }
    }
}

string decryptMessage(const string& encrypted) {
    DecryptionContext ctx;
    initializeContext(ctx, encrypted);

    if (encrypted.length() >= MINIMUM_LENGTH_FOR_SPECIAL) {
        handleSpecialSequences(ctx);
    }

    if (!ctx.hasSpecialSequences) {
        ctx.processedIndices = vector<bool>(encrypted.length(), false);
    }

    handleCharacterRotation(ctx);

    return ctx.output;
}

int main() {
    string encryptedMessage;
    getline(cin, encryptedMessage);

    string decryptedMessage = decryptMessage(encryptedMessage);

    cout << decryptedMessage << endl;

    return 0;
}
