vector<int> sums_cache;

int calculate_sum(const string& s) {
    int total = 0;
    for (char c : s) {
        if (!isdigit(c)) {
            throw invalid_argument("Non-digit character in number plate");
        }
        total += c - '0';
    }
    return total;
}

long string_to_long(const string& s) {
    istringstream iss(s);
    long val;
    iss >> val;
    if (iss.fail()) {
        throw runtime_error("Failed to convert string to long");
    }
    return val;
}

void preprocess_plates(int n) {
    plates.reserve(n);
    sums_cache.reserve(n);
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        if (s.length() > 10) {
            throw length_error("Number plate too long");
        }
        long num = string_to_long(s);
        int ssum = calculate_sum(s);
        plates.push_back({s, num, ssum, i});
        sums_cache.push_back(ssum);
    }
}

bool compare_plates(const NumberPlate& a, const NumberPlate& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    } else {
        return a.numeric > b.numeric;
    }
}

int find_position(const vector<NumberPlate>& sorted, const NumberPlate& target) {
    for (size_t i = 0; i < sorted.size(); ++i) {
        bool sum_equal = (sorted[i].sum == target.sum);
        bool num_equal = (sorted[i].numeric == target.numeric);
        bool original_equal = (sorted[i].original == target.original);
        if (sum_equal && num_equal && original_equal) {
            return i + 1;
        }
    }
    return -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cerr << "Invalid number of plates" << endl;
        return 1;
    }

    try {
        preprocess_plates(n);
    } catch (const exception& e) {
        cerr << "Error processing input: " << e.what() << endl;
        return 1;
