        int carry = 0;
        size_t max_len = max(a.size(), b.size());

        for (size_t i = 0; i < max_len || carry; ++i) {
            int digit_a = (i < a.size()) ? (a[i] - '0') : 0;
            int digit_b = (i < b.size()) ? (b[i] - '0') : 0;
            int total = digit_a + digit_b + carry;
            carry = total / 10;
            result.push_back((total % 10) + '0');
        }

