struct QueueState {
    string* array;
    int left;
    int right;
    bool error;
};

QueueState initializeQueue() {
    QueueState state;
    state.array = new string[105];
    state.left = 0;
    state.right = 0;
    state.error = false;
    return state;
}

bool validateOperation(int op) {
    return op == 1 || op == 2;
}

bool validateName(const string& name) {
    return !name.empty() && all_of(name.begin(), name.end(), [](char c) {
        return isalpha(c);
    });
}

void handleEnqueue(QueueState& state, const string& name) {
    bool insertionOccurred = false;
    int insertionPosition = -1;
    char firstLetter = toupper(name[0]);

    for (int currentIndex = state.left; currentIndex < state.right; currentIndex++) {
        if (state.array[currentIndex].empty()) continue;
        char currentFirstLetter = toupper(state.array[currentIndex][0]);
        if (currentFirstLetter == firstLetter) {
            insertionPosition = currentIndex;
            break;
        }
    }

    if (insertionPosition != -1) {
        for (int shiftIndex = state.right; shiftIndex > insertionPosition + 1; shiftIndex--) {
            state.array[shiftIndex] = state.array[shiftIndex - 1];
        }
        state.array[insertionPosition + 1] = name;
        insertionOccurred = true;
    }

    if (!insertionOccurred) {
        state.array[state.right] = name;
    }

    state.right++;
}

void handleDequeue(QueueState& state) {
    if (state.left >= state.right || state.array[state.left].empty()) {
        cout << 0 << endl;
        state.error = true;
    } else {
        string frontElement = state.array[state.left];
        if (frontElement.empty()) {
            cout << 0 << endl;
            state.error = true;
        } else {
            cout << frontElement << endl;
            state.left++;
        }
    }
}

