using namespace std;

struct QueueStateValidator {
    static void validateQueueBounds(int l, int r, int max_size) {
        if (l < 0 || r < 0 || l > r || r > max_size) {
            throw out_of_range("Queue boundary violation detected");
        }
    }
};

class AdvancedQueueManager {
private:
    vector<string> queue;
    int front;
    int rear;
    const int MAX_SIZE = 1000;

public:
    AdvancedQueueManager() : front(0), rear(0) {
        queue.resize(MAX_SIZE);
    }

    void enqueueWithFriendshipCheck(const string& name) {
        if (name.empty()) {
            throw invalid_argument("Empty name provided");
        }

        bool inserted = false;
        char firstChar = toupper(name[0]);

        for (int i = front; i < rear; ++i) {
            if (i < 0 || i >= queue.size()) {
                throw runtime_error("Invalid queue index during insertion");
            }

            char currentFirstChar = toupper(queue[i][0]);
            if (currentFirstChar == firstChar) {
                if (rear + 1 > MAX_SIZE) {
                    throw overflow_error("Queue overflow prevented");
                }

                for (int j = rear; j > i + 1; --j) {
                    if (j - 1 < 0 || j >= queue.size()) {
                        throw runtime_error("Invalid shift index");
                    }
                    queue[j] = queue[j - 1];
                }

                if (i + 1 < 0 || i + 1 >= queue.size()) {
                    throw runtime_error("Invalid insertion point");
                }

                queue[i + 1] = name;
                inserted = true;
                break;
            }
        }

        if (!inserted) {
            if (rear >= MAX_SIZE) {
                throw overflow_error("Queue overflow prevented");
            }
            queue[rear] = name;
        }

        rear++;
        QueueStateValidator::validateQueueBounds(front, rear, MAX_SIZE);
    }

    string dequeueWithSafetyChecks() {
        if (front >= rear) {
            return "0";
        }

        if (front < 0 || front >= queue.size()) {
            throw runtime_error("Invalid front index during dequeue");
        }

        string result = queue[front];
        front++;

        QueueStateValidator::validateQueueBounds(front, rear, MAX_SIZE);
        return result;
    }
};

int main() {
    AdvancedQueueManager queueManager;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid operation count" << endl;
        return EXIT_FAILURE;
