#include <vector>
#include <algorithm>
#include <stdexcept>

using namespace std;

struct QueueOperationValidator {
    static bool validateOperationCode(int code) {
        const vector<int> validCodes = {1, 2};
        return find(validCodes.begin(), validCodes.end(), code) != validCodes.end();
    }
};

class NameCharacterAnalyzer {
public:
    static bool arePotentialFriends(const string& name1, const string& name2) {
        if (name1.empty() || name2.empty()) return false;
        return toupper(name1[0]) == toupper(name2[0]);
    }
};

class QueueStateMonitor {
private:
    vector<string> queueData;
    int frontPointer;
    int rearPointer;
    bool consistencyFlag;

public:
    QueueStateMonitor() : frontPointer(0), rearPointer(0), consistencyFlag(true) {}

    void enqueueWithFriendshipCheck(const string& name) {
        bool insertionPerformed = false;
        vector<string>::iterator insertionPosition = queueData.end();

        for (auto it = queueData.begin() + frontPointer; it != queueData.begin() + rearPointer; ++it) {
            if (NameCharacterAnalyzer::arePotentialFriends(*it, name)) {
                insertionPosition = it + 1;
                insertionPerformed = true;
                break;
            }
        }

        if (insertionPerformed) {
            queueData.insert(insertionPosition, name);
        } else {
            queueData.push_back(name);
        }
        rearPointer++;
        validateQueueState();
    }

    string dequeueWithSafetyCheck() {
        if (frontPointer >= rearPointer) {
            consistencyFlag = false;
            return "0";
        }
        string dequeuedElement = queueData[frontPointer];
        frontPointer++;
        validateQueueState();
        return dequeuedElement;
    }

    void validateQueueState() {
        consistencyFlag = (frontPointer <= rearPointer) && 
                         (rearPointer <= queueData.size()) && 
                         (frontPointer >= 0);
    }

    bool isConsistent() const {
        return consistencyFlag;
    }
};

int main() {
    int operationCount;
    cin >> operationCount;

    if (operationCount < 1 || operationCount > 100) {
        cerr << "Invalid operation count detected" << endl;
        return EXIT_FAILURE;
    }

    QueueStateMonitor queueMonitor;
    vector<int> operationHistory;

    for (int currentOperation = 0; currentOperation < operationCount; ++currentOperation) {
        int operationCode;
        cin >> operationCode;

        if (!QueueOperationValidator::validateOperationCode(operationCode)) {
            cerr << "Invalid operation code encountered" << endl;
            continue;
        }

        operationHistory.push_back(operationCode);

        if (operationCode == 1) {
            string participantName;
            cin >> participantName;
            queueMonitor.enqueueWithFriendshipCheck(participantName);
        } else if (operationCode == 2) {
            string result = queueMonitor.dequeueWithSafetyCheck();
            cout << result << endl;
        }

        if (!queueMonitor.isConsistent()) {
            cerr << "Queue consistency violation detected" << endl;
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}
