#include<bits/stdc++.h>
using namespace std;

struct Child {
    int height;
    int id;
    int cnt;
    bool processed;
    bool operator<(const Child& other) const {
        return height < other.height;
    }
};

struct Balloon {
    int height;
    bool taken;
    bool operator<(const Balloon& other) const {
        return height < other.height;
    }
};

vector<Child> children;
vector<Balloon> balloons;

void validateInput(int n, int m) {
    if (n < 1 || n > 1000 || m < 1 || m > 1000) {
        cerr << "Invalid input range" << endl;
        exit(EXIT_FAILURE);
    }
}

void readChildren(int n) {
    children.resize(n);
    for (int i = 0; i < n; i++) {
        if (!(cin >> children[i].height)) {
            cerr << "Invalid child height input" << endl;
            exit(EXIT_FAILURE);
        }
        if (children[i].height < 1 || children[i].height > 100000) {
            cerr << "Child height out of bounds" << endl;
            exit(EXIT_FAILURE);
        }
        children[i].id = i;
        children[i].cnt = 0;
        children[i].processed = false;
    }
}

void readBalloons(int m) {
    balloons.resize(m);
    for (int i = 0; i < m; i++) {
        if (!(cin >> balloons[i].height)) {
            cerr << "Invalid balloon height input" << endl;
            exit(EXIT_FAILURE);
        }
        if (balloons[i].height < 1 || balloons[i].height > 100000) {
            cerr << "Balloon height out of bounds" << endl;
            exit(EXIT_FAILURE);
        }
        balloons[i].taken = false;
    }
}

void checkDuplicateHeights() {
    unordered_set<int> seen;
    for (const auto& child : children) {
        if (seen.count(child.height)) {
            cerr << "Duplicate child heights detected" << endl;
            exit(EXIT_FAILURE);
        }
        seen.insert(child.height);
    }
}

void processChildren() {
    sort(children.begin(), children.end());
    sort(balloons.begin(), balloons.end());

    int current_balloon_index = 0;
    for (auto& child : children) {
        if (child.processed) continue;

        int count = 0;
        while (current_balloon_index < balloons.size() && 
               !balloons[current_balloon_index].taken && 
               balloons[current_balloon_index].height <= child.height) {
            count++;
            balloons[current_balloon_index].taken = true;
            current_balloon_index++;
        }

        child.cnt = count;
        child.processed = true;

        for (int i = current_balloon_index; i < balloons.size(); i++) {
            if (!balloons[i].taken && balloons[i].height <= child.height) {
                child.cnt++;
                balloons[i].taken = true;
            }
        }
    }
}

void sortChildrenById() {
    sort(children.begin(), children.end(), [](const Child& a, const Child& b) {
        return a.id < b.id;
    });
}

void outputResults() {
    for (const auto& child : children) {
        cout << child.cnt << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) {
        cerr << "Invalid input" << endl;
        return EXIT_FAILURE;
    }

    validateInput(n, m);
    readChildren(n);
    readBalloons(m);
    checkDuplicateHeights();

    processChildren();
    sortChildrenById();
    outputResults();

    return 0;
}
