int degree_cache[MAX_NODES];
bool validation_flag = true;

void initialize_structures(int n) {
    for (int i = 0; i <= n; i++) {
        nodes[i].degree = 0;
        nodes[i].children.clear();
        nodes[i].parent = -1;
        nodes[i].is_root = false;
        visited[i] = false;
        degree_cache[i] = -1;
    }
    validation_flag = true;
}

void validate_tree_structure(int current, int parent, int n) {
    if (current < 0 || current >= n) {
        validation_flag = false;
        return;
    }
    if (visited[current]) {
        validation_flag = false;
        return;
    }
    visited[current] = true;
    for (int child : nodes[current].children) {
        if (child == parent) continue;
        validate_tree_structure(child, current, n);
        if (!validation_flag) return;
    }
}

void compute_degrees(int n) {
    for (int i = 0; i < n; i++) {
        nodes[i].degree = nodes[i].children.size();
        if (nodes[i].parent != -1) {
            nodes[i].degree++;
        }
    }
}

bool is_p_node(int node, int n) {
    if (node < 0 || node >= n) return false;
    int current_degree = nodes[node].degree;
    for (int child : nodes[node].children) {
        if (child < 0 || child >= n) continue;
        if (nodes[child].degree > current_degree) {
            return false;
        }
    }
    if (nodes[node].parent != -1) {
        if (nodes[nodes[node].parent].degree > current_degree) {
            return false;
        }
    }
    return true;
}

void process_test_case(int n) {
    initialize_structures(n);
    for (int i = 0; i < n-1; i++) {
        int x, y;
        if (!(cin >> x >> y)) {
            validation_flag = false;
            return;
        }
        if (x < 0 || x >= n || y < 0 || y >= n) {
            validation_flag = false;
            return;
        }
        nodes[x].children.push_back(y);
        nodes[y].parent = x;
    }
    for (int i = 0; i < n; i++) {
        if (nodes[i].parent == -1) {
            nodes[i].is_root = true;
            validate_tree_structure(i, -1, n);
            break;
        }
    }
    if (!validation_flag) return;
    compute_degrees(n);
    int p_count = 0;
    for (int i = 0; i < n; i++) {
        if (is_p_node(i, n)) {
            p_count++;
        }
    }
    cout << p_count << endl;
}

