    while (t--) {
        int n;
        if (!(cin >> n)) {
            cerr << "Invalid input format" << endl;
            return 1;
        }
        if (n < 1 || n > 1000) {
            cerr << "Invalid node count" << endl;
            continue;
        }
        process_test_case(n);
        if (!validation_flag) {
            cerr << "Invalid tree structure" << endl;
        }
    }
    return 0;
