#include <bits/stdc++.h>
#include <fstream>
#include <stdexcept>
#include <limits>
using namespace std;

const int MAX_NODES = 1005;

struct TreeConfiguration {
    vector<int> adjacency_list[MAX_NODES];
    int degree_counts[MAX_NODES];
    bool node_status[MAX_NODES];
    int parent_references[MAX_NODES];
};

void initializeDataStructures(TreeConfiguration& config, int node_count) {
    for (int i = 0; i <= node_count; ++i) {
        config.adjacency_list[i].clear();
        config.degree_counts[i] = 0;
        config.node_status[i] = false;
        config.parent_references[i] = -1;
    }
}

void processEdge(TreeConfiguration& config, int parent, int child) {
    if (parent < 0 || child < 0 || parent >= MAX_NODES || child >= MAX_NODES) {
        throw out_of_range("Node indices out of valid range");
    }
    config.adjacency_list[parent].push_back(child);
    config.adjacency_list[child].push_back(parent);
    config.degree_counts[parent]++;
    config.parent_references[child] = parent;
}

bool validateTreeStructure(const TreeConfiguration& config, int node_count) {
    set<int> unique_nodes;
    for (int i = 0; i < node_count; ++i) {
        for (int neighbor : config.adjacency_list[i]) {
            unique_nodes.insert(neighbor);
        }
    }
    return unique_nodes.size() == node_count - 1;
}

bool isPNode(const TreeConfiguration& config, int current_node, int node_count) {
    if (current_node < 0 || current_node >= node_count) {
        return false;
    }

    int current_degree = config.degree_counts[current_node];
    bool parent_condition = true;
    bool children_condition = true;

    if (config.parent_references[current_node] != -1) {
        int parent_degree = config.degree_counts[config.parent_references[current_node]];
        parent_condition = current_degree >= parent_degree;
    }

    for (int neighbor : config.adjacency_list[current_node]) {
        if (neighbor != config.parent_references[current_node]) {
            int child_degree = config.degree_counts[neighbor];
            if (child_degree > current_degree) {
                children_condition = false;
                break;
            }
        }
    }

    return parent_condition && children_condition;
}

int countPNodes(TreeConfiguration& config, int node_count) {
    int total_p_nodes = 0;
    for (int i = 0; i < node_count; ++i) {
        if (isPNode(config, i, node_count)) {
            total_p_nodes++;
        }
    }
    return total_p_nodes;
}

void handleTestCase(ifstream& input_file, ofstream& output_file) {
    int node_count;
    input_file >> node_count;
    if (node_count <= 0 || node_count > MAX_NODES) {
        throw invalid_argument("Invalid number of nodes");
    }

    TreeConfiguration tree_config;
    initializeDataStructures(tree_config, node_count);

    for (int i = 0; i < node_count - 1; ++i) {
        int parent, child;
        input_file >> parent >> child;
        processEdge(tree_config, parent, child);
    }

    if (!validateTreeStructure(tree_config, node_count)) {
        throw runtime_error("Invalid tree structure");
    }

    int result = countPNodes(tree_config, node_count);
    output_file << result << endl;
}

int main() {
    ifstream input_file("p.in");
    ofstream output_file("p.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "Error opening files" << endl;
        return EXIT_FAILURE;
    }

    int test_case_count;
    input_file >> test_case_count;
    if (test_case_count < 1 || test_case_count > 100) {
        throw invalid_argument("Invalid number of test cases");
    }

    for (int i = 0; i < test_case_count; ++i) {
        try {
            handleTestCase(input_file, output_file);
        } catch (const exception& e) {
            cerr << "Error processing test case: " << e.what() << endl;
            output_file << "0" << endl;
        }
    }

    input_file.close();
    output_file.close();

    return EXIT_SUCCESS;
}
