#include <bits/stdc++.h>
using namespace std;

struct QueueState {
    string* data;
    int left;
    int right;
    bool initialization_flag;
    bool memory_allocation_success;
};

void initializeQueueState(QueueState& qs) {
    qs.data = new string[100000];
    qs.left = 0;
    qs.right = 0;
    qs.initialization_flag = true;
    qs.memory_allocation_success = (qs.data != nullptr);
}

void cleanupQueueState(QueueState& qs) {
    if (qs.initialization_flag && qs.memory_allocation_success) {
        delete[] qs.data;
        qs.initialization_flag = false;
        qs.memory_allocation_success = false;
    }
}

bool performInsertOperation(QueueState& qs, const string& name) {
    if (!qs.initialization_flag || !qs.memory_allocation_success) {
        return false;
    }

    bool insertion_performed = false;
    bool friend_found = false;
    int insertion_position = -1;

    for (int current_position = qs.left; current_position < qs.right; current_position++) {
        if (!qs.data[current_position].empty() && qs.data[current_position][0] == name[0]) {
            friend_found = true;
            insertion_position = current_position;
            break;
        }
    }

    if (friend_found && insertion_position >= 0) {
        for (int shift_position = qs.right; shift_position > insertion_position + 1; shift_position--) {
            qs.data[shift_position] = qs.data[shift_position - 1];
        }
        qs.data[insertion_position + 1] = name;
        insertion_performed = true;
    }

    if (!insertion_performed) {
        qs.data[qs.right] = name;
    }

    qs.right++;
    return true;
}

string performRemoveOperation(QueueState& qs) {
    if (!qs.initialization_flag || !qs.memory_allocation_success) {
        return "0";
    }

    if (qs.left >= qs.right) {
        return "0";
    }

    string removed_element = qs.data[qs.left];
    qs.left++;
    return removed_element;
}

int main() {
    QueueState queue_state;
    initializeQueueState(queue_state);

    if (!queue_state.initialization_flag || !queue_state.memory_allocation_success) {
        cleanupQueueState(queue_state);
        return 1;
    }

    int operation_count;
    cin >> operation_count;

    while (operation_count-- > 0) {
        int operation_type;
        cin >> operation_type;

        if (operation_type == 1) {
            string new_name;
            cin >> new_name;
            bool insertion_result = performInsertOperation(queue_state, new_name);
            if (!insertion_result) {
                cleanupQueueState(queue_state);
                return 1;
            }
        } else if (operation_type == 2) {
            string removal_result = performRemoveOperation(queue_state);
            cout << removal_result << endl;
        } else {
            cleanupQueueState(queue_state);
            return 1;
        }
    }

    cleanupQueueState(queue_state);
    return 0;
}
