#include <bits/stdc++.h>
#include <stdexcept>
#include <typeinfo>
#include <limits>
using namespace std;

#define MAX_QUEUE_SIZE 1000000

struct QueueMetadata {
    string* data;
    int front;
    int rear;
    int capacity;
    bool initialized;
};

void validateQueueOperation(const QueueMetadata& q, bool isInsert) {
    if (!q.initialized) {
        throw runtime_error("Queue not initialized");
    }
    if (isInsert && q.rear >= q.capacity) {
        throw overflow_error("Queue overflow");
    }
    if (!isInsert && q.front == q.rear) {
        throw underflow_error("Queue underflow");
    }
}

void initializeQueue(QueueMetadata& q) {
    q.data = new string[MAX_QUEUE_SIZE];
    q.front = 0;
    q.rear = 0;
    q.capacity = MAX_QUEUE_SIZE;
    q.initialized = true;
}

void cleanupQueue(QueueMetadata& q) {
    if (q.initialized) {
        delete[] q.data;
        q.initialized = false;
    }
}

bool isFriend(const string& a, const string& b) {
    if (a.empty() || b.empty()) {
        return false;
    }
    return toupper(a[0]) == toupper(b[0]);
}

int findFirstFriendPosition(QueueMetadata& q, const string& name) {
    for (int i = q.front; i < q.rear; ++i) {
        try {
            if (isFriend(q.data[i], name)) {
                return i;
            }
        } catch (const exception& e) {
            cerr << "Error comparing names: " << e.what() << endl;
            continue;
        }
    }
    return -1;
}

void insertAfterPosition(QueueMetadata& q, int pos, const string& name) {
    if (pos < q.front || pos >= q.rear) {
        throw out_of_range("Invalid position for insertion");
    }
    for (int i = q.rear; i > pos + 1; --i) {
        q.data[i] = q.data[i - 1];
    }
    q.data[pos + 1] = name;
    q.rear++;
}

void handleEnqueue(QueueMetadata& q) {
    string name;
    cin >> name;
    if (name.length() > 100) {
        cerr << "Warning: Name length exceeds typical limits" << endl;
    }

    try {
        int friendPos = findFirstFriendPosition(q, name);
        if (friendPos != -1) {
            insertAfterPosition(q, friendPos, name);
        } else {
            validateQueueOperation(q, true);
            q.data[q.rear++] = name;
        }
    } catch (const exception& e) {
        cerr << "Enqueue error: " << e.what() << endl;
        cleanupQueue(q);
        exit(EXIT_FAILURE);
    }
}

void handleDequeue(QueueMetadata& q) {
    try {
        validateQueueOperation(q, false);
        if (q.front == q.rear) {
            cout << 0 << endl;
        } else {
            string frontElement = q.data[q.front++];
            if (frontElement.empty()) {
                cerr << "Warning: Dequeued empty name" << endl;
            }
            cout << frontElement << endl;
        }
    } catch (const exception& e) {
        cout << 0 << endl;
        cerr << "Dequeue error: " << e.what() << endl;
    }
}

int main() {
    QueueMetadata queue = {nullptr, 0, 0, 0, false};
    try {
        initializeQueue(queue);

        int n;
        cin >> n;
        if (n < 1 || n > 100) {
            throw invalid_argument("Invalid number of operations");
        }

        while (n--) {
            int k;
            cin >> k;
            if (cin.fail()) {
                cin.clear();
                cin.ignore(numeric_limits<streamsize>::max(), '\n');
                throw runtime_error("Invalid operation type");
            }

            if (k == 1) {
                handleEnqueue(queue);
            } else if (k == 2) {
                handleDequeue(queue);
            } else {
                throw invalid_argument("Unknown operation");
            }
        }
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        cleanupQueue(queue);
        return EXIT_FAILURE;
    }

    cleanupQueue(queue);
    return 0;
}
