#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 11;
const int MAX_DIAG = 20;

struct ChessState {
    bool board[MAX_N][MAX_N];
    bool black_rows[MAX_N];
    bool black_diag1[MAX_DIAG];
    bool black_diag2[MAX_DIAG];
    bool white_rows[MAX_N];
    bool white_diag1[MAX_DIAG];
    bool white_diag2[MAX_DIAG];
    int n;
};

void initializeState(ChessState& state, int size) {
    state.n = size;
    for (int i = 0; i < MAX_N; i++) {
        for (int j = 0; j < MAX_N; j++) {
            state.board[i][j] = false;
        }
        state.black_rows[i] = false;
        state.white_rows[i] = false;
    }
    for (int i = 0; i < MAX_DIAG; i++) {
        state.black_diag1[i] = false;
        state.black_diag2[i] = false;
        state.white_diag1[i] = false;
        state.white_diag2[i] = false;
    }
}

bool validatePosition(const ChessState& state, int row, int col, bool is_black) {
    if (row < 0 || row >= state.n || col < 0 || col >= state.n) {
        return false;
    }
    if (!state.board[row][col]) {
        return false;
    }
    if (is_black) {
        if (state.black_rows[row]) return false;
        if (state.black_diag1[row + col]) return false;
        if (state.black_diag2[col - row + state.n]) return false;
    } else {
        if (state.white_rows[row]) return false;
        if (state.white_diag1[row + col]) return false;
        if (state.white_diag2[col - row + state.n]) return false;
    }
    return true;
}

void updateState(ChessState& state, int row, int col, bool is_black, bool value) {
    if (row < 0 || row >= state.n || col < 0 || col >= state.n) {
        return;
    }
    if (is_black) {
        state.black_rows[row] = value;
        state.black_diag1[row + col] = value;
        state.black_diag2[col - row + state.n] = value;
    } else {
        state.white_rows[row] = value;
        state.white_diag1[row + col] = value;
        state.white_diag2[col - row + state.n] = value;
    }
    state.board[row][col] = !value;
}

void solve(ChessState& state, int col, bool is_black, int& count) {
    if (col == state.n) {
        if (is_black) {
            solve(state, 0, false, count);
        } else {
            count++;
        }
        return;
    }

    for (int row = 0; row < state.n; row++) {
        if (validatePosition(state, row, col, is_black)) {
            updateState(state, row, col, is_black, true);
            solve(state, col + 1, is_black, count);
            updateState(state, row, col, is_black, false);
        }
    }
}

int main() {
    freopen("queen.in", "r", stdin);
    freopen("queen.out", "w", stdout);

    ChessState state;
    int n;
    cin >> n;

    if (n <= 0 || n > 8) {
        cout << 0 << endl;
        return 0;
    }

    initializeState(state, n);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int val;
            cin >> val;
            if (val != 0 && val != 1) {
                cout << 0 << endl;
                return 0;
            }
            state.board[i][j] = (val == 1);
        }
    }

    int total = 0;
    solve(state, 0, true, total);

    cout << total << endl;

    return 0;
}
