bool black_queen_diagonal2_occupied[MAX_DIAGONAL];

bool white_queen_row_occupied[MAX_SIZE];
bool white_queen_diagonal1_occupied[MAX_DIAGONAL];
bool white_queen_diagonal2_occupied[MAX_DIAGONAL];

enum QueenType { BLACK_QUEEN = 1, WHITE_QUEEN = 2 };

bool validate_black_queen_position(int current_column, int current_row) {
    bool row_valid = !black_queen_row_occupied[current_row];
    bool diagonal1_valid = !black_queen_diagonal1_occupied[current_column + current_row];
    bool diagonal2_valid = !black_queen_diagonal2_occupied[current_column - current_row + board_size];
    bool position_available = chessboard[current_row][current_column];
    return row_valid && diagonal1_valid && diagonal2_valid && position_available;
}

bool validate_white_queen_position(int current_column, int current_row) {
    bool row_valid = !white_queen_row_occupied[current_row];
    bool diagonal1_valid = !white_queen_diagonal1_occupied[current_column + current_row];
    bool diagonal2_valid = !white_queen_diagonal2_occupied[current_column - current_row + board_size];
    bool position_available = chessboard[current_row][current_column];
    return row_valid && diagonal1_valid && diagonal2_valid && position_available;
}

void recursive_placement(int current_column, QueenType queen_type) {
    if (current_column == board_size) {
        if (queen_type == BLACK_QUEEN) {
            recursive_placement(0, WHITE_QUEEN);
        } else {
            total_solutions++;
        }
        return;
    }

    for (int current_row = 0; current_row < board_size; current_row++) {
        if (queen_type == BLACK_QUEEN) {
            if (validate_black_queen_position(current_column, current_row)) {
                black_queen_row_occupied[current_row] = true;
                black_queen_diagonal1_occupied[current_column + current_row] = true;
                black_queen_diagonal2_occupied[current_column - current_row + board_size] = true;
                chessboard[current_row][current_column] = false;

                recursive_placement(current_column + 1, queen_type);

                chessboard[current_row][current_column] = true;
                black_queen_row_occupied[current_row] = false;
                black_queen_diagonal1_occupied[current_column + current_row] = false;
                black_queen_diagonal2_occupied[current_column - current_row + board_size] = false;
            }
        } else {
            if (validate_white_queen_position(current_column, current_row)) {
                white_queen_row_occupied[current_row] = true;
                white_queen_diagonal1_occupied[current_column + current_row] = true;
                white_queen_diagonal2_occupied[current_column - current_row + board_size] = true;
                chessboard[current_row][current_column] = false;

                recursive_placement(current_column + 1, queen_type);

                chessboard[current_row][current_column] = true;
                white_queen_row_occupied[current_row] = false;
                white_queen_diagonal1_occupied[current_column + current_row] = false;
                white_queen_diagonal2_occupied[current_column - current_row + board_size] = false;
            }
        }
    }
}

int main() {
    ifstream input_file("queen.in");
    ofstream output_file("queen.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "Error opening files" << endl;
        return EXIT_FAILURE;
    }

    input_file >> board_size;

    for (int row_index = 0; row_index < board_size; row_index++) {
        for (int column_index = 0; column_index < board_size; column_index++) {
            input_file >> temp_input_value;
            chessboard[row_index][column_index] = (temp_input_value == 1);
        }
    }

    recursive_placement(0, BLACK_QUEEN);

    output_file << total_solutions;

    input_file.close();
    output_file.close();

    return 0;
}
