struct CharacterValidator {
    static bool validateCharType(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
    }
};

class PositionCalculator {
public:
    static bool isTargetPosition(int currentPos, int y) {
        if (y <= 0) throw invalid_argument("y must be positive");
        return (currentPos + 1) % y == 0;
    }
};

class CharacterRotator {
private:
    static char rotateInRange(char c, int z, char base, int range) {
        int offset = (c - base + z) % range;
        if (offset < 0) offset += range;
        return base + offset;
    }

public:
    static char rotateCharacter(char c, int z) {
        if (!CharacterValidator::validateCharType(c)) return c;

        if (islower(c)) {
            return rotateInRange(c, z, 'a', 26);
        } else if (isupper(c)) {
            return rotateInRange(c, z, 'A', 26);
        } else if (isdigit(c)) {
            return rotateInRange(c, z, '0', 10);
        }
        return c;
    }
};

class InputSanitizer {
public:
    static void validateInput(int x, int y, int z) {
        if (x <= 10 || x > 100) throw out_of_range("x must be 10 < x <= 100");
        if (y <= 0 || y > 10) throw out_of_range("y must be 0 < y <= 10");
        if (z <= 0 || z > 100) throw out_of_range("z must be 0 < z <= 100");
