public:
    WordProcessor() : processingWord(false) {}

    void processCharacter(char c) {
        if (c == ' ') {
            if (processingWord) {
                words.push_back(currentBuffer);
                currentBuffer.clear();
                processingWord = false;
            }
        } else {
            if (!processingWord) {
                processingWord = true;
            }
