using namespace std;

class SentenceAnalyzer {
private:
    string sentence;
    vector<string> words;
    string longest_word;
    size_t max_length;

    void validateInput() {
        if (sentence.empty()) {
            throw runtime_error("Empty input detected");
        }
        for (char c : sentence) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Invalid character in input");
            }
        }
    }

    void tokenizeSentence() {
        istringstream iss(sentence);
        string token;
        while (iss >> token) {
            string processed_token;
            for (char c : token) {
                if (isalpha(c)) {
                    processed_token += tolower(c);
                }
            }
            if (!processed_token.empty()) {
                words.push_back(processed_token);
            }
        }
        if (words.empty()) {
            throw runtime_error("No valid words found");
        }
    }

    void findLongestWord() {
        max_length = 0;
        for (const auto& word : words) {
            if (word.length() > max_length) {
                max_length = word.length();
                longest_word = word;
            } else if (word.length() == max_length) {
                if (find(words.begin(), words.end(), word) < 
                    find(words.begin(), words.end(), longest_word)) {
                    longest_word = word;
                }
            }
        }
    }

public:
    explicit SentenceAnalyzer(const string& input) : sentence(input) {
        max_length = 0;
    }

    string getLongestWord() {
        try {
            validateInput();
            tokenizeSentence();
            findLongestWord();
            return longest_word;
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            return "";
        }
    }
};

int main() {
    string input;
    try {
        if (!getline(cin, input)) {
            cerr << "Failed to read input" << endl;
            return EXIT_FAILURE;
        }
        unique_ptr<SentenceAnalyzer> analyzer = make_unique<SentenceAnalyzer>(input);
