        } else {
            cerr << "No valid output generated" << endl;
            return EXIT_FAILURE;
        }
    } catch (const exception& e) {
        cerr << "Unexpected error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
