struct TreeValidationResult {
    bool isValid;
    string errorMessage;
};

class TreeValidator {
public:
    static TreeValidationResult validateTreeStructure(int n, const vector<pair<int, int>>& edges) {
        vector<bool> visited(n, false);
        vector<int> parent(n, -1);
        vector<vector<int>> adj(n);

        for (const auto& edge : edges) {
            if (edge.first < 0 || edge.first >= n || edge.second < 0 || edge.second >= n) {
                return {false, "Node index out of bounds"};
            }
            adj[edge.first].push_back(edge.second);
            adj[edge.second].push_back(edge.first);
        }

        queue<int> q;
        q.push(0);
        visited[0] = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    q.push(v);
                } else if (v != parent[u]) {
                    return {false, "Tree contains cycles"};
                }
            }
        }

        for (bool v : visited) {
            if (!v) {
                return {false, "Tree is not connected"};
            }
        }

        return {true, ""};
    }
};

class DegreeAnalyzer {
private:
    vector<int> degrees;
    vector<vector<int>> children;
    vector<int> parent;

    void initializeStructures(int n) {
        degrees.resize(n);
        children.resize(n);
        parent.resize(n, -1);
    }

public:
    void processTree(int n, const vector<pair<int, int>>& edges) {
        initializeStructures(n);

        for (const auto& edge : edges) {
            if (edge.first >= 0 && edge.first < n && edge.second >= 0 && edge.second < n) {
                children[edge.first].push_back(edge.second);
                parent[edge.second] = edge.first;
                degrees[edge.first]++;
                degrees[edge.second]++;
            }
        }
    }

    bool isPNode(int node) const {
        if (node < 0 || node >= degrees.size()) return false;

        int nodeDegree = degrees[node];
        bool valid = true;

        if (parent[node] != -1) {
            if (degrees[parent[node]] > nodeDegree) {
                valid = false;
            }
        }

        for (int child : children[node]) {
            if (degrees[child] > nodeDegree) {
                valid = false;
                break;
            }
        }

        return valid;
    }

    const vector<int>& getDegrees() const {
        return degrees;
    }
};

