#include <bits/stdc++.h>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

struct StoneAttributes {
    int anger;
    int irritability;
    bool operator==(const StoneAttributes& other) const {
        return anger == other.anger && irritability == other.irritability;
    }
    bool operator!=(const StoneAttributes& other) const {
        return !(*this == other);
    }
};

class StoneValidator {
public:
    static void validateStoneCount(int n) {
        if (n < 1 || n > 10) {
            throw invalid_argument("Stone count must be between 1 and 10");
        }
    }

    static void validateAttributes(int anger, int irritability) {
        if (anger < numeric_limits<int>::min() || anger > numeric_limits<int>::max()) {
            throw overflow_error("Anger value out of bounds");
        }
        if (irritability < numeric_limits<int>::min() || irritability > numeric_limits<int>::max()) {
            throw overflow_error("Irritability value out of bounds");
        }
    }
};

class StoneProcessor {
private:
    vector<StoneAttributes> stones;
    int minDifference;

    void validateCombinationIndex(int index) const {
        if (index < 1 || index >= (1 << stones.size())) {
            throw out_of_range("Invalid combination index");
        }
    }

    StoneAttributes calculateCombination(int index) const {
        validateCombinationIndex(index);
        StoneAttributes result{1, 0};
        for (size_t i = 0; i < stones.size(); ++i) {
            if (index & (1 << i)) {
                if (stones[i].anger == 0) {
                    throw runtime_error("Zero anger value detected in combination");
                }
                result.anger *= stones[i].anger;
                result.irritability += stones[i].irritability;
            }
        }
        return result;
    }

    void updateMinDifference(const StoneAttributes& attributes) {
        int currentDiff = abs(attributes.anger - attributes.irritability);
        if (currentDiff < minDifference || minDifference == -1) {
            minDifference = currentDiff;
        }
    }

public:
    StoneProcessor(const vector<StoneAttributes>& s) : stones(s), minDifference(-1) {
        if (stones.empty()) {
            throw invalid_argument("No stones provided");
        }
    }

    int findMinDifference() {
        for (int i = 1; i < (1 << stones.size()); ++i) {
            try {
                StoneAttributes combo = calculateCombination(i);
                updateMinDifference(combo);
            } catch (const exception& e) {
                cerr << "Warning: " << e.what() << " - Skipping combination " << i << endl;
                continue;
            }
        }
        if (minDifference == -1) {
            throw runtime_error("No valid combinations found");
        }
        return minDifference;
    }
};

class FileHandler {
public:
    static vector<StoneAttributes> readStonesFromFile(const string& filename) {
        ifstream inputFile(filename);
        if (!inputFile.is_open()) {
            throw runtime_error("Failed to open input file");
        }

        int n;
        inputFile >> n;
        StoneValidator::validateStoneCount(n);

        vector<StoneAttributes> stones(n);
        for (int i = 0; i < n; ++i) {
            int anger, irritability;
            inputFile >> anger >> irritability;
            StoneValidator::validateAttributes(anger, irritability);
            stones[i] = {anger, irritability};
        }

        return stones;
    }

    static void writeResultToFile(const string& filename, int result) {
        ofstream outputFile(filename);
        if (!outputFile.is_open()) {
            throw runtime_error("Failed to open output file");
        }
        outputFile << result;
    }
};

int main() {
    try {
        vector<StoneAttributes> stones = FileHandler::readStonesFromFile("stone.in");
        StoneProcessor processor(stones);
        int result = processor.findMinDifference();
        FileHandler::writeResultToFile("stone.out", result);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        ofstream errorOutput("stone.out");
        if (errorOutput.is_open()) {
            errorOutput << "-1";
        }
        return 1;
    }
    return 0;
}
