#include<cmath>

using namespace std;

struct NumberWrapper {
    string original;
    int numeric_value;
    int digit_sum;
    bool is_valid;
};

bool validate_number(const string& s) {
    if (s.empty()) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    try {
        size_t pos;
        int val = stoi(s, &pos);
        if (pos != s.length()) return false;
        if (val <= 0 || val >= 10000) return false;
    } catch (...) {
        return false;
    }
    return true;
}

int compute_digit_sum(int num) {
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
        if (sum > 100000) {
            sum = -1;
            break;
        }
    }
    return sum;
}

bool compare_wrappers(const NumberWrapper& a, const NumberWrapper& b) {
    if (!a.is_valid || !b.is_valid) {
        throw runtime_error("Invalid number encountered during comparison");
    }
    if (a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    }
    if (a.numeric_value != b.numeric_value) {
        return a.numeric_value < b.numeric_value;
    }
    if (a.original.length() != b.original.length()) {
        return a.original.length() < b.original.length();
    }
    return a.original < b.original;
}

void process_input(int& n, vector<NumberWrapper>& numbers) {
    string input_line;
    while (true) {
        getline(cin, input_line);
        if (!input_line.empty()) break;
    }
    istringstream iss(input_line);
    iss >> n;
    if (iss.fail() || n <= 0 || n >= 101) {
        throw invalid_argument("Invalid value for N");
    }

    numbers.clear();
    numbers.reserve(n);
    string num_str;
    while (numbers.size() < n) {
        cin >> num_str;
        NumberWrapper wrapper;
        wrapper.original = num_str;
        wrapper.is_valid = validate_number(num_str);
        if (wrapper.is_valid) {
            wrapper.numeric_value = stoi(num_str);
            wrapper.digit_sum = compute_digit_sum(wrapper.numeric_value);
            if (wrapper.digit_sum < 0) {
                wrapper.is_valid = false;
            }
        }
        numbers.push_back(wrapper);
    }
}

void validate_output(const vector<NumberWrapper>& numbers) {
    for (const auto& wrapper : numbers) {
        if (!wrapper.is_valid) {
            throw runtime_error("Invalid number in output");
        }
    }
}

int main() {
    try {
        ios_base::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr);

        int n = 0;
        vector<NumberWrapper> numbers;
        process_input(n, numbers);

        sort(numbers.begin(), numbers.end(), compare_wrappers);

        validate_output(numbers);

        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i != 0) cout << " ";
            cout << numbers[i].numeric_value;
        }
        cout << endl;

        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    } catch (...) {
        cerr << "Unknown error occurred" << endl;
        return 2;
    }
}
