using namespace std;

struct StoneAttributes {
    int anger;
    int irritability;
};

struct CalculationState {
    int product;
    int sum;
    bool valid;
};

vector<StoneAttributes> stoneData;
const int MAX_STONES = 15;

CalculationState initializeCalculationState() {
    CalculationState state;
    state.product = 1;
    state.sum = 0;
    state.valid = true;
    return state;
}

void validateFileAccess(const string& filename, const string& mode) {
    struct stat buffer;
    if (stat(filename.c_str(), &buffer) != 0) {
        cerr << "File access validation failed for " << filename << endl;
        exit(EXIT_FAILURE);
    }
}

int computeDifferenceForCombination(unsigned long combination) {
    CalculationState current = initializeCalculationState();
    unsigned long tempCombination = combination;
    int stoneIndex = 0;

    while (tempCombination > 0 && stoneIndex < stoneData.size()) {
        if ((tempCombination & 1) == 1) {
            if (stoneData[stoneIndex].anger == 0) {
                current.valid = false;
                break;
            }
            current.product *= stoneData[stoneIndex].anger;
            current.sum += stoneData[stoneIndex].irritability;
        }
        tempCombination >>= 1;
        stoneIndex++;
    }

    if (!current.valid || combination == 0) {
        return INT_MAX;
    }

    return abs(current.product - current.sum);
}

int findMinimumDifference() {
    int minimumDifference = INT_MAX;
    unsigned long totalCombinations = (1UL << stoneData.size());

    for (unsigned long combination = 1; combination < totalCombinations; ++combination) {
        int currentDifference = computeDifferenceForCombination(combination);
        if (currentDifference < minimumDifference) {
            minimumDifference = currentDifference;
        }
    }

    return minimumDifference;
}

