#include <bits/stdc++.h>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

struct Stone {
    int anger;
    int irritability;
    bool operator<(const Stone& other) const {
        return anger * irritability < other.anger * other.irritability;
    }
};

vector<Stone> stones;
vector<bool> selected;
int global_min_diff = numeric_limits<int>::max();

namespace StoneUtils {
    bool validateStone(const Stone& s) {
        if (s.anger < 0 || s.irritability < 0) {
            throw invalid_argument("Stone attributes must be non-negative");
        }
        return true;
    }

    void preprocessStones() {
        sort(stones.begin(), stones.end());
        for (auto& s : stones) {
            if (s.anger == 0) s.anger = 1;
            if (s.irritability == 0) s.irritability = 1;
        }
    }

    int calculateProduct(const vector<Stone>& subset) {
        int product = 1;
        for (const auto& s : subset) {
            product *= s.anger;
            if (product < 0) throw overflow_error("Anger product overflow");
        }
        return product;
    }

    int calculateSum(const vector<Stone>& subset) {
        int sum = 0;
        for (const auto& s : subset) {
            sum += s.irritability;
            if (sum < 0) throw overflow_error("Irritability sum overflow");
        }
        return sum;
    }

    void updateMinDiff(int product, int sum) {
        int diff = abs(product - sum);
        if (diff < 0) throw runtime_error("Difference calculation error");
        if (diff < global_min_diff) {
            global_min_diff = diff;
        }
    }
}

void recursiveSelection(int index, vector<Stone>& current) {
    if (index == stones.size()) {
        if (!current.empty()) {
            try {
                int product = StoneUtils::calculateProduct(current);
                int sum = StoneUtils::calculateSum(current);
                StoneUtils::updateMinDiff(product, sum);
            } catch (const exception& e) {
                cerr << "Error in calculation: " << e.what() << endl;
            }
        }
        return;
    }

    recursiveSelection(index + 1, current);
    current.push_back(stones[index]);
    recursiveSelection(index + 1, current);
    current.pop_back();
}

void iterativeSelection() {
    int n = stones.size();
    for (int mask = 1; mask < (1 << n); ++mask) {
        vector<Stone> subset;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                subset.push_back(stones[i]);
            }
        }
        try {
            int product = StoneUtils::calculateProduct(subset);
            int sum = StoneUtils::calculateSum(subset);
            StoneUtils::updateMinDiff(product, sum);
        } catch (const exception& e) {
            cerr << "Error in calculation: " << e.what() << endl;
        }
    }
}

void initialize() {
    ifstream infile("stone.in");
    if (!infile.is_open()) {
        throw runtime_error("Failed to open input file");
    }

    int n;
    infile >> n;
    if (n < 1 || n > 10) {
        throw invalid_argument("Invalid number of stones");
    }

    stones.resize(n);
    for (int i = 0; i < n; ++i) {
        infile >> stones[i].anger >> stones[i].irritability;
        StoneUtils::validateStone(stones[i]);
    }

    infile.close();
}

void outputResult() {
    ofstream outfile("stone.out");
    if (!outfile.is_open()) {
        throw runtime_error("Failed to open output file");
    }
    outfile << global_min_diff << endl;
    outfile.close();
}

int main() {
    try {
        initialize();
        StoneUtils::preprocessStones();
        vector<Stone> temp;
        recursiveSelection(0, temp);
        iterativeSelection();
        outputResult();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
