        return a.numeric_value > b.numeric_value;
    }
    if(a.plate.length() != b.plate.length()) {
        return a.plate.length() > b.plate.length();
    }
    return lexicographical_compare(a.plate.begin(), a.plate.end(), b.plate.begin(), b.plate.end());
}

