#include<limits>
using namespace std;

void validateInputString(const string& s) {
    if (s.length() > 100) {
        throw length_error("Input string exceeds maximum length");
    }
    for (char c : s) {
        if (!isprint(c) && !isspace(c)) {
            throw invalid_argument("Invalid character in input");
        }
    }
}

string processCaseAndPunctuation(const string& s) {
    string processed;
    for (char c : s) {
        if (isupper(c) {
            if (c != 'I') {
                processed += tolower(c);
            } else {
                processed += c;
            }
        } else if (c == '?') {
            processed += '!';
        } else {
            processed += c;
        }
    }
    return processed;
}

vector<string> tokenizeString(const string& s) {
    vector<string> tokens;
    string current;
    for (char c : s) {
        if (isspace(c)) {
            if (!current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
        } else {
            current += c;
        }
    }
    if (!current.empty()) {
        tokens.push_back(current);
    }
    return tokens;
}

void validateTokenCount(const vector<string>& tokens) {
    if (tokens.size() > 100) {
        throw length_error("Too many tokens in input");
    }
}

vector<string> processRules(const vector<string>& tokens) {
    vector<string> result;
    vector<bool> processed(tokens.size(), false);

    for (size_t i = 0; i < tokens.size(); ++i) {
        if (processed[i]) continue;

        if (i + 1 < tokens.size() && !processed[i+1]) {
            if ((tokens[i] == "can" || tokens[i] == "could") && tokens[i+1] == "you") {
                result.push_back("I");
                result.push_back(tokens[i]);
                processed[i] = true;
                processed[i+1] = true;
                i++;
                continue;
            }
        }

        if (tokens[i] == "I" || tokens[i] == "me") {
            result.push_back("you");
            processed[i] = true;
        } else {
            result.push_back(tokens[i]);
            processed[i] = true;
        }
    }

    return result;
}

string reconstructString(const vector<string>& tokens) {
    if (tokens.empty()) return "";

    string result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        result += tokens[i];
        if (i != tokens.size() - 1) {
            result += " ";
        }
    }

    return result;
}

void processSingleInput(string& s) {
    try {
        validateInputString(s);
        string processed = processCaseAndPunctuation(s);
        vector<string> tokens = tokenizeString(processed);
        validateTokenCount(tokens);
        vector<string> processedTokens = processRules(tokens);
        string output = reconstructString(processedTokens);
        cout << output << endl;
    } catch (const exception& e) {
        cerr << "Error processing input: " << e.what() << endl;
        cout << s << endl;
    }
}

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 100) {
        cerr << "Invalid number of inputs" << endl;
        return 1;
    }

    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    for (int i = 0; i < n; ++i) {
        string s;
        getline(cin, s);
        if (cin.fail()) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            cerr << "Input error occurred" << endl;
            continue;
        }
        processSingleInput(s);
    }

    return 0;
}
