const int MAX_ITERATIONS = 1000000;
const double EPSILON = 1e-10;

struct SolutionValidator {
    bool operator()(int a, int b, int c, int d, int n) const {
        try {
            if (a < 0 || b < 0 || c < 0 || d < 0) {
                throw runtime_error("Negative value detected");
            }
            long long sum = static_cast<long long>(a)*a + static_cast<long long>(b)*b + 
                           static_cast<long long>(c)*c + static_cast<long long>(d)*d;
            if (abs(sum - n) > EPSILON) {
                throw runtime_error("Sum does not match target");
            }
            return true;
        } catch (const exception& e) {
            cerr << "Validation error: " << e.what() << endl;
            return false;
        }
    }
};

class FourSquareSolver {
private:
    int n;
    vector<int> current_best;
    SolutionValidator validator;

    void updateSolution(int a, int b, int c, int d) {
        vector<int> candidate = {a, b, c, d};
        sort(candidate.begin(), candidate.end());
        if (current_best.empty() || lexicographical_compare(
            candidate.begin(), candidate.end(),
            current_best.begin(), current_best.end())) {
            current_best = candidate;
        }
    }

    bool isPerfectSquare(int x) const {
        if (x < 0) return false;
        int root = static_cast<int>(sqrt(x) + EPSILON);
        return root * root == x;
    }

public:
    FourSquareSolver(int num) : n(num) {
        if (n <= 0 || n > 5000000) {
            throw invalid_argument("Invalid input range");
        }
    }

    vector<int> solve() {
        current_best.clear();
        int max_root = static_cast<int>(sqrt(n)) + 1;

        for (int a = 0; a <= max_root; ++a) {
            if (a * a > n) break;
            for (int b = 0; b <= max_root; ++b) {
                if (a * a + b * b > n) break;
                for (int c = 0; c <= max_root; ++c) {
                    if (a * a + b * b + c * c > n) break;
                    int remaining = n - (a * a + b * b + c * c);
                    if (remaining < 0) continue;
                    if (!isPerfectSquare(remaining)) continue;
                    int d = static_cast<int>(sqrt(remaining) + EPSILON);
                    if (validator(a, b, c, d, n)) {
                        updateSolution(a, b, c, d);
                    }
                }
            }
        }

        if (current_best.empty()) {
            throw runtime_error("No solution found");
        }

        return current_best;
    }
};

void handleIO(const string& input_file, const string& output_file) {
