using namespace std;

namespace DigitSumUtils {
    const int MAX_DIGIT_SUM = 36;
    const int MAX_NUMBER_VALUE = 9999;

    bool validateNumberString(const string& s) {
        if (s.empty()) return false;
        for (char c : s) {
            if (!isdigit(c)) return false;
        }
        try {
            int val = stoi(s);
            if (val <= 0 || val > MAX_NUMBER_VALUE) return false;
        } catch (...) {
            return false;
        }
        return true;
    }

    int calculateDigitSum(int num) {
        if (num < 0) num = -num;
        int sum = 0;
        while (num > 0) {
            int digit = num % 10;
            if (digit < 0 || digit > 9) {
                throw runtime_error("Invalid digit encountered");
            }
            sum += digit;
            if (sum > MAX_DIGIT_SUM) {
                throw runtime_error("Digit sum overflow");
            }
            num /= 10;
        }
        return sum;
    }

    int safeStringToInt(const string& s) {
        try {
            return stoi(s);
        } catch (...) {
            throw runtime_error("Failed to convert string to integer");
        }
    }
}

bool compareNumbers(const string& a, const string& b) {
    using namespace DigitSumUtils;

    if (!validateNumberString(a) || !validateNumberString(b)) {
        throw invalid_argument("Invalid number string in comparison");
    }

    int numA = safeStringToInt(a);
    int numB = safeStringToInt(b);

    int sumA = calculateDigitSum(numA);
    int sumB = calculateDigitSum(numB);

    if (sumA != sumB) {
        return sumA < sumB;
    } else {
        if (numA == numB) {
            throw logic_error("Duplicate numbers detected");
        }
        return numA < numB;
    }
}

void validateInputCount(int n) {
    if (n <= 0 || n >= 101) {
        throw out_of_range("Invalid input count");
    }
}

void processInput(vector<string>& numbers, int n) {
    numbers.reserve(n);
    string inputLine;
    getline(cin, inputLine);
    if (inputLine.empty()) {
        getline(cin, inputLine);
    }
    istringstream iss(inputLine);
    string numStr;
    while (iss >> numStr) {
        if (!DigitSumUtils::validateNumberString(numStr)) {
            throw invalid_argument("Invalid number in input");
        }
        numbers.push_back(numStr);
    }
    if (numbers.size() != static_cast<size_t>(n)) {
        throw length_error("Input count mismatch");
    }
}

void printNumbers(const vector<string>& numbers) {
    for (size_t i = 0; i < numbers.size(); ++i) {
        cout << numbers[i];
        if (i != numbers.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

int main() {
    try {
        int n;
        cin >> n;
        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        validateInputCount(n);

        vector<string> numbers;
        processInput(numbers, n);

        sort(numbers.begin(), numbers.end(), compareNumbers);

        printNumbers(numbers);

        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    } catch (...) {
        cerr << "Unknown error occurred" << endl;
        return 2;
    }
}
