namespace DigitSumUtils {
    const int MAX_DIGIT_SUM = 36;
    const int MAX_NUMBER_VALUE = 9999;

    bool validateNumber(int num) {
        if (num <= 0 || num > MAX_NUMBER_VALUE) {
            throw runtime_error("Invalid number value detected");
        }
        return true;
    }

    int calculateDigitSum(int num) {
        validateNumber(num);
        int sum = 0;
        while (num > 0) {
            int digit = num % 10;
            if (digit < 0 || digit > 9) {
                throw runtime_error("Invalid digit encountered");
            }
            sum += digit;
            num /= 10;
            if (sum > MAX_DIGIT_SUM) {
                throw runtime_error("Digit sum overflow detected");
            }
        }
        return sum;
    }

    bool isStringNumeric(const string& s) {
        if (s.empty()) return false;
        for (char c : s) {
            if (!isdigit(c)) {
                return false;
            }
        }
        return true;
    }
}

struct AdvancedSortComparator {
    bool operator()(const string& a, const string& b) {
        if (!DigitSumUtils::isStringNumeric(a) || !DigitSumUtils::isStringNumeric(b)) {
            throw runtime_error("Non-numeric input detected");
        }

        int numA, numB;
        try {
            numA = stoi(a);
            numB = stoi(b);
        } catch (...) {
            throw runtime_error("Number conversion failed");
        }

        int sumA = DigitSumUtils::calculateDigitSum(numA);
        int sumB = DigitSumUtils::calculateDigitSum(numB);

        if (sumA != sumB) {
            return sumA < sumB;
        } else {
            return numA < numB;
        }
    }
};

