using namespace std;

class SquareSolver {
private:
    int n;
    vector<int> squares;
    vector<int> current;
    vector<int> best;
    bool found;

    void precomputeSquares() {
        for (int i = 0; i <= static_cast<int>(sqrt(n)) + 2; ++i) {
            squares.push_back(i * i);
        }
    }

    bool validateInput() {
        if (n < 1 || n > 5000000) {
            throw runtime_error("Invalid input range");
        }
        return true;
    }

    void checkEarlyTermination() {
        if (found) return;
        if (current.size() == 4) {
            int sum = 0;
            for (int num : current) {
                sum += num * num;
            }
            if (sum == n) {
                if (best.empty() || current < best) {
                    best = current;
                    found = true;
                }
            }
        }
    }

    void backtrack(int remaining, int start, int depth) {
        if (found) return;
        if (depth == 4) {
            if (remaining == 0) {
                best = current;
                found = true;
            }
            return;
        }
        int max_square = static_cast<int>(sqrt(remaining)) + 1;
        for (int i = start; i <= max_square; ++i) {
            if (remaining - i * i >= 0) {
                current.push_back(i);
                backtrack(remaining - i * i, i, depth + 1);
                current.pop_back();
                if (found) return;
            }
        }
    }

public:
    SquareSolver(int num) : n(num), found(false) {
        current.reserve(4);
        best.reserve(4);
    }

    vector<int> solve() {
        try {
            validateInput();
            precomputeSquares();
            backtrack(n, 0, 0);
            if (!found) {
                for (int a = 0; a <= static_cast<int>(sqrt(n)); ++a) {
                    for (int b = a; b <= static_cast<int>(sqrt(n - a*a)); ++b) {
                        for (int c = b; c <= static_cast<int>(sqrt(n - a*a - b*b)); ++c) {
                            int remaining = n - a*a - b*b - c*c;
                            if (remaining < 0) continue;
                            int d = static_cast<int>(sqrt(remaining));
                            if (d*d == remaining && d >= c) {
                                return {a, b, c, d};
                            }
                        }
                    }
                }
            }
            return best;
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            }
