struct SolutionValidator {
    static bool validate(int n, int a, int b, int c, int d) {
        long long sum = static_cast<long long>(a)*a + static_cast<long long>(b)*b + static_cast<long long>(c)*c + static_cast<long long>(d)*d;
        return sum == n;
    }
};

class FourSquaresFinder {
private:
    int n;
    vector<tuple<int, int, int, int>> possible_solutions;

    void check_and_store(int a, int b, int c, int d) {
        if (SolutionValidator::validate(n, a, b, c, d)) {
            possible_solutions.emplace_back(a, b, c, d);
        }
    }

public:
    explicit FourSquaresFinder(int num) : n(num) {
        if (n <= 0) {
            throw invalid_argument("Input must be positive");
        }
    }

    void find_solutions() {
        int max_a = static_cast<int>(sqrt(n)) + 2;
        for (int a = 0; a <= max_a; ++a) {
            int remaining_after_a = n - a*a;
            if (remaining_after_a < 0) continue;

            int max_b = static_cast<int>(sqrt(remaining_after_a)) + 2;
            for (int b = 0; b <= max_b; ++b) {
                int remaining_after_b = remaining_after_a - b*b;
                if (remaining_after_b < 0) continue;

                int max_c = static_cast<int>(sqrt(remaining_after_b)) + 2;
                for (int c = 0; c <= max_c; ++c) {
                    int remaining_after_c = remaining_after_b - c*c;
                    if (remaining_after_c < 0) continue;

                    int d = static_cast<int>(sqrt(remaining_after_c));
                    while (d*d < remaining_after_c) d++;
                    while (d*d > remaining_after_c) d--;

                    check_and_store(a, b, c, d);
                    check_and_store(a, b, c, d+1);
                    check_and_store(a, b, c, d-1);
                }
            }
        }
    }

    tuple<int, int, int, int> get_lex_smallest() {
        if (possible_solutions.empty()) {
            throw runtime_error("No solutions found");
        }
        sort(possible_solutions.begin(), possible_solutions.end());
        return possible_solutions[0];
    }
};

int main() {
    ifstream input_file("square.in");
    ofstream output_file("square.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "File opening failed" << endl;
        return EXIT_FAILURE;
    }

    int n;
    input_file >> n;

    try {
        FourSquaresFinder finder(n);
        finder.find_solutions();
        auto solution = finder.get_lex_smallest();

        output_file << get<0>(solution) << " " 
                    << get<1>(solution) << " " 
                    << get<2>(solution) << " " 
                    << get<3>(solution) << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    input_file.close();
    output_file.close();
    return EXIT_SUCCESS;
}
