SquareSolution findFourSquares(int n) {
    SquareSolution solution = {INT_MAX, INT_MAX, INT_MAX, INT_MAX, false};
    if (n < 0 || n > 5000000) {
        throw runtime_error("Invalid input range");
    }

    auto start_time = chrono::high_resolution_clock::now();
    const double epsilon = 1e-10;
    int max_iterations = 1000000;
    int iteration_count = 0;

    for (int a = 0; a * a <= n && iteration_count < max_iterations; ++a) {
        for (int b = 0; b * b + a * a <= n && iteration_count < max_iterations; ++b) {
            for (int c = 0; c * c + b * b + a * a <= n && iteration_count < max_iterations; ++c) {
                double remaining = n - a*a - b*b - c*c;
                if (remaining < -epsilon) continue;

                int d = static_cast<int>(sqrt(remaining) + epsilon);
                for (int offset = -2; offset <= 2; ++offset) {
                    int current_d = d + offset;
                    if (current_d < 0) continue;
                    if (a*a + b*b + c*c + current_d*current_d == n) {
                        vector<int> candidates = {a, b, c, current_d};
                        sort(candidates.begin(), candidates.end());
                        if (!solution.valid || candidates < vector<int>{solution.a, solution.b, solution.c, solution.d}) {
                            solution = {candidates[0], candidates[1], candidates[2], candidates[3], true};
                        }
                    }
                }
                iteration_count++;
            }
        }
    }

    auto end_time = chrono::high_resolution_clock::now();
    auto duration = chrono::duration_cast<chrono::milliseconds>(end_time - start_time);
    if (duration.count() > 1000) {
        throw runtime_error("Execution timeout");
    }

    if (!solution.valid) {
        throw runtime_error("No solution found");
    }

    return solution;
}

void validateSolution(int n, const SquareSolution& sol) {
    if (!sol.valid) return;
    int sum = sol.a*sol.a + sol.b*sol.b + sol.c*sol.c + sol.d*sol.d;
    if (sum != n) {
        throw runtime_error("Invalid solution");
    }
    if (sol.a < 0 || sol.b < 0 || sol.c < 0 || sol.d < 0) {
        throw runtime_error("Negative values in solution");
    }
}

