        if (!fin.is_open()) {
            return false;
        }
        return true;
    }

    static bool safeOpenOutput(ofstream& fout, const string& filename) {
        fout.open(filename.c_str());
        if (!fout.is_open()) {
            return false;
        }
        return true;
    }
};

class InputProcessor {
public:
    static bool parseInput(ifstream& fin, int& n) {
        if (!fin) return false;
        fin >> n;
        if (fin.fail()) return false;
        return true;
    }
};

class SolutionFinder {
public:
    static void findSolution(int n, int& a, int& b, int& c, int& d) {
        const int max_possible = static_cast<int>(sqrt(n)) + 2;
        bool solution_found = false;

        for (a = 0; a <= max_possible && !solution_found; ++a) {
            int remaining_after_a = n - a * a;
            if (remaining_after_a < 0) continue;

            for (b = 0; b <= max_possible && !solution_found; ++b) {
                int remaining_after_b = remaining_after_a - b * b;
                if (remaining_after_b < 0) continue;

                for (c = 0; c <= max_possible && !solution_found; ++c) {
                    int remaining_after_c = remaining_after_b - c * c;
                    if (remaining_after_c < 0) continue;

                    d = static_cast<int>(sqrt(remaining_after_c));
                    if (d < 0) continue;

                    int calculated_d_squared = d * d;
                    if (calculated_d_squared == remaining_after_c) {
                        solution_found = true;
                    } else {
                        int d_plus_1 = d + 1;
                        int d_plus_1_squared = d_plus_1 * d_plus_1;
                        if (d_plus_1_squared == remaining_after_c) {
                            d = d_plus_1;
                            solution_found = true;
                        }
                    }
                }
            }
        }
    }
};

