bool validateNumberPlate(const string& s) {
    if(s.empty() || s.length() > 10) return false;
    for(char c : s) {
        if(!isdigit(c)) return false;
    }
    return true;
}

long long convertToNumber(const string& s) {
    stringstream ss(s);
    long long num;
    ss >> num;
    return num;
}

int calculateDigitSum(long long num) {
    int sum = 0;
    long long temp = abs(num);
    while(temp > 0) {
        int digit = temp % 10;
        sum += digit;
        temp /= 10;
    }
    return sum;
}

bool compareNumberPlates(const NumberPlate& a, const NumberPlate& b) {
    if(a.digit_sum != b.digit_sum) {
        return a.digit_sum < b.digit_sum;
    } else {
        return a.numeric_value > b.numeric_value;
    }
}

