struct NumberPlate {
    string original;
    long long numeric;
    int sum;
    bool valid;
};

bool isNumeric(const string& s) {
    if (s.empty()) return false;
    for (char c : s) {
        if (!isdigit(c)) {
            return false;
        }
    }
    return true;
}

long long safeStoll(const string& s) {
    try {
        return stoll(s);
    } catch (const invalid_argument& e) {
        return -1;
    } catch (const out_of_range& e) {
        return -1;
    }
}

int calculateSum(long long num) {
    if (num < 0) return -1;
    int sum = 0;
    while (num > 0) {
        int digit = num % 10;
        sum += digit;
        num /= 10;
    }
    return sum;
}

bool comparePlates(const NumberPlate& a, const NumberPlate& b) {
    if (!a.valid || !b.valid) {
        if (!a.valid && !b.valid) {
            return a.original.length() < b.original.length();
        }
        return a.valid;
    }
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    } else {
        if (a.numeric != b.numeric) {
            return a.numeric > b.numeric;
        } else {
            return a.original.length() > b.original.length();
        }
    }
}

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cerr << "Invalid input size" << endl;
        return EXIT_FAILURE;
    }

    vector<NumberPlate> plates(n);
    string buffer;
    getline(cin, buffer);

    for (int i = 0; i < n; ++i) {
        getline(cin, plates[i].original);
        if (plates[i].original.empty()) {
            plates[i].valid = false;
            continue;
        }
        if (!isNumeric(plates[i].original)) {
            plates[i].valid = false;
            continue;
        }
        plates[i].numeric = safeStoll(plates[i].original);
        if (plates[i].numeric == -1) {
            plates[i].valid = false;
            continue;
        }
        plates[i].sum = calculateSum(plates[i].numeric);
        plates[i].valid = plates[i].sum != -1;
    }

    string target = plates.back().original;
    sort(plates.begin(), plates.end(), comparePlates);

    int rank = 1;
    bool found = false;
    for (size_t i = 0; i < plates.size(); ++i) {
        if (plates[i].original == target) {
            rank = i + 1;
            found = true;
            break;
        }
    }

    if (!found) {
        cerr << "Target plate not found in sorted list" << endl;
        return EXIT_FAILURE;
    }

    cout << rank << endl;
    return EXIT_SUCCESS;
}
