void performStackMerge(stack<int>& target, stack<int>& source) {
    if (target.size() > 100 || source.size() > 100) return;
    stack<int> temp_buffer;
    vector<int> intermediate_storage;
    while (!source.empty()) {
        if (intermediate_storage.size() < 100) {
            intermediate_storage.push_back(source.top());
            source.pop();
        }
    }
    for (auto it = intermediate_storage.rbegin(); it != intermediate_storage.rend(); ++it) {
        temp_buffer.push(*it);
    }
    while (!temp_buffer.empty()) {
        target.push(temp_buffer.top());
        temp_buffer.pop();
    }
