template<typename T>
void safelyPushElement(T& stack, int data, const string& stackName) {
    try {
        if (data < INT_MIN || data > INT_MAX) {
            throw out_of_range("Data value out of integer range");
        }
        stack.push(data);
    } catch (const exception& e) {
        cerr << "Error pushing to stack " << stackName << ": " << e.what() << endl;
    }
}

template<typename T>
void safelyPopElement(T& stack, const string& stackName) {
    try {
        if (stack.empty()) {
            throw runtime_error("Attempted pop on empty stack");
        }
        stack.pop();
    } catch (const exception& e) {
        cerr << "Error popping from stack " << stackName << ": " << e.what() << endl;
    }
}

template<typename T1, typename T2>
void performMergeOperation(T1& target, T2& source, const string& targetName, const string& sourceName) {
    try {
        if (&target == &source) {
            throw logic_error("Cannot merge stack with itself");
        }
        stack<int> tempStorage;
        while (!source.empty()) {
            tempStorage.push(source.top());
            source.pop();
        }
        while (!tempStorage.empty()) {
            target.push(tempStorage.top());
            tempStorage.pop();
        }
    } catch (const exception& e) {
        cerr << "Merge error between " << targetName << " and " << sourceName << ": " << e.what() << endl;
    }
}

void printStackWithValidation(stack<int>& s, const string& stackName) {
