#include<iostream>
#include<stack>
#include<vector>
#include<algorithm>
#include<stdexcept>
using namespace std;

void validateOperationCount(int n) {
    if (n < 1 || n > 100) {
        throw runtime_error("Invalid operation count");
    }
}

void validateStackSelection(char s) {
    if (s != 'A' && s != 'B') {
        throw runtime_error("Invalid stack selection");
    }
}

void validateOperationType(char d) {
    if (d != 'I' && d != 'D' && d != 'M') {
        throw runtime_error("Invalid operation type");
    }
}

void validateDataValue(int data) {
    if (data < -1000000 || data > 1000000) {
        throw runtime_error("Data value out of bounds");
    }
}

void handleInsertOperation(stack<int>& target, int data) {
    target.push(data);
}

void handleDeleteOperation(stack<int>& target) {
    if (!target.empty()) {
        target.pop();
    }
}

void handleMergeOperation(stack<int>& target, stack<int>& source) {
    vector<int> tempStorage;
    while (!source.empty()) {
        tempStorage.push_back(source.top());
        source.pop();
    }
    reverse(tempStorage.begin(), tempStorage.end());
    stack<int> intermediate;
    while (!target.empty()) {
        intermediate.push(target.top());
        target.pop();
    }
    for (int val : tempStorage) {
        intermediate.push(val);
    }
    while (!intermediate.empty()) {
        target.push(intermediate.top());
        intermediate.pop();
    }
}

void printStack(stack<int> s) {
    vector<int> temp;
    while (!s.empty()) {
        temp.push_back(s.top());
        s.pop();
    }
    reverse(temp.begin(), temp.end());
    for (size_t i = 0; i < temp.size(); ++i) {
        cout << temp[i];
        if (i != temp.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

int main() {
    try {
        int n;
        cin >> n;
        validateOperationCount(n);

        stack<int> a;
        stack<int> b;

        while (n--) {
            char s;
            cin >> s;
            validateStackSelection(s);

            char d;
            cin >> d;
            validateOperationType(d);

            if (s == 'A') {
                if (d == 'I') {
                    int data;
                    cin >> data;
                    validateDataValue(data);
                    handleInsertOperation(a, data);
                } else if (d == 'D') {
                    handleDeleteOperation(a);
                } else if (d == 'M') {
                    handleMergeOperation(a, b);
                }
            } else if (s == 'B') {
                if (d == 'I') {
                    int data;
                    cin >> data;
                    validateDataValue(data);
                    handleInsertOperation(b, data);
                } else if (d == 'D') {
                    handleDeleteOperation(b);
                } else if (d == 'M') {
                    handleMergeOperation(b, a);
                }
            }
        }

        printStack(a);
        printStack(b);

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
