            while (getline(iss, token, ' ')) {
                if (!validateIntegerInput(token)) {
                    throw invalid_argument("Invalid integer input detected");
                }
                try {
                    numbers.push_back(stoi(token));
                } catch (const out_of_range&) {
                    throw out_of_range("Input integer out of range");
                }
                if (numbers.size() > 2) {
                    throw length_error("More than two integers provided");
                }
