        throw invalid_argument("Invalid character in input");
    }
}

void validateStackOperation(const stack<char>& s, const string& context) {
    if (s.empty()) {
        throw runtime_error("Stack underflow in " + context);
    }
}

string safelyExtractSubstring(stack<char>& s) {
    string tmp;
    while (true) {
        validateStackOperation(s, "safelyExtractSubstring");
        if (s.top() == '(') break;
        tmp += s.top();
        s.pop();
    }
    reverse(tmp.begin(), tmp.end());
    return tmp;
}

string processRepetition(stack<char>& s, const string& tmp) {
    string x;
    if (!s.empty() && isdigit(s.top())) {
        int num = s.top() - '0';
        if (num < 1 || num > 9) {
            throw out_of_range("Repetition count out of bounds");
        }
        for (int j = 0; j < num; j++) {
            x += tmp;
        }
        s.pop();
    } else {
        x = tmp;
    }
    return x;
}

void handleNestedParentheses(stack<char>& s, int& i, const string& str) {
    if (!s.empty() && s.top() == '(' && i + 1 < str.size() && str[i + 1] == ')') {
        s.pop();
        i++;
    }
}

void pushProcessedString(stack<char>& s, const string& x) {
    for (size_t j = 0; j < x.size(); j++) {
        s.push(x[j]);
    }
}

string buildFinalResult(stack<char>& s) {
    string str2;
    while (!s.empty()) {
        str2 += s.top();
        s.pop();
    }
    reverse(str2.begin(), str2.end());
    return str2;
}

