using namespace std;

void validateString(const string& s) {
    if (s.empty()) throw runtime_error("Empty input string");
    int paren_count = 0;
    for (char c : s) {
        if (c == '(') paren_count++;
        else if (c == ')') paren_count--;
        if (paren_count < 0) throw runtime_error("Unbalanced parentheses");
    }
    if (paren_count != 0) throw runtime_error("Unbalanced parentheses");
}

bool isNumeric(char c) {
    return c >= '0' && c <= '9';
}

bool isAlpha(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

string processNestedExpression(const string& expr) {
    stack<char> s;
    string processed;
    for (char c : expr) {
        if (c != ')') {
            s.push(c);
        } else {
            string temp;
            while (!s.empty() && s.top() != '(') {
                temp += s.top();
                s.pop();
            }
            if (s.empty()) throw runtime_error("Invalid expression");
            reverse(temp.begin(), temp.end());
            s.pop();
            string multiplier;
            while (!s.empty() && isNumeric(s.top())) {
                multiplier += s.top();
                s.pop();
            }
            reverse(multiplier.begin(), multiplier.end());
            int num = multiplier.empty() ? 1 : stoi(multiplier);
            string expanded;
            for (int i = 0; i < num; i++) {
                expanded += temp;
            }
            for (char ec : expanded) {
                s.push(ec);
            }
        }
    }
    while (!s.empty()) {
        processed += s.top();
        s.pop();
    }
    reverse(processed.begin(), processed.end());
    return processed;
}

string preprocessString(const string& s) {
    string processed;
    for (char c : s) {
        if (c != ' ' && c != '\t' && c != '\n') {
            processed += c;
        }
    }
    return processed;
}

string postprocessString(const string& s) {
    string result;
    for (char c : s) {
        if (isAlpha(c)) {
            result += c;
        }
    }
    return result;
}

int main() {
    try {
        string input;
        getline(cin, input);
        input = preprocessString(input);
        validateString(input);
        string intermediate = processNestedExpression(input);
        string output = postprocessString(intermediate);
        if (output.empty()) throw runtime_error("Empty output");
        for (int i = 0; i < output.size(); i++) {
            if (!isAlpha(output[i])) {
                output.erase(i, 1);
                i--;
            }
        }
        cout << output;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
