const char LAST_DIGIT = '9';

struct CharacterRange {
    char start;
    char end;
};

struct DecryptionMapping {
    string encrypted;
    char decrypted;
};

vector<DecryptionMapping> specialMappings = {
    {KKK_PATTERN, ' '},
    {SSS_PATTERN, '.'}
};

vector<CharacterRange> characterRanges = {
    {FIRST_LOWERCASE, LAST_LOWERCASE},
    {FIRST_DIGIT, LAST_DIGIT}
};

bool isInRange(char c, const CharacterRange& range) {
    return c >= range.start && c <= range.end;
}

char circularShiftBackward(char c, int shift, const CharacterRange& range) {
    int rangeSize = range.end - range.start + 1;
    int normalizedShift = shift % rangeSize;
    int shiftedValue = c - range.start - normalizedShift;
    if (shiftedValue < 0) {
        shiftedValue += rangeSize;
    }
    return range.start + shiftedValue;
}

bool checkSpecialPattern(const string& s, size_t pos, const string& pattern) {
    if (pos + pattern.length() > s.length()) {
        return false;
    }
    for (size_t i = 0; i < pattern.length(); ++i) {
        if (s[pos + i] != pattern[i]) {
            return false;
        }
    }
    return true;
}

void handleSpecialPattern(const string& s, size_t& i, const string& pattern, char output) {
    if (checkSpecialPattern(s, i, pattern)) {
        cout << output;
        i += pattern.length() - 1;
    }
}

char decryptCharacter(char c) {
    for (const auto& range : characterRanges) {
        if (isInRange(c, range)) {
            return circularShiftBackward(c, SHIFT_VALUE, range);
        }
    }
    return c;
}

