#include<bits/stdc++.h>
using namespace std;

struct CompressionState {
    char current_char;
    int current_count;
    bool is_first_char;
    bool is_first_line;
    bool is_first_char_in_line;
    bool has_printed_n;
    vector<int> compression_sequence;
};

void initializeCompressionState(CompressionState& state) {
    state.current_char = '\0';
    state.current_count = 0;
    state.is_first_char = true;
    state.is_first_line = true;
    state.is_first_char_in_line = true;
    state.has_printed_n = false;
}

void handleCharacterProcessing(CompressionState& state, char input_char) {
    if (state.is_first_char) {
        state.current_char = input_char;
        state.current_count = 1;
        state.is_first_char = false;
    } else {
        if (input_char == state.current_char) {
            state.current_count++;
        } else {
            state.compression_sequence.push_back(state.current_count);
            state.current_char = input_char;
            state.current_count = 1;
        }
    }
}

void processInputMatrix(CompressionState& state, int n) {
    string current_line;
    for (int line_index = 0; line_index < n; line_index++) {
        cin >> current_line;
        for (int char_index = 0; char_index < n; char_index++) {
            char current_char = current_line[char_index];
            handleCharacterProcessing(state, current_char);
        }
    }
    state.compression_sequence.push_back(state.current_count);
}

void outputCompressionResult(const CompressionState& state, int n) {
    ofstream output_file("zip.out");
    if (!output_file.is_open()) {
        cerr << "Error opening output file" << endl;
        exit(1);
    }

    output_file << n << " ";
    for (size_t i = 0; i < state.compression_sequence.size(); i++) {
        output_file << state.compression_sequence[i];
        if (i != state.compression_sequence.size() - 1) {
            output_file << " ";
        }
    }
    output_file.close();
}

