#include<bits/stdc++.h>
using namespace std;

struct CompressionState {
    char current_char;
    int count;
    bool initialized;
    bool first_output;
    bool error_occurred;
};

void initialize_compression_state(CompressionState& state, char first_char) {
    state.current_char = first_char;
    state.count = 1;
    state.initialized = true;
    state.first_output = true;
    state.error_occurred = false;
}

void handle_character(CompressionState& state, char new_char, ostream& output) {
    if (!state.initialized) {
        state.error_occurred = true;
        return;
    }

    if (new_char == state.current_char) {
        state.count++;
    } else {
        if (!state.first_output) {
            output << " ";
        } else {
            state.first_output = false;
        }
        output << state.count;
        state.current_char = new_char;
        state.count = 1;
    }
}

void finalize_compression(CompressionState& state, ostream& output) {
    if (state.error_occurred) {
        output << "ERROR_IN_COMPRESSION";
        return;
    }

    if (!state.first_output) {
        output << " ";
    }
    output << state.count;
}

int main() {
    ifstream input_file("zip.in");
    ofstream output_file("zip.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "File opening failed" << endl;
        return EXIT_FAILURE;
    }

    vector<string> matrix;
    string line;
    while (getline(input_file, line)) {
        if (!line.empty()) {
            matrix.push_back(line);
        }
    }

    if (matrix.empty()) {
        output_file << "EMPTY_INPUT";
        return EXIT_SUCCESS;
    }

    int n = matrix[0].size();
    output_file << n << " ";

    CompressionState state;
    initialize_compression_state(state, matrix[0][0]);

    for (int i = 0; i < matrix.size(); i++) {
        if (matrix[i].size() != n) {
            output_file << "INCONSISTENT_ROW_LENGTH";
            return EXIT_FAILURE;
        }

        for (int j = 0; j < matrix[i].size(); j++) {
            if (i == 0 && j == 0) continue;
            if (matrix[i][j] != '0' && matrix[i][j] != '1') {
                output_file << "INVALID_CHARACTER";
                return EXIT_FAILURE;
            }
            handle_character(state, matrix[i][j], output_file);
            if (state.error_occurred) {
                output_file << "COMPRESSION_ERROR";
                return EXIT_FAILURE;
            }
        }
    }

    finalize_compression(state, output_file);

    int total_sum = 0;
    output_file.seekp(0);
    string output_content;
    getline(output_file, output_content);
    istringstream iss(output_content);
    int val;
    iss >> val;
    while (iss >> val) {
        total_sum += val;
    }

    if (total_sum != n * n) {
        ofstream error_file("zip.out");
        error_file << "COMPRESSION_SUM_MISMATCH";
        return EXIT_FAILURE;
    }

    input_file.close();
    output_file.close();

    return EXIT_SUCCESS;
}
