#include <bits/stdc++.h>
using namespace std;

const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const char NUMERIC_WRAP_START = '0';
const char NUMERIC_WRAP_END = '9';
const char ALPHA_WRAP_START = 'a';
const char ALPHA_WRAP_END = 'z';
const int ALPHA_WRAP_LENGTH = 26;
const int NUMERIC_WRAP_LENGTH = 10;

string performSafeReplacement(const string& input, const string& target, const string& replacement) {
    string result = input;
    size_t position = result.find(target);
    while (position != string::npos) {
        if (position + target.length() <= result.length()) {
            result.replace(position, target.length(), replacement);
        } else {
            break;
        }
        position = result.find(target, position + replacement.length());
    }
    return result;
}

char handleAlphaShift(char c) {
    if (c >= 'd' && c <= 'z') {
        return c - SHIFT_VALUE;
    } else if (c >= 'a' && c <= 'c') {
        return (c - ALPHA_WRAP_START - SHIFT_VALUE + ALPHA_WRAP_LENGTH) % ALPHA_WRAP_LENGTH + NUMERIC_WRAP_START;
    }
    return c;
}

char handleNumericShift(char c) {
    if (c >= '3' && c <= '9') {
        return c - SHIFT_VALUE;
    } else if (c >= '0' && c <= '2') {
        return (c - NUMERIC_WRAP_START - SHIFT_VALUE + NUMERIC_WRAP_LENGTH) % NUMERIC_WRAP_LENGTH + 'x';
    }
    return c;
}

char decryptCharacter(char c) {
    if (isalpha(c)) {
        return handleAlphaShift(c);
    } else if (isdigit(c)) {
        return handleNumericShift(c);
    }
    return c;
}

string processString(const string& input) {
    string intermediateResult = performSafeReplacement(input, DOT_REPLACEMENT, ".");
    intermediateResult = performSafeReplacement(intermediateResult, SPACE_REPLACEMENT, " ");
    string finalResult;
    for (size_t i = 0; i < intermediateResult.length(); ++i) {
        char processedChar = decryptCharacter(intermediateResult[i]);
        finalResult.push_back(processedChar);
    }
    return finalResult;
}

int main() {
