string performSafeReplacement(const string& input, const string& target, const string& replacement) {
    string result = input;
    size_t position = result.find(target);
    while (position != string::npos) {
        if (position + target.length() <= result.length()) {
            result.replace(position, target.length(), replacement);
        } else {
            break;
        }
        position = result.find(target, position + replacement.length());
    }
    return result;
}

char handleCharacterShift(char c) {
    if (c >= 'd' && c <= 'z') {
        return static_cast<char>(c - SHIFT_VALUE);
    } else if (c >= '3' && c <= '9') {
        return static_cast<char>(c - SHIFT_VALUE);
    } else if (c >= 'a' && c <= 'c') {
        return static_cast<char>(NUMERIC_SHIFT_BASE + (c - ALPHA_WRAP_START));
    } else if (c >= '0' && c <= '2') {
        return static_cast<char>(ALPHA_SHIFT_BASE + (c - NUMERIC_WRAP_START + 1));
    }
    return c;
}

string processCharacterDecryption(const string& input) {
