    } else if (c >= 'a' && c <= 'c') {
        return 'x' + (c - 'a' + 1);
    } else if (c >= '3' && c <= '9') {
        return c - 3;
    } else if (c >= '0' && c <= '2') {
        return 'a' + (c - '0' + 7) % 26;
    } else {
