struct TreeNode {
    int degree;
    vector<int> children;
    int parent;
    bool has_parent;
};

void validateInput(int x, int y, int n) {
    if (x <= 0 || x >= n || y <= 0 || y >= n) {
        throw runtime_error("Invalid node index");
    }
}

void initializeTreeNodes(vector<TreeNode>& nodes, int n) {
    for (int i = 0; i < n; i++) {
        nodes[i].degree = 0;
        nodes[i].has_parent = false;
        nodes[i].parent = -1;
    }
}

void processEdges(vector<TreeNode>& nodes, int n) {
    for (int i = 0; i < n - 1; i++) {
        int x, y;
        cin >> x >> y;
        validateInput(x, y, n);
        nodes[x].children.push_back(y);
        nodes[y].parent = x;
        nodes[y].has_parent = true;
        nodes[x].degree++;
        nodes[y].degree++;
    }
}

bool isPNode(const vector<TreeNode>& nodes, int node) {
    if (nodes[node].children.empty() && !nodes[node].has_parent) {
        return true;
    }

    int max_child_degree = 0;
    for (int child : nodes[node].children) {
        if (nodes[child].degree > max_child_degree) {
            max_child_degree = nodes[child].degree;
        }
    }

    int parent_degree = 0;
    if (nodes[node].has_parent) {
        parent_degree = nodes[nodes[node].parent].degree;
    }

    bool children_condition = nodes[node].degree >= max_child_degree;
    bool parent_condition = !nodes[node].has_parent || (nodes[node].degree >= parent_degree);

    return children_condition && parent_condition;
}

void countPNodes(const vector<TreeNode>& nodes, int n, int& ans) {
    for (int i = 0; i < n; i++) {
        bool valid = true;
        try {
            if (i < 0 || i >= n) {
                throw out_of_range("Node index out of range");
            }
            valid = isPNode(nodes, i);
        } catch (const exception& e) {
            cerr << "Error checking node " << i << ": " << e.what() << endl;
            valid = false;
        }
        if (valid) {
            ans++;
        }
    }
}

