#include<bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 1005;
const int MIN_DIMENSION = 1;
const char BUSH = '#';
const char SPACE = '.';

struct CoordinateValidationResult {
    bool is_valid;
    int validated_x;
    int validated_y;
};

struct GridTraversalContext {
    char grid[MAX_DIMENSION][MAX_DIMENSION];
    bool visited[MAX_DIMENSION][MAX_DIMENSION];
    int rows;
    int columns;
    int grassland_count;
};

CoordinateValidationResult validate_coordinates(int potential_x, int potential_y, int max_rows, int max_cols) {
    CoordinateValidationResult result;
    result.is_valid = (potential_x >= 0) && (potential_x < max_rows) && (potential_y >= 0) && (potential_y < max_cols);
    result.validated_x = potential_x;
    result.validated_y = potential_y;
    return result;
}

void initialize_visited(GridTraversalContext* context) {
    for (int i = 0; i < context->rows; ++i) {
        for (int j = 0; j < context->columns; ++j) {
            context->visited[i][j] = false;
        }
    }
}

void perform_depth_first_search(int current_x, int current_y, GridTraversalContext* context) {
    const int direction_vectors[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    context->visited[current_x][current_y] = true;

    for (int direction_index = 0; direction_index < 4; ++direction_index) {
        int neighbor_x = current_x + direction_vectors[direction_index][0];
        int neighbor_y = current_y + direction_vectors[direction_index][1];

        CoordinateValidationResult validation = validate_coordinates(neighbor_x, neighbor_y, context->rows, context->columns);

        if (validation.is_valid && 
            context->grid[validation.validated_x][validation.validated_y] == BUSH && 
            !context->visited[validation.validated_x][validation.validated_y]) {
            perform_depth_first_search(validation.validated_x, validation.validated_y, context);
        }
    }
}

void process_input_dimensions(ifstream& input_stream, int* rows, int* columns) {
    input_stream >> *rows >> *columns;
    if (*rows < MIN_DIMENSION || *rows > MAX_DIMENSION || *columns < MIN_DIMENSION || *columns > MAX_DIMENSION) {
        cerr << "Invalid grid dimensions detected" << endl;
        exit(EXIT_FAILURE);
    }
}

void populate_grid(ifstream& input_stream, GridTraversalContext* context) {
    for (int row_index = 0; row_index < context->rows; ++row_index) {
        string current_row;
        input_stream >> current_row;
        if (current_row.length() != context->columns) {
            cerr << "Row length mismatch detected" << endl;
            exit(EXIT_FAILURE);
        }
        for (int col_index = 0; col_index < context->columns; ++col_index) {
            context->grid[row_index][col_index] = current_row[col_index];
        }
    }
}

void count_grasslands(GridTraversalContext* context) {
