    for (int i = 0; i < map.height; ++i) {
        for (int j = 0; j < map.width; ++j) {
            map.visited[i][j] = false;
        }
    }
}

void performDepthFirstSearch(Coordinate current, CanyonMap& map) {
    map.visited[current.x][current.y] = true;

    for (int direction_index = 0; direction_index < DIRECTION_COUNT; ++direction_index) {
        Coordinate neighbor = {
            current.x + DIRECTION_OFFSETS[direction_index].x,
            current.y + DIRECTION_OFFSETS[direction_index].y
        };

        if (validateCoordinate(neighbor, map)) {
            if (!map.visited[neighbor.x][neighbor.y] && map.terrain[neighbor.x][neighbor.y] == BUSH) {
                performDepthFirstSearch(neighbor, map);
            }
        }
    }
}

int countGrasslands(CanyonMap& map) {
    int grassland_count = 0;

    for (int i = 0; i < map.height; ++i) {
        for (int j = 0; j < map.width; ++j) {
            Coordinate current = {i, j};
            if (!map.visited[current.x][current.y] && map.terrain[current.x][current.y] == BUSH) {
                ++grassland_count;
                performDepthFirstSearch(current, map);
            }
        }
    }

    return grassland_count;
}

