    input_file >> map.height >> map.width;

    for (int i = 0; i < map.height; ++i) {
        string row;
        input_file >> row;
        for (int j = 0; j < map.width; ++j) {
            map.terrain[i][j] = row[j];
        }
    }

    input_file.close();
}

void writeOutputFile(int result) {
    ofstream output_file("hiking.out");
