#include<bits/stdc++.h>
using namespace std;
#define int long long
#define MAX_N 20
#define MAX_K 400
#define INF 1e18

int dp[1<<MAX_N][MAX_N];
int a[MAX_N];
int bonus[MAX_N][MAX_N];
int n, m, k;
vector<pair<int, int>> suggestions[MAX_N];

void validate_input() {
    if(n < 1 || n > 18) throw runtime_error("Invalid n");
    if(m < 1 || m > n) throw runtime_error("Invalid m");
    if(k < 0 || k > n*(n-1)) throw runtime_error("Invalid k");
    for(int i = 0; i < n; i++) {
        if(a[i] < 0 || a[i] > 1e9) throw runtime_error("Invalid a_i");
    }
}

void initialize_dp() {
    for(int mask = 0; mask < (1<<n); mask++) {
        for(int i = 0; i < n; i++) {
            dp[mask][i] = -INF;
        }
    }
    for(int i = 0; i < n; i++) {
        dp[1<<i][i] = a[i];
    }
}

void process_suggestions() {
    for(int i = 0; i < k; i++) {
        int x, y, c;
        cin >> x >> y >> c;
        if(x < 1 || x > n || y < 1 || y > n) throw runtime_error("Invalid x or y");
        if(c < 0 || c > 1e9) throw runtime_error("Invalid c_i");
        x--; y--;
        if(bonus[x][y] != 0) throw runtime_error("Duplicate suggestion");
        bonus[x][y] = c;
        suggestions[x].push_back({y, c});
    }
}

void compute_transitions() {
    for(int mask = 0; mask < (1<<n); mask++) {
        for(int last = 0; last < n; last++) {
            if(!(mask & (1<<last)) || dp[mask][last] == -INF) continue;

            for(int next = 0; next < n; next++) {
                if(mask & (1<<next)) continue;

                int new_mask = mask | (1<<next);
                int new_value = dp[mask][last] + a[next];

                if(bonus[last][next] > 0) {
                    new_value += bonus[last][next];
                }

                if(new_value > dp[new_mask][next]) {
                    dp[new_mask][next] = new_value;
                }
            }
        }
    }
}

int find_max_satisfaction() {
    int max_satisfaction = -INF;
    for(int mask = 0; mask < (1<<n); mask++) {
        if(__builtin_popcount(mask) != m) continue;
        for(int last = 0; last < n; last++) {
            if(dp[mask][last] > max_satisfaction) {
                max_satisfaction = dp[mask][last];
            }
        }
    }
    return max_satisfaction;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    try {
        freopen("meal.in", "r", stdin);
        freopen("meal.out", "w", stdout);

        cin >> n >> m >> k;
        if(cin.fail()) throw runtime_error("Failed to read n, m, k");

        for(int i = 0; i < n; i++) {
            cin >> a[i];
            if(cin.fail()) throw runtime_error("Failed to read a_i");
        }

        validate_input();
        initialize_dp();
        process_suggestions();
        compute_transitions();

        int result = find_max_satisfaction();
        if(result == -INF) throw runtime_error("No valid path found");

        cout << result << endl;
    } catch(const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
