    char original = c;
    int normalizedShift = shiftAmount;

    while (normalizedShift < 0) {
        normalizedShift += 26;
    }

    if (c >= 'a' && c <= 'z') {
        int relativePos = c - 'a';
        int newPos = (relativePos + normalizedShift) % 26;
        while (newPos < 0) newPos += 26;
        c = 'a' + newPos;
        wasProcessed = true;
    } else if (c >= 'A' && c <= 'Z') {
        int relativePos = c - 'A';
        int newPos = (relativePos + normalizedShift) % 26;
        while (newPos < 0) newPos += 26;
        c = 'A' + newPos;
        wasProcessed = true;
    } else if (c >= '0' && c <= '9') {
        int relativePos = c - '0';
        int newPos = (relativePos + normalizedShift) % 10;
        while (newPos < 0) newPos += 10;
        c = '0' + newPos;
        wasProcessed = true;
    }

    if (!wasProcessed) {
        return original;
    }

    return c;
}

