        istringstream iss(input);
        string token;
        int count = 0;

        while(iss >> token) {
            if(count >= 3) {
                throw runtime_error("Too many input values");
            }
            if(!InputValidation::isInteger(token)) {
                throw invalid_argument("Invalid integer input");
            }
            long long val = stoll(token);
            InputValidation::validateRange(val);
            values.push_back(static_cast<int>(val));
            count++;
