void validate_node_range(int node, int n) {
    if (node < 0 || node >= n) {
        throw out_of_range("Node index out of bounds");
    }
}

int calculate_degree_with_memoization(int node) {
    if (degree_cache.find(node) != degree_cache.end()) {
        return degree_cache[node];
    }
    int degree = G[node].size();
    degree_cache[node] = degree;
    return degree;
}

void perform_dfs_to_set_parents(int node, int parent, int n) {
    validate_node_range(node, n);
    visited_flags[node] = true;
    parent_tracking[node] = parent;
    for (int neighbor : G[node]) {
        if (!visited_flags[neighbor] && neighbor != parent) {
            perform_dfs_to_set_parents(neighbor, node, n);
        }
    }
}

bool verify_p_node_conditions(int node, int n) {
    if (node < 0 || node >= n) return false;
    int current_degree = calculate_degree_with_memoization(node);
    bool meets_conditions = true;

    for (int child : G[node]) {
        if (child == parent_tracking[node]) continue;
        int child_degree = calculate_degree_with_memoization(child);
        if (current_degree < child_degree) {
            meets_conditions = false;
            break;
        }
    }

    if (parent_tracking[node] != -1) {
        int parent_degree = calculate_degree_with_memoization(parent_tracking[node]);
        if (current_degree < parent_degree) {
            meets_conditions = false;
        }
    }

    return meets_conditions;
}

void reset_global_state(int n) {
    for (int i = 0; i < n; ++i) {
        G[i].clear();
        visited_flags[i] = false;
        parent_tracking[i] = -1;
    }
    degree_cache.clear();
}

