struct InputValidationException : public runtime_error {
    using runtime_error::runtime_error;
};

struct CharacterProcessingException : public runtime_error {
    using runtime_error::runtime_error;
};

class CircularShiftValidator {
public:
    static bool validateShiftParameters(int x, int y, int z) {
        if (x <= 10 || x > 100) throw InputValidationException("Invalid x value");
        if (y <= 0 || y > 10) throw InputValidationException("Invalid y value");
        if (z <= 0 || z > 100) throw InputValidationException("Invalid z value");
        return true;
    }
};

class CharacterProcessor {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;

    static char processAlphabetChar(char c, int shift, bool isUpper) {
        if (!isalpha(c)) throw CharacterProcessingException("Non-alphabet character");
        char base = isUpper ? 'A' : 'a';
        int normalizedShift = shift % ALPHABET_SIZE;
        if (normalizedShift < 0) normalizedShift += ALPHABET_SIZE;
        return (c - base + normalizedShift) % ALPHABET_SIZE + base;
    }

    static char processDigitChar(char c, int shift) {
        if (!isdigit(c)) throw CharacterProcessingException("Non-digit character");
        int normalizedShift = shift % DIGIT_SIZE;
        if (normalizedShift < 0) normalizedShift += DIGIT_SIZE;
        return (c - '0' + normalizedShift) % DIGIT_SIZE + '0';
    }

public:
    static char processCharacter(char c, int shift) {
        try {
            if (isupper(c)) {
                return processAlphabetChar(c, shift, true);
            } else if (islower(c)) {
                return processAlphabetChar(c, shift, false);
            } else if (isdigit(c)) {
                return processDigitChar(c, shift);
            } else {
                throw CharacterProcessingException("Invalid character type");
            }
        } catch (const CharacterProcessingException& e) {
            return c;
        }
    }
};

class PositionValidator {
public:
    static bool isTargetPosition(int index, int y) {
        if (y <= 0) return false;
        return (index + 1) % y == 0;
    }
};

