    }
    return true;
}

char transformCharacter(char c, int shift, bool isKeyPosition) {
    if (!isKeyPosition) return c;

    int base = 0;
    int range = 0;

    if (isupper(c)) {
        base = 'A';
        range = 26;
    } else if (islower(c)) {
        base = 'a';
        range = 26;
    } else if (isdigit(c)) {
        base = '0';
        range = 10;
