using namespace std;

template<typename T>
void validate_input_range(const T& value) {
    static_assert(is_integral<T>::value, "Input must be an integer type");
    if (numeric_limits<T>::is_signed) {
        if (value < numeric_limits<T>::min() || value > numeric_limits<T>::max()) {
            throw out_of_range("Input value out of range for type");
        }
    }
}

vector<string> tokenize_input(const string& input) {
    vector<string> tokens;
    istringstream iss(input);
    string token;
    while (iss >> token) {
        tokens.push_back(token);
    }
    if (tokens.size() != 3) {
        throw invalid_argument("Exactly three integers must be provided");
    }
    return tokens;
}

template<typename T>
T safe_stoi(const string& str) {
    try {
        size_t pos;
        long long val = stoll(str, &pos);
        if (pos != str.size()) {
            throw invalid_argument("Invalid characters in input");
        }
        validate_input_range(val);
        return static_cast<T>(val);
    } catch (const invalid_argument& e) {
        throw invalid_argument("Invalid integer input: " + string(e.what()));
    } catch (const out_of_range& e) {
        throw out_of_range("Input value out of range: " + string(e.what()));
    }
}

void format_output(ostream& os, const vector<string>& values) {
    if (values.size() != 3) {
        throw logic_error("Internal error: Unexpected number of values to format");
    }
    for (size_t i = 0; i < values.size(); ++i) {
        try {
            int val = safe_stoi<int>(values[i]);
            os << setw(8) << val;
            if (i != values.size() - 1) {
                os << " ";
            }
        } catch (...) {
            throw;
        }
    }
}

int main() {
    try {
        string input_line;
        getline(cin, input_line);
        if (input_line.empty()) {
            throw runtime_error("Empty input received");
        }
        vector<string> tokens = tokenize_input(input_line);
        format_output(cout, tokens);
        cout << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
