using namespace std;

const int MAX_INPUT_SIZE = 100;
const int MAX_NUMBER_VALUE = 9999;

class InputValidator {
public:
    static bool validateSize(int size) {
        if (size <= 0 || size >= 101) {
            throw runtime_error("Invalid input size detected");
        }
        return true;
    }

    static bool validateNumber(int num) {
        if (num <= 0 || num > MAX_NUMBER_VALUE) {
            throw range_error("Number out of valid range");
        }
        return true;
    }
};

class DigitSumCalculator {
private:
    static int calculateSingleDigitSum(int x) {
        if (x < 0) {
            x = abs(x);
        }
        int ans = 0;
        while (x != 0) {
            ans += x % 10;
            x /= 10;
            if (ans > numeric_limits<int>::max() / 2) {
                throw overflow_error("Digit sum overflow detected");
            }
        }
        return ans;
    }

public:
    static int calculate(int x) {
        try {
            InputValidator::validateNumber(x);
            return calculateSingleDigitSum(x);
        } catch (const exception& e) {
            cerr << "Error calculating digit sum: " << e.what() << endl;
            return -1;
        }
    }
};

class AdvancedComparator {
public:
    bool operator()(int x, int y) {
        int sum_x = DigitSumCalculator::calculate(x);
        int sum_y = DigitSumCalculator::calculate(y);

        if (sum_x == -1 || sum_y == -1) {
            throw runtime_error("Invalid digit sum encountered during comparison");
        }

        if (sum_x != sum_y) {
            return sum_x < sum_y;
        }

        if (x == y) {
            return false;
        }

        vector<int> temp{x, y};
        sort(temp.begin(), temp.end());
        return x == temp[0];
    }
};

class InputProcessor {
public:
