        int n;
        cin >> n;

        if (!InputValidator::validateSize(n)) {
            throw runtime_error("Input size validation failed");
        }

        vector<int> numbers;
        numbers.reserve(n);

        for (int i = 0; i < n; ++i) {
            int num;
            cin >> num;

            if (cin.fail()) {
                cin.clear();
                cin.ignore(numeric_limits<streamsize>::max(), '\n');
                throw runtime_error("Invalid input format detected");
