struct CharacterCategory {
    bool isNumeric;
    bool isAlpha;
    bool isSpecial;
    bool needsWrapping;
};

CharacterCategory analyzeCharacter(char c) {
    CharacterCategory result;
    result.isNumeric = (c >= NUMERIC_START && c <= NUMERIC_END);
    result.isAlpha = (c >= ALPHA_START && c <= ALPHA_END);
    result.isSpecial = false;
    result.needsWrapping = false;
    return result;
}

string processTriplets(const string& input) {
    string processed;
    size_t inputLength = input.length();
    size_t currentPosition = 0;

    while (currentPosition < inputLength) {
        bool tripletFound = false;

        if (currentPosition + 2 < inputLength) {
            string potentialTriplet = input.substr(currentPosition, 3);
            if (potentialTriplet == SPACE_REPLACEMENT) {
                processed += " ";
                currentPosition += 3;
                tripletFound = true;
            } else if (potentialTriplet == DOT_REPLACEMENT) {
                processed += ".";
                currentPosition += 3;
                tripletFound = true;
            }
        }

        if (!tripletFound) {
            processed += input[currentPosition];
            currentPosition++;
        }
    }

    return processed;
}

