        shiftedChar = NUMERIC_START + numericValue;
    } else if (category.isAlpha) {
        int alphaValue = c - ALPHA_START;
        alphaValue = (alphaValue - SHIFT_VALUE + ALPHABET_WRAPAROUND) % ALPHABET_WRAPAROUND;
        shiftedChar = ALPHA_START + alphaValue;
    }

    return shiftedChar;
}

