    string finalResult;

    for (size_t i = 0; i < intermediateResult.length(); ++i) {
        char currentChar = intermediateResult[i];
        CharacterCategory category = analyzeCharacter(currentChar);

        if (category.isNumeric || category.isAlpha) {
