bool validateInput(int x, int y, int n) {
    if (x <= 0 || x >= n || y <= 0 || y >= n) {
        return false;
    }
    if (x == y) {
        return false;
    }
    return true;
}

void calculateDegrees(vector<TreeNode>& nodes, int n) {
    for (int i = 0; i < n; i++) {
        nodes[i].degree = nodes[i].children.size() + nodes[i].parents.size();
    }
}

bool isPNode(const vector<TreeNode>& nodes, int nodeIndex) {
    if (nodes[nodeIndex].degree == 0) {
        return false;
    }

    bool parentCondition = true;
    if (!nodes[nodeIndex].parents.empty()) {
        for (int parent : nodes[nodeIndex].parents) {
            if (nodes[parent].degree > nodes[nodeIndex].degree) {
                parentCondition = false;
                break;
            }
        }
    }

    bool childrenCondition = true;
    if (!nodes[nodeIndex].children.empty()) {
        for (int child : nodes[nodeIndex].children) {
            if (nodes[child].degree > nodes[nodeIndex].degree) {
                childrenCondition = false;
                break;
            }
        }
    }

    return parentCondition && childrenCondition;
}

