class PNodeAnalyzer {
private:
    vector<TreeValidationUnit> tree_units;
    int total_nodes;
    int p_node_count;

    void initialize_units(int n) {
        tree_units.clear();
        tree_units.resize(n);
        for(int i = 0; i < n; i++) {
            tree_units[i].adjacency_list.clear();
            tree_units[i].node_degree = 0;
            tree_units[i].is_p_node_candidate = false;
        }
        p_node_count = 0;
    }

    void process_edge(int x, int y) {
        if(x < 0 || x >= total_nodes || y < 0 || y >= total_nodes) {
            return;
        }
        tree_units[x].adjacency_list.push_back(y);
        tree_units[y].adjacency_list.push_back(x);
    }

    void calculate_degrees() {
        for(int i = 0; i < total_nodes; i++) {
            tree_units[i].node_degree = tree_units[i].adjacency_list.size();
        }
    }

    void evaluate_p_node_candidates() {
        for(int i = 0; i < total_nodes; i++) {
            tree_units[i].is_p_node_candidate = true;
            if(tree_units[i].node_degree == 0) {
                tree_units[i].is_p_node_candidate = false;
                continue;
            }

            for(int neighbor_index = 0; neighbor_index < tree_units[i].adjacency_list.size(); neighbor_index++) {
                int neighbor = tree_units[i].adjacency_list[neighbor_index];
                if(tree_units[neighbor].node_degree > tree_units[i].node_degree) {
                    tree_units[i].is_p_node_candidate = false;
                    break;
                }
            }
        }
    }

    void count_p_nodes() {
        for(int i = 0; i < total_nodes; i++) {
            if(tree_units[i].is_p_node_candidate) {
                p_node_count++;
            }
        }
    }

public:
    int analyze_tree(int n, const vector<pair<int, int>>& edges) {
        total_nodes = n;
        initialize_units(n);

        for(const auto& edge : edges) {
            process_edge(edge.first, edge.second);
        }

        calculate_degrees();
        evaluate_p_node_candidates();
        count_p_nodes();

        return p_node_count;
    }
};

