        }
    }
    return true;
}

bool hasValidLength(const string& s) {
    if (s.length() % UNIT_SIZE != 0) {
        return false;
    }
    return true;
}

string processLetterUnit(const string& unit) {
    if (unit.substr(0, 3) != LETTER_PREFIX) {
        throw runtime_error("Invalid letter prefix");
    }
    string binaryPart = unit.substr(3);
    int value = 0;
    for (int i = 0; i < binaryPart.size(); ++i) {
        if (binaryPart[i] == '1') {
            value += pow(2, binaryPart.size() - 1 - i);
        }
    }
    if (value < 0 || value >= 26) {
        throw out_of_range("Letter value out of range");
    }
    return string(1, 'A' + value);
}

string processSpaceUnit(const string& unit) {
    if (unit.substr(0, 3) != SPACE_PREFIX) {
        throw runtime_error("Invalid space prefix");
    }
    for (int i = 3; i < unit.size(); ++i) {
        if (unit[i] != '0') {
            throw runtime_error("Invalid space unit format");
        }
    }
    return " ";
}

pair<int, bool> processNumberUnit(const string& unit) {
    if (unit[0] != '0') {
        throw runtime_error("Invalid number prefix");
    }
    int value = 0;
    for (int i = 0; i < unit.size(); ++i) {
        if (unit[i] == '1') {
            value += pow(2, unit.size() - 1 - i);
        }
    }
    return make_pair(value / 2, true);
}

string decodeInformation(const string& code) {
    if (!validateBinaryString(code) || !hasValidLength(code)) {
        return "Error";
    }

    vector<string> units;
    for (size_t i = 0; i < code.size(); i += UNIT_SIZE) {
        string unit = code.substr(i, UNIT_SIZE);
        if (unit.size() != UNIT_SIZE) {
            return "Error";
        }
        units.push_back(unit);
    }

    string result;
    for (size_t i = 0; i < units.size(); ) {
        string unit = units[i];
        try {
            if (unit.substr(0, 3) == LETTER_PREFIX) {
