void processBookPlacements(ShelfInventory* shelves, int n, int m) {
    for (int placement_index = 0; placement_index < m; ++placement_index) {
        int target_shelf;
        std::string book_title;

        if (!(std::cin >> target_shelf >> book_title)) {
            throw std::runtime_error("Invalid input format detected");
        }

        if (!validateBookPlacement(target_shelf, n)) {
            throw std::out_of_range("Invalid bookshelf identifier encountered");
        }

        bool shelf_found = false;
        for (int shelf_index = 0; shelf_index < n; ++shelf_index) {
            if (shelves[shelf_index].shelf_identifier == target_shelf) {
                shelves[shelf_index].book_titles_collection.push_back(book_title);
                shelves[shelf_index].total_books_count++;
                shelf_found = true;
                break;
            }
        }

        if (!shelf_found) {
            throw std::logic_error("Target shelf not found in inventory");
        }
    }
}

void sortAndDisplayShelves(ShelfInventory* shelves, int n) {
