    shelves[shelf_num - 1].books.push_back(book_name);
    shelves[shelf_num - 1].count++;
}

void initializeShelves(vector<BookshelfData>& shelves, int n) {
    shelves.resize(n);
    for (int i = 0; i < n; i++) {
        shelves[i].id = i + 1;
        shelves[i].count = 0;
    }
}

void sortAllShelves(vector<BookshelfData>& shelves) {
    for (auto& shelf : shelves) {
        sort(shelf.books.begin(), shelf.books.end(), [](const string& a, const string& b) {
            return lexicographical_compare(a.begin(), a.end(), b.begin(), b.end());
        });
    }
}

void printShelves(const vector<BookshelfData>& shelves) {
    for (const auto& shelf : shelves) {
        cout << shelf.id << ' ' << shelf.count;
        for (const auto& book : shelf.books) {
            cout << ' ' << book;
        }
        cout << '\n';
    }
}

