    bool solutionFound;
    int bestA, bestB, bestC, bestD;

    void checkAndUpdate(int a, int b, int c, int d) {
        ResultValidator validator;
        if (validator.validate(a, b, c, d, n)) {
            if (!solutionFound || 
                (d < bestD) || 
                (d == bestD && c < bestC) || 
                (d == bestD && c == bestC && b < bestB) || 
                (d == bestD && c == bestC && b == bestB && a < bestA)) {
                bestA = a;
                bestB = b;
                bestC = c;
                bestD = d;
                solutionFound = true;
