const int MAX_LENGTH = 15;

bool validatePlate(const string& plate) {
    if (plate.empty() || plate.length() > MAX_LENGTH) return false;
    for (char c : plate) {
        if (!isdigit(c)) return false;
    }
    return true;
}

int calculateSum(const string& plate) {
    int total = 0;
    for (char c : plate) {
        if (isdigit(c)) {
            total += c - '0';
        } else {
            throw runtime_error("Invalid character in plate");
        }
    }
    return total;
}

long long convertToNumber(const string& plate) {
    long long num = 0;
    try {
        num = stoll(plate);
    } catch (...) {
        throw runtime_error("Plate number too large");
    }
    return num;
}

bool comparePlates(const NumberPlate& a, const NumberPlate& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    if (a.numericValue != b.numericValue) {
        return a.numericValue > b.numericValue;
    }
    return a.plate.length() > b.plate.length();
}

int findPlateIndex(const vector<NumberPlate>& plates, const string& target) {
    for (size_t i = 0; i < plates.size(); ++i) {
        if (plates[i].plate == target) {
            return i + 1;
        }
    }
    return -1;
}

void processInput(int n) {
    if (n <= 0 || n > MAX_PLATES) {
        throw runtime_error("Invalid number of plates");
    }

    plates.reserve(n);
    string currentPlate;
    string garlicPlate;

    for (int i = 0; i < n; ++i) {
        cin >> currentPlate;
        if (!validatePlate(currentPlate)) {
            throw runtime_error("Invalid plate format");
        }
        if (i == n - 1) {
            garlicPlate = currentPlate;
        } else {
            NumberPlate np;
            np.plate = currentPlate;
            np.sum = calculateSum(currentPlate);
            np.numericValue = convertToNumber(currentPlate);
            plates.push_back(np);
        }
    }

    NumberPlate garlicNP;
    garlicNP.plate = garlicPlate;
    garlicNP.sum = calculateSum(garlicPlate);
    garlicNP.numericValue = convertToNumber(garlicPlate);
    plates.push_back(garlicNP);
}

int main() {
