    int requirement;
    bool operator<(const NobleShop& other) const {
        return (requirement - price) < (other.requirement - other.price);
    }
};

class NobleShopper {
private:
    vector<NobleShop> shops;
    vector<int> dp;
    int maxMoney;
    int shopCount;
    void validateInput() {
        if (shops.size() != shopCount) {
            cerr << "Input validation failed: Incorrect number of shops" << endl;
            exit(1);
        }
        for (const auto& shop : shops) {
            if (shop.price > shop.requirement) {
                cerr << "Input validation failed: Price exceeds requirement" << endl;
                exit(1);
            }
        }
    }
public:
    NobleShopper(int n, int m) : shopCount(n), maxMoney(m) {
        dp.resize(m + 1, 0);
        shops.reserve(n);
    }
    void addShop(int p, int v, int q) {
        if (p < 0 || v < 0 || q < 0) {
            cerr << "Negative values detected in shop parameters" << endl;
            exit(1);
        }
        shops.push_back({p, v, q});
    }
    void processShops() {
        validateInput();
        sort(shops.begin(), shops.end());
        for (size_t i = 0; i < shops.size(); ++i) {
            const NobleShop& currentShop = shops[i];
            if (currentShop.price > maxMoney) continue;
            for (int j = maxMoney; j >= currentShop.price; --j) {
                if (j >= currentShop.requirement) {
                    int potentialValue = dp[j - currentShop.price] + currentShop.value;
                    if (potentialValue > dp[j]) {
                        dp[j] = potentialValue;
                    }
                }
            }
        }
    }
