char processUppercase(char c, int shift) {
    const int alphabetSize = 26;
    int normalizedShift = shift % alphabetSize;
    if (normalizedShift < 0) {
        normalizedShift += alphabetSize;
    }
    int originalPos = c - 'A';
    int newPos = (originalPos + normalizedShift) % alphabetSize;
    return 'A' + newPos;
}

char processLowercase(char c, int shift) {
    const int alphabetSize = 26;
    int normalizedShift = shift % alphabetSize;
    if (normalizedShift < 0) {
        normalizedShift += alphabetSize;
    }
    int originalPos = c - 'a';
    int newPos = (originalPos + normalizedShift) % alphabetSize;
    return 'a' + newPos;
}

char processDigit(char c, int shift) {
    const int digitSize = 10;
    int normalizedShift = shift % digitSize;
    if (normalizedShift < 0) {
        normalizedShift += digitSize;
    }
    int originalPos = c - '0';
    int newPos = (originalPos + normalizedShift) % digitSize;
    return '0' + newPos;
}

char transformCharacter(char c, int shift, int position, int y) {
    if ((position + 1) % y != 0) {
        return c;
    }

    bool isUppercase = (c >= 'A' && c <= 'Z');
    bool isLowercase = (c >= 'a' && c <= 'z');
    bool isDigit = (c >= '0' && c <= '9');

    if (isUppercase) {
        return processUppercase(c, shift);
    } else if (isLowercase) {
        return processLowercase(c, shift);
    } else if (isDigit) {
        return processDigit(c, shift);
    }

    return c;
}

