    static T calculate_initial_distance(T n, T a) {
        T initial_distance = n * a;
        if (initial_distance <= 600) {
            throw std::logic_error("Initial distance must be greater than shooting range");
        }
        return initial_distance;
    }

    template<typename T>
    static T compute_time_to_shoot(T initial_distance, T a, T b) {
