#include <iostream>
#include <algorithm>
#include <fstream>
#include <vector>
#include <limits>
#include <stdexcept>

using namespace std;

const long long ASCEND_TIME = 5;
const long long DESCEND_TIME = 4;
const long long DOOR_OPEN_TIME = 3;
const long long PERSON_EXIT_TIME = 2;

struct ElevatorState {
    long long current_floor;
    long long total_time;
    bool door_open;
    vector<long long> destinations;
};

void validate_input(long long n, const vector<long long>& a) {
    if (n < 1 || n > 100000) {
        throw runtime_error("Invalid number of people");
    }
    for (const auto& floor : a) {
        if (floor < 1 || floor > 1000000000000LL) {
            throw runtime_error("Invalid floor number");
        }
    }
}

void initialize_elevator(ElevatorState& state, long long n) {
    state.current_floor = 0;
    state.total_time = 0;
    state.door_open = false;
    state.destinations.resize(n);
}

void process_input(ElevatorState& state, ifstream& input_file) {
    long long n;
    input_file >> n;
    for (long long i = 0; i < n; ++i) {
        input_file >> state.destinations[i];
    }
    validate_input(n, state.destinations);
    sort(state.destinations.begin(), state.destinations.end());
}

void simulate_elevator_movement(ElevatorState& state) {
    for (size_t i = 0; i < state.destinations.size(); ++i) {
        long long target_floor = state.destinations[i];
        if (target_floor > state.current_floor) {
            state.total_time += (target_floor - state.current_floor) * ASCEND_TIME;
        } else if (target_floor < state.current_floor) {
            state.total_time += (state.current_floor - target_floor) * DESCEND_TIME;
        }
        state.current_floor = target_floor;
        state.total_time += DOOR_OPEN_TIME;
        state.door_open = true;
        state.total_time += PERSON_EXIT_TIME;
        state.door_open = false;
    }
    if (state.current_floor != 0) {
        state.total_time += state.current_floor * DESCEND_TIME;
        state.current_floor = 0;
    }
}

void write_output(const ElevatorState& state) {
    ofstream output_file("elevator.out");
    if (!output_file.is_open()) {
        throw runtime_error("Failed to open output file");
    }
    output_file << state.total_time << endl;
    output_file.close();
}

int main() {
    try {
        ifstream input_file("elevator.in");
        if (!input_file.is_open()) {
            throw runtime_error("Failed to open input file");
        }

        ElevatorState elevator;
        long long n;
        input_file >> n;
        initialize_elevator(elevator, n);
        process_input(elevator, input_file);
        input_file.close();

        simulate_elevator_movement(elevator);
        write_output(elevator);
    } catch (const exception& e) {
        ofstream error_log("elevator_error.log");
        error_log << "Error: " << e.what() << endl;
        error_log.close();
        return 1;
    }
    return 0;
}
