#include <iostream>
#include <stdexcept>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

struct CharacterData {
    char original;
    bool shouldTransform;
    size_t position;
};

class CharacterTransformer {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;
    int rotationOffset;
    vector<CharacterData> characterCollection;

    char transformUpperCase(char inputChar) {
        int normalizedValue = inputChar - 'A';
        int transformedValue = (normalizedValue + rotationOffset) % ALPHABET_SIZE;
        while (transformedValue < 0) {
            transformedValue += ALPHABET_SIZE;
        }
        return static_cast<char>(transformedValue + 'A');
    }

    char transformLowerCase(char inputChar) {
        int normalizedValue = inputChar - 'a';
        int transformedValue = (normalizedValue + rotationOffset) % ALPHABET_SIZE;
        while (transformedValue < 0) {
            transformedValue += ALPHABET_SIZE;
        }
        return static_cast<char>(transformedValue + 'a');
    }

    char transformDigit(char inputChar) {
        int normalizedValue = inputChar - '0';
        int transformedValue = (normalizedValue + rotationOffset) % DIGIT_SIZE;
        while (transformedValue < 0) {
            transformedValue += DIGIT_SIZE;
        }
        return static_cast<char>(transformedValue + '0');
    }

public:
    explicit CharacterTransformer(int offset) : rotationOffset(offset) {}

    void processCharacter(CharacterData& data) {
        if (!data.shouldTransform) return;

        char current = data.original;
        if (current >= 'A' && current <= 'Z') {
            data.original = transformUpperCase(current);
        } else if (current >= 'a' && current <= 'z') {
            data.original = transformLowerCase(current);
        } else if (current >= '0' && current <= '9') {
            data.original = transformDigit(current);
        }
    }

    void addCharacter(CharacterData data) {
        characterCollection.push_back(data);
    }

    void transformAll() {
        for_each(characterCollection.begin(), characterCollection.end(), [this](CharacterData& data) {
            processCharacter(data);
        });
    }

    string getResult() {
        string result;
        for (const auto& data : characterCollection) {
            result += data.original;
        }
        return result;
    }
};

class InputValidator {
public:
    static void validateParameters(int x, int y, int z) {
        if (x <= 10 || x > 100) {
            throw invalid_argument("Invalid x value");
        }
        if (y <= 0 || y > 10) {
            throw invalid_argument("Invalid y value");
        }
        if (z <= 0 || z > 100) {
            throw invalid_argument("Invalid z value");
        }
    }
};

int main() {
    try {
        int x, y, z;
        cin >> x >> y >> z;

        InputValidator::validateParameters(x, y, z);

        CharacterTransformer transformer(z);

        for (size_t currentPosition = 0; currentPosition < x; ++currentPosition) {
            char currentChar;
            cin >> currentChar;

            bool needsTransformation = (currentPosition % y) == 0;

            CharacterData charData{currentChar, needsTransformation, currentPosition};
            transformer.addCharacter(charData);
        }

        transformer.transformAll();
        string result = transformer.getResult();

        if (result.size() != x) {
            throw runtime_error("Output length mismatch");
        }

        cout << result;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
