using namespace std;

int validateMatrixDimensions(int n, int m) {
    if (n < 1 || n > 50 || m < 1 || m > 50) {
        throw invalid_argument("Matrix dimensions out of bounds");
    }
    return n * m;
}

void validateMatrixElement(int val) {
    if (val < -1000 || val > 1000) {
        throw out_of_range("Matrix element out of range");
    }
}

vector<vector<int>> precomputeRowSums(const vector<vector<int>>& matrix) {
    vector<vector<int>> rowSums(matrix.size(), vector<int>(matrix[0].size() + 1, 0));
    for (int i = 0; i < matrix.size(); ++i) {
        for (int j = 0; j < matrix[0].size(); ++j) {
            rowSums[i][j + 1] = rowSums[i][j] + matrix[i][j];
        }
    }
    return rowSums;
}

int computeSubmatrixSum(const vector<vector<int>>& rowSums, int row1, int row2, int col1, int col2) {
    if (row1 < 0 || row2 >= rowSums.size() || col1 < 0 || col2 >= rowSums[0].size() - 1) {
        throw out_of_range("Submatrix coordinates out of bounds");
    }
    int sum = 0;
    for (int i = row1; i <= row2; ++i) {
        sum += rowSums[i][col2 + 1] - rowSums[i][col1];
    }
    return sum;
}

int main() {
    ifstream infile("submatrix.in");
    ofstream outfile("submatrix.out");

