#include <iostream>
#include <vector>
#include <stdexcept>
#include <algorithm>
#include <cctype>

using namespace std;

struct InputValidationException : public runtime_error {
    using runtime_error::runtime_error;
};

class CharacterValidator {
public:
    static bool isValidCharacter(char c) {
        return (isalpha(c) || isdigit(c));
    }
};

class CyclicShifter {
private:
    int shiftAmount;
    bool shouldProcess(int index, int cycle) const {
        if (cycle <= 0) throw invalid_argument("Cycle must be positive");
        return (index % cycle) == (cycle - 1);
    }

    char shiftAlpha(char c, bool isUpper) const {
        const char base = isUpper ? 'A' : 'a';
        return static_cast<char>(base + (c - base + shiftAmount) % 26);
    }

    char shiftDigit(char c) const {
        return static_cast<char>('0' + (c - '0' + shiftAmount) % 10);
    }

public:
    CyclicShifter(int shift) : shiftAmount(shift) {
        if (shift <= 0) throw invalid_argument("Shift amount must be positive");
    }

    char processCharacter(char c, int index, int cycle) {
        if (!CharacterValidator::isValidCharacter(c)) {
            throw invalid_argument("Invalid character in input");
        }

        if (!shouldProcess(index, cycle)) {
            return c;
        }

        if (isupper(c)) {
            return shiftAlpha(c, true);
        } else if (islower(c)) {
            return shiftAlpha(c, false);
        } else if (isdigit(c)) {
            return shiftDigit(c);
        }

        return c;
    }
};

class InputProcessor {
private:
    int x, y, z;
    vector<char> characters;

    void validateInput() const {
        if (x <= 10 || x > 100) throw InputValidationException("Invalid x value");
        if (y <= 0 || y > 10) throw InputValidationException("Invalid y value");
        if (z <= 0 || z > 100) throw InputValidationException("Invalid z value");
        if (characters.size() != static_cast<size_t>(x)) {
            throw InputValidationException("Character count mismatch");
        }
    }

public:
    void readInput() {
        cin >> x >> y >> z;
        if (!cin.good()) throw InputValidationException("Invalid input format");

        characters.reserve(x);
        for (int i = 0; i < x; ++i) {
            char c;
            cin >> c;
            if (!CharacterValidator::isValidCharacter(c)) {
                throw InputValidationException("Invalid character in input");
            }
            characters.push_back(c);
        }
        validateInput();
    }

    string process() {
        CyclicShifter shifter(z);
        string result;
        result.reserve(x);

        for (int i = 0; i < x; ++i) {
            try {
                result += shifter.processCharacter(characters[i], i, y);
            } catch (const exception& e) {
                cerr << "Error processing character: " << e.what() << endl;
                result += characters[i];
            }
        }

        return result;
    }
};

int main() {
    try {
        InputProcessor processor;
        processor.readInput();
        string result = processor.process();
        cout << result;
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
