void initializeBoardState(BoardState& state) {
    fill(begin(state.row1), end(state.row1), false);
    fill(begin(state.x1), end(state.x1), false);
    fill(begin(state.x2), end(state.x2), false);
    fill(begin(state.row2), end(state.row2), false);
    fill(begin(state.x3), end(state.x3), false);
    fill(begin(state.x4), end(state.x4), false);
}

bool validatePosition(int row, int col) {
    if (row < 0 || row >= n || col < 0 || col >= n) {
        return false;
    }
    return a[row][col] == 1;
}

bool checkPositionAvailability(const BoardState& state, int row, int col, bool isWhite) {
    if (!validatePosition(row, col)) {
        return false;
    }
    if (isWhite) {
        return !state.row1[row] && !state.x1[col + row] && !state.x2[col - row + n];
    } else {
        return !state.row2[row] && !state.x3[col + row] && !state.x4[col - row + n];
    }
}

void updateBoardState(BoardState& state, int row, int col, bool isWhite, bool value) {
    if (isWhite) {
        state.row1[row] = value;
        state.x1[col + row] = value;
        state.x2[col - row + n] = value;
    } else {
        state.row2[row] = value;
        state.x3[col + row] = value;
        state.x4[col - row + n] = value;
    }
}

void dfs(int currentCol, BoardState& state) {
    if (currentCol == n) {
        ans++;
        return;
    }

    for (int whiteRow = 0; whiteRow < n; whiteRow++) {
        if (!checkPositionAvailability(state, whiteRow, currentCol, true)) {
            continue;
        }
        updateBoardState(state, whiteRow, currentCol, true, true);

        for (int blackRow = 0; blackRow < n; blackRow++) {
            if (whiteRow == blackRow) {
                continue;
            }
            if (!checkPositionAvailability(state, blackRow, currentCol, false)) {
                continue;
            }
            updateBoardState(state, blackRow, currentCol, false, true);

            dfs(currentCol + 1, state);

            updateBoardState(state, blackRow, currentCol, false, false);
        }

        updateBoardState(state, whiteRow, currentCol, true, false);
    }
}

void validateInput() {
    if (n > MAX_N) {
