#include<unordered_map>
#include<deque>
#include<memory>
#include<exception>
#include<stdexcept>
using namespace std;

class QueueManager {
private:
    deque<string> main_queue;
    unordered_map<char, vector<size_t>> friend_indices;

public:
    void enqueue(const string& name) {
        if (name.empty()) {
            throw invalid_argument("Name cannot be empty");
        }

        char first_char = toupper(name[0]);
        bool friend_found = false;
        size_t insert_position = main_queue.size();

        if (friend_indices.find(first_char) != friend_indices.end()) {
            for (const auto& pos : friend_indices[first_char]) {
                if (pos < main_queue.size()) {
                    insert_position = pos + 1;
                    friend_found = true;
                    break;
                }
            }
        }

        if (friend_found) {
            main_queue.insert(main_queue.begin() + insert_position, name);
            for (auto& [key, positions] : friend_indices) {
                for (auto& pos : positions) {
                    if (pos >= insert_position) {
                        pos++;
                    }
                }
            }
        } else {
            main_queue.push_back(name);
        }

        friend_indices[first_char].push_back(insert_position);
    }

    string dequeue() {
        if (main_queue.empty()) {
            return "0";
        }

        string front_person = main_queue.front();
        char first_char = toupper(front_person[0]);

        main_queue.pop_front();

        if (friend_indices.find(first_char) != friend_indices.end()) {
            auto& positions = friend_indices[first_char];
            positions.erase(remove(positions.begin(), positions.end(), 0), positions.end());
            for (auto& pos : positions) {
                if (pos > 0) {
                    pos--;
                }
            }
        }

        for (auto& [key, positions] : friend_indices) {
            for (auto& pos : positions) {
                if (pos > 0) {
                    pos--;
                }
            }
        }

        return front_person;
    }
};

int main() {
    QueueManager qm;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    while (n--) {
        int k;
        cin >> k;

        if (k == 1) {
            string name;
            cin >> name;
            if (name.length() > 100) {
                cerr << "Name too long" << endl;
                continue;
