using namespace std;

struct QueueState {
    vector<string> queue_data;
    int front_pointer;
    int rear_pointer;
    bool initialization_flag;
};

void initializeQueueState(QueueState& qs) {
    qs.queue_data.resize(1005);
    qs.front_pointer = 0;
    qs.rear_pointer = 0;
    qs.initialization_flag = true;
}

void handleEnqueueOperation(QueueState& qs, const string& name) {
    bool friend_found_indicator = false;
    int insertion_position_index = -1;
    char first_letter_comparator = name.empty() ? '\0' : name[0];

    for (int current_position = qs.front_pointer; current_position < qs.rear_pointer; ++current_position) {
        if (!qs.queue_data[current_position].empty() && qs.queue_data[current_position][0] == first_letter_comparator) {
            friend_found_indicator = true;
            insertion_position_index = current_position;
            break;
        }
    }

    if (friend_found_indicator) {
        for (int shift_position = qs.rear_pointer; shift_position > insertion_position_index + 1; --shift_position) {
            qs.queue_data[shift_position] = qs.queue_data[shift_position - 1];
        }
        qs.queue_data[insertion_position_index + 1] = name;
    } else {
        qs.queue_data[qs.rear_pointer] = name;
    }

    qs.rear_pointer++;
}

string handleDequeueOperation(QueueState& qs) {
    if (qs.front_pointer >= qs.rear_pointer) {
        return "0";
    }
    string dequeued_value = qs.queue_data[qs.front_pointer];
    qs.front_pointer++;
    return dequeued_value;
}

int main() {
    QueueState queue_state;
    initializeQueueState(queue_state);

    int operation_count;
    cin >> operation_count;

    while (operation_count--) {
        int operation_type;
        cin >> operation_type;

        if (operation_type == 1) {
            string new_person_name;
            cin >> new_person_name;
            handleEnqueueOperation(queue_state, new_person_name);
        } else if (operation_type == 2) {
            string result = handleDequeueOperation(queue_state);
            cout << result << endl;
        } else {
            continue;
        }
    }

    return 0;
}
