using namespace std;

vector<string> tokenize_string(const string& input) {
    vector<string> tokens;
    string current_token;
    for (char ch : input) {
        if (isspace(ch)) {
            if (!current_token.empty()) {
                tokens.push_back(current_token);
                current_token.clear();
            }
        } else {
            current_token += ch;
        }
    }
    if (!current_token.empty()) {
        tokens.push_back(current_token);
    }
    return tokens;
}

string process_case(const string& s) {
    string processed;
    for (char ch : s) {
        if (isupper(ch) && ch != 'I') {
            processed += tolower(ch);
        } else if (ch == '?') {
            processed += '!';
        } else {
            processed += ch;
        }
    }
    return processed;
}

vector<string> apply_rule_4(const vector<string>& tokens) {
    vector<string> modified;
    for (const string& token : tokens) {
        if (token == "I" || token == "me") {
            modified.push_back("you");
        } else {
            modified.push_back(token);
        }
    }
    return modified;
}

vector<string> apply_rule_3(const vector<string>& tokens) {
    vector<string> modified;
    size_t i = 0;
    while (i < tokens.size()) {
        if (i + 1 < tokens.size() && 
            (tokens[i] == "can" || tokens[i] == "could") && 
            tokens[i+1] == "you") {
            modified.push_back("I");
            modified.push_back(tokens[i]);
            i += 2;
        } else {
            modified.push_back(tokens[i]);
            i++;
        }
    }
    return modified;
}

string reconstruct_sentence(const vector<string>& tokens) {
    if (tokens.empty()) return "";
    ostringstream oss;
    copy(tokens.begin(), prev(tokens.end()), ostream_iterator<string>(oss, " "));
    oss << tokens.back();
    return oss.str();
}

