    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    vector<string> inputs;
    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        inputs.push_back(line);
    }

    for (string input : inputs) {
        string case_processed = process_case(input);
        vector<string> tokens = tokenize_string(case_processed);
        vector<string> rule4_applied = apply_rule_4(tokens);
        vector<string> rule3_applied = apply_rule_3(rule4_applied);
        string final_output = reconstruct_sentence(rule3_applied);
        cout << final_output << endl;
    }

