    if (skipNext) {
        skipNext = false;
        wasReplaced = false;
        return word;
    }

    string temp = word;
    if (temp == "can" || temp == "could") {
        wasReplaced = true;
        return "I " + temp;
    }
    else if ((temp == "I" || temp == "me") && !wasReplaced) {
        skipNext = wasReplaced = true;
        return "you";
    }
    wasReplaced = false;
    return word;
}

string processSentence(string s) {
    vector<string> words;
    string current;
    for (char& c : s) {
        if (isupper(c) && c != 'I') c = tolower(c);
        if (c == '?') c = '!';
        if (c == ' ') {
            if (!current.empty()) {
                words.push_back(current);
                current.clear();
            }
        } else {
            current += c;
        }
    }
    if (!current.empty()) words.push_back(current);

    vector<bool> processed(words.size(), false);
    string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (processed[i]) continue;

        if (i + 1 < words.size() && !processed[i+1]) {
            if ((words[i] == "can" || words[i] == "could") && words[i+1] == "you") {
                result += "I " + words[i] + " ";
                processed[i] = processed[i+1] = true;
                continue;
            }
        }

        if (!processed[i] && (words[i] == "I" || words[i] == "me")) {
            bool adjacentProcessed = false;
            if (i > 0 && processed[i-1]) adjacentProcessed = true;
            if (i + 1 < words.size() && processed[i+1]) adjacentProcessed = true;

            if (!adjacentProcessed) {
                result += "you ";
                processed[i] = true;
                continue;
