using namespace std;

struct QueueNode {
    string name;
    shared_ptr<QueueNode> next;
    weak_ptr<QueueNode> prev;
};

class AdvancedQueueManager {
private:
    shared_ptr<QueueNode> head;
    shared_ptr<QueueNode> tail;
    size_t current_size;
    const size_t MAX_SIZE = 1000;

    bool validateName(const string& name) {
        if (name.empty()) return false;
        if (!isalpha(name[0])) return false;
        if (name.size() > 100) return false;
        return true;
    }

    shared_ptr<QueueNode> findFirstFriend(const string& name) {
        if (!head) return nullptr;
        char target = toupper(name[0]);
        auto current = head;
        while (current) {
            if (!current->name.empty() && toupper(current->name[0]) == target) {
                return current;
            }
            current = current->next;
        }
        return nullptr;
    }

public:
    AdvancedQueueManager() : head(nullptr), tail(nullptr), current_size(0) {}

    void enqueue(const string& name) {
        if (current_size >= MAX_SIZE) {
            throw runtime_error("Queue capacity exceeded");
        }

        if (!validateName(name)) {
            throw invalid_argument("Invalid name format");
        }

        auto new_node = make_shared<QueueNode>();
        new_node->name = name;

        auto friend_node = findFirstFriend(name);
        if (friend_node) {
            new_node->next = friend_node->next;
            if (friend_node->next) {
                friend_node->next->prev = new_node;
            }
            friend_node->next = new_node;
            new_node->prev = friend_node;

            if (friend_node == tail) {
                tail = new_node;
            }
        } else {
            if (!tail) {
                head = tail = new_node;
            } else {
                tail->next = new_node;
                new_node->prev = tail;
                tail = new_node;
            }
        }
        current_size++;
    }

    string dequeue() {
        if (!head) {
            return "0";
        }

        auto old_head = head;
        string result = old_head->name;

        if (head->next) {
            head = head->next;
            head->prev.reset();
        } else {
            head.reset();
            tail.reset();
        }

        current_size--;
        return result;
    }

    bool isEmpty() const {
        return current_size == 0;
    }
};

