#include <bits/stdc++.h>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

namespace NumberPlateUtils {
    template<typename T>
    typename enable_if<is_integral<T>::value, bool>::type
    validateNumberPlate(const T& plate) {
        return plate >= 0;
    }

    template<typename T>
    typename enable_if<is_integral<T>::value, T>::type
    calculateDigitSum(T num) {
        if (!validateNumberPlate(num)) {
            throw invalid_argument("Negative number plate detected");
        }
        T sum = 0;
        T temp = num;
        const T base = 10;
        while (temp != 0) {
            sum += temp % base;
            temp /= base;
            if (sum < 0) {
                throw overflow_error("Digit sum overflow detected");
            }
        }
        return sum;
    }

    template<typename T>
    struct Comparator {
        bool operator()(const T& a, const T& b) const {
            try {
                T sum_a = calculateDigitSum(a);
                T sum_b = calculateDigitSum(b);
                if (sum_a != sum_b) {
                    return sum_a < sum_b;
                }
                return a > b;
            } catch (const exception& e) {
                cerr << "Comparator error: " << e.what() << endl;
                return false;
            }
        }
    };
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cerr << "Invalid number of plates" << endl;
        return EXIT_FAILURE;
    }

    vector<string> plateStrings(n);
    for (int i = 0; i < n; ++i) {
        cin >> plateStrings[i];
        if (plateStrings[i].empty() || plateStrings[i].size() > 10) {
            cerr << "Invalid plate length" << endl;
            return EXIT_FAILURE;
        }
        for (char c : plateStrings[i]) {
            if (!isdigit(c)) {
                cerr << "Non-digit character detected" << endl;
                return EXIT_FAILURE;
            }
        }
    }

    string garlicPlate = plateStrings.back();
    vector<long long> plates;
    plates.reserve(n);
    try {
        for (const auto& s : plateStrings) {
            plates.push_back(stoll(s));
        }
    } catch (const exception& e) {
        cerr << "Plate conversion error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    sort(plates.begin(), plates.end(), NumberPlateUtils::Comparator<long long>());

    long long garlicValue;
    try {
        garlicValue = stoll(garlicPlate);
    } catch (const exception& e) {
        cerr << "Garlic plate conversion error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    auto it = find(plates.begin(), plates.end(), garlicValue);
    if (it != plates.end()) {
        cout << distance(plates.begin(), it) + 1;
    } else {
        cerr << "Garlic plate not found in sorted list" << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
