    long long safe_stoll(const string& s) {
        try {
            size_t pos;
            long long val = stoll(s, &pos);
            if (pos != s.size()) throw invalid_argument("Invalid characters in number");
            return val;
        } catch (const invalid_argument& e) {
            cerr << "Invalid number format: " << e.what() << endl;
            return numeric_limits<long long>::min();
        } catch (const out_of_range& e) {
            cerr << "Number out of range: " << e.what() << endl;
            return numeric_limits<long long>::min();
        }
    }

    int calculate_digit_sum(long long num) {
        if (num == numeric_limits<long long>::min()) return -1;
        int sum = 0;
        num = abs(num);
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
