    if (m <= 1 || m > 100000) return false;
    return true;
}

bool validateBook(int k, int n) {
    if (k < 1 || k > n) return false;
    return true;
}

string sanitizeString(const string& s) {
    string sanitized;
    for (char c : s) {
        if (isalpha(c) || c == ' ' || c == '-') {
            sanitized += c;
        }
    }
    return sanitized;
}

void processBookshelves(int n, int m, vector<BookShelf>& shelves) {
    for (int i = 1; i <= n; i++) {
        shelves[i].id = i;
        shelves[i].count = 0;
    }

    for (int i = 0; i < m; i++) {
        int k;
        string s;
        cin >> k >> s;

        if (!validateBook(k, n)) {
            continue;
        }

        string processed = sanitizeString(s);
        if (processed.empty()) {
            continue;
        }

        shelves[k].books.push_back(processed);
        shelves[k].count++;
    }
}

void sortAndOutput(vector<BookShelf>& shelves, int n) {
    for (int i = 1; i <= n; i++) {
        sort(shelves[i].books.begin(), shelves[i].books.end(), [](const string& a, const string& b) {
            return lexicographical_compare(a.begin(), a.end(), b.begin(), b.end());
        });

        cout << shelves[i].id << " " << shelves[i].count;
        for (const string& book : shelves[i].books) {
            cout << " " << book;
        }
        cout << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    if (!validateInput(n, m)) {
        cerr << "Invalid input parameters" << endl;
        return 1;
    }

    vector<BookShelf> shelves(n + 1);
    processBookshelves(n, m, shelves);

    for (int i = 1; i <= n; i++) {
        if (shelves[i].count != shelves[i].books.size()) {
            cerr << "Data inconsistency detected on shelf " << i << endl;
            return 1;
        }
    }

    sortAndOutput(shelves, n);

    return 0;
}
