    unordered_map<int, int> shelfIndexMap;

public:
    void initializeShelves(int n) {
        shelves.reserve(n);
        for (int i = 1; i <= n; ++i) {
            auto shelf = make_unique<BookshelfData>();
            shelf->id = i;
            shelf->count = 0;
            shelves.push_back(move(shelf));
            shelfIndexMap[i] = i - 1;
