class SentenceProcessor {
private:
    string raw_input;
    vector<WordMetadata> words;
    bool processed;

    void validateInput() {
        if (raw_input.empty()) {
            throw runtime_error("Input cannot be empty");
        }
        for (char c : raw_input) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Input contains invalid characters");
            }
