        istringstream iss(raw_input);
        string token;
        size_t pos_counter = 0;

        while (iss >> token) {
            bool valid_word = true;
            for (char c : token) {
                if (!isalpha(c)) {
                    valid_word = false;
                    break;
                }
            }
            if (valid_word) {
                words.push_back({token, pos_counter, token.length()});
                pos_counter++;
            }
        }
    }

public:
    explicit SentenceProcessor(const string& input) : raw_input(input), processed(false) {
        validateInput();
    }

    void process() {
        tokenizeWords();
        processed = true;
