#include<bits/stdc++.h>
using namespace std;

struct QueueStatus {
    bool operation_success;
    string error_message;
    int current_length;
};

class OverlyCautiousQueue {
private:
    vector<string> queue_data;
    int front_index;
    int rear_index;
    int max_capacity;
    bool initialization_complete;

    bool validateOperation(int operation_type) {
        if (operation_type != 1 && operation_type != 2) {
            return false;
        }
        return true;
    }

    bool validateName(const string& name) {
        if (name.empty()) {
            return false;
        }
        for (char c : name) {
            if (!isalpha(c)) {
                return false;
            }
        }
        return true;
    }

    QueueStatus performInsertion(const string& name) {
        QueueStatus status;
        status.operation_success = false;
        status.current_length = rear_index - front_index;

        if (rear_index >= max_capacity) {
            status.error_message = "Queue capacity exceeded";
            return status;
        }

        bool friend_found = false;
        int insertion_position = rear_index;

        for (int i = front_index; i < rear_index; i++) {
            if (!queue_data[i].empty() && queue_data[i][0] == name[0]) {
                friend_found = true;
                insertion_position = i + 1;
                break;
            }
        }

        if (friend_found) {
            if (rear_index + 1 > max_capacity) {
                status.error_message = "Cannot shift elements, queue full";
                return status;
            }

            for (int j = rear_index; j > insertion_position; j--) {
                if (j - 1 >= front_index) {
                    queue_data[j] = queue_data[j - 1];
                }
            }
            queue_data[insertion_position] = name;
        } else {
            queue_data[rear_index] = name;
        }

        rear_index++;
        status.operation_success = true;
        status.current_length = rear_index - front_index;
        return status;
    }

    QueueStatus performDeletion() {
        QueueStatus status;
        status.operation_success = false;

        if (front_index >= rear_index) {
            status.error_message = "Queue is empty";
            return status;
        }

        front_index++;
        status.operation_success = true;
        status.current_length = rear_index - front_index;
        return status;
    }

public:
    OverlyCautiousQueue(int capacity) {
        max_capacity = capacity;
        queue_data.resize(max_capacity);
        front_index = 0;
        rear_index = 0;
        initialization_complete = true;
    }

    string processOperation(int operation_type, const string& name = "") {
        if (!initialization_complete) {
            return "0";
        }

        if (!validateOperation(operation_type)) {
            return "0";
        }

        if (operation_type == 1) {
            if (!validateName(name)) {
                return "0";
            }

            QueueStatus insert_status = performInsertion(name);
            if (!insert_status.operation_success) {
                return "0";
            }
            return "";
        } else {
            if (front_index >= rear_index) {
                return "0";
            }

            string front_element = queue_data[front_index];
            QueueStatus delete_status = performDeletion();
            if (!delete_status.operation_success) {
                return "0";
            }
            return front_element;
        }
    }
};

int main() {
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        while (n--) {
            int k;
            cin >> k;
            if (k == 2) {
                cout << "0" << endl;
            }
        }
        return 0;
    }

    OverlyCautiousQueue queue(105);

    while (n--) {
        int k;
        cin >> k;

        if (k == 1) {
            string name;
            cin >> name;
            queue.processOperation(k, name);
        } else {
            string result = queue.processOperation(k);
            if (!result.empty()) {
                cout << result << endl;
            }
        }
    }

    return 0;
}
