#include<bits/stdc++.h>
using namespace std;

struct Person {
    string name;
    char first_letter;
    int position;
    bool has_friend;
};

class QueueManager {
private:
    vector<Person> queue;
    int front;
    int back;
    int capacity;
    int current_size;

public:
    QueueManager(int max_size) {
        capacity = max_size;
        queue.resize(capacity);
        front = 0;
        back = 0;
        current_size = 0;
    }

    void validateOperation(int op) {
        if (op != 1 && op != 2) {
            throw invalid_argument("Invalid operation code");
        }
    }

    void validateName(const string& name) {
        if (name.empty()) {
            throw invalid_argument("Name cannot be empty");
        }
        if (!isalpha(name[0])) {
            throw invalid_argument("Name must start with a letter");
        }
    }

    void enqueue(const string& name) {
        validateName(name);
        if (current_size >= capacity) {
            throw overflow_error("Queue capacity exceeded");
        }

        Person new_person;
        new_person.name = name;
        new_person.first_letter = toupper(name[0]);
        new_person.has_friend = false;

        bool inserted = false;
        for (int i = front; i < back; ++i) {
            if (toupper(queue[i].name[0]) == new_person.first_letter) {
                for (int j = back; j > i + 1; --j) {
                    if (j < capacity) {
                        queue[j] = queue[j - 1];
                    }
                }
                new_person.position = i + 1;
                new_person.has_friend = true;
                if (i + 1 < capacity) {
                    queue[i + 1] = new_person;
                }
                inserted = true;
                break;
            }
        }

        if (!inserted) {
            new_person.position = back;
            new_person.has_friend = false;
            if (back < capacity) {
                queue[back] = new_person;
            }
        }

        back = (back + 1) % capacity;
        current_size++;
    }

    string dequeue() {
        if (current_size == 0) {
            return "0";
        }

        Person front_person = queue[front];
        front = (front + 1) % capacity;
        current_size--;

        return front_person.name;
    }
};

int main() {
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    QueueManager qm(105);

    while (n--) {
        int k;
        cin >> k;

        try {
            qm.validateOperation(k);
        } catch (const invalid_argument& e) {
            cerr << "Error: " << e.what() << endl;
            continue;
        }

        if (k == 1) {
            string name;
            cin >> name;
            try {
                qm.enqueue(name);
            } catch (const exception& e) {
                cerr << "Enqueue error: " << e.what() << endl;
            }
        } else if (k == 2) {
            string result = qm.dequeue();
            cout << result << endl;
        }
    }

    return 0;
}
