                if (remaining3 < 0) continue;
                int d = sqrt(remaining3);
                if (d * d == remaining3) {
                    solutions.push_back({a, b, c, d});
                }
            }
        }
    }
}

void find_solution_optimized(int n) {
    for (const auto& pair1 : precomputed_pairs) {
        int remaining = n - pair1.first;
