        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= m; ++j) {
                if (!(inFile >> matrix[i][j])) {
                    throw runtime_error("Failed to read matrix element");
                }
                validateMatrixElement(matrix[i][j]);
            }
        }

        int globalMax = INT_MIN;
        vector<vector<int>> prefixSum(n + 2, vector<int>(m + 2, 0));

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= m; ++j) {
