namespace NumberPlateUtils {
    template<typename T>
    struct DigitSumCalculator {
        static_assert(is_integral<T>::value, "DigitSumCalculator requires integral type");
        static T calculate(T value) noexcept {
            T sum = 0;
            while (value != 0) {
                sum += value % 10;
                value /= 10;
            }
            return sum;
        }
    };

    template<typename T>
    class NumberPlateComparator {
    public:
        bool operator()(const T& lhs, const T& rhs) const {
            const T lhsSum = DigitSumCalculator<T>::calculate(lhs);
            const T rhsSum = DigitSumCalculator<T>::calculate(rhs);

            if (lhsSum != rhsSum) {
                return lhsSum < rhsSum;
            } else {
                return lhs > rhs;
            }
        }
    };

    template<typename Container>
    class NumberPlateProcessor {
    public:
        using ValueType = typename Container::value_type;

        explicit NumberPlateProcessor(const Container& plates) 
            : plates_(plates), validated_(false) {
            validateInput();
        }

        size_t findPlatePosition(const ValueType& target) const {
            if (!validated_) {
                throw runtime_error("Input not validated");
            }

            Container sortedPlates = plates_;
            sort(sortedPlates.begin(), sortedPlates.end(), 
                NumberPlateComparator<ValueType>());

            auto it = find(sortedPlates.begin(), sortedPlates.end(), target);
            if (it == sortedPlates.end()) {
                throw out_of_range("Target plate not found");
            }

            return distance(sortedPlates.begin(), it) + 1;
        }

    private:
        void validateInput() {
            if (plates_.empty()) {
                throw invalid_argument("Empty plate list");
            }
            for (const auto& plate : plates_) {
                if (plate < 0) {
                    throw invalid_argument("Negative plate value");
                }
            }
            validated_ = true;
        }

        const Container& plates_;
        bool validated_;
    };
}

