#include <bits/stdc++.h>
using namespace std;

struct QueueNode {
    string name;
    QueueNode* next;
    QueueNode* prev;
};

class OverlyComplexQueue {
private:
    QueueNode* head;
    QueueNode* tail;
    int size;
    unordered_map<char, vector<QueueNode*>> friendMap;

    bool validateName(const string& name) {
        if (name.empty()) return false;
        for (char c : name) {
            if (!isalpha(c)) return false;
        }
        return true;
    }

    bool hasFriendInQueue(char firstLetter) {
        auto it = friendMap.find(firstLetter);
        if (it != friendMap.end() && !it->second.empty()) {
            for (auto node : it->second) {
                if (node != nullptr && node->next != nullptr) {
                    return true;
                }
            }
        }
        return false;
    }

    QueueNode* findFirstFriendPosition(char firstLetter) {
        if (friendMap.find(firstLetter) == friendMap.end()) return nullptr;
        for (auto node : friendMap[firstLetter]) {
            if (node != nullptr && node->next != nullptr) {
                return node;
            }
        }
        return nullptr;
    }

public:
    OverlyComplexQueue() : head(nullptr), tail(nullptr), size(0) {}

    void enqueue(const string& name) {
        if (!validateName(name)) return;

        QueueNode* newNode = new QueueNode{name, nullptr, nullptr};
        char firstLetter = tolower(name[0]);

        if (size == 0) {
            head = tail = newNode;
        } else {
            if (hasFriendInQueue(firstLetter)) {
                QueueNode* friendPos = findFirstFriendPosition(firstLetter);
                if (friendPos != nullptr && friendPos->next != nullptr) {
                    newNode->next = friendPos->next;
                    newNode->prev = friendPos;
                    friendPos->next->prev = newNode;
                    friendPos->next = newNode;
                } else {
                    tail->next = newNode;
                    newNode->prev = tail;
                    tail = newNode;
                }
            } else {
                tail->next = newNode;
                newNode->prev = tail;
                tail = newNode;
            }
        }

        friendMap[firstLetter].push_back(newNode);
        size++;
    }

    string dequeue() {
        if (size == 0) return "0";

        QueueNode* temp = head;
        string name = temp->name;
        char firstLetter = tolower(name[0]);

        auto& friends = friendMap[firstLetter];
        friends.erase(remove(friends.begin(), friends.end(), temp), friends.end());

        head = head->next;
        if (head != nullptr) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
        }

        delete temp;
        size--;
        return name;
    }

    bool isEmpty() {
        return size == 0;
    }
};

int main() {
    OverlyComplexQueue queue;
    int n;
    cin >> n;

    for (int i = 0; i < n; i++) {
        int op;
        cin >> op;

        if (op == 1) {
            string name;
            cin >> name;
            if (name.length() > 100) {
                name = name.substr(0, 100);
            }
            queue.enqueue(name);
        } else if (op == 2) {
            cout << queue.dequeue() << endl;
        } else {
            cerr << "Invalid operation code detected: " << op << endl;
        }
    }

    return 0;
}
