using namespace std;

bool validateSentence(const string& sentence) {
    if (sentence.empty()) return false;
    for (char c : sentence) {
        if (!isalpha(c) && !isspace(c)) {
            return false;
        }
    }
    return true;
}

vector<string> tokenizeSentence(const string& sentence) {
    vector<string> tokens;
    string token;
    istringstream tokenStream(sentence);
    while (tokenStream >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

string findLongestWordWithValidation(const vector<string>& words) {
    if (words.empty()) throw runtime_error("No words found in sentence");

    string longest;
    size_t max_len = 0;
    bool has_alpha = false;

    for (const auto& word : words) {
        bool current_has_alpha = false;
        for (char c : word) {
            if (isalpha(c)) {
                current_has_alpha = true;
                break;
            }
        }

        if (!current_has_alpha) continue;

        if (word.length() > max_len || 
            (word.length() == max_len && !has_alpha)) {
            longest = word;
            max_len = word.length();
            has_alpha = current_has_alpha;
        }
    }

    if (!has_alpha) throw runtime_error("No valid words found");
    return longest;
}

void processSentence(const string& sentence) {
    if (!validateSentence(sentence)) {
        cerr << "Invalid sentence format" << endl;
        return;
    }

    vector<string> words = tokenizeSentence(sentence);

    try {
        string longest = findLongestWordWithValidation(words);
        cout << longest << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
    }
}

int main() {
    string input;
    try {
        if (!getline(cin, input)) {
            throw runtime_error("Failed to read input");
        }

        processSentence(input);
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
