#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <iterator>
#include <stdexcept>

using namespace std;

struct WordMetadata {
    string content;
    size_t position;
    size_t length;
};

bool compareWordMetadata(const WordMetadata& a, const WordMetadata& b) {
    if (a.length != b.length) {
        return a.length > b.length;
    }
    return a.position < b.position;
}

void validateInputString(const string& input) {
    if (input.empty()) {
        throw runtime_error("Input string cannot be empty");
    }
    if (input.find_first_not_of(" abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ") != string::npos) {
        throw runtime_error("Input contains invalid characters");
    }
}

vector<string> tokenizeStringWithValidation(const string& input) {
    istringstream iss(input);
    vector<string> tokens;
    copy(istream_iterator<string>(iss),
         istream_iterator<string>(),
         back_inserter(tokens));

    if (tokens.empty()) {
        throw runtime_error("No words found in input");
    }

    return tokens;
}

vector<WordMetadata> createWordMetadataVector(const vector<string>& tokens) {
    vector<WordMetadata> wordData;
    for (size_t i = 0; i < tokens.size(); ++i) {
        WordMetadata wm;
        wm.content = tokens[i];
        wm.position = i;
        wm.length = tokens[i].length();
        wordData.push_back(wm);
    }
    return wordData;
}

string determineLongestWord(const vector<WordMetadata>& wordData) {
    if (wordData.empty()) {
        throw runtime_error("Word metadata vector is empty");
    }

    vector<WordMetadata> sortedWordData = wordData;
    stable_sort(sortedWordData.begin(), sortedWordData.end(), compareWordMetadata);

    return sortedWordData.front().content;
}

int main() {
    try {
        string input;
        getline(cin, input);

        validateInputString(input);

        vector<string> tokens = tokenizeStringWithValidation(input);

        vector<WordMetadata> wordData = createWordMetadataVector(tokens);

        string result = determineLongestWord(wordData);

        cout << result << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

