#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cctype>
#include <stdexcept>
using namespace std;

struct WordMetadata {
    string content;
    size_t position;
    size_t length;
};

class SentenceProcessor {
private:
    string sentence;
    vector<WordMetadata> words;
    bool processed;

    void validateInput() {
        if (sentence.empty()) {
            throw runtime_error("Empty input sentence");
        }
        for (char c : sentence) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Invalid character in input");
            }
        }
    }

    void tokenizeSentence() {
        istringstream iss(sentence);
        string token;
        size_t pos = 0;
        while (iss >> token) {
            WordMetadata wm;
            wm.content = token;
            wm.position = pos;
            wm.length = token.size();
            words.push_back(wm);
            pos += token.size() + 1;
        }
        if (words.empty()) {
            throw runtime_error("No words found in sentence");
        }
    }

public:
    explicit SentenceProcessor(const string& input) : sentence(input), processed(false) {
        validateInput();
    }

    void process() {
        tokenizeSentence();
        processed = true;
    }

    string findLongestWord() {
        if (!processed) {
            process();
        }

        if (words.size() == 1) {
            return words[0].content;
        }

        vector<WordMetadata> candidates;
        size_t max_len = 0;

        for (const auto& word : words) {
            if (word.length > max_len) {
                max_len = word.length;
                candidates.clear();
                candidates.push_back(word);
            } else if (word.length == max_len) {
                candidates.push_back(word);
            }
        }

        if (candidates.empty()) {
            throw runtime_error("No candidates found");
        }

        WordMetadata result = candidates[0];
        for (const auto& candidate : candidates) {
            if (candidate.position < result.position) {
                result = candidate;
            }
        }

        return result.content;
    }
};

int main() {
    try {
        string input;
        getline(cin, input);

        SentenceProcessor processor(input);
        processor.process();

        string longestWord = processor.findLongestWord();

        if (longestWord.empty()) {
            cerr << "Error: Empty longest word detected" << endl;
            return 1;
        }

        cout << longestWord << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
