bool is_valid_word_char(char c) {
    return isalpha(static_cast<unsigned char>(c)) || c == '\'';
}

string sanitize_word(const string& word) {
    string sanitized;
    for (char c : word) {
        if (is_valid_word_char(c)) {
            sanitized += tolower(c);
        }
    }
    return sanitized;
}

vector<string> tokenize_sentence(const string& sentence) {
    vector<string> tokens;
    istringstream iss(sentence);
    copy(istream_iterator<string>(iss),
         istream_iterator<string>(),
         back_inserter(tokens));
    return tokens;
}

pair<string, size_t> find_longest_valid_word(const vector<string>& words) {
    string current_longest;
    size_t max_length = 0;
    bool found_valid = false;

    for (const auto& word : words) {
        string sanitized = sanitize_word(word);
        if (!sanitized.empty()) {
            found_valid = true;
            if (sanitized.length() > max_length) {
                max_length = sanitized.length();
                current_longest = word;
            }
        }
    }

    if (!found_valid) {
        return make_pair("", 0);
    }

    return make_pair(current_longest, max_length);
}

