#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cctype>
#include <stdexcept>

using namespace std;

struct WordData {
    string content;
    size_t position;
    size_t length;
};

void validateInput(const string& input) {
    if (input.empty()) {
        throw runtime_error("Empty input detected");
    }
    for (char c : input) {
        if (!isalpha(c) && !isspace(c)) {
            throw runtime_error("Invalid character in input");
        }
    }
}

vector<WordData> processWords(const string& input) {
    vector<WordData> words;
    istringstream iss(input);
    string token;
    size_t pos = 0;

    while (iss >> token) {
        words.push_back({token, pos, token.length()});
        pos += token.length() + 1;
    }

    if (words.empty()) {
        throw runtime_error("No words found in input");
    }

    return words;
}

WordData findLongestWord(const vector<WordData>& words) {
    if (words.size() == 1) {
        return words[0];
    }

    WordData longest = words[0];
    bool hasTies = false;
    vector<WordData> candidates;

    for (const auto& word : words) {
        if (word.length > longest.length) {
            longest = word;
            hasTies = false;
            candidates.clear();
        } else if (word.length == longest.length) {
            hasTies = true;
            candidates.push_back(word);
        }
    }

    if (hasTies) {
        for (const auto& candidate : candidates) {
            if (candidate.position < longest.position) {
                longest = candidate;
            }
        }
    }

    return longest;
}

void verifyResult(const WordData& result, const string& original) {
    if (result.content.empty()) {
        throw runtime_error("Result verification failed: empty word");
    }
    if (original.find(result.content) == string::npos) {
        throw runtime_error("Result verification failed: word not found in original");
    }
}

int main() {
    try {
        string input;
        getline(cin, input);

        validateInput(input);

        vector<WordData> words = processWords(input);

        WordData result = findLongestWord(words);

        verifyResult(result, input);

        cout << result.content << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
