#include <bits/stdc++.h>
using namespace std;

const int MAX_NODES = 1005;
const int INVALID_NODE = -1;
const int DEFAULT_DEGREE = 0;
const int MIN_TEST_CASES = 1;
const int MAX_TEST_CASES = 100;
const int MIN_NODES = 1;
const int MAX_NODES = 1000;

struct TreeValidationResult {
    bool isValid;
    string errorMessage;
};

struct NodeDegreeInfo {
    int degree;
    bool isPNode;
};

vector<vector<int>> adjacencyMatrix(MAX_NODES, vector<int>(MAX_NODES, 0));
vector<NodeDegreeInfo> nodeDegrees(MAX_NODES, {DEFAULT_DEGREE, false});
vector<bool> visitedNodes(MAX_NODES, false);
vector<int> parentNodes(MAX_NODES, INVALID_NODE);

TreeValidationResult validateInput(int t, int n) {
    TreeValidationResult result = {true, ""};
    if (t < MIN_TEST_CASES || t > MAX_TEST_CASES) {
        result.isValid = false;
        result.errorMessage = "Invalid number of test cases";
    }
    if (n < MIN_NODES || n > MAX_NODES) {
        result.isValid = false;
        result.errorMessage = "Invalid number of nodes";
    }
    return result;
}

void resetGlobalDataStructures() {
    for (int i = 0; i < MAX_NODES; ++i) {
        fill(adjacencyMatrix[i].begin(), adjacencyMatrix[i].end(), 0);
        nodeDegrees[i] = {DEFAULT_DEGREE, false};
        visitedNodes[i] = false;
        parentNodes[i] = INVALID_NODE;
    }
}

void buildTree(int n) {
    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        cin >> x >> y;
        if (x < 0 || x >= n || y < 0 || y >= n) {
            cerr << "Invalid node indices" << endl;
            continue;
        }
        adjacencyMatrix[x][y] = 1;
        nodeDegrees[x].degree++;
        parentNodes[y] = x;
    }
}

void performDFS(int currentNode, int n) {
    visitedNodes[currentNode] = true;
    bool qualifiesAsPNode = true;

    for (int neighbor = 0; neighbor < n; ++neighbor) {
        if (adjacencyMatrix[currentNode][neighbor] && !visitedNodes[neighbor]) {
            if (nodeDegrees[currentNode].degree < nodeDegrees[neighbor].degree) {
                qualifiesAsPNode = false;
            }
            performDFS(neighbor, n);
        }
    }

    if (parentNodes[currentNode] != INVALID_NODE) {
        if (nodeDegrees[currentNode].degree > nodeDegrees[parentNodes[currentNode]].degree) {
            qualifiesAsPNode = false;
        }
    }

    nodeDegrees[currentNode].isPNode = qualifiesAsPNode;
}

int countPNodes(int n) {
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (nodeDegrees[i].isPNode) {
            count++;
        }
    }
    return count;
}

int main() {
    freopen("p.in", "r", stdin);
    freopen("p.out", "w", stdout);

    int t;
    cin >> t;

    auto validation = validateInput(t, t);
    if (!validation.isValid) {
        cerr << validation.errorMessage << endl;
        return 1;
    }

    while (t--) {
        int n;
        cin >> n;

        validation = validateInput(1, n);
        if (!validation.isValid) {
            cerr << validation.errorMessage << endl;
            continue;
        }

        resetGlobalDataStructures();
        buildTree(n);

        for (int i = 0; i < n; ++i) {
            if (!visitedNodes[i]) {
                performDFS(i, n);
            }
        }

        cout << countPNodes(n) << endl;
    }

    return 0;
}
