using namespace std;

struct NumberWithSum {
    int original;
    int digit_sum;
};

vector<NumberWithSum> preprocessed_numbers;
vector<int> input_buffer;

int calculate_digit_sum(int x) {
    if(x < 0) {
        throw invalid_argument("Negative numbers not supported");
    }
    if(x >= 10000) {
        throw out_of_range("Number exceeds maximum allowed value");
    }
    int accumulated_sum = 0;
    int remaining_value = x;
    while(remaining_value != 0) {
        int extracted_digit = remaining_value % 10;
        accumulated_sum += extracted_digit;
        remaining_value = remaining_value / 10;
        if(accumulated_sum > numeric_limits<int>::max() - 9) {
            throw overflow_error("Digit sum overflow detected");
        }
    }
    return accumulated_sum;
}

bool compare_numbers(const NumberWithSum& num1, const NumberWithSum& num2) {
    if(num1.digit_sum != num2.digit_sum) {
        return num1.digit_sum < num2.digit_sum;
    }
    return num1.original < num2.original;
}

void validate_input_count(int count) {
    if(count <= 0 || count >= 101) {
        throw range_error("Invalid input count detected");
    }
}

void process_input_numbers(int count) {
