            throw runtime_error("Invalid input format detected");
        }
        if(input_buffer[i] <= 0 || input_buffer[i] >= 10000) {
            throw out_of_range("Input number out of valid range");
        }
    }
}

void prepare_sorting_data() {
    preprocessed_numbers.resize(input_buffer.size());
    for(size_t i = 0; i < input_buffer.size(); i++) {
        preprocessed_numbers[i].original = input_buffer[i];
        preprocessed_numbers[i].digit_sum = calculate_digit_sum(input_buffer[i]);
