#include<type_traits>
using namespace std;

template<typename T>
constexpr bool is_valid_integer_type = is_integral_v<T> && is_unsigned_v<T>;

template<typename T>
T validate_input_range(T value, T min_val, T max_val) {
    static_assert(is_valid_integer_type<T>, "Invalid integer type for validation");
    if (value <= min_val || value >= max_val) {
        throw out_of_range("Input value out of specified range");
    }
    return value;
}

template<typename T>
T calculate_digit_sum(T num) noexcept {
    static_assert(is_valid_integer_type<T>, "Invalid type for digit sum calculation");
    T sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
        if (sum > numeric_limits<T>::max() / 10) {
            sum = numeric_limits<T>::max();
            break;
        }
    }
    return sum;
}

template<typename T>
struct DigitSumComparator {
    static_assert(is_valid_integer_type<T>, "Invalid type for comparator");
    bool operator()(T a, T b) const {
        T sum_a = calculate_digit_sum(a);
        T sum_b = calculate_digit_sum(b);
        if (sum_a != sum_b) {
            return sum_a < sum_b;
        } else {
            if (a != b) {
                return a < b;
            } else {
                return false;
            }
        }
    }
};

template<typename T>
void validate_array_elements(const vector<T>& arr, T max_val) {
    static_assert(is_valid_integer_type<T>, "Invalid type for array validation");
    for (const auto& elem : arr) {
        if (elem >= max_val) {
            throw invalid_argument("Array element exceeds maximum allowed value");
        }
    }
}

template<typename T>
void print_sorted_array(const vector<T>& arr) {
    static_assert(is_valid_integer_type<T>, "Invalid type for printing");
    for (size_t i = 0; i < arr.size(); ++i) {
        cout << arr[i];
        if (i != arr.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;
}

