        for (const auto& row : adjacencyMatrix) {
            int x = row.first;
            for (const auto& entry : row.second) {
                if (entry.second) {
                    int y = entry.first;
                    nodes[x].children.push_back(y);
                    nodes[y].parent = x;
                }
            }
        }
    }

    void calculateDegrees() {
        for (int i = 0; i < n; ++i) {
            nodes[i].degree = nodes[i].children.size();
            if (nodes[i].parent != -1) {
