            relatedNodes.push_back(node.parent);
        }
        relatedNodes.insert(relatedNodes.end(), node.children.begin(), node.children.end());

        for (int relatedId : relatedNodes) {
            if (relatedId < 0 || relatedId >= n) continue;
            if (nodes[relatedId].degree > node.degree) {
                return false;
            }
        }

        return true;
    }

