    weak_ptr<TreeNode> parent;
};

class TreeAnalyzer {
private:
    vector<shared_ptr<TreeNode>> nodes;
    unordered_map<int, shared_ptr<TreeNode>> node_map;
    int node_count;

    void validateInput(int x, int y) {
        if (x < 0 || y < 0 || x >= node_count || y >= node_count) {
            throw out_of_range("Node index out of bounds");
        }
        if (x == y) {
            throw invalid_argument("Node cannot be its own parent");
        }
    }

    void initializeNodes(int n) {
        nodes.clear();
        node_map.clear();
        node_count = n;
        for (int i = 0; i < n; ++i) {
            auto node = make_shared<TreeNode>();
            node->id = i;
            node->degree = 0;
            nodes.push_back(node);
            node_map[i] = node;
        }
    }

    void buildTree(const vector<pair<int, int>>& edges) {
        for (const auto& edge : edges) {
            int x = edge.first;
            int y = edge.second;
            validateInput(x, y);
            auto parent_node = node_map[x];
            auto child_node = node_map[y];
            parent_node->children.push_back(child_node);
            child_node->parent = parent_node;
            parent_node->degree++;
            child_node->degree++;
        }
    }

    bool isPNode(const shared_ptr<TreeNode>& node) {
        if (!node) return false;
        int current_degree = node->degree;

        if (!node->parent.expired()) {
            auto parent = node->parent.lock();
            if (parent && current_degree < parent->degree) {
                return false;
            }
        }

        for (const auto& child : node->children) {
            if (child && current_degree < child->degree) {
                return false;
            }
        }

        return true;
    }

public:
    int countPNodes(int n, const vector<pair<int, int>>& edges) {
        try {
            initializeNodes(n);
            buildTree(edges);
            int count = 0;
            for (const auto& node : nodes) {
                if (isPNode(node)) {
                    count++;
                }
            }
            return count;
