#include <algorithm>
#include <fstream>
#include <stdexcept>
#include <limits>

using namespace std;

struct TreeValidationResult {
    bool isValid;
    string errorMessage;
};

TreeValidationResult validateTreeStructure(const vector<vector<int>>& adjacencyList, int n) {
    vector<bool> visited(n, false);
    vector<int> parent(n, -1);
    bool hasCycle = false;

    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            vector<int> stack;
            stack.push_back(i);
            visited[i] = true;

            while (!stack.empty()) {
                int current = stack.back();
                stack.pop_back();

                for (int neighbor : adjacencyList[current]) {
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        parent[neighbor] = current;
                        stack.push_back(neighbor);
                    } else if (neighbor != parent[current]) {
                        hasCycle = true;
                    }
                }
            }
        }
    }

    if (hasCycle) {
        return {false, "Tree contains cycle"};
    }

    int rootCount = 0;
    for (int i = 0; i < n; ++i) {
        if (parent[i] == -1) {
            rootCount++;
        }
    }

    if (rootCount != 1) {
        return {false, "Tree has multiple roots"};
    }

    return {true, ""};
}

void processTestCase(ifstream& inputFile, ofstream& outputFile) {
    int n;
    inputFile >> n;

    if (n < 1 || n > 1000) {
        throw out_of_range("Invalid number of nodes");
    }

    vector<vector<int>> adjacencyList(n);
    vector<int> degree(n, 0);

    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        inputFile >> x >> y;

        if (x < 0 || x >= n || y < 0 || y >= n) {
            throw out_of_range("Invalid node index");
        }

        adjacencyList[x].push_back(y);
        degree[x]++;
        degree[y]++;
    }

    TreeValidationResult validation = validateTreeStructure(adjacencyList, n);
    if (!validation.isValid) {
        throw invalid_argument(validation.errorMessage);
    }

    vector<bool> isPNode(n, false);
    vector<int> parent(n, -1);

    for (int i = 0; i < n; ++i) {
        for (int child : adjacencyList[i]) {
            parent[child] = i;
        }
    }

    for (int i = 0; i < n; ++i) {
        bool satisfiesCondition = true;

        for (int child : adjacencyList[i]) {
            if (degree[i] < degree[child]) {
                satisfiesCondition = false;
                break;
            }
        }

        if (parent[i] != -1 && degree[i] < degree[parent[i]]) {
            satisfiesCondition = false;
        }

        isPNode[i] = satisfiesCondition;
    }

    int pNodeCount = count(isPNode.begin(), isPNode.end(), true);
    outputFile << pNodeCount << endl;
}

int main() {
    ifstream inputFile("p.in");
    ofstream outputFile("p.out");

