        while (current != nullptr) {
            this->enqueue(current->name);
            current = current->next;
        }
    }

public:
    OverlyComplexQueue() : head(nullptr), tail(nullptr), size(0) {}

    OverlyComplexQueue(const OverlyComplexQueue& other) {
        performDeepCopy(other);
    }

    ~OverlyComplexQueue() {
        while (head != nullptr) {
            QueueNode* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void enqueue(const string& name) {
