        ss << "Invalid input values: " << x << ", " << y;
        throw invalid_argument(ss.str());
    }
}

int calculateAbsoluteDifference(int a, int b) {
    return abs(a - b);
}

int findMinimumValue(int a, int b) {
    return min(a, b);
}

DataSet processDataSet(int x, int y, int index) {
    DataSet ds;
    ds.x = x;
    ds.y = y;
    ds.min_val = findMinimumValue(x, y);
    ds.diff = calculateAbsoluteDifference(x, y);
    ds.index = index;
