#include <bits/stdc++.h>
using namespace std;

struct DecryptionContext {
    stack<char> charStack;
    stack<int> multiplierStack;
    vector<string> tempResults;
    bool inNestedContext;
    int currentMultiplier;
    string currentSegment;
};

void validateInputString(const string& s) {
    if (s.empty()) {
        throw runtime_error("Empty input string");
    }
    if (s.find('(') == string::npos || s.find(')') == string::npos) {
        throw runtime_error("Invalid encryption format");
    }
    for (char c : s) {
        if (!(isdigit(c) || isalpha(c) || c == '(' || c == ')')) {
            throw runtime_error("Invalid character in input");
        }
    }
}

void processClosingBracket(DecryptionContext& context, const string& s, int i) {
    if (context.charStack.empty()) {
        throw runtime_error("Unmatched closing bracket");
    }

    string segment;
    while (!context.charStack.empty() && context.charStack.top() != '(') {
        segment = context.charStack.top() + segment;
        context.charStack.pop();
    }

    if (context.charStack.empty()) {
        throw runtime_error("Unmatched closing bracket");
    }

    context.charStack.pop();

    if (context.charStack.empty() || !isdigit(context.charStack.top())) {
        throw runtime_error("Missing multiplier before bracket");
    }

    int multiplier = context.charStack.top() - '0';
    context.charStack.pop();

    string multipliedSegment;
    for (int j = 0; j < multiplier; j++) {
        multipliedSegment += segment;
    }

    if (context.inNestedContext) {
        context.currentSegment = multipliedSegment + context.currentSegment;
    } else {
        for (char c : multipliedSegment) {
            context.charStack.push(c);
        }
    }
}

void handleNumericCharacter(DecryptionContext& context, char c) {
    if (context.inNestedContext) {
        context.currentMultiplier = c - '0';
        context.multiplierStack.push(context.currentMultiplier);
    } else {
        context.charStack.push(c);
    }
}

void handleOpeningBracket(DecryptionContext& context) {
    if (context.inNestedContext) {
        context.tempResults.push_back(context.currentSegment);
        context.currentSegment.clear();
    }
    context.inNestedContext = true;
}

string decryptString(const string& s) {
    DecryptionContext context;
    context.inNestedContext = false;
    context.currentMultiplier = 1;

    validateInputString(s);

    for (int i = 0; i < s.size(); i++) {
        char c = s[i];
        if (isdigit(c)) {
            handleNumericCharacter(context, c);
        } else if (c == '(') {
            handleOpeningBracket(context);
        } else if (c == ')') {
            processClosingBracket(context, s, i);
        } else if (isalpha(c)) {
            if (context.inNestedContext) {
                context.currentSegment += c;
            } else {
                context.charStack.push(c);
            }
        } else {
            throw runtime_error("Invalid character encountered");
        }
    }

    if (context.inNestedContext && !context.currentSegment.empty()) {
        context.tempResults.push_back(context.currentSegment);
    }

    string result;
    while (!context.charStack.empty()) {
        result = context.charStack.top() + result;
        context.charStack.pop();
    }

    for (const string& temp : context.tempResults) {
        result += temp;
    }

    if (result.empty()) {
        throw runtime_error("Empty decryption result");
    }

    return result;
}

