#include <bits/stdc++.h>
using namespace std;

bool is_valid_digit(char c) {
    return c >= '0' && c <= '9';
}

bool is_valid_parenthesis(char c) {
    return c == '(' || c == ')';
}

bool is_valid_character(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

string reverse_string_with_validation(const string& s) {
    string reversed;
    for (int i = s.length() - 1; i >= 0; --i) {
        if (is_valid_character(s[i]) || is_valid_parenthesis(s[i]) || is_valid_digit(s[i])) {
            reversed += s[i];
        }
    }
    return reversed;
}

int safe_char_to_int(char c) {
    if (!is_valid_digit(c)) {
        return 0;
    }
    return c - '0';
}

string process_stack_contents(stack<char>& st) {
    string accumulated;
    while (!st.empty()) {
        char current = st.top();
        st.pop();
        if (is_valid_character(current) || is_valid_digit(current)) {
            accumulated += current;
        }
    }
    return reverse_string_with_validation(accumulated);
}

void handle_nested_expression(stack<char>& st, const string& input, int& index) {
    string temporary_buffer;
    string intermediate_result;
    while (!st.empty() && st.top() != '(') {
        char top_element = st.top();
        if (is_valid_character(top_element)) {
            temporary_buffer += top_element;
        }
        st.pop();
    }
    if (!st.empty() && st.top() == '(') {
        st.pop();
    }
    temporary_buffer = reverse_string_with_validation(temporary_buffer);
    if (!st.empty() && is_valid_digit(st.top())) {
        int repetition_factor = safe_char_to_int(st.top());
        st.pop();
        for (int j = 0; j < repetition_factor; ++j) {
            intermediate_result += temporary_buffer;
        }
    }
    for (int j = intermediate_result.length() - 1; j >= 0; --j) {
        st.push(intermediate_result[j]);
    }
    if (index + 1 < input.length() && input[index + 1] == ')') {
        index++;
    }
}

int main() {
    string input;
    cin >> input;
    stack<char> processing_stack;
    string final_output;
    string auxiliary_buffer;
    for (int i = 0; i < input.size(); ++i) {
        if (input[i] != ')') {
            processing_stack.push(input[i]);
        } else {
            handle_nested_expression(processing_stack, input, i);
        }
    }
    final_output = process_stack_contents(processing_stack);
    cout << final_output;
    return 0;
}
