    for (char c : s) {
        if (c == '(') open_count++;
        else if (c == ')') {
            if (open_count <= 0) return false;
            open_count--;
        }
        else if (!isdigit(c) && !isalpha(c)) {
            return false;
        }
    }
    return open_count == 0;
}

string processNestedPattern(const string& s) {
    stack<string> charStack;
    stack<int> numStack;
    string current;
    int i = 0;
    while (i < s.size()) {
        if (isdigit(s[i])) {
            int num = 0;
            while (i < s.size() && isdigit(s[i])) {
                num = num * 10 + (s[i] - '0');
                i++;
            }
            numStack.push(num);
        } else if (s[i] == '(') {
            charStack.push(current);
            current = "";
            i++;
        } else if (s[i] == ')') {
            string temp = charStack.top();
            charStack.pop();
            int repeat = numStack.top();
            numStack.pop();
            string repeated;
            for (int j = 0; j < repeat; j++) {
                repeated += current;
            }
            current = temp + repeated;
            i++;
        } else {
            if (!isalpha(s[i])) {
                throw invalid_argument("Invalid character in input");
            }
            current += s[i];
            i++;
        }
    }
    return current;
}

string decodeString(const string& s) {
    if (!validateString(s)) {
        throw invalid_argument("Invalid input string format");
    }
    stack<string> segmentStack;
    stack<int> multiplierStack;
    string currentSegment;
    int i = 0;
    while (i < s.size()) {
        if (isdigit(s[i])) {
            if (!currentSegment.empty()) {
                segmentStack.push(currentSegment);
                currentSegment.clear();
            }
            int num = 0;
            while (i < s.size() && isdigit(s[i])) {
                num = num * 10 + (s[i] - '0');
                i++;
            }
            multiplierStack.push(num);
        } else if (s[i] == '(') {
            segmentStack.push(currentSegment);
            currentSegment.clear();
            i++;
        } else if (s[i] == ')') {
            string temp = segmentStack.top();
            segmentStack.pop();
            int repeat = multiplierStack.top();
            multiplierStack.pop();
            string repeated;
            for (int j = 0; j < repeat; j++) {
                repeated += currentSegment;
            }
            currentSegment = temp + repeated;
            i++;
        } else {
            if (!isalpha(s[i])) {
                throw runtime_error("Unexpected non-alphabetic character");
            }
            currentSegment += s[i];
            i++;
        }
    }
    while (!segmentStack.empty()) {
        string temp = segmentStack.top();
        segmentStack.pop();
        currentSegment = temp + currentSegment;
    }
    return currentSegment;
}

int main() {
