#include<bits/stdc++.h>
using namespace std;

struct StackValidator {
    static bool validateStackOperation(const stack<int>& s, const string& op) {
        if (op == "D" && s.empty()) {
            return false;
        }
        return true;
    }
};

class StackMerger {
public:
    static void mergeStacks(stack<int>& dest, stack<int>& src, stack<int>& temp) {
        stack<int> intermediate;
        while (!src.empty()) {
            intermediate.push(src.top());
            src.pop();
        }
        while (!intermediate.empty()) {
            temp.push(intermediate.top());
            intermediate.pop();
        }
        while (!dest.empty()) {
            intermediate.push(dest.top());
            dest.pop();
        }
        while (!intermediate.empty()) {
            temp.push(intermediate.top());
            intermediate.pop();
        }
        while (!temp.empty()) {
            dest.push(temp.top());
            temp.pop();
        }
    }
};

class StackPrinter {
public:
    static void printStack(stack<int>& s) {
        vector<int> temp;
        while (!s.empty()) {
            temp.push_back(s.top());
            s.pop();
        }
        reverse(temp.begin(), temp.end());
        for (size_t i = 0; i < temp.size(); ++i) {
            cout << temp[i];
            if (i != temp.size() - 1) {
                cout << " ";
            }
        }
        cout << endl;
    }
};

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    stack<int> a, b, temp;
    string currentStack;
    char operation;
    int data;

    for (int i = 0; i < n; ++i) {
        cin >> currentStack;
        if (currentStack != "A" && currentStack != "B") {
