        } else if (operation == 'D') {
            if (currentStack == "A") {
                if (StackValidator::validateStackOperation(a, "D")) {
                    a.pop();
                }
            } else {
                if (StackValidator::validateStackOperation(b, "D")) {
                    b.pop();
                }
            }
        } else if (operation == 'M') {
            if (currentStack == "A") {
                StackMerger::mergeStacks(a, b, temp);
            } else {
                StackMerger::mergeStacks(b, a, temp);
            }
        }
    }

    stack<int> a_copy = a, b_copy = b;
    StackPrinter::printStack(a_copy);
    StackPrinter::printStack(b_copy);

