using namespace std;

struct WordMetadata {
    string content;
    bool processed;
    bool is_punctuation;
};

vector<WordMetadata> preprocess_string(const string& input) {
    vector<WordMetadata> words;
    string current_word;
    for (char c : input) {
        if (isalpha(c) || c == '\'') {
            char processed_char = c;
            if (isupper(c) && c != 'I') {
                processed_char = tolower(c);
            }
            current_word += processed_char;
        } else {
            if (!current_word.empty()) {
                words.push_back({current_word, false, false});
                current_word.clear();
            }
            if (c == '?') {
                words.push_back({"!", false, true});
            } else if (!isspace(c)) {
                string punct;
                punct += c;
                words.push_back({punct, false, true});
            }
        }
    }
    if (!current_word.empty()) {
        words.push_back({current_word, false, false});
    }
    return words;
}

vector<WordMetadata> apply_rule_three(vector<WordMetadata> words) {
    for (size_t i = 0; i + 1 < words.size(); ++i) {
        if (!words[i].processed && !words[i].is_punctuation && 
            !words[i+1].processed && !words[i+1].is_punctuation) {
            if ((words[i].content == "can" || words[i].content == "could") && 
                words[i+1].content == "you") {
                words[i].content = "I";
                words[i].processed = true;
                words[i+1].content = words[i].content == "can" ? "can" : "could";
                words[i+1].processed = true;
            }
        }
    }
    return words;
}

vector<WordMetadata> apply_rule_four(vector<WordMetadata> words) {
    for (auto& word : words) {
        if (!word.processed && !word.is_punctuation && 
            (word.content == "I" || word.content == "me")) {
            word.content = "you";
            word.processed = true;
        }
    }
    return words;
}

string reconstruct_sentence(const vector<WordMetadata>& words) {
    stringstream ss;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i > 0 && !words[i-1].is_punctuation && !words[i].is_punctuation) {
            ss << " ";
        }
        ss << words[i].content;
    }
    return ss.str();
}

string process_input_string(const string& input) {
    vector<WordMetadata> words = preprocess_string(input);
    words = apply_rule_three(words);
    words = apply_rule_four(words);
    return reconstruct_sentence(words);
}

int main() {
    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');
    vector<string> inputs;
    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        inputs.push_back(line);
    }
    for (const auto& input : inputs) {
        string processed = process_input_string(input);
        cout << processed << endl;
    }
    return 0;
}
