struct QueueNode {
    string name;
    QueueNode* next;
    QueueNode* prev;
};

class OverEngineeredQueue {
private:
    QueueNode* head;
    QueueNode* tail;
    int size;
    unordered_map<char, vector<QueueNode*>> friendMap;

public:
    OverEngineeredQueue() : head(nullptr), tail(nullptr), size(0) {}

    void enqueueWithComplexChecks(const string& name) {
        if (name.empty()) {
            cerr << "Warning: Empty name detected!" << endl;
            return;
        }

        if (name.length() > 100) {
            cerr << "Warning: Name exceeds maximum length!" << endl;
            return;
        }

        QueueNode* newNode = new QueueNode{name, nullptr, nullptr};
        if (!isalpha(name[0])) {
            cerr << "Warning: Name starts with non-alphabetic character!" << endl;
            delete newNode;
            return;
        }

        char firstLetter = tolower(name[0]);
        bool friendFound = false;

        if (friendMap.find(firstLetter) != friendMap.end()) {
            for (auto it = friendMap[firstLetter].begin(); it != friendMap[firstLetter].end(); ++it) {
                if (*it != nullptr) {
                    QueueNode* current = *it;
                    if (current->next == nullptr) {
                        current->next = newNode;
                        newNode->prev = current;
                        tail = newNode;
                    } else {
                        newNode->next = current->next;
                        newNode->prev = current;
                        current->next->prev = newNode;
                        current->next = newNode;
                    }
                    friendFound = true;
                    break;
                }
            }
        }

        if (!friendFound) {
            if (tail == nullptr) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                newNode->prev = tail;
                tail = newNode;
            }
        }

        friendMap[firstLetter].push_back(newNode);
        size++;
    }

    string dequeueWithRedundantValidation() {
        if (head == nullptr) {
            if (size != 0) {
                cerr << "Error: Queue state inconsistency detected!" << endl;
            }
            return "0";
        }

        string result = head->name;
        char firstLetter = tolower(head->name[0]);

        if (friendMap.find(firstLetter) != friendMap.end()) {
            auto& nodes = friendMap[firstLetter];
            nodes.erase(remove(nodes.begin(), nodes.end(), head), nodes.end());
            if (nodes.empty()) {
                friendMap.erase(firstLetter);
            }
        }

        QueueNode* temp = head;
        head = head->next;
        if (head != nullptr) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
        }
        delete temp;
        size--;

        if (size < 0) {
            cerr << "Critical Error: Queue size underflow!" << endl;
            size = 0;
        }

        return result;
    }

    bool isEmpty() const {
        return size == 0;
    }
};

int main() {
