struct QueueStateMonitor {
    int frontPointer;
    int rearPointer;
    vector<string> storage;

    QueueStateMonitor(int capacity) : frontPointer(0), rearPointer(0), storage(capacity) {}

    bool isEmpty() const {
        return frontPointer >= rearPointer;
    }

    bool isFull() const {
        return rearPointer >= storage.size();
    }
};

class AdvancedQueueManager {
private:
    QueueStateMonitor monitor;
    vector<string> temporaryInsertionBuffer;

public:
    AdvancedQueueManager(int maxCapacity) : monitor(maxCapacity) {}

    void processInsertionOperation(const string& name) {
        if (monitor.isFull()) {
            throw runtime_error("Queue capacity exceeded");
        }

        bool friendFound = false;
        char targetInitial = name.empty() ? '\0' : name[0];
        int insertionPosition = -1;

        for (int currentPosition = monitor.frontPointer; currentPosition < monitor.rearPointer; ++currentPosition) {
            if (!monitor.storage[currentPosition].empty() && monitor.storage[currentPosition][0] == targetInitial) {
                friendFound = true;
                insertionPosition = currentPosition;
                break;
            }
        }

        if (friendFound) {
            temporaryInsertionBuffer.clear();
            temporaryInsertionBuffer.reserve(monitor.rearPointer - monitor.frontPointer + 1);

            for (int i = monitor.frontPointer; i <= insertionPosition; ++i) {
                temporaryInsertionBuffer.push_back(monitor.storage[i]);
            }

            temporaryInsertionBuffer.push_back(name);

            for (int i = insertionPosition + 1; i < monitor.rearPointer; ++i) {
                temporaryInsertionBuffer.push_back(monitor.storage[i]);
            }

            for (size_t i = 0; i < temporaryInsertionBuffer.size(); ++i) {
                monitor.storage[monitor.frontPointer + i] = temporaryInsertionBuffer[i];
            }
        } else {
            monitor.storage[monitor.rearPointer] = name;
        }

        monitor.rearPointer++;
    }

    string processRemovalOperation() {
        if (monitor.isEmpty()) {
            return "0";
        }

        string removedElement = monitor.storage[monitor.frontPointer];
        monitor.frontPointer++;

        if (monitor.isEmpty()) {
            monitor.frontPointer = 0;
            monitor.rearPointer = 0;
        }

        return removedElement;
    }
};

