#include <vector>
#include <cctype>
#include <sstream>
#include <algorithm>
#include <iterator>
using namespace std;

bool is_word_character(char c) {
    return isalpha(c) || c == '\'' || c == '-';
}

vector<string> advanced_split(const string& s) {
    vector<string> tokens;
    string current_token;
    bool in_word = false;
    for (char c : s) {
        if (is_word_character(c)) {
            if (!in_word && !current_token.empty()) {
                tokens.push_back(current_token);
                current_token.clear();
            }
            current_token += c;
            in_word = true;
        } else {
            if (in_word) {
                tokens.push_back(current_token);
                current_token.clear();
                in_word = false;
            }
            if (c != ' ') {
                string punct;
                punct += c;
                tokens.push_back(punct);
            }
        }
    }
    if (!current_token.empty()) {
        tokens.push_back(current_token);
    }
    return tokens;
}

string process_case_and_punctuation(const string& s) {
    string result;
    for (char c : s) {
        if (c != 'I' && isupper(c)) {
            result += tolower(c);
        } else if (c == '?') {
            result += '!';
        } else {
            result += c;
        }
    }
    return result;
}

vector<string> apply_rule_4(const vector<string>& tokens) {
    vector<string> processed;
    vector<bool> replaced(tokens.size(), false);
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (!replaced[i] && (tokens[i] == "I" || tokens[i] == "me")) {
            processed.push_back("you");
            replaced[i] = true;
        } else {
            processed.push_back(tokens[i]);
        }
    }
    return processed;
}

vector<string> apply_rule_3(const vector<string>& tokens) {
    vector<string> processed;
    vector<bool> replaced(tokens.size(), false);
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (replaced[i]) {
            continue;
        }
        if (i + 1 < tokens.size() && !replaced[i+1] && 
            (tokens[i] == "can" || tokens[i] == "could") && tokens[i+1] == "you") {
            processed.push_back("I");
            processed.push_back(tokens[i]);
            replaced[i] = true;
            replaced[i+1] = true;
            i++;
        } else {
            processed.push_back(tokens[i]);
        }
    }
    return processed;
}

string reconstruct_sentence(const vector<string>& tokens) {
    string result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i > 0 && is_word_character(tokens[i][0]) && is_word_character(tokens[i-1][0])) {
            result += " ";
        }
        result += tokens[i];
    }
    return result;
}

