    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');
    vector<string> inputs;
    for (int i = 0; i < n; ++i) {
        string s;
        getline(cin, s);
        inputs.push_back(s);
    }
    for (string s : inputs) {
        string step1 = process_case_and_punctuation(s);
        vector<string> tokens = advanced_split(step1);
        vector<string> after_rule4 = apply_rule_4(tokens);
        vector<string> after_rule3 = apply_rule_3(after_rule4);
        string output = reconstruct_sentence(after_rule3);
        cout << output << endl;
    }
    return 0;
}
