#include <bits/stdc++.h>
using namespace std;

struct Person {
    string name;
    char first_letter;
    bool has_friend;
    int friend_position;
};

bool validateName(const string& name) {
    if (name.empty()) return false;
    for (char c : name) {
        if (!isalpha(c)) return false;
    }
    return true;
}

int findFriendPosition(const vector<Person>& queue, char first_letter) {
    for (int i = 0; i < queue.size(); ++i) {
        if (queue[i].first_letter == first_letter) {
            return i;
        }
    }
    return -1;
}

void insertPerson(vector<Person>& queue, const Person& p, int pos) {
    if (pos < 0 || pos > queue.size()) return;
    queue.insert(queue.begin() + pos + 1, p);
}

void handleEnqueue(vector<Person>& queue, const string& name) {
    if (!validateName(name)) return;

    Person new_person;
    new_person.name = name;
    new_person.first_letter = toupper(name[0]);
    new_person.has_friend = false;
    new_person.friend_position = -1;

    int friend_pos = findFriendPosition(queue, new_person.first_letter);
    if (friend_pos != -1) {
        new_person.has_friend = true;
        new_person.friend_position = friend_pos;
        insertPerson(queue, new_person, friend_pos);
    } else {
        queue.push_back(new_person);
    }
}

string handleDequeue(vector<Person>& queue) {
    if (queue.empty()) return "0";
    string front_name = queue.front().name;
    queue.erase(queue.begin());
    return front_name;
}

int main() {
    int n;
    cin >> n;
    if (n < 1 || n > 100) return 0;

    vector<Person> queue;
    queue.reserve(105);

    while (n--) {
        int k;
        cin >> k;
        if (k == 1) {
            string name;
            cin >> name;
            if (name.length() > 100) continue;
            handleEnqueue(queue, name);
        } else if (k == 2) {
            cout << handleDequeue(queue) << endl;
        } else {
            continue;
        }
    }

    return 0;
}
