    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else if (a.min_val != b.min_val) {
        return a.min_val < b.min_val;
    } else {
        return a.index < b.index;
    }
}

void validateInput(int value, int min_val, int max_val, const string& message) {
    if (value < min_val || value > max_val) {
        throw runtime_error(message);
    }
}

int computeDifference(int x, int y) {
    int diff = abs(x - y);
    if (diff < 0) {
        throw runtime_error("Difference cannot be negative");
    }
    return diff;
}

int findMinimumValue(int x, int y) {
    return min(x, y);
}

