            if (!(cin >> x >> y)) {
                throw runtime_error("Invalid input format");
            }
            validateInput(x, 1, 20, "Invalid X value");
            validateInput(y, 1, 20, "Invalid Y value");

            int diff = computeDifference(x, y);
            int min_val = findMinimumValue(x, y);

