    size_t original_position;
    size_t length;
};

class SentenceProcessor {
private:
    string raw_input;
    vector<string> tokenized_words;
    vector<WordMetadata> word_metadata_collection;
    bool input_validated;

    void validate_input_integrity() {
        if (raw_input.empty()) {
            input_validated = false;
            return;
        }
        for (char c : raw_input) {
            if (!isalpha(c) && !isspace(c)) {
                input_validated = false;
                return;
            }
        }
        input_validated = true;
    }

    void tokenize_with_redundant_checks() {
        if (!input_validated) return;

        istringstream input_stream(raw_input);
        string temporary_buffer;
        size_t position_counter = 0;

        while (input_stream >> temporary_buffer) {
            bool contains_non_alpha = false;
            for (char c : temporary_buffer) {
                if (!isalpha(c)) {
                    contains_non_alpha = true;
                    break;
                }
            }
            if (!contains_non_alpha) {
                tokenized_words.push_back(temporary_buffer);
                WordMetadata metadata;
                metadata.content = temporary_buffer;
                metadata.original_position = position_counter++;
                metadata.length = temporary_buffer.length();
                word_metadata_collection.push_back(metadata);
            }
        }
    }

public:
    explicit SentenceProcessor(const string& input) : raw_input(input), input_validated(false) {
        validate_input_integrity();
        tokenize_with_redundant_checks();
    }

    string find_longest_word_with_excessive_logic() {
        if (!input_validated || word_metadata_collection.empty()) {
            return "";
        }

        size_t max_length = 0;
        size_t earliest_position = numeric_limits<size_t>::max();
        string result;

        for (const auto& metadata : word_metadata_collection) {
            if (metadata.length > max_length) {
                max_length = metadata.length;
                earliest_position = metadata.original_position;
                result = metadata.content;
            } else if (metadata.length == max_length) {
                if (metadata.original_position < earliest_position) {
                    earliest_position = metadata.original_position;
                    result = metadata.content;
                }
            }
        }

        return result;
    }
};

int main() {
