        currentWord.clear();
        inWord = false;
    }

public:
    vector<string> extractWords(const string& sentence) {
        resetState();
        for (size_t i = 0; i < sentence.size(); ++i) {
            char c = sentence[i];
            if (isalpha(c)) {
                currentWord += c;
                inWord = true;
                if (i == sentence.size() - 1) {
                    words.push_back(currentWord);
                }
            } else {
                if (inWord) {
                    words.push_back(currentWord);
                    currentWord.clear();
                    inWord = false;
