        if (nodes.empty()) throw runtime_error("Tree not initialized");
        int root_count = 0;
        for (int i = 0; i < node_count; ++i) {
            if (nodes[i].parent_id == -1) {
                nodes[i].is_root = true;
                root_count++;
            }
            if (nodes[i].children.empty()) {
                nodes[i].is_leaf = true;
            }
        }
        if (root_count != 1) throw runtime_error("Invalid tree structure");
    }

    void calculate_degrees() {
        for (int i = 0; i < node_count; ++i) {
            nodes[i].degree = nodes[i].children.size();
            if (!nodes[i].is_root) {
                nodes[i].parent_degree = nodes[nodes[i].parent_id].degree;
            }
        }
    }

