#include <iostream>
#include <vector>
#include <fstream>
#include <algorithm>
#include <limits>
#include <utility>
using namespace std;

struct TreeNode {
    int degree = 0;
    int parent_degree = 0;
    int parent_id = -1;
    vector<int> children;
    bool is_processed = false;
};

struct TreeValidationResult {
    bool is_valid_tree = true;
    string validation_error = "";
};

struct NodeDegreeComparisonResult {
    bool all_children_satisfy = true;
    bool parent_satisfies = true;
};

TreeValidationResult validate_tree_structure(int node_count, const vector<pair<int, int>>& edges) {
    TreeValidationResult result;
    if (node_count <= 0) {
        result.is_valid_tree = false;
        result.validation_error = "Invalid node count";
        return result;
    }
    vector<bool> visited(node_count + 1, false);
    for (const auto& edge : edges) {
        if (edge.first <= 0 || edge.first >= node_count + 1 || edge.second <= 0 || edge.second >= node_count + 1) {
            result.is_valid_tree = false;
            result.validation_error = "Invalid node ID in edge";
            return result;
        }
        visited[edge.first] = true;
        visited[edge.second] = true;
    }
    int root_count = 0;
    for (int i = 1; i <= node_count; ++i) {
        if (!visited[i]) {
            root_count++;
        }
    }
    if (root_count != 1 && node_count > 1) {
        result.is_valid_tree = false;
        result.validation_error = "Multiple roots detected";
    }
    return result;
}

