TreeValidationResult validateTreeStructure(const vector<TreeNode>& tree, int n) {
    TreeValidationResult result;
    result.is_valid_tree = true;
    result.validation_message = "Tree structure appears valid";

    if (tree.size() != n + 1) {
        result.is_valid_tree = false;
        result.validation_message = "Tree size mismatch";
        return result;
    }

    vector<bool> visited(n + 1, false);
    int root_count = 0;
    for (int i = 1; i <= n; ++i) {
        if (tree[i].parent_id == -1) {
            root_count++;
        }
    }

    if (root_count != 1) {
        result.is_valid_tree = false;
        result.validation_message = "Invalid root count detected";
        return result;
    }

    return result;
}

void processTestCase(int test_case_number, int n, const vector<pair<int, int>>& edges) {
    vector<TreeNode> nodes(n + 1);

    for (const auto& edge : edges) {
        int x = edge.first;
        int y = edge.second;

        if (x < 1 || x > n || y < 1 || y > n) {
            cerr << "Invalid node ID in test case " << test_case_number << endl;
            return;
        }

        nodes[x].degree++;
        nodes[y].parent_degree = nodes[x].degree;
        nodes[y].parent_id = x;
        nodes[x].children.push_back(y);
    }

    TreeValidationResult validation = validateTreeStructure(nodes, n);
    if (!validation.is_valid_tree) {
        cerr << "Validation failed for test case " << test_case_number << ": " << validation.validation_message << endl;
        return;
    }

    int p_node_count = 0;
    vector<bool> p_node_status(n + 1, false);
    vector<int> degree_comparison_results(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        bool is_p_node = true;
        int current_degree = nodes[i].degree;
        int parent_degree = (nodes[i].parent_id != -1) ? nodes[nodes[i].parent_id].degree : numeric_limits<int>::min();

        if (parent_degree >= current_degree && nodes[i].parent_id != -1) {
            is_p_node = false;
            degree_comparison_results[i] = -1;
        }

        for (int child : nodes[i].children) {
            if (nodes[child].degree >= current_degree) {
                is_p_node = false;
                degree_comparison_results[i] = -1;
                break;
            }
        }

