int safe_abs(int x) {
    if (x == numeric_limits<int>::min()) {
        throw overflow_error("Absolute value overflow");
    }
    return abs(x);
}

bool validate_input(istream& is) {
    if (is.fail()) {
        is.clear();
        is.ignore(numeric_limits<streamsize>::max(), '\n');
        throw runtime_error("Invalid input format");
    }
    return true;
}

void sort_by_absolute_value(int& a, int& b) {
    int abs_a, abs_b;
    try {
        abs_a = safe_abs(a);
        abs_b = safe_abs(b);
    } catch (const overflow_error& e) {
        cerr << "Warning: " << e.what() << endl;
        abs_a = a >= 0 ? a : (a == numeric_limits<int>::min() ? numeric_limits<int>::max() : -a);
        abs_b = b >= 0 ? b : (b == numeric_limits<int>::min() ? numeric_limits<int>::max() : -b);
    }

    if (abs_a < abs_b) {
        return;
    } else if (abs_a > abs_b) {
        swap(a, b);
    } else {
        if (a > b) {
            swap(a, b);
        }
    }
}

int main() {
    int a, b;
    cin >> a >> b;
    try {
        validate_input(cin);
    } catch (const runtime_error& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    int original_a = a;
    int original_b = b;
    bool a_negative = a < 0;
    bool b_negative = b < 0;
    int temp_a = a_negative ? -a : a;
    int temp_b = b_negative ? -b : b;

