class WordProcessor {
private:
    vector<string> words;
    string currentWord;
    bool processingWord;

    void finalizeCurrentWord() {
        if (!currentWord.empty()) {
            words.push_back(currentWord);
            currentWord.clear();
        }
        processingWord = false;
    }

public:
    WordProcessor() : processingWord(false) {}

    void processCharacter(char c) {
        if (isalpha(c)) {
            currentWord += c;
            processingWord = true;
        } else if (isspace(c)) {
            if (processingWord) {
                finalizeCurrentWord();
            }
        } else {
            throw invalid_argument("Invalid character detected");
        }
    }

    void processEndOfString() {
        if (processingWord) {
            finalizeCurrentWord();
        }
    }

    vector<string> getWords() const {
