struct WordMetadata {
    string content;
    size_t length;
    size_t position;
};

bool compareWordMetadata(const WordMetadata& a, const WordMetadata& b) {
    if (a.length != b.length) {
        return a.length > b.length;
    }
    return a.position < b.position;
}

string sanitizeInput(const string& input) {
    string sanitized;
    for (char c : input) {
        if (isalpha(c) || c == ' ') {
            sanitized += c;
        }
    }
    return sanitized;
}

vector<string> tokenizeSentence(const string& sentence) {
    vector<string> tokens;
    istringstream iss(sentence);
    string token;
    while (iss >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

vector<WordMetadata> processTokens(const vector<string>& tokens) {
    vector<WordMetadata> wordData;
    for (size_t i = 0; i < tokens.size(); ++i) {
        WordMetadata metadata;
        metadata.content = tokens[i];
        metadata.length = tokens[i].length();
        metadata.position = i;
        wordData.push_back(metadata);
    }
    return wordData;
}

string determineLongestWord(const vector<WordMetadata>& wordData) {
    if (wordData.empty()) {
        return "";
    }
    vector<WordMetadata> sortedData = wordData;
    sort(sortedData.begin(), sortedData.end(), compareWordMetadata);
    return sortedData[0].content;
}

