    vector<string> tokens = tokenizeSentence(sanitizedSentence);

    if (tokens.empty()) {
        cout << "" << endl;
        return 0;
    }

    vector<WordMetadata> wordMetadata = processTokens(tokens);
    string longestWord = determineLongestWord(wordMetadata);

    if (!longestWord.empty()) {
