#include <string>
#include <iostream>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cctype>
#include <stdexcept>
using namespace std;

bool validateString(const string& str) {
    for (char c : str) {
        if (!isalpha(c) && c != ' ') {
            return false;
        }
    }
    return true;
}

vector<string> tokenizeSentence(const string& input) {
    vector<string> tokens;
    stringstream ss(input);
    string token;
    while (ss >> token) {
        bool valid = true;
        for (char c : token) {
            if (!isalpha(c)) {
                valid = false;
                break;
            }
        }
        if (valid) {
            tokens.push_back(token);
        } else {
            throw runtime_error("Invalid word detected");
        }
    }
    return tokens;
}

string findLongestWordWithValidation(const vector<string>& words) {
    if (words.empty()) {
        throw runtime_error("No valid words found");
    }

    string longest = words[0];
    for (size_t i = 1; i < words.size(); ++i) {
        if (words[i].length() > longest.length()) {
            bool isEnglish = true;
            for (char c : words[i]) {
                if (!isalpha(c)) {
                    isEnglish = false;
                    break;
                }
            }
            if (isEnglish) {
                longest = words[i];
            }
        } else if (words[i].length() == longest.length()) {
            bool bothValid = true;
            for (char c : words[i]) {
                if (!isalpha(c)) {
                    bothValid = false;
                    break;
                }
            }
            for (char c : longest) {
                if (!isalpha(c)) {
                    bothValid = false;
                    break;
                }
            }
            if (bothValid && i < find(words.begin(), words.end(), longest) - words.begin()) {
                longest = words[i];
            }
        }
    }
    return longest;
}

int main() {
    try {
        string input;
        getline(cin, input);

        if (input.empty()) {
            throw runtime_error("Empty input detected");
        }

        if (!validateString(input)) {
            throw runtime_error("Invalid characters in input");
        }

        vector<string> words = tokenizeSentence(input);

        if (words.empty()) {
            throw runtime_error("No valid words found after tokenization");
        }

        string longest = findLongestWordWithValidation(words);

        if (longest.empty()) {
            throw runtime_error("Longest word is empty");
        }

        cout << longest << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
