const int MAX_STONES = 15;
const int MAX_ATTRIBUTE = 1000000;
const int MIN_ATTRIBUTE = -1000000;
const int MAX_DIFF = INT_MAX;
const int MIN_DIFF = INT_MIN;
const int MAX_ITERATIONS = 1000000;

struct StoneValidator {
    static bool validateAnger(int anger) {
        return anger >= MIN_ATTRIBUTE && anger <= MAX_ATTRIBUTE;
    }
    static bool validateIrritability(int irritability) {
        return irritability >= MIN_ATTRIBUTE && irritability <= MAX_ATTRIBUTE;
    }
};

class StoneConfigurationManager {
private:
    int anger[MAX_STONES];
    int irritability[MAX_STONES];
    bool selected[MAX_STONES];
    int n;
    int currentMinDiff;

    void initialize() {
        fill_n(selected, MAX_STONES, false);
        currentMinDiff = MAX_DIFF;
    }

    void validateInput() {
        if (n < 1 || n > 10) {
            throw invalid_argument("Invalid number of stones");
        }
        for (int i = 0; i < n; i++) {
            if (!StoneValidator::validateAnger(anger[i]) || 
                !StoneValidator::validateIrritability(irritability[i])) {
                throw invalid_argument("Invalid stone attributes");
            }
        }
    }

    void calculateDifference() {
        int product = 1;
        int sum = 0;
        bool atLeastOneSelected = false;
        for (int i = 0; i < n; i++) {
            if (selected[i]) {
                product *= anger[i];
                sum += irritability[i];
                atLeastOneSelected = true;
            }
        }
        if (!atLeastOneSelected) return;
        int diff = abs(product - sum);
        if (diff < currentMinDiff) {
            currentMinDiff = diff;
        }
    }

    void exploreCombinations(int index, bool forceSelection) {
        if (index == n) {
            calculateDifference();
            return;
        }
        if (forceSelection) {
            selected[index] = true;
            exploreCombinations(index + 1, false);
            selected[index] = false;
        } else {
            selected[index] = true;
            exploreCombinations(index + 1, false);
            selected[index] = false;
            exploreCombinations(index + 1, false);
        }
    }

public:
    void loadStones() {
        ifstream inputFile("stone.in");
        if (!inputFile.is_open()) {
            throw runtime_error("Failed to open input file");
        }
        inputFile >> n;
        for (int i = 0; i < n; i++) {
            inputFile >> anger[i] >> irritability[i];
        }
        inputFile.close();
    }

    void findMinimumDifference() {
        initialize();
        validateInput();
        mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
        uniform_int_distribution<int> dist(0, 1);
        for (int i = 0; i < MAX_ITERATIONS; i++) {
            for (int j = 0; j < n; j++) {
                selected[j] = dist(rng) == 1;
            }
            calculateDifference();
        }
        exploreCombinations(0, true);
        exploreCombinations(0, false);
    }

    int getMinimumDifference() const {
        return currentMinDiff;
    }
};

int main() {
    try {
        StoneConfigurationManager manager;
        manager.loadStones();
        manager.findMinimumDifference();
        ofstream outputFile("stone.out");
        if (!outputFile.is_open()) {
            throw runtime_error("Failed to open output file");
        }
        outputFile << manager.getMinimumDifference() << endl;
        outputFile.close();
