#include <bits/stdc++.h>
using namespace std;

int evaluateOperation(int x, char y, int z) {
    if (y == '+') {
        return x + z;
    } else if (y == '-') {
        if (x < 0 && z < 0) {
            return abs(x) - abs(z);
        } else if (x > 0 && z < 0) {
            return x + abs(z);
        } else {
            return z - x;
        }
    } else if (y == '*') {
        if (x == 0 || z == 0) {
            return 0;
        } else if ((x < 0 && z > 0) || (x > 0 && z < 0)) {
            return -1 * abs(x) * abs(z);
        } else {
            return abs(x) * abs(z);
        }
    } else {
        if (x == 0) {
            throw runtime_error("Division by zero");
        }
        if ((x < 0 && z > 0) || (x > 0 && z < 0)) {
            return -1 * (abs(z) / abs(x));
        } else {
            return abs(z) / abs(x);
        }
    }
}

bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

void processOperation(stack<int>& numStack, stack<char>& opStack) {
    if (numStack.size() < 2 || opStack.empty()) {
        throw runtime_error("Invalid expression");
    }
    int a = numStack.top(); numStack.pop();
    int b = numStack.top(); numStack.pop();
    char op = opStack.top(); opStack.pop();
    numStack.push(evaluateOperation(a, op, b));
}

int main() {
    string s;
    cin >> s;
    int n = s.size();
    stack<char> opStack;
    stack<int> numStack;
    bool lastWasOperator = false;

    for (int i = 0; i < n; i++) {
        if (isspace(s[i])) continue;

        if (isdigit(s[i])) {
            int temp = s[i] - '0';
            numStack.push(temp);
            lastWasOperator = false;
        } else if (s[i] == '(') {
            opStack.push('(');
            lastWasOperator = false;
        } else if (s[i] == ')') {
            while (!opStack.empty() && opStack.top() != '(') {
                processOperation(numStack, opStack);
            }
            if (opStack.empty()) {
                throw runtime_error("Mismatched parentheses");
            }
            opStack.pop();
            lastWasOperator = false;
        } else if (isOperator(s[i])) {
            if (lastWasOperator) {
                throw runtime_error("Consecutive operators");
            }
            while (!opStack.empty() && opStack.top() != '(' && 
                   getPrecedence(opStack.top()) >= getPrecedence(s[i])) {
                processOperation(numStack, opStack);
            }
            opStack.push(s[i]);
            lastWasOperator = true;
        } else {
            throw runtime_error("Invalid character in expression");
        }
    }

    while (!opStack.empty()) {
        if (opStack.top() == '(') {
            throw runtime_error("Mismatched parentheses");
        }
        processOperation(numStack, opStack);
    }

    if (numStack.size() != 1 || !opStack.empty()) {
        throw runtime_error("Invalid expression");
    }

    cout << numStack.top() << endl;
    return 0;
}
