int performOperation(int operand1, char operation, int operand2) {
    int resultValue = 0;
    bool operationValid = true;
    switch(operation) {
        case '+':
            resultValue = operand1 + operand2;
            break;
        case '-':
            resultValue = operand2 - operand1;
            break;
        case '*':
            resultValue = operand1 * operand2;
            break;
        case '/':
            if (operand1 == 0) {
                operationValid = false;
                cerr << "Division by zero detected" << endl;
                exit(1);
            }
            resultValue = operand2 / operand1;
            break;
        default:
            operationValid = false;
            cerr << "Invalid operation detected" << endl;
            exit(1);
    }
    if (!operationValid) {
        cerr << "Operation validation failed" << endl;
        exit(1);
    }
    return resultValue;
}

void processStackOperations(stack<char>& operationStack, stack<int>& numberStack, bool processUntilParenthesis) {
    while (!operationStack.empty()) {
        char currentOperation = operationStack.top();
        if (processUntilParenthesis && currentOperation == '(') {
            break;
        }
        if (numberStack.size() < 2) {
            cerr << "Insufficient operands for operation" << endl;
            exit(1);
        }
        int firstOperand = numberStack.top();
        numberStack.pop();
        int secondOperand = numberStack.top();
        numberStack.pop();
        int intermediateResult = performOperation(firstOperand, currentOperation, secondOperand);
        numberStack.push(intermediateResult);
        operationStack.pop();
    }
}

int main() {
