    for (int currentIndex = 0; currentIndex < expressionLength; currentIndex++) {
        char currentCharacter = inputExpression[currentIndex];
        if (isdigit(currentCharacter)) {
            int numericValue = currentCharacter - '0';
            numberStack.push(numericValue);
        } else if (currentCharacter == '(') {
            operationStack.push(currentCharacter);
        } else if (currentCharacter == ')') {
            processStackOperations(operationStack, numberStack, true);
            if (operationStack.empty() || operationStack.top() != '(') {
                cerr << "Mismatched parentheses detected" << endl;
                exit(1);
            }
            operationStack.pop();
        } else if (currentCharacter == '+' || currentCharacter == '-') {
            processStackOperations(operationStack, numberStack, true);
            operationStack.push(currentCharacter);
