#include <bits/stdc++.h>
using namespace std;

struct QueueNode {
    string name;
    QueueNode* next;
    QueueNode* prev;
};

class OverEngineeredQueue {
private:
    QueueNode* head;
    QueueNode* tail;
    int size;
    unordered_map<char, vector<QueueNode*>> friendMap;

    void validateOperation(int k) {
        if (k != 1 && k != 2) {
            throw runtime_error("Invalid operation code");
        }
    }

    void validateName(const string& name) {
        if (name.empty()) {
            throw runtime_error("Name cannot be empty");
        }
        if (!isalpha(name[0])) {
            throw runtime_error("Name must start with a letter");
        }
    }

    void performInsertionChecks() {
        if (size >= 100) {
            throw runtime_error("Queue capacity exceeded");
        }
    }

public:
    OverEngineeredQueue() : head(nullptr), tail(nullptr), size(0) {}

    void enqueue(const string& name) {
        validateName(name);
        performInsertionChecks();

        QueueNode* newNode = new QueueNode{name, nullptr, nullptr};
        char firstChar = tolower(name[0]);
        bool inserted = false;

        if (!friendMap[firstChar].empty()) {
            for (auto node : friendMap[firstChar]) {
                if (node != nullptr) {
                    QueueNode* nextNode = node->next;
                    node->next = newNode;
                    newNode->prev = node;
                    newNode->next = nextNode;
                    if (nextNode != nullptr) {
                        nextNode->prev = newNode;
                    } else {
                        tail = newNode;
                    }
                    inserted = true;
                    break;
                }
            }
        }

        if (!inserted) {
            if (tail == nullptr) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                newNode->prev = tail;
                tail = newNode;
            }
        }

        friendMap[firstChar].push_back(newNode);
        size++;
    }

    string dequeue() {
        if (head == nullptr) {
            return "0";
        }

        QueueNode* temp = head;
        string name = temp->name;
        char firstChar = tolower(name[0]);

        auto& friends = friendMap[firstChar];
        friends.erase(remove(friends.begin(), friends.end(), temp), friends.end());

        head = head->next;
        if (head != nullptr) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
        }

        delete temp;
        size--;
        return name;
    }

    void processOperation(int k, const string& name = "") {
        try {
            validateOperation(k);
            if (k == 1) {
                enqueue(name);
            } else if (k == 2) {
                string result = dequeue();
                cout << result << endl;
            }
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
        }
    }
};

int main() {
    OverEngineeredQueue queue;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    while (n--) {
        int k;
        cin >> k;
        if (k == 1) {
            string name;
            cin >> name;
            queue.processOperation(k, name);
        } else if (k == 2) {
            queue.processOperation(k);
        } else {
            cerr << "Invalid operation code" << endl;
        }
    }

    return 0;
}
