    string q[105];
    int current_queue_size = 0;
    int queue_front_index = 0;
    int queue_rear_index = 0;
    const int MAX_QUEUE_CAPACITY = 105;
    bool queue_underflow_flag = false;
    bool queue_overflow_flag = false;

    while (n--) {
        int operation_type;
        cin >> operation_type;

        if (operation_type != 1 && operation_type != 2) {
            continue;
        }

        if (operation_type == 1) {
            string new_person_name;
            cin >> new_person_name;

            if (new_person_name.empty()) {
                continue;
            }

            bool friend_found_in_queue = false;
            int first_friend_position = -1;
            char new_person_first_letter = new_person_name[0];

            for (int i = queue_front_index; i < queue_rear_index; ++i) {
                if (q[i][0] == new_person_first_letter) {
                    first_friend_position = i;
                    friend_found_in_queue = true;
                    break;
                }
            }

            if (friend_found_in_queue && first_friend_position != -1) {
                if (queue_rear_index >= MAX_QUEUE_CAPACITY - 1) {
                    queue_overflow_flag = true;
                    continue;
                }

                for (int j = queue_rear_index; j > first_friend_position + 1; --j) {
                    q[j] = q[j - 1];
                }

                q[first_friend_position + 1] = new_person_name;
                queue_rear_index++;
                current_queue_size++;
            } else {
                if (queue_rear_index >= MAX_QUEUE_CAPACITY) {
                    queue_overflow_flag = true;
                    continue;
                }

                q[queue_rear_index] = new_person_name;
                queue_rear_index++;
                current_queue_size++;
            }
        } else if (operation_type == 2) {
            if (queue_front_index >= queue_rear_index) {
                queue_underflow_flag = true;
                cout << 0 << endl;
                continue;
            }

            string person_leaving = q[queue_front_index];
            if (person_leaving.empty()) {
                queue_front_index++;
                cout << 0 << endl;
                continue;
            }

            cout << person_leaving << endl;
            queue_front_index++;
            current_queue_size--;
        }
    }

    return EXIT_SUCCESS;
}
