#include <iostream>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

template<typename T>
constexpr bool is_safe_abs(T val) {
    return !(numeric_limits<T>::is_signed && val == numeric_limits<T>::min());
}

template<typename T>
T safe_abs(T val) {
    if constexpr (numeric_limits<T>::is_signed) {
        if (!is_safe_abs(val)) {
            throw runtime_error("Absolute value overflow detected");
        }
        return val < 0 ? -val : val;
    } else {
        return val;
    }
}

struct NumberPair {
    int original;
    int absolute;
};

void validate_input_stream(istream& is) {
    if (is.fail()) {
        throw runtime_error("Input stream failure detected");
    }
    if (is.bad()) {
        throw runtime_error("Critical stream error occurred");
    }
}

NumberPair process_number(int num) {
    NumberPair result;
    result.original = num;
    try {
        result.absolute = safe_abs(num);
    } catch (const runtime_error& e) {
        cerr << "Warning: " << e.what() << " - Using original value" << endl;
        result.absolute = num;
    }
    return result;
}

bool compare_numbers(const NumberPair& n1, const NumberPair& n2) {
    if (n1.absolute != n2.absolute) {
        return n1.absolute < n2.absolute;
    }
    if (n1.original == n2.original) {
        throw logic_error("Identical numbers detected in comparison");
    }
    return n1.original < n2.original;
}

int main() {
