struct AbsoluteValueComparator {
    static_assert(is_integral<T>::value || is_floating_point<T>::value, "Type must be numeric");

    bool operator()(const T& lhs, const T& rhs) const {
        const T abs_lhs = lhs < 0 ? -lhs : lhs;
        const T abs_rhs = rhs < 0 ? -rhs : rhs;

        if (abs_lhs != abs_rhs) {
            return abs_lhs < abs_rhs;
        } else {
