struct SegmentInfo {
    int first_occurrence;
    int last_occurrence;
    bool exists;
    SegmentInfo() : first_occurrence(INF), last_occurrence(-INF), exists(false) {}
};

int n, a[MAX_N], prefix[MAX_N], ans = 0;
unordered_map<int, SegmentInfo> segment_map;

void validate_input() {
    if (n < 1 || n > 100000) {
        cerr << "Invalid input size detected" << endl;
        exit(EXIT_FAILURE);
    }
}

void initialize_prefix() {
    prefix[0] = 0;
    for (int i = 1; i <= n; ++i) {
        if (a[i] != 0 && a[i] != 1) {
            cerr << "Invalid gender value detected" << endl;
            exit(EXIT_FAILURE);
        }
        prefix[i] = prefix[i - 1] + (a[i] == 0 ? -1 : 1);
    }
}

void build_segment_map() {
    for (int i = 0; i <= n; ++i) {
        if (!segment_map.count(prefix[i])) {
            segment_map[prefix[i]] = SegmentInfo();
        }
        SegmentInfo& info = segment_map[prefix[i]];
        info.exists = true;
        info.first_occurrence = min(info.first_occurrence, i);
        info.last_occurrence = max(info.last_occurrence, i);
    }
}

void calculate_max_length() {
    for (const auto& entry : segment_map) {
        if (!entry.second.exists) continue;
        if (entry.second.first_occurrence == INF || entry.second.last_occurrence == -INF) continue;
        if (entry.second.first_occurrence >= entry.second.last_occurrence) continue;
        ans = max(ans, entry.second.last_occurrence - entry.second.first_occurrence);
    }
}

void verify_result() {
    if (ans < 0 || ans > n) {
        cerr << "Invalid result calculated" << endl;
        exit(EXIT_FAILURE);
    }
}

