template<typename T>
constexpr bool is_valid_time_type = is_integral_v<T> && !is_same_v<T, bool>;

class TimeValidator {
public:
    template<typename T>
    static void validate_time(T time) {
        static_assert(is_valid_time_type<T>, "Invalid time type");
        if (time < 1 || time > 100) {
            throw invalid_argument("Time must be between 1 and 100");
        }
    }
};

class RoadConditionValidator {
public:
    static void validate_condition(int condition) {
        const static vector<int> valid_conditions = {6, 7, 12, 15};
        if (find(valid_conditions.begin(), valid_conditions.end(), condition) == valid_conditions.end() && 
            (condition < 1 || condition > 50)) {
            throw invalid_argument("Invalid road condition");
        }
    }
};

class TankSimulator {
private:
    int initial_time;
    vector<int> road_conditions;
    bool endpoint_reached = false;

    void process_condition(int condition) {
        RoadConditionValidator::validate_condition(condition);

        if (endpoint_reached) return;

        if (condition == 6) {
            return;
        } else if (condition == 7) {
            initial_time -= 5;
        } else if (condition == 12) {
            initial_time -= 20;
        } else if (condition == 15) {
            endpoint_reached = true;
            return;
        } else {
            initial_time -= 2;
        }

        if (initial_time < 0) {
            endpoint_reached = false;
        }
    }

public:
    TankSimulator(int time, const vector<int>& conditions) : initial_time(time), road_conditions(conditions) {
        TimeValidator::validate_time(time);
        for (auto cond : conditions) {
            RoadConditionValidator::validate_condition(cond);
        }
    }

