                if (endpoint_reached) break;
                if (initial_time <= 0 && i != road_conditions.size() - 1) break;
            }
            return endpoint_reached || initial_time >= 0;
        } catch (const exception& e) {
            cerr << "Simulation error: " << e.what() << endl;
            return false;
        }
    }
};

