        if (!RoadConditionValidator::validate(m)) {
            throw invalid_argument("Invalid road condition detected");
        }

        if (m == 6) {
            minutes_left += 1;
        } else if (m == 7) {
            remaining_time -= 5;
            if (remaining_time < 0) remaining_time = 0;
        } else if (m == 12) {
