#include<atomic>
#include<condition_variable>
#define MAX 1000000000000LL
using namespace std;

namespace ElevatorTimeCalculator {
    class TimeValidator {
    public:
        static bool validateFloor(long long floor) {
            return floor >= 1 && floor <= MAX;
        }
        static bool validatePeopleCount(long long n) {
            return n >= 1 && n <= 100000;
        }
    };

    class ElevatorSimulator {
    private:
        vector<long long> floors;
        long long n;
        mutex mtx;
        atomic<long long> totalTime;

        void calculateAscendingTime() {
            lock_guard<mutex> lock(mtx);
            if (!floors.empty()) {
                totalTime += 5 * floors.back();
            }
        }

        void calculateDescendingTime() {
            lock_guard<mutex> lock(mtx);
            if (!floors.empty()) {
                totalTime += 4 * floors.back();
            }
        }

        void calculateDoorOperations() {
            lock_guard<mutex> lock(mtx);
            totalTime += 3;
            totalTime += 2 * n;
        }

        void processFloors() {
            vector<thread> threads;
            threads.emplace_back([this]() { calculateAscendingTime(); });
            threads.emplace_back([this]() { calculateDescendingTime(); });
            threads.emplace_back([this]() { calculateDoorOperations(); });

            for (auto& t : threads) {
                if (t.joinable()) {
                    t.join();
                }
            }
        }

    public:
        ElevatorSimulator(long long numPeople, const vector<long long>& targetFloors) 
            : n(numPeople), floors(targetFloors), totalTime(0) {
            sort(floors.begin(), floors.end(), greater<long long>());
        }

        long long calculateTotalTime() {
            if (n == 0 || floors.empty()) {
                return 0;
            }

            for (const auto& floor : floors) {
                if (!TimeValidator::validateFloor(floor)) {
                    throw runtime_error("Invalid floor number detected");
                }
            }

            if (!TimeValidator::validatePeopleCount(n)) {
                throw runtime_error("Invalid number of people");
            }

            processFloors();
            return totalTime;
        }
    };
}

int main() {
    ifstream infile("elevator.in");
    ofstream outfile("elevator.out");

    if (!infile.is_open() || !outfile.is_open()) {
        cerr << "Error opening files" << endl;
        return EXIT_FAILURE;
    }

    try {
        long long n;
        infile >> n;
        if (infile.fail()) {
            throw runtime_error("Failed to read number of people");
