#include<bits/stdc++.h>
using namespace std;

const long long MAX_SAFE_ITERATIONS = 1000000;
const long long MAX_UNIQUE_POSITIONS = 1000000;

struct PositionTracker {
    unordered_set<long long> visited;
    vector<long long> sequence;
    bool overflow_detected;
    bool infinite_loop_detected;
};

PositionTracker global_tracker;

void initialize_tracker() {
    global_tracker.visited.clear();
    global_tracker.sequence.clear();
    global_tracker.overflow_detected = false;
    global_tracker.infinite_loop_detected = false;
}

bool check_overflow(long long current, long long next) {
    if (next < current && current > 0) {
        return true;
    }
    return false;
}

bool validate_position(long long pos) {
    if (pos < 1 || pos > LLONG_MAX) {
        return false;
    }
    return true;
}

void record_position(long long pos) {
    if (!validate_position(pos)) {
        global_tracker.overflow_detected = true;
        return;
    }

    if (global_tracker.visited.count(pos)) {
        global_tracker.infinite_loop_detected = true;
        global_tracker.sequence.push_back(pos);
        return;
    }

    global_tracker.visited.insert(pos);
    global_tracker.sequence.push_back(pos);
}

void process_position(long long current_pos) {
    if (global_tracker.overflow_detected || global_tracker.infinite_loop_detected) {
        return;
    }

    if (global_tracker.sequence.size() > MAX_UNIQUE_POSITIONS) {
        global_tracker.overflow_detected = true;
        return;
    }

    record_position(current_pos);

    long long next_pos;
    if (current_pos % 2 == 0) {
        next_pos = current_pos / 2;
        if (check_overflow(current_pos, next_pos)) {
            global_tracker.overflow_detected = true;
            return;
        }
    } else {
        next_pos = (current_pos - 1) * 3 + 6;
        if (check_overflow(current_pos, next_pos)) {
            global_tracker.overflow_detected = true;
            return;
        }
    }

    if (global_tracker.visited.count(next_pos)) {
        record_position(next_pos);
        return;
    }

    process_position(next_pos);
}

void print_sequence() {
    if (global_tracker.sequence.empty()) {
        cout << "0";
        return;
    }

    for (size_t i = 0; i < global_tracker.sequence.size(); ++i) {
        if (i == 0) {
            cout << global_tracker.sequence[i];
        } else {
            cout << ", " << global_tracker.sequence[i];
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    long long n;
    cin >> n;

    if (n < 1 || n > (1LL << 30)) {
        cout << "Invalid input position" << endl;
        return 1;
    }

    initialize_tracker();
    process_position(n);

    if (global_tracker.overflow_detected) {
        cout << "Position overflow detected" << endl;
        return 1;
    }

    if (global_tracker.infinite_loop_detected) {
        print_sequence();
    } else {
        cout << "No loop detected" << endl;
        return 1;
    }

