#include <cstdio>
#include <cstring>
#include <vector>
#include <stdexcept>
#include <algorithm>
#include <climits>

const int MAXN = 1e5 + 5;
const int MAX_DIMENSION = 205;
const int MIN_DIMENSION = 3;

struct CompressionState {
    int current_value;
    int consecutive_count;
    bool initialized;
};

class MatrixValidator {
public:
    static void validateDimension(int dimension) {
        if (dimension < MIN_DIMENSION || dimension > MAX_DIMENSION) {
            throw std::runtime_error("Invalid matrix dimension");
        }
    }

    static void validateCharacter(char c) {
        if (c != '0' && c != '1') {
            throw std::runtime_error("Invalid matrix character");
        }
    }
};

void initializeCompressionState(CompressionState& state) {
    state.current_value = -1;
    state.consecutive_count = 0;
    state.initialized = false;
}

void processMatrixCharacter(CompressionState& state, int value, std::vector<int>& result) {
    if (!state.initialized) {
        state.current_value = value;
        state.consecutive_count = 1;
        state.initialized = true;
    } else {
        if (value == state.current_value) {
            state.consecutive_count++;
        } else {
            result.push_back(state.consecutive_count);
            state.current_value = value;
            state.consecutive_count = 1;
        }
    }
}

void finalizeCompression(CompressionState& state, std::vector<int>& result) {
    if (state.initialized) {
        result.push_back(state.consecutive_count);
    }
}

void validateResultSize(int n, const std::vector<int>& result) {
    int sum = 0;
    for (int count : result) {
        sum += count;
    }
    if (sum != n * n) {
        throw std::runtime_error("Compression result size mismatch");
    }
}

int main() {
    FILE* input_file = nullptr;
    FILE* output_file = nullptr;
    char buffer[MAX_DIMENSION + 2];
    std::vector<std::vector<char>> matrix;
    std::vector<int> compression_result;
    CompressionState compression_state;

    try {
        input_file = fopen("zip.in", "r");
        if (!input_file) {
            throw std::runtime_error("Failed to open input file");
        }

        if (!fgets(buffer, sizeof(buffer), input_file)) {
            throw std::runtime_error("Failed to read matrix dimension");
        }

        int n = strlen(buffer);
        while (n > 0 && (buffer[n-1] == '\n' || buffer[n-1] == '\r')) {
            buffer[--n] = '\0';
        }

        MatrixValidator::validateDimension(n);

        matrix.resize(n + 1);
        for (int i = 0; i <= n; ++i) {
            matrix[i].resize(n + 2);
        }

        for (int j = 1; j <= n; ++j) {
            MatrixValidator::validateCharacter(buffer[j-1]);
            matrix[1][j] = buffer[j-1];
        }

        for (int i = 2; i <= n; ++i) {
            if (!fgets(buffer, sizeof(buffer), input_file)) {
                throw std::runtime_error("Incomplete matrix data");
            }
            int len = strlen(buffer);
            while (len > 0 && (buffer[len-1] == '\n' || buffer[len-1] == '\r')) {
                buffer[--len] = '\0';
            }
            for (int j = 1; j <= n; ++j) {
                MatrixValidator::validateCharacter(buffer[j-1]);
                matrix[i][j] = buffer[j-1];
            }
        }

        initializeCompressionState(compression_state);

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                int current_value = matrix[i][j] - '0';
                processMatrixCharacter(compression_state, current_value, compression_result);
            }
        }

        finalizeCompression(compression_state, compression_result);
        validateResultSize(n, compression_result);

        output_file = fopen("zip.out", "w");
        if (!output_file) {
            throw std::runtime_error("Failed to open output file");
        }

        fprintf(output_file, "%d ", n);
        for (size_t i = 0; i < compression_result.size(); ++i) {
            if (i > 0) {
                fprintf(output_file, " ");
            }
            fprintf(output_file, "%d", compression_result[i]);
