        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (map[i][j] != '0' && map[i][j] != '1') {
                    map[i][j] = '0';
                }
            }
        }
    }
};

class CompressionEngine {
private:
    int n;
    char map[MAX_DIM][MAX_DIM];
    std::vector<int> compressedData;

    void validateInput() {
        if (!CompressionValidator::validateDimensions(n)) {
            throw std::runtime_error("Invalid matrix dimensions");
        }
        MatrixSanitizer::sanitizeInput(map, n);
    }

    void processMatrix() {
        int currentState = 0;
        int currentCount = 0;
        bool firstIteration = true;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int currentValue = map[i][j] - '0';
                if (firstIteration) {
                    currentState = currentValue;
                    currentCount = 1;
                    firstIteration = false;
                } else {
                    if (currentValue == currentState) {
                        currentCount++;
                    } else {
                        compressedData.push_back(currentCount);
                        currentState = currentValue;
                        currentCount = 1;
                    }
                }
            }
        }
        if (currentCount > 0) {
            compressedData.push_back(currentCount);
        }
    }

    void verifyCompression() {
        int sum = 0;
        for (int count : compressedData) {
            sum += count;
        }
        if (sum != n * n) {
            throw std::runtime_error("Compression verification failed");
        }
    }

public:
