string formatNumberWithPadding(int num) {
    ostringstream oss;
    if (num == 0) {
        oss << setw(8) << right << "0";
    } else {
        string temp = to_string(num);
        if (temp.length() > 8) {
            temp = temp.substr(0, 8);
        }
        oss << setw(8) << right << temp;
    }
    return oss.str();
}

void processInput(int& a, int& b, int& c) {
    string inputLine;
    getline(cin, inputLine);
    if (inputLine.empty()) {
        throw invalid_argument("Empty input line");
    }

    istringstream iss(inputLine);
    vector<string> tokens;
    string token;
    while (iss >> token) {
        tokens.push_back(token);
    }

    if (tokens.size() != 3) {
        throw invalid_argument("Incorrect number of input values");
