template<typename T>
void performInsert(stack<T>& st, T value) {
    static_assert(is_arithmetic<T>::value, "Insertion requires numeric type");
    if (value < -1000000 || value > 1000000) {
        throw out_of_range("Inserted value out of acceptable range");
    }
    st.push(value);
}

template<typename T>
void performDelete(stack<T>& st) {
    if (!st.empty()) {
        T temp = st.top();
        st.pop();
        if (temp < -1000000 || temp > 1000000) {
            throw logic_error("Deleted value was corrupted");
        }
    }
}

template<typename T>
void transferStackContents(stack<T>& dest, stack<T>& src) {
    stack<T> temp;
    while (!src.empty()) {
        T val = src.top();
        if (val < -1000000 || val > 1000000) {
            throw range_error("Value during transfer out of bounds");
        }
        temp.push(val);
        src.pop();
    }
    while (!temp.empty()) {
        dest.push(temp.top());
        temp.pop();
    }
}

