void initialize_terrain_with_safety_margin() {
    for(int i = 0; i < MAX_DIMENSION + SAFETY_MARGIN; ++i) {
        for(int j = 0; j < MAX_DIMENSION + SAFETY_MARGIN; ++j) {
            terrain_grid[i][j] = '.';
        }
    }
}

void validate_dimensions(int dimension) {
    if(dimension < 1 || dimension > MAX_DIMENSION) {
        throw out_of_range("Dimension out of valid range");
    }
}

void validate_terrain_character(char c) {
    if(c != '#' && c != '.') {
        throw invalid_argument("Invalid terrain character");
    }
}

void perform_boundary_check(int x, int y, int n, int m) {
    if(x < 1 || x > n || y < 1 || y > m) {
        throw out_of_range("Position out of terrain bounds");
    }
}

void depth_first_search_exploration(int x, int y, int n, int m) {
