#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>
#include <algorithm>
using namespace std;

const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const int ALPHABET_SIZE = 26;
const int DIGIT_COUNT = 10;

struct CharCategory {
    bool isLowercase;
    bool isDigit;
    bool isSpecial;
    bool isPotentialReplacement;
};

CharCategory analyzeCharacter(char c, const string& s, size_t pos) {
    CharCategory result = {false, false, false, false};
    if (c >= 'a' && c <= 'z') {
        result.isLowercase = true;
    } else if (c >= '0' && c <= '9') {
        result.isDigit = true;
    }

    if (pos + 2 < s.size()) {
        string triplet = s.substr(pos, 3);
        if (triplet == SPACE_REPLACEMENT || triplet == DOT_REPLACEMENT) {
            result.isPotentialReplacement = true;
        }
    }

    return result;
}

char decryptSingleChar(char c) {
    const string lowercaseChars = "abcdefghijklmnopqrstuvwxyz";
    const string digits = "0123456789";
    size_t foundPos;

    if ((foundPos = lowercaseChars.find(c)) != string::npos) {
        int shiftedPos = (foundPos - SHIFT_VALUE + ALPHABET_SIZE) % ALPHABET_SIZE;
        return lowercaseChars[shiftedPos];
    } else if ((foundPos = digits.find(c)) != string::npos) {
        int shiftedPos = (foundPos - SHIFT_VALUE + DIGIT_COUNT) % DIGIT_COUNT;
        return digits[shiftedPos];
    }

    throw runtime_error("Invalid character encountered during decryption");
}

string processTripletReplacement(const string& s, size_t& i) {
    if (i + 2 >= s.size()) {
        throw runtime_error("Incomplete triplet at end of string");
    }

    string triplet = s.substr(i, 3);
    if (triplet == SPACE_REPLACEMENT) {
        i += 2;
        return " ";
    } else if (triplet == DOT_REPLACEMENT) {
        i += 2;
        return ".";
    }

    throw runtime_error("Unknown triplet pattern encountered");
}

string decryptMessage(const string& encrypted) {
    string decrypted;
    vector<char> buffer;
    size_t i = 0;

    while (i < encrypted.size()) {
        CharCategory analysis = analyzeCharacter(encrypted[i], encrypted, i);

        if (analysis.isPotentialReplacement) {
            try {
                decrypted += processTripletReplacement(encrypted, i);
            } catch (const runtime_error& e) {
                decrypted += encrypted[i];
