            factorialCache[n].digits[factorialCache[n].length] %= 10;
        }
        factorialCache[n].length++;
    }
}

void updateSum(int n) {
    sumLength = max(sumLength, factorialCache[n].length);

    for (int i = 0; i < factorialCache[n].length; ++i) {
        sumCache[i] += factorialCache[n].digits[i];
    }

