        if (terrain[x][y] != '#') return;

        visited[x][y] = true;
        for (int i = 0; i < MAX_DIRECTIONS; i++) {
            int newX = x + dir[i][0];
            int newY = y + dir[i][1];
            if (CoordinateValidator::validate(newX, newY, rows, cols)) {
                if (!visited[newX][newY] && terrain[newX][newY] == '#') {
                    performDFS(newX, newY);
                }
            }
        }
    }

public:
    GrasslandAnalyzer(int n, int m) : rows(n), cols(m) {
        initializeVisited();
    }

    void setTerrain(int i, int j, char val) {
        if (i >= 0 && i < rows && j >= 0 && j < cols) {
            terrain[i][j] = val;
        }
    }

    int countGrasslands() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j] && terrain[i][j] == '#') {
                    performDFS(i, j);
                    count++;
                }
            }
        }
        return count;
    }
};

