#include <bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 1005;
const int MAX_DIRECTIONS = 4;

struct CoordinateValidator {
    int lower_x;
    int upper_x;
    int lower_y;
    int upper_y;

    CoordinateValidator(int n, int m) {
        lower_x = 0;
        upper_x = n - 1;
        lower_y = 0;
        upper_y = m - 1;
    }

    bool is_valid(int x, int y) const {
        bool x_valid = (x >= lower_x) && (x <= upper_x);
        bool y_valid = (y >= lower_y) && (y <= upper_y);
        return x_valid && y_valid;
    }
};

class GrasslandExplorer {
private:
    int direction_offsets[MAX_DIRECTIONS][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    char terrain_grid[MAX_DIMENSION][MAX_DIMENSION];
    bool visited[MAX_DIMENSION][MAX_DIMENSION];
    int row_count;
    int col_count;
    CoordinateValidator validator;

    void initialize_visited() {
        for (int i = 0; i < MAX_DIMENSION; ++i) {
            for (int j = 0; j < MAX_DIMENSION; ++j) {
                visited[i][j] = false;
            }
        }
    }

    void explore_grassland(int x, int y) {
        visited[x][y] = true;
        for (int dir_idx = 0; dir_idx < MAX_DIRECTIONS; ++dir_idx) {
            int new_x = x + direction_offsets[dir_idx][0];
            int new_y = y + direction_offsets[dir_idx][1];
            if (validator.is_valid(new_x, new_y) && !visited[new_x][new_y] && terrain_grid[new_x][new_y] == '#') {
                explore_grassland(new_x, new_y);
            }
        }
    }

public:
    GrasslandExplorer(int n, int m) : validator(n, m) {
        row_count = n;
        col_count = m;
        initialize_visited();
    }

    void load_terrain() {
        for (int i = 0; i < row_count; ++i) {
            string row_data;
            cin >> row_data;
            for (int j = 0; j < col_count; ++j) {
                terrain_grid[i][j] = row_data[j];
            }
        }
    }

    int count_grasslands() {
        int grassland_count = 0;
        for (int i = 0; i < row_count; ++i) {
            for (int j = 0; j < col_count; ++j) {
                if (!visited[i][j] && terrain_grid[i][j] == '#') {
                    explore_grassland(i, j);
                    ++grassland_count;
                }
            }
        }
        return grassland_count;
    }
};

int main() {
    ifstream input_file("hiking.in");
    ofstream output_file("hiking.out");

    streambuf* original_cin = cin.rdbuf();
    streambuf* original_cout = cout.rdbuf();

    cin.rdbuf(input_file.rdbuf());
    cout.rdbuf(output_file.rdbuf());

    int n, m;
    cin >> n >> m;

    GrasslandExplorer explorer(n, m);
    explorer.load_terrain();
    int result = explorer.count_grasslands();

    cout << result << endl;

    cin.rdbuf(original_cin);
    cout.rdbuf(original_cout);

    input_file.close();
    output_file.close();

    return 0;
}
