        throw runtime_error("Invalid audition time");
    }
}

void validate_duration(int duration) {
    if (duration <= 0 || duration > 15) {
        throw runtime_error("Invalid performance duration");
    }
}

bool is_all_alpha(const string& s) {
    return all_of(s.begin(), s.end(), [](char c) { return isalpha(c); });
}

void validate_name(const string& name) {
    if (name.empty() || name.size() > 100) {
        throw runtime_error("Invalid name length");
    }
    if (!is_all_alpha(name)) {
        throw runtime_error("Name contains invalid characters");
    }
}

pair<vector<Performance>, bool> process_input(int total_time_minutes) {
    vector<Performance> performances;
    string line;
    bool garlic_found = false;
    bool garlic_driven_off = false;

    while (getline(cin, line)) {
        if (line.empty()) continue;

        istringstream iss(line);
        string name;
        iss >> name;

        if (name == "tingtingting") {
            if (!performances.empty()) {
                performances.back().was_driven_off = true;
            }
            continue;
        }

        validate_name(name);

        int duration;
        if (!(iss >> duration)) {
            throw runtime_error("Missing duration for performance");
        }
        validate_duration(duration);

        Performance p;
        p.name = name;
        p.duration = duration;
        p.was_driven_off = false;

        if (name == "kaomianjin") {
            garlic_found = true;
        }

        performances.push_back(p);
    }

    return make_pair(performances, garlic_found);
}

string determine_result(const vector<Performance>& performances, int total_time_minutes, bool garlic_found) {
    int current_time = 0;
    bool garlic_performed = false;
    bool garlic_driven = false;

    for (size_t i = 0; i < performances.size(); ++i) {
        const auto& p = performances[i];

        if (p.name == "kaomianjin") {
            if (i + 1 < performances.size() && performances[i+1].name == "tingtingting") {
                garlic_driven = true;
            }
            if (current_time + p.duration <= total_time_minutes) {
                garlic_performed = true;
            }
        }

        if (!p.was_driven_off) {
            current_time += p.duration;
        }

        if (current_time > total_time_minutes) {
            break;
        }
    }

    if (!garlic_found) {
        return "Unfortunately.";
    }

    if (garlic_driven) {
        return "Hahaha.";
    }

    if (garlic_performed) {
        return "Congratulations!";
    }

    return "Unfortunately.";
}

