    try {
        int x_hours;
        cin >> x_hours;
        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        validate_input_time(x_hours);
        int total_time_minutes = x_hours * 60;

        auto input_result = process_input(total_time_minutes);
        auto& performances = input_result.first;
        bool garlic_found = input_result.second;

        string result = determine_result(performances, total_time_minutes, garlic_found);
        cout << result << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
