        digits[0] = 1;
    }

    void multiply(int x) {
        if (x < 0) {
            throw invalid_argument("Negative multiplication factor");
        }

        for (int i = 0; i < length; i++) {
            digits[i] *= x;
        }

        for (int i = 0; i < length; i++) {
            if (digits[i] >= 10) {
                digits[i+1] += digits[i] / 10;
                digits[i] %= 10;
            }
        }

        while (digits[length] > 0) {
            if (length >= MAX_DIGITS - 1) {
                throw overflow_error("Exceeded maximum digit capacity");
            }
            digits[length+1] += digits[length] / 10;
            digits[length] %= 10;
            length++;
        }
    }

    void add(const BigNum& other) {
        length = max(length, other.length);
        for (int i = 0; i < length; i++) {
