const int SHIFT_VALUE = 3;
const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int TRIPLE_LENGTH = 3;

string performCircularShift(char inputChar, bool reverseDirection) {
    size_t foundPosition = CIRCULAR_SEQUENCE.find(inputChar);
    if (foundPosition == string::npos) {
        throw invalid_argument("Invalid character detected in input");
    }
    int shiftDirection = reverseDirection ? -SHIFT_VALUE : SHIFT_VALUE;
    int adjustedPosition = (foundPosition + shiftDirection + CIRCULAR_SEQUENCE.length()) % CIRCULAR_SEQUENCE.length();
    return string(1, CIRCULAR_SEQUENCE[adjustedPosition]);
}

bool isTriplePattern(const string& str, size_t pos, const string& pattern) {
    if (pos + TRIPLE_LENGTH > str.length()) return false;
    for (int i = 0; i < TRIPLE_LENGTH; ++i) {
        if (str[pos + i] != pattern[0]) return false;
    }
    return true;
}

string processEncryptedCharacter(char currentChar, const string& inputStr, size_t& currentIndex) {
    if (isTriplePattern(inputStr, currentIndex, SPACE_REPLACEMENT)) {
        currentIndex += TRIPLE_LENGTH - 1;
        return " ";
    } else if (isTriplePattern(inputStr, currentIndex, DOT_REPLACEMENT)) {
        currentIndex += TRIPLE_LENGTH - 1;
        return ".";
    } else if (isalnum(currentChar) || islower(currentChar)) {
        return performCircularShift(currentChar, true);
    } else {
        throw runtime_error("Unexpected character encountered during decryption");
    }
}

string decryptMessage(const string& encryptedMessage) {
