    for (size_t i = 0; i < encryptedMessage.length(); ) {
        char currentCharacter = encryptedMessage[i];
        try {
            string processedCharacter = processEncryptedCharacter(currentCharacter, encryptedMessage, i);
            decryptedResult += processedCharacter;
            ++i;
        } catch (const exception& e) {
