        }
        if (x == 0) {
            digits = {0};
            length = 1;
            return;
        }
        int carry = 0;
        for (int i = 0; i < length; ++i) {
            int product = digits[i] * x + carry;
            digits[i] = product % 10;
            carry = product / 10;
        }
        while (carry > 0) {
            digits.push_back(carry % 10);
            carry /= 10;
            length++;
        }
        normalize();
    }

    void add(const BigNum& other) {
        int max_len = max(length, other.length);
        int carry = 0;
        digits.resize(max_len, 0);
        for (int i = 0; i < max_len; ++i) {
            int sum = digits[i] + (i < other.length ? other.digits[i] : 0) + carry;
            digits[i] = sum % 10;
            carry = sum / 10;
        }
        if (carry > 0) {
            digits.push_back(carry);
        }
        length = digits.size();
