    class TowerOptimizer {
    private:
        vector<int> heights;
        int min_excess = INF;
        int target;

        void backtrack(int idx, int current_sum) {
            if (current_sum >= target) {
                if (current_sum - target < min_excess) {
                    min_excess = current_sum - target;
                }
                return;
            }
            if (idx >= heights.size()) {
                return;
            }
            for (int i = 0; i < 2; ++i) {
                if (i == 0) {
                    backtrack(idx + 1, current_sum);
                } else {
                    if (current_sum + heights[idx] <= target + min_excess) {
                        backtrack(idx + 1, current_sum + heights[idx]);
                    }
                }
            }
        }

    public:
        TowerOptimizer(const vector<int>& h, int b) : heights(h), target(b) {
            sort(heights.rbegin(), heights.rend());
        }

        int findMinExcess() {
            if (heights.empty()) {
                return -1;
            }
            for (int mask = 0; mask < (1 << heights.size()); ++mask) {
                int sum = 0;
                for (int i = 0; i < heights.size(); ++i) {
                    if (mask & (1 << i)) {
                        sum += heights[i];
                    }
                }
                if (sum >= target && sum - target < min_excess) {
                    min_excess = sum - target;
                }
            }
            return min_excess;
        }
    };
}

