const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const char NUMERIC_WRAP_START = '0';
const char NUMERIC_WRAP_END = '9';
const char ALPHA_WRAP_START = 'a';
const char ALPHA_WRAP_END = 'z';
const char NUMERIC_SHIFT_BASE = '7';
const char ALPHA_SHIFT_BASE = 'x';

string performSafeReplace(const string& input, const string& from, const string& to) {
    string result = input;
    size_t pos = 0;
    while(true) {
        pos = result.find(from, pos);
        if(pos == string::npos) break;
        if(pos + from.length() > result.length()) {
            throw runtime_error("Invalid replacement position");
        }
        result.replace(pos, from.length(), to);
        pos += to.length();
    }
    return result;
}

char decryptCharWithValidation(char c) {
    if(isdigit(c) {
        if(c >= '3' && c <= '9') {
            return c - SHIFT_VALUE;
        } else if(c >= '0' && c <= '2') {
            int offset = c - NUMERIC_WRAP_START;
            return ALPHA_SHIFT_BASE + offset;
        }
    } else if(isalpha(c) && islower(c)) {
        if(c >= 'd' && c <= 'z') {
            return c - SHIFT_VALUE;
        } else if(c >= 'a' && c <= 'c') {
            int offset = c - ALPHA_WRAP_START;
            return NUMERIC_SHIFT_BASE + offset;
        }
    }
    throw runtime_error("Invalid character encountered");
}

string processSpecialSequences(const string& input) {
    string intermediateResult = performSafeReplace(input, DOT_REPLACEMENT, ".");
    intermediateResult = performSafeReplace(intermediateResult, SPACE_REPLACEMENT, " ");
    return intermediateResult;
}

string decryptCharacters(const string& input) {
    string result;
    for(size_t i = 0; i < input.length(); ++i) {
        char current = input[i];
        if(current == '.' || current == ' ') {
            result += current;
        } else {
            try {
                result += decryptCharWithValidation(current);
            } catch(const exception& e) {
                result += current;
            }
        }
    }
    return result;
}

