    long long current_iteration_count;
};

void initializePositionTracker(PositionTracker* tracker) {
    tracker->termination_condition_met = false;
    tracker->current_iteration_count = 0;
}

void processPosition(long long pos, PositionTracker* tracker) {
    if (tracker->termination_condition_met) {
        return;
    }
    if (tracker->current_iteration_count >= MAX_ITERATIONS) {
        tracker->termination_condition_met = true;
        return;
    }
    if (tracker->visited.find(pos) != tracker->visited.end()) {
        tracker->path.push_back(pos);
        tracker->termination_condition_met = true;
        return;
    }
    tracker->visited[pos] = true;
    tracker->path.push_back(pos);
    tracker->current_iteration_count++;
}

long long calculateNextPosition(long long current_pos) {
    if (current_pos <= 0) {
        return -1;
    }
    if (current_pos % 2 == 1) {
        long long n = (current_pos - 1) / 2;
        return 6 * n + 6;
    } else {
        return current_pos / 2;
    }
}

void simulateGame(long long start_pos, PositionTracker* tracker) {
    initializePositionTracker(tracker);
    long long current_position = start_pos;
    while (!tracker->termination_condition_met) {
