template<typename T, typename = typename enable_if<is_integral<T>::value>::type>
class PositionValidator {
public:
    static bool validateInitialPosition(T n) {
        if (n <= 0) throw invalid_argument("Position must be positive");
        if (n > numeric_limits<long long>::max()) throw overflow_error("Position too large");
        return true;
    }
};

template<typename T>
class PositionHistoryTracker {
private:
    vector<T> history;
    unordered_set<T> visited;
public:
    void recordPosition(T pos) {
        if (pos < 1) throw runtime_error("Invalid position recorded");
        history.push_back(pos);
    }
    bool hasVisited(T pos) const {
        return visited.find(pos) != visited.end();
    }
    void markVisited(T pos) {
        if (pos < 1) throw runtime_error("Cannot mark invalid position");
        visited.insert(pos);
    }
    const vector<T>& getHistory() const {
        return history;
    }
};

template<typename T>
T calculateNextPosition(T current) {
    if (current < 1) throw invalid_argument("Current position invalid");
    if (current % 2 == 1) {
        T n = (current - 1) / 2;
        T next = 6 * n + 6;
        if (next < current) throw runtime_error("Invalid forward movement");
        return next;
    } else {
        T next = current / 2;
        if (next >= current) throw runtime_error("Invalid backward movement");
        return next;
    }
}

template<typename T>
void simulateGame(T initialPos) {
    PositionValidator<T>::validateInitialPosition(initialPos);
    PositionHistoryTracker<T> tracker;

    T current = initialPos;
    while (true) {
        try {
            if (tracker.hasVisited(current)) {
                tracker.recordPosition(current);
                break;
            }
            tracker.recordPosition(current);
            tracker.markVisited(current);
            current = calculateNextPosition(current);
        } catch (const exception& e) {
            cerr << "Game simulation error: " << e.what() << endl;
            tracker.recordPosition(current);
            break;
        }
    }

