#include<bits/stdc++.h>
using namespace std;

struct RoadCondition {
    int code;
    int timeImpact;
    bool isTerminal;
    bool isSpecial;
};

class TankSimulator {
private:
    int remainingTime;
    vector<RoadCondition> conditions;
    bool reachedEnd;

    void initializeConditions() {
        conditions.push_back({6, 0, false, true});
        conditions.push_back({7, -5, false, true});
        conditions.push_back({12, -20, false, true});
        conditions.push_back({15, 0, true, true});
    }

    RoadCondition findCondition(int code) {
        for (const auto& cond : conditions) {
            if (cond.code == code) {
                return cond;
            }
        }
        return {code, -2, false, false};
    }

    void processMinute(int code) {
        RoadCondition current = findCondition(code);
        if (current.isTerminal) {
            reachedEnd = true;
            return;
        }
        if (current.isSpecial) {
            remainingTime += current.timeImpact;
        } else {
            remainingTime += current.timeImpact;
        }
        if (remainingTime <= 0) {
            reachedEnd = false;
        }
    }

public:
    TankSimulator(int time) : remainingTime(time), reachedEnd(false) {
        initializeConditions();
    }

    void simulate(vector<int> road) {
        for (size_t i = 0; i < road.size() && remainingTime > 0 && !reachedEnd; ++i) {
            try {
                if (road[i] < 1 || road[i] > 50) {
                    throw out_of_range("Invalid road condition code");
                }
                processMinute(road[i]);
            } catch (const exception& e) {
                remainingTime = -1;
                break;
            }
        }
    }

    string getResult() const {
        if (reachedEnd && remainingTime >= 0) {
            return "YES";
        }
        return "NO";
    }
};

int main() {
    int totalTime;
    cin >> totalTime;
    if (totalTime < 1 || totalTime > 100) {
        cout << "NO" << endl;
        return 1;
    }

    vector<int> roadConditions(totalTime);
    for (int i = 0; i < totalTime; ++i) {
        cin >> roadConditions[i];
        if (roadConditions[i] < 1 || roadConditions[i] > 50) {
            cout << "NO" << endl;
            return 1;
        }
    }

    TankSimulator simulator(totalTime);
    simulator.simulate(roadConditions);
    cout << simulator.getResult() << endl;

    return 0;
}
```

