                break;
            case RoadCondition::ROADBLOCK:
                state.remaining -= 5;
                break;
            case RoadCondition::TRAP:
                state.remaining -= 20;
                break;
            case RoadCondition::ENDPOINT:
                state.terminated = true;
                state.success = true;
                break;
            default:
                state.remaining -= 2;
                break;
