#include <bits/stdc++.h>
using namespace std;

int cal(int x, int y, char o) {
    if(o == '+') {
        return x + y;
    } else if(o == '-') {
        return y - x;
    } else if(o == '*') {
        return x * y;
    } else if(o == '/') {
        if(x == 0) {
            throw runtime_error("Division by zero detected");
        }
        return y / x;
    } else {
        throw invalid_argument("Invalid operator encountered");
    }
}

bool isHigherPrecedence(char op1, char op2) {
    if(op2 == '(' || op2 == ')') return false;
    if((op1 == '*' || op1 == '/') && (op2 == '+' || op2 == '-')) return true;
    if((op1 == '+' || op1 == '-') && (op2 == '*' || op2 == '/')) return false;
    return false;
}

void processOperation(stack<int>& nums, stack<char>& ops) {
    if(nums.size() < 2 || ops.empty()) {
        throw runtime_error("Invalid expression structure");
    }
    int tmp1 = nums.top();
    nums.pop();
    int tmp2 = nums.top();
    nums.pop();
    char op = ops.top();
    ops.pop();
    nums.push(cal(tmp1, tmp2, op));
}

int main() {
    string s;
    cin >> s;
    if(s.empty()) {
        cout << 0 << endl;
        return 0;
    }

    stack<int> nums;
    stack<char> ops;
    bool expectNumber = true;

    for(int i = 0; i < s.size(); i++) {
        if(isspace(s[i])) continue;

        if(isdigit(s[i])) {
            if(!expectNumber) {
                throw runtime_error("Unexpected number in expression");
            }
            nums.push(s[i] - '0');
            expectNumber = false;
        } else if(s[i] == '(') {
            ops.push(s[i]);
            expectNumber = true;
        } else if(s[i] == ')') {
            while(!ops.empty() && ops.top() != '(') {
                processOperation(nums, ops);
            }
            if(ops.empty()) {
                throw runtime_error("Mismatched parentheses");
            }
            ops.pop();
            expectNumber = false;
        } else if(s[i] == '+' || s[i] == '-' || s[i] == '*' || s[i] == '/') {
            if(expectNumber && s[i] != '-') {
                throw runtime_error("Unexpected operator in expression");
            }
            while(!ops.empty() && isHigherPrecedence(s[i], ops.top())) {
                processOperation(nums, ops);
            }
            ops.push(s[i]);
            expectNumber = true;
        } else {
            throw invalid_argument("Invalid character in expression");
        }
    }

    while(!ops.empty()) {
        if(ops.top() == '(') {
            throw runtime_error("Mismatched parentheses");
        }
        processOperation(nums, ops);
    }

    if(nums.size() != 1 || !ops.empty()) {
        throw runtime_error("Invalid expression format");
    }

    cout << nums.top() << endl;
    return 0;
}
