#include<bits/stdc++.h>
using namespace std;

struct StoneConfiguration {
    int sum;
    int mul;
    bool is_valid;
    int difference;
};

vector<StoneConfiguration> configurations;
int n;
vector<int> anger_values;
vector<int> irritability_values;
int global_minimum_difference = INT_MAX;

void validateAndStoreConfiguration(int current_sum, int current_mul, int stones_used) {
    StoneConfiguration config;
    config.sum = current_sum;
    config.mul = current_mul;
    config.is_valid = (stones_used > 0);

    if (config.is_valid) {
        if (current_sum > current_mul) {
            config.difference = current_sum - current_mul;
        } else {
            config.difference = current_mul - current_sum;
        }

        if (config.difference < global_minimum_difference) {
            global_minimum_difference = config.difference;
        }
    }

    configurations.push_back(config);
}

void recursiveStoneSelection(int current_index, int current_sum, int current_mul, int stones_used) {
    if (current_index >= n) {
        validateAndStoreConfiguration(current_sum, current_mul, stones_used);
        return;
    }

    int new_sum_with_stone = current_sum + irritability_values[current_index];
    int new_mul_with_stone = current_mul * anger_values[current_index];

    recursiveStoneSelection(current_index + 1, new_sum_with_stone, new_mul_with_stone, stones_used + 1);
    recursiveStoneSelection(current_index + 1, current_sum, current_mul, stones_used);
}

void initializeDataStructures() {
    anger_values.resize(n);
    irritability_values.resize(n);
    configurations.reserve(1 << n);
}

void readInputData() {
    ifstream input_file("stone.in");
    if (!input_file.is_open()) {
        cerr << "Error opening input file" << endl;
        exit(1);
