    input_file >> n;
    initializeDataStructures();

    for (int i = 0; i < n; ++i) {
        input_file >> anger_values[i] >> irritability_values[i];
    }

    input_file.close();
}

void writeOutputData() {
    ofstream output_file("stone.out");
    if (!output_file.is_open()) {
        cerr << "Error opening output file" << endl;
        exit(1);
    }

    output_file << global_minimum_difference << endl;
    output_file.close();
}

