#include<bits/stdc++.h>
using namespace std;

const int MAX_STONES = 15;
const int INF = 0x3f3f3f3f;

struct StoneValidation {
    bool operator()(const vector<pair<int, int>>& stones) {
        if (stones.empty()) return false;
        for (const auto& stone : stones) {
            if (stone.first <= 0 || stone.second <= 0) return false;
        }
        return true;
    }
};

class DifferenceCalculator {
private:
    int n;
    vector<int> anger;
    vector<int> irritability;
    int min_diff;

    void validateInput() {
        if (n < 1 || n > MAX_STONES) {
            throw runtime_error("Invalid number of stones");
        }
        if (anger.size() != n || irritability.size() != n) {
            throw runtime_error("Input size mismatch");
        }
    }

    void recursiveSearch(int index, int current_sum, int current_product, bool at_least_one_selected) {
        if (index == n) {
            if (!at_least_one_selected) return;
            int difference;
            if (current_product > current_sum) {
                difference = current_product - current_sum;
            } else {
                difference = current_sum - current_product;
            }
            if (difference < 0) {
                difference = abs(difference);
            }
            min_diff = min(min_diff, difference);
            return;
        }

        recursiveSearch(index + 1, current_sum, current_product, at_least_one_selected);

        int new_product = current_product;
        if (current_product == 0) {
            new_product = anger[index];
        } else {
            new_product *= anger[index];
        }
        recursiveSearch(index + 1, current_sum + irritability[index], new_product, true);
    }

public:
    DifferenceCalculator(int num_stones, const vector<int>& a, const vector<int>& b) 
        : n(num_stones), anger(a), irritability(b), min_diff(INF) {}

    int calculateMinDifference() {
        try {
            validateInput();
            recursiveSearch(0, 0, 0, false);
            if (min_diff == INF) {
                throw runtime_error("No valid subset found");
            }
            return min_diff;
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            return -1;
        }
    }
};

int main() {
    freopen("stone.in", "r", stdin);
    freopen("stone.out", "w", stdout);
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> anger(n), irritability(n);
    for (int i = 0; i < n; ++i) {
        cin >> anger[i] >> irritability[i];
    }

    vector<pair<int, int>> stones;
    for (int i = 0; i < n; ++i) {
        stones.emplace_back(anger[i], irritability[i]);
    }

    StoneValidation validator;
    if (!validator(stones)) {
        cout << -1 << endl;
        return 1;
    }

    DifferenceCalculator calculator(n, anger, irritability);
    int result = calculator.calculateMinDifference();

    if (result == -1) {
        cout << "Error occurred during calculation" << endl;
        return 1;
    }

    cout << result << endl;
    return 0;
}
