struct is_valid_integer_type {
    static constexpr bool value = is_same<T, long long>::value || is_same<T, unsigned long long>::value || is_same<T, int>::value;
};

template<typename T>
typename enable_if<is_valid_integer_type<T>::value, void>::type
validate_input_range(T n) {
    if (n < 1 || n > numeric_limits<long long>::max()) {
        throw out_of_range("Input value out of valid range");
    }
}

template<typename T>
typename enable_if<is_valid_integer_type<T>::value, string>::type
generate_sequence(T initial_n) {
    unordered_set<T> visited;
    vector<T> sequence;
    T current = initial_n;
    bool cycle_detected = false;
    int max_iterations = 1000000;
    int iteration_count = 0;

    while (!cycle_detected && iteration_count < max_iterations) {
        if (visited.find(current) != visited.end()) {
            cycle_detected = true;
            sequence.push_back(current);
            break;
        }

        visited.insert(current);
        sequence.push_back(current);

        if (current % 2 == 0) {
            T next = current / 2;
            if (next <= 0 || next > numeric_limits<T>::max()) {
                throw overflow_error("Calculation resulted in overflow");
            }
            current = next;
        } else {
            T next = 6 * (current / 2) + 6;
            if (next <= 0 || next > numeric_limits<T>::max()) {
                throw overflow_error("Calculation resulted in overflow");
            }
            current = next;
