#include <limits>
#include <stdexcept>
#include <type_traits>
#include <sstream>

using namespace std;

template<typename T>
class PositionValidator {
public:
    static bool isValidPosition(T pos) {
        return pos >= 1 && pos <= numeric_limits<T>::max();
    }
};

template<typename T>
class PositionHistoryManager {
private:
    unordered_set<T> visited;
    vector<T> sequence;
public:
    void recordPosition(T pos) {
        if (!PositionValidator<T>::isValidPosition(pos)) {
            throw out_of_range("Position value out of valid range");
        }
        sequence.push_back(pos);
    }

    bool hasVisited(T pos) const {
        return visited.find(pos) != visited.end();
    }

    void markVisited(T pos) {
        if (!PositionValidator<T>::isValidPosition(pos)) {
            throw out_of_range("Position value out of valid range");
        }
        visited.insert(pos);
    }

    const vector<T>& getSequence() const {
        return sequence;
    }
};

template<typename T>
class ChessMoveCalculator {
public:
    static T calculateNextPosition(T current) {
        static_assert(is_integral<T>::value, "Integer type required");
        if (!PositionValidator<T>::isValidPosition(current)) {
            throw invalid_argument("Invalid current position");
        }

        if (current % 2 == 0) {
            T next = current / 2;
            if (!PositionValidator<T>::isValidPosition(next)) {
                throw overflow_error("Position calculation overflow");
            }
            return next;
        } else {
            if (current > (numeric_limits<T>::max() - 3) / 3) {
                throw overflow_error("Position calculation overflow");
            }
            return current * 3 + 3;
        }
    }
};

