void processPosition(long long currentPosition, vector<long long>& visitedPositions, unordered_set<long long>& positionTracker, bool& terminationFlag) {
    if (positionTracker.find(currentPosition) != positionTracker.end()) {
        terminationFlag = true;
        return;
