#include<bits/stdc++.h>
using namespace std;

const int MAX_COWS = 25;
const int INF = 2147483647;

struct CowTowerValidator {
    bool operator()(int current_sum, int shelf_height) const {
        return current_sum >= shelf_height;
    }
};

class HeightAccumulator {
private:
    int heights[MAX_COWS];
    int cow_count;
    int shelf_height;
    int minimal_excess;

    void validateInputParameters() {
        if (cow_count < 1 || cow_count > 20) {
            throw invalid_argument("Invalid number of cows");
        }
        if (shelf_height < 1) {
            throw invalid_argument("Invalid shelf height");
        }
    }

    void initializeMinimalExcess() {
        minimal_excess = INF;
    }

    void recursiveHeightSearch(int current_cow, int current_sum) {
        if (current_cow > cow_count) {
            CowTowerValidator validator;
            if (validator(current_sum, shelf_height)) {
                if (current_sum < minimal_excess) {
                    minimal_excess = current_sum;
                }
            }
            return;
        }

        if (current_sum > minimal_excess + shelf_height) {
            return;
        }

        recursiveHeightSearch(current_cow + 1, current_sum + heights[current_cow]);
        recursiveHeightSearch(current_cow + 1, current_sum);
    }

public:
    HeightAccumulator(int n, int b, int h[]) : cow_count(n), shelf_height(b) {
        copy(h, h + n + 1, heights);
        validateInputParameters();
        initializeMinimalExcess();
    }

    int findMinimalExcess() {
        recursiveHeightSearch(1, 0);
        if (minimal_excess == INF) {
            throw runtime_error("No valid tower configuration found");
        }
        return minimal_excess - shelf_height;
    }
};

int main() {
    ifstream input_file("shelf.in");
    ofstream output_file("shelf.out");

    if (!input_file.is_open()) {
        cerr << "Failed to open input file" << endl;
        return EXIT_FAILURE;
    }

    if (!output_file.is_open()) {
        cerr << "Failed to open output file" << endl;
        return EXIT_FAILURE;
    }

    int n, b;
    input_file >> n >> b;

    int heights[MAX_COWS] = {0};
    for (int i = 1; i <= n; ++i) {
        input_file >> heights[i];
        if (heights[i] < 1 || heights[i] > 1000000) {
            cerr << "Invalid cow height detected" << endl;
            return EXIT_FAILURE;
        }
    }

    try {
        HeightAccumulator accumulator(n, b, heights);
        int result = accumulator.findMinimalExcess();
        output_file << result << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    input_file.close();
    output_file.close();

    return EXIT_SUCCESS;
}
