public:
    static void validateStone(const Stone& s) {
        if(s.anger < 0 || s.irritability < 0) {
            throw StoneValidationException();
        }
    }
};

class InputHandler {
private:
    static bool fileExists(const string& filename) {
        ifstream f(filename.c_str());
        return f.good();
    }

public:
    static void validateInput(int n, const vector<Stone>& stones) {
        if(n < 1 || n > 10) {
            throw InputValidationException();
        }
        if(stones.size() != static_cast<size_t>(n)) {
            throw InputValidationException();
        }
        for(const auto& stone : stones) {
            StoneValidator::validateStone(stone);
        }
    }

    static vector<Stone> readStones() {
        if(!fileExists("stone.in")) {
            throw InputValidationException();
        }

        ifstream fin("stone.in");
        int n;
        fin >> n;

        vector<Stone> stones(n);
        for(int i = 0; i < n; i++) {
            fin >> stones[i].anger >> stones[i].irritability;
            stones[i].validated = true;
        }

        validateInput(n, stones);
        return stones;
    }
};

class DifferenceCalculator {
private:
    vector<Stone> stones;
    int minDifference;

    void recursiveSearch(int index, int currentAnger, int currentIrritability, bool atLeastOneSelected) {
        if(index == stones.size()) {
            if(!atLeastOneSelected) return;
            int difference = abs(currentAnger - currentIrritability);
            if(difference < minDifference) {
                minDifference = difference;
            }
            return;
        }

        recursiveSearch(index + 1, currentAnger, currentIrritability, atLeastOneSelected);
        recursiveSearch(index + 1, 
                        currentAnger * stones[index].anger, 
                        currentIrritability + stones[index].irritability, 
                        true);
    }

public:
    DifferenceCalculator(const vector<Stone>& s) : stones(s), minDifference(INT_MAX) {}

    int calculateMinimumDifference() {
        if(stones.empty()) return 0;
        recursiveSearch(0, 1, 0, false);
        return minDifference;
    }
};

class OutputHandler {
public:
    static void writeOutput(int result) {
        ofstream fout("stone.out");
        if(!fout.is_open()) {
            throw runtime_error("Unable to open output file");
        }
        fout << result;
        fout.close();
    }
};

int main() {
    try {
        vector<Stone> stones = InputHandler::readStones();
        DifferenceCalculator calculator(stones);
        int result = calculator.calculateMinimumDifference();
        OutputHandler::writeOutput(result);
    } catch(const exception& e) {
        ofstream fout("stone.out");
        fout << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
