    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    return a.numeric_value > b.numeric_value;
}

long long convertToNumber(const std::string& s) {
    try {
        return std::stoll(s);
    } catch (const std::out_of_range& e) {
        return std::numeric_limits<long long>::max();
    } catch (const std::invalid_argument& e) {
        return 0;
    }
}

int calculateDigitSum(const std::string& s) {
    int total = 0;
    for (char c : s) {
        if (isdigit(c)) {
            total += c - '0';
        }
    }
    return total;
}

