#include <iostream>
#include <vector>
#include <string>
#include <stdexcept>
#include <algorithm>
#include <cctype>

using namespace std;

class CharacterValidator {
public:
    static bool isValidAlphabet(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    }

    static bool isValidNumber(char c) {
        return c >= '0' && c <= '9';
    }

    static bool isValidCharacter(char c) {
        return isValidAlphabet(c) || isValidNumber(c);
    }
};

class PositionCalculator {
public:
    static bool isTargetPosition(int index, int y) {
        if (y <= 0) throw invalid_argument("y must be positive");
        return index % y == 0;
    }
};

class CharacterTransformer {
private:
    static char transformAlphabet(char c, int z, bool isLower) {
        const int alphabetSize = 26;
        int base = isLower ? 'a' : 'A';
        int normalized = (c - base + z) % alphabetSize;
        if (normalized < 0) normalized += alphabetSize;
        return static_cast<char>(base + normalized);
    }

    static char transformNumber(char c, int z) {
        const int numberSize = 10;
        int normalized = (c - '0' + z) % numberSize;
        if (normalized < 0) normalized += numberSize;
        return static_cast<char>('0' + normalized);
    }

public:
    static char transformCharacter(char c, int z) {
        if (CharacterValidator::isValidAlphabet(c)) {
            bool isLower = islower(c);
            return transformAlphabet(c, z, isLower);
        } else if (CharacterValidator::isValidNumber(c)) {
            return transformNumber(c, z);
        }
        return c;
    }
};

class InputSanitizer {
public:
    static void validateInput(int x, int y, int z) {
        if (x <= 10 || x > 100) throw out_of_range("x must be 10 < x <= 100");
        if (y <= 0 || y > 10) throw out_of_range("y must be 0 < y <= 10");
        if (z <= 0 || z > 100) throw out_of_range("z must be 0 < z <= 100");
    }
};

int main() {
    try {
        int x, y, z;
        cin >> x >> y >> z;

        InputSanitizer::validateInput(x, y, z);

        vector<char> characters;
        characters.reserve(x);

        for (int i = 1; i <= x; ++i) {
            char c;
            cin >> c;

            if (!CharacterValidator::isValidCharacter(c)) {
                throw invalid_argument("Invalid character in input");
            }

            if (PositionCalculator::isTargetPosition(i, y)) {
                c = CharacterTransformer::transformCharacter(c, z);
            }

            characters.push_back(c);
        }

        for (const auto& c : characters) {
            cout << c;
        }

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
