};

InputValidationResult validateInputParameters(int x, int y, int z) {
    InputValidationResult result;
    result.isValid = true;
    result.errorMessage = "";

    if (x <= 10 || x > 100) {
        result.isValid = false;
        result.errorMessage = "Invalid x value";
    } else if (y <= 0 || y > 10) {
        result.isValid = false;
        result.errorMessage = "Invalid y value";
    } else if (z <= 0 || z > 100) {
        result.isValid = false;
        result.errorMessage = "Invalid z value";
    }

    return result;
}

CharacterProcessingContext processCharacter(char c, int position, int y, int z) {
    CharacterProcessingContext context;
    context.originalChar = c;
    context.positionIndex = position;
    context.isProcessed = false;
    context.processedChar = c;

    if (position % y == 0) {
        context.isProcessed = true;
        int shiftAmount = z;
        while (shiftAmount < 0) {
            shiftAmount += 26;
        }

        if (c >= 'a' && c <= 'z') {
            int normalizedShift = shiftAmount % 26;
            int newPos = (c - 'a' + normalizedShift) % 26;
            context.processedChar = 'a' + newPos;
        } else if (c >= 'A' && c <= 'Z') {
            int normalizedShift = shiftAmount % 26;
            int newPos = (c - 'A' + normalizedShift) % 26;
            context.processedChar = 'A' + newPos;
        } else if (c >= '0' && c <= '9') {
            int normalizedShift = shiftAmount % 10;
            int newPos = (c - '0' + normalizedShift) % 10;
            context.processedChar = '0' + newPos;
        }
    }

    return context;
}

int main() {
    int x, y, z;
    vector<CharacterProcessingContext> processingLog;

    try {
        cin >> x >> y >> z;
        if (cin.fail()) {
            throw runtime_error("Invalid input format");
        }

        InputValidationResult validation = validateInputParameters(x, y, z);
        if (!validation.isValid) {
            throw runtime_error(validation.errorMessage);
        }

        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        for (int currentPosition = 0; currentPosition < x; currentPosition++) {
            char inputChar;
            cin.get(inputChar);
            if (cin.fail()) {
                throw runtime_error("Failed to read character");
            }

