}

void validate_matrix_dimensions() {
    if (n < 3 || n > 200) {
        state.error_occurred = true;
    }
}

void process_matrix_element(int value) {
    if (!state.initialized) {
        state.current_value = value;
        state.initialized = true;
        state.current_count = 1;
    } else {
        if (value == state.current_value) {
            state.current_count++;
        } else {
            ans[++tot] = state.current_count;
            state.current_value = value;
            state.current_count = 1;
        }
    }
}

void finalize_compression() {
    if (state.initialized && !state.error_occurred) {
        ans[++tot] = state.current_count;
    }
}

void verify_compression_integrity() {
    int sum = 0;
    for (int i = 1; i <= tot; i++) {
        sum += ans[i];
    }
    if (sum != n * n) {
        state.error_occurred = true;
    }
}

