            fclose(input_file);
            fclose(output_file);
            exit(EXIT_FAILURE);
        }
        if (strlen(mat[i]) != n) {
            state.error_occurred = true;
        }
    }

    initialize_compression_state();

    for (int i = 1; i <= n && !state.error_occurred; i++) {
        for (int j = 0; j < n && !state.error_occurred; j++) {
            process_matrix_element(mat[i][j] - '0');
        }
    }

    finalize_compression();
    verify_compression_integrity();

    if (state.error_occurred) {
        fprintf(output_file, "Error in compression process\n");
    } else {
        fprintf(output_file, "%d ", n);
        for (int i = 1; i <= tot; i++) {
