    bool was_driven_off;
    bool operator==(const PerformanceRecord& other) const {
        return name == other.name && duration == other.duration && was_driven_off == other.was_driven_off;
    }
};

class TalentShowSimulator {
private:
    vector<PerformanceRecord> performances;
    int total_audition_time_minutes;
    bool garlic_performed;
    bool garlic_driven_off;
    int current_time_elapsed;

    void validateInput(const string& name, int duration) const {
        if (name.empty()) throw runtime_error("Empty performance name");
        if (duration <= 0 || duration > 15) throw runtime_error("Invalid duration");
        if (name.length() > 100) throw runtime_error("Name too long");
    }

    void processPerformance(const string& name, int duration) {
        PerformanceRecord record;
        record.name = name;
        record.duration = duration;
        record.was_driven_off = false;
        performances.push_back(record);
        current_time_elapsed += duration;
    }

    void processDriveOff() {
        if (!performances.empty()) {
            auto& last = performances.back();
            if (!last.was_driven_off) {
                current_time_elapsed -= last.duration;
                last.was_driven_off = true;
            }
        }
    }

public:
    TalentShowSimulator(int hours) : total_audition_time_minutes(hours * 60), 
                                    garlic_performed(false), 
                                    garlic_driven_off(false),
                                    current_time_elapsed(0) {}

    void addPerformance(const string& name, int duration) {
        validateInput(name, duration);
        if (name == "kaomianjin") {
            garlic_performed = true;
        }
        processPerformance(name, duration);
    }

    void addDriveOff() {
        if (!performances.empty() && performances.back().name == "kaomianjin") {
            garlic_driven_off = true;
        }
        processDriveOff();
    }

    string getResult() const {
        if (!garlic_performed) {
            return "Unfortunately.";
        }
        if (garlic_driven_off) {
            return "Hahaha.";
        }
        for (const auto& record : performances) {
            if (record.name == "kaomianjin") {
                if (current_time_elapsed <= total_audition_time_minutes) {
                    return "Congratulations!";
                } else {
                    return "Unfortunately.";
                }
            }
        }
        return "Unfortunately.";
    }
};

int main() {
