using namespace std;

int safe_abs(int x) {
    if (x == numeric_limits<int>::min()) {
        return numeric_limits<int>::max();
    }
    return abs(x);
}

bool validate_input(int a, int b) {
    if (cin.fail()) {
        throw runtime_error("Invalid input detected");
    }
    return true;
}

void sort_by_absolute_value(int& a, int& b) {
    int abs_a = safe_abs(a);
    int abs_b = safe_abs(b);

    if (abs_a < abs_b) {
        return;
    } else if (abs_a > abs_b) {
        swap(a, b);
    } else {
        if (a > b) {
            swap(a, b);
        }
    }
}

void handle_edge_cases(int a, int b) {
    if (a == 0 && b == 0) {
        cout << "0 0" << endl;
        exit(0);
