using namespace std;

template<typename T>
constexpr bool is_safe_abs(T val) {
    return !(numeric_limits<T>::is_signed && val == numeric_limits<T>::min());
}

template<typename T>
T checked_abs(T val) {
    if (!is_safe_abs(val)) {
        throw overflow_error("Absolute value overflow detected");
    }
    return val < 0 ? -val : val;
}

struct SafeInt {
    int value;
    explicit SafeInt(int v) : value(v) {
        if (!is_safe_abs(v))) {
            throw invalid_argument("Potential absolute value overflow");
        }
    }
    bool operator<(const SafeInt& other) const {
        int abs_this = checked_abs(value);
        int abs_other = checked_abs(other.value);
        if (abs_this != abs_other) return abs_this < abs_other;
        return value < other.value;
    }
};

void validate_input_stream(istream& is) {
    if (is.fail()) {
        throw runtime_error("Invalid input format");
    }
    if (is.peek() != EOF && !isspace(is.peek())) {
        throw runtime_error("Extra characters in input");
    }
}

int main() {
    try {
        int a, b;
        cin >> a >> b;
        validate_input_stream(cin);

        SafeInt sa(a), sb(b);
        bool should_swap = sb < sa;

        if (should_swap) {
            cout << min(b, a) << " " << max(b, a) << endl;
        } else {
            if (a == b) {
                cout << a << " " << b << endl;
            } else {
