T calculate_minutes_with_overflow_check(T n, T a, T b) {
    const T max_val = std::numeric_limits<T>::max();
    if (n > max_val / a) {
        throw std::overflow_error("Potential overflow in distance calculation");
    }
    T distance = n * a;
    if (distance <= 600) {
        throw std::logic_error("Enemy ship is already within shooting range");
    }
    T relative_speed = b - a;
    if (relative_speed == 0) {
        throw std::logic_error("Speeds must be different");
    }
    T minutes = distance / relative_speed;
    T remainder = distance % relative_speed;
    if (remainder != 0) {
        minutes++;
    }
    return minutes;
}

template<typename T>
T safe_divide(T dividend, T divisor) {
    if (divisor == 0) {
        throw std::invalid_argument("Division by zero");
    }
    return dividend / divisor;
