void performCompression() {
    if (matrixData.empty()) {
        exit(EXIT_FAILURE);
    }
    int N = matrixData[0].size();
    char previousChar = '\0';
    char currentChar = '\0';
    int currentCount = 0;
    bool firstIteration = true;
    for (int rowIndex = 0; rowIndex < N; ++rowIndex) {
        for (int colIndex = 0; colIndex < N; ++colIndex) {
            currentChar = matrixData[rowIndex][colIndex];
            if (firstIteration) {
