#include<iostream>
#include<string>
#include<vector>
#include<algorithm>
#include<fstream>
#include<exception>
#include<stdexcept>
#include<cctype>
using namespace std;

class MatrixValidator {
public:
    static bool validateSize(int size) {
        return size >= 3 && size <= 200;
    }

    static bool validateRow(const string& row, int expectedSize) {
        if (row.size() != expectedSize) return false;
        return all_of(row.begin(), row.end(), [](char c) {
            return c == '0' || c == '1';
        });
    }
};

class CompressionEngine {
private:
    vector<string> matrix;
    int currentCount;
    char currentChar;

    void initializeState() {
        if (!matrix.empty() && !matrix[0].empty()) {
            currentChar = matrix[0][0];
            currentCount = 0;
        }
    }

    void processTransition(char newChar, ostream& output) {
        if (newChar != currentChar) {
            output << currentCount << " ";
            currentCount = 1;
            currentChar = newChar;
        } else {
            currentCount++;
        }
    }

public:
    void loadMatrix(istream& input) {
        string firstRow;
        input >> firstRow;
        if (!MatrixValidator::validateRow(firstRow, firstRow.size())) {
            throw runtime_error("Invalid matrix row detected");
        }
        matrix.push_back(firstRow);

        int N = firstRow.size();
        if (!MatrixValidator::validateSize(N)) {
            throw runtime_error("Invalid matrix size");
        }

        for (int i = 1; i < N; i++) {
            string row;
            input >> row;
            if (!MatrixValidator::validateRow(row, N)) {
                throw runtime_error("Invalid matrix row detected");
            }
            matrix.push_back(row);
        }
    }

    void compress(ostream& output) {
        if (matrix.empty()) return;

        output << matrix.size() << " ";
        initializeState();

        for (const auto& row : matrix) {
            for (char c : row) {
                if (c != '0' && c != '1') {
                    throw runtime_error("Invalid character in matrix");
                }
                processTransition(c, output);
            }
        }

        if (currentCount > 0) {
            output << currentCount << " ";
        }
    }
};

class FileHandler {
public:
    static ifstream openInputFile(const string& filename) {
        ifstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("Could not open input file");
        }
        return file;
    }

    static ofstream openOutputFile(const string& filename) {
        ofstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("Could not open output file");
        }
        return file;
    }
};

int main() {
    try {
        auto inputFile = FileHandler::openInputFile("zip.in");
        auto outputFile = FileHandler::openOutputFile("zip.out");

        CompressionEngine engine;
        engine.loadMatrix(inputFile);
        engine.compress(outputFile);

        inputFile.close();
        outputFile.close();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

