#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <stdexcept>
#include <limits>
using namespace std;

void validateInputRange(int value, int min_val, int max_val, const string& param_name) {
    if (value <= min_val || value > max_val) {
        throw out_of_range(param_name + " out of valid range");
    }
}

void sanitizeString(string& s) {
    if (s.empty()) {
        throw invalid_argument("Book name cannot be empty");
    }
    if (s.length() > 20) {
        throw length_error("Book name exceeds maximum length");
    }
    for (char& c : s) {
        if (!isprint(c)) {
            c = '?';
        }
    }
}

struct Bookshelf {
    int id;
    vector<string> books;

    void validate() const {
        if (id <= 0) {
            throw logic_error("Invalid bookshelf ID");
        }
        for (const auto& book : books) {
            sanitizeString(const_cast<string&>(book));
        }
    }

    void sortBooks() {
        try {
            sort(books.begin(), books.end(), [](const string& a, const string& b) {
                return a < b;
            });
        } catch (...) {
            throw runtime_error("Failed to sort books");
        }
    }
};

int main() {
    try {
        int n, m;
        cin.exceptions(ios::failbit);
        cin >> n >> m;

        validateInputRange(n, 1, 10000, "n");
        validateInputRange(m, 1, 100000, "m");

        vector<Bookshelf> shelves(n);
        for (int i = 0; i < n; ++i) {
            shelves[i].id = i + 1;
        }

        for (int i = 0; i < m; ++i) {
            int k;
            string name;

            try {
                cin >> k >> name;
                validateInputRange(k, 1, n, "k_i");
                sanitizeString(name);

                if (k < 1 || k > n) {
                    throw out_of_range("Bookshelf index out of range");
                }

                shelves[k - 1].books.push_back(name);
            } catch (const exception& e) {
                cerr << "Error processing book " << (i + 1) << ": " << e.what() << endl;
                cin.clear();
                cin.ignore(numeric_limits<streamsize>::max(), '\n');
                continue;
            }
        }

        for (auto& shelf : shelves) {
            try {
                shelf.validate();
                shelf.sortBooks();

                cout << shelf.id << " " << shelf.books.size();
                if (!shelf.books.empty()) {
                    cout << " ";
                    for (size_t j = 0; j < shelf.books.size(); ++j) {
                        if (j > 0) {
                            cout << " ";
                        }
                        cout << shelf.books[j];
                    }
