const string SPACE_REPLACEMENT = "kkk";
const string DOT_REPLACEMENT = "sss";
const int SHIFT_VALUE = 3;
const int NUMERIC_WRAP_START = '0';
const int NUMERIC_WRAP_END = '9';
const int ALPHA_WRAP_START = 'a';
const int ALPHA_WRAP_END = 'z';

struct DecryptionMapping {
    string encrypted;
    char decrypted;
};

vector<DecryptionMapping> specialCases = {
    {SPACE_REPLACEMENT, ' '},
    {DOT_REPLACEMENT, '.'}
};

char handleAlphabetWrap(char c) {
    if (c >= 'a' && c <= 'c') {
        return NUMERIC_WRAP_END - ('c' - c);
    }
    return c;
}

char handleNumericWrap(char c) {
    if (c >= '0' && c <= '2') {
        return ALPHA_WRAP_END - ('2' - c);
    }
    return c;
}

char decryptCharacter(char c) {
    if (isalnum(c)) {
        if (isdigit(c)) {
            char temp = c - SHIFT_VALUE;
            if (temp < NUMERIC_WRAP_START) {
                temp = handleNumericWrap(c);
            }
            return temp;
        } else {
            char temp = c - SHIFT_VALUE;
            if (temp < ALPHA_WRAP_START) {
                temp = handleAlphabetWrap(c);
            }
            return temp;
        }
    }
    return c;
}

void processSpecialCases(string& s) {
    for (const auto& mapping : specialCases) {
        size_t pos = 0;
        while ((pos = s.find(mapping.encrypted, pos)) != string::npos) {
            string before = s.substr(0, pos);
            string after = s.substr(pos + mapping.encrypted.length());
            s = before + mapping.decrypted + after;
            pos += 1;
        }
    }
}

