using namespace std;

struct SubmatrixBoundary {
    int top;
    int bottom;
    int left;
    int right;
    bool operator==(const SubmatrixBoundary& other) const {
        return top == other.top && bottom == other.bottom && 
               left == other.left && right == other.right;
    }
};

namespace std {
    template<>
    struct hash<SubmatrixBoundary> {
        size_t operator()(const SubmatrixBoundary& sb) const {
            return hash<int>()(sb.top) ^ hash<int>()(sb.bottom) ^ 
                   hash<int>()(sb.left) ^ hash<int>()(sb.right);
        }
    };
}

class MatrixValidator {
public:
    static void validateDimensions(int n, int m) {
        if (n < 1 || n > 50 || m < 1 || m > 50) {
            throw out_of_range("Matrix dimensions out of bounds");
        }
    }

    static void validateElement(int val) {
        if (val < -1000 || val > 1000) {
            throw out_of_range("Matrix element out of bounds");
        }
    }
};

class SubmatrixProcessor {
private:
    vector<vector<int>> matrix;
    int n, m;
    unordered_map<SubmatrixBoundary, int> memo;

    void precomputePrefixSums(vector<vector<int>>& prefix) {
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                if (i == 0 || j == 0) {
                    prefix[i][j] = 0;
                } else {
                    prefix[i][j] = matrix[i-1][j-1] + prefix[i-1][j] + 
                                  prefix[i][j-1] - prefix[i-1][j-1];
                }
            }
        }
    }

    int calculateSubmatrixSum(const SubmatrixBoundary& sb, 
                            const vector<vector<int>>& prefix) {
        if (memo.find(sb) != memo.end()) {
            return memo[sb];
        }
        int sum = prefix[sb.bottom+1][sb.right+1] - 
                 prefix[sb.top][sb.right+1] - 
                 prefix[sb.bottom+1][sb.left] + 
                 prefix[sb.top][sb.left];
        memo[sb] = sum;
        return sum;
    }

public:
    SubmatrixProcessor(const vector<vector<int>>& mat, int rows, int cols) 
        : matrix(mat), n(rows), m(cols) {
        MatrixValidator::validateDimensions(n, m);
        for (const auto& row : matrix) {
            for (int val : row) {
                MatrixValidator::validateElement(val);
            }
        }
    }

    int findMaxSubmatrixSum() {
        vector<vector<int>> prefix(n+1, vector<int>(m+1, 0));
        precomputePrefixSums(prefix);

        int max_sum = numeric_limits<int>::min();
        vector<SubmatrixBoundary> boundaries;

        for (int top = 0; top < n; ++top) {
            for (int left = 0; left < m; ++left) {
                for (int bottom = top; bottom < n; ++bottom) {
                    for (int right = left; right < m; ++right) {
                        SubmatrixBoundary sb{top, bottom, left, right};
                        boundaries.push_back(sb);
                    }
                }
            }
        }

        for (const auto& sb : boundaries) {
            int current_sum = calculateSubmatrixSum(sb, prefix);
            if (current_sum > max_sum) {
                max_sum = current_sum;
            }
        }

        return max_sum;
    }
};

