struct SubmatrixBoundary {
    int top_row;
    int bottom_row;
    int left_col;
    int right_col;
};

struct MatrixDimension {
    int rows;
    int cols;
};

struct MatrixElement {
    int value;
    bool is_visited;
};

vector<vector<MatrixElement>> matrix_data;
vector<vector<int>> prefix_sum_cache;
int global_maximum = INT_MIN;

void validate_input_file(ifstream& input_file) {
    if (!input_file.is_open()) {
        throw runtime_error("Unable to open input file");
    }
}

void validate_output_file(ofstream& output_file) {
    if (!output_file.is_open()) {
        throw runtime_error("Unable to open output file");
    }
}

void initialize_prefix_sum_cache(const MatrixDimension& dimensions) {
    prefix_sum_cache.resize(dimensions.rows + 1, vector<int>(dimensions.cols + 1, 0));
    for (int i = 1; i <= dimensions.rows; ++i) {
        for (int j = 1; j <= dimensions.cols; ++j) {
            prefix_sum_cache[i][j] = prefix_sum_cache[i-1][j] + prefix_sum_cache[i][j-1] 
                                   - prefix_sum_cache[i-1][j-1] + matrix_data[i-1][j-1].value;
        }
    }
}

int calculate_submatrix_sum(const SubmatrixBoundary& boundary) {
    return prefix_sum_cache[boundary.bottom_row][boundary.right_col] 
           - prefix_sum_cache[boundary.top_row-1][boundary.right_col] 
           - prefix_sum_cache[boundary.bottom_row][boundary.left_col-1] 
           + prefix_sum_cache[boundary.top_row-1][boundary.left_col-1];
}

void process_all_possible_submatrices(const MatrixDimension& dimensions) {
    for (int top = 1; top <= dimensions.rows; ++top) {
        for (int left = 1; left <= dimensions.cols; ++left) {
            for (int bottom = top; bottom <= dimensions.rows; ++bottom) {
                for (int right = left; right <= dimensions.cols; ++right) {
                    SubmatrixBoundary current_boundary = {top, bottom, left, right};
                    int current_sum = calculate_submatrix_sum(current_boundary);
                    if (current_sum > global_maximum) {
                        global_maximum = current_sum;
                    }
                }
            }
        }
    }
}

void read_input_data(ifstream& input_file, MatrixDimension& dimensions) {
    input_file >> dimensions.rows >> dimensions.cols;
    matrix_data.resize(dimensions.rows, vector<MatrixElement>(dimensions.cols));
    for (int i = 0; i < dimensions.rows; ++i) {
        for (int j = 0; j < dimensions.cols; ++j) {
            input_file >> matrix_data[i][j].value;
            matrix_data[i][j].is_visited = false;
        }
    }
}

void write_output_data(ofstream& output_file) {
    output_file << global_maximum;
}

int main() {
    try {
        ifstream input_file("submatrix.in");
        validate_input_file(input_file);

        MatrixDimension matrix_dimensions;
        read_input_data(input_file, matrix_dimensions);
        input_file.close();

        initialize_prefix_sum_cache(matrix_dimensions);
        process_all_possible_submatrices(matrix_dimensions);

        ofstream output_file("submatrix.out");
        validate_output_file(output_file);
        write_output_data(output_file);
        output_file.close();
    } catch (const exception& e) {
        cerr << "Error occurred: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
