struct MatrixValidationResult {
    bool isValid;
    string errorMessage;
};

struct BFSNode {
    int x;
    int y;
};

const int MAX_DIMENSION = 50;
const int MIN_ELEMENT_VALUE = -1000;
const int MAX_ELEMENT_VALUE = 1000;
const int DIRECTIONS[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

int matrix[MAX_DIMENSION + 2][MAX_DIMENSION + 2];
bool visited[MAX_DIMENSION + 2][MAX_DIMENSION + 2];
int tempSum = 0;
int maxSum = numeric_limits<int>::min();
int rows, cols;

MatrixValidationResult validateMatrixDimensions(int n, int m) {
    MatrixValidationResult result;
    result.isValid = true;
    if (n < 1 || n > MAX_DIMENSION || m < 1 || m > MAX_DIMENSION) {
        result.isValid = false;
        result.errorMessage = "Invalid matrix dimensions";
    }
    return result;
}

MatrixValidationResult validateMatrixElement(int value) {
    MatrixValidationResult result;
    result.isValid = true;
    if (value < MIN_ELEMENT_VALUE || value > MAX_ELEMENT_VALUE) {
        result.isValid = false;
        result.errorMessage = "Matrix element out of bounds";
    }
    return result;
}

void initializeVisitedMatrix() {
    for (int i = 0; i <= rows + 1; i++) {
        for (int j = 0; j <= cols + 1; j++) {
            visited[i][j] = false;
        }
    }
}

void performBFSForPositiveRegion(int startX, int startY) {
    queue<BFSNode> bfsQueue;
    bfsQueue.push(BFSNode{startX, startY});
    visited[startX][startY] = true;

    while (!bfsQueue.empty()) {
        BFSNode current = bfsQueue.front();
        bfsQueue.pop();
        tempSum += matrix[current.x][current.y];

        for (int dir = 0; dir < 4; dir++) {
            int newX = current.x + DIRECTIONS[dir][0];
            int newY = current.y + DIRECTIONS[dir][1];

            if (newX < 1 || newX > rows || newY < 1 || newY > cols) {
                continue;
