#include <bits/stdc++.h>
#include <limits>
#include <stdexcept>
using namespace std;

const int MAX_ITERATIONS = 10000000;
const int SAFETY_THRESHOLD = 5000000;
const double EPSILON = 1e-10;

struct SolutionValidator {
    static bool validateSolutionComponents(const vector<int>& components, int target) {
        long long sum = 0;
        for (int comp : components) {
            if (comp < 0 || comp > SAFETY_THRESHOLD) {
                return false;
            }
            sum += static_cast<long long>(comp) * comp;
        }
        return sum == target;
    }
};

class FourSquaresSolver {
private:
    int targetNumber;
    vector<int> currentSolution;
    vector<int> bestSolution;
    bool solutionFound;

    void initializeBestSolution() {
        bestSolution = {numeric_limits<int>::max(), numeric_limits<int>::max(), 
                       numeric_limits<int>::max(), numeric_limits<int>::max()};
    }

    bool isBetterSolution(const vector<int>& newSolution) {
        for (int i = 0; i < 4; ++i) {
            if (newSolution[i] < bestSolution[i]) return true;
            if (newSolution[i] > bestSolution[i]) return false;
        }
        return false;
    }

    void verifyAndStoreSolution() {
        vector<int> tempSolution = currentSolution;
        sort(tempSolution.begin(), tempSolution.end());
        if (SolutionValidator::validateSolutionComponents(tempSolution, targetNumber)) {
            if (!solutionFound || isBetterSolution(tempSolution)) {
                bestSolution = tempSolution;
                solutionFound = true;
            }
        }
    }

public:
    FourSquaresSolver(int n) : targetNumber(n), solutionFound(false) {
        initializeBestSolution();
    }

    void solve() {
        int iterationCounter = 0;
        int maxA = static_cast<int>(sqrt(targetNumber)) + 1;
        for (int a = 0; a <= maxA && iterationCounter < MAX_ITERATIONS; ++a) {
            int remainingAfterA = targetNumber - a * a;
            if (remainingAfterA < 0) continue;
            int maxB = static_cast<int>(sqrt(remainingAfterA)) + 1;
            for (int b = a; b <= maxB && iterationCounter < MAX_ITERATIONS; ++b) {
                int remainingAfterB = remainingAfterA - b * b;
                if (remainingAfterB < 0) continue;
                int maxC = static_cast<int>(sqrt(remainingAfterB)) + 1;
                for (int c = b; c <= maxC && iterationCounter < MAX_ITERATIONS; ++c) {
                    int remainingAfterC = remainingAfterB - c * c;
                    if (remainingAfterC < 0) continue;
                    double dDouble = sqrt(remainingAfterC);
                    if (abs(dDouble - round(dDouble)) > EPSILON) continue;
                    int d = static_cast<int>(round(dDouble));
                    if (d < c) continue;
                    currentSolution = {a, b, c, d};
                    verifyAndStoreSolution();
                    iterationCounter++;
                }
            }
        }
    }

    vector<int> getBestSolution() {
        if (!solutionFound) {
            throw runtime_error("No valid solution found after exhaustive search");
        }
        return bestSolution;
    }
};

int main() {
    ifstream inputFile("square.in", ios::in);
    ofstream outputFile("square.out", ios::out);

    if (!inputFile.is_open() || !outputFile.is_open()) {
        cerr << "File operation failed" << endl;
        return EXIT_FAILURE;
    }

    int N;
    inputFile >> N;

    if (N < 1 || N > SAFETY_THRESHOLD) {
        cerr << "Invalid input range" << endl;
        return EXIT_FAILURE;
    }

    FourSquaresSolver solver(N);
    solver.solve();

    vector<int> result = solver.getBestSolution();
    for (size_t i = 0; i < result.size(); ++i) {
        outputFile << result[i];
        if (i != result.size() - 1) {
            outputFile << " ";
        }
    }

    inputFile.close();
    outputFile.close();
    return EXIT_SUCCESS;
}
