bool is_lexicographically_smaller(const array<int, 4>& lhs, const array<int, 4>& rhs) {
    for (int i = 0; i < 4; ++i) {
        if (lhs[i] != rhs[i]) {
            return lhs[i] < rhs[i];
        }
    }
    return false;
}

void find_all_solutions(int n) {
    int upper_bound = static_cast<int>(sqrt(n)) + 1;
    upper_bound = min(upper_bound, MAX_SQRT);

    for (int i = 0; i <= upper_bound; ++i) {
        int i_sq = i * i;
        if (i_sq > n) continue;

        for (int j = i; j <= upper_bound; ++j) {
            int j_sq = j * j;
            if (i_sq + j_sq > n) continue;

            for (int k = j; k <= upper_bound; ++k) {
                int k_sq = k * k;
                if (i_sq + j_sq + k_sq > n) continue;

                int remaining = n - i_sq - j_sq - k_sq;
                if (remaining < 0) continue;

                int l = static_cast<int>(sqrt(remaining));
                if (l * l == remaining && l >= k) {
                    array<int, 4> current_solution = {i, j, k, l};
                    validate_solution(current_solution);
                    solution_cache.push_back(current_solution);
                }
            }
        }
    }
