    if (grid[y1-1][x1-1] != '.' || grid[y2-1][x2-1] != '.') {
        return false;
    }

    set<State> visited;
    queue<State> q;

    for (int initialDir = 0; initialDir < 4; ++initialDir) {
        State start{x1, y1, initialDir, 0};
        if (visited.find(start) == visited.end()) {
            q.push(start);
            visited.insert(start);
        }
    }

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        if (current.x == x2 && current.y == y2) {
            if (current.turns <= k) {
                return true;
            }
            continue;
        }

        for (int newDir = 0; newDir < 4; ++newDir) {
            int newX = current.x + dx[newDir];
            int newY = current.y + dy[newDir];
            if (!isValid(newX, newY, m, n)) {
                continue;
            }
            if (grid[newY-1][newX-1] != '.') {
                continue;
            }
            int newTurns = current.turns;
            if (newDir != current.dir) {
                newTurns++;
            }
            if (newTurns > k) {
                continue;
            }
            State next{newX, newY, newDir, newTurns};
            if (visited.find(next) == visited.end()) {
                visited.insert(next);
                q.push(next);
            }
        }
    }

    return false;
}

