template<typename T>
T calculateElevatorTime(const vector<FloorData<T>>& floors) {
    T totalTime = 0;
    T currentFloor = 0;
    bool doorOpen = false;
    bool movementInProgress = false;
    size_t processedCount = 0;
    size_t totalFloors = floors.size();

    while (processedCount < totalFloors) {
        for (const auto& floorData : floors) {
            if (!floorData.processed) {
                T floorDifference = abs(floorData.floor - currentFloor);
                if (floorDifference > 0) {
                    if (floorData.floor > currentFloor) {
                        totalTime += floorDifference * 5;
                    } else {
                        totalTime += floorDifference * 4;
                    }
                    currentFloor = floorData.floor;
                    movementInProgress = true;
                }
                if (!doorOpen) {
                    totalTime += 3;
                    doorOpen = true;
                }
                totalTime += floorData.count * 2;
                const_cast<FloorData<T>&>(floorData).processed = true;
                processedCount++;
                doorOpen = false;
                movementInProgress = false;
            }
        }
    }

    if (currentFloor != 0) {
        T returnDifference = currentFloor;
        totalTime += returnDifference * 4;
        currentFloor = 0;
    }

    return totalTime;
}

