class MatrixProcessor {
private:
    string matrixData;
    int matrixSize;

public:
    MatrixProcessor(const string& data, int size) : matrixData(data), matrixSize(size) {
        if (matrixData.empty()) {
            throw runtime_error("Matrix data cannot be empty");
        }
        if (matrixSize < 3 || matrixSize > 200) {
            throw runtime_error("Invalid matrix size");
        }
    }

    string generateCompressionCode() {
        stringstream compressedOutput;
        compressedOutput << matrixSize << ' ';

        if (matrixData.empty()) return "";

        char currentState = matrixData[0];
        int counter = 1;
        bool stateChanged = false;

        for (size_t i = 1; i < matrixData.length(); ++i) {
            if (matrixData[i] == currentState) {
                counter++;
                stateChanged = false;
            } else {
                compressedOutput << counter << ' ';
                currentState = matrixData[i];
                counter = 1;
                stateChanged = true;
            }

            if (i == matrixData.length() - 1) {
                if (!stateChanged) {
                    compressedOutput << counter;
                } else {
                    compressedOutput << ' ' << counter;
                }
            }
        }

        string result = compressedOutput.str();
        if (result.back() == ' ') {
            result.pop_back();
        }
        return result;
    }
};

