struct SquareResult {
    int a;
    int b;
    int c;
    int d;
    bool found;
};

SquareResult find_squares_bruteforce(int n) {
    SquareResult result = {0, 0, 0, 0, false};
    int max_iter = static_cast<int>(ceil(sqrt(n))) + 2;

    for (int a = 0; a <= max_iter && !result.found; ++a) {
        for (int b = 0; b <= max_iter && !result.found; ++b) {
            for (int c = 0; c <= max_iter && !result.found; ++c) {
                int remaining = n - (a*a + b*b + c*c);
                if (remaining < 0) continue;
                int d = static_cast<int>(round(sqrt(remaining)));
                for (int offset = -2; offset <= 2 && !result.found; ++offset) {
                    int current_d = d + offset;
                    if (current_d < 0) continue;
                    if (a*a + b*b + c*c + current_d*current_d == n) {
                        result = {a, b, c, current_d, true};
                    }
                }
            }
        }
    }

    if (!result.found) {
        throw runtime_error("No solution found (should never happen per Lagrange's theorem)");
    }

    return result;
}

