#include <bits/stdc++.h>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <type_traits>
using namespace std;

template<typename T>
struct SquareSumValidator {
    static_assert(is_integral<T>::value, "Integral type required");
    static bool validate(T a, T b, T c, T d, T target) {
        try {
            if (a < 0 || b < 0 || c < 0 || d < 0) {
                throw out_of_range("Negative values not allowed");
            }
            T aa = a * a;
            T bb = b * b;
            T cc = c * c;
            T dd = d * d;
            if (aa > numeric_limits<T>::max() - bb || 
                aa + bb > numeric_limits<T>::max() - cc || 
                aa + bb + cc > numeric_limits<T>::max() - dd) {
                throw overflow_error("Potential integer overflow detected");
            }
            return (aa + bb + cc + dd) == target;
        } catch (const exception& e) {
            cerr << "Validation error: " << e.what() << endl;
            return false;
        }
    }
};

template<typename T>
class FourSquareSolver {
private:
    T n;
    bool solution_found;
    T a_val, b_val, c_val, d_val;

    void check_and_set_solution(T a, T b, T c, T d) {
        if (SquareSumValidator<T>::validate(a, b, c, d, n)) {
            if (!solution_found) {
                solution_found = true;
                a_val = a;
                b_val = b;
                c_val = c;
                d_val = d;
            } else {
                if (make_tuple(a, b, c, d) < make_tuple(a_val, b_val, c_val, d_val)) {
                    a_val = a;
                    b_val = b;
                    c_val = c;
                    d_val = d;
                }
            }
        }
    }

public:
    FourSquareSolver(T num) : n(num), solution_found(false), a_val(0), b_val(0), c_val(0), d_val(0) {
        if (n <= 0) {
            throw invalid_argument("Input must be positive");
        }
    }

    void solve() {
        T max_possible = static_cast<T>(sqrt(n)) + 2;
        vector<T> square_roots(max_possible + 1);
        for (T i = 0; i <= max_possible; ++i) {
            square_roots[i] = i * i;
        }

        for (T a = 0; a <= max_possible && !solution_found; ++a) {
            for (T b = a; b <= max_possible && !solution_found; ++b) {
                for (T c = b; c <= max_possible && !solution_found; ++c) {
                    T remaining = n - square_roots[a] - square_roots[b] - square_roots[c];
                    if (remaining < 0) continue;
                    T d = static_cast<T>(sqrt(remaining));
                    for (T delta = -2; delta <= 2; ++delta) {
                        T current_d = d + delta;
                        if (current_d >= c && current_d >= 0) {
                            check_and_set_solution(a, b, c, current_d);
                        }
                    }
                }
            }
        }
    }

    tuple<T, T, T, T> get_solution() const {
        if (!solution_found) {
            throw runtime_error("No solution found");
        }
        return make_tuple(a_val, b_val, c_val, d_val);
    }
};

int main() {
    ifstream input_file("square.in");
    ofstream output_file("square.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "File opening failed" << endl;
        return EXIT_FAILURE;
    }

    int n;
    input_file >> n;

    try {
        FourSquareSolver<int> solver(n);
        solver.solve();
        auto [a, b, c, d] = solver.get_solution();
        output_file << a << " " << b << " " << c << " " << d;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    input_file.close();
    output_file.close();
    return EXIT_SUCCESS;
}
