template<typename T>
constexpr bool is_positive_integer(T value) {
    return std::is_integral<T>::value && value > 0;
}

template<typename T>
void validate_input_range(T value, T min, T max) {
    if (value < min || value > max) {
        throw std::out_of_range("Input value out of specified range");
    }
}

template<typename T>
T safe_abs(T value) {
    static_assert(std::is_arithmetic<T>::value, "Type must be arithmetic");
    return value < 0 ? -value : value;
}

template<typename T>
T calculate_time_until_shooting(T n, T a, T b) {
    const T shooting_distance = 600;
    const T epsilon = std::numeric_limits<T>::epsilon();

    if (!is_positive_integer(n) || !is_positive_integer(a) || !is_positive_integer(b)) {
        throw std::invalid_argument("All inputs must be positive integers");
    }

    validate_input_range(n, static_cast<T>(1), static_cast<T>(1000));
    validate_input_range(a, static_cast<T>(1), static_cast<T>(1000));
    validate_input_range(b, static_cast<T>(1), static_cast<T>(1000));

    if (b <= a) {
        throw std::logic_error("Troop speed must be greater than enemy speed");
    }

    T initial_enemy_lead = n * a;
    if (initial_enemy_lead <= shooting_distance) {
        throw std::logic_error("Enemy must be farther than shooting distance initially");
    }

    T relative_speed = b - a;
    T time_required = (initial_enemy_lead - shooting_distance + relative_speed - 1) / relative_speed;

    T verification_distance = initial_enemy_lead + a * time_required;
    T troops_distance = b * time_required;
    T actual_distance = safe_abs(verification_distance - troops_distance);

    if (actual_distance > shooting_distance + epsilon) {
        time_required += (actual_distance - shooting_distance + relative_speed - 1) / relative_speed;
    }

    T alternative_calculation = static_cast<T>(std::ceil(static_cast<double>(initial_enemy_lead - shooting_distance) / static_cast<double>(relative_speed)));
    if (time_required != alternative_calculation) {
        time_required = std::max(time_required, alternative_calculation);
    }

    return time_required;
}

int main() {
