    const T shooting_distance = 600;
    const T epsilon = std::numeric_limits<T>::epsilon();

    if (b <= a) {
        throw std::logic_error("Troops speed must be greater than enemy speed");
    }

    T initial_distance = n * a;
    if (initial_distance <= shooting_distance) {
