vector<string> tokenizeWithValidation(const string& input) {
    vector<string> tokens;
    string current;
    bool inWord = false;
    bool hasInvalidChar = false;

    for (size_t i = 0; i < input.size(); ++i) {
        if (isalpha(input[i])) {
            if (hasInvalidChar) {
                throw runtime_error("Invalid character sequence detected");
            }
            current += input[i];
            inWord = true;
        } else if (input[i] == ' ') {
            if (inWord) {
                if (!current.empty()) {
                    tokens.push_back(current);
                }
                current.clear();
                inWord = false;
                hasInvalidChar = false;
            }
        } else {
            hasInvalidChar = true;
        }
    }

    if (inWord && !current.empty()) {
        tokens.push_back(current);
    }

    if (tokens.empty()) {
        throw runtime_error("No valid words found");
    }

    return tokens;
}

string findLongestWordWithBackup(const vector<string>& words) {
    if (words.empty()) {
        return "";
