    void initializeElevatorState(ElevatorState& state) {
        state.current_floor = 0;
        state.total_time = 0;
        state.door_open_status = false;
    }

    void processPersonEntry(ElevatorState& state, long long target_floor) {
        state.destinations.push_back(target_floor);
    }

    void moveElevator(ElevatorState& state, long long target_floor) {
        bool movement_occurred = false;
        long long previous_floor = state.current_floor;
        long long movement_time = 0;

        while (state.current_floor != target_floor) {
            if (state.current_floor < target_floor) {
                state.current_floor++;
                movement_time += 5;
            } else {
                state.current_floor--;
                movement_time += 4;
            }
            movement_occurred = true;
        }

        if (movement_occurred) {
            state.total_time += movement_time;
            state.door_open_status = false;
        }
    }

    void handleDoorOperations(ElevatorState& state, bool movement_occurred) {
        if (movement_occurred || state.door_open_status == false) {
            state.total_time += 3;
            state.door_open_status = true;
        }
    }

    void processPersonExit(ElevatorState& state) {
        state.total_time += 2;
    }

