using namespace std;

struct WordMetadata {
    string content;
    size_t start_pos;
    size_t end_pos;
    size_t length;
    size_t occurrence_order;
};

class SentenceAnalyzer {
private:
    string sentence;
    vector<WordMetadata> words;
    bool analyzed;

    void validateSentence() {
        if (sentence.empty()) {
            throw runtime_error("Empty sentence provided");
        }
        for (char c : sentence) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Invalid character in sentence");
            }
        }
    }

    void tokenizeWords() {
        size_t start = 0;
        size_t end = 0;
        size_t order = 0;
        bool in_word = false;

        while (end < sentence.length()) {
            if (isalpha(sentence[end])) {
                if (!in_word) {
                    start = end;
                    in_word = true;
                }
            } else {
                if (in_word) {
                    words.push_back({
                        sentence.substr(start, end - start),
                        start,
                        end - 1,
                        end - start,
                        order++
                    });
                    in_word = false;
                }
            }
            end++;
        }

        if (in_word) {
            words.push_back({
                sentence.substr(start, end - start),
                start,
                end - 1,
                end - start,
                order++
            });
        }
    }

public:
    explicit SentenceAnalyzer(const string& s) : sentence(s), analyzed(false) {
        validateSentence();
    }

    void analyze() {
        if (analyzed) return;
        tokenizeWords();
        analyzed = true;
    }

    string findLongestWord() {
        if (!analyzed) analyze();

        if (words.empty()) return "";

        auto max_it = max_element(words.begin(), words.end(),
            [](const WordMetadata& a, const WordMetadata& b) {
                if (a.length != b.length) {
                    return a.length < b.length;
                }
                return a.occurrence_order > b.occurrence_order;
            });

        return max_it->content;
    }

    vector<WordMetadata> getAllWords() const {
        return words;
    }
};

int main() {
    try {
        string input;
        getline(cin, input);

        if (cin.fail()) {
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            throw runtime_error("Input reading failed");
        }

        SentenceAnalyzer analyzer(input);
        analyzer.analyze();

        string longest = analyzer.findLongestWord();
        if (!longest.empty()) {
            cout << longest;
        } else {
            cout << "No valid words found";
        }

        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
}
