class RoadConditionProcessor {
private:
    vector<int> road_conditions;
    CombatStatus status;

    void validateInput(int n, const vector<int>& conditions) {
        if (n <= 0 || n > 100) {
            throw invalid_argument("Invalid combat time");
        }
        for (int condition : conditions) {
            if (condition <= 0 || condition > 50) {
                throw invalid_argument("Invalid road condition");
            }
        }
    }

    void processCondition(int condition) {
        if (condition == 6) {
            return;
        } else if (condition == 7) {
            status.remaining_time -= 5;
        } else if (condition == 12) {
            status.remaining_time -= 20;
        } else if (condition == 15) {
            status.reached_endpoint = true;
        } else {
            status.remaining_time -= 2;
        }

        if (status.remaining_time <= 0 && !status.reached_endpoint) {
            status.time_expired = true;
        }
    }

public:
    RoadConditionProcessor(int n, const vector<int>& conditions) {
        validateInput(n, conditions);
        status.remaining_time = n;
        status.reached_endpoint = false;
        status.time_expired = false;
        road_conditions = conditions;
    }

    string executeCombat() {
        for (size_t i = 0; i < road_conditions.size() && !status.reached_endpoint && !status.time_expired; ++i) {
            try {
                processCondition(road_conditions[i]);
            } catch (...) {
                return "No";
            }
        }

        if (status.reached_endpoint && status.remaining_time >= 0) {
            return "Yes";
        } else {
            return "No";
