    NORMAL = -1
};

RoadCondition parseRoadCondition(const string& input) {
    try {
        int value = stoi(input);
        switch(value) {
            case 6: return RoadCondition::ACCELERATION_BELT;
            case 7: return RoadCondition::ROADBLOCK;
            case 12: return RoadCondition::TRAP;
            case 15: return RoadCondition::ENDPOINT;
            default: return RoadCondition::NORMAL;
        }
    } catch (const invalid_argument& e) {
        return RoadCondition::NORMAL;
    } catch (const out_of_range& e) {
        return RoadCondition::NORMAL;
    }
}

bool validateInput(int n, const vector<string>& conditions) {
    if (n <= 0 || n > 100) return false;
    for (const auto& cond : conditions) {
        try {
            int val = stoi(cond);
            if (val < 1 || val > 50) return false;
        } catch (...) {
            return false;
        }
    }
    return true;
}

vector<string> splitString(const string& s) {
