void initialize_elevator(ElevatorState& state) {
    state.current_floor = 0;
    state.total_time = 0;
    state.door_open = false;
}

void process_destinations(ElevatorState& state) {
    sort(state.destinations.begin(), state.destinations.end());
    state.destinations.erase(unique(state.destinations.begin(), state.destinations.end()), state.destinations.end());
}

void calculate_movement_time(ElevatorState& state) {
    long long previous_floor = 0;
    for (size_t i = 0; i < state.destinations.size(); ++i) {
        long long floor_diff = state.destinations[i] - previous_floor;
        if (floor_diff > 0) {
            state.total_time += floor_diff * UP_TIME;
        } else if (floor_diff < 0) {
            state.total_time += abs(floor_diff) * DOWN_TIME;
        }
        state.total_time += OPEN_TIME;
        previous_floor = state.destinations[i];
    }
    long long return_diff = previous_floor;
    if (return_diff > 0) {
        state.total_time += return_diff * DOWN_TIME;
    }
}

void calculate_exit_time(ElevatorState& state, long long n) {
