    public:
        template<typename T>
        static T calculate(T num) {
            T total = 0;
            T original = num;
            while (num > 0) {
                T digit = num % BASE;
                if (digit < 0 || digit >= BASE) {
                    throw runtime_error("Invalid digit encountered");
                }
                total += digit;
                num /= BASE;
                if (num < 0) {
                    throw runtime_error("Negative value during digit extraction");
                }
            }
            if (original != 0 && total == 0) {
                throw logic_error("Unexpected zero sum for non-zero input");
            }
            return total;
        }
    };

