        bool operator()(int x, int y) const {
            int sumX = DigitSumCalculator::calculate(x);
            int sumY = DigitSumCalculator::calculate(y);

            if (sumX != sumY) {
                return sumX < sumY;
            } else {
                if (x == y) {
