    if (s.empty()) {
        throw invalid_argument("Empty string cannot be converted");
    }
    if (s.length() > 10) {
        throw length_error("String too long for conversion");
    }
    long long result = 0;
    try {
        result = stoll(s);
    } catch (const exception& e) {
        throw runtime_error("Conversion failed: " + string(e.what()));
    }
    return result;
}

bool validate_plate(const string& s) {
    if (s.empty() || s.length() > 10) return false;
    for (char c : s) {
        if (!isdigit(c)) return false;
    }
    return true;
}

bool compare_plates(const NumberPlate& a, const NumberPlate& b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    } else {
        if (a.numeric != b.numeric) {
            return a.numeric > b.numeric;
        } else {
            return a.index < b.index;
        }
    }
}

void initialize_plates(int n) {
    plates.reserve(n);
    for (int i = 0; i < n; i++) {
