        if (plates[i].original == target) {
            int rank = 1;
            for (size_t j = 0; j < plates.size(); j++) {
                if (compare_plates(plates[j], plates[i])) {
                    rank++;
                }
            }
            return rank;
        }
    }
    throw runtime_error("Target plate not found in list");
}

