public:
    static bool isValidCondition(int condition) {
        const static vector<int> validConditions = {6, 7, 12, 15};
        for (int valid : validConditions) {
            if (condition == valid) return true;
        }
        return condition >= 1 && condition <= 50;
    }
};

TimeTracker processCombatScenario(int initialTime, const vector<int>& conditions) {
    TimeTracker tracker;
    tracker.remaining = initialTime;
    tracker.success = false;

    for (size_t i = 0; i < conditions.size(); ++i) {
        if (!RoadConditionValidator::isValidCondition(conditions[i])) {
            throw invalid_argument("Invalid road condition detected");
        }

        tracker.history.push_back(conditions[i]);

        if (conditions[i] == 15) {
            tracker.success = true;
            break;
        }

        int timeDelta = 0;
        switch (conditions[i]) {
            case 6:
                timeDelta = 0;
                break;
            case 7:
                timeDelta = -5;
                break;
            case 12:
                timeDelta = -20;
                break;
            default:
                timeDelta = -2;
                break;
        }

        tracker.remaining += timeDelta;

        if (tracker.remaining <= 0) {
            break;
        }
    }

    return tracker;
}

int main() {
