        int tempCondition;
        while (iss >> tempCondition) {
            conditions.push_back(tempCondition);
        }

        if (conditions.size() != initialTime) {
            throw runtime_error("Input condition count mismatch");
        }

        TimeTracker result = processCombatScenario(initialTime, conditions);

