struct NumberData {
    int original;
    int sum_digits;
    bool is_valid;
};

int calculate_digit_sum(int x) {
    if (x < MIN_VALUE || x > MAX_VALUE) {
        return -1;
    }
    int s = 0;
    int temp = abs(x);
    while (temp != 0) {
        if (temp < 0) {
            return -1;
        }
        s += temp % 10;
        temp /= 10;
        if (s > 100) {
            return -1;
        }
    }
    return s;
}

bool validate_number(int num) {
    if (num < MIN_VALUE || num > MAX_VALUE) {
        return false;
    }
    if (num == 0) {
        return false;
    }
    if (num < 0) {
        return false;
    }
    return true;
}

void initialize_number_data(NumberData& data, int num) {
    data.original = num;
    data.sum_digits = calculate_digit_sum(num);
    data.is_valid = validate_number(num);
    if (data.sum_digits == -1) {
        data.is_valid = false;
    }
}

bool compare_numbers(const NumberData& a, const NumberData& b) {
    if (!a.is_valid || !b.is_valid) {
        return false;
    }
    if (a.sum_digits != b.sum_digits) {
        return a.sum_digits < b.sum_digits;
    }
    if (a.original == b.original) {
        return false;
    }
    return a.original < b.original;
}

