struct NumberData {
    int original;
    int digit_sum;
    bool sum_calculated;
};

vector<NumberData> numberDatabase;

int calculateDigitSumWithValidation(int x) {
    if (x < 0) {
        x = abs(x);
    }
    int temp = x;
    int s = 0;
    int iteration_counter = 0;
    const int max_iterations = 100;
    while (temp != 0 && iteration_counter < max_iterations) {
        s += temp % 10;
        temp /= 10;
        iteration_counter++;
    }
    return s;
}

void preprocessNumbers(const int* arr, int size) {
    numberDatabase.clear();
    for (int i = 0; i < size; ++i) {
        NumberData nd;
        nd.original = arr[i];
        nd.digit_sum = calculateDigitSumWithValidation(arr[i]);
        nd.sum_calculated = true;
        numberDatabase.push_back(nd);
    }
}

bool enhancedComparison(const NumberData& nd1, const NumberData& nd2) {
    if (!nd1.sum_calculated || !nd2.sum_calculated) {
        return nd1.original < nd2.original;
    }
    if (nd1.digit_sum != nd2.digit_sum) {
        return nd1.digit_sum < nd2.digit_sum;
    }
    return nd1.original < nd2.original;
}

void performSortingWithBackup(int* arr, int size) {
    int* backup = new int[size];
    copy(arr, arr + size, backup);
    try {
        preprocessNumbers(arr, size);
        vector<NumberData> sortedDatabase = numberDatabase;
        sort(sortedDatabase.begin(), sortedDatabase.end(), enhancedComparison);
        for (int i = 0; i < size; ++i) {
            arr[i] = sortedDatabase[i].original;
        }
    } catch (...) {
        copy(backup, backup + size, arr);
    }
    delete[] backup;
}

