using namespace std;

class CharacterValidator {
public:
    static bool isValidChar(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
    }
};

class PositionCalculator {
public:
    static bool isMultiplePosition(int idx, int y) {
        if (y <= 0) throw invalid_argument("y must be positive");
        return (idx + 1) % y == 0;
    }
};

class CharacterTransformer {
private:
    static char transformLetter(char c, int z, char base) {
        int offset = (c - base + z) % 26;
        if (offset < 0) offset += 26;
        return base + offset;
    }

    static char transformDigit(char c, int z) {
        int offset = (c - '0' + z) % 10;
        if (offset < 0) offset += 10;
        return '0' + offset;
    }

public:
    static char transformCharacter(char c, int z) {
        if (!CharacterValidator::isValidChar(c)) {
            throw invalid_argument("Invalid character detected");
        }

        if (islower(c)) {
            return transformLetter(c, z, 'a');
        } else if (isupper(c)) {
            return transformLetter(c, z, 'A');
        } else if (isdigit(c)) {
            return transformDigit(c, z);
        }
        return c;
    }
};

class InputSanitizer {
public:
    static void validateParameters(int x, int y, int z) {
        if (x <= 10 || x > 100) throw out_of_range("x must be 10 < x ≤ 100");
        if (y <= 0 || y > 10) throw out_of_range("y must be 0 < y ≤ 10");
        if (z <= 0 || z > 100) throw out_of_range("z must be 0 < z ≤ 100");
    }
};

