        if (characters.size() != x) {
            throw runtime_error("Input length mismatch");
        }

        string result;
        for (int i = 0; i < characters.size(); ++i) {
            char current = characters[i];
            if (PositionCalculator::isMultiplePosition(i, y)) {
                try {
                    current = CharacterTransformer::transformCharacter(current, z);
                } catch (const invalid_argument& e) {
                    cerr << "Transformation error: " << e.what() << endl;
                    current = '?';
