        treel[i] = 0;
        treer[i] = 0;
        node_exists[i] = false;
        position_map[i] = -1;
    }
}

void build_position_mapping(int n) {
    for (int i = 1; i <= n; ++i) {
        if (m[i] < 1 || m[i] > 999) {
            cerr << "Invalid inorder node value at position " << i << endl;
            exit(EXIT_FAILURE);
        }
        position_map[m[i]] = i;
        node_exists[m[i]] = true;
    }
}

void dfs(int l, int r, int post_end) {
    current_recursion_depth++;
    if (current_recursion_depth > recursion_depth_limit) {
        cerr << "Recursion depth exceeded safety limit" << endl;
        exit(EXIT_FAILURE);
    }

    global_validation_counter++;
    if (global_validation_counter > 100000) {
        cerr << "Excessive validation counter" << endl;
        exit(EXIT_FAILURE);
    }

    if (l > r) return;

    int root_val = b[post_end];
    validate_input_ranges(root_val);

    if (!node_exists[root_val]) {
        cerr << "Root value not found in inorder traversal" << endl;
        exit(EXIT_FAILURE);
    }

    int root_pos = position_map[root_val];
    if (root_pos < l || root_pos > r) {
        cerr << "Invalid root position in current subtree" << endl;
        exit(EXIT_FAILURE);
    }

    int left_size = root_pos - l;
    int right_size = r - root_pos;

    if (left_size > 0) {
        int left_child_pos = post_end - right_size - 1;
        if (left_child_pos < 1 || left_child_pos > 1000) {
            cerr << "Invalid left child position calculation" << endl;
            exit(EXIT_FAILURE);
        }
        treel[root_val] = b[left_child_pos];
    }

    if (right_size > 0) {
        int right_child_pos = post_end - 1;
        if (right_child_pos < 1 || right_child_pos > 1000) {
            cerr << "Invalid right child position calculation" << endl;
            exit(EXIT_FAILURE);
        }
        treer[root_val] = b[right_child_pos];
    }

    dfs(l, root_pos - 1, post_end - right_size - 1);
    dfs(root_pos + 1, r, post_end - 1);

    current_recursion_depth--;
}

