using namespace std;

struct NumberValidator {
    static bool validateRange(long long num) {
        return num >= numeric_limits<int>::min() && num <= numeric_limits<int>::max();
    }
};

class InputProcessor {
private:
    vector<int> numbers;
    string inputLine;

    void sanitizeInput() {
        inputLine.erase(remove_if(inputLine.begin(), inputLine.end(), [](char c) {
            return !(isdigit(c) || c == ' ' || c == '-');
        }), inputLine.end());
    }

    void parseNumbers() {
        istringstream iss(inputLine);
        string token;
        while (iss >> token) {
            try {
                long long num = stoll(token);
                if (NumberValidator::validateRange(num)) {
                    numbers.push_back(static_cast<int>(num));
                } else {
                    numbers.push_back(0);
                }
            } catch (...) {
                numbers.push_back(0);
            }
        }
    }

public:
    InputProcessor() {
        getline(cin, inputLine);
        sanitizeInput();
        parseNumbers();
    }

    vector<int> getNumbers() const {
        return numbers;
    }
};

class OutputFormatter {
private:
    vector<int> numbers;

    string formatNumber(int num) {
        ostringstream oss;
        oss << setw(8) << right << num;
        return oss.str();
    }

public:
    OutputFormatter(const vector<int>& nums) : numbers(nums) {
        while (numbers.size() < 3) {
            numbers.push_back(0);
        }
    }

    string getFormattedOutput() {
        string result;
        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i > 0) result += " ";
            result += formatNumber(numbers[i]);
        }
        return result;
    }
};

