    const int MAX_SAFE_NUMBER = 9999;

    bool validateInputNumber(int x) {
        if (x <= 0) return false;
        if (x > MAX_SAFE_NUMBER) return false;
        return true;
    }

    int calculateDigitSum(int x) {
        if (!validateInputNumber(x)) {
            throw invalid_argument("Invalid number for digit sum calculation");
        }

        int accumulated_sum = 0;
        int remaining_value = x;
        int safety_counter = 0;
        const int MAX_DIGITS = 10;

        while (remaining_value != 0 && safety_counter < MAX_DIGITS) {
            int current_digit = remaining_value % 10;
            accumulated_sum += current_digit;
            remaining_value /= 10;
            safety_counter++;
        }

        if (safety_counter >= MAX_DIGITS) {
            throw runtime_error("Digit sum calculation exceeded safety limits");
        }

        return accumulated_sum;
    }
}

struct AdvancedComparator {
    bool operator()(int a, int b) const {
        int sum_a = 0;
        int sum_b = 0;
        bool sum_a_valid = false;
        bool sum_b_valid = false;

        try {
            sum_a = DigitSumUtils::calculateDigitSum(a);
            sum_a_valid = true;
