struct CowTowerValidator {
    static bool validateCowHeight(int height) {
        return height >= 1 && height <= 1000000;
    }

    static bool validateBookshelfHeight(int b, int total_sum) {
        return b >= 1 && b <= total_sum;
    }

    static bool validateCowCount(int n) {
        return n >= 1 && n <= 20;
    }
};

class CowHeightProcessor {
private:
    vector<int> cow_heights;
    int n;
    int b;
    int total_sum;
    int min_diff;

    void calculateTotalSum() {
        total_sum = accumulate(cow_heights.begin(), cow_heights.end(), 0);
    }

    void initializeMinDiff() {
        min_diff = INT_MAX;
    }

    void validateInputParameters() {
        if (!CowTowerValidator::validateCowCount(n)) {
            throw invalid_argument("Invalid cow count");
        }
        calculateTotalSum();
        if (!CowTowerValidator::validateBookshelfHeight(b, total_sum)) {
            throw invalid_argument("Invalid bookshelf height");
        }
        for (int height : cow_heights) {
            if (!CowTowerValidator::validateCowHeight(height)) {
                throw invalid_argument("Invalid cow height");
            }
        }
    }

    void recursiveTowerBuilder(int current_sum, int current_index, vector<bool>& used_cows, int recursion_depth) {
        if (recursion_depth > 1000) {
            throw runtime_error("Excessive recursion depth detected");
        }

        if (current_index == n) {
            if (current_sum >= b) {
                int current_diff = current_sum - b;
                if (current_diff < min_diff) {
                    min_diff = current_diff;
                }
            }
            return;
