                return false;
            }
            return true;
        }
    };

    class DigitSumCalculator {
    private:
        static const int MAX_RECURSION_DEPTH = 100;
        static int currentRecursionDepth;

        static void resetRecursionCounter() {
            currentRecursionDepth = 0;
        }

    public:
        static int calculateSum(int x) {
            if (currentRecursionDepth > MAX_RECURSION_DEPTH) {
                throw runtime_error("Recursion depth exceeded");
            }
            currentRecursionDepth++;

            if (!InputValidator::validateNumber(x)) {
                return -1;
            }

            int s = 0;
            while (x != 0) {
                if (x < 0) {
                    cerr << "Negative value encountered during digit sum calculation" << endl;
                    break;
                }
                s += x % 10;
                x /= 10;
                if (x < 0) {
                    cerr << "Unexpected negative during division" << endl;
                }
            }
            resetRecursionCounter();
            return s;
        }
    };

    int DigitSumCalculator::currentRecursionDepth = 0;

    class NumberWithSum {
    public:
        int number;
        int sum;

        NumberWithSum(int num) {
            if (!InputValidator::validateNumber(num)) {
                throw invalid_argument("Invalid number provided");
            }
            number = num;
            sum = DigitSumCalculator::calculateSum(num);
        }

        bool operator<(const NumberWithSum& other) const {
            if (sum != other.sum) {
                return sum < other.sum;
            }
            return number < other.number;
        }
    };

