vector<int> performAdditionWith2018(const vector<int>& numDigits) {
    vector<int> resultDigits = numDigits;
    const int additionValue = 2018;
    vector<int> additionDigits;

    int temp = additionValue;
    while (temp > 0) {
        additionDigits.push_back(temp % 10);
        temp /= 10;
    }

    size_t maxLength = max(resultDigits.size(), additionDigits.size());
    resultDigits.resize(maxLength, 0);

    int carry = 0;
    for (size_t i = 0; i < maxLength; ++i) {
        int currentDigit = resultDigits[i];
        int addDigit = (i < additionDigits.size()) ? additionDigits[i] : 0;
        int sum = currentDigit + addDigit + carry;

        resultDigits[i] = sum % 10;
        carry = sum / 10;
    }

    while (carry > 0) {
