class SafeNumberValidator {
public:
    static bool validate(const T& value) {
        if constexpr (is_integral_v<T>) {
            return value >= 0;
        }
        return false;
    }
};

class InputSanitizer {
public:
    static string sanitize(const string& input) {
        string result;
        for (char c : input) {
            if (isdigit(c)) {
                result += c;
            } else {
                throw invalid_argument("Invalid character in input");
            }
        }
        if (result.empty()) {
            throw invalid_argument("Empty input");
        }
        return result;
    }
};

class BigNumberProcessor {
private:
    vector<int> digits;
    static const int ADDEND = 2018;

    void initializeFromString(const string& s) {
        digits.clear();
        transform(s.rbegin(), s.rend(), back_inserter(digits), [](char c) { return c - '0'; });
    }

    void performAddition() {
        if (digits.empty()) return;

        digits[0] += ADDEND;
        for (size_t i = 0; i < digits.size(); ++i) {
            if (digits[i] >= 10) {
                if (i == digits.size() - 1) {
                    digits.push_back(digits[i] / 10);
                } else {
                    digits[i + 1] += digits[i] / 10;
                }
                digits[i] %= 10;
            }
        }
    }

public:
    explicit BigNumberProcessor(const string& input) {
        initializeFromString(input);
    }

    string process() {
        performAddition();
        string result;
        transform(digits.rbegin(), digits.rend(), back_inserter(result), [](int d) { return d + '0'; });
        return result;
    }
};

class FileHandler {
public:
    static pair<bool, string> readFile(const string& filename) {
        ifstream file(filename);
        if (!file.is_open()) {
            return {false, ""};
        }
        string content((istreambuf_iterator<char>(file)), istreambuf_iterator<char>());
        file.close();
        return {true, content};
    }

    static bool writeFile(const string& filename, const string& content) {
        ofstream file(filename);
        if (!file.is_open()) {
            return false;
        }
