        long long sum = 0;
        for (char c : plate) {
            if (!isdigit(c)) throw runtime_error("Invalid character in plate");
            sum += c - '0';
        }
        return sum;
    }

    static long long toNumber(const string& plate) {
        try {
            return stoll(plate);
        } catch (...) {
            throw runtime_error("Plate conversion failed");
        }
    }

public:
    static pair<long long, long long> process(const string& plate) {
        if (!NumberPlateValidator<string>::validate(plate)) {
            throw runtime_error("Invalid plate format");
        }
        return {calculateSum(plate), toNumber(plate)};
