#include <bits/stdc++.h>
#include <stdexcept>
#include <limits>
using namespace std;

struct NumberPlateInfo {
    string original;
    long long numericValue;
    int digitSum;
    int originalIndex;
};

vector<NumberPlateInfo> plateDatabase;
unordered_map<string, int> plateLookupTable;

long long convertToNumber(const string& s) {
    if (s.empty()) return 0;
    long long value = 0;
    try {
        value = stoll(s);
    } catch (const invalid_argument& ia) {
        value = 0;
    } catch (const out_of_range& oor) {
        value = numeric_limits<long long>::max();
    }
    return value;
}

int calculateDigitSum(long long x) {
    if (x < 0) x = -x;
    int s = 0;
    while (x != 0) {
        s += x % 10;
        x = x / 10;
    }
    return s;
}

bool comparePlates(const NumberPlateInfo& a, const NumberPlateInfo& b) {
    if (a.digitSum != b.digitSum) {
        return a.digitSum < b.digitSum;
    }
    if (a.numericValue != b.numericValue) {
        return a.numericValue > b.numericValue;
    }
    return a.originalIndex < b.originalIndex;
}

void initializeDatabase(const vector<string>& plates) {
    plateDatabase.clear();
    plateLookupTable.clear();
    for (size_t i = 0; i < plates.size(); ++i) {
        NumberPlateInfo info;
        info.original = plates[i];
        info.numericValue = convertToNumber(plates[i]);
        info.digitSum = calculateDigitSum(info.numericValue);
        info.originalIndex = i;
        plateDatabase.push_back(info);
        plateLookupTable[plates[i]] = i;
    }
}

int determineClaimPosition(const string& targetPlate) {
    auto it = plateLookupTable.find(targetPlate);
    if (it == plateLookupTable.end()) {
        return -1;
    }
    int targetIndex = it->second;
    vector<NumberPlateInfo> sortedDatabase = plateDatabase;
    sort(sortedDatabase.begin(), sortedDatabase.end(), comparePlates);
    for (size_t i = 0; i < sortedDatabase.size(); ++i) {
        if (sortedDatabase[i].originalIndex == targetIndex) {
            return i + 1;
        }
    }
    return -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n;
    cin >> n;
    if (n < 1 || n > 10000) {
        cout << 1 << endl;
        return 0;
    }

    vector<string> plates(n);
    for (int i = 0; i < n; ++i) {
        cin >> plates[i];
        if (plates[i].size() > 10) {
            plates[i] = plates[i].substr(0, 10);
        }
    }

    string targetPlate = plates.back();
    initializeDatabase(plates);
    int position = determineClaimPosition(targetPlate);

    if (position != -1) {
        cout << position << endl;
    } else {
        cout << 1 << endl;
    }

    return 0;
}
