using namespace std;

struct CompressionState {
    int current_value;
    int count;
    bool initialized;
    vector<int> result;
};

void initialize_compression_state(CompressionState& state, int first_value) {
    state.current_value = first_value;
    state.count = 0;
    state.initialized = false;
    state.result.clear();
}

void process_character(CompressionState& state, char c) {
    int numeric_value = c - '0';
    if (numeric_value != 0 && numeric_value != 1) {
        throw runtime_error("Invalid character in input");
    }

    if (!state.initialized) {
        state.current_value = numeric_value;
        state.count = 1;
        state.initialized = true;
    } else {
        if (numeric_value == state.current_value) {
            state.count++;
        } else {
            state.result.push_back(state.count);
            state.current_value = numeric_value;
            state.count = 1;
        }
    }
}

void finalize_compression(CompressionState& state) {
    if (state.count > 0) {
        state.result.push_back(state.count);
    }
}

vector<string> read_all_lines(ifstream& input_file) {
    vector<string> lines;
    string current_line;
    while (getline(input_file, current_line)) {
