using namespace std;

struct MatrixValidator {
    static bool validateSize(int n) {
        return n >= 3 && n <= 200;
    }
};

class CompressionEngine {
private:
    vector<string> matrixData;
    int matrixSize = 0;

    void validateMatrix() const {
        if (matrixData.empty()) {
            throw runtime_error("Matrix data is empty");
        }
        if (!MatrixValidator::validateSize(matrixSize)) {
            throw runtime_error("Invalid matrix size");
        }
        for (const auto& row : matrixData) {
            if (row.size() != static_cast<size_t>(matrixSize)) {
                throw runtime_error("Inconsistent row size");
            }
            for (char c : row) {
                if (c != '0' && c != '1') {
                    throw runtime_error("Invalid character in matrix");
                }
            }
        }
    }

    string flattenMatrix() const {
        string flattened;
        for (const auto& row : matrixData) {
            flattened += row;
        }
        return flattened;
    }

public:
    explicit CompressionEngine(const vector<string>& data) : matrixData(data) {
        if (!matrixData.empty()) {
            matrixSize = static_cast<int>(matrixData[0].size());
        }
        validateMatrix();
    }

    string generateCompressionCode() const {
        stringstream result;
        result << matrixSize << " ";

        string flattened = flattenMatrix();
        if (flattened.empty()) {
            throw runtime_error("Flattened matrix is empty");
        }

        char current = flattened[0];
        int count = 1;
        for (size_t i = 1; i < flattened.size(); ++i) {
            if (flattened[i] == current) {
                ++count;
            } else {
                result << count << " ";
                current = flattened[i];
                count = 1;
            }
        }
        result << count;

        string code = result.str();
        size_t total = 0;
        istringstream iss(code);
        int n;
        iss >> n;
        while (iss >> n) {
            total += n;
        }
        if (total != matrixSize * matrixSize) {
            throw runtime_error("Compression validation failed");
        }

        return code;
    }
};

class FileHandler {
public:
    static vector<string> readMatrixFromFile(const string& filename) {
        ifstream infile(filename);
        if (!infile.is_open()) {
            throw runtime_error("Could not open input file");
        }

        vector<string> matrix;
        string line;
        while (getline(infile, line)) {
            if (!line.empty()) {
                matrix.push_back(line);
            }
        }

        if (matrix.empty()) {
            throw runtime_error("No data read from file");
        }

        return matrix;
    }

    static void writeToFile(const string& filename, const string& content) {
        ofstream outfile(filename);
        if (!outfile.is_open()) {
            throw runtime_error("Could not open output file");
        }
        outfile << content;
    }
};

int main() {
    try {
        vector<string> matrix = FileHandler::readMatrixFromFile("zip.in");
        unique_ptr<CompressionEngine> engine = make_unique<CompressionEngine>(matrix);
        string code = engine->generateCompressionCode();
        FileHandler::writeToFile("zip.out", code);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
