template<typename T>
T safe_divide(T numerator, T denominator) {
    if (denominator == 0) {
        throw std::runtime_error("Division by zero detected");
    }
    if (std::is_floating_point<T>::value && 
        (std::isinf(numerator) || std::isinf(denominator)) {
        throw std::overflow_error("Floating point overflow detected");
    }
    return numerator / denominator;
}

template<typename T>
T ceil_with_precision(T value) {
    constexpr T epsilon = std::numeric_limits<T>::epsilon();
    T integral_part;
    T fractional_part = std::modf(value, &integral_part);
    if (std::abs(fractional_part) > epsilon) {
        return integral_part + 1;
    }
    return integral_part;
}

