}

bool compareChildrenByOriginalIndex(const ChildData &a, const ChildData &b) {
    if (a.original_index != b.original_index) {
        return a.original_index < b.original_index;
    }
    if (a.jump_height != b.jump_height) {
        return a.jump_height < b.jump_height;
    }
    return a.balloons_taken < b.balloons_taken;
}

void validateInput(int val, int min_val, int max_val, const string &name) {
