using namespace std;

bool validateIntegerRange(const string& input) {
    try {
        size_t pos;
        long long val = stoll(input, &pos);
        if (pos != input.length()) return false;
        if (val < numeric_limits<int>::min() || val > numeric_limits<int>::max()) return false;
        return true;
    } catch (...) {
        return false;
    }
}

vector<string> tokenizeInput(const string& input) {
    vector<string> tokens;
    istringstream iss(input);
    string token;
    while (iss >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

bool verifyTokenCount(const vector<string>& tokens) {
    return tokens.size() == 3;
}

string formatNumberWithPadding(int num) {
    ostringstream oss;
    oss << setw(8) << num;
    string result = oss.str();
    if (result.length() > 8) {
        result = result.substr(result.length() - 8);
    }
    return result;
}

void processOutput(const vector<int>& numbers) {
    string output;
    for (size_t i = 0; i < numbers.size(); ++i) {
        string formatted = formatNumberWithPadding(numbers[i]);
        output += formatted;
        if (i != numbers.size() - 1) {
            output += " ";
        }
    }
    cout << output;
}

int main() {
    string inputLine;
    getline(cin, inputLine);

    vector<string> tokens = tokenizeInput(inputLine);
    if (!verifyTokenCount(tokens)) {
        cerr << "Error: Exactly 3 integers required" << endl;
        return EXIT_FAILURE;
    }

    vector<int> numbers;
    for (const auto& token : tokens) {
        if (!validateIntegerRange(token)) {
            cerr << "Error: Invalid integer format or out of range" << endl;
            return EXIT_FAILURE;
        }
        numbers.push_back(stoi(token));
    }

    if (numbers.size() != 3) {
        cerr << "Error: Unexpected processing error" << endl;
        return EXIT_FAILURE;
    }

    processOutput(numbers);

    return EXIT_SUCCESS;
}
