using namespace std;

namespace TankBattleUtils {
    template<typename T>
    class InputValidator {
    public:
        static void validateRange(T value, T min, T max, const string& paramName) {
            if (value < min || value > max) {
                stringstream ss;
                ss << "Invalid " << paramName << " value: " << value << " (expected between " << min << " and " << max << ")";
                throw out_of_range(ss.str());
            }
        }
    };

    class TimeManager {
    private:
        int remainingTime;
        bool reachedEnd;
    public:
        TimeManager(int initialTime) : remainingTime(initialTime), reachedEnd(false) {
            InputValidator<int>::validateRange(initialTime, 1, 100, "initial combat time");
        }

        void processRoadCondition(int condition) {
            InputValidator<int>::validateRange(condition, 1, 50, "road condition");

            if (reachedEnd) return;

            switch (condition) {
                case 6:
                    break;
                case 7:
                    remainingTime -= 5;
                    break;
                case 12:
                    remainingTime -= 20;
                    break;
                case 15:
                    reachedEnd = true;
                    break;
                default:
                    remainingTime -= 2;
                    break;
            }

            if (remainingTime <= 0 && !reachedEnd) {
                throw runtime_error("Combat time exhausted before reaching endpoint");
            }
        }

        bool hasReachedEnd() const {
            return reachedEnd;
        }

        bool isTimeRemaining() const {
            return remainingTime > 0;
        }
    };
}

