            vector<QueueNode> new_queue(new_capacity);
            for (int i = 0; i < size; ++i) {
                new_queue[i] = queue[(head + i) % capacity];
            }
            queue = move(new_queue);
            head = 0;
            tail = size;
            capacity = new_capacity;
