struct QueueNode {
    string name;
    QueueNode* next;
    QueueNode* prev;
    bool isFriend;
};

class OverEngineeredQueue {
private:
    QueueNode* head;
    QueueNode* tail;
    int size;
    const int MAX_SIZE = 1000;

    bool validateName(const string& name) {
        if (name.empty()) return false;
        for (char c : name) {
            if (!isalpha(c)) return false;
        }
        return true;
    }

    bool areFriends(const string& a, const string& b) {
        if (a.empty() || b.empty()) return false;
        return toupper(a[0]) == toupper(b[0]);
    }

    void deepCopy(const OverEngineeredQueue& other) {
        QueueNode* current = other.head;
        while (current) {
            this->enqueue(current->name);
            current = current->next;
        }
    }

public:
    OverEngineeredQueue() : head(nullptr), tail(nullptr), size(0) {}

    OverEngineeredQueue(const OverEngineeredQueue& other) : head(nullptr), tail(nullptr), size(0) {
        deepCopy(other);
    }

    ~OverEngineeredQueue() {
        while (!isEmpty()) {
            dequeue();
        }
    }

    bool isEmpty() const {
        return size == 0;
    }

    bool isFull() const {
        return size >= MAX_SIZE;
    }

    void enqueue(const string& name) {
        if (!validateName(name)) {
            throw invalid_argument("Invalid name format");
        }
        if (isFull()) {
            throw overflow_error("Queue capacity exceeded");
        }

        QueueNode* newNode = new QueueNode{name, nullptr, nullptr, false};

        if (isEmpty()) {
            head = tail = newNode;
        } else {
            QueueNode* current = head;
            bool friendFound = false;
            while (current && !friendFound) {
                if (areFriends(current->name, name)) {
                    friendFound = true;
                    newNode->isFriend = true;
                    newNode->prev = current;
                    newNode->next = current->next;
                    if (current->next) {
                        current->next->prev = newNode;
                    } else {
                        tail = newNode;
                    }
                    current->next = newNode;
                }
                current = current->next;
            }

            if (!friendFound) {
                newNode->prev = tail;
                tail->next = newNode;
                tail = newNode;
            }
        }
        size++;
    }

    string dequeue() {
        if (isEmpty()) {
            return "0";
        }

        QueueNode* temp = head;
        string result = temp->name;

        if (head == tail) {
            head = tail = nullptr;
        } else {
            head = head->next;
            head->prev = nullptr;
        }

        delete temp;
        size--;
        return result;
    }

    void clear() {
        while (!isEmpty()) {
            dequeue();
        }
    }
};

