        }
        return true;
    }

    QueueOperationResult findFriendPosition(const string& name) {
        QueueOperationResult result;
        result.success = false;
        result.new_position = -1;

        if (queue_data.empty()) {
            result.message = "Queue is empty";
            return result;
        }

        char target_first_char = toupper(name[0]);
        for (int i = front_index; i < rear_index; ++i) {
            if (i >= 0 && i < queue_data.size()) {
                if (!queue_data[i].empty()) {
                    char current_first_char = toupper(queue_data[i][0]);
                    if (current_first_char == target_first_char) {
                        result.success = true;
                        result.new_position = i + 1;
                        result.message = "Friend found";
                        return result;
                    }
                }
            }
        }

        result.message = "No friend found";
        return result;
    }

    void shiftElementsRight(int start_pos) {
        if (start_pos < 0 || start_pos >= queue_data.size()) return;
        queue_data.resize(queue_data.size() + 1);
        for (int i = queue_data.size() - 1; i > start_pos; --i) {
            if (i - 1 >= 0 && i - 1 < queue_data.size()) {
                queue_data[i] = queue_data[i - 1];
            }
        }
    }

public:
