        queue_data.reserve(capacity);
    }

    QueueOperationResult enqueue(const string& name) {
        QueueOperationResult result;
        result.success = false;

        if (!validateName(name)) {
            result.message = "Invalid name format";
            return result;
        }

        if (rear_index >= max_capacity) {
            result.message = "Queue capacity exceeded";
            return result;
        }

        QueueOperationResult friend_result = findFriendPosition(name);
        if (friend_result.success) {
            int insert_pos = friend_result.new_position;
            if (insert_pos >= 0 && insert_pos <= queue_data.size()) {
                shiftElementsRight(insert_pos);
                queue_data[insert_pos] = name;
                rear_index++;
                result.success = true;
                result.message = "Inserted behind friend";
                result.new_position = insert_pos;
            } else {
                result.message = "Invalid friend position";
            }
        } else {
