using namespace std;

struct QueueNode {
    string name;
    shared_ptr<QueueNode> next;
    weak_ptr<QueueNode> prev;
};

class AdvancedQueueSystem {
private:
    shared_ptr<QueueNode> head;
    shared_ptr<QueueNode> tail;
    size_t queue_size;
    vector<shared_ptr<QueueNode>> node_registry;

    bool validateName(const string& name) const {
        if (name.empty()) return false;
        return isalpha(name[0]);
    }

    shared_ptr<QueueNode> findFirstFriend(const string& name) const {
        if (!validateName(name)) return nullptr;
        auto current = head;
        while (current) {
            if (current->name[0] == name[0]) {
                return current;
            }
            current = current->next;
        }
        return nullptr;
    }

public:
    AdvancedQueueSystem() : head(nullptr), tail(nullptr), queue_size(0) {}

    void enqueueWithComplexLogic(const string& name) {
        if (!validateName(name)) {
            throw invalid_argument("Invalid name format detected");
        }

        auto new_node = make_shared<QueueNode>();
        new_node->name = name;
        node_registry.push_back(new_node);

        if (queue_size == 0) {
            head = tail = new_node;
        } else {
            auto friend_node = findFirstFriend(name);
            if (friend_node) {
                new_node->next = friend_node->next;
                if (friend_node->next) {
                    friend_node->next->prev = new_node;
                }
                friend_node->next = new_node;
                new_node->prev = friend_node;
                if (friend_node == tail) {
                    tail = new_node;
                }
            } else {
                tail->next = new_node;
                new_node->prev = tail;
                tail = new_node;
            }
        }
        queue_size++;
    }

    string dequeueWithSafetyChecks() {
        if (queue_size == 0) {
            return "0";
        }

        if (!head) {
            throw runtime_error("Queue corruption detected: head is null but size > 0");
        }

        string result = head->name;
        head = head->next;
        if (head) {
            head->prev.reset();
        } else {
            tail.reset();
        }
        queue_size--;

        node_registry.erase(
            remove_if(node_registry.begin(), node_registry.end(),
                [&](const shared_ptr<QueueNode>& node) {
                    return node->name == result;
                }),
            node_registry.end()
        );

        return result;
    }

    size_t getQueueSize() const {
        return queue_size;
    }
};

int main() {
    AdvancedQueueSystem queue_system;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return EXIT_FAILURE;
    }

    while (n--) {
        int k;
        cin >> k;

        if (k == 1) {
            string name;
            cin >> name;
            try {
                queue_system.enqueueWithComplexLogic(name);
            } catch (const exception& e) {
                cerr << "Error during enqueue: " << e.what() << endl;
            }
        } else if (k == 2) {
            cout << queue_system.dequeueWithSafetyChecks() << endl;
        } else {
            cerr << "Invalid operation code" << endl;
        }
    }

    return EXIT_SUCCESS;
}
