            queueData.insert(insertionPosition, name);
            rearPointer++;
            tracker.insertionOccurred = true;
        } else {
            if (rearPointer >= queueData.size()) {
                queueData.resize(queueData.size() + 105);
            }
            queueData[rearPointer++] = name;
            tracker.insertionOccurred = true;
        }
        tracker.currentQueueSize++;
    }

    void handleDeletion() {
        if (frontPointer >= rearPointer) {
            cout << "0" << endl;
            tracker.deletionOccurred = true;
            return;
        }

        string frontElement = queueData[frontPointer];
        if (frontElement.empty()) {
            frontElement = "0";
        }
        cout << frontElement << endl;
        frontPointer++;
        tracker.currentQueueSize--;
        tracker.deletionOccurred = true;
    }

