        tracker.operationPerformed = false;
        tracker.insertionOccurred = false;
        tracker.deletionOccurred = false;
        tracker.currentQueueSize = 0;
        queueData.resize(105);
    }

    void processOperation(int operationType, string name = "") {
        tracker.operationPerformed = false;
        tracker.insertionOccurred = false;
        tracker.deletionOccurred = false;

        try {
            validateOperation(operationType);
            if (operationType == 1) {
                handleInsertion(name);
            } else {
                handleDeletion();
            }
            tracker.operationPerformed = true;
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
        }
    }
};

