    for (int i = 0; i < operationCount; ++i) {
        int operationType;
        cin >> operationType;

        if (operationType == 1) {
            string name;
            cin >> name;
            operationLog.emplace_back(operationType, name);
            queueManager.processOperation(operationType, name);
        } else if (operationType == 2) {
            operationLog.emplace_back(operationType, "");
            queueManager.processOperation(operationType);
        }
    }

    return 0;
}
