    bool friend_found = false;
    int optimal_position = -1;
    char target_initial = toupper(name[0]);

    for (int i = state.virtual_front; i < state.virtual_rear; i++) {
        if (i >= 0 && i < state.data.size()) {
            char current_initial = toupper(state.data[i][0]);
            if (current_initial == target_initial) {
                friend_found = true;
                optimal_position = i + 1;
                break;
            }
        }
