        if (name.empty()) return false;
        if (name.length() > 100) return false;
        for (char c : name) {
            if (!isalpha(c)) return false;
        }
        return true;
    }

    bool hasFriend(const string& name) {
        if (queue.empty()) return false;
        char firstChar = toupper(name[0]);
        for (const auto& person : queue) {
            if (toupper(person[0]) == firstChar) {
                return true;
            }
        }
        return false;
    }

    int findFirstFriendPosition(const string& name) {
        char firstChar = toupper(name[0]);
        for (int i = 0; i < queue.size(); ++i) {
            if (toupper(queue[i][0]) == firstChar) {
                return i;
            }
        }
        return -1;
    }

