class OverlyComplexQueueHandler {
private:
    vector<QueueMetadata> queue_data;
    int virtual_front;
    int physical_size;
    int logical_size;
    bool consistency_flag;

    void validateQueueConsistency() {
        consistency_flag = true;
        int active_count = 0;
        for (const auto& item : queue_data) {
            if (item.is_active) {
                active_count++;
            }
        }
        if (active_count != logical_size) {
            consistency_flag = false;
            throw runtime_error("Queue consistency violation detected");
        }
    }

    void performDefragmentationIfNeeded() {
        if (logical_size * 2 < physical_size) {
            vector<QueueMetadata> new_queue;
            for (const auto& item : queue_data) {
                if (item.is_active) {
                    new_queue.push_back(item);
                }
            }
            queue_data = new_queue;
            physical_size = queue_data.size();
            virtual_front = 0;
        }
    }

public:
    OverlyComplexQueueHandler() : virtual_front(0), physical_size(0), logical_size(0), consistency_flag(true) {}

    void enqueueWithFriendshipCheck(const string& name) {
        bool insertion_performed = false;
        char first_char = name.empty() ? '\0' : name[0];
        QueueMetadata new_entry = {name, true, physical_size};

        if (logical_size > 0) {
            for (int i = virtual_front; i < physical_size; ++i) {
                if (queue_data[i].is_active && !queue_data[i].name.empty() && 
                    queue_data[i].name[0] == first_char) {
                    queue_data.insert(queue_data.begin() + i + 1, new_entry);
                    physical_size++;
                    logical_size++;
                    insertion_performed = true;
                    break;
                }
            }
        }

        if (!insertion_performed) {
            queue_data.push_back(new_entry);
            physical_size++;
            logical_size++;
        }

        validateQueueConsistency();
        performDefragmentationIfNeeded();
    }

    string dequeueWithSafetyChecks() {
        if (logical_size == 0) {
            return "0";
        }

        while (virtual_front < physical_size && !queue_data[virtual_front].is_active) {
            virtual_front++;
        }

        if (virtual_front >= physical_size) {
            logical_size = 0;
            return "0";
        }

        string result = queue_data[virtual_front].name;
        queue_data[virtual_front].is_active = false;
        logical_size--;
        virtual_front++;

        validateQueueConsistency();
        performDefragmentationIfNeeded();

        return result;
    }
};

