#include <iostream>
#include <stdexcept>
#include <vector>
#include <algorithm>
using namespace std;

struct CharacterData {
    char original;
    bool shouldTransform;
    char transformed;
};

class CharacterValidator {
public:
    static bool isValidCharacter(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
    }
};

class CharacterTransformer {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;
    int shiftAmount;

    char transformLowerCase(char c) {
        int normalized = c - 'a';
        int shifted = (normalized + shiftAmount) % ALPHABET_SIZE;
        if(shifted < 0) shifted += ALPHABET_SIZE;
        return static_cast<char>(shifted + 'a');
    }

    char transformUpperCase(char c) {
        int normalized = c - 'A';
        int shifted = (normalized + shiftAmount) % ALPHABET_SIZE;
        if(shifted < 0) shifted += ALPHABET_SIZE;
        return static_cast<char>(shifted + 'A');
    }

    char transformDigit(char c) {
        int normalized = c - '0';
        int shifted = (normalized + shiftAmount) % DIGIT_SIZE;
        if(shifted < 0) shifted += DIGIT_SIZE;
        return static_cast<char>(shifted + '0');
    }

public:
    explicit CharacterTransformer(int z) : shiftAmount(z) {
        if(z <= 0) {
            throw invalid_argument("Shift amount must be positive");
        }
    }

    char transformCharacter(char c) {
        if(!CharacterValidator::isValidCharacter(c)) {
            return c;
        }

        if(c >= 'a' && c <= 'z') {
            return transformLowerCase(c);
        } else if(c >= 'A' && c <= 'Z') {
            return transformUpperCase(c);
        } else if(c >= '0' && c <= '9') {
            return transformDigit(c);
        }

        return c;
    }
};

class InputProcessor {
private:
    int x, y, z;
    vector<CharacterData> characterCollection;

    void validateInputParameters() {
        if(x <= 10 || x > 100) {
            throw out_of_range("x must be between 11 and 100");
        }
        if(y <= 0 || y > 10) {
            throw out_of_range("y must be between 1 and 10");
        }
        if(z <= 0 || z > 100) {
            throw out_of_range("z must be between 1 and 100");
        }
    }

public:
    void readInput() {
        cin >> x >> y >> z;
        validateInputParameters();

        characterCollection.reserve(x);
        for(int position = 0; position < x; ++position) {
            char currentChar;
            cin >> currentChar;

            bool needsTransformation = (position + 1) % y == 0;
            characterCollection.push_back({currentChar, needsTransformation, '\0'});
        }
    }

    void processCharacters() {
        CharacterTransformer transformer(z);
        for(auto& data : characterCollection) {
            if(data.shouldTransform) {
                data.transformed = transformer.transformCharacter(data.original);
            } else {
                data.transformed = data.original;
            }
        }
    }

    void displayResult() {
        for(const auto& data : characterCollection) {
            cout << data.transformed;
        }
    }
};

int main() {
    try {
        InputProcessor processor;
        processor.readInput();
        processor.processCharacters();
        processor.displayResult();
    } catch(const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
