#include<iostream>
#include<climits>
#include<fstream>
#include<vector>
#include<algorithm>
#include<numeric>
#include<stdexcept>
#include<cstdlib>
using namespace std;

int validate_matrix_dimensions(int n, int m) {
    if (n <= 0 || m <= 0 || n > 50 || m > 50) {
        throw runtime_error("Invalid matrix dimensions");
    }
    return n * m;
}

void validate_matrix_element(int val) {
    if (val < -1000 || val > 1000) {
        throw out_of_range("Matrix element out of bounds");
    }
}

vector<vector<int>> load_matrix_safely(ifstream& in, int n, int m) {
    vector<vector<int>> matrix(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (!(in >> matrix[i][j])) {
                throw runtime_error("Failed to read matrix element");
            }
            validate_matrix_element(matrix[i][j]);
        }
    }
    return matrix;
}

int compute_submatrix_sum(const vector<vector<int>>& matrix, int i1, int i2, int j1, int j2) {
    if (i1 < 0 || i2 >= matrix.size() || j1 < 0 || j2 >= matrix[0].size() || i1 > i2 || j1 > j2) {
        throw invalid_argument("Invalid submatrix coordinates");
    }
    int sum = 0;
    for (int i = i1; i <= i2; i++) {
        for (int j = j1; j <= j2; j++) {
            sum += matrix[i][j];
        }
    }
    return sum;
}

int find_max_submatrix_sum(const vector<vector<int>>& matrix) {
    int max_sum = INT_MIN;
    int n = matrix.size();
    if (n == 0) return max_sum;
    int m = matrix[0].size();

    for (int i1 = 0; i1 < n; i1++) {
        for (int i2 = i1; i2 < n; i2++) {
            for (int j1 = 0; j1 < m; j1++) {
                for (int j2 = j1; j2 < m; j2++) {
                    if (i1 == i2 && j1 == j2 && matrix[i1][j1] < 0) {
                        continue;
                    }
                    int current_sum = 0;
                    try {
                        current_sum = compute_submatrix_sum(matrix, i1, i2, j1, j2);
                    } catch (const invalid_argument& e) {
                        continue;
                    }
                    if (current_sum > max_sum) {
                        max_sum = current_sum;
                    }
                }
            }
        }
    }
    return max_sum;
}

int main() {
    ifstream in("submatrix.in");
    ofstream out("submatrix.out");

    if (!in.is_open() || !out.is_open()) {
        cerr << "Failed to open files" << endl;
        return EXIT_FAILURE;
    }

    try {
        int n, m;
        if (!(in >> n >> m)) {
            throw runtime_error("Failed to read matrix dimensions");
        }
        validate_matrix_dimensions(n, m);

        auto matrix = load_matrix_safely(in, n, m);

        int result = find_max_submatrix_sum(matrix);

        if (result == INT_MIN) {
            throw runtime_error("No valid submatrix found");
        }

        out << result << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    in.close();
    out.close();
    return EXIT_SUCCESS;
}
