constexpr bool is_safe_multiply(T a, T b) {
    return (a == 0) || (b == 0) || (numeric_limits<T>::max() / abs(a) >= abs(b));
}

template<typename T>
constexpr bool is_safe_add(T a, T b) {
    return ((b > 0) && (a <= numeric_limits<T>::max() - b)) || 
           ((b < 0) && (a >= numeric_limits<T>::min() - b));
}

struct StoneSafetyValidator {
    static void validate_stone_attributes(int anger, int irritability) {
        if (anger == numeric_limits<int>::min() || irritability == numeric_limits<int>::min()) {
            throw underflow_error("Stone attribute at minimum limit");
        }
        if (anger == numeric_limits<int>::max() || irritability == numeric_limits<int>::max()) {
            throw overflow_error("Stone attribute at maximum limit");
        }
    }
};

class StoneCombinationAnalyzer {
private:
    vector<pair<int, int>> stones;
    int global_min_diff;
    bool initialized;

    void recursive_analyzer(size_t index, int current_count, int sum_irritability, int product_anger) {
        if (index == stones.size()) {
            if (current_count > 0) {
                if (!is_safe_add<int>(product_anger, -sum_irritability)) {
                    throw overflow_error("Difference calculation would overflow");
                }
                int current_diff = abs(product_anger - sum_irritability);
                if (!initialized || current_diff < global_min_diff) {
                    global_min_diff = current_diff;
                    initialized = true;
                }
            }
            return;
        }

