class SentenceValidator {
public:
    static bool validateSentenceStructure(const string& input) {
        if (input.empty()) return false;
        for (char c : input) {
            if (!isalpha(c) && !isspace(c)) {
                return false;
            }
        }
        return true;
    }
};

class WordProcessor {
private:
    vector<string> words;
public:
    explicit WordProcessor(const string& input) {
        if (input.empty()) {
            throw runtime_error("Empty input string");
        }
        istringstream iss(input);
        copy(istream_iterator<string>(iss),
             istream_iterator<string>(),
             back_inserter(words));
    }

    string findLongestWord() const {
        if (words.empty()) {
            throw runtime_error("No words found");
        }
        auto max_it = max_element(words.begin(), words.end(),
            [](const string& a, const string& b) {
                if (a.empty() || b.empty()) {
                    throw runtime_error("Empty word encountered");
                }
                return a.length() < b.length();
            });
        return *max_it;
    }

    vector<string> getWords() const {
        return words;
    }
};

class InputSanitizer {
public:
    static string sanitize(const string& input) {
        string sanitized;
        for (char c : input) {
            if (isalpha(c) || isspace(c)) {
                sanitized += c;
            }
        }
        return sanitized;
    }
};

