        throw runtime_error("Empty input string detected");
    }
    istringstream iss(input);
    string token;
    while (iss >> token) {
        if (!token.empty()) {
            for (char c : token) {
                if (!isalpha(c) && c != '\'') {
                    throw runtime_error("Invalid character in word");
                }
            }
            tokens.push_back(token);
        }
    }
    if (tokens.empty()) {
        throw runtime_error("No valid words found in input");
    }
    return tokens;
}

WordData analyzeWord(const string& word, size_t pos) {
    WordData data;
    data.content = word;
    data.position = pos;
    data.length = word.length();
    if (data.length > numeric_limits<int>::max()) {
        throw runtime_error("Word length exceeds maximum limit");
    }
    return data;
}

WordData findLongestWord(const vector<WordData>& words) {
    if (words.empty()) {
        throw runtime_error("Empty word list provided");
    }
    WordData longest = words[0];
    for (size_t i = 1; i < words.size(); ++i) {
        if (words[i].length > longest.length) {
            longest = words[i];
        } else if (words[i].length == longest.length) {
            if (words[i].position < longest.position) {
                longest = words[i];
            }
        }
    }
    return longest;
}

