template<typename T>
void validateInputRange(const T& value) {
    if (!std::is_integral<T>::value) {
        throw std::invalid_argument("Input must be an integer");
    }
    if (value < std::numeric_limits<int>::min() || value > std::numeric_limits<int>::max()) {
        throw std::out_of_range("Input out of int range");
    }
}

template<typename T>
std::string formatWithPadding(T value) {
    std::ostringstream oss;
    if (sizeof(value) > sizeof(int)) {
        oss << std::setw(8) << "ERROR";
    } else {
        oss << std::setw(8) << value;
    }
    return oss.str();
}

void processInput(std::istream& input, int& a, int& b, int& c) {
    std::string line;
    std::getline(input, line);
    std::istringstream iss(line);
    if (!(iss >> a >> b >> c)) {
        throw std::runtime_error("Invalid input format");
    }
    validateInputRange(a);
    validateInputRange(b);
    validateInputRange(c);
    if (iss.rdbuf()->in_avail() != 0) {
        throw std::runtime_error("Extra input detected");
    }
}

