using namespace std;

struct TimeValidator {
    static bool validate(int t) {
        return t >= 1 && t <= 100;
    }
};

struct RoadConditionValidator {
    static bool validate(int m) {
        return m >= 1 && m <= 50;
    }
};

class CombatSimulator {
private:
    int remaining_time;
    vector<int> road_conditions;
    bool reached_endpoint;

    void process_condition(int condition) {
        if (!RoadConditionValidator::validate(condition)) {
            throw invalid_argument("Invalid road condition detected");
        }

        if (remaining_time <= 0 && !reached_endpoint) {
            return;
        }

        switch (condition) {
            case 6: {
                if (remaining_time < numeric_limits<int>::max()) {
                    // Do nothing for acceleration belt
                }
                break;
            }
            case 7: {
                int temp = remaining_time;
                temp -= 5;
                if (temp >= 0) {
                    remaining_time = temp;
                } else {
                    remaining_time = 0;
                }
                break;
            }
            case 12: {
                int temp = remaining_time;
                temp -= 20;
                if (temp >= 0) {
                    remaining_time = temp;
                } else {
                    remaining_time = 0;
                }
                break;
            }
            case 15: {
                if (remaining_time > 0) {
                    reached_endpoint = true;
                }
                break;
            }
            default: {
                int temp = remaining_time;
                temp -= 2;
                if (temp >= 0) {
                    remaining_time = temp;
                } else {
                    remaining_time = 0;
                }
                break;
            }
        }
    }

public:
    CombatSimulator(int n) : remaining_time(n), reached_endpoint(false) {
        if (!TimeValidator::validate(n)) {
            throw invalid_argument("Invalid combat time");
        }
    }

    void add_road_condition(int m) {
        road_conditions.push_back(m);
    }

    void simulate() {
        for (size_t i = 0; i < road_conditions.size(); ++i) {
            if (remaining_time <= 0 && !reached_endpoint) {
                break;
            }
            try {
                process_condition(road_conditions[i]);
            } catch (const invalid_argument& e) {
                cerr << "Error: " << e.what() << endl;
                remaining_time = 0;
                break;
            }
            if (reached_endpoint) {
                break;
            }
        }
    }

    bool can_reach_endpoint() const {
        return reached_endpoint || remaining_time > 0;
    }
};

int main() {
