#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <cstdlib>
#include <cmath>

using namespace std;

struct DataSet {
    int x;
    int y;
    int diff;
    int min_val;
    int index;
};

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else {
        if (a.min_val != b.min_val) {
            return a.min_val < b.min_val;
        } else {
            return a.index < b.index;
        }
    }
}

void validateInput(int n) {
    if (n < 1 || n > 100) {
        throw invalid_argument("Invalid number of data sets");
    }
}

void validateXY(int x, int y) {
    if (x < 1 || x > 20 || y < 1 || y > 20) {
        throw out_of_range("X and Y must be between 1 and 20");
    }
}

int computeDifference(int x, int y) {
    return abs(x - y);
}

int findMinimumValue(int x, int y) {
    return min(x, y);
}

void processDataSet(vector<DataSet>& dataSets, int x, int y, int index) {
    DataSet current;
    current.x = x;
    current.y = y;
    current.diff = computeDifference(x, y);
    current.min_val = findMinimumValue(x, y);
    current.index = index;
    dataSets.push_back(current);
}

void findResult(const vector<DataSet>& dataSets, int& resultX, int& resultY) {
    if (dataSets.empty()) {
        throw runtime_error("No data sets provided");
    }

    vector<DataSet> sortedDataSets = dataSets;
    sort(sortedDataSets.begin(), sortedDataSets.end(), compareDataSets);

    resultX = sortedDataSets[0].x;
    resultY = sortedDataSets[0].y;
}

int main() {
    try {
        int n;
        cin >> n;
        validateInput(n);

        vector<DataSet> dataSets;
        dataSets.reserve(n);

        for (int i = 0; i < n; ++i) {
            int x, y;
            if (!(cin >> x >> y)) {
                throw runtime_error("Invalid input format");
            }
            validateXY(x, y);
            processDataSet(dataSets, x, y, i);
        }

        int resultX, resultY;
        findResult(dataSets, resultX, resultY);

        cout << resultX << " " << resultY << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
