#include <bits/stdc++.h>
using namespace std;

const int MAX_CHARACTERS = 1000;
const int ALPHANUM_SIZE = 36;
const int SPECIAL_SEQUENCE_LENGTH = 3;

struct DecryptionContext {
    string encrypted;
    string decrypted;
    bool hasError;
    int currentPosition;
};

void initializeAlphanumericArray(char arr[]) {
    const string base = "abcdefghijklmnopqrstuvwxyz0123456789";
    for (int i = 0; i < ALPHANUM_SIZE; ++i) {
        arr[i] = base[i];
    }
}

bool validateTripleCharacter(const DecryptionContext& ctx, char c) {
    if (ctx.currentPosition + 2 >= ctx.encrypted.length()) {
        return false;
    }
    return ctx.encrypted[ctx.currentPosition] == c && 
           ctx.encrypted[ctx.currentPosition + 1] == c && 
           ctx.encrypted[ctx.currentPosition + 2] == c;
}

void handleSpecialSequence(DecryptionContext& ctx, char replacement) {
    ctx.decrypted += replacement;
    ctx.currentPosition += SPECIAL_SEQUENCE_LENGTH;
}

int findCharacterIndex(const char arr[], char target) {
    for (int i = 0; i < ALPHANUM_SIZE; ++i) {
        if (arr[i] == target) {
            return i;
        }
    }
    return -1;
}

void handleAlphanumericCharacter(DecryptionContext& ctx, const char alphanum[]) {
    int originalIndex = findCharacterIndex(alphanum, ctx.encrypted[ctx.currentPosition]);
    if (originalIndex == -1) {
        ctx.hasError = true;
        return;
    }

    int decryptedIndex = (originalIndex - 3 + ALPHANUM_SIZE) % ALPHANUM_SIZE;
    if (decryptedIndex < 0) {
        decryptedIndex += ALPHANUM_SIZE;
    }

    ctx.decrypted += alphanum[decryptedIndex];
    ctx.currentPosition++;
}

void decryptMessage(DecryptionContext& ctx) {
    char alphanum[ALPHANUM_SIZE];
    initializeAlphanumericArray(alphanum);

    while (ctx.currentPosition < ctx.encrypted.length()) {
        if (validateTripleCharacter(ctx, 'k')) {
            handleSpecialSequence(ctx, ' ');
        } else if (validateTripleCharacter(ctx, 's')) {
            handleSpecialSequence(ctx, '.');
        } else {
            handleAlphanumericCharacter(ctx, alphanum);
        }

        if (ctx.hasError) {
            cerr << "Decryption error encountered at position " << ctx.currentPosition << endl;
            return;
        }
    }
}

int main() {
