    if (ctx.encrypted.length() > MAX_CHARACTERS) {
        cerr << "Input exceeds maximum allowed length" << endl;
        return 1;
    }

    decryptMessage(ctx);

    if (!ctx.hasError) {
        cout << ctx.decrypted << endl;
    } else {
        return 1;
    }

