#include<bits/stdc++.h>
using namespace std;

bool isPunctuation(char c) {
    return c == '!' || c == '?' || c == '.' || c == ',' || c == ';' || c == ':';
}

bool isWordChar(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '\'';
}

string processWord(const string& word) {
    string result = word;
    for (char& c : result) {
        if (c != 'I' && isupper(c)) {
            c = tolower(c);
        }
    }
    size_t qmark = result.find('?');
    while (qmark != string::npos) {
        result.replace(qmark, 1, "!");
        qmark = result.find('?', qmark + 1);
    }
    return result;
}

vector<string> tokenize(const string& s) {
    vector<string> tokens;
    string current;
    bool inWord = false;

    for (char c : s) {
        if (isWordChar(c)) {
            if (!inWord && !current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
            current += c;
            inWord = true;
        } else {
            if (inWord) {
                tokens.push_back(current);
                current.clear();
                inWord = false;
            }
            if (!isspace(c)) {
                current += c;
                tokens.push_back(current);
                current.clear();
            }
        }
    }

    if (!current.empty()) {
        tokens.push_back(current);
    }

    return tokens;
}

bool shouldReplace(const vector<string>& tokens, size_t i, const string& target1, const string& target2) {
    if (i + 1 >= tokens.size()) return false;
    if (tokens[i] != target1) return false;
    if (tokens[i+1] != target2) return false;
    if (i > 0 && isPunctuation(tokens[i-1].back())) return false;
    if (i + 2 < tokens.size() && isPunctuation(tokens[i+2].front())) return false;
    return true;
}

vector<string> applyRules(const vector<string>& tokens) {
    vector<string> result;
    vector<bool> processed(tokens.size(), false);

    for (size_t i = 0; i < tokens.size(); ++i) {
        if (processed[i]) continue;

        if (shouldReplace(tokens, i, "can", "you")) {
            result.push_back("I");
            result.push_back("can");
            processed[i] = processed[i+1] = true;
            i++;
        } else if (shouldReplace(tokens, i, "could", "you")) {
            result.push_back("I");
            result.push_back("could");
            processed[i] = processed[i+1] = true;
            i++;
        } else {
            string word = tokens[i];
            if (!processed[i] && (word == "I" || word == "me")) {
                result.push_back("you");
                processed[i] = true;
            } else {
                result.push_back(word);
            }
        }
    }

    return result;
}

string reconstruct(const vector<string>& tokens) {
    string result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i > 0 && !isPunctuation(tokens[i].front()) && !isPunctuation(tokens[i-1].back())) {
            result += " ";
        }
        result += tokens[i];
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

