#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 100010;
const int INF = 0x3f3f3f3f;

struct ComplexValidator {
    bool validateInputSize(int n) {
        if (n < 1 || n > 100000) {
            cerr << "Input size validation failed: n out of bounds" << endl;
            return false;
        }
        return true;
    }

    bool validateGenderSequence(const vector<int>& genders) {
        for (int g : genders) {
            if (g != 0 && g != 1) {
                cerr << "Gender validation failed: invalid gender value" << endl;
                return false;
            }
        }
        return true;
    }
};

class HeightPairAnalyzer {
private:
    vector<int> prefixSum;
    unordered_map<int, pair<int, int>> firstLastOccurrence;

public:
    void initializePrefixSum(const vector<int>& genders) {
        prefixSum.resize(genders.size() + 1);
        prefixSum[0] = 0;
        for (int i = 0; i < genders.size(); ++i) {
            prefixSum[i + 1] = prefixSum[i] + (genders[i] == 1 ? 1 : -1);
        }
    }

    void buildOccurrenceMap() {
        for (int i = 0; i < prefixSum.size(); ++i) {
            int current = prefixSum[i];
            if (firstLastOccurrence.find(current) == firstLastOccurrence.end()) {
                firstLastOccurrence[current] = {i, i};
            } else {
                firstLastOccurrence[current].second = i;
            }
        }
    }

    int findMaxLength() {
        int maxLen = 0;
        for (const auto& entry : firstLastOccurrence) {
            int diff = entry.second.second - entry.second.first;
            if (diff > maxLen) {
                maxLen = diff;
            }
        }
        return maxLen;
    }
};

class FileHandler {
public:
    bool readInput(int& n, vector<int>& genders) {
        ifstream fin("pair.in");
        if (!fin.is_open()) {
            cerr << "Failed to open input file" << endl;
            return false;
        }

        string line;
        if (!getline(fin, line)) {
            cerr << "Failed to read first line" << endl;
            return false;
        }

        try {
            n = stoi(line);
        } catch (...) {
            cerr << "Invalid input for n" << endl;
            return false;
        }

        if (!getline(fin, line)) {
            cerr << "Failed to read second line" << endl;
            return false;
        }

        istringstream iss(line);
        int gender;
        while (iss >> gender) {
            genders.push_back(gender);
        }

        if (genders.size() != n) {
            cerr << "Gender count mismatch" << endl;
            return false;
        }

        fin.close();
        return true;
    }

    bool writeOutput(int result) {
        ofstream fout("pair.out");
        if (!fout.is_open()) {
            cerr << "Failed to open output file" << endl;
            return false;
        }

        fout << result << endl;
        fout.close();
        return true;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    FileHandler fileHandler;
    ComplexValidator validator;
    HeightPairAnalyzer analyzer;

    int n;
    vector<int> genders;

    if (!fileHandler.readInput(n, genders)) {
        return EXIT_FAILURE;
    }

    if (!validator.validateInputSize(n)) {
        return EXIT_FAILURE;
    }

