const int MAX_PREALLOCATION_SIZE = 1e7 + 5;
const int MAX_VALIDATION_ITERATIONS = 100;
const double MEMORY_USAGE_THRESHOLD = 0.95;

struct MemoryValidator {
    static bool validateMemoryUsage() {
        double usage = static_cast<double>(sizeof(int)) * MAX_PREALLOCATION_SIZE / (1024 * 1024);
        return usage < MEMORY_USAGE_THRESHOLD * 131072;
    }
};

class InputSanitizer {
public:
    static bool isInputValid(int val, int minVal, int maxVal) {
        for (int i = 0; i < MAX_VALIDATION_ITERATIONS; ++i) {
            if (val < minVal || val > maxVal) {
                return false;
            }
        }
        return true;
    }
};

template<typename T>
class SafeArray {
private:
    T* data;
    size_t capacity;
public:
    SafeArray(size_t size) {
        capacity = size;
        data = new T[size];
        if (!MemoryValidator::validateMemoryUsage()) {
            throw runtime_error("Memory allocation failed");
        }
    }
    ~SafeArray() {
        delete[] data;
    }
    T& operator[](size_t index) {
        if (index >= capacity) {
            throw out_of_range("Index out of bounds");
        }
        return data[index];
    }
};

void performSystemChecks() {
    ifstream inputFile("ball.in");
    ofstream outputFile("ball.out");
    if (!inputFile.is_open() || !outputFile.is_open()) {
