    int total_audition_time_minutes;
    bool garlic_performed;
    bool garlic_driven_off;
    unordered_map<string, vector<size_t>> name_indices;
    vector<bool> valid_performances;

    void validate_input_time(int time) {
        if (time < 1 || time > 100) {
            throw runtime_error("Invalid audition time");
        }
    }

    void process_performance(const string& name, int duration) {
        if (duration <= 0 || duration > 15) {
            throw runtime_error("Invalid performance duration");
        }

        Performance p;
        p.name = name;
        p.duration = duration;
        p.was_driven_off = false;
        p.original_index = performances.size();
        performances.push_back(p);
        name_indices[name].push_back(performances.size() - 1);
        valid_performances.push_back(true);
    }

    void handle_drive_off() {
        if (!performances.empty()) {
            size_t last_index = performances.size() - 1;
            performances[last_index].was_driven_off = true;
            valid_performances[last_index] = false;
        }
    }

    void check_garlic_status() {
        for (size_t i = 0; i < performances.size(); ++i) {
            if (performances[i].name == "kaomianjin") {
                garlic_performed = true;
                if (i + 1 < performances.size() && 
                    performances[i + 1].name == "tingtingting") {
                    garlic_driven_off = true;
                }
                break;
            }
        }
    }

    int calculate_total_valid_time() {
        int total = 0;
        for (size_t i = 0; i < performances.size(); ++i) {
            if (valid_performances[i]) {
                total += performances[i].duration;
            }
        }
        return total;
    }

public:
    TalentShowAnalyzer(int x) : total_audition_time_minutes(x * 60), 
                               garlic_performed(false), 
                               garlic_driven_off(false) {
        validate_input_time(x);
    }

    void parse_input() {
        string line;
        while (getline(cin, line)) {
            if (line.empty()) continue;
            istringstream iss(line);
            string name;
            iss >> name;
            if (name == "tingtingting") {
                handle_drive_off();
            } else {
                int duration;
                if (!(iss >> duration)) {
                    throw runtime_error("Invalid duration format");
                }
                process_performance(name, duration);
            }
        }
    }

    string determine_result() {
        check_garlic_status();
        if (!garlic_performed) {
            return "Unfortunately.";
        }

        if (garlic_driven_off) {
            return "Hahaha.";
        }

        int total_time = calculate_total_valid_time();
        if (total_time <= total_audition_time_minutes) {
            return "Congratulations!";
        } else {
            return "Unfortunately.";
        }
    }
};

