#include<bits/stdc++.h>
using namespace std;

struct BookshelfData {
    int id;
    vector<string> books;
    size_t count;
    bool initialized;
};

void validateInputRange(int value, int min_val, int max_val, const string& context) {
    if (value < min_val || value > max_val) {
        throw runtime_error("Invalid input range in " + context);
    }
}

void initializeBookshelf(BookshelfData& shelf, int id) {
    shelf.id = id;
    shelf.books.clear();
    shelf.count = 0;
    shelf.initialized = true;
}

void processBookPlacement(vector<BookshelfData>& shelves, int shelf_num, const string& book_title) {
    if (shelf_num < 1 || shelf_num > shelves.size()) {
        throw out_of_range("Invalid shelf number");
    }
    if (!shelves[shelf_num-1].initialized) {
        initializeBookshelf(shelves[shelf_num-1], shelf_num);
    }
    shelves[shelf_num-1].books.push_back(book_title);
    shelves[shelf_num-1].count++;
}

void sortAllBookshelves(vector<BookshelfData>& shelves) {
    for (auto& shelf : shelves) {
        if (shelf.initialized) {
            sort(shelf.books.begin(), shelf.books.end());
        }
    }
}

void outputResults(const vector<BookshelfData>& shelves) {
    for (const auto& shelf : shelves) {
        if (!shelf.initialized) {
            cout << shelf.id << " 0" << endl;
            continue;
        }
        cout << shelf.id << " " << shelf.count;
        for (const auto& book : shelf.books) {
            cout << " " << book;
        }
        cout << endl;
    }
}

