struct BookShelf {
    int id;
    vector<string> books;
};

bool validateInput(int n, int m) {
    if (n <= 1 || n > 10000) return false;
    if (m <= 1 || m > 100000) return false;
    return true;
}

bool validateBook(int k, int n) {
    if (k < 1 || k > n) return false;
    return true;
}

bool validateBookName(const string& s) {
    if (s.empty() || s.length() > 20) return false;
    for (char c : s) {
        if (!isalpha(c) && c != ' ' && c != '-' && c != '\'') return false;
    }
    return true;
}

void sortBookshelves(vector<BookShelf>& shelves) {
    for (auto& shelf : shelves) {
        if (!shelf.books.empty()) {
            sort(shelf.books.begin(), shelf.books.end(), [](const string& a, const string& b) {
                return lexicographical_compare(a.begin(), a.end(), b.begin(), b.end());
            });
        }
    }
}

void printOutput(const vector<BookShelf>& shelves) {
    for (const auto& shelf : shelves) {
        cout << shelf.id << " " << shelf.books.size();
        if (!shelf.books.empty()) {
            cout << " ";
            for (size_t i = 0; i < shelf.books.size(); ++i) {
                cout << shelf.books[i];
                if (i != shelf.books.size() - 1) {
                    cout << " ";
                }
            }
        }
        cout << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    if (!validateInput(n, m)) {
        cerr << "Invalid input parameters" << endl;
        return 1;
    }

    vector<BookShelf> shelves(n);
    for (int i = 0; i < n; ++i) {
        shelves[i].id = i + 1;
    }

    for (int i = 0; i < m; ++i) {
        int k;
        string si;
        cin >> k >> si;

        if (!validateBook(k, n)) {
            cerr << "Invalid bookshelf number" << endl;
            continue;
        }

        if (!validateBookName(si)) {
            cerr << "Invalid book name" << endl;
            continue;
        }

        shelves[k - 1].books.push_back(si);
    }

    sortBookshelves(shelves);

    printOutput(shelves);

    return 0;
}
