#include <iostream>
#include <iomanip>
#include <limits>
#include <sstream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

namespace OutputAlignmentUtils {
    class InputValidator {
    public:
        static bool validateInteger(const string& str) {
            if (str.empty()) return false;
            size_t pos = 0;
            if (str[0] == '-') pos = 1;
            return all_of(str.begin() + pos, str.end(), [](char c) {
                return isdigit(c);
            });
        }

        static bool isWithinIntRange(const string& str) {
            try {
                long long val = stoll(str);
                return val >= numeric_limits<int>::min() && val <= numeric_limits<int>::max();
            } catch (...) {
                return false;
            }
        }
    };

    class InputProcessor {
    private:
        static vector<string> tokenizeInput(const string& input) {
            vector<string> tokens;
            istringstream iss(input);
            string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
            return tokens;
        }

    public:
        static bool processInput(int& a, int& b, int& c) {
            string inputLine;
            getline(cin, inputLine);
            vector<string> tokens = tokenizeInput(inputLine);

            if (tokens.size() != 3) {
                cerr << "Error: Exactly three integers required" << endl;
                return false;
            }

            for (const auto& token : tokens) {
                if (!InputValidator::validateInteger(token)) {
                    cerr << "Error: Invalid integer format" << endl;
                    return false;
                }
                if (!InputValidator::isWithinIntRange(token)) {
                    cerr << "Error: Integer out of range" << endl;
                    return false;
                }
            }

            a = stoi(tokens[0]);
            b = stoi(tokens[1]);
            c = stoi(tokens[2]);
            return true;
        }
    };

    class OutputFormatter {
    public:
        static void formatOutput(int a, int b, int c) {
            cout << right << setw(8) << a << " ";
            cout << right << setw(8) << b << " ";
            cout << right << setw(8) << c;
            cout << endl;
        }
    };
}

int main() {
    int a = 0, b = 0, c = 0;
    bool inputSuccess = false;
    int retryCount = 0;
    const int maxRetries = 5;

    while (!inputSuccess && retryCount < maxRetries) {
        try {
            inputSuccess = OutputAlignmentUtils::InputProcessor::processInput(a, b, c);
            if (!inputSuccess) {
                retryCount++;
                if (retryCount < maxRetries) {
                    cout << "Please try again (" << maxRetries - retryCount << " attempts remaining)" << endl;
                }
            }
        } catch (const exception& e) {
            cerr << "Unexpected error: " << e.what() << endl;
            retryCount++;
            if (retryCount < maxRetries) {
                cout << "Please try again (" << maxRetries - retryCount << " attempts remaining)" << endl;
            }
        }
    }

    if (!inputSuccess) {
        cerr << "Maximum retry attempts reached. Exiting." << endl;
        return EXIT_FAILURE;
    }

    OutputAlignmentUtils::OutputFormatter::formatOutput(a, b, c);

    return EXIT_SUCCESS;
}
