class AdvancedQueueManager {
private:
    vector<string> queue;
    int front;
    int rear;
    int capacity;

public:
    AdvancedQueueManager(int max_size) : front(0), rear(0), capacity(max_size) {
        queue.resize(max_size, "0");
    }

    bool enqueueWithFriendCheck(const string& name) {
        if (!QueueValidator::validateName(name)) {
            return false;
        }

        bool friendFound = false;
        int friendPosition = -1;

        for (int i = front; i < rear; ++i) {
            if (queue[i] != "0" && queue[i][0] == name[0]) {
                friendFound = true;
                friendPosition = i;
                break;
            }
        }

        if (!friendFound) {
            if (rear >= capacity) {
                return false;
            }
            queue[rear++] = name;
            return true;
        }

        if (rear >= capacity) {
            return false;
        }

        for (int j = rear; j > friendPosition + 1; --j) {
            if (j < capacity) {
                swap(queue[j], queue[j - 1]);
            }
        }

        if (friendPosition + 1 < capacity) {
            queue[friendPosition + 1] = name;
            rear++;
            return true;
        }

        return false;
    }

    string dequeueWithSafety() {
        if (front >= rear || queue[front] == "0") {
            return "0";
        }

        string result = queue[front];
        queue[front] = "0";
        front++;

        if (front > rear) {
            front = rear = 0;
        }

        return result;
    }

    bool isEmpty() const {
        return front >= rear;
    }
};

