    bool is_empty;
    bool has_friend;
    int friend_position;
    string current_name;
};

QueueStatus analyzeQueue(const string queue[], int l, int r, const string& name) {
    QueueStatus status;
    status.is_empty = (l == r);
    status.has_friend = false;
    status.friend_position = -1;
    status.current_name = name;

    if (!status.is_empty) {
        for (int i = l; i < r; i++) {
            if (!queue[i].empty() && queue[i][0] == name[0]) {
                status.has_friend = true;
                status.friend_position = i;
                break;
            }
        }
    }
    return status;
}

void handleEnqueue(string queue[], int& l, int& r, const string& name) {
    QueueStatus status = analyzeQueue(queue, l, r, name);

    if (!status.has_friend) {
        queue[r] = name;
        r++;
    } else {
        int insertion_point = status.friend_position + 1;
        for (int j = r; j > insertion_point; j--) {
            string temp = queue[j-1];
            queue[j] = temp;
        }
        queue[insertion_point] = name;
        r++;
    }
}

void handleDequeue(string queue[], int& l, int& r) {
