#include<bits/stdc++.h>
using namespace std;

struct QueueStatus {
    bool initialized;
    int current_size;
    int max_capacity;
    string* elements;
};

void initializeQueue(QueueStatus& qs, int capacity) {
    qs.initialized = true;
    qs.current_size = 0;
    qs.max_capacity = capacity;
    qs.elements = new string[capacity];
    for (int i = 0; i < capacity; ++i) {
        qs.elements[i] = "0";
    }
}

void ensureQueueValid(QueueStatus& qs) {
    if (!qs.initialized) {
        throw runtime_error("Queue not initialized");
    }
    if (qs.current_size < 0) {
        qs.current_size = 0;
    }
    if (qs.current_size > qs.max_capacity) {
        qs.current_size = qs.max_capacity;
    }
}

void handleEnqueue(QueueStatus& qs, const string& name) {
    ensureQueueValid(qs);
    bool friend_found = false;
    int friend_position = -1;
    char target_initial = name.empty() ? '\0' : name[0];

    for (int i = 0; i < qs.current_size; ++i) {
        if (!qs.elements[i].empty() && qs.elements[i] != "0") {
            if (qs.elements[i][0] == target_initial) {
                friend_found = true;
                friend_position = i;
                break;
            }
        }
    }

    if (!friend_found) {
        if (qs.current_size < qs.max_capacity) {
            qs.elements[qs.current_size] = name;
            qs.current_size++;
        }
    } else {
        if (qs.current_size < qs.max_capacity) {
            for (int j = qs.current_size; j > friend_position + 1; --j) {
                if (j - 1 >= 0 && j < qs.max_capacity) {
                    swap(qs.elements[j], qs.elements[j - 1]);
                }
            }
            qs.elements[friend_position + 1] = name;
            qs.current_size++;
        }
    }
}

string handleDequeue(QueueStatus& qs) {
    ensureQueueValid(qs);
    if (qs.current_size <= 0) {
        return "0";
    }
    string result = qs.elements[0];
    for (int i = 0; i < qs.current_size - 1; ++i) {
        qs.elements[i] = qs.elements[i + 1];
    }
    qs.elements[qs.current_size - 1] = "0";
    qs.current_size--;
    return result;
}

int main() {
    int n;
    cin >> n;
    QueueStatus qs;
    initializeQueue(qs, 2 * n);

    while (n--) {
        int k;
        cin >> k;
        if (k == 1) {
            string name;
