#include<bits/stdc++.h>
using namespace std;

struct QueueValidator {
    static bool validateName(const string& name) {
        if (name.empty()) return false;
        for (char c : name) {
            if (!isalpha(c)) return false;
        }
        return true;
    }
};

class AdvancedQueueManager {
private:
    vector<string> queue;
    int front;
    int rear;
    int capacity;

public:
    AdvancedQueueManager(int max_size) : front(0), rear(0), capacity(max_size) {
        queue.resize(max_size, "0");
    }

    bool enqueue(const string& name) {
        if (rear >= capacity) {
            vector<string> new_queue(capacity * 2, "0");
            copy(queue.begin(), queue.end(), new_queue.begin());
            queue = new_queue;
            capacity *= 2;
        }

        if (!QueueValidator::validateName(name)) {
            return false;
        }

        bool friend_found = false;
        int insert_position = rear;

        for (int i = front; i < rear; ++i) {
            if (queue[i] != "0" && queue[i][0] == name[0]) {
                friend_found = true;
                insert_position = i + 1;
                while (insert_position < rear && queue[insert_position][0] == name[0]) {
                    insert_position++;
                }
                break;
            }
        }

        if (friend_found) {
            if (rear + 1 >= capacity) {
                vector<string> new_queue(capacity * 2, "0");
                copy(queue.begin(), queue.end(), new_queue.begin());
                queue = new_queue;
                capacity *= 2;
            }
            for (int j = rear; j > insert_position; --j) {
                queue[j] = queue[j - 1];
            }
            queue[insert_position] = name;
        } else {
            queue[rear] = name;
        }

        rear++;
        return true;
    }

    string dequeue() {
        if (front >= rear || queue[front] == "0") {
            return "0";
        }
        string result = queue[front];
        queue[front] = "0";
        front++;

        if (front > capacity / 4 && front > 10) {
            vector<string> new_queue(capacity, "0");
            copy(queue.begin() + front, queue.begin() + rear, new_queue.begin());
            rear -= front;
            front = 0;
            queue = new_queue;
        }

        return result;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    AdvancedQueueManager aqm(200);

    while (n--) {
        int k;
        cin >> k;

