            string name;
            cin >> name;
            if (!aqm.enqueue(name)) {
                cerr << "Invalid name encountered" << endl;
            }
        } else if (k == 2) {
            string result = aqm.dequeue();
            cout << (result.empty() ? "0" : result) << endl;
        } else {
            cerr << "Invalid operation code" << endl;
            continue;
        }
    }

    return 0;
}
