            RoadCondition rc = static_cast<RoadCondition>(*it);
            switch (rc) {
                case RoadCondition::ACCELERATION:
                    break;
                case RoadCondition::ENDPOINT:
                    reached_endpoint = true;
                    break;
                case RoadCondition::ROADBLOCK:
                    remaining_time = (remaining_time > 5) ? remaining_time - 5 : 0;
