            throw runtime_error("Queue capacity exceeded");
        }
        if (!validateName(name)) {
            throw invalid_argument("Invalid name format");
        }

        bool friend_found = false;
        char target_char = toupper(name[0]);
        for (auto it = queue.begin(); it != queue.end(); ++it) {
            if (toupper((*it)[0]) == target_char) {
                queue.insert(it + 1, name);
                friend_found = true;
                break;
            }
        }

        if (!friend_found) {
            queue.push_back(name);
        }
    }

    string dequeue() {
        if (queue.empty()) {
            return "0";
        }
        string front = queue.front();
        queue.erase(queue.begin());
        return front;
    }
};

