#include <iostream>
#include <limits>
#include <stdexcept>
#include <type_traits>
#include <cmath>
using namespace std;

template<typename T>
constexpr bool is_safe_abs(T value) {
    return !(numeric_limits<T>::is_signed && value == numeric_limits<T>::min());
}

template<typename T>
typename enable_if<is_signed<T>::value, T>::type safe_abs(T value) {
    if (!is_safe_abs(value)) {
        throw runtime_error("Absolute value overflow detected");
    }
    return value < 0 ? -value : value;
}

template<typename T>
typename enable_if<!is_signed<T>::value, T>::type safe_abs(T value) {
    return value;
}

struct NumberPair {
    int original;
    int absolute;
    bool is_negative;
};

NumberPair process_number(int num) {
    NumberPair result;
    result.original = num;
    try {
        result.absolute = safe_abs(num);
    } catch (const runtime_error& e) {
        cerr << "Warning: " << e.what() << " Using max value instead." << endl;
        result.absolute = numeric_limits<int>::max();
    }
    result.is_negative = num < 0;
    return result;
}

bool compare_numbers(const NumberPair& a, const NumberPair& b) {
    if (a.absolute != b.absolute) {
        return a.absolute < b.absolute;
    }
    if (a.is_negative && !b.is_negative) {
        return true;
    }
    if (!a.is_negative && b.is_negative) {
        return false;
    }
    return a.original < b.original;
}

void validate_input(int a, int b) {
    if (cin.fail()) {
        throw runtime_error("Invalid input detected");
    }
    if (a == numeric_limits<int>::min() || b == numeric_limits<int>::min()) {
        cerr << "Warning: Input contains minimum integer value" << endl;
    }
}

int main() {
    int a, b;
    cin >> a >> b;

    try {
        validate_input(a, b);
    } catch (const runtime_error& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    NumberPair num1 = process_number(a);
    NumberPair num2 = process_number(b);

    if (compare_numbers(num1, num2)) {
        if (num1.original == num2.original && num1.is_negative != num2.is_negative) {
            cout << min(num1.original, num2.original) << " " << max(num1.original, num2.original) << endl;
        } else {
