using namespace std;

template<typename T>
constexpr bool is_arithmetic_v = std::is_arithmetic<T>::value;

template<typename T>
void validate_input_range(T value, T min_val, T max_val) {
    static_assert(is_arithmetic_v<T>, "Type must be arithmetic");
    if (value < min_val || value > max_val) {
        throw std::out_of_range("Input value out of range");
    }
}

template<typename T>
T safe_divide(T numerator, T denominator) {
    if (denominator == 0) {
        throw std::runtime_error("Division by zero");
    }
    return numerator / denominator;
}

template<typename T>
T safe_subtract(T a, T b) {
    if ((b > 0 && a < std::numeric_limits<T>::min() + b) ||
        (b < 0 && a > std::numeric_limits<T>::max() + b)) {
        throw std::overflow_error("Subtraction overflow");
    }
    return a - b;
}

template<typename T>
T safe_multiply(T a, T b) {
    if (a > 0 && b > 0 && a > std::numeric_limits<T>::max() / b) {
        throw std::overflow_error("Multiplication overflow");
    }
    return a * b;
}

template<typename T>
T compute_time_to_shoot(T n, T a, T b) {
    try {
        validate_input_range(n, static_cast<T>(1), static_cast<T>(1000));
        validate_input_range(a, static_cast<T>(1), static_cast<T>(1000));
        validate_input_range(b, static_cast<T>(1), static_cast<T>(1000));

        if (b <= a) {
            throw std::logic_error("Troops speed must be greater than enemy speed");
        }

        T distance_difference = safe_multiply(a, n);
        if (distance_difference <= 600) {
            throw std::logic_error("Initial distance must be greater than shooting range");
        }

        T relative_distance = safe_subtract(distance_difference, static_cast<T>(600));
        T speed_difference = safe_subtract(b, a);
        T time = safe_divide(relative_distance, speed_difference);

        if (safe_multiply(time, speed_difference) != relative_distance) {
            time = safe_divide(relative_distance + speed_difference - 1, speed_difference);
        }

        return time;
    } catch (const std::exception& e) {
        cerr << "Error: " << e.what() << endl;
        return -1;
    }
}

int main() {
