    if (num1.absolute != num2.absolute) {
        return num1.absolute > num2.absolute;
    } else {
        if (num1.isNegative && !num2.isNegative) {
            return true;
        } else if (!num1.isNegative && num2.isNegative) {
            return false;
        } else {
            return num1.original > num2.original;
        }
    }
}

