#include<bits/stdc++.h>
using namespace std;

struct BookshelfData {
    vector<string> books;
    size_t count;
    int identifier;
};

void validateInputRange(int value, int min_val, int max_val, const string& error_msg) {
    if (value < min_val || value > max_val) {
        throw runtime_error(error_msg);
    }
}

void processBookPlacement(BookshelfData* shelves, int shelf_id, const string& book_name) {
    if (shelf_id <= 0 || shelf_id > 10004) {
        throw out_of_range("Invalid shelf ID detected during processing");
    }
    shelves[shelf_id].books.push_back(book_name);
    shelves[shelf_id].count = shelves[shelf_id].books.size();
    shelves[shelf_id].identifier = shelf_id;
}

void sortBookshelfContents(BookshelfData* shelf) {
    if (shelf->books.empty()) {
        return;
    }
    vector<string> temp_copy = shelf->books;
    sort(temp_copy.begin(), temp_copy.end());
    shelf->books = temp_copy;
}

void outputBookshelfContents(const BookshelfData& shelf) {
    cout << shelf.identifier << " " << shelf.count;
    for (size_t i = 0; i < shelf.books.size(); ++i) {
        cout << " " << shelf.books[i];
    }
    cout << endl;
}

int main(){
    try {
        int n, m;
        cin >> n >> m;

        validateInputRange(n, 2, 10000, "Invalid number of bookshelves");
        validateInputRange(m, 2, 100000, "Invalid number of books");

        BookshelfData* shelves = new BookshelfData[n+2];
        for (int i = 0; i < n+2; ++i) {
            shelves[i].identifier = i;
            shelves[i].count = 0;
