        for (int book_num = 1; book_num <= m; ++book_num) {
            int shelf_id;
            string book_name;
            cin >> shelf_id >> book_name;

            validateInputRange(shelf_id, 1, n, "Invalid shelf ID in input");
            if (book_name.empty() || book_name.size() > 20) {
                throw invalid_argument("Invalid book name length");
            }

            processBookPlacement(shelves, shelf_id, book_name);
        }

        for (int i = 1; i <= n; ++i) {
            sortBookshelfContents(&shelves[i]);
            outputBookshelfContents(shelves[i]);
        }

        delete[] shelves;
