using namespace std;

struct InputValidator {
    static bool isValidInteger(const string& s) {
        if (s.empty()) return false;
        size_t i = 0;
        if (s[0] == '-') {
            if (s.length() == 1) return false;
            i = 1;
        }
        for (; i < s.length(); ++i) {
            if (!isdigit(s[i])) return false;
        }
        return true;
    }

    static pair<int, int> parseInput(const string& input) {
        istringstream iss(input);
        string token;
        vector<string> tokens;
        while (getline(iss, token, ' ')) {
            if (!token.empty()) {
                tokens.push_back(token);
            }
        }
        if (tokens.size() != 2) {
            throw runtime_error("Invalid input format");
        }
        if (!isValidInteger(tokens[0]) || !isValidInteger(tokens[1])) {
            throw runtime_error("Invalid integer format");
        }
        long long a = stoll(tokens[0]);
        long long b = stoll(tokens[1]);
        if (a < numeric_limits<int>::min() || a > numeric_limits<int>::max() ||
            b < numeric_limits<int>::min() || b > numeric_limits<int>::max()) {
            throw runtime_error("Integer out of range");
        }
        return {static_cast<int>(a), static_cast<int>(b)};
    }
};

class AbsoluteValueComparator {
private:
    int a, b;
    int a_abs, b_abs;

    void calculateAbsoluteValues() {
        a_abs = a;
        if (a_abs < 0) {
            a_abs = -a_abs;
        }
        b_abs = b;
        if (b_abs < 0) {
            b_abs = -b_abs;
        }
    }

public:
    AbsoluteValueComparator(int x, int y) : a(x), b(y) {
        calculateAbsoluteValues();
    }

    pair<int, int> getSortedPair() {
        if (a_abs != b_abs) {
            if (a_abs > b_abs) {
                return {b, a};
            } else {
                return {a, b};
            }
        } else {
            if (a > b) {
                return {b, a};
            } else {
                return {a, b};
            }
        }
    }
};

int main() {
