    int deliciousness;
};

class CafeteriaMenu {
private:
    vector<Dish> vegetarianDishes;
    vector<Dish> meatDishes;
    int budget;
    int maxDeliciousness;

    void validateInput() {
        if (vegetarianDishes.empty()) {
            throw runtime_error("Must have at least one vegetarian dish");
        }
        if (budget <= 0) {
            throw runtime_error("Budget must be positive");
        }
    }

    void computeVegetarianDP(vector<int>& dp) {
        for (const auto& dish : vegetarianDishes) {
            for (int j = budget; j >= dish.price; --j) {
                if (dp[j - dish.price] != numeric_limits<int>::min()) {
                    dp[j] = max(dp[j], dp[j - dish.price] + dish.deliciousness);
                }
            }
        }
    }

    void computeMeatDP(const vector<int>& vegDP, vector<int>& combinedDP) {
        combinedDP = vegDP;
        for (const auto& dish : meatDishes) {
            for (int j = budget; j >= dish.price; --j) {
                if (combinedDP[j - dish.price] != numeric_limits<int>::min()) {
                    combinedDP[j] = max(combinedDP[j], combinedDP[j - dish.price] + dish.deliciousness);
                }
            }
        }
    }

public:
    void readInput() {
        ifstream inputFile("health.in");
        if (!inputFile.is_open()) {
            throw runtime_error("Failed to open input file");
        }

        int N, M;
        inputFile >> N >> M >> budget;

        vegetarianDishes.resize(N);
        for (int i = 0; i < N; ++i) {
            inputFile >> vegetarianDishes[i].price;
        }
        for (int i = 0; i < N; ++i) {
            inputFile >> vegetarianDishes[i].deliciousness;
        }

        meatDishes.resize(M);
        for (int i = 0; i < M; ++i) {
            inputFile >> meatDishes[i].price;
        }
        for (int i = 0; i < M; ++i) {
            inputFile >> meatDishes[i].deliciousness;
        }

        inputFile.close();
    }

    void calculateMaxDeliciousness() {
        validateInput();

        vector<int> vegDP(budget + 1, numeric_limits<int>::min());
        vegDP[0] = 0;
        computeVegetarianDP(vegDP);

        vector<int> combinedDP;
        computeMeatDP(vegDP, combinedDP);

        maxDeliciousness = *max_element(combinedDP.begin(), combinedDP.end());
        if (maxDeliciousness < 0) {
            maxDeliciousness = 0;
        }
    }

    void writeOutput() {
        ofstream outputFile("health.out");
        if (!outputFile.is_open()) {
            throw runtime_error("Failed to open output file");
        }
        outputFile << maxDeliciousness << endl;
        outputFile.close();
    }
};

int main() {
    try {
        CafeteriaMenu menu;
        menu.readInput();
        menu.calculateMaxDeliciousness();
        menu.writeOutput();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
