using namespace std;

template<typename T>
constexpr bool is_safe_abs(T value) {
    return !(numeric_limits<T>::is_signed && value == numeric_limits<T>::min());
}

template<typename T>
T safe_abs(T value) {
    if constexpr (numeric_limits<T>::is_signed) {
        if (!is_safe_abs(value)) {
            throw runtime_error("Absolute value overflow detected");
        }
    }
    return value < 0 ? -value : value;
}

template<typename T>
void validate_input(T value) {
    if (cin.fail()) {
        throw runtime_error("Invalid input type detected");
    }
    if (is_same<T, int>::value && (value < numeric_limits<int>::min() || value > numeric_limits<int>::max())) {
        throw runtime_error("Input out of int range");
    }
}

template<typename T>
void sort_by_absolute_value(T& a, T& b) {
    T abs_a = safe_abs(a);
    T abs_b = safe_abs(b);

    if (abs_a > abs_b) {
        swap(a, b);
    } else if (abs_a == abs_b) {
        if (a > b) {
            swap(a, b);
        }
    }
}

int main() {
