        int a, b;
        cin >> a >> b;

        validate_input(a);
        validate_input(b);

        if (!is_safe_abs(a) || !is_safe_abs(b)) {
            throw runtime_error("Potential absolute value overflow");
        }

        int original_a = a;
        int original_b = b;

        sort_by_absolute_value(a, b);

        if (safe_abs(a) == safe_abs(b)) {
            if (original_a > original_b) {
