    int total = 0;
    int position = 1;
    for (int i = s.length() - 1; i >= 0; --i) {
        if (s[i] == '?') {
            if (hasQuestionMark) {
                throw runtime_error("Multiple question marks detected");
            }
            hasQuestionMark = true;
            continue;
        }
        int digit = s[i] - '0';
        if (digit < 0 || digit > 9) {
            throw runtime_error("Invalid digit in string");
        }
        total += digit * position;
        ++position;
    }
    return total;
}

pair<int, int> findQuestionMarkPosition(const string& s) {
    for (int i = s.length() - 1; i >= 0; --i) {
        if (s[i] == '?') {
            return {i, s.length() - i};
        }
    }
    return {-1, -1};
}

