        static pair<int, int> getAbsoluteValues(int x, int y) {
            int absX = abs(x);
            int absY = abs(y);
            return make_pair(absX, absY);
        }

        static bool shouldSwap(int x, int y) {
            auto absValues = getAbsoluteValues(x, y);
            if (absValues.first == absValues.second) {
                return x > y;
            }
            return absValues.first > absValues.second;
        }

    public:
        static void sortByAbsoluteValue(int& x, int& y) {
            if (shouldSwap(x, y)) {
                swap(x, y);
            }
        }
    };
}

