            if (sentence.length() > numeric_limits<size_t>::max() / 2) {
                throw length_error("Input sentence too long");
            }
            processingWord = false;
            for (char c : sentence) {
                if (isalpha(c)) {
                    currentWord += c;
                    processingWord = true;
                } else if (isspace(c)) {
                    if (processingWord) {
                        words.push_back(currentWord);
                        currentWord.clear();
                        processingWord = false;
                    }
                }
            }
            if (processingWord && !currentWord.empty()) {
                words.push_back(currentWord);
            }
        }

        vector<string> getWords() const {
            if (words.empty()) {
                throw runtime_error("No words found in sentence");
            }
            return words;
        }
