int recursive_calls = 0;
int max_recursive_depth = 0;

void validate_input() {
    if (n < 1 || n > 10) {
        cerr << "Invalid number of stones" << endl;
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < n; ++i) {
        if (stones[i].anger <= 0 || stones[i].irritability <= 0) {
            cerr << "Invalid stone attributes" << endl;
            exit(EXIT_FAILURE);
        }
    }
}

void update_min_diff() {
    if (current_product == 1 && current_sum == 0) return;
    int diff = abs(current_product - current_sum);
    if (diff < min_diff) {
        min_diff = diff;
    }
}

void complex_dfs(int depth, int start) {
    recursive_calls++;
    max_recursive_depth = max(max_recursive_depth, depth);

    if (depth > n) {
        cerr << "Recursion depth exceeded" << endl;
        return;
    }

    for (int i = start; i < n; ++i) {
        if (!selected[i]) {
            int prev_product = current_product;
            int prev_sum = current_sum;

            current_product *= stones[i].anger;
            current_sum += stones[i].irritability;
