#include<bits/stdc++.h>
using namespace std;

const int MAX_STONES = 15;
const int INF = 1e9 + 7;

struct StoneValidation {
    bool anger_valid;
    bool irritability_valid;
    bool stone_valid;
};

struct StoneConfiguration {
    int product;
    int sum;
    bool configuration_valid;
};

int global_min_diff = INF;
int stone_count;
int anger_values[MAX_STONES + 2];
int irritability_values[MAX_STONES + 2];
bool selected_stones[MAX_STONES + 2];

StoneValidation validateStone(int anger, int irritability) {
    StoneValidation validation;
    validation.anger_valid = (anger >= -1000 && anger <= 1000);
    validation.irritability_valid = (irritability >= -1000 && irritability <= 1000);
    validation.stone_valid = validation.anger_valid && validation.irritability_valid;
    return validation;
}

void initializeSelection() {
    for (int i = 0; i <= MAX_STONES + 1; i++) {
        selected_stones[i] = false;
    }
}

StoneConfiguration calculateCurrentConfiguration() {
    StoneConfiguration config;
    config.product = 1;
    config.sum = 0;
    config.configuration_valid = false;
    bool at_least_one_selected = false;

    for (int i = 1; i <= stone_count; i++) {
        if (selected_stones[i]) {
            at_least_one_selected = true;
            config.product *= anger_values[i];
            config.sum += irritability_values[i];
        }
    }

    if (at_least_one_selected) {
        config.configuration_valid = true;
    } else {
        config.product = 0;
        config.sum = 0;
    }

    return config;
}

void updateGlobalMin(int current_diff) {
    if (abs(current_diff) < abs(global_min_diff)) {
        global_min_diff = current_diff;
    } else if (abs(current_diff) == abs(global_min_diff)) {
        if (current_diff < global_min_diff) {
            global_min_diff = current_diff;
        }
    }
}

void recursiveStoneSelection(int current_stone) {
    if (current_stone > stone_count) {
        StoneConfiguration config = calculateCurrentConfiguration();
        if (config.configuration_valid) {
            int current_diff = config.product - config.sum;
            updateGlobalMin(current_diff);
        }
        return;
    }

    selected_stones[current_stone] = true;
    recursiveStoneSelection(current_stone + 1);

    selected_stones[current_stone] = false;
    recursiveStoneSelection(current_stone + 1);
}

void processInput() {
    ifstream input_file("stone.in");
    ofstream output_file("stone.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "File opening failed" << endl;
        exit(EXIT_FAILURE);
    }

    input_file >> stone_count;
    if (stone_count < 1 || stone_count > 10) {
        cerr << "Invalid stone count" << endl;
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i <= stone_count; i++) {
        input_file >> anger_values[i] >> irritability_values[i];
        StoneValidation validation = validateStone(anger_values[i], irritability_values[i]);
        if (!validation.stone_valid) {
            cerr << "Invalid stone attributes" << endl;
            exit(EXIT_FAILURE);
        }
    }

    initializeSelection();
    recursiveStoneSelection(1);

    output_file << abs(global_min_diff) << endl;

    input_file.close();
    output_file.close();
}

int main() {
    processInput();
    return 0;
}
