const char NUMERIC_WRAP_START = '0';
const char NUMERIC_WRAP_END = '9';
const char ALPHA_WRAP_START = 'a';
const char ALPHA_WRAP_END = 'z';
const char NUMERIC_BOUNDARY = '2';
const char ALPHA_BOUNDARY = 'c';

string performSafeReplacement(const string& input, const string& target, const string& replacement) {
    string result = input;
    size_t position = result.find(target);
    while (position != string::npos) {
        if (position + target.length() <= result.length()) {
            result.replace(position, target.length(), replacement);
        } else {
            break;
        }
        position = result.find(target, position + replacement.length());
    }
    return result;
}

char handleNumericShift(char c) {
    if (c >= '3' && c <= '9') {
        return c - SHIFT_VALUE;
    } else if (c >= NUMERIC_WRAP_START && c <= NUMERIC_BOUNDARY) {
        return (c - NUMERIC_WRAP_START) + 'x';
    }
    return c;
}

char handleAlphaShift(char c) {
    if (c >= 'd' && c <= ALPHA_WRAP_END) {
        return c - SHIFT_VALUE;
    } else if (c >= ALPHA_WRAP_START && c <= ALPHA_BOUNDARY) {
        return (c - ALPHA_WRAP_START) + '7';
    }
    return c;
}

string processCharacterShifts(const string& input) {
    string processed;
    for (size_t i = 0; i < input.length(); ++i) {
        char current = input[i];
        if (isdigit(current)) {
            processed += handleNumericShift(current);
        } else if (isalpha(current)) {
            processed += handleAlphaShift(current);
        } else {
            processed += current;
        }
    }
    return processed;
}

