    getline(cin, encrypted);

    string stage1 = performSafeReplacement(encrypted, SPACE_REPLACEMENT, " ");
    string stage2 = performSafeReplacement(stage1, DOT_REPLACEMENT, ".");

    string decrypted = processCharacterShifts(stage2);

    cout << decrypted << endl;

    return 0;
}
