struct Performance {
    string name;
    int duration;
    bool was_driven_off;
};

vector<Performance> performances;
int total_audition_time_minutes = 0;
int accumulated_time = 0;
bool garlic_performed = false;
bool garlic_driven_off = false;

void validate_input(const string& s, int t) {
    if (s.empty() || s.length() > 100) {
        throw invalid_argument("Invalid program name length");
    }
    if (t <= 0 || t > 15) {
        throw out_of_range("Invalid duration value");
    }
}

