    if (!performances.empty()) {
        Performance& last = performances.back();
        if (last.was_driven_off) {
            throw logic_error("Multiple tingtingting in sequence");
        }
        accumulated_time -= last.duration;
        last.was_driven_off = true;
    } else {
        throw logic_error("tingtingting with no previous performance");
    }
}

void process_regular_performance(const string& s, int t) {
    validate_input(s, t);
    Performance p;
    p.name = s;
    p.duration = t;
    p.was_driven_off = false;
    performances.push_back(p);
    accumulated_time += t;
}

void process_kaomianjin(int t) {
    validate_input("kaomianjin", t);
    Performance p;
    p.name = "kaomianjin";
    p.duration = t;
    p.was_driven_off = false;
    performances.push_back(p);
    accumulated_time += t;
    garlic_performed = true;
}

void check_time_limit() {
    if (accumulated_time >= total_audition_time_minutes) {
        throw runtime_error("Time limit exceeded");
    }
}

