    int duration;
    bool wasInterrupted;
    size_t originalIndex;
};

class TalentShowSimulator {
private:
    vector<PerformanceRecord> performances;
    int totalAuditionTimeMinutes;
    int accumulatedTime;
    bool garlicPerformed;
    bool garlicInterrupted;
    bool timeExceeded;

public:
    TalentShowSimulator(int hours) : totalAuditionTimeMinutes(hours * 60), accumulatedTime(0), garlicPerformed(false), garlicInterrupted(false), timeExceeded(false) {}

    void processInput() {
        string currentLine;
        PerformanceRecord currentRecord;
        size_t performanceCounter = 0;

        while (getline(cin, currentLine)) {
            if (currentLine.empty()) continue;

            istringstream iss(currentLine);
            string name;
            if (!(iss >> name)) continue;

            if (name == "tingtingting") {
                if (!performances.empty()) {
                    performances.back().wasInterrupted = true;
                    accumulatedTime -= performances.back().duration;
                    performances.pop_back();
                }
            } else {
                int duration;
                if (iss >> duration) {
                    currentRecord = {name, duration, false, performanceCounter++};
                    if (name == "kaomianjin") {
                        performances.push_back(currentRecord);
                        accumulatedTime += duration;
                        garlicPerformed = true;
                        string nextLine;
                        if (getline(cin, nextLine)) {
                            if (nextLine.find("tingtingting") != string::npos) {
                                garlicInterrupted = true;
                                return;
                            }
                        }
                        return;
                    } else {
                        if (accumulatedTime + duration > totalAuditionTimeMinutes) {
                            timeExceeded = true;
                            return;
                        }
                        performances.push_back(currentRecord);
                        accumulatedTime += duration;
                    }
                }
            }
        }
    }

    string getResult() {
        if (garlicInterrupted) {
            return "Hahaha.";
        }
        if (garlicPerformed) {
            return "Congratulations!";
        }
        if (timeExceeded || accumulatedTime >= totalAuditionTimeMinutes) {
