    }
    if (fa[v] != -1) {
        cerr << "Node " << v << " already has a parent" << endl;
        exit(1);
    }
}

void compute_degrees(int n) {
    for (int i = 0; i < n; i++) {
        degree[i] = G[i].size();
        if (fa[i] != -1) {
            degree[i]++;
        }
    }
}

bool check_parent_condition(int node, int parent) {
    if (parent == -1) return true;
    return degree[node] >= degree[parent];
}

bool check_children_condition(int node) {
    for (int child : G[node]) {
        if (degree[node] < degree[child]) {
            return false;
        }
    }
    return true;
}

void verify_tree_structure(int n) {
    vector<bool> visited(n, false);
    queue<int> q;
    q.push(0);
    visited[0] = true;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : G[u]) {
            if (visited[v]) {
                cerr << "Cycle detected in tree structure" << endl;
                exit(1);
            }
            visited[v] = true;
            q.push(v);
        }
    }
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            cerr << "Disconnected tree detected" << endl;
            exit(1);
        }
    }
}

