#include <bits/stdc++.h>
#include <cerrno>
#include <cstring>
using namespace std;

const int N = 1000 + 10;
const int ADDEND = 2018;
const int MAX_ITERATIONS = 10000;

struct BigNumContainer {
    int digits[1005];
    int length;
    bool is_valid;
};

void initializeContainer(BigNumContainer* container) {
    memset(container->digits, 0, sizeof(container->digits));
    container->length = 0;
    container->is_valid = true;
}

bool validateInputString(const string& str) {
    if (str.empty()) return false;
    for (char c : str) {
        if (!isdigit(c)) return false;
    }
    return true;
}

void processInputString(BigNumContainer* container, const string& num) {
    if (!container->is_valid) return;

    container->length = num.length();
    if (container->length > 1000) {
        container->is_valid = false;
        return;
    }

    for (int i = 1; i <= container->length; i++) {
        container->digits[i] = num[container->length - 1 - (i - 1)] - '0';
        if (container->digits[i] < 0 || container->digits[i] > 9) {
            container->is_valid = false;
            return;
        }
    }
}

void performAddition(BigNumContainer* container) {
    if (!container->is_valid) return;

    container->digits[1] += ADDEND;
    int safety_counter = 0;

    for (int i = 1; i <= container->length && safety_counter < MAX_ITERATIONS; i++, safety_counter++) {
        container->digits[i + 1] += container->digits[i] / 10;
        container->digits[i] %= 10;
    }

    while (container->digits[container->length + 1] && safety_counter < MAX_ITERATIONS) {
        container->length++;
        container->digits[container->length + 1] += container->digits[container->length] / 10;
        container->digits[container->length] %= 10;
        safety_counter++;
    }
}

