struct BigNumberValidationResult {
    bool isValid;
    string errorMessage;
};

class BigNumberProcessor {
private:
    int digits[MAX_LENGTH + 2] = {0};
    int length = 0;
    bool isProcessed = false;

    BigNumberValidationResult validateInput(const string& input) {
        BigNumberValidationResult result;
        result.isValid = true;

        if (input.empty()) {
            result.isValid = false;
            result.errorMessage = "Empty input string";
            return result;
        }

        if (input.size() > MAX_LENGTH) {
            result.isValid = false;
            result.errorMessage = "Input exceeds maximum length";
            return result;
        }

        if (input[0] == '0' && input.size() > 1) {
            result.isValid = false;
            result.errorMessage = "Leading zeros are not allowed";
            return result;
        }

        for (char c : input) {
            if (!isdigit(c)) {
                result.isValid = false;
                result.errorMessage = "Non-digit character found";
                return result;
            }
        }

        return result;
    }

    void initializeDigits(const string& numStr) {
        length = numStr.length();
        for (int i = 0; i < length; ++i) {
            if (!isdigit(numStr[length - 1 - i])) {
                throw runtime_error("Invalid digit during initialization");
            }
            digits[i + 1] = numStr[length - 1 - i] - '0';
        }
    }

    void handleSmallNumberCase() {
        if (length <= MAX_SAFE_INTEGER_DIGITS) {
            unsigned long long smallValue = 0;
            for (int i = length; i >= 1; --i) {
                smallValue = smallValue * 10 + digits[i];
            }
            smallValue += ADDEND;
            string temp = to_string(smallValue);
            initializeDigits(temp);
            isProcessed = true;
        }
    }

    void performAddition() {
        if (isProcessed) return;

        digits[1] += ADDEND;
        for (int i = 1; i <= length; ++i) {
            if (digits[i] >= 10) {
                digits[i + 1] += digits[i] / 10;
                digits[i] %= 10;
                if (i == length) {
                    length++;
                }
            }
        }

        while (digits[length + 1] > 0) {
            length++;
            if (digits[length] >= 10) {
                digits[length + 1] += digits[length] / 10;
                digits[length] %= 10;
            }
        }
        isProcessed = true;
    }

public:
    void processNumber(const string& numStr) {
        auto validation = validateInput(numStr);
        if (!validation.isValid) {
            throw invalid_argument(validation.errorMessage);
        }

        initializeDigits(numStr);
        handleSmallNumberCase();
        performAddition();
    }

    string getResult() {
        if (!isProcessed) {
            throw logic_error("Number not processed yet");
        }

        string result;
        for (int i = length; i >= 1; --i) {
            result += to_string(digits[i]);
        }
        return result;
    }
};

int main() {
    try {
        ifstream inputFile("bigadd.in");
        ofstream outputFile("bigadd.out");

        if (!inputFile.is_open()) {
            throw runtime_error("Failed to open input file");
        }

        if (!outputFile.is_open()) {
            throw runtime_error("Failed to open output file");
        }

