            result.isValid = false;
            result.errorMessage = "Empty input detected";
            return result;
        }

        if (input.size() > MAX_DIGITS) {
            result.isValid = false;
            result.errorMessage = "Input exceeds maximum digit limit";
            return result;
        }

        for (char c : input) {
            if (!isdigit(c)) {
                result.isValid = false;
                result.errorMessage = "Non-digit character found";
                return result;
            }
        }

        if (input[0] == '0' && input.size() > 1) {
            result.isValid = false;
            result.errorMessage = "Leading zeros are not allowed";
            return result;
        }

        return result;
    }

