        int newLength = length;
        while (digits[newLength + 1] != 0) {
            newLength++;
            if (newLength >= MAX_DIGITS + MAX_CARRY) {
                throw runtime_error("Result exceeds maximum digit capacity");
            }
        }
        length = newLength;
    }

    string buildResultString() {
        string result;
        for (int i = length; i >= 1; i--) {
            result += to_string(digits[i]);
        }
        return result;
    }

