#include<bits/stdc++.h>
using namespace std;

const int MAX_NODES = 1005;
vector<int> G[MAX_NODES];
int t, n, x, y, fa[MAX_NODES], cnt = 0;
int degree_cache[MAX_NODES];
bool visited[MAX_NODES];
int parent_degree_cache[MAX_NODES];
int child_degree_cache[MAX_NODES][MAX_NODES];

void initialize_globals() {
    memset(fa, 0, sizeof(fa));
    memset(degree_cache, 0, sizeof(degree_cache));
    memset(visited, false, sizeof(visited));
    memset(parent_degree_cache, 0, sizeof(parent_degree_cache));
    memset(child_degree_cache, 0, sizeof(child_degree_cache));
    for(int i = 0; i < MAX_NODES; i++) {
        G[i].clear();
        vector<int>().swap(G[i]);
    }
}

void precompute_degrees() {
    for(int i = 0; i < n; i++) {
        degree_cache[i] = G[i].size();
        if(fa[i] != i) {
            parent_degree_cache[i] = G[fa[i]].size();
        }
        for(size_t j = 0; j < G[i].size(); j++) {
            child_degree_cache[i][j] = G[G[i][j]].size();
        }
    }
}

bool validate_node(int node) {
    if(node < 0 || node >= n) return false;
    if(visited[node]) return false;
    visited[node] = true;
    return true;
}

bool check_parent_condition(int node) {
    if(fa[node] == node) return true;
    if(!validate_node(fa[node])) return false;
    return degree_cache[node] >= parent_degree_cache[node];
}

bool check_children_condition(int node) {
    for(size_t i = 0; i < G[node].size(); i++) {
        int child = G[node][i];
        if(!validate_node(child)) continue;
        if(degree_cache[node] < child_degree_cache[node][i]) {
            return false;
        }
    }
    return true;
}

bool is_p_node(int node) {
    if(!validate_node(node)) return false;
    bool parent_ok = check_parent_condition(node);
    bool children_ok = check_children_condition(node);
    return parent_ok && children_ok;
}

void process_test_case() {
    initialize_globals();
    cnt = 0;
    cin >> n;
    if(n < 1 || n > 1000) return;
    for(int i = 0; i < n - 1; i++) {
        cin >> x >> y;
        if(x < 0 || x >= n || y < 0 || y >= n) continue;
        G[x].push_back(y);
        fa[y] = x;
    }
    precompute_degrees();
    for(int i = 0; i < n; i++) {
        memset(visited, false, sizeof(visited));
        if(is_p_node(i)) {
            cnt++;
        }
    }
    cout << cnt << endl;
}

int main() {
    freopen("p.in", "r", stdin);
    freopen("p.out", "w", stdout);
    cin >> t;
    if(t < 1 || t > 100) return 0;
    while(t--) {
        process_test_case();
    }
    return 0;
}
