#include <bits/stdc++.h>
using namespace std;
const int maxn = 1005;
vector <int> G[maxn];
int fa[maxn];
int degree_cache[maxn];
bool validation_flag[maxn];
vector<int> temp_storage;
unordered_set<int> processed_nodes;

void initialize_structures(int n) {
    for(int i = 0; i < maxn; i++) {
        G[i].clear();
        fa[i] = 0;
        degree_cache[i] = 0;
        validation_flag[i] = false;
    }
    temp_storage.clear();
    processed_nodes.clear();
}

void precompute_degrees(int n) {
    for(int i = 0; i < n; i++) {
        degree_cache[i] = G[i].size();
    }
}

bool validate_parent_condition(int node) {
    if(fa[node] != node) {
        if(degree_cache[node] < degree_cache[fa[node]]) {
            return false;
        }
    }
    return true;
}

bool validate_children_condition(int node) {
    for(size_t j = 0; j < G[node].size(); j++) {
        int child = G[node][j];
        if(degree_cache[node] < degree_cache[child]) {
            return false;
        }
    }
    return true;
}

void process_test_case(int n, int &result) {
    int local_counter = 0;
    for(int i = 0; i < n; i++) {
        bool parent_valid = true;
        bool children_valid = true;

        if(processed_nodes.find(i) != processed_nodes.end()) {
            continue;
        }

        parent_valid = validate_parent_condition(i);
        children_valid = validate_children_condition(i);

        if(parent_valid && children_valid) {
            validation_flag[i] = true;
            temp_storage.push_back(i);
        }
        processed_nodes.insert(i);
    }

    for(int i = 0; i < n; i++) {
        if(validation_flag[i]) {
            local_counter++;
        }
    }

    result += local_counter;
}

int main(){
    ifstream input_file("p.in");
    ofstream output_file("p.out");

    if(!input_file.is_open() || !output_file.is_open()) {
        cerr << "File opening failed" << endl;
        return EXIT_FAILURE;
    }

    int t, global_result = 0;
    input_file >> t;

    for(int test_case = 0; test_case < t; test_case++) {
        int n;
        input_file >> n;

        initialize_structures(n);

        for(int i = 0; i < n - 1; i++) {
            int u, v;
            input_file >> u >> v;
            if(u < 0 || u >= n || v < 0 || v >= n) {
                continue;
            }
            G[u].push_back(v);
            fa[v] = u;
        }

        precompute_degrees(n);

        int case_result = 0;
        process_test_case(n, case_result);

        output_file << case_result << endl;
        global_result += case_result;
    }

    input_file.close();
    output_file.close();
    return 0;
}
