    }

    static bool validateMonth(int m) {
        return m >= 1 && m <= 12;
    }

    static void validateInput(int y, int m) {
        vector<string> errors;
        if (!validateYear(y)) {
            stringstream ss;
            ss << "Year " << y << " is out of valid range (1600-3000)";
            errors.push_back(ss.str());
        }
        if (!validateMonth(m)) {
            stringstream ss;
            ss << "Month " << m << " is invalid (1-12)";
            errors.push_back(ss.str());
        }
        if (!errors.empty()) {
            string error_msg = "Validation errors:\n";
            for (const auto& e : errors) {
                error_msg += e + "\n";
            }
            throw runtime_error(error_msg);
        }
    }
};

class LeapYearCalculator {
public:
    static bool isLeapYear(int y) {
        if (y % 4 != 0) {
            return false;
        } else if (y % 100 != 0) {
            return true;
        } else {
            return y % 400 == 0;
        }
    }
};

class MonthDaysCalculator {
private:
    static const vector<int> LONG_MONTHS;
    static const vector<int> SHORT_MONTHS;

    static bool contains(const vector<int>& vec, int val) {
        return find(vec.begin(), vec.end(), val) != vec.end();
    }

public:
    static int getDays(int y, int m) {
        if (contains(LONG_MONTHS, m)) {
            return 31;
        } else if (contains(SHORT_MONTHS, m)) {
