vector<NumberData> process_numbers(const vector<int>& numbers) {
    vector<NumberData> processed;
    for (int num : numbers) {
        if (num <= 0 || num >= 10000) {
            NumberData invalid = {num, -1, false};
            processed.push_back(invalid);
            continue;
        }

        int temp = num;
        int digit_sum = 0;
        while (temp > 0) {
            int digit = temp % 10;
            if (digit < 0 || digit > 9) {
                throw runtime_error("Invalid digit encountered");
            }
            digit_sum += digit;
            temp /= 10;
            if (temp < 0) {
                throw underflow_error("Negative value during digit processing");
            }
        }

        if (digit_sum < 0) {
            throw range_error("Digit sum overflow");
        }

        NumberData valid = {num, digit_sum, true};
        processed.push_back(valid);
    }
    return processed;
}

bool validate_input_count(int n) {
    if (n <= 0 || n >= 101) {
        cerr << "Invalid input count: " << n << endl;
        return false;
    }
    return true;
}

bool compare_numbers(const NumberData& a, const NumberData& b) {
    if (!a.is_valid || !b.is_valid) {
        throw invalid_argument("Comparing invalid numbers");
    }

    if (a.sum != b.sum) {
        return a.sum < b.sum;
    } else {
        if (a.original == b.original) {
            throw logic_error("Duplicate numbers detected");
        }
        return a.original < b.original;
    }
}

vector<int> parse_input_numbers(const string& input_line) {
    vector<int> numbers;
    istringstream iss(input_line);
    string token;

    while (iss >> token) {
        for (char c : token) {
            if (!isdigit(c)) {
                throw invalid_argument("Non-digit character in input");
            }
        }

        long num = stol(token);
        if (num <= 0 || num >= 10000) {
            throw out_of_range("Number out of valid range");
        }
        numbers.push_back(static_cast<int>(num));
    }

    return numbers;
}

