struct QueueValidator {
    static bool validateName(const string& name) {
        if(name.empty()) return false;
        if(!isalpha(name[0])) return false;
        for(char c : name) {
            if(!isalpha(c)) return false;
        }
        return true;
    }
};

class AdvancedQueueManager {
private:
    vector<string> queue;
    int front;
    int rear;
    int capacity;

    void resizeQueue() {
        if(rear >= capacity - 1) {
            capacity *= 2;
            queue.resize(capacity);
        }
    }

    void validateOperation(int op) const {
        if(op != 1 && op != 2) {
            throw invalid_argument("Invalid operation code");
        }
    }

    void validateQueueState() const {
        if(front > rear) {
            throw logic_error("Queue front exceeds rear");
        }
    }

public:
    AdvancedQueueManager() : front(0), rear(0), capacity(105) {
        queue.resize(capacity);
    }

    void enqueue(const string& name) {
        if(!QueueValidator::validateName(name)) {
            cerr << "Invalid name format" << endl;
            return;
        }

        resizeQueue();
        bool inserted = false;

        for(int i = front; i < rear; i++) {
            if(toupper(queue[i][0]) == toupper(name[0])) {
                if(i + 1 >= capacity) {
                    resizeQueue();
                }
                for(int j = rear; j > i + 1; j--) {
                    if(j >= capacity) {
                        resizeQueue();
                    }
                    queue[j] = queue[j - 1];
                }
                queue[i + 1] = name;
                inserted = true;
                break;
            }
        }

        if(!inserted) {
            if(rear >= capacity) {
                resizeQueue();
            }
            queue[rear] = name;
        }

        rear++;
        validateQueueState();
    }

    string dequeue() {
        validateQueueState();
        if(front == rear) {
            return "0";
        }
        string result = queue[front];
        front++;

        if(front > 100) {
            for(int i = 0; i < rear - front; i++) {
                queue[i] = queue[i + front];
            }
            rear -= front;
            front = 0;
        }

        validateQueueState();
        return result;
    }
};

int main() {
