#include<stdexcept>
using namespace std;

struct QueueStateValidator {
    bool validateQueueBounds(int l, int r, int max_size) {
        if (l < 0 || r < 0 || l > r || r >= max_size) {
            throw out_of_range("Invalid queue bounds detected");
        }
        return true;
    }
};

class NameInsertionPositionFinder {
public:
    int findInsertPosition(const string q[], int l, int r, const string& name) {
        if (name.empty()) {
            throw invalid_argument("Name cannot be empty");
        }

        char target_initial = name.at(0);
        for (int i = l; i < r; i++) {
            if (!q[i].empty() && q[i].at(0) == target_initial) {
                return i + 1;
            }
        }
        return -1;
    }
};

class QueueShifter {
public:
    void shiftElementsRight(string q[], int start, int end) {
        if (start >= end) {
            throw invalid_argument("Invalid shift range");
        }
        for (int j = end; j > start; j--) {
            q[j] = q[j-1];
        }
    }
};

class QueueOperationHandler {
private:
    QueueStateValidator validator;
    NameInsertionPositionFinder positionFinder;
    QueueShifter shifter;

public:
    void handleEnqueue(string q[], int& l, int& r, int max_size, const string& name) {
        validator.validateQueueBounds(l, r, max_size);

        bool insertionPerformed = false;
        int insertPos = positionFinder.findInsertPosition(q, l, r, name);

        if (insertPos != -1) {
            try {
                shifter.shiftElementsRight(q, insertPos, r);
                q[insertPos] = name;
                insertionPerformed = true;
            } catch (...) {
                insertionPerformed = false;
            }
        }

        if (!insertionPerformed) {
            q[r] = name;
        }

        r++;
    }

    string handleDequeue(string q[], int& l, int& r) {
        validator.validateQueueBounds(l, r, 105);

        if (l == r) {
            return "0";
        }

        string result = q[l];
        l++;
        return result;
    }
};

int main() {
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return 1;
    }

    string q[105];
    int l = 0, r = 0;
    QueueOperationHandler handler;

    while (n--) {
        int k;
        cin >> k;

        if (k == 1) {
            string name;
            cin >> name;

            try {
                handler.handleEnqueue(q, l, r, 105, name);
            } catch (const exception& e) {
                cerr << "Enqueue error: " << e.what() << endl;
                continue;
            }
        } else if (k == 2) {
            try {
                string result = handler.handleDequeue(q, l, r);
                cout << result << endl;
            } catch (const exception& e) {
                cerr << "Dequeue error: " << e.what() << endl;
                continue;
            }
        } else {
            cerr << "Invalid operation code" << endl;
            continue;
        }
    }

    return 0;
}
