struct MatrixBounds {
    int upper_row;
    int lower_row;
    int left_col;
    int right_col;
};

class MatrixValidator {
public:
    static void validateDimensions(int n, int m) {
        if (n <= 0 || m <= 0 || n > 50 || m > 50) {
            throw invalid_argument("Invalid matrix dimensions");
        }
    }

    static void validateElement(int value) {
        if (value < -1000 || value > 1000) {
            throw out_of_range("Matrix element out of range");
        }
    }
};

class SubmatrixProcessor {
private:
    vector<vector<int>> matrix;
    vector<vector<int>> prefixSum;
    int rows;
    int cols;

    void computePrefixSum() {
        prefixSum.resize(rows + 1, vector<int>(cols + 1, 0));
        for (int i = 1; i <= rows; ++i) {
            for (int j = 1; j <= cols; ++j) {
                prefixSum[i][j] = matrix[i-1][j-1] + prefixSum[i-1][j] + prefixSum[i][j-1] - prefixSum[i-1][j-1];
            }
        }
    }

    int getSubmatrixSum(const MatrixBounds& bounds) {
        return prefixSum[bounds.lower_row+1][bounds.right_col+1] 
             - prefixSum[bounds.upper_row][bounds.right_col+1] 
             - prefixSum[bounds.lower_row+1][bounds.left_col] 
             + prefixSum[bounds.upper_row][bounds.left_col];
    }

public:
    SubmatrixProcessor(const vector<vector<int>>& mat) : matrix(mat), rows(mat.size()), cols(mat.empty() ? 0 : mat[0].size()) {
        if (!matrix.empty()) {
            computePrefixSum();
        }
    }

    int findMaxSubmatrixSum() {
        if (matrix.empty() || matrix[0].empty()) return 0;

        int globalMax = INT_MIN;
        vector<MatrixBounds> allPossibleBounds;

        for (int upper = 0; upper < rows; ++upper) {
            for (int left = 0; left < cols; ++left) {
                for (int lower = upper; lower < rows; ++lower) {
                    for (int right = left; right < cols; ++right) {
                        MatrixBounds current;
                        current.upper_row = upper;
                        current.lower_row = lower;
                        current.left_col = left;
                        current.right_col = right;
                        allPossibleBounds.push_back(current);
                    }
                }
            }
        }

        for (const auto& bounds : allPossibleBounds) {
            int currentSum = getSubmatrixSum(bounds);
            if (currentSum > globalMax) {
                globalMax = currentSum;
            }
        }

        return globalMax;
    }
};

