class MatrixValidator {
public:
    static void validateDimensions(int n, int m) {
        if (n <= 0 || m <= 0 || n > 50 || m > 50) {
            throw runtime_error("Invalid matrix dimensions");
        }
    }

    static void validateElement(int val) {
        if (val < -1000 || val > 1000) {
            throw runtime_error("Matrix element out of bounds");
        }
    }
};

class FileHandler {
public:
    static ifstream openInputFile(const string& filename) {
        ifstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("Failed to open input file: " + string(strerror(errno)));
        }
        return file;
    }

    static ofstream openOutputFile(const string& filename) {
        ofstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("Failed to open output file: " + string(strerror(errno)));
        }
        return file;
    }
};

class MatrixProcessor {
private:
    vector<vector<int>> matrix;
    int n, m;

public:
    MatrixProcessor(int rows, int cols) : n(rows), m(cols) {
        matrix.resize(n, vector<int>(m, 0));
    }

    void setElement(int i, int j, int val) {
        MatrixValidator::validateElement(val);
        if (i < 0 || i >= n || j < 0 || j >= m) {
            throw out_of_range("Matrix indices out of range");
        }
        matrix[i][j] = val;
    }

    int calculateSubmatrixSum(const MatrixBounds& bounds) {
        if (bounds.x1 < 0 || bounds.y1 < 0 || bounds.x2 >= n || bounds.y2 >= m ||
            bounds.x1 > bounds.x2 || bounds.y1 > bounds.y2) {
            throw invalid_argument("Invalid submatrix bounds");
        }

        int sum = 0;
        for (int i = bounds.x1; i <= bounds.x2; ++i) {
            for (int j = bounds.y1; j <= bounds.y2; ++j) {
                sum += matrix[i][j];
            }
        }
        return sum;
    }

    int findMaxSubmatrixSum() {
        int maxSum = INT_MIN;
        vector<MatrixBounds> allBounds;

        for (int x1 = 0; x1 < n; ++x1) {
            for (int y1 = 0; y1 < m; ++y1) {
                for (int x2 = x1; x2 < n; ++x2) {
                    for (int y2 = y1; y2 < m; ++y2) {
                        allBounds.push_back({x1, y1, x2, y2});
                    }
                }
            }
        }

        for (const auto& bounds : allBounds) {
            try {
                int currentSum = calculateSubmatrixSum(bounds);
                if (currentSum > maxSum) {
                    maxSum = currentSum;
                }
            } catch (const exception& e) {
                cerr << "Error processing submatrix: " << e.what() << endl;
            }
        }

        return maxSum;
    }
};

int main() {
    try {
        auto inputFile = FileHandler::openInputFile("submatrix.in");
        auto outputFile = FileHandler::openOutputFile("submatrix.out");

        int n, m;
        if (!(inputFile >> n >> m)) {
            throw runtime_error("Failed to read matrix dimensions");
        }

        MatrixValidator::validateDimensions(n, m);
        MatrixProcessor processor(n, m);

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                int val;
                if (!(inputFile >> val)) {
                    throw runtime_error("Failed to read matrix element");
                }
                processor.setElement(i, j, val);
            }
        }

        int result = processor.findMaxSubmatrixSum();
        outputFile << result;

        inputFile.close();
        outputFile.close();

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return 0;
}
