struct FactorialState {
    int digits[MAX_DIGITS];
    int length;
    bool error_flag;
};

struct SumState {
    int digits[MAX_DIGITS];
    int length;
    bool overflow_detected;
};

void initializeState(FactorialState& state) {
    memset(state.digits, 0, sizeof(state.digits));
    state.length = 1;
    state.error_flag = false;
}

void initializeSumState(SumState& state) {
    memset(state.digits, 0, sizeof(state.digits));
    state.length = 1;
    state.overflow_detected = false;
}

void multiplyFactorial(FactorialState& state, int factor) {
    if (factor < 0 || factor > MAX_ITERATIONS) {
        state.error_flag = true;
        return;
    }

    for (int j = 0; j < state.length; j++) {
        state.digits[j] *= factor;
    }

    for (int j = 0; j < state.length; j++) {
        if (state.digits[j] >= 10) {
            state.digits[j+1] += state.digits[j] / 10;
            state.digits[j] %= 10;
        }
    }

    while (state.digits[state.length] > 0) {
        if (state.length >= MAX_DIGITS - 1) {
            state.error_flag = true;
            break;
        }
        state.length++;
        if (state.digits[state.length-1] >= 10) {
            state.digits[state.length] += state.digits[state.length-1] / 10;
            state.digits[state.length-1] %= 10;
        }
    }
}

void addToSum(SumState& sum, const FactorialState& fact) {
    if (fact.error_flag) {
        sum.overflow_detected = true;
        return;
    }

    int max_len = max(sum.length, fact.length);
    for (int j = 0; j < max_len; j++) {
        sum.digits[j] += fact.digits[j];
        if (sum.digits[j] >= 10) {
            sum.digits[j+1] += sum.digits[j] / 10;
            sum.digits[j] %= 10;
        }
    }

    sum.length = max_len;
    while (sum.digits[sum.length] > 0) {
        if (sum.length >= MAX_DIGITS - 1) {
            sum.overflow_detected = true;
            break;
        }
        sum.length++;
        if (sum.digits[sum.length-1] >= 10) {
            sum.digits[sum.length] += sum.digits[sum.length-1] / 10;
            sum.digits[sum.length-1] %= 10;
        }
    }
}

