#include <iostream>
#include <vector>
#include <stdexcept>
#include <cctype>
using namespace std;

class CharacterValidator {
public:
    static bool isValidAlphabetUpper(char c) {
        return c >= 'A' && c <= 'Z';
    }
    static bool isValidAlphabetLower(char c) {
        return c >= 'a' && c <= 'z';
    }
    static bool isValidDigit(char c) {
        return c >= '0' && c <= '9';
    }
};

class CyclicShifter {
private:
    static char shiftUpperCase(char c, int shift) {
        if (!CharacterValidator::isValidAlphabetUpper(c)) {
            throw invalid_argument("Invalid uppercase character");
        }
        int normalizedShift = shift % 26;
        if (normalizedShift < 0) normalizedShift += 26;
        return 'A' + (c - 'A' + normalizedShift) % 26;
    }
    static char shiftLowerCase(char c, int shift) {
        if (!CharacterValidator::isValidAlphabetLower(c)) {
            throw invalid_argument("Invalid lowercase character");
        }
        int normalizedShift = shift % 26;
        if (normalizedShift < 0) normalizedShift += 26;
        return 'a' + (c - 'a' + normalizedShift) % 26;
    }
    static char shiftDigit(char c, int shift) {
        if (!CharacterValidator::isValidDigit(c)) {
            throw invalid_argument("Invalid digit character");
        }
        int normalizedShift = shift % 10;
        if (normalizedShift < 0) normalizedShift += 10;
        return '0' + (c - '0' + normalizedShift) % 10;
    }
public:
    static char shiftCharacter(char c, int shift) {
        try {
            if (CharacterValidator::isValidAlphabetUpper(c)) {
                return shiftUpperCase(c, shift);
            } else if (CharacterValidator::isValidAlphabetLower(c)) {
                return shiftLowerCase(c, shift);
            } else if (CharacterValidator::isValidDigit(c)) {
                return shiftDigit(c, shift);
            } else {
                throw invalid_argument("Unsupported character type");
            }
        } catch (const exception& e) {
            cerr << "Error shifting character: " << e.what() << endl;
            return c;
        }
    }
};

class InputSanitizer {
public:
    static void validateInputParameters(int x, int y, int z) {
        if (x <= 10 || x > 100) {
            throw invalid_argument("Invalid x value");
        }
        if (y <= 0 || y > 10) {
            throw invalid_argument("Invalid y value");
        }
        if (z <= 0 || z > 100) {
            throw invalid_argument("Invalid z value");
        }
    }
};

class PositionAnalyzer {
public:
    static bool isKeyPosition(int position, int y) {
        if (y <= 0) return false;
        return position % y == 0;
    }
};

