class TalentShowAnalyzer {
private:
    vector<Performance> performances;
    int total_time_minutes;
    int current_time;
    bool garlic_performed;
    bool garlic_driven_off;

public:
    TalentShowAnalyzer(int hours) : total_time_minutes(hours * 60), current_time(0), garlic_performed(false), garlic_driven_off(false) {}

    void processInput() {
        string input_name;
        int input_duration;
        string next_token;
        bool previous_driven_off = false;

        while (true) {
            if (!(cin >> input_name)) {
                break;
            }

            if (input_name == "tingtingting") {
                if (!performances.empty()) {
                    performances.back().driven_off = true;
                    current_time -= performances.back().duration;
                }
                previous_driven_off = true;
                continue;
            }

            if (!(cin >> input_duration)) {
                break;
            }

            Performance p;
            p.name = input_name;
            p.duration = input_duration;
            p.driven_off = false;

            if (previous_driven_off) {
                p.driven_off = true;
                previous_driven_off = false;
            }

            performances.push_back(p);
            current_time += input_duration;

            if (p.name == "kaomianjin") {
                garlic_performed = true;
                if (p.driven_off) {
                    garlic_driven_off = true;
                }
                break;
            }

            if (current_time > total_time_minutes) {
                break;
            }
        }
    }

    string getResult() {
        if (garlic_performed) {
            if (garlic_driven_off) {
                return "Hahaha.";
            } else if (current_time <= total_time_minutes) {
                return "Congratulations!";
            } else {
                return "Unfortunately.";
            }
        } else {
            if (current_time <= total_time_minutes) {
                for (const auto& p : performances) {
                    if (p.name == "kaomianjin") {
                        if (p.driven_off) {
                            return "Hahaha.";
                        } else {
                            return "Congratulations!";
                        }
                    }
                }
            }
            return "Unfortunately.";
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int audition_hours;
    if (!(cin >> audition_hours)) {
        cout << "Unfortunately." << endl;
        return 1;
    }

    if (audition_hours < 1 || audition_hours > 100) {
        cout << "Invalid input." << endl;
        return 1;
    }

    TalentShowAnalyzer analyzer(audition_hours);
    analyzer.processInput();
    cout << analyzer.getResult() << endl;

    return 0;
}
