using namespace std;

struct CharacterProcessor {
    static char processLowercase(char c, int shift) {
        if(!islower(c)) throw invalid_argument("Not lowercase");
        int normalizedShift = shift % 26;
        if(normalizedShift < 0) normalizedShift += 26;
        int newPos = (c - 'a' + normalizedShift) % 26;
        return 'a' + newPos;
    }

    static char processUppercase(char c, int shift) {
        if(!isupper(c)) throw invalid_argument("Not uppercase");
        int normalizedShift = shift % 26;
        if(normalizedShift < 0) normalizedShift += 26;
        int newPos = (c - 'A' + normalizedShift) % 26;
        return 'A' + newPos;
    }

    static char processDigit(char c, int shift) {
        if(!isdigit(c)) throw invalid_argument("Not digit");
        int normalizedShift = shift % 10;
        if(normalizedShift < 0) normalizedShift += 10;
        int newPos = (c - '0' + normalizedShift) % 10;
        return '0' + newPos;
    }
};

int main(){
    int x, y, z;
