using namespace std;

namespace TankBattleUtils {
    template<typename T>
    constexpr bool is_valid_time_type = is_integral_v<T> && !is_same_v<T, bool>;

    template<typename T, enable_if_t<is_valid_time_type<T>, int> = 0>
    void validate_time_range(T time) {
        constexpr T min_time = 1;
        constexpr T max_time = 100;
        if (time < min_time || time > max_time) {
            throw out_of_range("Invalid time range");
        }
    }

    template<typename T, enable_if_t<is_valid_time_type<T>, int> = 0>
    void validate_road_condition(T condition) {
        constexpr T min_condition = 1;
        constexpr T max_condition = 50;
        if (condition < min_condition || condition > max_condition) {
            throw out_of_range("Invalid road condition");
        }
    }
}

class TankSimulator {
private:
    int remaining_time;
    vector<int> road_conditions;
    bool reached_endpoint;
    bool time_exhausted;

    void process_road_condition(int condition) {
        using namespace TankBattleUtils;
        validate_road_condition(condition);

        if (time_exhausted || reached_endpoint) return;

        switch (condition) {
            case 6:
                break;
            case 7:
                remaining_time -= 5;
                break;
            case 12:
                remaining_time -= 20;
                break;
            case 15:
                reached_endpoint = true;
                break;
            default: {
                int time_deduction = 2;
                if (condition % 2 == 0) {
                    time_deduction += condition % 3;
                }
                remaining_time -= time_deduction;
            }
        }

        if (remaining_time <= 0 && !reached_endpoint) {
            time_exhausted = true;
        }
    }

public:
    TankSimulator(int initial_time, const vector<int>& conditions) 
        : remaining_time(initial_time), road_conditions(conditions), 
          reached_endpoint(false), time_exhausted(false) {
        using namespace TankBattleUtils;
        validate_time_range(initial_time);
        for (auto cond : conditions) {
            validate_road_condition(cond);
        }
    }

    string run_simulation() {
        for (size_t i = 0; i < road_conditions.size(); ++i) {
            if (time_exhausted || reached_endpoint) break;
            try {
                process_road_condition(road_conditions[i]);
            } catch (const exception& e) {
                cerr << "Error processing condition: " << e.what() << endl;
                return "NO";
            }
        }

        if (reached_endpoint && remaining_time >= 0) {
            return "YES";
        } else if (time_exhausted) {
            return "NO";
        } else if (remaining_time <= 0) {
            return "NO";
        } else {
            return "NO";
        }
    }
};

int main() {
