#include<bits/stdc++.h>
using namespace std;

int validateInput(int value, int minVal, int maxVal) {
    if (value < minVal || value > maxVal) {
        return -1;
    }
    return value;
}

bool isSpecialCondition(int code) {
    return (code == 6 || code == 7 || code == 12 || code == 15);
}

int handleSpecialCondition(int code, int currentTime) {
    switch(code) {
        case 6:
            return currentTime;
        case 7:
            return currentTime - 5;
        case 12:
            return currentTime - 20;
        case 15:
            return currentTime;
        default:
            return currentTime - 2;
    }
}

