#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <cstdlib>
using namespace std;

struct DataSet {
    int x;
    int y;
    int index;
    int difference;
    int minimum;
};

void validateInputRange(int value, int minVal, int maxVal, const string& message) {
    if (value < minVal || value > maxVal) {
        stringstream ss;
        ss << "Invalid input: " << message << " must be between " << minVal << " and " << maxVal;
        throw runtime_error(ss.str());
    }
}

DataSet calculateSetProperties(int x, int y, int index) {
    DataSet ds;
    ds.x = x;
    ds.y = y;
    ds.index = index;
    ds.difference = abs(x - y);
    ds.minimum = min(x, y);
    return ds;
}

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.difference != b.difference) {
        return a.difference > b.difference;
    } else if (a.minimum != b.minimum) {
        return a.minimum < b.minimum;
    } else {
        return a.index < b.index;
    }
}

int main() {
    try {
        int n;
        cin >> n;
        validateInputRange(n, 1, 100, "Number of data sets");

        vector<DataSet> dataSets;
        dataSets.reserve(n);

        for (int i = 0; i < n; ++i) {
            int x, y;
            if (!(cin >> x >> y)) {
                throw runtime_error("Invalid input format");
            }
            validateInputRange(x, 1, 20, "X value");
            validateInputRange(y, 1, 20, "Y value");
            dataSets.push_back(calculateSetProperties(x, y, i));
        }

        if (dataSets.empty()) {
            throw runtime_error("No data sets provided");
        }

        sort(dataSets.begin(), dataSets.end(), compareDataSets);

        DataSet bestSet = dataSets.front();
        for (const auto& ds : dataSets) {
            if (ds.difference == bestSet.difference && 
                ds.minimum == bestSet.minimum && 
                ds.index < bestSet.index) {
                bestSet = ds;
            }
        }

        cout << bestSet.x << " " << bestSet.y << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
