#include<bits/stdc++.h>
using namespace std;

struct NodeMetadata {
    int degree;
    vector<int> children;
    int parent;
    bool has_parent;
};

vector<NodeMetadata> initialize_node_metadata(int n) {
    vector<NodeMetadata> nodes(n);
    for (int i = 0; i < n; ++i) {
        nodes[i].degree = 0;
        nodes[i].has_parent = false;
        nodes[i].parent = -1;
    }
    return nodes;
}

void process_tree_edges(vector<NodeMetadata>& nodes, int n) {
    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        if (!(cin >> x >> y)) {
            cerr << "Error reading edge data" << endl;
            exit(1);
        }
        if (x < 0 || x >= n || y < 0 || y >= n) {
            cerr << "Invalid node index in edge data" << endl;
            exit(1);
        }
        nodes[x].degree++;
        nodes[y].degree++;
        nodes[x].children.push_back(y);
        nodes[y].parent = x;
        nodes[y].has_parent = true;
    }
}

bool validate_node_degrees(const vector<NodeMetadata>& nodes) {
    for (const auto& node : nodes) {
        if (node.degree < 0) {
            cerr << "Negative degree detected" << endl;
            return false;
        }
    }
    return true;
}

bool is_p_node(const vector<NodeMetadata>& nodes, int index) {
    const auto& current_node = nodes[index];
    bool condition_satisfied = true;

    for (int child : current_node.children) {
        if (nodes[child].degree > current_node.degree) {
            condition_satisfied = false;
            break;
        }
    }

    if (current_node.has_parent) {
        if (nodes[current_node.parent].degree > current_node.degree) {
            condition_satisfied = false;
        }
    }

    return condition_satisfied;
}

int count_p_nodes(const vector<NodeMetadata>& nodes) {
    int count = 0;
    for (size_t i = 0; i < nodes.size(); ++i) {
        if (is_p_node(nodes, i)) {
            count++;
        }
    }
    return count;
}

void handle_test_case(int case_num) {
    int n;
    if (!(cin >> n)) {
        cerr << "Error reading node count" << endl;
        exit(1);
    }
    if (n < 1 || n > 1000) {
        cerr << "Invalid node count" << endl;
        exit(1);
    }

    vector<NodeMetadata> nodes = initialize_node_metadata(n);
    process_tree_edges(nodes, n);

    if (!validate_node_degrees(nodes)) {
        cerr << "Degree validation failed" << endl;
        exit(1);
    }

    int p_count = count_p_nodes(nodes);
    cout << p_count << endl;
}

int main() {
