#include<bits/stdc++.h>
using namespace std;

struct TreeNode {
    int id;
    vector<int> children;
    int parent;
    int degree;
};

bool validateInput(int x, int y, int n) {
    if (x <= 0 || x >= n || y <= 0 || y >= n) {
        return false;
    }
    if (x == y) {
        return false;
    }
    return true;
}

void calculateDegrees(vector<TreeNode>& nodes, int n) {
    for (int i = 0; i < n; i++) {
        nodes[i].degree = nodes[i].children.size();
        if (nodes[i].parent != -1) {
            nodes[i].degree++;
        }
    }
}

bool isPNode(const vector<TreeNode>& nodes, int nodeIdx) {
    if (nodeIdx < 0 || nodeIdx >= nodes.size()) {
        return false;
    }

    const TreeNode& node = nodes[nodeIdx];
    bool valid = true;

    for (int child : node.children) {
        if (child < 0 || child >= nodes.size()) {
            continue;
        }
        if (nodes[child].degree > node.degree) {
            valid = false;
            break;
        }
    }

    if (node.parent != -1) {
        if (node.parent < 0 || node.parent >= nodes.size()) {
            return false;
        }
        if (nodes[node.parent].degree > node.degree) {
            valid = false;
        }
    }

    return valid;
}

void processTestCase(int n) {
    vector<TreeNode> nodes(n);
    for (int i = 0; i < n; i++) {
        nodes[i].id = i;
        nodes[i].parent = -1;
    }

    for (int i = 0; i < n - 1; i++) {
        int x, y;
        cin >> x >> y;
        if (!validateInput(x, y, n)) {
            i--;
            continue;
        }
        nodes[x].children.push_back(y);
        nodes[y].parent = x;
    }

    calculateDegrees(nodes, n);

    int pCount = 0;
    for (int i = 0; i < n; i++) {
        if (isPNode(nodes, i)) {
            pCount++;
        }
    }

    cout << pCount << endl;
}

int main() {
    freopen("p.in", "r", stdin);
    freopen("p.out", "w", stdout);

    int t;
    cin >> t;
    if (t < 1 || t > 100) {
        return 1;
    }

    for (int testCase = 0; testCase < t; testCase++) {
        int n;
        cin >> n;
        if (n < 1 || n > 1000) {
            testCase--;
            continue;
        }

        processTestCase(n);
    }

    return 0;
}
