#include <iostream>
#include <limits>
#include <stdexcept>
#include <type_traits>
#include <cmath>
using namespace std;

template<typename T>
constexpr bool is_safe_abs(T value) {
    return !(numeric_limits<T>::is_signed && value == numeric_limits<T>::min());
}

template<typename T>
typename enable_if<is_signed<T>::value, T>::type 
safe_abs(T value) {
    if (!is_safe_abs(value)) {
        throw overflow_error("Absolute value overflow detected");
    }
    return value < 0 ? -value : value;
}

template<typename T>
typename enable_if<!is_signed<T>::value, T>::type 
safe_abs(T value) {
    return value;
}

struct AbsoluteComparator {
    bool operator()(int a, int b) const {
        try {
            int abs_a = safe_abs(a);
            int abs_b = safe_abs(b);

            if (abs_a != abs_b) {
                return abs_a < abs_b;
            } else {
                if (a == b) {
                    return false;
                }
                if (a == 0 && b == 0) {
                    return false;
                }
                if ((a > 0 && b > 0) || (a < 0 && b < 0)) {
                    return a < b;
                }
                if (a > 0 && b < 0) {
                    return true;
                }
                if (a < 0 && b > 0) {
                    return false;
                }
                if (a == 0) {
                    return b > 0;
                }
                if (b == 0) {
                    return a < 0;
                }
                return false;
            }
        } catch (const overflow_error& e) {
            cerr << "Error: " << e.what() << endl;
            return a < b;
        }
    }
};

