CharacterValidationResult validateCharacterType(char c) {
    CharacterValidationResult result;
    result.isLowerAlpha = (c >= 'a' && c <= 'z');
    result.isUpperAlpha = (c >= 'A' && c <= 'Z');
    result.isNumeric = (c >= '0' && c <= '9');
    result.isValid = result.isLowerAlpha || result.isUpperAlpha || result.isNumeric;
    return result;
}

char performCyclicShift(char original, int shiftAmount, const CharacterValidationResult& validation) {
    if (validation.isLowerAlpha) {
        int normalizedShift = shiftAmount % 26;
        int base = 'a';
        int adjustedPosition = (original - base + normalizedShift) % 26;
        if (adjustedPosition < 0) adjustedPosition += 26;
        return static_cast<char>(base + adjustedPosition);
    } else if (validation.isUpperAlpha) {
        int normalizedShift = shiftAmount % 26;
        int base = 'A';
        int adjustedPosition = (original - base + normalizedShift) % 26;
        if (adjustedPosition < 0) adjustedPosition += 26;
        return static_cast<char>(base + adjustedPosition);
    } else if (validation.isNumeric) {
        int normalizedShift = shiftAmount % 10;
        int base = '0';
        int adjustedPosition = (original - base + normalizedShift) % 10;
        if (adjustedPosition < 0) adjustedPosition += 10;
        return static_cast<char>(base + adjustedPosition);
    }
    return original;
}

