class PositionCalculator {
public:
    static bool isTargetPosition(int index, int y) {
        if (y <= 0) throw invalid_argument("y must be positive");
        return (index + 1) % y == 0;
    }
};

class CharacterRotator {
private:
    static char rotateInRange(char c, char base, int range, int z) {
        if (range <= 0) throw invalid_argument("Range must be positive");
        int offset = (c - base + z) % range;
        if (offset < 0) offset += range;
        return static_cast<char>(base + offset);
    }

public:
    static char rotateCharacter(char c, int z) {
        if (!CharacterValidator::isValidCharacter(c)) return c;

        if (islower(c)) {
            return rotateInRange(c, 'a', 26, z);
        } else if (isupper(c)) {
            return rotateInRange(c, 'A', 26, z);
        } else if (isdigit(c)) {
            return rotateInRange(c, '0', 10, z);
        }
        return c;
    }
};

class InputSanitizer {
public:
    static void validateInput(int x, int y, int z) {
        if (x <= 10 || x > 100) throw out_of_range("x must be 10 < x <= 100");
