public:
    static char shiftCharacter(char c, int shift) {
        CharacterValidator::validateCharacter(c);

        if (isdigit(c)) {
            return handleDigitShift(c, shift);
        } else if (isupper(c)) {
            return handleAlphaShift(c, shift, 'A', 26);
        } else if (islower(c)) {
