template<typename T>
constexpr bool is_valid_time_type = is_integral_v<T> && is_signed_v<T>;

template<typename T>
void validate_time_remaining(T time) {
    static_assert(is_valid_time_type<T>, "Invalid time type");
    if (time < numeric_limits<T>::min() || time > numeric_limits<T>::max()) {
        throw out_of_range("Time value out of range");
    }
}

enum class RoadCondition : int {
    ACCELERATION = 6,
    ROADBLOCK = 7,
    TRAP = 12,
    ENDPOINT = 15,
    NORMAL = -1
};

RoadCondition classify_condition(int m) {
    switch(m) {
        case 6: return RoadCondition::ACCELERATION;
        case 7: return RoadCondition::ROADBLOCK;
        case 12: return RoadCondition::TRAP;
        case 15: return RoadCondition::ENDPOINT;
        default: return RoadCondition::NORMAL;
    }
}

struct TimeState {
    int remaining;
    bool reached_end;
    bool time_expired;
};

TimeState process_condition(RoadCondition cond, TimeState state) {
    validate_time_remaining(state.remaining);

    if (state.reached_end || state.time_expired) {
        return state;
    }

    switch(cond) {
        case RoadCondition::ACCELERATION:
            break;
        case RoadCondition::ROADBLOCK:
            state.remaining -= 5;
            break;
        case RoadCondition::TRAP:
            state.remaining -= 20;
            break;
        case RoadCondition::ENDPOINT:
            state.reached_end = true;
            break;
        default:
            state.remaining -= 2;
            break;
    }

    if (state.remaining <= 0 && !state.reached_end) {
        state.time_expired = true;
    }

    return state;
}

int main() {
    try {
        int total_time;
        cin >> total_time;
        if (cin.fail() || total_time < 1 || total_time > 100) {
            throw invalid_argument("Invalid initial time");
        }

        TimeState state{total_time, false, false};
        vector<int> conditions(total_time);

        for (int i = 0; i < total_time; ++i) {
            cin >> conditions[i];
            if (cin.fail() || conditions[i] < 1 || conditions[i] > 50) {
                throw invalid_argument("Invalid road condition");
            }
        }

        for (int m : conditions) {
            RoadCondition cond = classify_condition(m);
            state = process_condition(cond, state);
            if (state.reached_end) break;
        }

        if (state.reached_end || (!state.time_expired && state.remaining > 0)) {
            cout << "YES";
        } else {
            cout << "NO";
        }
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

