struct NumberWithSum {
    int original;
    int sum;
    bool operator<(const NumberWithSum& other) const {
        if (sum != other.sum) {
            return sum < other.sum;
        }
        return original < other.original;
    }
};

int calculateDigitSumWithValidation(int m) {
    if (m < 0) {
        throw invalid_argument("Negative numbers not allowed");
    }
    if (m >= 10000) {
        throw out_of_range("Number exceeds maximum allowed value");
    }
    int s = 0;
    int temp = m;
    while (temp != 0) {
        if (temp < 0) {
            throw runtime_error("Unexpected negative during digit calculation");
        }
        s += temp % 10;
        temp /= 10;
        if (s > numeric_limits<int>::max() - 100) {
            throw overflow_error("Digit sum overflow detected");
        }
    }
    return s;
}

void validateInputCount(int n) {
    if (n <= 0 || n >= 101) {
        throw out_of_range("Invalid input count");
    }
