constexpr bool is_arithmetic_v = std::is_arithmetic<T>::value;

template<typename T>
void validate_input(const T& value, const string& param_name) {
    static_assert(is_arithmetic_v<T>, "Input must be arithmetic");
    if (value <= 0) {
        throw invalid_argument(param_name + " must be positive");
    }
    if (value > 1000) {
        throw out_of_range(param_name + " exceeds maximum allowed value");
    }
}

double calculate_initial_distance(int n, int a) {
    const double epsilon = 1e-10;
    double distance = static_cast<double>(n) * static_cast<double>(a);
    if (abs(distance - 600.0) < epsilon) {
        throw logic_error("Initial distance cannot be exactly 600 meters");
    }
    return distance;
}

double calculate_relative_speed(int b, int a) {
    if (b <= a) {
        throw domain_error("Troops speed must be greater than enemy speed");
    }
    return static_cast<double>(b) - static_cast<double>(a);
}

double compute_time_to_shoot(double distance_to_close, double relative_speed) {
    const double shooting_threshold = 600.0;
    if (distance_to_close <= shooting_threshold) {
        throw logic_error("Already within shooting range");
    }
    double raw_time = (distance_to_close - shooting_threshold) / relative_speed;
    if (raw_time < 0) {
        throw logic_error("Negative time calculated");
    }
    return raw_time;
}

int round_up_time(double time) {
    const double epsilon = 1e-10;
    int base_time = static_cast<int>(time);
    double fractional = time - base_time;
    if (fractional > epsilon) {
        return base_time + 1;
    }
    return base_time;
}

