    if (!isalnum(c) && c != ' ') {
        throw CharacterProcessingException("Invalid character encountered");
    }

    if (islower(c)) {
        int normalizedShift = shift % 26;
        if (normalizedShift < 0) normalizedShift += 26;
        int newPos = (c - 'a' + normalizedShift) % 26;
        if (newPos < 0) newPos += 26;
        return 'a' + newPos;
