#include <iostream>
#include <vector>
#include <stdexcept>
#include <algorithm>
#include <cctype>

using namespace std;

struct InputValidationException : public exception {
    const char* what() const throw() {
        return "Input validation failed";
    }
};

class CharacterProcessor {
private:
    static bool validateRange(int value, int min, int max, const string& context) {
        if (value <= min || value > max) {
            throw InputValidationException();
        }
        return true;
    }

    static char processAlpha(char c, int shift, bool isUpper) {
        const char base = isUpper ? 'A' : 'a';
        int adjustedShift = shift % 26;
        if (adjustedShift < 0) adjustedShift += 26;
        return static_cast<char>(base + (c - base + adjustedShift) % 26);
    }

    static char processDigit(char c, int shift) {
        const char base = '0';
        int adjustedShift = shift % 10;
        if (adjustedShift < 0) adjustedShift += 10;
        return static_cast<char>(base + (c - base + adjustedShift) % 10);
    }

public:
    static char processCharacter(char c, int shift) {
        if (isupper(c)) {
            return processAlpha(c, shift, true);
        } else if (islower(c)) {
            return processAlpha(c, shift, false);
        } else if (isdigit(c)) {
            return processDigit(c, shift);
        }
        return c;
    }
};

class KeyGenerator {
private:
    vector<char> buffer;
    int x, y, z;

    void validateParameters() const {
        try {
            CharacterProcessor::validateRange(x, 10, 100, "x");
            CharacterProcessor::validateRange(y, 0, 10, "y");
            CharacterProcessor::validateRange(z, 0, 100, "z");
        } catch (const InputValidationException& e) {
            cerr << e.what() << endl;
            throw;
        }
    }

public:
    KeyGenerator(int x, int y, int z) : x(x), y(y), z(z) {
        validateParameters();
        buffer.reserve(x);
    }

    void processInput() {
        char c;
        for (int i = 0; i < x; ++i) {
            cin >> c;
            if (!cin.good()) {
                throw runtime_error("Input stream error");
            }

            if ((i + 1) % y == 0) {
                c = CharacterProcessor::processCharacter(c, z);
            }
            buffer.push_back(c);
        }
    }

    string getResult() const {
        string result;
        result.reserve(buffer.size());
        for (char c : buffer) {
            result += c;
        }
        return result;
    }
};

int main() {
    try {
        int x, y, z;
        if (!(cin >> x >> y >> z)) {
            throw runtime_error("Failed to read input parameters");
        }

        KeyGenerator generator(x, y, z);
        generator.processInput();
        cout << generator.getResult();

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
