#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>
#include <limits>
#include <stdexcept>
#include <type_traits>
#include <algorithm>

template<typename T>
void validateInputRange(T value) {
    if (std::is_signed<T>::value) {
        if (value < std::numeric_limits<T>::min() || value > std::numeric_limits<T>::max()) {
            throw std::out_of_range("Input value out of range for type");
        }
    }
}

template<typename T>
T safeInput() {
    T value;
    std::cin >> value;
    if (std::cin.fail()) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        throw std::invalid_argument("Invalid input type");
    }
    validateInputRange(value);
    return value;
}

std::string formatNumber(int num) {
    std::ostringstream oss;
    oss << std::setw(8) << num;
    std::string s = oss.str();
    if (s.length() > 8) {
        s = s.substr(s.length() - 8);
    }
    return s;
}

void validateOutputWidth(const std::string& s) {
    if (s.length() != 8) {
        throw std::runtime_error("Formatting error: incorrect width");
    }
}

void printFormattedNumber(int num) {
    std::string formatted = formatNumber(num);
    validateOutputWidth(formatted);
    std::cout << formatted;
}

void handleInputOutput() {
    try {
        int a = safeInput<int>();
        int b = safeInput<int>();
        int c = safeInput<int>();

        printFormattedNumber(a);
        std::cout << " ";
        printFormattedNumber(b);
        std::cout << " ";
        printFormattedNumber(c);
        std::cout << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        std::exit(EXIT_FAILURE);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    handleInputOutput();

    return 0;
}
