#include <iostream>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <type_traits>

template<typename T>
constexpr bool is_arithmetic_v = std::is_arithmetic<T>::value;

template<typename T, typename U, typename V>
void validate_input_range(T n, U a, V b) {
    if (!is_arithmetic_v<T> || !is_arithmetic_v<U> || !is_arithmetic_v<V>) {
        throw std::invalid_argument("Input types must be arithmetic");
    }
    if (n <= 0 || a <= 0 || b <= 0) {
        throw std::out_of_range("Input values must be positive");
    }
    if (n > 1000 || a > 1000 || b > 1000) {
        throw std::out_of_range("Input values exceed maximum limit");
    }
    if (b <= a) {
        throw std::logic_error("Troop speed must be greater than enemy speed");
    }
}

double calculate_interception_time(double n, double a, double b) {
    constexpr double SHOOTING_DISTANCE = 600.0;
    if (n * a <= SHOOTING_DISTANCE) {
        throw std::logic_error("Enemy must be beyond shooting distance initially");
    }
    double relative_speed = b - a;
    if (relative_speed <= std::numeric_limits<double>::epsilon()) {
        throw std::runtime_error("Relative speed calculation error");
    }
    double raw_time = (n * a - SHOOTING_DISTANCE) / relative_speed;
    if (raw_time < 0) {
        throw std::domain_error("Negative time calculation");
    }
    return raw_time;
}

int round_up_time(double time) {
    const double epsilon = std::numeric_limits<double>::epsilon();
    double fractional_part = time - std::floor(time);
    if (std::abs(fractional_part) < epsilon) {
        return static_cast<int>(time);
    }
    if (time > std::numeric_limits<int>::max()) {
        throw std::overflow_error("Time value too large for integer");
    }
    return static_cast<int>(std::ceil(time));
}

int main() {
    try {
        double n, a, b;
        if (!(std::cin >> n >> a >> b)) {
            throw std::runtime_error("Invalid input format");
        }
        validate_input_range(n, a, b);
        double interception_time = calculate_interception_time(n, a, b);
        int result = round_up_time(interception_time);
        std::cout << result;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
