#include <limits>
#include <stdexcept>

using namespace std;

int main() {
    int n = 0;
    int a = 0;
    int b = 0;
    bool inputValidationFlag = false;
    double rawTime = 0.0;
    double absoluteDifferenceThreshold = 1e-9;
    double shootingDistance = 600.0;
    double timeCeiling = 0.0;
    double timeFloor = 0.0;
    double timeDifference = 0.0;
    int finalTime = 0;

    try {
        cin.exceptions(ios::failbit);
        cin >> n >> a >> b;
        if (n <= 0 || a <= 0 || b <= 0) {
            throw invalid_argument("Input values must be positive");
        }
        if (b <= a) {
            throw logic_error("Troop speed must exceed enemy speed");
        }
        if (n * a <= shootingDistance) {
            throw runtime_error("Enemy must be beyond shooting distance initially");
        }
        inputValidationFlag = true;
    } catch (const ios_base::failure& e) {
        cerr << "Input error occurred" << endl;
        return 1;
    } catch (const exception& e) {
        cerr << e.what() << endl;
        return 1;
    }

    if (inputValidationFlag) {
        rawTime = (n * a - shootingDistance) / (b - a);
        timeFloor = floor(rawTime);
        timeCeiling = ceil(rawTime);
        timeDifference = rawTime - timeFloor;

        if (abs(timeDifference) < absoluteDifferenceThreshold) {
            finalTime = static_cast<int>(timeFloor);
        } else {
            if (timeDifference > 0) {
                finalTime = static_cast<int>(timeFloor) + 1;
            } else {
                finalTime = static_cast<int>(timeCeiling);
            }
        }

        double verificationDistance = finalTime * b - (n + finalTime) * a;
        if (abs(verificationDistance - shootingDistance) > absoluteDifferenceThreshold) {
            finalTime += 1;
        }

        cout << finalTime << endl;
    }

    return 0;
}
