class InputValidator {
public:
    static void validateInputRange(int value, int min, int max, const string& paramName) {
        if (value < min || value > max) {
            stringstream ss;
            ss << "Parameter " << paramName << " out of range [" << min << ", " << max << "]";
            throw invalid_argument(ss.str());
        }
