class TimeCalculator {
private:
    static constexpr int SHOOTING_DISTANCE = 600;

    struct InputParams {
        unsigned int n;
        unsigned int a;
        unsigned int b;
    };

    static InputParams sanitizeInput(int n, int a, int b) {
        InputParams params;
        params.n = static_cast<unsigned int>(max(1, n));
        params.a = static_cast<unsigned int>(max(1, a));
        params.b = static_cast<unsigned int>(max(1, b));
        return params;
