#include <bits/stdc++.h>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
#include <sstream>
#include <stdexcept>
using namespace std;

struct CompressionState {
    int current_count;
    char current_char;
    bool initialized;
    vector<int> result;
};

void initialize_compression_state(CompressionState& state, char first_char) {
    state.current_count = 0;
    state.current_char = first_char;
    state.initialized = true;
    state.result.clear();
}

void process_character(CompressionState& state, char c) {
    if (!state.initialized) {
        throw runtime_error("Compression state not initialized");
    }
    if (c == state.current_char) {
        state.current_count++;
    } else {
        state.result.push_back(state.current_count);
        state.current_count = 1;
        state.current_char = c;
    }
}

void finalize_compression(CompressionState& state) {
    if (state.current_count > 0) {
        state.result.push_back(state.current_count);
    }
}

vector<string> read_input_safely(const string& filename) {
    ifstream input_file(filename.c_str());
    if (!input_file.is_open()) {
        throw runtime_error("Failed to open input file");
    }
    vector<string> lines;
    string line;
    while (getline(input_file, line)) {
        if (line.empty()) continue;
        lines.push_back(line);
    }
    input_file.close();
    if (lines.empty()) {
        throw runtime_error("Input file is empty");
    }
    return lines;
}

void write_output_safely(const string& filename, const vector<int>& result) {
    ofstream output_file(filename.c_str());
    if (!output_file.is_open()) {
        throw runtime_error("Failed to open output file");
    }
    for (size_t i = 0; i < result.size(); ++i) {
        if (i != 0) output_file << " ";
        output_file << result[i];
    }
    output_file.close();
}

void validate_input_dimensions(const vector<string>& lines) {
    size_t n = lines.size();
    for (size_t i = 0; i < n; ++i) {
        if (lines[i].size() != n) {
            throw runtime_error("Input is not a square matrix");
        }
    }
}

int main() {
    try {
        vector<string> lines = read_input_safely("zip.in");
        validate_input_dimensions(lines);
        int n = lines.size();
        CompressionState state;
        initialize_compression_state(state, lines[0][0]);
        if (state.current_char != '0') {
            state.result.push_back(0);
        }
        for (int i = 0; i < n; ++i) {
