#include <bits/stdc++.h>
#include <stdexcept>
#include <vector>
#include <algorithm>
using namespace std;

struct CompressionState {
    char current_char;
    int current_count;
    bool initialized;
    bool error_occurred;
    vector<int> result_buffer;
};

void initialize_compression_state(CompressionState& state, char initial_char) {
    state.current_char = initial_char;
    state.current_count = 0;
    state.initialized = true;
    state.error_occurred = false;
    state.result_buffer.clear();
}

void process_character(CompressionState& state, char input_char) {
    if (!state.initialized) {
        state.error_occurred = true;
        return;
    }

    if (input_char != '0' && input_char != '1') {
        state.error_occurred = true;
        return;
    }

    if (input_char == state.current_char) {
        state.current_count++;
    } else {
        if (state.current_count > 0) {
            state.result_buffer.push_back(state.current_count);
        }
        state.current_char = input_char;
        state.current_count = 1;
    }
}

void finalize_compression(CompressionState& state) {
    if (!state.error_occurred && state.initialized && state.current_count > 0) {
        state.result_buffer.push_back(state.current_count);
    }
}

int main() {
    ifstream input_file("zip.in");
    ofstream output_file("zip.out");

    if (!input_file.is_open() || !output_file.is_open()) {
        cerr << "File operation failed" << endl;
        return EXIT_FAILURE;
    }

    vector<string> matrix_lines;
    string current_line;

    while (getline(input_file, current_line)) {
        if (!current_line.empty()) {
            matrix_lines.push_back(current_line);
        }
    }

    if (matrix_lines.empty()) {
        output_file << "0";
        return EXIT_FAILURE;
    }

    const size_t matrix_size = matrix_lines.size();
    for (const auto& line : matrix_lines) {
        if (line.size() != matrix_size) {
            output_file << "0";
            return EXIT_FAILURE;
        }
    }

    CompressionState compression_state;
    initialize_compression_state(compression_state, matrix_lines[0][0]);

    for (size_t row_idx = 0; row_idx < matrix_size; ++row_idx) {
        for (size_t col_idx = 0; col_idx < matrix_size; ++col_idx) {
            if (compression_state.error_occurred) {
                output_file << "0";
                return EXIT_FAILURE;
            }
            process_character(compression_state, matrix_lines[row_idx][col_idx]);
        }
    }

    finalize_compression(compression_state);

    if (compression_state.error_occurred || compression_state.result_buffer.empty()) {
        output_file << "0";
        return EXIT_FAILURE;
    }

    output_file << matrix_size << " ";
    for (size_t i = 0; i < compression_state.result_buffer.size(); ++i) {
        if (i != 0) {
            output_file << " ";
        }
        output_file << compression_state.result_buffer[i];
    }

    input_file.close();
    output_file.close();
    return EXIT_SUCCESS;
}
