};

class ElevatorTimeCalculator {
private:
    vector<long long> floor_requests;
    map<long long, long long> floor_counts;
    ElevatorConfiguration config;
    long long total_time;
    bool initialized;

    void validate_input(long long n) {
        if (n < 1 || n > 100000) {
            throw invalid_argument("Invalid number of people");
        }
