        if (floor < 1 || floor > 1000000000000LL) {
            throw invalid_argument("Invalid floor request");
        }
        floor_requests.push_back(floor);
        floor_counts[floor]++;
    }

    void initialize_configuration() {
        config.rise_time = 5;
        config.descend_time = 4;
        config.door_open_time = 3;
        config.person_exit_time = 2;
        config.initial_floor = 0;
        initialized = true;
    }

    void calculate_ascent_time() {
        long long current_floor = config.initial_floor;
        for (size_t i = 0; i < floor_requests.size(); ++i) {
            if (floor_requests[i] > current_floor) {
                total_time += (floor_requests[i] - current_floor) * config.rise_time;
            }
            current_floor = floor_requests[i];
            total_time += config.door_open_time;
            total_time += floor_counts[floor_requests[i]] * config.person_exit_time;
        }
    }

    void calculate_descent_time() {
        if (!floor_requests.empty()) {
            long long max_floor = *max_element(floor_requests.begin(), floor_requests.end());
            total_time += (max_floor - config.initial_floor) * config.descend_time;
        }
    }

