        input_file.close();
    }

    void calculate_total_time() {
        sort(floor_requests.begin(), floor_requests.end());
        floor_requests.erase(unique(floor_requests.begin(), floor_requests.end()), floor_requests.end());

        calculate_ascent_time();
        calculate_descent_time();
    }

    void write_output() {
        ofstream output_file("elevator.out");
        if (!output_file.is_open()) {
            throw runtime_error("Unable to open output file");
        }
