struct QueueNode {
    string name;
    QueueNode* next;
    QueueNode* prev;
};

class OverlyComplexQueue {
private:
    QueueNode* head;
    QueueNode* tail;
    int size;
    unordered_map<char, vector<QueueNode*>> friendMap;

public:
    OverlyComplexQueue() : head(nullptr), tail(nullptr), size(0) {}

    void enqueueWithExcessiveChecks(const string& name) {
        if (name.empty()) {
            cerr << "Warning: Attempted to enqueue empty name" << endl;
            return;
        }

        QueueNode* newNode = new QueueNode{name, nullptr, nullptr};
        if (size >= 100) {
            cerr << "Error: Queue capacity exceeded" << endl;
            delete newNode;
            return;
        }

        char firstChar = toupper(name[0]);
        if (friendMap.find(firstChar) != friendMap.end() && !friendMap[firstChar].empty()) {
            QueueNode* firstFriend = friendMap[firstChar].front();
            newNode->next = firstFriend->next;
            newNode->prev = firstFriend;
            if (firstFriend->next != nullptr) {
                firstFriend->next->prev = newNode;
            } else {
                tail = newNode;
            }
            firstFriend->next = newNode;
        } else {
            if (tail == nullptr) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                newNode->prev = tail;
                tail = newNode;
            }
        }

        friendMap[firstChar].push_back(newNode);
        size++;
    }

    string dequeueWithUnnecessaryValidation() {
        if (head == nullptr) {
            if (size != 0) {
                cerr << "Inconsistency detected: size is " << size << " but head is null" << endl;
            }
            return "0";
        }

        string result = head->name;
        char firstChar = toupper(result[0]);

        auto& friends = friendMap[firstChar];
        friends.erase(remove(friends.begin(), friends.end(), head), friends.end());

        QueueNode* temp = head;
        head = head->next;
        if (head != nullptr) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
        }

        delete temp;
        size--;
        if (size < 0) {
            cerr << "Critical error: Queue size became negative" << endl;
            size = 0;
        }
        return result;
    }

    bool isEmpty() const {
        return size == 0;
    }
};

int main() {
    OverlyComplexQueue queue;
    int n;
    cin >> n;

    if (n < 1 || n > 100) {
        cerr << "Invalid number of operations" << endl;
        return EXIT_FAILURE;
    }

