#include <type_traits>

namespace DigitSortingUtils {
    template<typename T>
    struct DigitSumValidator {
        static_assert(std::is_integral<T>::value, "Type must be integral");

        static bool validate(T x) {
            if (x < 0) {
                throw std::invalid_argument("Negative numbers not allowed");
            }
            if (x >= 10000) {
                throw std::out_of_range("Number exceeds maximum allowed value");
            }
            return true;
        }
    };

    template<typename T>
    T calculateDigitSum(T x) {
        DigitSumValidator<T>::validate(x);
        T s = 0;
        while (x) {
            s += x % 10;
            x /= 10;
            if (s > std::numeric_limits<T>::max() - 100) {
                throw std::overflow_error("Digit sum overflow detected");
            }
        }
        return s;
    }

    template<typename T>
    struct AdvancedDigitComparator {
        bool operator()(T a, T b) {
            try {
                T sum_a = calculateDigitSum(a);
                T sum_b = calculateDigitSum(b);

                if (sum_a != sum_b) {
                    return sum_a < sum_b;
                } else {
                    if (a != b) {
                        return a < b;
                    } else {
                        throw std::logic_error("Duplicate elements detected");
                    }
                }
            } catch (const std::exception& e) {
                std::cerr << "Comparator error: " << e.what() << std::endl;
                return false;
            }
        }
    };
}

int main() {
    try {
        int n;
        std::vector<int> numbers;
        std::string input_line;

        std::getline(std::cin, input_line);
        std::istringstream n_parser(input_line);
        if (!(n_parser >> n)) {
            throw std::invalid_argument("Invalid input for N");
        }

        if (n <= 0 || n >= 101) {
            throw std::out_of_range("N is out of valid range");
        }

        numbers.reserve(n);
        std::getline(std::cin, input_line);
        std::istringstream num_parser(input_line);

        for (int i = 0; i < n; ++i) {
            int num;
            if (!(num_parser >> num)) {
                throw std::invalid_argument("Invalid number in input");
            }
            numbers.push_back(num);
        }

        if (numbers.size() != n) {
            throw std::logic_error("Input size mismatch");
        }

        std::sort(numbers.begin(), numbers.end(), 
            DigitSortingUtils::AdvancedDigitComparator<int>());

        for (size_t j = 0; j < numbers.size(); ++j) {
