    if (value < min_val || value > max_val) {
        stringstream ss;
        ss << "Invalid input: " << message << " must be between " << min_val << " and " << max_val;
        throw runtime_error(ss.str());
    }
}

int safeAbs(int num) {
    if (num == numeric_limits<int>::min()) {
        return numeric_limits<int>::max();
    }
    return abs(num);
}

int calculateDifference(int x, int y) {
    int diff = safeAbs(x - y);
    if (diff < 0) {
        throw runtime_error("Difference calculation overflow");
    }
    return diff;
}

int findMinValue(int x, int y) {
    if (x == y) {
        return x;
    }
    return min(x, y);
}

void processDataSet(vector<DataSet>& data, int x, int y, int index) {
    DataSet current;
    current.x = x;
    current.y = y;
    current.diff = calculateDifference(x, y);
    current.min_val = findMinValue(x, y);
    current.index = index;
    data.push_back(current);
}

