int safeAbsoluteValue(int value) {
    if (value == numeric_limits<int>::min()) {
        throw overflow_error("Absolute value overflow");
    }
    return (value < 0) ? -value : value;
}

bool validateInput(istream& stream) {
    if (stream.fail()) {
        stream.clear();
        stream.ignore(numeric_limits<streamsize>::max(), '\n');
        return false;
    }
    return true;
}

void sortByAbsoluteValueWithFallback(int& first, int& second) {
    int firstAbs;
    int secondAbs;
    bool firstAbsValid = false;
    bool secondAbsValid = false;

    try {
        firstAbs = safeAbsoluteValue(first);
        firstAbsValid = true;
    } catch (const overflow_error& e) {
        firstAbs = numeric_limits<int>::max();
    }

    try {
        secondAbs = safeAbsoluteValue(second);
        secondAbsValid = true;
    } catch (const overflow_error& e) {
        secondAbs = numeric_limits<int>::max();
    }

    bool shouldSwap = false;
    if (firstAbsValid && secondAbsValid) {
