struct CharacterProcessor {
    static char processLower(char c, int shift) {
        const int alphabetSize = 26;
        int normalizedShift = shift % alphabetSize;
        if (normalizedShift < 0) normalizedShift += alphabetSize;
        int originalPos = c - 'a';
        int newPos = (originalPos + normalizedShift) % alphabetSize;
        return 'a' + newPos;
    }

    static char processUpper(char c, int shift) {
        const int alphabetSize = 26;
        int normalizedShift = shift % alphabetSize;
        if (normalizedShift < 0) normalizedShift += alphabetSize;
        int originalPos = c - 'A';
        int newPos = (originalPos + normalizedShift) % alphabetSize;
        return 'A' + newPos;
    }

    static char processDigit(char c, int shift) {
        const int digitSize = 10;
        int normalizedShift = shift % digitSize;
        if (normalizedShift < 0) normalizedShift += digitSize;
        int originalPos = c - '0';
        int newPos = (originalPos + normalizedShift) % digitSize;
        return '0' + newPos;
    }
};

class InputValidator {
public:
