struct EncryptionParameters {
    int length;
    int multiple;
    int shift;
    vector<char> data;
};

bool validateParameters(const EncryptionParameters& params) {
    if (params.length <= 10 || params.length > 100) {
        throw runtime_error("Invalid length parameter");
    }
    if (params.multiple <= 0 || params.multiple > 10) {
        throw runtime_error("Invalid multiple parameter");
    }
    if (params.shift <= 0 || params.shift > 100) {
        throw runtime_error("Invalid shift parameter");
    }
    if (params.data.size() != params.length) {
        throw runtime_error("Data length mismatch");
    }
    return true;
}

char transformCharacter(char c, int shift, bool shouldTransform) {
    if (!shouldTransform) return c;

    int base = 0;
    int range = 0;

    if (islower(c)) {
        base = 'a';
        range = 26;
    } else if (isupper(c)) {
        base = 'A';
        range = 26;
    } else if (isdigit(c)) {
        base = '0';
        range = 10;
    } else {
        return c;
    }

    int normalizedShift = shift % range;
    if (normalizedShift < 0) normalizedShift += range;

    return static_cast<char>(base + (c - base + normalizedShift) % range);
}

void processEncryption(EncryptionParameters& params) {
    try {
        if (!validateParameters(params)) {
            cerr << "Parameter validation failed" << endl;
            return;
        }

        for (size_t i = 0; i < params.data.size(); ++i) {
            bool shouldTransform = ((i + 1) % params.multiple == 0);
            params.data[i] = transformCharacter(params.data[i], params.shift, shouldTransform);

            if (!isalnum(params.data[i]) && params.data[i] != '\0') {
                cerr << "Warning: Non-alphanumeric character detected at position " << i << endl;
            }
        }
    } catch (const exception& e) {
