vector<string> tokenizeWithValidation(const string& s) {
    vector<string> tokens;
    string current;
    bool inWord = false;
    for (char c : s) {
        if (isalpha(c)) {
            current += c;
            inWord = true;
        } else if (isspace(c)) {
            if (inWord) {
                if (!current.empty()) {
                    tokens.push_back(current);
                    current.clear();
                }
                inWord = false;
            }
        } else {
            throw runtime_error("Invalid character detected");
        }
    }
    if (!current.empty()) {
        tokens.push_back(current);
    }
    return tokens;
}

string findLongestWordWithFallbacks(const vector<string>& words) {
