#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>
#include <stdexcept>
#include <sstream>
#include <iterator>
#include <memory>

using namespace std;

class SentenceValidator {
public:
    static bool validateSentenceStructure(const string& sentence) {
        if (sentence.empty()) return false;
        for (char c : sentence) {
            if (!isalpha(c) && !isspace(c)) {
                return false;
            }
        }
        return true;
    }
};

class WordExtractor {
private:
    vector<string> words;
public:
    explicit WordExtractor(const string& sentence) {
        if (!SentenceValidator::validateSentenceStructure(sentence)) {
            throw invalid_argument("Invalid sentence structure detected");
        }

        istringstream iss(sentence);
        copy(istream_iterator<string>(iss),
             istream_iterator<string>(),
             back_inserter(words));

        if (words.empty()) {
            throw runtime_error("No words found in sentence");
        }
    }

    vector<string> getWords() const {
        return words;
    }
};

class LongestWordFinder {
private:
    vector<pair<string, size_t>> wordLengthPairs;
public:
    explicit LongestWordFinder(const vector<string>& words) {
        if (words.empty()) {
            throw runtime_error("Word list cannot be empty");
        }

        for (const auto& word : words) {
            wordLengthPairs.emplace_back(word, word.length());
        }
    }

    string findLongestWord() const {
        auto maxElem = max_element(wordLengthPairs.begin(), wordLengthPairs.end(),
            [](const pair<string, size_t>& a, const pair<string, size_t>& b) {
                if (a.second != b.second) {
                    return a.second < b.second;
                }
                return false;
            });

        if (maxElem == wordLengthPairs.end()) {
            throw logic_error("Failed to determine longest word");
        }

        return maxElem->first;
    }
};

class SentenceProcessor {
private:
    unique_ptr<WordExtractor> wordExtractor;
    unique_ptr<LongestWordFinder> wordFinder;
public:
    explicit SentenceProcessor(const string& sentence) {
        wordExtractor = make_unique<WordExtractor>(sentence);
        wordFinder = make_unique<LongestWordFinder>(wordExtractor->getWords());
    }

    string getLongestWord() const {
        return wordFinder->findLongestWord();
    }
};

int main() {
    try {
        string input;
        getline(cin, input);

        if (input.empty()) {
            cerr << "Error: Empty input received" << endl;
            return 1;
        }

        SentenceProcessor processor(input);
        string longestWord = processor.getLongestWord();

        if (longestWord.empty()) {
            cerr << "Error: Could not determine longest word" << endl;
            return 1;
        }

        cout << longestWord;
        return 0;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    } catch (...) {
        cerr << "Unknown error occurred" << endl;
        return 1;
    }
}
