#include <iterator>
#include <memory>

using namespace std;

class SentenceValidator {
public:
    static bool validateSentenceStructure(const string& input) {
        if (input.empty()) return false;
        if (input.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ ") != string::npos) {
            return false;
        }
        if (input.front() == ' ' || input.back() == ' ') {
            return false;
        }
        return true;
    }
};

class WordExtractor {
private:
    vector<string> words;
public:
    explicit WordExtractor(const string& sentence) {
        istringstream iss(sentence);
        copy(istream_iterator<string>(iss),
             istream_iterator<string>(),
             back_inserter(words));

        if (words.empty()) {
            throw runtime_error("No words found in input");
        }
    }

    const vector<string>& getWords() const {
        return words;
    }
};

class LongestWordFinder {
public:
    static pair<string, size_t> findLongestWord(const vector<string>& words) {
        if (words.empty()) {
            throw invalid_argument("Word list cannot be empty");
        }

        string longest;
        size_t max_length = 0;
        bool found = false;

        for (const auto& word : words) {
            size_t current_length = word.length();
            if (current_length > max_length || 
                (current_length == max_length && !found)) {
                max_length = current_length;
                longest = word;
                found = true;
            }
        }

        if (!found) {
            throw runtime_error("Failed to determine longest word");
        }

        return make_pair(longest, max_length);
    }
};

int main() {
    try {
        string input;
        if (!getline(cin, input)) {
            cerr << "Error reading input" << endl;
            return EXIT_FAILURE;
        }

        if (!SentenceValidator::validateSentenceStructure(input)) {
            cerr << "Invalid sentence structure" << endl;
            return EXIT_FAILURE;
        }

        WordExtractor extractor(input);
        auto words = extractor.getWords();

        auto result = LongestWordFinder::findLongestWord(words);

        cout << result.first;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
