    if (n < 1 || n > 100) {
        throw runtime_error("Invalid number of datasets");
    }
}

void validateXY(int x, int y) {
    if (x < 1 || x > 20 || y < 1 || y > 20) {
        throw runtime_error("X or Y out of bounds");
    }
}

int calculateAbsoluteDifference(int a, int b) {
    return abs(a - b);
}

int findMinimumValue(int a, int b) {
    return min(a, b);
}

DataSet processDataSet(int x, int y, int idx) {
    DataSet ds;
    ds.x = x;
    ds.y = y;
    ds.diff = calculateAbsoluteDifference(x, y);
    ds.min_val = findMinimumValue(x, y);
    ds.index = idx;
    return ds;
}

bool compareDataSets(const DataSet& a, const DataSet& b) {
    if (a.diff != b.diff) {
        return a.diff > b.diff;
    } else if (a.min_val != b.min_val) {
        return a.min_val < b.min_val;
    } else {
        return a.index < b.index;
    }
}

int main() {
    try {
        int n;
        cin >> n;
        validateInput(n);

        vector<DataSet> datasets;
        datasets.reserve(n);

        for (int i = 0; i < n; ++i) {
            int x, y;
            cin >> x >> y;
            validateXY(x, y);
            datasets.push_back(processDataSet(x, y, i));
        }

        if (datasets.empty()) {
            throw runtime_error("No datasets provided");
        }

        sort(datasets.begin(), datasets.end(), compareDataSets);

        DataSet result = datasets.front();
        for (const auto& ds : datasets) {
            if (ds.diff == result.diff && ds.min_val == result.min_val && ds.index < result.index) {
                result = ds;
            }
        }

        cout << result.x << " " << result.y;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
