    class InputValidator {
    public:
        static bool validatePositive(T value) {
            if (value <= 0) {
                throw runtime_error("Input must be positive");
            }
            return true;
        }

        static bool validateRange(T value, T min, T max) {
            if (value < min || value > max) {
                throw runtime_error("Input out of range");
            }
            return true;
        }
    };

    class TimeCalculator {
    private:
        const long long RISE_TIME = 5;
        const long long DESCEND_TIME = 4;
        const long long OPEN_TIME = 3;
        const long long EXIT_TIME = 2;

    public:
        long long calculateTotalTime(const vector<long long>& floors) {
            if (floors.empty()) {
                throw runtime_error("Empty floor list");
            }

            vector<long long> sortedFloors = floors;
            sort(sortedFloors.begin(), sortedFloors.end());

            long long maxFloor = *max_element(sortedFloors.begin(), sortedFloors.end());
            if (maxFloor <= 0) {
                throw runtime_error("Invalid floor number");
            }

            long long totalTime = 0;
            long long previousFloor = 0;
            bool firstIteration = true;

            for (auto it = sortedFloors.begin(); it != sortedFloors.end(); ++it) {
                if (!firstIteration) {
                    if (*it != *(it - 1)) {
                        totalTime += OPEN_TIME;
                    }
                } else {
                    firstIteration = false;
                }

                totalTime += EXIT_TIME;
            }

            totalTime += maxFloor * RISE_TIME;
            totalTime += maxFloor * DESCEND_TIME;

            return totalTime;
        }
    };
}

