        throw invalid_argument("Node cannot be child of itself");
    }
}

bool check_p_node_condition(int current_node, const vector<int> G[], const vector<NodeDegreeInfo>& degree_info) {
    bool meets_condition = true;
    size_t current_degree = degree_info[current_node].degree;

    for(size_t j = 0; j < G[current_node].size(); j++) {
        int neighbor = G[current_node][j];
        if(degree_info[neighbor].degree > current_degree) {
            meets_condition = false;
            break;
