bool verifyTreeStructure(const vector<TreeNode>& nodes, int n) {
    vector<bool> visited(n, false);
    queue<int> q;
    q.push(0);
    visited[0] = true;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : nodes[u].children) {
            if (visited[v]) {
