vector<vector<long long>> validateAndInitializeMatrix(ifstream& inputFile, long long n, long long m) {
    if (n < MIN_DIM || n > MAX_DIM || m < MIN_DIM || m > MAX_DIM) {
        throw invalid_argument("Matrix dimensions out of bounds");
    }

    vector<vector<long long>> matrix(n, vector<long long>(m));
    for (long long i = 0; i < n; ++i) {
        for (long long j = 0; j < m; ++j) {
            if (!(inputFile >> matrix[i][j])) {
                throw runtime_error("Failed to read matrix element");
            }
            if (matrix[i][j] < MIN_VAL || matrix[i][j] > MAX_VAL) {
                throw out_of_range("Matrix element out of bounds");
            }
        }
    }
    return matrix;
}

long long computeSubmatrixSum(const vector<vector<long long>>& matrix, const MatrixBounds& bounds) {
    if (bounds.x1 < 0 || bounds.y1 < 0 || bounds.x2 >= matrix.size() || bounds.y2 >= matrix[0].size()) {
        throw out_of_range("Submatrix bounds out of range");
    }

    long long sum = 0;
    for (long long i = bounds.x1; i <= bounds.x2; ++i) {
        for (long long j = bounds.y1; j <= bounds.y2; ++j) {
            sum += matrix[i][j];
        }
    }
    return sum;
}

long long findMaxSubmatrixSum(const vector<vector<long long>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) {
        throw invalid_argument("Empty matrix provided");
    }

    long long maxSum = LLONG_MIN;
    vector<MatrixBounds> candidateBounds;

    for (long long x1 = 0; x1 < matrix.size(); ++x1) {
        for (long long y1 = 0; y1 < matrix[0].size(); ++y1) {
            for (long long x2 = x1; x2 < matrix.size(); ++x2) {
                for (long long y2 = y1; y2 < matrix[0].size(); ++y2) {
                    MatrixBounds currentBounds = {x1, y1, x2, y2};
                    candidateBounds.push_back(currentBounds);
                }
            }
        }
    }

    for (const auto& bounds : candidateBounds) {
        try {
            long long currentSum = computeSubmatrixSum(matrix, bounds);
            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        } catch (const exception& e) {
            cerr << "Error computing submatrix sum: " << e.what() << endl;
        }
    }

    return maxSum;
}

void validateOutputFile(ofstream& outputFile) {
