    const char* what() const throw() {
        return "Matrix value out of bounds";
    }
};

struct FileIOException : public exception {
    const char* what() const throw() {
        return "File I/O error";
    }
};

void validateDimensions(int n, int m) {
    if (n < MIN_DIM || n > MAX_DIM || m < MIN_DIM || m > MAX_DIM) {
        throw MatrixBoundsException();
    }
}

void validateMatrixValue(int val) {
    if (val < MIN_VAL || val > MAX_VAL) {
        throw MatrixValueException();
    }
}

vector<vector<int>> readMatrixFromFile(const string& filename, int& n, int& m) {
    ifstream infile(filename);
    if (!infile.is_open()) {
        throw FileIOException();
    }

    string line;
    if (!getline(infile, line)) {
        throw FileIOException();
    }

    istringstream iss(line);
    if (!(iss >> n >> m)) {
        throw FileIOException();
    }

    validateDimensions(n, m);

    vector<vector<int>> matrix(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        if (!getline(infile, line)) {
            throw FileIOException();
        }
        istringstream rowIss(line);
        for (int j = 0; j < m; ++j) {
            int val;
            if (!(rowIss >> val)) {
                throw FileIOException();
            }
            validateMatrixValue(val);
            matrix[i][j] = val;
        }
    }

    return matrix;
}

int computeMaxSubmatrixSum(const vector<vector<int>>& matrix, int n, int m) {
    int maxSum = INT_MIN;
    vector<vector<int>> prefixSum(n+1, vector<int>(m+1, 0));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            prefixSum[i][j] = matrix[i-1][j-1] + prefixSum[i-1][j] + 
                             prefixSum[i][j-1] - prefixSum[i-1][j-1];
        }
    }

    for (int x1 = 1; x1 <= n; ++x1) {
        for (int x2 = x1; x2 <= n; ++x2) {
            for (int y1 = 1; y1 <= m; ++y1) {
                for (int y2 = y1; y2 <= m; ++y2) {
                    int currentSum = prefixSum[x2][y2] - prefixSum[x1-1][y2] - 
                                   prefixSum[x2][y1-1] + prefixSum[x1-1][y1-1];
                    if (currentSum > maxSum) {
                        maxSum = currentSum;
                    }
                }
            }
        }
    }

    return maxSum;
}

void writeResultToFile(const string& filename, int result) {
    ofstream outfile(filename);
    if (!outfile.is_open()) {
        throw FileIOException();
    }
    outfile << result << endl;
}

int main() {
    try {
        int n, m;
        auto matrix = readMatrixFromFile("max_sub_sum.in", n, m);
        int result = computeMaxSubmatrixSum(matrix, n, m);
        writeResultToFile("max_sub_sum.out", result);
    } catch (const MatrixBoundsException& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    } catch (const MatrixValueException& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    } catch (const FileIOException& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    } catch (...) {
        cerr << "Unknown error occurred" << endl;
        return 1;
    }

    return 0;
}
