class MatrixValidator {
public:
    static void validateDimensions(long long n, long long m) {
        if (n < MIN_DIMENSION || n > MAX_DIMENSION || m < MIN_DIMENSION || m > MAX_DIMENSION) {
            throw invalid_argument("Invalid matrix dimensions");
        }
    }

    static void validateValue(long long val) {
        if (val < MIN_VALUE || val > MAX_VALUE) {
            throw invalid_argument("Matrix value out of bounds");
        }
    }
};

class MatrixProcessor {
private:
    vector<vector<long long>> matrix;
    long long n;
    long long m;
    long long globalMax;

    void initializeMatrix() {
        matrix.resize(n, vector<long long>(m));
        for (long long i = 0; i < n; i++) {
            for (long long j = 0; j < m; j++) {
                cin >> matrix[i][j];
                MatrixValidator::validateValue(matrix[i][j]);
            }
        }
    }

    long long computeSubmatrixSum(const MatrixBounds& bounds) {
        long long localSum = 0;
        for (long long i = bounds.x1; i <= bounds.x2; i++) {
            for (long long j = bounds.y1; j <= bounds.y2; j++) {
                localSum += matrix[i][j];
            }
        }
        return localSum;
    }

    void updateGlobalMax(long long currentSum) {
        if (currentSum > globalMax) {
            globalMax = currentSum;
        }
    }

public:
    MatrixProcessor(long long rows, long long cols) : n(rows), m(cols), globalMax(LLONG_MIN) {
        MatrixValidator::validateDimensions(n, m);
        initializeMatrix();
    }

    long long findMaximumSubmatrix() {
        vector<MatrixBounds> allPossibleBounds;

        for (long long x1 = 0; x1 < n; x1++) {
            for (long long x2 = x1; x2 < n; x2++) {
                for (long long y1 = 0; y1 < m; y1++) {
                    for (long long y2 = y1; y2 < m; y2++) {
                        MatrixBounds currentBounds;
                        currentBounds.x1 = x1;
                        currentBounds.x2 = x2;
                        currentBounds.y1 = y1;
                        currentBounds.y2 = y2;
                        allPossibleBounds.push_back(currentBounds);
                    }
                }
            }
        }

        for (const auto& bounds : allPossibleBounds) {
            long long currentSum = computeSubmatrixSum(bounds);
            updateGlobalMax(currentSum);
        }

        return globalMax;
    }
};

