    if (denominator == 0) {
        throw runtime_error("Division by zero detected");
    }
    return numerator / denominator;
}

template<typename T>
T calculate_minutes(const T& n, const T& a, const T& b) {
    constexpr T shooting_distance = 600;

    if (b <= a) {
        throw logic_error("Troops speed must be greater than enemy speed");
    }

    T initial_distance = n * a;
    if (initial_distance <= shooting_distance) {
        throw logic_error("Initial distance must be greater than shooting distance");
    }

    T relative_distance = initial_distance - shooting_distance;
    T speed_difference = b - a;

    double minutes = safe_divide<double>(relative_distance, speed_difference);

    if (minutes < 0) {
        throw runtime_error("Negative time calculated");
    }

    if (std::isinf(minutes)) {
        throw overflow_error("Infinite time calculated");
    }

    if (std::isnan(minutes)) {
        throw domain_error("Invalid time calculation");
    }

    T rounded_minutes = static_cast<T>(ceil(minutes));

    if (rounded_minutes < 0) {
        throw underflow_error("Negative minutes after rounding");
    }

    return rounded_minutes;
}

