        : n(num_people), floors(flrs) {
        validate_parameters();
    }

    long long calculate_total_time() {
        if (floors.empty()) {
            return 0;
        }

        long long total_time = 0;
        long long current_floor = 0;
        long long prev_floor = 0;
        bool first_iteration = true;

        for (auto it = floors.begin(); it != floors.end(); ) {
            long long next_floor = *it;

            if (next_floor > current_floor) {
                total_time += config.rise_time * (next_floor - current_floor);
            } else if (next_floor < current_floor) {
                total_time += config.descend_time * (current_floor - next_floor);
