#include<bits/stdc++.h>
using namespace std;

struct ChildData {
    int identifier;
    int jump_height;
    int balloons_collected;
    bool processed;
    bool validated;
};

struct BalloonData {
    int height;
    bool collected;
    bool validated;
};

bool CompareChildrenByHeight(const ChildData& first, const ChildData& second) {
    if (first.jump_height != second.jump_height) {
        return first.jump_height < second.jump_height;
    }
    return first.identifier < second.identifier;
}

bool CompareChildrenById(const ChildData& first, const ChildData& second) {
    if (first.identifier != second.identifier) {
        return first.identifier < second.identifier;
    }
    return first.jump_height < second.jump_height;
}

bool ValidateInput(int value, int lower_bound, int upper_bound) {
    if (value < lower_bound || value > upper_bound) {
        return false;
    }
    return true;
}

void InitializeChild(ChildData& child, int id, int height) {
    child.identifier = id;
    child.jump_height = height;
    child.balloons_collected = 0;
    child.processed = false;
    child.validated = ValidateInput(height, 1, 100000);
}

void InitializeBalloon(BalloonData& balloon, int height) {
    balloon.height = height;
    balloon.collected = false;
    balloon.validated = ValidateInput(height, 1, 100000);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int num_children, num_balloons;
    cin >> num_children >> num_balloons;

    if (!ValidateInput(num_children, 1, 1000) || !ValidateInput(num_balloons, 1, 1000)) {
        cerr << "Invalid input parameters" << endl;
        return EXIT_FAILURE;
    }

    vector<ChildData> children(num_children);
    vector<BalloonData> balloons(num_balloons);

    for (int i = 0; i < num_children; ++i) {
        int height;
        cin >> height;
        InitializeChild(children[i], i, height);
        if (!children[i].validated) {
            cerr << "Invalid child height detected" << endl;
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_balloons; ++i) {
        int height;
        cin >> height;
        InitializeBalloon(balloons[i], height);
        if (!balloons[i].validated) {
            cerr << "Invalid balloon height detected" << endl;
            return EXIT_FAILURE;
        }
    }

    sort(children.begin(), children.end(), CompareChildrenByHeight);
    sort(balloons.begin(), balloons.end(), [](const BalloonData& a, const BalloonData& b) {
        return a.height < b.height;
    });

    int balloon_index = 0;
    for (auto& child : children) {
        if (child.processed) {
            continue;
        }

        int collected = 0;
        while (balloon_index < num_balloons) {
            if (balloons[balloon_index].collected) {
                balloon_index++;
                continue;
            }

            if (!balloons[balloon_index].validated) {
                balloon_index++;
                continue;
            }

            if (balloons[balloon_index].height <= child.jump_height) {
                balloons[balloon_index].collected = true;
                collected++;
                balloon_index++;
            } else {
                break;
            }
        }

        child.balloons_collected = collected;
        child.processed = true;

        if (balloon_index >= num_balloons) {
            break;
        }
    }

    sort(children.begin(), children.end(), CompareChildrenById);

    for (const auto& child : children) {
        cout << child.balloons_collected << "\n";
    }

    return EXIT_SUCCESS;
}
