    sort(h, h + m);
    for(int i = 0; i < n; i++) {
        int balloons_collected = 0;
        vector<int> temp_indices;
        for(int j = 0; j < m; j++) {
            if(!h_processed[j] && h[j] <= cs[i].height) {
