#include <bits/stdc++.h>
using namespace std;

struct Child {
    int id;
    int height;
    int cnt;
    bool processed;
    vector<int> balloon_indices;
};

struct Balloon {
    int height;
    bool taken;
    int taken_by;
};

bool compareChildrenByHeight(const Child& a, const Child& b) {
    if (a.height != b.height) {
        return a.height < b.height;
    }
    return a.id < b.id;
}

bool compareChildrenById(const Child& a, const Child& b) {
    if (a.id != b.id) {
        return a.id < b.id;
    }
    return a.height < b.height;
}

bool compareBalloonsByHeight(const Balloon& a, const Balloon& b) {
    if (a.height != b.height) {
        return a.height < b.height;
    }
    return !a.taken;
}

void validateInput(int n, int m) {
    if (n < 1 || n > 1000 || m < 1 || m > 1000) {
        throw runtime_error("Invalid input range");
    }
}

void processChildren(vector<Child>& children, vector<Balloon>& balloons) {
    for (auto& child : children) {
        if (child.processed) continue;
        for (auto& balloon : balloons) {
            if (!balloon.taken && balloon.height <= child.height) {
                balloon.taken = true;
                balloon.taken_by = child.id;
                child.balloon_indices.push_back(balloon.height);
                child.cnt++;
            }
        }
        child.processed = true;
    }
}

void verifyUniqueHeights(const vector<Child>& children) {
    unordered_set<int> heights;
    for (const auto& child : children) {
        if (heights.count(child.height)) {
            throw runtime_error("Duplicate child heights detected");
        }
        heights.insert(child.height);
    }
}

void initializeBalloons(vector<Balloon>& balloons, const vector<int>& h) {
    for (size_t i = 0; i < h.size(); ++i) {
        balloons[i].height = h[i];
        balloons[i].taken = false;
        balloons[i].taken_by = -1;
    }
}

void finalizeCounts(vector<Child>& children) {
    for (auto& child : children) {
        if (child.cnt < 0) {
            child.cnt = 0;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n, m;
    cin >> n >> m;

    try {
        validateInput(n, m);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    vector<Child> children(n);
    for (int i = 0; i < n; ++i) {
        cin >> children[i].height;
        children[i].id = i;
        children[i].cnt = 0;
        children[i].processed = false;
    }

    vector<int> h(m);
    for (int i = 0; i < m; ++i) {
        cin >> h[i];
    }

    try {
        verifyUniqueHeights(children);
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    vector<Balloon> balloons(m);
    initializeBalloons(balloons, h);

    sort(children.begin(), children.end(), compareChildrenByHeight);
    sort(balloons.begin(), balloons.end(), compareBalloonsByHeight);

    processChildren(children, balloons);

    sort(children.begin(), children.end(), compareChildrenById);
    finalizeCounts(children);

    for (const auto& child : children) {
        cout << child.cnt << endl;
    }

    return 0;
}
