                    numeric_limits<int>::max(), numeric_limits<int>::max()};

    const int upper_bound = safe_sqrt(N) + 2;

    for (int a = 0; a <= upper_bound; ++a) {
        if (!is_safe_to_square(a)) continue;
        int a_sq = a * a;
