            return false;
        }
        return true;
    }

    static bool validatePeopleCount(long long n) {
        if (n < MIN_PEOPLE || n > MAX_PEOPLE) {
            cerr << "Invalid people count: " << n << endl;
            return false;
        }
        return true;
    }
};

class FileHandler {
private:
    string inputFilename;
    string outputFilename;
    bool filesValid;

public:
    FileHandler(const string& in, const string& out) : inputFilename(in), outputFilename(out) {
        struct stat buffer;
        filesValid = (stat(inputFilename.c_str(), &buffer) == 0);
        if (!filesValid) {
            cerr << "Input file not found: " << inputFilename << endl;
        }
    }

