};

class SentenceProcessor {
private:
    string raw_input;
    vector<WordMetadata> word_data;
    bool processed;

    void validate_input() {
        if (raw_input.empty()) {
            throw runtime_error("Input sentence cannot be empty");
        }

        for (char c : raw_input) {
            if (!isalpha(c) && !isspace(c)) {
                throw runtime_error("Input contains invalid characters");
            }
        }
    }

    void tokenize_input() {
        istringstream iss(raw_input);
        string token;
        size_t position_counter = 0;

        while (iss >> token) {
            WordMetadata meta;
            meta.content = token;
            meta.original_position = position_counter++;
            meta.length = token.length();
            word_data.push_back(meta);
        }

        if (word_data.empty()) {
            throw runtime_error("No valid words found in input");
        }
    }

public:
    explicit SentenceProcessor(const string& input) : raw_input(input), processed(false) {
        validate_input();
    }

    void process() {
        tokenize_input();
        processed = true;
    }

    WordMetadata find_longest_word() {
        if (!processed) {
            throw runtime_error("Must call process() first");
        }

        WordMetadata longest = word_data[0];
        for (const auto& word : word_data) {
            if (word.length > longest.length) {
                longest = word;
            } else if (word.length == longest.length) {
                if (word.original_position < longest.original_position) {
                    longest = word;
                }
            }
        }

        return longest;
    }
};

int main() {
