        cout << result.content << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    } catch (...) {
        cerr << "Unknown error occurred" << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
