};

class SentenceProcessor {
private:
    vector<WordMetadata> words;
    string original_sentence;

    void initializeMetadata() {
        for (size_t i = 0; i < words.size(); ++i) {
            words[i].processed = false;
            words[i].original_position = i;
        }
    }

    void formatCaseAndPunctuation() {
        for (auto& c : original_sentence) {
            if (isupper(c) {
                if (c != 'I') {
                    c = tolower(c);
                }
            }
            if (c == '?') {
                c = '!';
            }
        }
    }

    void splitIntoWords() {
        string current_word;
        for (char c : original_sentence) {
            if (isspace(c)) {
                if (!current_word.empty()) {
                    words.push_back({current_word, false, words.size()});
                    current_word.clear();
                }
            } else {
                current_word.push_back(c);
            }
        }
        if (!current_word.empty()) {
            words.push_back({current_word, false, words.size()});
        }
    }

    void applyRule3() {
        for (size_t i = 0; i + 1 < words.size(); ++i) {
            if (!words[i].processed && !words[i+1].processed) {
                if ((words[i].content == "can" && words[i+1].content == "you") ||
                    (words[i].content == "could" && words[i+1].content == "you")) {
                    words[i].content = "I " + words[i].content;
                    words[i+1].processed = true;
                    words[i].processed = true;
                }
            }
        }
    }

    void applyRule4() {
        for (auto& word : words) {
            if (!word.processed && (word.content == "I" || word.content == "me")) {
                word.content = "you";
                word.processed = true;
            }
        }
    }

    string reconstructSentence() {
        string result;
        for (size_t i = 0; i < words.size(); ++i) {
            if (words[i].original_position == i && !words[i].processed) {
                result += words[i].content;
                if (i != words.size() - 1) {
                    result += " ";
                }
            } else if (words[i].processed) {
                if (words[i].content.find(' ') != string::npos) {
                    result += words[i].content;
                    if (i != words.size() - 1) {
