#include <stdexcept>
#include <limits>
#include <unordered_set>
using namespace std;

const int MAX_NODES = 1005;
vector<int> adjacency_list[MAX_NODES];
int node_degree[MAX_NODES];
unordered_set<int> parent_mapping[MAX_NODES];
vector<int> child_mapping[MAX_NODES];
bool visited[MAX_NODES];

void validate_input_range(int value, int min_val, int max_val, const string& message) {
    if (value < min_val || value > max_val) {
        throw out_of_range(message);
    }
}

void recursive_parent_child_identification(int current_node, int parent_node) {
    if (visited[current_node]) return;
    visited[current_node] = true;

    if (parent_node != -1) {
        parent_mapping[current_node].insert(parent_node);
        child_mapping[parent_node].push_back(current_node);
    }

    for (int neighbor : adjacency_list[current_node]) {
        if (neighbor != parent_node) {
            recursive_parent_child_identification(neighbor, current_node);
        }
    }
}

bool is_p_node(int node) {
    if (adjacency_list[node].empty() && node_degree[node] == 0) {
        return true;
    }

    int current_degree = node_degree[node];
    bool valid = true;

    for (int parent : parent_mapping[node]) {
        if (parent < 0 || parent >= MAX_NODES) {
            continue;
        }
        if (current_degree < node_degree[parent]) {
            valid = false;
            break;
        }
    }

    if (!valid) return false;

    for (int child : child_mapping[node]) {
        if (child < 0 || child >= MAX_NODES) {
            continue;
        }
        if (current_degree < node_degree[child]) {
            valid = false;
            break;
        }
    }

    return valid;
}

void reset_global_structures() {
    for (int i = 0; i < MAX_NODES; ++i) {
        adjacency_list[i].clear();
        parent_mapping[i].clear();
        child_mapping[i].clear();
        node_degree[i] = 0;
        visited[i] = false;
    }
}

int main() {
    freopen("p.in", "r", stdin);
    freopen("p.out", "w", stdout);

    int test_cases;
    cin >> test_cases;
    validate_input_range(test_cases, 1, 100, "Invalid number of test cases");

    while (test_cases--) {
        reset_global_structures();

        int node_count;
        cin >> node_count;
        validate_input_range(node_count, 1, 1000, "Invalid node count");

        for (int i = 0; i < node_count - 1; ++i) {
            int parent, child;
            cin >> parent >> child;
            validate_input_range(parent, 0, node_count-1, "Invalid parent node");
            validate_input_range(child, 0, node_count-1, "Invalid child node");

            adjacency_list[parent].push_back(child);
            adjacency_list[child].push_back(parent);
            node_degree[parent]++;
            node_degree[child]++;
        }

        memset(visited, false, sizeof(visited));
        recursive_parent_child_identification(0, -1);

        int p_node_count = 0;
        for (int i = 0; i < node_count; ++i) {
            if (is_p_node(i)) {
                p_node_count++;
            }
        }

        cout << p_node_count << endl;
    }

    return 0;
}
