        return t >= 1 && t <= 100;
    }
};

class RoadConditionValidator {
public:
    static bool isValidCondition(int c) {
        return c >= 1 && c <= 50;
    }
};

class TankSimulator {
private:
    int initialTime;
    vector<int> conditions;
    vector<RoadCondition> conditionMapping = {
        {6, 0}, {7, -5}, {12, -20}, {15, 0}
    };

    int getImpactForCondition(int code) {
        auto it = find_if(conditionMapping.begin(), conditionMapping.end(),
            [code](const RoadCondition& rc) { return rc.code == code; });

        if (it != conditionMapping.end()) {
            return it->timeImpact;
        }
        return -2;
    }

public:
    TankSimulator(int time, const vector<int>& conds) : initialTime(time), conditions(conds) {
        if (!TimeValidator::isValidTime(time)) {
            throw invalid_argument("Invalid initial time");
        }
        for (int c : conds) {
            if (!RoadConditionValidator::isValidCondition(c)) {
                throw invalid_argument("Invalid road condition");
            }
        }
    }

    bool simulate() {
        int remainingTime = initialTime;
        bool reachedEnd = false;

        for (size_t i = 0; i < conditions.size() && remainingTime > 0 && !reachedEnd; ++i) {
            int currentCondition = conditions[i];
            int impact = getImpactForCondition(currentCondition);

            remainingTime += impact;

            if (currentCondition == 15) {
                reachedEnd = true;
            }

            if (remainingTime < 0) {
                remainingTime = 0;
            }
        }

        return reachedEnd && remainingTime >= 0;
    }
