    }
};

struct Balloon {
    int height;
    bool taken;
    explicit Balloon(int h) : height(h), taken(false) {}
};

void validate_input_range(int value, int min_val, int max_val, const string& name) {
    if (value < min_val || value > max_val) {
        throw out_of_range(name + " out of valid range");
    }
}

int main() {
    try {
        int n, m;
        cin >> n >> m;

        validate_input_range(n, 1, 1000, "Number of children");
        validate_input_range(m, 1, 1000, "Number of balloons");

        vector<Child> children(n);
        set<int> unique_jumps;
        for (int i = 0; i < n; ++i) {
            int jump;
            cin >> jump;
            validate_input_range(jump, 1, 100000, "Jump height");
            if (unique_jumps.count(jump)) {
                throw runtime_error("Duplicate jump heights detected");
            }
            unique_jumps.insert(jump);
            children[i] = {i, jump, 0};
        }

        vector<Balloon> balloons;
        for (int i = 0; i < m; ++i) {
            int height;
            cin >> height;
            validate_input_range(height, 1, 100000, "Balloon height");
            balloons.emplace_back(height);
        }

        sort(children.begin(), children.end());
        sort(balloons.begin(), balloons.end(), [](const Balloon& a, const Balloon& b) {
            return a.height < b.height;
        });

        int current_balloon_index = 0;
        for (auto& child : children) {
            int count = 0;
            while (current_balloon_index < balloons.size()) {
                if (!balloons[current_balloon_index].taken && 
                    balloons[current_balloon_index].height <= child.jump_height) {
                    count++;
                    balloons[current_balloon_index].taken = true;
                    current_balloon_index++;
                } else if (balloons[current_balloon_index].height > child.jump_height) {
                    break;
                } else {
                    current_balloon_index++;
                }
            }
            child.balloons_taken = count;
        }

        sort(children.begin(), children.end(), [](const Child& a, const Child& b) {
            return a.id < b.id;
        });

        for (const auto& child : children) {
            cout << child.balloons_taken << endl;
        }

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
