#include<iostream>
#include<cstring>
#include<algorithm>
#include<vector>
#include<map>
#include<set>
#include<cassert>
#include<limits>
using namespace std;

const int MAX_CHILDREN = 1005;
const int MAX_BALLOONS = 1005;
const int INF = numeric_limits<int>::max();

struct Child {
    int id;
    int jump_height;
    int balloons_taken;
    bool processed;
    vector<int> balloon_indices;
};

struct Balloon {
    int height;
    bool taken;
    int taken_by;
};

bool compareChildrenByHeight(const Child& a, const Child& b) {
    if (a.jump_height != b.jump_height) {
        return a.jump_height < b.jump_height;
    }
    return a.id < b.id;
}

bool compareChildrenById(const Child& a, const Child& b) {
    return a.id < b.id;
}

bool compareBalloons(const Balloon& a, const Balloon& b) {
    return a.height < b.height;
}

void validateInput(int n, int m) {
    if (n < 1 || n > 1000 || m < 1 || m > 1000) {
        cerr << "Invalid input range" << endl;
        exit(EXIT_FAILURE);
    }
}

void processChild(Child& child, vector<Balloon>& balloons, int& current_balloon_index) {
    if (child.processed) return;

    int start_index = current_balloon_index;
    while (current_balloon_index < balloons.size()) {
        if (balloons[current_balloon_index].taken) {
            current_balloon_index++;
            continue;
        }

        if (balloons[current_balloon_index].height <= child.jump_height) {
            balloons[current_balloon_index].taken = true;
            balloons[current_balloon_index].taken_by = child.id;
            child.balloon_indices.push_back(current_balloon_index);
            current_balloon_index++;
        } else {
            break;
        }
    }

    child.balloons_taken = child.balloon_indices.size();
    child.processed = true;

    if (current_balloon_index >= balloons.size()) {
        current_balloon_index = balloons.size();
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n, m;
    cin >> n >> m;

    validateInput(n, m);

    vector<Child> children(n);
    vector<Balloon> balloons(m);

    for (int i = 0; i < n; ++i) {
        int height;
        cin >> height;
        if (height < 1 || height > 100000) {
            cerr << "Invalid jump height" << endl;
            exit(EXIT_FAILURE);
        }
        children[i] = {i, height, 0, false, {}};
    }

    for (int i = 0; i < m; ++i) {
        int height;
        cin >> height;
        if (height < 1 || height > 100000) {
            cerr << "Invalid balloon height" << endl;
            exit(EXIT_FAILURE);
        }
        balloons[i] = {height, false, -1};
    }

    sort(children.begin(), children.end(), compareChildrenByHeight);
    sort(balloons.begin(), balloons.end(), compareBalloons);

    int current_balloon_index = 0;
    for (int i = 0; i < n; ++i) {
        if (current_balloon_index >= m) break;

        int prev_index = current_balloon_index;
        processChild(children[i], balloons, current_balloon_index);

        if (current_balloon_index == prev_index && current_balloon_index < m) {
            if (balloons[current_balloon_index].height > children[i].jump_height) {
                continue;
            }
        }
    }

    sort(children.begin(), children.end(), compareChildrenById);

