int calculateTimePenalty(int condition, int current_time) {
    static const int MAX_PENALTY = numeric_limits<int>::max();
    switch (condition) {
        case 6:
            return 0;
        case 7:
            if (current_time < 5) {
                return MAX_PENALTY;
            }
            return 5;
        case 12:
            if (current_time < 20) {
                return MAX_PENALTY;
            }
            return 20;
        case 15:
            return 0;
        default:
            if (current_time < 2) {
                return MAX_PENALTY;
            }
            return 2;
    }
}

bool simulateCombat(int n, const vector<int>& conditions) {
    int remaining_time = n;
    bool reached_end = false;

    for (size_t i = 0; i < conditions.size(); ++i) {
        int penalty = calculateTimePenalty(conditions[i], remaining_time);

        if (penalty == numeric_limits<int>::max()) {
            return false;
        }

        remaining_time -= penalty;

        if (conditions[i] == 15) {
            reached_end = true;
            break;
        }

