        ifstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("Cannot open input file");
        }
        return file;
    }

    static ofstream openOutputFile(const string& filename) {
        ofstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("Cannot open output file");
        }
        return file;
    }
};

class BigNumberProcessor {
private:
    vector<int> digits;
    const int ADD_VALUE = 2018;

    void validateAndInitialize(const string& numStr) {
        if (!BigNumberValidator::validate(numStr)) {
            throw invalid_argument("Invalid number format");
        }
        digits.resize(numStr.size() + 10, 0);
        for (int i = 0; i < numStr.size(); i++) {
            digits[numStr.size() - i] = numStr[i] - '0';
        }
    }

    void performAddition() {
        digits[1] += ADD_VALUE;
        int carry = 0;
        for (size_t i = 1; i < digits.size(); i++) {
            digits[i] += carry;
            carry = digits[i] / 10;
            digits[i] %= 10;
            if (i == digits.size() - 1 && carry > 0) {
                digits.push_back(0);
            }
        }
    }

    string buildResultString() {
        string result;
        bool leadingZero = true;
        for (auto it = digits.rbegin(); it != digits.rend(); ++it) {
            if (*it != 0) leadingZero = false;
            if (!leadingZero) {
                result += to_string(*it);
            }
        }
        if (result.empty()) return "0";
        return result;
    }

public:
    string process(const string& numStr) {
        validateAndInitialize(numStr);
        performAddition();
        return buildResultString();
    }
};

