#include<bits/stdc++.h>
using namespace std;

const long long INF = 1000000000000LL;
const int MAX_STONES = 15;

struct StoneValidation {
    bool is_valid;
    int error_code;
    string message;
};

struct StoneAttributes {
    int anger;
    int irritability;
};

class StoneValidator {
public:
    static StoneValidation validateStone(int anger, int irritability) {
        StoneValidation validation;
        validation.is_valid = true;

        if (anger < 0 || irritability < 0) {
            validation.is_valid = false;
            validation.error_code = 1;
            validation.message = "Negative values not allowed";
        }

        if (anger == 0 && irritability == 0) {
            validation.is_valid = false;
            validation.error_code = 2;
            validation.message = "Zero values not meaningful";
        }

        return validation;
    }
};

class StoneProcessor {
private:
    vector<StoneAttributes> stones;
    long long min_diff;
    int n;

    void initializeMinDiff() {
        min_diff = INF;
    }

    void validateInput() {
        if (n < 1 || n > 10) {
            cerr << "Invalid number of stones" << endl;
            exit(EXIT_FAILURE);
        }
    }

    void processDFS(int index, long long current_anger, long long current_irritability, bool at_least_one_selected) {
        if (index == n) {
            if (!at_least_one_selected) return;

            long long diff = abs(current_anger - current_irritability);
            if (diff < min_diff) {
                min_diff = diff;
            }
            return;
        }

        if (index > n) {
            cerr << "Index out of bounds in DFS" << endl;
            return;
        }

        processDFS(index + 1, current_anger * stones[index].anger, current_irritability + stones[index].irritability, true);
        processDFS(index + 1, current_anger, current_irritability, at_least_one_selected);
    }

public:
    StoneProcessor(int num_stones) : n(num_stones) {
        initializeMinDiff();
        stones.resize(n);
    }

    void addStone(int index, int anger, int irritability) {
        StoneValidation validation = StoneValidator::validateStone(anger, irritability);
        if (!validation.is_valid) {
            cerr << "Invalid stone attributes: " << validation.message << endl;
            exit(EXIT_FAILURE);
        }
        stones[index].anger = anger;
        stones[index].irritability = irritability;
    }

    long long calculateMinDifference() {
        validateInput();
        processDFS(0, 1, 0, false);
        return min_diff;
    }
};

int main() {
    ifstream fin("stone.in");
    ofstream fout("stone.out");

    if (!fin.is_open() || !fout.is_open()) {
        cerr << "Failed to open files" << endl;
        return EXIT_FAILURE;
    }

    int n;
    fin >> n;

    StoneProcessor processor(n);

    for (int i = 0; i < n; ++i) {
        int anger, irritability;
        fin >> anger >> irritability;
        processor.addStone(i, anger, irritability);
    }

    long long result = processor.calculateMinDifference();
    fout << result << endl;

    fin.close();
    fout.close();

    return EXIT_SUCCESS;
}
