#include<bits/stdc++.h>
using namespace std;

const long long INFINITE_DIFFERENCE = 1000000000000LL;
const int MAX_STONES = 15;

struct StoneAttributes {
    int anger;
    int irritability;
};

class StoneDifferenceCalculator {
private:
    int totalStones;
    StoneAttributes stones[MAX_STONES];
    long long minimalDifference;
    bool initializationFlag;
    bool calculationComplete;
    vector<bool> selectionTracker;

    void validateInputRange(int value, const string& attributeName) {
        if (value < 0) {
            cerr << "Invalid negative " << attributeName << " value detected" << endl;
            exit(EXIT_FAILURE);
        }
    }

    void recursiveStoneSelector(int currentIndex, long long cumulativeAnger, long long cumulativeIrritability, bool atLeastOneSelected) {
        if (currentIndex > totalStones) {
            if (!atLeastOneSelected) return;
            long long currentDifference = abs(cumulativeAnger - cumulativeIrritability);
            if (currentDifference < minimalDifference) {
                minimalDifference = currentDifference;
            }
            return;
        }

        bool originalSelectionState = selectionTracker[currentIndex];

        selectionTracker[currentIndex] = true;
        recursiveStoneSelector(currentIndex + 1, 
                              cumulativeAnger * stones[currentIndex].anger, 
                              cumulativeIrritability + stones[currentIndex].irritability,
                              true);

        selectionTracker[currentIndex] = false;
        recursiveStoneSelector(currentIndex + 1,
                              cumulativeAnger,
                              cumulativeIrritability,
                              atLeastOneSelected);

        selectionTracker[currentIndex] = originalSelectionState;
    }

public:
    StoneDifferenceCalculator() : totalStones(0), minimalDifference(INFINITE_DIFFERENCE), 
                                initializationFlag(false), calculationComplete(false) {}

    void initializeFromInputFile() {
        ifstream inputFile("stone.in");
        if (!inputFile.is_open()) {
            cerr << "Failed to open input file" << endl;
            exit(EXIT_FAILURE);
        }

        inputFile >> totalStones;
        if (totalStones < 1 || totalStones > 10) {
            cerr << "Invalid number of stones" << endl;
            exit(EXIT_FAILURE);
        }

        for (int i = 1; i <= totalStones; ++i) {
            inputFile >> stones[i].anger >> stones[i].irritability;
            validateInputRange(stones[i].anger, "anger");
            validateInputRange(stones[i].irritability, "irritability");
        }

        selectionTracker.resize(totalStones + 1, false);
        initializationFlag = true;
        inputFile.close();
    }

    void computeMinimalDifference() {
        if (!initializationFlag) {
            cerr << "Calculator not initialized" << endl;
            exit(EXIT_FAILURE);
        }

        recursiveStoneSelector(1, 1, 0, false);
        calculationComplete = true;
    }

    void outputResultToFile() {
        if (!calculationComplete) {
            cerr << "Calculation not performed" << endl;
            exit(EXIT_FAILURE);
        }

        ofstream outputFile("stone.out");
        if (!outputFile.is_open()) {
            cerr << "Failed to open output file" << endl;
            exit(EXIT_FAILURE);
        }

        outputFile << minimalDifference;
        outputFile.close();
    }
};

int main() {
    StoneDifferenceCalculator calculator;
    calculator.initializeFromInputFile();
    calculator.computeMinimalDifference();
    calculator.outputResultToFile();
    return 0;
}
