    vector<char> specialCharacters;
};

void handleSpecialSequences(string& input, DecryptionContext& context) {
    size_t currentPosition = 0;
    while (currentPosition < input.length()) {
        if (input.substr(currentPosition, DOT_REPLACEMENT.length()) == DOT_REPLACEMENT) {
            context.specialPositions.push_back(currentPosition);
            context.specialCharacters.push_back('.');
            currentPosition += DOT_REPLACEMENT.length();
        } else if (input.substr(currentPosition, SPACE_REPLACEMENT.length()) == SPACE_REPLACEMENT) {
