#include<bits/stdc++.h>
using namespace std;

const long long INFINITE_LIMIT = 1000000000000000LL;
const int MAX_STONES = 15;
const int MIN_STONES = 1;
const int MAX_ATTRIBUTE = 1000000000;
const int MIN_ATTRIBUTE = -1000000000;

struct StoneValidationResult {
    bool isValid;
    string errorMessage;
};

struct StoneConfiguration {
    int anger;
    int irritability;
};

class StoneValidator {
public:
    static StoneValidationResult validateStoneCount(int count) {
        if (count < MIN_STONES || count > MAX_STONES) {
            return {false, "Invalid number of stones"};
        }
        return {true, ""};
    }

    static StoneValidationResult validateAttributes(int anger, int irritability) {
        if (anger < MIN_ATTRIBUTE || anger > MAX_ATTRIBUTE) {
            return {false, "Anger value out of bounds"};
        }
        if (irritability < MIN_ATTRIBUTE || irritability > MAX_ATTRIBUTE) {
            return {false, "Irritability value out of bounds"};
        }
        return {true, ""};
    }
};

class StoneProcessor {
private:
    vector<StoneConfiguration> stones;
    long long globalMinimum;

    void processCombination(int index, long long product, long long sum, int selectedCount) {
        if (index == stones.size()) {
            if (selectedCount > 0) {
                long long currentDifference = abs(product - sum);
                if (currentDifference < globalMinimum) {
                    globalMinimum = currentDifference;
                }
            }
            return;
        }

        if (product > INFINITE_LIMIT || sum > INFINITE_LIMIT) {
            return;
        }

        processCombination(
            index + 1,
            product * stones[index].anger,
            sum + stones[index].irritability,
            selectedCount + 1
        );

        processCombination(
            index + 1,
            product,
            sum,
            selectedCount
        );
    }

public:
    StoneProcessor(const vector<StoneConfiguration>& s) : stones(s), globalMinimum(INFINITE_LIMIT) {}

    long long findMinimumDifference() {
        if (stones.empty()) {
            throw runtime_error("No stones provided");
        }

        processCombination(0, 1, 0, 0);

        if (globalMinimum == INFINITE_LIMIT) {
            throw runtime_error("No valid combination found");
        }

        return globalMinimum;
    }
};

int main() {
    ifstream inputFile("stone.in");
    ofstream outputFile("stone.out");

    if (!inputFile.is_open()) {
        cerr << "Failed to open input file" << endl;
        return EXIT_FAILURE;
    }

    if (!outputFile.is_open()) {
        cerr << "Failed to open output file" << endl;
        return EXIT_FAILURE;
    }

    int stoneCount;
    inputFile >> stoneCount;

    auto countValidation = StoneValidator::validateStoneCount(stoneCount);
    if (!countValidation.isValid) {
        cerr << countValidation.errorMessage << endl;
        return EXIT_FAILURE;
    }

    vector<StoneConfiguration> stones(stoneCount);
    for (int i = 0; i < stoneCount; ++i) {
        inputFile >> stones[i].anger >> stones[i].irritability;
        auto attrValidation = StoneValidator::validateAttributes(stones[i].anger, stones[i].irritability);
        if (!attrValidation.isValid) {
            cerr << attrValidation.errorMessage << endl;
            return EXIT_FAILURE;
        }
    }

    try {
        StoneProcessor processor(stones);
        long long result = processor.findMinimumDifference();
        outputFile << result << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    inputFile.close();
    outputFile.close();

    return EXIT_SUCCESS;
}
