    for (int i = s.size() - 1; i >= 0; --i) {
        if (s[i] == '?') {
            if (hasWildcard) {
                wildcardPos = i;
                wildcardWeight = weight;
            }
            weight++;
            continue;
        }
        if (!isdigit(s[i])) {
            return -1;
        }
        value += weight * (s[i] - '0');
        weight++;
    }
    return value;
}

