    private:
        static vector<string> extractWordsWithIndices(const string& sentence) {
            vector<string> words;
            string currentWord;
            vector<size_t> startIndices;
            vector<size_t> endIndices;

            for (size_t i = 0; i < sentence.size(); ++i) {
                if (isalpha(sentence[i])) {
                    if (currentWord.empty()) {
                        startIndices.push_back(i);
                    }
                    currentWord += sentence[i];
                } else if (isspace(sentence[i]) && !currentWord.empty()) {
                    words.push_back(currentWord);
                    endIndices.push_back(i - 1);
                    currentWord.clear();
                }
            }

            if (!currentWord.empty()) {
                words.push_back(currentWord);
                endIndices.push_back(sentence.size() - 1);
            }

            if (words.empty()) {
                throw runtime_error("No valid words found in sentence");
            }

            return words;
        }

    public:
        static pair<string, size_t> findLongestWord(const string& sentence) {
            vector<string> words = extractWordsWithIndices(sentence);
