struct InputValidator {
    static void validate_n(long long n) {
        if (n <= 0 || n > 100000) {
            throw invalid_argument("Invalid value of n");
        }
    }

    static void validate_gender(int val) {
        if (val != 0 && val != 1) {
            throw invalid_argument("Invalid gender value");
        }
    }
};

class DifferenceTracker {
private:
    unordered_map<long long, vector<long long>> diff_map;
    long long offset;
public:
    DifferenceTracker(long long off) : offset(off) {
        if (off < 0 || off > MAX_POSSIBLE_SUM) {
            throw invalid_argument("Invalid offset value");
        }
        diff_map.reserve(MAX_SAFE_INDEX);
    }

    void record_difference(long long diff, long long index) {
        if (index < 0 || index > MAX_SAFE_INDEX) {
            throw out_of_range("Invalid index value");
        }
        diff_map[diff].push_back(index);
    }

    optional<pair<long long, long long>> find_matching_diff(long long current_diff) const {
        auto it = diff_map.find(current_diff);
        if (it != diff_map.end() && !it->second.empty()) {
            return make_pair(it->second.front(), it->second.back());
        }
        return nullopt;
    }
};

