class ShiftCalculator {
private:
    static const int ALPHABET_SIZE = 26;
    static const int DIGIT_SIZE = 10;
public:
    static char calculateShift(char c, int shift) {
        if (!CharacterValidator::isValidCharacter(c)) {
            throw CharacterProcessingException();
        }

        if (isupper(c)) {
            return performAlphabetShift(c, shift, 'A');
        } else if (islower(c)) {
            return performAlphabetShift(c, shift, 'a');
        } else if (isdigit(c)) {
            return performDigitShift(c, shift);
        } else {
            throw CharacterProcessingException();
        }
    }

private:
    static char performAlphabetShift(char c, int shift, char base) {
        int normalizedShift = shift % ALPHABET_SIZE;
        if (normalizedShift < 0) {
            normalizedShift += ALPHABET_SIZE;
        }
        return static_cast<char>((c - base + normalizedShift) % ALPHABET_SIZE + base);
    }

    static char performDigitShift(char c, int shift) {
        int normalizedShift = shift % DIGIT_SIZE;
        if (normalizedShift < 0) {
            normalizedShift += DIGIT_SIZE;
        }
        return static_cast<char>((c - '0' + normalizedShift) % DIGIT_SIZE + '0');
    }
};

