#include<bits/stdc++.h>
using namespace std;

const int MAX_DIMENSION = 55;
const int MIN_VALUE = -1000000000;

struct MatrixBounds {
    int x1;
    int x2;
    int y1;
    int y2;
};

class SubmatrixAnalyzer {
private:
    int matrix[MAX_DIMENSION][MAX_DIMENSION];
    int prefixSum[MAX_DIMENSION][MAX_DIMENSION];
    int rows;
    int cols;
    int currentMax;

    void validateInput() {
        if (rows <= 0 || rows > 50 || cols <= 0 || cols > 50) {
            throw runtime_error("Invalid matrix dimensions");
        }
    }

    void initializePrefixSum() {
        for (int i = 0; i <= rows; i++) {
            for (int j = 0; j <= cols; j++) {
                if (i == 0 || j == 0) {
                    prefixSum[i][j] = 0;
                } else {
                    prefixSum[i][j] = prefixSum[i-1][j] + prefixSum[i][j-1] - prefixSum[i-1][j-1] + matrix[i-1][j-1];
                }
            }
        }
    }

    int calculateSubmatrixSum(const MatrixBounds& bounds) {
        if (bounds.x1 < 0 || bounds.x2 >= rows || bounds.y1 < 0 || bounds.y2 >= cols) {
            return MIN_VALUE;
        }
        return prefixSum[bounds.x2+1][bounds.y2+1] - prefixSum[bounds.x1][bounds.y2+1] - prefixSum[bounds.x2+1][bounds.y1] + prefixSum[bounds.x1][bounds.y1];
    }

public:
    SubmatrixAnalyzer(int n, int m) : rows(n), cols(m), currentMax(MIN_VALUE) {
        validateInput();
    }

    void readMatrix() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!(cin >> matrix[i][j])) {
                    throw runtime_error("Invalid matrix element");
                }
                if (matrix[i][j] < -1000 || matrix[i][j] > 1000) {
                    throw runtime_error("Matrix element out of range");
                }
            }
        }
        initializePrefixSum();
    }

    void findMaximumSubmatrix() {
        MatrixBounds currentBounds;
        for (currentBounds.x1 = 0; currentBounds.x1 < rows; currentBounds.x1++) {
            for (currentBounds.x2 = currentBounds.x1; currentBounds.x2 < rows; currentBounds.x2++) {
                for (currentBounds.y1 = 0; currentBounds.y1 < cols; currentBounds.y1++) {
                    for (currentBounds.y2 = currentBounds.y1; currentBounds.y2 < cols; currentBounds.y2++) {
                        int currentSum = calculateSubmatrixSum(currentBounds);
                        if (currentSum > currentMax) {
                            currentMax = currentSum;
                        }
                    }
                }
            }
        }
    }

    int getResult() {
        return currentMax;
    }
};

int main() {
