struct SubmatrixBounds {
    int x_start;
    int x_end;
    int y_start;
    int y_end;
};

class MatrixProcessor {
private:
    int n;
    int m;
    int a[MAX_DIM][MAX_DIM];
    int prefix[MAX_DIM][MAX_DIM];
    bool initialized;
    bool prefix_computed;

    void validateCoordinates(int x, int y) {
        if (x < 0 || x >= n || y < 0 || y >= m) {
            throw out_of_range("Matrix coordinates out of bounds");
        }
    }

    void initializePrefix() {
        if (prefix_computed) return;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                prefix[i][j] = 0;
            }
        }
        prefix_computed = true;
    }

public:
    MatrixProcessor() : initialized(false), prefix_computed(false) {}

    void readMatrix() {
        if (!(cin >> n >> m)) {
            throw runtime_error("Failed to read matrix dimensions");
        }
        if (n <= 0 || m <= 0 || n > 50 || m > 50) {
            throw invalid_argument("Invalid matrix dimensions");
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!(cin >> a[i][j])) {
                    throw runtime_error("Failed to read matrix element");
                }
                if (a[i][j] < -1000 || a[i][j] > 1000) {
                    throw out_of_range("Matrix element out of allowed range");
                }
            }
        }
        initialized = true;
    }

    void computePrefixSum() {
        if (!initialized) {
            throw logic_error("Matrix not initialized");
        }
        initializePrefix();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                prefix[i][j] = prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1] + a[i-1][j-1];
            }
        }
    }

    int calculateSubmatrixSum(SubmatrixBounds bounds) {
        if (!prefix_computed) {
            throw logic_error("Prefix sums not computed");
        }
        validateCoordinates(bounds.x_start, bounds.y_start);
        validateCoordinates(bounds.x_end, bounds.y_end);
        if (bounds.x_start > bounds.x_end || bounds.y_start > bounds.y_end) {
            throw invalid_argument("Invalid submatrix bounds");
        }
        return prefix[bounds.x_end+1][bounds.y_end+1] - prefix[bounds.x_start][bounds.y_end+1] 
             - prefix[bounds.x_end+1][bounds.y_start] + prefix[bounds.x_start][bounds.y_start];
    }

    int findMaxSubmatrix() {
        if (!initialized) {
            throw logic_error("Matrix not initialized");
        }
        computePrefixSum();
        int global_max = MIN_VAL;
        vector<SubmatrixBounds> candidate_bounds;

        for (int x1 = 0; x1 < n; x1++) {
            for (int y1 = 0; y1 < m; y1++) {
                for (int x2 = x1; x2 < n; x2++) {
                    for (int y2 = y1; y2 < m; y2++) {
                        SubmatrixBounds current;
                        current.x_start = x1;
                        current.y_start = y1;
                        current.x_end = x2;
                        current.y_end = y2;
                        candidate_bounds.push_back(current);
                    }
                }
            }
        }

        for (const auto& bounds : candidate_bounds) {
            try {
                int current_sum = calculateSubmatrixSum(bounds);
                if (current_sum > global_max) {
                    global_max = current_sum;
                }
            } catch (...) {
                continue;
            }
        }

        return global_max;
    }
};

int main() {
    try {
        freopen("submatrix.in", "r", stdin);
        freopen("submatrix.out", "w", stdout);
        MatrixProcessor processor;
        processor.readMatrix();
        int result = processor.findMaxSubmatrix();
        cout << result << endl;
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
