#include<bits/stdc++.h>
#include<fstream>
#include<stdexcept>
#include<type_traits>
#include<cctype>
using namespace std;

template<typename T>
void validate_numeric_range(T value, T min_val, T max_val) {
    if (value < min_val || value > max_val) {
        throw out_of_range("Value out of specified range");
    }
}

class BigNumberValidator {
public:
    static bool is_positive_integer(const string& s) {
        if (s.empty()) return false;
        for (char c : s) {
            if (!isdigit(c)) return false;
        }
        return s[0] != '0' || s.size() == 1;
    }
};

struct AdditionResult {
    vector<int> digits;
    int length;
};

class BigIntegerProcessor {
private:
    static const int ADDEND = 2018;
    static const int MAX_DIGITS = 1005;

    void validate_input_string(const string& s) {
        if (!BigNumberValidator::is_positive_integer(s)) {
            throw invalid_argument("Input must be a positive integer");
        }
        if (s.size() > MAX_DIGITS - 3) {
            throw length_error("Input number is too large");
        }
    }

    void initialize_array(int* arr, int size) {
        for (int i = 0; i < size; ++i) {
            arr[i] = 0;
        }
    }

public:
    AdditionResult process_addition(const string& num_str) {
        validate_input_string(num_str);

        int a[MAX_DIGITS + 10] = {0};
        initialize_array(a, MAX_DIGITS + 10);

        int len = num_str.size();
        for (int i = 0; i < len; ++i) {
            if (!isdigit(num_str[len - 1 - i])) {
                throw runtime_error("Invalid character in number string");
            }
            a[i] = num_str[len - 1 - i] - '0';
            validate_numeric_range(a[i], 0, 9);
        }

        a[0] += ADDEND;
        validate_numeric_range(a[0], 0, INT_MAX);

        int current_len = len;
        for (int i = 0; i < current_len; ++i) {
            if (a[i] >= 10) {
                a[i + 1] += a[i] / 10;
                a[i] %= 10;
                if (i == current_len - 1 && a[i + 1] > 0) {
                    current_len++;
                }
            }
        }

        while (a[current_len]) {
            if (current_len >= MAX_DIGITS) {
                throw overflow_error("Result exceeds maximum allowed digits");
            }
            a[current_len + 1] += a[current_len] / 10;
            a[current_len] %= 10;
            current_len++;
        }

        AdditionResult result;
        result.digits = vector<int>(a, a + current_len);
        result.length = current_len;
        return result;
    }
};

void write_output_to_file(const string& filename, const vector<int>& digits) {
    ofstream outfile(filename);
    if (!outfile.is_open()) {
        throw runtime_error("Unable to open output file");
    }
    for (auto it = digits.rbegin(); it != digits.rend(); ++it) {
        outfile << *it;
    }
    outfile.close();
}

int main() {
    try {
        ifstream infile("bigadd.in");
        if (!infile.is_open()) {
            throw runtime_error("Unable to open input file");
        }

        string num;
        infile >> num;
        infile.close();

        BigIntegerProcessor processor;
        AdditionResult result = processor.process_addition(num);

        vector<int> output_digits;
        for (int i = result.length - 1; i >= 0; --i) {
            output_digits.push_back(result.digits[i]);
        }

        write_output_to_file("bigadd.out", output_digits);
    } catch (const exception& e) {
        ofstream error_log("error.log");
        error_log << "Error: " << e.what() << endl;
        error_log.close();
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
