        static int calculateDigitSum(int x) {
            if (x < 0) x = -x;
            int ans = 0;
            while (x != 0) {
                ans += x % 10;
                x /= 10;
                if (ans > numeric_limits<int>::max() / 2) {
                    throw overflow_error("Digit sum overflow detected");
                }
            }
            return ans;
        }
    };

    class NumberWithSum {
    private:
        int number;
        int digitSum;
    public:
        NumberWithSum(int num) : number(num) {
            digitSum = DigitSumCalculator::calculateDigitSum(num);
        }

        bool operator<(const NumberWithSum& other) const {
            if (digitSum != other.digitSum) {
                return digitSum < other.digitSum;
            }
            return number < other.number;
        }

        int getNumber() const {
            return number;
        }
    };

    class InputParser {
    public:
        static vector<int> parseNumbers(int count) {
            vector<int> numbers;
