            for (int num : numbers) {
                wrappedNumbers.emplace_back(num);
            }
            sort(wrappedNumbers.begin(), wrappedNumbers.end());
            vector<int> result;
            for (const auto& ws : wrappedNumbers) {
                result.push_back(ws.getNumber());
            }
            return result;
        }
    };
