#include <stdexcept>
#include <limits>

using namespace std;

struct NumberWithSum {
    int original;
    int digit_sum;
    string string_representation;
};

int calculate_digit_sum_with_validation(int number) {
    if (number < 0) {
        throw invalid_argument("Negative numbers not allowed");
    }
    if (number >= 10000) {
        throw out_of_range("Number exceeds maximum allowed value");
    }
    int temp_sum = 0;
    int temp_number = number;
    while (temp_number != 0) {
        temp_sum += temp_number % 10;
        temp_number /= 10;
    }
    return temp_sum;
}

bool compare_numbers(const NumberWithSum& num1, const NumberWithSum& num2) {
    if (num1.digit_sum != num2.digit_sum) {
        return num1.digit_sum < num2.digit_sum;
    }
    return num1.original < num2.original;
}

void validate_input_count(int count) {
    if (count <= 0 || count >= 101) {
        throw out_of_range("Invalid input count");
    }
}

vector<string> tokenize_input_string(const string& input) {
    istringstream iss(input);
    vector<string> tokens;
    string token;
    while (iss >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

void convert_and_validate_numbers(const vector<string>& string_numbers, vector<NumberWithSum>& numbers) {
    for (const auto& str_num : string_numbers) {
        try {
            int num = stoi(str_num);
            if (num <= 0) {
                throw invalid_argument("Non-positive numbers not allowed");
            }
            NumberWithSum nws;
            nws.original = num;
            nws.digit_sum = calculate_digit_sum_with_validation(num);
            nws.string_representation = str_num;
            numbers.push_back(nws);
        } catch (const invalid_argument& e) {
            throw invalid_argument("Invalid number format");
        } catch (const out_of_range& e) {
            throw out_of_range("Number out of valid range");
        }
    }
}

int main() {
    try {
        string line;
        int n;

        getline(cin, line);
        n = stoi(line);
        validate_input_count(n);

        vector<NumberWithSum> numbers;
        numbers.reserve(n);

        getline(cin, line);
        vector<string> string_numbers = tokenize_input_string(line);

        if (string_numbers.size() != static_cast<size_t>(n)) {
            throw length_error("Input count mismatch");
        }

        convert_and_validate_numbers(string_numbers, numbers);

        sort(numbers.begin(), numbers.end(), compare_numbers);

        for (size_t i = 0; i < numbers.size(); ++i) {
            if (i != 0) {
                cout << " ";
            }
            cout << numbers[i].string_representation;
        }
        cout << endl;

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
