using namespace std;

namespace DigitSumUtility {
    class InputValidator {
    public:
        static bool validateIntegerInput(const string& input) {
            if (input.empty()) return false;
            for (char c : input) {
                if (!isdigit(c)) return false;
            }
            long long val = stoll(input);
            return val > 0 && val < 101;
        }

        static bool validateNumber(const string& numStr) {
            if (numStr.empty()) return false;
            for (char c : numStr) {
                if (!isdigit(c)) return false;
            }
            int num = stoi(numStr);
            return num > 0 && num < 10000;
        }
    };

    class DigitSumCalculator {
    private:
        static int calculateSingleDigitSum(int n) {
            if (n < 0) n = -n;
            int sum = 0;
            while (n > 0) {
                sum += n % 10;
                n /= 10;
            }
            return sum;
        }

    public:
        static int calculateDigitSum(const string& numStr) {
            if (!InputValidator::validateNumber(numStr)) {
                throw invalid_argument("Invalid number string");
            }
            int num = stoi(numStr);
            return calculateSingleDigitSum(num);
        }
    };
}

class AdvancedIntegerSorter {
private:
    vector<string> numbers;
    int count;

    void validateAndInitializeCount(const string& input) {
        if (!DigitSumUtility::InputValidator::validateIntegerInput(input)) {
            throw invalid_argument("Invalid count value");
        }
        count = stoi(input);
    }

    void validateAndAddNumber(const string& numStr) {
        if (!DigitSumUtility::InputValidator::validateNumber(numStr)) {
            throw invalid_argument("Invalid number in input");
        }
        numbers.push_back(numStr);
    }

    static bool compareNumbers(const string& a, const string& b) {
        int sumA = DigitSumUtility::DigitSumCalculator::calculateDigitSum(a);
        int sumB = DigitSumUtility::DigitSumCalculator::calculateDigitSum(b);

        if (sumA != sumB) {
            return sumA < sumB;
        } else {
            int numA = stoi(a);
            int numB = stoi(b);
            return numA < numB;
        }
    }

public:
    void processInput() {
        string line;
        getline(cin, line);
        validateAndInitializeCount(line);

        getline(cin, line);
        istringstream iss(line);
        string num;
        while (iss >> num) {
            validateAndAddNumber(num);
            if (numbers.size() > static_cast<size_t>(count)) {
                throw runtime_error("Input count mismatch");
            }
        }

        if (numbers.size() != static_cast<size_t>(count)) {
            throw runtime_error("Insufficient input numbers");
        }
    }

    void sortNumbers() {
        sort(numbers.begin(), numbers.end(), compareNumbers);
    }

    void displayResult() {
        for (size_t i = 0; i < numbers.size(); ++i) {
            cout << numbers[i];
            if (i != numbers.size() - 1) {
                cout << " ";
            }
        }
        cout << endl;
    }
};

int main() {
    try {
        AdvancedIntegerSorter sorter;
        sorter.processInput();
        sorter.sortNumbers();
        sorter.displayResult();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
