        if (rear >= MAX_SIZE) {
            throw out_of_range("Queue capacity exceeded");
        }

        bool friendFound = false;
        char firstChar = toupper(name[0]);

        for (int i = front; i < rear; ++i) {
            if (toupper(queue[i][0]) == firstChar) {
                if (rear + 1 >= MAX_SIZE) {
                    throw out_of_range("Queue capacity exceeded during insertion");
                }

                for (int j = rear; j > i + 1; --j) {
                    if (j - 1 < 0 || j >= MAX_SIZE) {
                        throw out_of_range("Invalid index during shifting");
                    }
                    queue[j] = queue[j - 1];
                }

                if (i + 1 < 0 || i + 1 >= MAX_SIZE) {
                    throw out_of_range("Invalid insertion index");
                }

                queue[i + 1] = name;
                friendFound = true;
                break;
            }
        }

        if (!friendFound) {
            if (rear < 0 || rear >= MAX_SIZE) {
                throw out_of_range("Invalid rear index");
            }
            queue[rear] = name;
        }

        rear++;
        capacity++;
