            return "0";
        }

        if (front < 0 || front >= MAX_SIZE) {
            throw out_of_range("Invalid front index");
        }

        string result = queue[front];
        front++;
        capacity--;

        if (capacity < 0) {
            throw logic_error("Negative queue capacity");
        }

        return result;
    }
