#include <iostream>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cctype>
#include <string>
#include <stdexcept>
#include <limits>
using namespace std;

struct QueuePerson {
    string name;
    char first_letter;
    bool has_friend;
    int friend_position;
};

void validateInput(int n) {
    if (n < 1 || n > 100) {
        throw invalid_argument("Invalid number of operations");
    }
}

char extractFirstLetter(const string& name) {
    if (name.empty()) {
        throw runtime_error("Empty name provided");
    }
    return toupper(name[0]);
}

int findFriendPosition(const vector<QueuePerson>& queue, char first_letter) {
    for (size_t i = 0; i < queue.size(); ++i) {
        if (queue[i].first_letter == first_letter) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

void insertPerson(vector<QueuePerson>& queue, const string& name) {
    QueuePerson new_person;
    new_person.name = name;
    new_person.first_letter = extractFirstLetter(name);
    int friend_pos = findFriendPosition(queue, new_person.first_letter);

    if (friend_pos != -1) {
        new_person.has_friend = true;
        new_person.friend_position = friend_pos;
        queue.insert(queue.begin() + friend_pos + 1, new_person);
    } else {
        new_person.has_friend = false;
        new_person.friend_position = -1;
        queue.push_back(new_person);
    }
}

string removePerson(vector<QueuePerson>& queue) {
    if (queue.empty()) {
        return "0";
    }
    string removed_name = queue.front().name;
