void recursive_explorer(int current_index, int product_anger, int sum_irritability, vector<bool>& selected) {
    if (current_index == stones.size()) {
        bool at_least_one_selected = false;
        for (bool sel : selected) {
            if (sel) {
                at_least_one_selected = true;
                break;
            }
        }
        if (!at_least_one_selected) {
            return;
        }
        int current_diff = abs(product_anger - sum_irritability);
        if (current_diff < global_min_diff) {
            global_min_diff = current_diff;
        }
        return;
    }

    string state_key = generate_state_key(selected);
    if (visited_states.find(state_key) != visited_states.end()) {
        return;
    }
    visited_states.insert(state_key);

    selected[current_index] = true;
    recursive_explorer(
