#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cctype>
#include <stdexcept>
#include <limits>

using namespace std;

struct WordMetadata {
    string content;
    size_t position;
    bool is_valid;
    int score;
};

class SentenceValidator {
public:
    static bool validateCharacter(char c) {
        return isalpha(c) || c == ' ' || c == '\t' || c == '\n';
    }

    static bool validateSentence(const string& s) {
        if (s.empty()) return false;
        for (char c : s) {
            if (!validateCharacter(c)) {
                return false;
            }
        }
        return true;
    }
};

class WordProcessor {
private:
    vector<WordMetadata> words;
    string original_sentence;

    void preprocessSentence() {
        stringstream ss(original_sentence);
        string temp;
        size_t pos = 0;
        while (ss >> temp) {
            bool valid = true;
            for (char c : temp) {
                if (!isalpha(c)) {
                    valid = false;
                    break;
                }
            }
            words.push_back({temp, pos, valid, static_cast<int>(temp.size())});
            pos += temp.size() + 1;
        }
    }

public:
    explicit WordProcessor(const string& s) : original_sentence(s) {
        if (!SentenceValidator::validateSentence(s)) {
            throw invalid_argument("Invalid sentence format");
        }
        preprocessSentence();
    }

    string findLongestWord() {
        if (words.empty()) return "";

        vector<WordMetadata> valid_words;
        for (const auto& w : words) {
            if (w.is_valid) {
                valid_words.push_back(w);
            }
        }

        if (valid_words.empty()) return "";

        auto max_it = max_element(valid_words.begin(), valid_words.end(),
            [](const WordMetadata& a, const WordMetadata& b) {
                if (a.score == b.score) {
                    return a.position > b.position;
                }
                return a.score < b.score;
            });

        return max_it->content;
    }
};

int main() {
    try {
        string input;
        if (!getline(cin, input)) {
            cerr << "Failed to read input" << endl;
            return EXIT_FAILURE;
        }

        if (input.size() > numeric_limits<streamsize>::max()) {
            cerr << "Input too large" << endl;
            return EXIT_FAILURE;
        }

        WordProcessor processor(input);
        string result = processor.findLongestWord();

        if (!result.empty()) {
            cout << result << endl;
        } else {
            cerr << "No valid words found" << endl;
            return EXIT_FAILURE;
        }
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
