void handleSpecialPatterns(DecryptionContext& ctx) {
    size_t sss_pos = ctx.intermediate.find(DOT_REPLACEMENT);
    while (sss_pos != string::npos) {
        ctx.intermediate.replace(sss_pos, DOT_REPLACEMENT.length(), ".");
        ctx.specialPositions.push_back(sss_pos);
        ctx.specialTypes.push_back('.');
        sss_pos = ctx.intermediate.find(DOT_REPLACEMENT, sss_pos + 1);
