using namespace std;

struct BigNumber {
    vector<int> digits;
    bool is_valid;
    size_t max_size;
};

void validateInputFile(ifstream& input_file) {
    if (!input_file.is_open()) {
        throw runtime_error("Unable to open input file");
    }
}

void validateOutputFile(ofstream& output_file) {
    if (!output_file.is_open()) {
        throw runtime_error("Unable to open output file");
    }
}

BigNumber initializeBigNumber() {
    BigNumber num;
    num.is_valid = true;
    num.max_size = 1005;
    return num;
}

void processInputString(const string& input_str, BigNumber& num) {
    if (input_str.empty()) {
        num.is_valid = false;
        return;
    }

    for (char c : input_str) {
        if (!isdigit(c)) {
            num.is_valid = false;
            return;
        }
    }

    num.digits.resize(input_str.length());
    transform(input_str.rbegin(), input_str.rend(), num.digits.begin(), 
        [](char c) { return c - '0'; });
}

void addConstantToBigNumber(BigNumber& num, int constant) {
    if (!num.is_valid) return;

    vector<int> const_digits;
    while (constant > 0) {
        const_digits.push_back(constant % 10);
        constant /= 10;
    }

    size_t max_len = max(num.digits.size(), const_digits.size());
    num.digits.resize(max_len + 2, 0);

    for (size_t i = 0; i < const_digits.size(); ++i) {
        num.digits[i] += const_digits[i];
    }

    for (size_t i = 0; i < num.digits.size() - 1; ++i) {
        if (num.digits[i] >= 10) {
            num.digits[i+1] += num.digits[i] / 10;
            num.digits[i] %= 10;
        }
    }

    while (num.digits.size() > 1 && num.digits.back() == 0) {
        num.digits.pop_back();
    }
}

string convertBigNumberToString(const BigNumber& num) {
    if (!num.is_valid) return "INVALID_INPUT";

    string result;
    for (auto it = num.digits.rbegin(); it != num.digits.rend(); ++it) {
        result += to_string(*it);
    }
    return result;
}

int main() {
    try {
        ifstream input_file("bigadd.in");
        validateInputFile(input_file);

        ofstream output_file("bigadd.out");
        validateOutputFile(output_file);

        string input_str;
        input_file >> input_str;

        BigNumber num = initializeBigNumber();
        processInputString(input_str, num);

        const int addition_constant = 2018;
        addConstantToBigNumber(num, addition_constant);

        string result = convertBigNumberToString(num);
        output_file << result;

        input_file.close();
        output_file.close();
    } catch (const exception& e) {
        ofstream error_file("bigadd.out");
        error_file << "ERROR: " << e.what();
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
