        throw runtime_error("Input exceeds maximum length");
    }
    if (!all_of(num.begin(), num.end(), [](char c) { return isdigit(c); })) {
        throw runtime_error("Non-digit characters found in input");
    }
    if (num[0] == '0' && num.size() > 1) {
        throw runtime_error("Leading zeros are not allowed");
    }
}

void initializeResultArray(vector<int>& a, const string& num) {
    for (int i = 0; i < num.size(); ++i) {
        if (i >= a.size()) {
            a.resize(i + 1);
        }
        a[i] = num[num.size() - 1 - i] - '0';
        if (a[i] < 0 || a[i] > 9) {
            throw runtime_error("Invalid digit conversion");
        }
    }
}

void performAdditionWithCarry(vector<int>& a, int addend) {
    if (a.empty()) {
        throw runtime_error("Empty array during addition");
    }
    a[0] += addend;
    for (size_t i = 0; i < a.size(); ++i) {
        if (a[i] < 0) {
            throw runtime_error("Negative value detected during addition");
        }
        if (i + 1 >= a.size() && a[i] >= 10) {
            a.push_back(0);
        }
        if (a[i] >= 10) {
            a[i + 1] += a[i] / 10;
            a[i] %= 10;
        }
    }
}

void handlePotentialOverflow(vector<int>& a, int& len) {
    while (a.size() > len) {
        if (a[len] >= 10) {
            if (len + 1 >= a.size()) {
                a.push_back(0);
            }
            a[len + 1] += a[len] / 10;
            a[len] %= 10;
        }
        len++;
        if (len > 1005) {
            throw runtime_error("Potential buffer overflow detected");
        }
    }
}

string convertResultToString(const vector<int>& a, int len) {
    stringstream ss;
    for (int i = len - 1; i >= 0; --i) {
        if (i < 0 || i >= a.size()) {
            throw runtime_error("Invalid index during result conversion");
        }
        ss << a[i];
    }
    string result = ss.str();
    if (result.empty()) {
        throw runtime_error("Empty result string generated");
    }
    return result;
}

int main() {
