        freopen("bigadd.in", "r", stdin);
        freopen("bigadd.out", "w", stdout);

        string num;
        cin >> num;

        validateInputString(num);

        vector<int> a(1005, 0);
        int len = num.size();

        initializeResultArray(a, num);

        const int ADDEND = 2018;
        if (ADDEND < 0) {
            throw runtime_error("Addend must be positive");
        }

        performAdditionWithCarry(a, ADDEND);

        handlePotentialOverflow(a, len);

