using namespace std;

struct WordTracker {
    string content;
    size_t length;
    size_t position;
};

class SentenceAnalyzer {
private:
    string rawInput;
    vector<string> tokenizedWords;
    vector<WordTracker> wordMetrics;
    bool inputValid;

    void validateInput() {
        inputValid = !rawInput.empty();
        if (!inputValid) {
            cerr << "Input validation failed: Empty string detected" << endl;
        }
    }

    void tokenizeSentence() {
        istringstream iss(rawInput);
        copy(istream_iterator<string>(iss),
             istream_iterator<string>(),
             back_inserter(tokenizedWords));
    }

    void calculateWordMetrics() {
        for (size_t i = 0; i < tokenizedWords.size(); ++i) {
            WordTracker metric;
            metric.content = tokenizedWords[i];
            metric.length = tokenizedWords[i].size();
            metric.position = i;
            wordMetrics.push_back(metric);
        }
    }

public:
    explicit SentenceAnalyzer(const string& input) : rawInput(input), inputValid(false) {
        validateInput();
        if (inputValid) {
            tokenizeSentence();
            calculateWordMetrics();
        }
    }

    string findLongestWord() {
        if (!inputValid || wordMetrics.empty()) {
            return "";
        }

        auto maxElement = wordMetrics.begin();
        bool firstIteration = true;

        for (auto it = wordMetrics.begin(); it != wordMetrics.end(); ++it) {
            if (firstIteration) {
                maxElement = it;
                firstIteration = false;
                continue;
            }

            if (it->length > maxElement->length) {
                maxElement = it;
            }
        }

        return maxElement->content;
    }
};

int main() {
    string inputLine;
    getline(cin, inputLine);

    unique_ptr<SentenceAnalyzer> analyzer = make_unique<SentenceAnalyzer>(inputLine);
    string result = analyzer->findLongestWord();

    if (!result.empty()) {
        cout << result << endl;
    } else {
        cerr << "No valid words found in input" << endl;
    }

    return 0;
}
