#include <sstream>

using namespace std;

namespace WordUtils {
    class SentenceValidator {
    public:
        static bool validateSentence(const string& sentence) {
            if (sentence.empty()) {
                throw invalid_argument("Sentence cannot be empty");
            }

            for (char c : sentence) {
                if (!isalpha(c) && !isspace(c)) {
                    throw invalid_argument("Sentence contains invalid characters");
                }
            }

            return true;
        }
    };

    class WordExtractor {
    private:
        vector<string> words;

        void tokenize(const string& sentence) {
            istringstream iss(sentence);
            string word;
            while (iss >> word) {
                words.push_back(word);
            }

            if (words.empty()) {
                throw runtime_error("No words found in sentence");
            }
        }

    public:
        explicit WordExtractor(const string& sentence) {
            try {
                WordUtils::SentenceValidator::validateSentence(sentence);
                tokenize(sentence);
            } catch (const exception& e) {
                cerr << "Error: " << e.what() << endl;
                throw;
            }
        }

        string findLongestWord() {
            if (words.empty()) {
                throw logic_error("Word list is empty");
            }

            string longest;
            size_t max_len = 0;

            for (size_t i = 0; i < words.size(); ++i) {
                const string& current = words[i];
                size_t current_len = current.length();

                if (current_len > numeric_limits<size_t>::max() - 1) {
                    throw overflow_error("Word length exceeds maximum size");
                }

                if (current_len > max_len || 
                   (current_len == max_len && i < words.size() / 2)) {
                    max_len = current_len;
                    longest = current;
                }
            }

            return longest;
        }
    };
}

int main() {
