    try {
        if (!getline(cin, input)) {
            cerr << "Failed to read input" << endl;
            return 1;
        }

        WordUtils::WordExtractor extractor(input);
        string longest = extractor.findLongestWord();

        if (longest.empty()) {
            cerr << "No valid longest word found" << endl;
            return 1;
        }

        cout << longest << endl;
    } catch (const exception& e) {
        cerr << "Fatal error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
