using namespace std;

int performOperationSafely(int operand1, int operand2, char operationSymbol) {
    if (operationSymbol == '+') {
        return operand1 + operand2;
    } else if (operationSymbol == '-') {
        return operand2 - operand1;
    } else if (operationSymbol == '*') {
        return operand1 * operand2;
    } else if (operationSymbol == '/') {
        if (operand1 == 0) {
            throw runtime_error("Division by zero detected");
        }
        return operand2 / operand1;
    } else {
        throw runtime_error("Unrecognized operation symbol encountered");
    }
}

bool isHigherPrecedence(char op1, char op2) {
    if (op2 == '(' || op2 == ')') {
        return false;
    }
    if ((op1 == '*' || op1 == '/') && (op2 == '+' || op2 == '-')) {
        return true;
    }
    return false;
}

void processStackOperations(stack<char>& operationStack, stack<int>& numberStack, char currentOp) {
    while (!operationStack.empty() && operationStack.top() != '(' && 
          (isHigherPrecedence(operationStack.top(), currentOp) || 
           operationStack.top() == currentOp)) {
        if (numberStack.size() < 2) {
            throw runtime_error("Insufficient operands for operation");
        }
        int val1 = numberStack.top();
        numberStack.pop();
        int val2 = numberStack.top();
        numberStack.pop();
        char op = operationStack.top();
        operationStack.pop();
        numberStack.push(performOperationSafely(val1, val2, op));
    }
}

void handleClosingParenthesis(stack<char>& operationStack, stack<int>& numberStack) {
    while (!operationStack.empty() && operationStack.top() != '(') {
        if (numberStack.size() < 2) {
            throw runtime_error("Mismatched parentheses detected");
        }
        int val1 = numberStack.top();
        numberStack.pop();
        int val2 = numberStack.top();
        numberStack.pop();
        char op = operationStack.top();
        operationStack.pop();
        numberStack.push(performOperationSafely(val1, val2, op));
    }
    if (operationStack.empty()) {
        throw runtime_error("Mismatched parentheses detected");
    }
    operationStack.pop();
}

void validateExpression(const string& expr) {
    int parenthesisBalance = 0;
    for (char c : expr) {
