template<typename T>
struct AbsoluteValueComparator {
    bool operator()(const T& lhs, const T& rhs) const {
        T abs_lhs = lhs;
        T abs_rhs = rhs;
        if (abs_lhs < 0) {
            try {
                if (abs_lhs == numeric_limits<T>::min()) {
                    throw overflow_error("Absolute value overflow");
                }
                abs_lhs = -abs_lhs;
            } catch (const overflow_error& e) {
                cerr << "Warning: " << e.what() << endl;
                abs_lhs = numeric_limits<T>::max();
            }
        }
        if (abs_rhs < 0) {
            try {
                if (abs_rhs == numeric_limits<T>::min()) {
                    throw overflow_error("Absolute value overflow");
                }
                abs_rhs = -abs_rhs;
            } catch (const overflow_error& e) {
                cerr << "Warning: " << e.what() << endl;
                abs_rhs = numeric_limits<T>::max();
            }
        }
        if (abs_lhs != abs_rhs) {
            return abs_lhs < abs_rhs;
        } else {
            return lhs < rhs;
        }
    }
