        bool y_valid = (y >= 0) && (y < width);
        return x_valid && y_valid;
    }

    void initializeVisited() {
        for (int i = 0; i < MAX_DIMENSION; ++i) {
            for (int j = 0; j < MAX_DIMENSION; ++j) {
                visited[i][j] = false;
            }
        }
    }

    void exploreGrassland(int x, int y) {
        Coordinate directions[MAX_DIRECTIONS] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        queue<Coordinate> exploration_queue;

        Coordinate start = {x, y};
        exploration_queue.push(start);
        visited[x][y] = true;

        while (!exploration_queue.empty()) {
            Coordinate current = exploration_queue.front();
            exploration_queue.pop();

            for (int i = 0; i < MAX_DIRECTIONS; ++i) {
                Coordinate next = {
                    current.x + directions[i].x,
                    current.y + directions[i].y
                };

                if (validateCoordinates(next.x, next.y)) {
                    if (terrain[next.x][next.y] == '#' && !visited[next.x][next.y]) {
                        visited[next.x][next.y] = true;
                        exploration_queue.push(next);
                    }
                }
            }
        }
    }

public:
    CanyonMap() : width(0), height(0), grassland_count(0) {
        initializeVisited();
    }

    void readInput(const string& filename) {
        ifstream input_file(filename.c_str());
        if (!input_file.is_open()) {
            cerr << "Error opening input file: " << strerror(errno) << endl;
            exit(EXIT_FAILURE);
        }

        input_file >> height >> width;
        if (height <= 0 || width <= 0 || height > MAX_DIMENSION || width > MAX_DIMENSION) {
            cerr << "Invalid map dimensions" << endl;
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < height; ++i) {
            string row;
            input_file >> row;
            if (row.length() != static_cast<size_t>(width)) {
                cerr << "Invalid row length at row " << i << endl;
                exit(EXIT_FAILURE);
            }
            for (int j = 0; j < width; ++j) {
                terrain[i][j] = row[j];
            }
        }
    }

    void countGrasslands() {
        initializeVisited();
        grassland_count = 0;

        for (int i = 0; i < height; ++i) {
            for (int j = 0; j < width; ++j) {
                if (terrain[i][j] == '#' && !visited[i][j]) {
                    exploreGrassland(i, j);
                    ++grassland_count;
                }
            }
        }
    }

    int getGrasslandCount() const {
        return grassland_count;
    }
};

