    int degree[MAX_N];
    int parent[MAX_N];
    bool initialized = false;
};

TreeData trees[MAX_T];

void initializeTree(int treeIdx, int n) {
    if (trees[treeIdx].initialized) return;
    for (int i = 0; i <= n; i++) {
        trees[treeIdx].children[i].clear();
        trees[treeIdx].degree[i] = 0;
        trees[treeIdx].parent[i] = -1;
    }
    trees[treeIdx].initialized = true;
}

int findParent(int treeIdx, int node) {
    if (node < 0 || node >= MAX_N) return -1;
    return trees[treeIdx].parent[node];
}

vector<int> getChildren(int treeIdx, int node) {
    if (node < 0 || node >= MAX_N) return vector<int>();
    return trees[treeIdx].children[node];
}

int calculateDegree(int treeIdx, int node) {
    if (node < 0 || node >= MAX_N) return 0;
    int deg = trees[treeIdx].children[node].size();
    if (trees[treeIdx].parent[node] != -1) deg++;
    trees[treeIdx].degree[node] = deg;
    return deg;
}

int getMaxChildDegree(int treeIdx, int node) {
    if (node < 0 || node >= MAX_N) return NEG_INF;
    int max_deg = NEG_INF;
    for (int child : trees[treeIdx].children[node]) {
        int child_deg = calculateDegree(treeIdx, child);
        if (child_deg > max_deg) {
            max_deg = child_deg;
        }
    }
    return max_deg;
}

